def actor(request):
    if hasattr(request.user, "iam_account"):
        return request.user.iam_account
    from iam.models import UserAccount
    return UserAccount.objects.first()


def audit(request, obj, action, before=None, after=None, reason=""):
    comp = getattr(obj, "company", None) or (obj if isinstance(obj, Company) else None)
    record_audit(
        company=comp, actor_user=actor(request), module_code="FA", action_code=action,
        entity=obj, before=before or {}, after=after or {}, request=request, reason=reason,
    )


def _closed(company, date):
    if models.AssetPeriod.objects.filter(company=company, start_date__lte=date, end_date__gte=date, status="CLOSED").exists():
        return True
    from general_ledger.models import AccountingPeriod
    return AccountingPeriod.objects.filter(company=company, start_date__lte=date, end_date__gte=date, status="CLOSED").exists()


def _snapshot(asset):
    return {
        "category": str(asset.category_id), "original_cost": str(asset.original_cost),
        "accumulated_depreciation": str(asset.accumulated_depreciation), "allocated_value": str(asset.allocated_value),
        "periods_processed": asset.periods_processed, "branch": str(asset.branch_id),
        "department": str(asset.department_id) if asset.department_id else None,
        "custodian": str(asset.custodian_id) if asset.custodian_id else None,
        "status": asset.status, "disposed_at": str(asset.disposed_at) if asset.disposed_at else None,
        "quantity": str(asset.quantity), "salvage_value": str(asset.salvage_value),
        "useful_life_periods": asset.useful_life_periods,
    }


def _split(asset, quantity, obj):
    """Move `quantity` units (and their share of every value) of an asset into a new record."""
    if quantity <= 0 or quantity > asset.quantity:
        raise ValidationError("Số lượng điều chuyển/ghi giảm phải lớn hơn 0 và không vượt số lượng đang theo dõi.")
    if quantity == asset.quantity:
        return asset
    ratio = quantity / asset.quantity
    share = lambda value: (value * ratio).quantize(Decimal("0.0001"))
    suffix = 1
    while models.AssetRecord.objects.filter(company=asset.company, code=f"{asset.code}.{suffix}").exists():
        suffix += 1
    part = models.AssetRecord.objects.create(
        company=asset.company, code=f"{asset.code}.{suffix}", name=asset.name, asset_type=asset.asset_type,
        category=asset.category, description=asset.description, quantity=quantity,
        acquisition_date=asset.acquisition_date, in_service_date=asset.in_service_date,
        original_cost=share(asset.original_cost), salvage_value=share(asset.salvage_value),
        accumulated_depreciation=share(asset.accumulated_depreciation), allocated_value=share(asset.allocated_value),
        method=asset.method, useful_life_periods=asset.useful_life_periods, periods_processed=asset.periods_processed,
        branch=asset.branch, department=asset.department, custodian=asset.custodian, source_module="FA",
        source_reference=obj.number, status=asset.status, created_by=obj.created_by,
    )
    asset.quantity -= quantity
    asset.original_cost -= part.original_cost
    asset.salvage_value -= part.salvage_value
    asset.accumulated_depreciation -= part.accumulated_depreciation
    asset.allocated_value -= part.allocated_value
    asset.save()
    obj.split_asset = part
    return part


@transaction.atomic
def submit(obj, request):
    obj = models.AssetTransaction.objects.select_for_update().get(pk=obj.pk)
    if obj.status not in {"DRAFT", "REJECTED"}:
        raise ValidationError("Trạng thái không cho phép gửi duyệt.")
    if _closed(obj.company, obj.transaction_date):
        raise ValidationError("Không được gửi giao dịch vào kỳ đã đóng.")
    raw = request.data.get("workflow_snapshot") or {}
    try:
        levels = max(1, min(int(raw.get("levels", 1)), 20))
    except (TypeError, ValueError):
        raise ValidationError("Số cấp phê duyệt không hợp lệ.")
    obj.workflow_snapshot = {"version": str(raw.get("version", "DEFAULT"))[:80], "levels": levels, "allow_self_approval": bool(raw.get("allow_self_approval", True))}
    configured = configured_snapshot(obj, f"FA.{obj.transaction_type}")
    if configured is not None:
        obj.workflow_snapshot = configured
    old = obj.status
    obj.status = "PENDING_APPROVAL" if configured is None or configured["approval_required"] else "APPROVED"
    obj.submitted_at = timezone.now()
    obj.approved_at = timezone.now() if obj.status == "APPROVED" else None
    obj.save(update_fields=("workflow_snapshot", "status", "submitted_at", "approved_at", "updated_at"))
    models.ApprovalDecision.objects.create(company=obj.company, transaction=obj, decision="SUBMITTED", actor=actor(request))
    audit(request, obj, "SUBMIT", {"status": old}, {"status": obj.status})
    return obj


@transaction.atomic
def decide(obj, request, approved):
    obj = models.AssetTransaction.objects.select_for_update().get(pk=obj.pk)
    comment = request.data.get("comment", "").strip()
    if obj.status != "PENDING_APPROVAL":
        raise ValidationError("Giao dịch không chờ duyệt.")
    if _closed(obj.company, obj.transaction_date):
        raise ValidationError("Không được duyệt giao dịch trong kỳ đã đóng.")
    if not approved and not comment:
        raise ValidationError({"comment": "Ý kiến từ chối là bắt buộc."})
    if obj.created_by_id == actor(request).id and not obj.workflow_snapshot.get("allow_self_approval", False) and not getattr(request.user, "is_superuser", False):
        raise ValidationError("Người tạo không được tự phê duyệt.")
    level = obj.approval_decisions.filter(decision="APPROVED").count() + 1
    final = approved and level >= int(obj.workflow_snapshot.get("levels", 1))
    progress = approval_progress(obj, actor(request), approved, obj.approval_decisions.all())
    if progress is not None:
        level, final = progress["level"], progress["final"]
    old = obj.status
    obj.status = "APPROVED" if final else "PENDING_APPROVAL" if approved or progress and progress["return_to_previous"] else "REJECTED"
    obj.approved_at = timezone.now() if final else None
    obj.save(update_fields=("status", "approved_at", "updated_at"))
    models.ApprovalDecision.objects.create(company=obj.company, transaction=obj, level=level, decision="APPROVED" if approved else "REJECTED", actor=actor(request), comment=comment)
    audit(request, obj, "APPROVE" if approved else "REJECT", {"status": old}, {"status": obj.status}, comment)
    return obj


@transaction.atomic
def post_transaction(obj, request):
    obj = models.AssetTransaction.objects.select_for_update().get(pk=obj.pk)
    asset = models.AssetRecord.objects.select_for_update().get(pk=obj.asset_id)
    if obj.status != "APPROVED" or obj.asset_applied:
        raise ValidationError("Giao dịch chưa duyệt hoặc đã cập nhật tài sản.")
    if _closed(obj.company, obj.transaction_date):
        raise ValidationError("Không được ghi nhận giao dịch vào kỳ đã đóng.")
    before = _snapshot(asset)
    kind = obj.transaction_type
    # A partial transfer/disposal acts on the split-off part; the rest stays on the original record.
    target = _split(asset, obj.quantity, obj) if kind in ("TRANSFER", "DISPOSAL") and obj.quantity is not None else asset
    if kind == "ACQUISITION":
        if asset.status != "DRAFT" or asset.transactions.filter(transaction_type="ACQUISITION", status="POSTED").exists():
            raise ValidationError("Tài sản đã được ghi tăng.")
        if obj.amount != asset.original_cost:
            raise ValidationError("Giá trị ghi tăng phải bằng nguyên giá trên hồ sơ.")
        asset.status = "ACTIVE"
    elif kind == "DEPRECIATION":
        if asset.asset_type != "FIXED_ASSET" or asset.status != "ACTIVE":
            raise ValidationError("Tài sản không đủ điều kiện khấu hao.")
        limit = asset.original_cost - asset.salvage_value - asset.accumulated_depreciation
        if obj.amount > limit:
            raise ValidationError("Khấu hao vượt giá trị còn được phép khấu hao.")
        asset.accumulated_depreciation += obj.amount
        asset.periods_processed += 1
    elif kind == "ALLOCATION":
        if asset.asset_type != "TOOL" or asset.status != "ACTIVE":
            raise ValidationError("CCDC không đủ điều kiện phân bổ.")
        if obj.amount > asset.original_cost - asset.allocated_value:
            raise ValidationError("Phân bổ vượt giá trị CCDC còn lại.")
        asset.allocated_value += obj.amount
        asset.periods_processed += 1
    elif kind == "TRANSFER":
        targets = (obj.target_branch, obj.target_department, obj.target_custodian)
        if not any(targets):
            raise ValidationError("Thiếu đơn vị/người nhận điều chuyển.")
        for value in targets:
            if value and value.company_id != asset.company_id:
                raise ValidationError("Đơn vị/người nhận phải thuộc cùng doanh nghiệp.")
        if obj.target_branch_id:
            target.branch = obj.target_branch
        if obj.target_department_id:
            target.department = obj.target_department
        if obj.target_custodian_id:
            target.custodian = obj.target_custodian
        obj.gl_status = "NOT_REQUIRED"
    elif kind == "RECLASSIFICATION":
        if not obj.target_category_id or obj.target_category_id == asset.category_id or obj.target_category.asset_type != asset.asset_type:
            raise ValidationError("Nhóm đích không hợp lệ.")
        asset.category = obj.target_category
        obj.gl_status = "NOT_REQUIRED"
    elif kind == "VALUE_INCREASE":
        asset.original_cost += obj.amount
    elif kind == "VALUE_DECREASE":
        if asset.original_cost - obj.amount < asset.processed_value + asset.salvage_value:
            raise ValidationError("Giảm nguyên giá làm giá trị còn lại không hợp lệ.")
        asset.original_cost -= obj.amount
    elif kind == "DISPOSAL":
        if target.status == "DISPOSED":
            raise ValidationError("Tài sản đã được ghi giảm.")
        if target is not asset:
            obj.amount = target.remaining_value
        elif obj.amount != asset.remaining_value:
            raise ValidationError("Giá trị ghi giảm phải bằng giá trị còn lại tại thời điểm xử lý.")
        target.status = "DISPOSED"
        target.disposed_at = obj.transaction_date
    elif kind == "LIFE_CHANGE":
        periods = obj.target_useful_life_periods
        if not periods or periods <= asset.periods_processed:
            raise ValidationError("Số kỳ mới phải lớn hơn số kỳ đã khấu hao/phân bổ.")
        asset.useful_life_periods = periods
        obj.gl_status = "NOT_REQUIRED"
    else:
        raise ValidationError("Loại giao dịch không được ghi nhận trực tiếp.")
    asset.save()
    if target is not asset:
        target.save()
    obj.before_snapshot = before
    obj.after_snapshot = _snapshot(asset)
    obj.asset_applied = True
    obj.status = "POSTED"
    obj.posted_at = timezone.now()
    obj.save(update_fields=("before_snapshot", "after_snapshot", "asset_applied", "status", "posted_at", "gl_status",
                            "split_asset", "amount", "updated_at"))
    audit(request, obj, "POST", before, obj.after_snapshot)
    return obj


@transaction.atomic
def reverse(obj, request):
    obj = models.AssetTransaction.objects.select_for_update().get(pk=obj.pk)
    reason = request.data.get("reason", "").strip()
    if obj.status != "POSTED" or obj.gl_status == "POSTED" or not reason:
        raise ValidationError("Giao dịch không thể đảo; cần lý do và xử lý GL trước.")
    if obj.reversals.filter(status__in=("APPROVED", "POSTED")).exists():
        raise ValidationError("Giao dịch đã có giao dịch đảo.")
    asset = models.AssetRecord.objects.select_for_update().get(pk=obj.asset_id)
    snapshot = obj.before_snapshot
    asset.category_id = snapshot["category"]
    asset.original_cost = Decimal(snapshot["original_cost"])
    asset.accumulated_depreciation = Decimal(snapshot["accumulated_depreciation"])
    asset.allocated_value = Decimal(snapshot["allocated_value"])
    asset.periods_processed = snapshot["periods_processed"]
    asset.branch_id = snapshot["branch"]
    asset.department_id = snapshot["department"]
    asset.custodian_id = snapshot["custodian"]
    asset.status = snapshot["status"]
    asset.disposed_at = snapshot["disposed_at"] or None
    for field in ("quantity", "salvage_value"):
        if field in snapshot:
            setattr(asset, field, Decimal(snapshot[field]))
    if "useful_life_periods" in snapshot:
        asset.useful_life_periods = snapshot["useful_life_periods"]
    if obj.split_asset_id:
        # The split-off part merges back; refuse if it has a history of its own since.
        part = models.AssetRecord.objects.select_for_update().get(pk=obj.split_asset_id)
        if part.transactions.exists():
            raise ValidationError("Phần tài sản đã tách có phát sinh giao dịch khác; hãy đảo các giao dịch đó trước.")
        obj.split_asset = None
        obj.save(update_fields=("split_asset",))
        part.delete()
    asset.save()
    reversal = models.AssetTransaction.objects.create(
        company=obj.company, asset=asset, number=f"REV-{obj.number}", transaction_type="REVERSAL",
        transaction_date=timezone.localdate(), amount=obj.amount, reason=reason, original_transaction=obj,
        before_snapshot=obj.after_snapshot, after_snapshot=obj.before_snapshot, status="POSTED", asset_applied=True,
        gl_status="NOT_REQUIRED", created_by=actor(request), approved_at=timezone.now(), posted_at=timezone.now(),
    )
    obj.status = "REVERSED"
    obj.save(update_fields=("status", "updated_at"))
    audit(request, reversal, "REVERSE", reversal.before_snapshot, reversal.after_snapshot, reason)
    return reversal


@transaction.atomic
def calculate(run, request):
    run = models.CalculationRun.objects.select_for_update().get(pk=run.pk)
    if run.status != "DRAFT" or _closed(run.company, run.period_end):
        raise ValidationError("Kỳ tính đã xử lý hoặc đã đóng.")
    asset_type = "FIXED_ASSET" if run.calculation_type == "DEPRECIATION" else "TOOL"
    operation = run.calculation_type
    assets = models.AssetRecord.objects.select_for_update().filter(
        company=run.company, asset_type=asset_type, status="ACTIVE",
        is_depreciable=True, method="STRAIGHT_LINE", in_service_date__lte=run.period_end,
    )
    total = Decimal("0")
    for asset in assets:
        if models.AssetTransaction.objects.filter(asset=asset, transaction_type=operation, period_code=run.period_code, status__in=("DRAFT", "PENDING_APPROVAL", "APPROVED", "POSTED")).exists():
            continue
        opening = asset.remaining_value
        if asset_type == "FIXED_ASSET":
            depreciable = asset.depreciable_amount if asset.depreciable_amount > 0 else (asset.original_cost - asset.salvage_value)
        else:
            depreciable = asset.original_cost
        processed = asset.accumulated_depreciation if asset_type == "FIXED_ASSET" else asset.allocated_value
        remaining = depreciable - processed
        if remaining <= 0:
            continue
        # Spread what is left over the periods left, so life changes and value changes are absorbed going forward.
        periods_left = max(asset.useful_life_periods - asset.periods_processed, 1)
        amount = min(remaining, (remaining / periods_left).quantize(Decimal("0.0001")))
        models.CalculationLine.objects.create(run=run, asset=asset, opening_value=opening, amount=amount, closing_value=opening - amount)
        total += amount
    if not run.lines.exists():
        raise ValidationError("Không có tài sản đủ điều kiện tính trong kỳ.")
    run.status = "CALCULATED"
    run.total_amount = total
    run.save(update_fields=("status", "total_amount"))
    audit(request, run, "CALCULATE", after={"total_amount": str(total), "lines": run.lines.count()})
    return run


@transaction.atomic
def post_run(run, request):
    run = models.CalculationRun.objects.select_for_update().prefetch_related("lines__asset").get(pk=run.pk)
    if run.status != "CALCULATED" or _closed(run.company, run.period_end):
        raise ValidationError("Bảng tính chưa sẵn sàng hoặc kỳ đã đóng.")
    for index, line in enumerate(run.lines.all(), 1):
        obj = models.AssetTransaction.objects.create(
            company=run.company, asset=line.asset, number=f"{run.number}-{index:04d}",
            transaction_type=run.calculation_type, transaction_date=run.period_end, amount=line.amount,
            period_code=run.period_code, source_module="FA_RUN", source_reference=str(run.id),
            idempotency_key=f"FA-RUN:{run.id}:{line.asset_id}", status="APPROVED", created_by=actor(request), approved_at=timezone.now(),
        )
        post_transaction(obj, request)
        line.transaction = obj
        line.save(update_fields=("transaction",))
    run.status = "POSTED"
    run.save(update_fields=("status",))
    audit(request, run, "POST_RUN", after={"status": run.status})
    return run


@transaction.atomic
def post_gl(obj, request):
    obj = models.AssetTransaction.objects.select_for_update().get(pk=obj.pk)
    reference = request.data.get("gl_reference", "").strip()
    debit = Decimal(str(request.data.get("total_debit", "0")))
    credit = Decimal(str(request.data.get("total_credit", "0")))
    if obj.status != "POSTED" or obj.gl_status in {"POSTED", "NOT_REQUIRED"} or not reference:
        raise ValidationError("Giao dịch không ở trạng thái có thể chuyển GL.")
    category = obj.asset.category
    asset = obj.asset
    has_accounts = (
        (asset.asset_account_id or category.asset_account_id)
        and (not asset.is_depreciable or asset.accumulated_account_id or category.accumulated_account_id)
        and (not asset.is_depreciable or bool(asset.allocations) or category.expense_account_id)
    )
    if not has_accounts:
        raise ValidationError("Nhóm tài sản chưa cấu hình đủ tài khoản hạch toán.")
    if debit != credit or debit != obj.amount:
        raise ValidationError("Bút toán phải cân bằng và bằng giá trị giao dịch tài sản.")
    obj.gl_status = "POSTED"
    obj.gl_reference = reference
    obj.save(update_fields=("gl_status", "gl_reference", "updated_at"))
    if obj.transaction_type == "ACQUISITION":
        asset.accounting_reconciliation_status = models.AccountingReconciliationStatus.RECONCILED
        asset.save(update_fields=("accounting_reconciliation_status", "updated_at"))
    audit(request, obj, "POST_GL", after={"gl_reference": reference})
    return obj


def _parse_date(value):
    if isinstance(value, date_cls) and not isinstance(value, datetime):
        return value
    text = str(value or "").strip()
    if not text:
        return None
    for fmt in ("%d/%m/%Y", "%Y-%m-%d"):
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            continue
    return None


def _parse_decimal(value, default=None):
    if value is None or value == "":
        return default
    if isinstance(value, Decimal):
        return value
    text = str(value).strip()
    if not text:
        return default
    # Handle Vietnamese thousand/decimal formatting if passed as string
    if "," in text and "." in text:
        text = text.replace(".", "").replace(",", ".")
    elif "," in text and text.count(",") == 1 and len(text.split(",")[1]) <= 4:
        text = text.replace(",", ".")
    try:
        return Decimal(text)
    except InvalidOperation:
        return None


def _resolve_account(company, identifier):
    if not identifier:
        return None
    from general_ledger.models import Account
    ident = str(identifier).strip()
    if not ident:
        return None
    account = Account.objects.filter(company=company, code=ident).first()
    if not account:
        try:
            uuid.UUID(ident)
            account = Account.objects.filter(company=company, pk=ident).first()
        except (ValueError, TypeError, ValidationError):
            account = None
    return account


def _resolve_department(company, identifier):
    if not identifier:
        return None
    from organization.models import Department
    ident = str(identifier).strip()
    if not ident:
        return None
    dept = Department.objects.filter(company=company, code__iexact=ident).first()
    if not dept:
        dept = Department.objects.filter(company=company, name__iexact=ident).first()
    if not dept:
        try:
            dept = Department.objects.filter(company=company, pk=ident).first()
        except (ValueError, ValidationError):
            dept = None
    return dept


def _resolve_category(company, identifier):
    if not identifier:
        return None
    ident = str(identifier).strip()
    if not ident:
        return None
    cat = models.AssetCategory.objects.filter(company=company, code__iexact=ident).first()
    if not cat:
        cat = models.AssetCategory.objects.filter(company=company, name__iexact=ident).first()
    if not cat:
        try:
            cat = models.AssetCategory.objects.filter(company=company, pk=ident).first()
        except (ValueError, ValidationError):
            cat = None
    return cat


def _determine_reconciliation_status(company, original_cost, asset_account, origins, gl_reference=""):
    """
    UC-FA-01 (EF25, BR12, BR29, Section 5.2):
    Compare asset original_cost against GL JournalEntry / source purchase documents without posting a duplicate GL entry.
    Returns (reconciliation_status, gl_status, matched_gl_ref).
    """
    from general_ledger.models import JournalEntry, JournalLine

    doc_numbers = [str(item.get("document_number") or "").strip() for item in (origins or []) if str(item.get("document_number") or "").strip()]
    if gl_reference:
        doc_numbers.append(str(gl_reference).strip())

    if not doc_numbers:
        return models.AccountingReconciliationStatus.UNRECONCILED, models.GlStatus.PENDING, ""

    entries = JournalEntry.objects.filter(company=company, status="POSTED", number__in=doc_numbers)
    if not entries.exists():
        # Also check source_event_id or description containing document number
        matched_ids = []
        for doc_no in doc_numbers:
            for entry in JournalEntry.objects.filter(company=company, status="POSTED", description__icontains=doc_no)[:5]:
                matched_ids.append(entry.id)
        if matched_ids:
            entries = JournalEntry.objects.filter(id__in=matched_ids)

    if not entries.exists():
        # Check GoodsPurchase in purchases module if linked
        try:
            from purchases.models import GoodsPurchase
            purchases = GoodsPurchase.objects.filter(company=company, number__in=doc_numbers).exclude(status="CANCELLED")
            if purchases.exists():
                pur_total = sum((p.total_amount - getattr(p, "total_tax_amount", Decimal("0")) for p in purchases), Decimal("0"))
                first_ref = purchases.first().number
                if pur_total == original_cost or sum((p.total_amount for p in purchases), Decimal("0")) == original_cost:
                    return models.AccountingReconciliationStatus.RECONCILED, models.GlStatus.POSTED, first_ref
                return models.AccountingReconciliationStatus.DISCREPANCY, models.GlStatus.PENDING, first_ref
        except Exception:
            pass
        return models.AccountingReconciliationStatus.UNRECONCILED, models.GlStatus.PENDING, ""

    # Sum debit lines on asset_account (or 211/213 accounts)
    lines_qs = JournalLine.objects.filter(entry__in=entries, debit__gt=0)
    if asset_account:
        acc_lines = lines_qs.filter(account=asset_account)
        if not acc_lines.exists():
            acc_lines = lines_qs.filter(account__code__startswith=asset_account.code[:3])
    else:
        acc_lines = lines_qs.filter(account__code__startswith="21")

    first_number = entries.first().number
    if acc_lines.exists():
        gl_debit_sum = acc_lines.aggregate(total=Sum("debit"))["total"] or Decimal("0")
        if gl_debit_sum == original_cost:
            return models.AccountingReconciliationStatus.RECONCILED, models.GlStatus.POSTED, first_number
        return models.AccountingReconciliationStatus.DISCREPANCY, models.GlStatus.PENDING, first_number

    total_entry_debit = entries.aggregate(total=Sum("total_debit"))["total"] or Decimal("0")
    if total_entry_debit == original_cost:
        return models.AccountingReconciliationStatus.RECONCILED, models.GlStatus.POSTED, first_number
    return models.AccountingReconciliationStatus.DISCREPANCY, models.GlStatus.PENDING, first_number


def acquire_fixed_asset(request, data):
    """
    UC-FA-01 — Ghi tăng tài sản cố định.
    Validates EF01–EF25 & BR01–BR30, creates AssetRecord (ACTIVE) and AssetTransaction (ACQUISITION, POSTED),
    verifies source documents & GL reconciliation status without creating duplicate GL entries, and records AuditLog.
    """
    from iam.permissions import has_effective_permission
    from organization.models import Branch, Company

    company_id = request.query_params.get("company_id") or data.get("company")
    try:
        company = Company.objects.get(pk=company_id) if company_id else None
    except (Company.DoesNotExist, ValueError, ValidationError):
        company = None

    # EF01 & BR01: Permission check
    if not request.user or not request.user.is_authenticated or not company:
        raise PermissionDenied("Bạn không có quyền ghi tăng tài sản cố định.")
    if not getattr(request.user, "is_superuser", False):
        iam_acc = getattr(request.user, "iam_account", None)
        if not iam_acc or not has_effective_permission(iam_acc, company, "FA.ASSET.CREATE"):
            raise PermissionDenied("Bạn không có quyền ghi tăng tài sản cố định.")

    # EF02 & EF03 & BR04: Số CT ghi tăng
    voucher_no = str(data.get("voucher_no") or data.get("acquisition_voucher_no") or data.get("number") or "").strip()
    if not voucher_no:
        raise ValidationError({"voucher_no": "Vui lòng nhập số chứng từ ghi tăng."})
    if (
        models.AssetTransaction.objects.filter(company=company, number=voucher_no).exists()
        or models.AssetRecord.objects.filter(company=company, acquisition_voucher_no=voucher_no).exists()
    ):
        raise ValidationError({"voucher_no": "Số chứng từ ghi tăng đã tồn tại."})

    # EF04 & EF05 & BR05: Ngày ghi tăng & Kỳ kế toán
    raw_acq_date = data.get("acquisition_date") if "acquisition_date" in data else data.get("voucher_date")
    acquisition_date = _parse_date(raw_acq_date)
    if not acquisition_date:
        raise ValidationError({"acquisition_date": "Vui lòng nhập Ngày ghi tăng hợp lệ theo định dạng DD/MM/YYYY."})
    if _closed(company, acquisition_date):
        raise ValidationError({"acquisition_date": "Không thể ghi tăng tài sản trong kỳ kế toán đã khóa."})

    # EF06 & BR06 & BR09: Loại tài sản
    category = _resolve_category(company, data.get("category") or data.get("category_code") or data.get("category_name"))
    if not category or not category.is_active or category.company_id != company.id or category.asset_type != models.AssetType.FIXED_ASSET:
        raise ValidationError({"category": "Vui lòng chọn loại tài sản hợp lệ."})

    # EF07 & EF08 & BR03 & BR09: Mã tài sản
    code = str(data.get("code") or "").strip()
    if not code:
        raise ValidationError({"code": "Vui lòng nhập mã tài sản."})
    if models.AssetRecord.objects.filter(company=company, code=code).exists():
        raise ValidationError({"code": "Mã tài sản đã tồn tại. Vui lòng nhập mã khác."})

    # EF09 & BR09 & BR10: Đơn vị sử dụng
    department = _resolve_department(company, data.get("department") or data.get("department_code") or data.get("department_name"))
    if not department or department.company_id != company.id or getattr(department, "status", "ACTIVE") not in ("ACTIVE", True) or getattr(department, "is_active", True) is False:
        raise ValidationError({"department": "Vui lòng chọn đơn vị sử dụng hợp lệ."})

    branch = None
    if data.get("branch"):
        try:
            branch = Branch.objects.filter(company=company, pk=data.get("branch")).first()
        except (ValueError, ValidationError):
            branch = None
    if not branch:
        branch = getattr(department, "branch", None) or Branch.objects.filter(company=company).first()
    if not branch or branch.company_id != company.id:
        raise ValidationError({"department": "Vui lòng chọn đơn vị sử dụng hợp lệ."})

    # EF10 & BR09: Tên tài sản
    name = str(data.get("name") or "").strip()
    if not name:
        raise ValidationError({"name": "Vui lòng nhập tên tài sản cố định."})

    # EF11 & EF12 & BR02 & BR07 & BR08: Nguyên giá & Điều kiện ghi nhận TSCĐ
    original_cost = _parse_decimal(data.get("original_cost"), default=None)
    if original_cost is None or original_cost <= 0:
        raise ValidationError({"original_cost": "Nguyên giá tài sản phải lớn hơn 0 và có căn cứ hợp lệ."})

    meets_criteria = data.get("meets_recognition_criteria", True)
    min_threshold = _parse_decimal(data.get("min_recognition_threshold"), default=Decimal("0"))
    if meets_criteria is False or (min_threshold and min_threshold > 0 and original_cost < min_threshold):
        raise ValidationError({"original_cost": "Tài sản chưa đủ điều kiện ghi nhận là tài sản cố định."})

    # EF13 & BR11: TK nguyên giá
    raw_asset_acc = data.get("asset_account") if "asset_account" in data else data.get("cost_account")
    asset_account = _resolve_account(company, raw_asset_acc)
    if not asset_account or asset_account.company_id != company.id or asset_account.status != "ACTIVE" or not asset_account.is_postable:
        raise ValidationError({"asset_account": "Tài khoản nguyên giá không hợp lệ."})
    if not any(asset_account.code.startswith(prefix) for prefix in ("211", "212", "213")):
        raise ValidationError({"asset_account": "Tài khoản nguyên giá không hợp lệ."})
    # Check compatibility between category and asset_account (intangible vs tangible)
    is_intangible_cat = "vô hình" in category.name.lower() or "vo hinh" in category.name.lower() or (category.asset_account and category.asset_account.code.startswith("213"))
    if is_intangible_cat and not asset_account.code.startswith("213"):
        raise ValidationError({"asset_account": "Tài khoản nguyên giá không hợp lệ."})
    if not is_intangible_cat and category.asset_account and category.asset_account.code.startswith("211") and asset_account.code.startswith("213"):
        raise ValidationError({"asset_account": "Tài khoản nguyên giá không hợp lệ."})

    # AF03 & BR19: Không tính khấu hao / Đối tượng trích khấu hao
    if "no_depreciation" in data:
        is_depreciable = not bool(data.get("no_depreciation"))
    else:
        is_depreciable = bool(data.get("is_depreciable", True))

    # EF17 & BR16 & BR17: Hao mòn lũy kế & Giá trị còn lại
    accumulated_depreciation = _parse_decimal(data.get("accumulated_depreciation", "0"), default=None)
    source_module = str(data.get("source_module") or "FA").upper()
    allow_prior_depr = bool(data.get("allow_prior_depreciation", False)) or source_module == "OPENING"
    if (
        accumulated_depreciation is None
        or accumulated_depreciation < 0
        or accumulated_depreciation > original_cost
        or (not allow_prior_depr and accumulated_depreciation > 0)
    ):
        raise ValidationError({"accumulated_depreciation": "Hao mòn lũy kế không hợp lệ."})

    salvage_value = _parse_decimal(data.get("salvage_value", "0"), default=Decimal("0"))
    if salvage_value is None or salvage_value < 0 or salvage_value > original_cost:
        raise ValidationError({"salvage_value": "Thông tin khấu hao không nhất quán. Vui lòng kiểm tra lại."})

    method = str(data.get("method") or category.default_method or models.DepreciationMethod.STRAIGHT_LINE).strip().upper()
    if method not in dict(models.DepreciationMethod.choices):
        raise ValidationError({"method": "Thông tin khấu hao không nhất quán. Vui lòng kiểm tra lại."})

    if is_depreciable:
        # EF14 & BR11 & BR13: TK khấu hao
        raw_acc_acc = data.get("accumulated_account") if "accumulated_account" in data else data.get("depr_account")
        accumulated_account = _resolve_account(company, raw_acc_acc)
        if (
            not accumulated_account
            or accumulated_account.company_id != company.id
            or accumulated_account.status != "ACTIVE"
            or not accumulated_account.is_postable
            or not accumulated_account.code.startswith("214")
        ):
            raise ValidationError({"accumulated_account": "Vui lòng chọn tài khoản khấu hao hợp lệ."})
        if asset_account.code.startswith("213") and accumulated_account.code.startswith(("2141", "2142")):
            raise ValidationError({"accumulated_account": "Vui lòng chọn tài khoản khấu hao hợp lệ."})
        if asset_account.code.startswith("211") and accumulated_account.code.startswith("2143"):
            raise ValidationError({"accumulated_account": "Vui lòng chọn tài khoản khấu hao hợp lệ."})

        # EF15 & AF06 & BR13 & BR15: Thời gian sử dụng & Đơn vị thời gian (Năm / Tháng)
        raw_life = data.get("useful_life_value") if "useful_life_value" in data else data.get("useful_life_periods")
        useful_life_value = _parse_decimal(raw_life, default=None)
        raw_unit = str(data.get("useful_life_unit") or ("MONTH" if "useful_life_periods" in data and "useful_life_value" not in data else "YEAR")).strip().upper()
        if raw_unit in ("YEAR", "YEARS", "NĂM", "NAM"):
            useful_life_unit = models.UsefulLifeUnit.YEAR
        elif raw_unit in ("MONTH", "MONTHS", "THÁNG", "THANG"):
            useful_life_unit = models.UsefulLifeUnit.MONTH
        else:
            raise ValidationError({"useful_life_unit": "Thời gian sử dụng tài sản không hợp lệ."})

        if useful_life_value is None or useful_life_value <= 0:
            raise ValidationError({"useful_life_value": "Thời gian sử dụng tài sản không hợp lệ."})

        total_months_dec = useful_life_value * Decimal("12") if useful_life_unit == models.UsefulLifeUnit.YEAR else useful_life_value
        if total_months_dec <= 0 or total_months_dec != int(total_months_dec) or total_months_dec > 1200:
            raise ValidationError({"useful_life_value": "Thời gian sử dụng tài sản không hợp lệ."})
        useful_life_periods = int(total_months_dec)

        # EF16 & BR13 & BR14: Ngày BĐ tính KH
        raw_start_date = data.get("in_service_date") if "in_service_date" in data else data.get("depreciation_start_date")
        in_service_date = _parse_date(raw_start_date)
        if not in_service_date or (source_module != "OPENING" and in_service_date < acquisition_date):
            raise ValidationError({"in_service_date": "Ngày bắt đầu tính khấu hao không hợp lệ."})

        # EF18 & BR20 & Section 4.4: Giá trị tính KH, tỷ lệ KH, mức KH
        default_depreciable = original_cost - salvage_value
        depreciable_amount = _parse_decimal(
            data.get("depreciable_amount") if "depreciable_amount" in data else default_depreciable,
            default=None,
        )
        if depreciable_amount is None or depreciable_amount <= 0 or depreciable_amount > original_cost:
            raise ValidationError({"depreciable_amount": "Thông tin khấu hao không nhất quán. Vui lòng kiểm tra lại."})

        if method == models.DepreciationMethod.STRAIGHT_LINE:
            expected_monthly_amount = (depreciable_amount / Decimal(useful_life_periods)).quantize(Decimal("0.0001"))
            expected_annual_amount = (expected_monthly_amount * Decimal("12")).quantize(Decimal("0.0001"))
            expected_monthly_rate = (Decimal("100") / Decimal(useful_life_periods)).quantize(Decimal("0.0001"))
            expected_annual_rate = (expected_monthly_rate * Decimal("12")).quantize(Decimal("0.0001"))

            if "monthly_depreciation_amount" in data and data.get("monthly_depreciation_amount") not in (None, ""):
                given_m_amt = _parse_decimal(data.get("monthly_depreciation_amount"))
                tol_m = max(Decimal("5"), (depreciable_amount * Decimal("0.001")))
                if given_m_amt is None or given_m_amt <= 0 or abs(given_m_amt - expected_monthly_amount) > tol_m:
                    raise ValidationError({"monthly_depreciation_amount": "Thông tin khấu hao không nhất quán. Vui lòng kiểm tra lại."})
                monthly_depreciation_amount = given_m_amt
            else:
                monthly_depreciation_amount = expected_monthly_amount

            if "annual_depreciation_amount" in data and data.get("annual_depreciation_amount") not in (None, ""):
                given_y_amt = _parse_decimal(data.get("annual_depreciation_amount"))
                tol_y = max(Decimal("25"), (depreciable_amount * Decimal("0.002")))
                if given_y_amt is None or given_y_amt <= 0 or abs(given_y_amt - expected_annual_amount) > tol_y:
                    raise ValidationError({"annual_depreciation_amount": "Thông tin khấu hao không nhất quán. Vui lòng kiểm tra lại."})
                annual_depreciation_amount = given_y_amt
            else:
                annual_depreciation_amount = expected_annual_amount

            if "monthly_depreciation_rate" in data and data.get("monthly_depreciation_rate") not in (None, ""):
                given_m_rate = _parse_decimal(data.get("monthly_depreciation_rate"))
                if given_m_rate is None or given_m_rate <= 0 or abs(given_m_rate - expected_monthly_rate) > Decimal("0.1"):
                    raise ValidationError({"monthly_depreciation_rate": "Thông tin khấu hao không nhất quán. Vui lòng kiểm tra lại."})
                monthly_depreciation_rate = given_m_rate
            else:
                monthly_depreciation_rate = expected_monthly_rate

            if "annual_depreciation_rate" in data and data.get("annual_depreciation_rate") not in (None, ""):
                given_y_rate = _parse_decimal(data.get("annual_depreciation_rate"))
                if given_y_rate is None or given_y_rate <= 0 or abs(given_y_rate - expected_annual_rate) > Decimal("0.2"):
                    raise ValidationError({"annual_depreciation_rate": "Thông tin khấu hao không nhất quán. Vui lòng kiểm tra lại."})
                annual_depreciation_rate = given_y_rate
            else:
                annual_depreciation_rate = expected_annual_rate
        else:
            # AF07: Non-straight-line method
            monthly_depreciation_amount = _parse_decimal(data.get("monthly_depreciation_amount"), default=Decimal("0"))
            annual_depreciation_amount = _parse_decimal(data.get("annual_depreciation_amount"), default=Decimal("0"))
            monthly_depreciation_rate = _parse_decimal(data.get("monthly_depreciation_rate"), default=Decimal("0"))
            annual_depreciation_rate = _parse_decimal(data.get("annual_depreciation_rate"), default=Decimal("0"))
            if monthly_depreciation_amount is None or monthly_depreciation_amount <= 0 or monthly_depreciation_amount > depreciable_amount:
                raise ValidationError({"monthly_depreciation_amount": "Thông tin khấu hao không nhất quán. Vui lòng kiểm tra lại."})

        # AF08 & BR21: CIT tax cap
        cit_cap_enabled = bool(data.get("cit_cap_enabled", False))
        if cit_cap_enabled:
            cit_depreciable_cap = _parse_decimal(data.get("cit_depreciable_cap"), default=None)
            if cit_depreciable_cap is None or cit_depreciable_cap <= 0:
                raise ValidationError({"cit_depreciable_cap": "Thông tin khấu hao không nhất quán. Vui lòng kiểm tra lại."})
            cit_monthly_cap = _parse_decimal(
                data.get("cit_monthly_cap"),
                default=(cit_depreciable_cap / Decimal(useful_life_periods)).quantize(Decimal("0.0001")),
            )
            if cit_monthly_cap is None or cit_monthly_cap <= 0:
                raise ValidationError({"cit_monthly_cap": "Thông tin khấu hao không nhất quán. Vui lòng kiểm tra lại."})
        else:
            cit_depreciable_cap = Decimal("0")
            cit_monthly_cap = Decimal("0")
    else:
        accumulated_account = None
        useful_life_value = Decimal("0")
        useful_life_unit = models.UsefulLifeUnit.YEAR
        useful_life_periods = 0
        in_service_date = _parse_date(data.get("in_service_date") or data.get("depreciation_start_date")) or acquisition_date
        depreciable_amount = Decimal("0")
        monthly_depreciation_rate = Decimal("0")
        annual_depreciation_rate = Decimal("0")
        monthly_depreciation_amount = Decimal("0")
        annual_depreciation_amount = Decimal("0")
        cit_cap_enabled = False
        cit_depreciable_cap = Decimal("0")
        cit_monthly_cap = Decimal("0")

    # EF19 & EF20 & AF09 & AF10 & BR22 & BR23: Thiết lập phân bổ
    raw_allocations = data.get("allocations")
    normalized_allocations = []
    if is_depreciable:
        if raw_allocations is None and category.expense_account_id:
            # AF09: Single allocation derived from category configuration and asset's using department
            raw_allocations = [{
                "department_id": str(department.id),
                "department_name": department.name,
                "rate": "100",
                "expense_account": str(category.expense_account_id),
                "expense_item": "",
                "cost_center": "",
            }]
        if not isinstance(raw_allocations, list) or len(raw_allocations) == 0:
            raise ValidationError({"allocations": "Tổng tỷ lệ phân bổ khấu hao phải bằng 100%."})

        total_rate = Decimal("0")
        valid_expense_prefixes = ("621", "622", "623", "627", "641", "642", "154", "241", "811")
        for line in raw_allocations:
            if not isinstance(line, dict):
                raise ValidationError({"allocations": "Thông tin phân bổ chi phí khấu hao không hợp lệ."})
            line_dept = _resolve_department(
                company,
                line.get("department_id") or line.get("department") or line.get("department_code") or line.get("department_name"),
            )
            if not line_dept or line_dept.company_id != company.id or getattr(line_dept, "status", "ACTIVE") not in ("ACTIVE", True):
                raise ValidationError({"allocations": "Thông tin phân bổ chi phí khấu hao không hợp lệ."})

            line_acc = _resolve_account(
                company,
                line.get("expense_account_id") or line.get("expense_account") or line.get("expense_account_code"),
            )
            if (
                not line_acc
                or line_acc.company_id != company.id
                or line_acc.status != "ACTIVE"
                or not line_acc.is_postable
                or not any(line_acc.code.startswith(p) for p in valid_expense_prefixes)
            ):
                raise ValidationError({"allocations": "Thông tin phân bổ chi phí khấu hao không hợp lệ."})

            rate = _parse_decimal(line.get("rate") if "rate" in line else line.get("percentage"), default=None)
            if rate is None or rate <= 0 or rate > Decimal("100"):
                raise ValidationError({"allocations": "Thông tin phân bổ chi phí khấu hao không hợp lệ."})
            total_rate += rate

            normalized_allocations.append({
                "department_id": str(line_dept.id),
                "department_code": line_dept.code,
                "department_name": line_dept.name,
                "rate": str(rate.quantize(Decimal("0.01"))),
                "expense_account_id": str(line_acc.id),
                "expense_account_code": line_acc.code,
                "expense_account_name": line_acc.name,
                "expense_item": str(line.get("expense_item") or "").strip(),
                "cost_center": str(line.get("cost_center") or "").strip(),
            })

        if abs(total_rate - Decimal("100")) > Decimal("0.01"):
            raise ValidationError({"allocations": "Tổng tỷ lệ phân bổ khấu hao phải bằng 100%."})

    # EF21 & EF22 & AF05 & AF11 & BR07 & BR08 & BR24 & BR25: Nguồn gốc hình thành
    raw_origins = data.get("origins") or []
    normalized_origins = []
    if not isinstance(raw_origins, list):
        raise ValidationError({"origins": "Nguyên giá chưa phù hợp với hồ sơ nguồn. Vui lòng kiểm tra lại."})

    origins_total = Decimal("0")
    existing_assets = list(models.AssetRecord.objects.filter(company=company).exclude(status="DISPOSED").only("id", "source_reference", "origins"))
    for item in raw_origins:
        if not isinstance(item, dict):
            raise ValidationError({"origins": "Nguyên giá chưa phù hợp với hồ sơ nguồn. Vui lòng kiểm tra lại."})
        doc_no = str(item.get("document_number") or item.get("voucher_no") or "").strip()
        src_id = str(item.get("source_document_id") or "").strip()
        allow_multiple = bool(item.get("allow_multiple_assets", False))

        # EF21: Check duplicate source document already used for another asset
        if not allow_multiple and (doc_no or src_id):
            for ex in existing_assets:
                if doc_no and ex.source_reference == doc_no:
                    raise ValidationError({"origins": "Tài sản đã được ghi tăng từ hồ sơ này. Vui lòng kiểm tra lại."})
                for ex_origin in (ex.origins or []):
                    if not isinstance(ex_origin, dict):
                        continue
                    if src_id and str(ex_origin.get("source_document_id") or "") == src_id:
                        raise ValidationError({"origins": "Tài sản đã được ghi tăng từ hồ sơ này. Vui lòng kiểm tra lại."})
                    if doc_no and str(ex_origin.get("document_number") or "") == doc_no and not ex_origin.get("allow_multiple_assets"):
                        raise ValidationError({"origins": "Tài sản đã được ghi tăng từ hồ sơ này. Vui lòng kiểm tra lại."})

        amt = _parse_decimal(item.get("capitalized_amount") if "capitalized_amount" in item else item.get("amount"), default=None)
        if amt is None or amt <= 0:
            raise ValidationError({"origins": "Nguyên giá chưa phù hợp với hồ sơ nguồn. Vui lòng kiểm tra lại."})
        origins_total += amt
        doc_date = _parse_date(item.get("document_date"))
        normalized_origins.append({
            "origin_type": str(item.get("origin_type") or "Mua sắm mới").strip(),
            "document_number": doc_no,
            "document_date": str(doc_date) if doc_date else str(item.get("document_date") or "").strip(),
            "amount": str(amt.quantize(Decimal("0.0001"))),
            "partner_code": str(item.get("partner_code") or "").strip(),
            "partner_name": str(item.get("partner_name") or "").strip(),
            "source_document_id": src_id,
            "allow_multiple_assets": allow_multiple,
        })

    if normalized_origins:
        variance_reason = str(data.get("origin_variance_reason") or "").strip()
        if origins_total != original_cost and not variance_reason:
            raise ValidationError({"origins": "Nguyên giá chưa phù hợp với hồ sơ nguồn. Vui lòng kiểm tra lại."})

    # AF12 & AF13 & BR26: Bộ phận cấu thành & Dụng cụ, phụ tùng kèm theo (không tự cộng trùng vào nguyên giá)
    def _clean_parts(items_list):
        cleaned = []
        for part in (items_list or []):
            if not isinstance(part, dict):
                continue
            p_name = str(part.get("name") or "").strip()
            if not p_name:
                continue
            p_qty = _parse_decimal(part.get("quantity", "1"), default=Decimal("1")) or Decimal("1")
            p_val = _parse_decimal(part.get("value", "0"), default=Decimal("0")) or Decimal("0")
            cleaned.append({
                "name": p_name,
                "unit": str(part.get("unit") or "").strip(),
                "quantity": str(p_qty),
                "value": str(p_val),
            })
        return cleaned

    normalized_components = _clean_parts(data.get("components"))
    normalized_accessories = _clean_parts(data.get("accessories"))

    # AF14: Thông tin khác (Nước sản xuất, Năm sản xuất)
    country_of_origin = str(data.get("country_of_origin") or "").strip()
    manufacture_year = None
    if data.get("manufacture_year") not in (None, ""):
        try:
            manufacture_year = int(data.get("manufacture_year"))
        except (TypeError, ValueError):
            manufacture_year = None

    # EF25 & BR12 & BR29 & Section 5.2: Đối chiếu Sổ cái (không tự tạo bút toán nguyên giá trùng)
    reconciliation_status, gl_status, matched_gl_ref = _determine_reconciliation_status(
        company=company,
        original_cost=original_cost,
        asset_account=asset_account,
        origins=normalized_origins,
        gl_reference=str(data.get("gl_reference") or "").strip(),
    )

    first_origin_doc = normalized_origins[0]["document_number"] if normalized_origins else ""
    source_ref = str(data.get("source_reference") or first_origin_doc or "").strip()
    period_code = f"{acquisition_date.year:04d}-{acquisition_date.month:02d}"
    user_actor = actor(request)

    try:
        with transaction.atomic():
            asset = models.AssetRecord.objects.create(
                company=company,
                code=code,
                name=name,
                asset_type=models.AssetType.FIXED_ASSET,
                category=category,
                description=str(data.get("description") or "").strip(),
                serial_number=str(data.get("serial_number") or "").strip(),
                quantity=_parse_decimal(data.get("quantity", "1"), default=Decimal("1")) or Decimal("1"),
                acquisition_date=acquisition_date,
                in_service_date=in_service_date,
                original_cost=original_cost,
                salvage_value=salvage_value,
                accumulated_depreciation=accumulated_depreciation,
                allocated_value=Decimal("0"),
                method=method,
                useful_life_periods=useful_life_periods,
                periods_processed=0,
                branch=branch,
                department=department,
                acquisition_voucher_no=voucher_no,
                is_depreciable=is_depreciable,
                asset_account=asset_account,
                accumulated_account=accumulated_account,
                depreciable_amount=depreciable_amount,
                useful_life_value=useful_life_value,
                useful_life_unit=useful_life_unit,
                monthly_depreciation_rate=monthly_depreciation_rate,
                annual_depreciation_rate=annual_depreciation_rate,
                monthly_depreciation_amount=monthly_depreciation_amount,
                annual_depreciation_amount=annual_depreciation_amount,
                cit_cap_enabled=cit_cap_enabled,
                cit_depreciable_cap=cit_depreciable_cap,
                cit_monthly_cap=cit_monthly_cap,
                allocations=normalized_allocations,
                origins=normalized_origins,
                components=normalized_components,
                accessories=normalized_accessories,
                country_of_origin=country_of_origin,
                manufacture_year=manufacture_year,
                accounting_reconciliation_status=reconciliation_status,
                source_module=source_module,
                source_reference=source_ref,
                status=models.AssetStatus.ACTIVE,
                created_by=user_actor,
            )

            now = timezone.now()
            after_snap = _snapshot(asset)
            acq_tx = models.AssetTransaction.objects.create(
                company=company,
                asset=asset,
                number=voucher_no,
                transaction_type=models.TransactionType.ACQUISITION,
                transaction_date=acquisition_date,
                amount=original_cost,
                period_code=period_code,
                reason=str(data.get("reason") or f"Ghi tăng tài sản cố định {code} - {name}").strip(),
                source_module=source_module,
                source_reference=source_ref,
                idempotency_key=f"FA-ACQ:{company.id}:{voucher_no}",
                target_branch=branch,
                target_department=department,
                before_snapshot={},
                after_snapshot=after_snap,
                status=models.TransactionStatus.POSTED,
                asset_applied=True,
                gl_status=gl_status,
                gl_reference=matched_gl_ref,
                created_by=user_actor,
                submitted_at=now,
                approved_at=now,
                posted_at=now,
            )

            audit(
                request,
                asset,
                "ACQUIRE",
                before={},
                after={
                    **after_snap,
                    "voucher_no": voucher_no,
                    "is_depreciable": is_depreciable,
                    "accounting_reconciliation_status": reconciliation_status,
                    "allocations": normalized_allocations,
                    "origins": normalized_origins,
                },
                reason=acq_tx.reason,
            )
            audit(request, acq_tx, "POST", before={}, after=after_snap, reason=acq_tx.reason)
            return asset, acq_tx
    except IntegrityError as exc:
        raise ValidationError({"detail": "Dữ liệu tài sản đã thay đổi. Vui lòng kiểm tra và thực hiện lại."}) from exc
    except DatabaseError as exc:
        raise ValidationError({"detail": "Ghi tăng tài sản cố định thất bại. Vui lòng thử lại."}) from exc


@transaction.atomic
def reconcile_asset_accounting(asset, request):
    asset = models.AssetRecord.objects.select_for_update().get(pk=asset.pk)
    gl_ref_input = str(request.data.get("gl_reference") or "").strip()
    before_status = asset.accounting_reconciliation_status
    rec_status, gl_status, matched_ref = _determine_reconciliation_status(
        company=asset.company,
        original_cost=asset.original_cost,
        asset_account=asset.asset_account,
        origins=asset.origins,
        gl_reference=gl_ref_input,
    )
    asset.accounting_reconciliation_status = rec_status
    asset.save(update_fields=("accounting_reconciliation_status", "updated_at"))
    acq_tx = asset.transactions.filter(transaction_type=models.TransactionType.ACQUISITION).first()
    if acq_tx:
        acq_tx.gl_status = gl_status
        if matched_ref:
            acq_tx.gl_reference = matched_ref
        acq_tx.save(update_fields=("gl_status", "gl_reference", "updated_at"))
    audit(
        request,
        asset,
        "RECONCILE_GL",
        before={"accounting_reconciliation_status": before_status},
        after={"accounting_reconciliation_status": rec_status, "gl_reference": matched_ref},
    )
    return asset


def _validate_text_field(field_name, value, max_length):
    """UC-FA-02 EF17: Check invalid control characters / script injection / max length."""
    text = str(value or "")
    if len(text) > max_length:
        raise ValidationError({field_name: "Thông tin nhập không hợp lệ hoặc vượt quá độ dài cho phép."})
    if "\x00" in text or "<script" in text.lower() or "</script" in text.lower():
        raise ValidationError({field_name: "Thông tin nhập không hợp lệ hoặc vượt quá độ dài cho phép."})
    for ch in text:
        if ord(ch) < 32 and ch not in ("\n", "\r", "\t"):
            raise ValidationError({field_name: "Thông tin nhập không hợp lệ hoặc vượt quá độ dài cho phép."})


def update_fixed_asset_info(request, asset_id, data):
    """
    UC-FA-02 — Cập nhật thông tin tài sản.
    Enforces Main Flow (2.1), Alternative Flows (AF01–AF18), Exception Flows (EF01–EF18),
    Business Rules (BR01–BR26), and Accounting Data Invariants (Section 4.1–4.4 & Section 5).
    Returns (asset, changed_fields_dict, message).
    """
    from iam.permissions import has_effective_permission
    from organization.models import Company

    # EF01: Check asset existence
    try:
        asset_initial = models.AssetRecord.objects.select_related(
            "company", "category", "branch", "department", "custodian",
            "asset_account", "accumulated_account",
        ).filter(pk=asset_id).first()
    except (ValueError, ValidationError):
        asset_initial = None

    if not asset_initial:
        raise ValidationError({"detail": "Không tìm thấy thông tin tài sản cố định."})

    # EF18 & BR24: Cross-company check
    req_company_id = request.query_params.get("company_id") or data.get("company")
    if req_company_id and str(asset_initial.company_id) != str(req_company_id):
        raise PermissionDenied("Bạn không có quyền cập nhật tài sản thuộc doanh nghiệp khác.")

    if not request.user or not request.user.is_authenticated:
        raise PermissionDenied("Bạn không có quyền thực hiện thao tác này.")

    if not getattr(request.user, "is_superuser", False):
        iam_acc = getattr(request.user, "iam_account", None)
        if not iam_acc:
            raise PermissionDenied("Bạn không có quyền thực hiện thao tác này.")
        if not iam_acc.company_memberships.filter(company=asset_initial.company).exists():
            raise PermissionDenied("Bạn không có quyền cập nhật tài sản thuộc doanh nghiệp khác.")
        if not has_effective_permission(iam_acc, asset_initial.company, "FA.ASSET.EDIT"):
            raise PermissionDenied("Bạn không có quyền thực hiện thao tác này.")

    try:
        with transaction.atomic():
            asset = models.AssetRecord.objects.select_for_update().filter(pk=asset_initial.pk).first()
            if not asset:
                raise ValidationError({"detail": "Không tìm thấy thông tin tài sản cố định."})

            # EF14: Concurrent status change while user had the form open
            expected_status = data.get("expected_status")
            if expected_status not in (None, "") and str(expected_status).strip() != asset.status:
                raise ValidationError({"status": "Trạng thái tài sản đã thay đổi. Vui lòng kiểm tra lại."})

            # EF03 & AF18 & BR23: Asset disposed or not in an editable status
            if asset.status != models.AssetStatus.ACTIVE or asset.disposed_at is not None:
                raise ValidationError({"status": "Trạng thái tài sản không cho phép cập nhật trực tiếp."})

            # EF13 & BR20: Optimistic concurrency check (version / updated_at)
            expected_version = data.get("version") if "version" in data else data.get("expected_version")
            if expected_version not in (None, ""):
                try:
                    if int(expected_version) != asset.version:
                        raise ValidationError({"version": "Thông tin tài sản đã được thay đổi. Vui lòng tải lại dữ liệu trước khi cập nhật."})
                except (TypeError, ValueError):
                    raise ValidationError({"version": "Thông tin tài sản đã được thay đổi. Vui lòng tải lại dữ liệu trước khi cập nhật."})

            expected_updated_at = data.get("expected_updated_at")
            if expected_updated_at not in (None, ""):
                if str(expected_updated_at).strip() != asset.updated_at.isoformat():
                    raise ValidationError({"updated_at": "Thông tin tài sản đã được thay đổi. Vui lòng tải lại dữ liệu trước khi cập nhật."})

            # EF06 & BR03: Prevent changing asset code
            if "code" in data and data.get("code") is not None:
                if str(data.get("code")).strip() != asset.code:
                    raise ValidationError({"code": "Không được thay đổi mã tài sản trong chức năng này."})

            # EF07 & BR15 & BR26: Prevent changing acquisition voucher number or acquisition date
            for v_key in ("voucher_no", "acquisition_voucher_no"):
                if v_key in data and data.get(v_key) is not None:
                    given_v = str(data.get(v_key)).strip()
                    if given_v and given_v != asset.acquisition_voucher_no:
                        raise ValidationError({v_key: "Thông tin chứng từ ghi tăng không được chỉnh sửa trực tiếp tại hồ sơ tài sản."})

            for d_key in ("acquisition_date", "voucher_date"):
                if d_key in data and data.get(d_key) not in (None, ""):
                    parsed_d = _parse_date(data.get(d_key))
                    if not parsed_d or parsed_d != asset.acquisition_date:
                        raise ValidationError({d_key: "Thông tin chứng từ ghi tăng không được chỉnh sửa trực tiếp tại hồ sơ tài sản."})

            # EF08 & AF11 & AF12 & AF13 & BR07–BR10 & BR21: Prevent direct modification of accounting/depreciation fields
            if data.get("requires_cost_upgrade") or data.get("adjust_original_cost"):
                raise ValidationError({"original_cost": "Thông tin kế toán không được chỉnh sửa trực tiếp. Vui lòng thực hiện nghiệp vụ điều chỉnh phù hợp."})

            decimal_accounting_checks = (
                ("original_cost", asset.original_cost),
                ("accumulated_depreciation", asset.accumulated_depreciation),
                ("remaining_value", asset.remaining_value),
                ("salvage_value", asset.salvage_value),
                ("depreciable_amount", asset.depreciable_amount),
                ("useful_life_value", asset.useful_life_value),
                ("monthly_depreciation_rate", asset.monthly_depreciation_rate),
                ("annual_depreciation_rate", asset.annual_depreciation_rate),
                ("monthly_depreciation_amount", asset.monthly_depreciation_amount),
                ("annual_depreciation_amount", asset.annual_depreciation_amount),
                ("cit_depreciable_cap", asset.cit_depreciable_cap),
                ("cit_monthly_cap", asset.cit_monthly_cap),
            )
            for f_key, current_val in decimal_accounting_checks:
                if f_key in data and data.get(f_key) not in (None, ""):
                    parsed_val = _parse_decimal(data.get(f_key), default=None)
                    if parsed_val is None or parsed_val.quantize(Decimal("0.01")) != Decimal(str(current_val)).quantize(Decimal("0.01")):
                        raise ValidationError({f_key: "Thông tin kế toán không được chỉnh sửa trực tiếp. Vui lòng thực hiện nghiệp vụ điều chỉnh phù hợp."})

            if "useful_life_periods" in data and data.get("useful_life_periods") not in (None, ""):
                try:
                    if int(data.get("useful_life_periods")) != asset.useful_life_periods:
                        raise ValidationError({"useful_life_periods": "Thông tin kế toán không được chỉnh sửa trực tiếp. Vui lòng thực hiện nghiệp vụ điều chỉnh phù hợp."})
                except (TypeError, ValueError):
                    raise ValidationError({"useful_life_periods": "Thông tin kế toán không được chỉnh sửa trực tiếp. Vui lòng thực hiện nghiệp vụ điều chỉnh phù hợp."})

            if "useful_life_unit" in data and data.get("useful_life_unit") not in (None, ""):
                raw_u = str(data.get("useful_life_unit")).strip().upper()
                norm_u = "YEAR" if raw_u in ("YEAR", "YEARS", "NĂM", "NAM") else ("MONTH" if raw_u in ("MONTH", "MONTHS", "THÁNG", "THANG") else raw_u)
                if norm_u != asset.useful_life_unit:
                    raise ValidationError({"useful_life_unit": "Thông tin kế toán không được chỉnh sửa trực tiếp. Vui lòng thực hiện nghiệp vụ điều chỉnh phù hợp."})

            for start_key in ("in_service_date", "depreciation_start_date"):
                if start_key in data and data.get(start_key) not in (None, ""):
                    parsed_start = _parse_date(data.get(start_key))
                    if not parsed_start or parsed_start != asset.in_service_date:
                        raise ValidationError({start_key: "Thông tin kế toán không được chỉnh sửa trực tiếp. Vui lòng thực hiện nghiệp vụ điều chỉnh phù hợp."})

            if "method" in data and data.get("method") not in (None, ""):
                if str(data.get("method")).strip().upper() != asset.method:
                    raise ValidationError({"method": "Thông tin kế toán không được chỉnh sửa trực tiếp. Vui lòng thực hiện nghiệp vụ điều chỉnh phù hợp."})

            if "is_depreciable" in data and data.get("is_depreciable") is not None:
                if bool(data.get("is_depreciable")) != asset.is_depreciable:
                    raise ValidationError({"is_depreciable": "Thông tin kế toán không được chỉnh sửa trực tiếp. Vui lòng thực hiện nghiệp vụ điều chỉnh phù hợp."})

            if "no_depreciation" in data and data.get("no_depreciation") is not None:
                if (not bool(data.get("no_depreciation"))) != asset.is_depreciable:
                    raise ValidationError({"no_depreciation": "Thông tin kế toán không được chỉnh sửa trực tiếp. Vui lòng thực hiện nghiệp vụ điều chỉnh phù hợp."})

            if "allocations" in data and data.get("allocations") is not None:
                if data.get("allocations") != asset.allocations:
                    raise ValidationError({"allocations": "Thông tin kế toán không được chỉnh sửa trực tiếp. Vui lòng thực hiện nghiệp vụ điều chỉnh phù hợp."})

            # EF09 & AF10 & BR12: Category / GL Accounts change check
            for acc_key, cur_acc_id in (
                ("asset_account", asset.asset_account_id),
                ("cost_account", asset.asset_account_id),
                ("accumulated_account", asset.accumulated_account_id),
                ("depr_account", asset.accumulated_account_id),
            ):
                if acc_key in data and data.get(acc_key) not in (None, ""):
                    resolved_acc = _resolve_account(asset.company, data.get(acc_key))
                    if not resolved_acc or resolved_acc.id != cur_acc_id:
                        raise ValidationError({acc_key: "Không thể thay đổi loại tài sản trực tiếp vì ảnh hưởng dữ liệu kế toán."})

            new_category = asset.category
            for cat_key in ("category", "category_code", "category_name"):
                if cat_key in data and data.get(cat_key) not in (None, ""):
                    resolved_cat = _resolve_category(asset.company, data.get(cat_key))
                    if not resolved_cat or resolved_cat.id != asset.category_id:
                        allow_corr = bool(data.get("allow_initial_correction", False))
                        has_subsequent = asset.periods_processed > 0 or asset.transactions.exclude(transaction_type="ACQUISITION").exists()
                        same_accounting = (
                            resolved_cat is not None
                            and resolved_cat.is_active
                            and resolved_cat.company_id == asset.company_id
                            and resolved_cat.asset_type == asset.asset_type
                            and (not resolved_cat.asset_account_id or resolved_cat.asset_account_id == asset.asset_account_id)
                            and (not resolved_cat.accumulated_account_id or resolved_cat.accumulated_account_id == asset.accumulated_account_id)
                            and resolved_cat.default_method == asset.method
                        )
                        if not (allow_corr and not has_subsequent and same_accounting):
                            raise ValidationError({"category": "Không thể thay đổi loại tài sản trực tiếp vì ảnh hưởng dữ liệu kế toán."})
                        new_category = resolved_cat
                    break

            # EF10 & AF08 & AF09 & BR11 & BR12: Department change check
            new_department = asset.department
            for dept_key in ("department", "department_code", "department_name"):
                if dept_key in data and data.get(dept_key) not in (None, ""):
                    resolved_dept = _resolve_department(asset.company, data.get(dept_key))
                    if not resolved_dept or resolved_dept.id != asset.department_id:
                        allow_corr = bool(data.get("allow_initial_correction", False))
                        has_subsequent = asset.periods_processed > 0 or asset.transactions.exclude(transaction_type="ACQUISITION").exists()
                        if not (
                            allow_corr
                            and not has_subsequent
                            and resolved_dept is not None
                            and resolved_dept.company_id == asset.company_id
                            and getattr(resolved_dept, "status", "ACTIVE") in ("ACTIVE", True)
                        ):
                            raise ValidationError({"department": "Vui lòng thực hiện điều chuyển TSCĐ để thay đổi đơn vị sử dụng."})
                        new_department = resolved_dept
                    break

            # EF04 & BR04 & BR05 & EF17: Validate Name
            new_name = asset.name
            if "name" in data:
                new_name = str(data.get("name") or "").strip()
                if not new_name:
                    raise ValidationError({"name": "Vui lòng nhập tên tài sản cố định."})
                _validate_text_field("name", new_name, 255)

            # BR04 & EF17: Validate Country of Origin, Serial Number, Description
            new_country = asset.country_of_origin
            if "country_of_origin" in data:
                new_country = str(data.get("country_of_origin") or "").strip()
                _validate_text_field("country_of_origin", new_country, 120)

            new_serial = asset.serial_number
            if "serial_number" in data:
                new_serial = str(data.get("serial_number") or "").strip()
                _validate_text_field("serial_number", new_serial, 100)

            new_description = asset.description
            if "description" in data:
                new_description = str(data.get("description") or "").strip()
                _validate_text_field("description", new_description, 2000)

            # EF05 & BR06: Validate Manufacture Year
            new_manufacture_year = asset.manufacture_year
            if "manufacture_year" in data:
                raw_year = data.get("manufacture_year")
                if raw_year in (None, ""):
                    new_manufacture_year = None
                else:
                    if isinstance(raw_year, bool):
                        raise ValidationError({"manufacture_year": "Năm sản xuất không hợp lệ. Vui lòng kiểm tra lại."})
                    year_str = str(raw_year).strip()
                    if not year_str.isdigit():
                        raise ValidationError({"manufacture_year": "Năm sản xuất không hợp lệ. Vui lòng kiểm tra lại."})
                    year_int = int(year_str)
                    current_year = timezone.localdate().year
                    if year_int < 1900 or year_int > current_year:
                        raise ValidationError({"manufacture_year": "Năm sản xuất không hợp lệ. Vui lòng kiểm tra lại."})
                    new_manufacture_year = year_int

            # AF05 & AF06 & BR14 & EF17: Validate Components & Accessories (without modifying original_cost)
            def _clean_and_validate_parts(field_key, raw_list):
                if not isinstance(raw_list, list):
                    raise ValidationError({field_key: "Thông tin nhập không hợp lệ hoặc vượt quá độ dài cho phép."})
                cleaned = []
                for part in raw_list:
                    if not isinstance(part, dict):
                        raise ValidationError({field_key: "Thông tin nhập không hợp lệ hoặc vượt quá độ dài cho phép."})
                    p_name = str(part.get("name") or "").strip()
                    if not p_name:
                        continue
                    _validate_text_field(field_key, p_name, 255)
                    p_unit = str(part.get("unit") or "").strip()
                    _validate_text_field(field_key, p_unit, 50)
                    p_qty = _parse_decimal(part.get("quantity", "1"), default=None)
                    p_val = _parse_decimal(part.get("value", "0"), default=None)
                    if p_qty is None or p_qty <= 0 or p_val is None or p_val < 0:
                        raise ValidationError({field_key: "Thông tin nhập không hợp lệ hoặc vượt quá độ dài cho phép."})
                    cleaned.append({
                        "name": p_name,
                        "unit": p_unit,
                        "quantity": str(p_qty),
                        "value": str(p_val),
                    })
                return cleaned

            new_components = asset.components
            if "components" in data and data.get("components") is not None:
                new_components = _clean_and_validate_parts("components", data.get("components"))

            new_accessories = asset.accessories
            if "accessories" in data and data.get("accessories") is not None:
                new_accessories = _clean_and_validate_parts("accessories", data.get("accessories"))

            # AF07 & EF11 & BR13: Validate Origins reference updates (cannot change accounting amounts)
            new_origins = asset.origins
            if "origins" in data and data.get("origins") is not None:
                raw_origins = data.get("origins")
                if not isinstance(raw_origins, list):
                    raise ValidationError({"origins": "Thông tin nguồn gốc hình thành chưa hợp lệ. Vui lòng kiểm tra chứng từ liên quan."})
                if len(raw_origins) == 0 and len(asset.origins or []) > 0:
                    raise ValidationError({"origins": "Thông tin nguồn gốc hình thành chưa hợp lệ. Vui lòng kiểm tra chứng từ liên quan."})

                cleaned_origins = []
                origins_sum = Decimal("0")
                other_assets = list(
                    models.AssetRecord.objects.filter(company=asset.company)
                    .exclude(pk=asset.pk)
                    .exclude(status="DISPOSED")
                    .only("id", "source_reference", "origins")
                )
                for idx, item in enumerate(raw_origins):
                    if not isinstance(item, dict):
                        raise ValidationError({"origins": "Thông tin nguồn gốc hình thành chưa hợp lệ. Vui lòng kiểm tra chứng từ liên quan."})
                    doc_no = str(item.get("document_number") or item.get("voucher_no") or "").strip()
                    if not doc_no:
                        raise ValidationError({"origins": "Thông tin nguồn gốc hình thành chưa hợp lệ. Vui lòng kiểm tra chứng từ liên quan."})
                    _validate_text_field("origins", doc_no, 100)

                    # Check duplicate with another asset
                    allow_multi = bool(item.get("allow_multiple_assets", False))
                    if not allow_multi:
                        for oa in other_assets:
                            if oa.source_reference == doc_no:
                                raise ValidationError({"origins": "Thông tin nguồn gốc hình thành chưa hợp lệ. Vui lòng kiểm tra chứng từ liên quan."})
                            for oa_orig in (oa.origins or []):
                                if isinstance(oa_orig, dict) and str(oa_orig.get("document_number") or "") == doc_no and not oa_orig.get("allow_multiple_assets"):
                                    raise ValidationError({"origins": "Thông tin nguồn gốc hình thành chưa hợp lệ. Vui lòng kiểm tra chứng từ liên quan."})

                    amt = _parse_decimal(item.get("capitalized_amount") if "capitalized_amount" in item else item.get("amount"), default=None)
                    if amt is None or amt <= 0:
                        raise ValidationError({"origins": "Thông tin nguồn gốc hình thành chưa hợp lệ. Vui lòng kiểm tra chứng từ liên quan."})
                    # BR13: Cannot alter existing line's accounting amount
                    if idx < len(asset.origins or []):
                        old_line_amt = _parse_decimal((asset.origins[idx] or {}).get("amount"), default=None)
                        if old_line_amt is not None and amt.quantize(Decimal("0.0001")) != old_line_amt.quantize(Decimal("0.0001")):
                            raise ValidationError({"origins": "Thông tin nguồn gốc hình thành chưa hợp lệ. Vui lòng kiểm tra chứng từ liên quan."})
                    origins_sum += amt
                    doc_date = _parse_date(item.get("document_date"))
                    cleaned_origins.append({
                        "origin_type": str(item.get("origin_type") or "Mua sắm mới").strip(),
                        "document_number": doc_no,
                        "document_date": str(doc_date) if doc_date else str(item.get("document_date") or "").strip(),
                        "amount": str(amt.quantize(Decimal("0.0001"))),
                        "partner_code": str(item.get("partner_code") or "").strip(),
                        "partner_name": str(item.get("partner_name") or "").strip(),
                        "source_document_id": str(item.get("source_document_id") or "").strip(),
                        "allow_multiple_assets": allow_multi,
                    })

                if cleaned_origins and origins_sum.quantize(Decimal("0.0001")) != asset.original_cost.quantize(Decimal("0.0001")):
                    raise ValidationError({"origins": "Thông tin nguồn gốc hình thành chưa hợp lệ. Vui lòng kiểm tra chứng từ liên quan."})
                new_origins = cleaned_origins

            # Step 14 & Section 4.4: Compare before and after to determine actual changed fields
            before_values = {}
            after_values = {}
            update_fields = []

            if new_name != asset.name:
                before_values["name"] = asset.name
                after_values["name"] = new_name
                asset.name = new_name
                update_fields.append("name")

            if new_country != asset.country_of_origin:
                before_values["country_of_origin"] = asset.country_of_origin
                after_values["country_of_origin"] = new_country
                asset.country_of_origin = new_country
                update_fields.append("country_of_origin")

            if new_manufacture_year != asset.manufacture_year:
                before_values["manufacture_year"] = asset.manufacture_year
                after_values["manufacture_year"] = new_manufacture_year
                asset.manufacture_year = new_manufacture_year
                update_fields.append("manufacture_year")

            if new_serial != asset.serial_number:
                before_values["serial_number"] = asset.serial_number
                after_values["serial_number"] = new_serial
                asset.serial_number = new_serial
                update_fields.append("serial_number")

            if new_description != asset.description:
                before_values["description"] = asset.description
                after_values["description"] = new_description
                asset.description = new_description
                update_fields.append("description")

            if new_components != asset.components:
                before_values["components"] = asset.components
                after_values["components"] = new_components
                asset.components = new_components
                update_fields.append("components")

            if new_accessories != asset.accessories:
                before_values["accessories"] = asset.accessories
                after_values["accessories"] = new_accessories
                asset.accessories = new_accessories
                update_fields.append("accessories")

            if new_origins != asset.origins:
                before_values["origins"] = asset.origins
                after_values["origins"] = new_origins
                asset.origins = new_origins
                update_fields.append("origins")
                if new_origins and new_origins[0].get("document_number"):
                    asset.source_reference = new_origins[0]["document_number"]
                    update_fields.append("source_reference")

            if new_category.id != asset.category_id:
                before_values["category"] = asset.category.name
                after_values["category"] = new_category.name
                asset.category = new_category
                update_fields.append("category")

            if (new_department.id if new_department else None) != asset.department_id:
                before_values["department"] = asset.department.name if asset.department else ""
                after_values["department"] = new_department.name if new_department else ""
                asset.department = new_department
                update_fields.append("department")

            # AF14 & BR18: If no actual changes, return "Không có thông tin thay đổi." without creating fake history
            if not update_fields:
                return asset, {}, "Không có thông tin thay đổi."

            # EF12 & Step 11: Validate Update Reason (mandatory when updating asset info)
            raw_reason = data.get("update_reason") if "update_reason" in data else data.get("reason")
            update_reason = str(raw_reason or "").strip()
            if not update_reason:
                raise ValidationError({"update_reason": "Vui lòng nhập lý do cập nhật thông tin tài sản."})
            _validate_text_field("update_reason", update_reason, 500)

            # Section 4.1–4.3 Invariants assertion: original_cost, accumulated_depreciation, remaining_value remain untouched
            user_actor = actor(request)
            asset.version = (asset.version or 1) + 1
            asset.last_update_reason = update_reason
            asset.updated_by = user_actor
            update_fields.extend(["version", "last_update_reason", "updated_by", "updated_at"])
            asset.save(update_fields=update_fields)

            # Step 17 & BR19: Record Audit Log with asset_code, changed_fields, before, after, reason, actor, timestamp
            audit(
                request,
                asset,
                "UPDATE_INFO",
                before=before_values,
                after=after_values,
                reason=update_reason,
            )
            return asset, {"before": before_values, "after": after_values, "changed_fields": list(after_values.keys())}, "Cập nhật thông tin tài sản thành công."
    except DatabaseError as exc:
        # EF15 & EF16
        raise ValidationError({"detail": "Cập nhật thông tin tài sản thất bại. Vui lòng thử lại."}) from exc


# ==============================================================================
# UC-FA-03 — TÍNH KHẤU HAO TÀI SẢN CỐ ĐỊNH
# ==============================================================================

def _check_depreciation_permission(request, company, perm_code="FA.CALCULATION.CALCULATE", uc04=False):
    """EF01 (UC-FA-03) / EF02 & EF21 (UC-FA-04): Verify user permission to calculate/save/post fixed asset depreciation."""
    from iam.permissions import has_effective_permission

    err_msg = "Bạn không có quyền ghi sổ chứng từ khấu hao." if uc04 else "Bạn không có quyền tính khấu hao tài sản cố định."
    cross_company_msg = (
        "Bạn không có quyền ghi sổ chứng từ khấu hao thuộc doanh nghiệp khác."
        if uc04
        else "Bạn không có quyền tính khấu hao tài sản cố định thuộc doanh nghiệp khác."
    )
    if not request.user or not request.user.is_authenticated:
        raise PermissionDenied(err_msg)
    if getattr(request.user, "is_superuser", False):
        return
    iam_acc = getattr(request.user, "iam_account", None)
    if not iam_acc:
        raise PermissionDenied(err_msg)
    if not iam_acc.company_memberships.filter(company=company).exists():
        if iam_acc.company_memberships.exists():
            raise PermissionDenied(cross_company_msg)
        raise PermissionDenied(err_msg)
    if uc04:
        if not has_effective_permission(iam_acc, company, "FA.CALCULATION.POST"):
            raise PermissionDenied(err_msg)
        return
    if not (
        has_effective_permission(iam_acc, company, perm_code)
        or has_effective_permission(iam_acc, company, "FA.CALCULATION.CREATE")
        or has_effective_permission(iam_acc, company, "FA.CALCULATION.POST")
    ):
        raise PermissionDenied(err_msg)


def _parse_depreciation_period(data):
    """EF02 & BR02 & BR03: Parse and validate month (1..12) and year (1900..2100)."""
    import calendar

    raw_month = data.get("month") if "month" in data else data.get("period_month")
    raw_year = data.get("year") if "year" in data else data.get("period_year")
    period_code_in = str(data.get("period_code") or "").strip()

    if (raw_month in (None, "") or raw_year in (None, "")) and "-" in period_code_in:
        parts = period_code_in.split("-")
        if len(parts) == 2 and parts[0].isdigit() and parts[1].isdigit():
            raw_year, raw_month = parts[0], parts[1]

    if isinstance(raw_month, bool) or isinstance(raw_year, bool):
        raise ValidationError({"period": "Vui lòng chọn kỳ tính khấu hao hợp lệ."})
    try:
        month = int(str(raw_month).strip())
        year = int(str(raw_year).strip())
    except (TypeError, ValueError):
        raise ValidationError({"period": "Vui lòng chọn kỳ tính khấu hao hợp lệ."})

    if month < 1 or month > 12 or year < 1900 or year > 2100:
        raise ValidationError({"period": "Vui lòng chọn kỳ tính khấu hao hợp lệ."})

    last_day = calendar.monthrange(year, month)[1]
    period_start = date_cls(year, month, 1)
    period_end = date_cls(year, month, last_day)
    period_code = f"{year:04d}-{month:02d}"
    return month, year, period_code, period_start, period_end, last_day


def _has_locked_subsequent_period(company, period_end):
    """EF17 & BR17: Check if any subsequent period after period_end is locked."""
    from general_ledger.models import AccountingPeriod

    if models.AssetPeriod.objects.filter(
        company=company, start_date__gt=period_end, status__in=("CLOSED", "LOCKED")
    ).exists():
        return True
    if AccountingPeriod.objects.filter(
        company=company, start_date__gt=period_end, status__in=("CLOSED", "LOCKED")
    ).exists():
        return True
    return False


def _next_depreciation_voucher_no(company):
    """Step 7 & 12: Propose next sequential depreciation voucher number KH00001."""
    existing_numbers = list(
        models.CalculationRun.objects.filter(company=company, calculation_type="DEPRECIATION")
        .values_list("number", flat=True)
    )
    max_seq = 0
    for num_str in existing_numbers:
        s = str(num_str or "").strip().upper()
        if s.startswith("KH") and s[2:].isdigit():
            max_seq = max(max_seq, int(s[2:]))
    next_seq = max_seq + 1
    candidate = f"KH{next_seq:05d}"
    while candidate in existing_numbers:
        next_seq += 1
        candidate = f"KH{next_seq:05d}"
    return candidate


def _compute_depreciation_for_company_period(
    company,
    month,
    year,
    period_code,
    period_start,
    period_end,
    total_days_in_period,
    recalculate=False,
    explicit_asset_ids=None,
    require_explicit_allocations=False,
):
    """
    Core calculation engine for UC-FA-03 Steps 13–23, AF05–AF14, EF08–EF24, BR04–BR26, Section 4.1–4.8.
    Returns dict with lines, allocations, accounting_entries, total_amount, total_deductible, total_non_deductible.
    """
    # EF22: If explicit asset_ids passed, check they all belong to company
    if explicit_asset_ids:
        found_count = models.AssetRecord.objects.filter(company=company, id__in=explicit_asset_ids).count()
        if found_count != len(set(str(x) for x in explicit_asset_ids)):
            raise PermissionDenied("Bạn không có quyền tính khấu hao tài sản cố định thuộc doanh nghiệp khác.")

    # Step 13 & BR04 & BR05 & BR06: Retrieve candidate fixed assets of company
    qs = models.AssetRecord.objects.select_related(
        "category", "branch", "department", "asset_account", "accumulated_account",
        "category__asset_account", "category__accumulated_account", "category__expense_account",
    ).filter(
        company=company,
        asset_type="FIXED_ASSET",
    ).order_by("code")

    if explicit_asset_ids:
        qs = qs.filter(id__in=explicit_asset_ids)

    candidates = list(qs)
    eligible_lines = []
    all_allocations = []
    all_accounting_entries = []
    total_amount = Decimal("0")
    total_deductible = Decimal("0")
    total_non_deductible = Decimal("0")
    skipped_already_depreciated = 0

    valid_expense_prefixes = ("621", "622", "623", "627", "641", "642", "154", "241", "811")

    for asset in candidates:
        # AF07 & BR05: Skip assets marked non-depreciable
        if not asset.is_depreciable:
            continue

        # Exclude suspended/draft or assets disposed BEFORE period_start (AF08, BR06)
        if asset.status not in (models.AssetStatus.ACTIVE, models.AssetStatus.DISPOSED):
            continue
        if asset.status == models.AssetStatus.DISPOSED and (not asset.disposed_at or asset.disposed_at < period_start):
            continue
        if asset.disposed_at and asset.disposed_at < period_start:
            continue

        # EF10: Validate in_service_date
        if not asset.in_service_date or (
            asset.source_module != "OPENING"
            and asset.acquisition_date
            and asset.in_service_date < asset.acquisition_date
        ):
            raise ValidationError({
                "in_service_date": "Ngày bắt đầu tính khấu hao của tài sản không hợp lệ.",
                "asset_code": asset.code,
            })

        # Exclude assets whose depreciation start date is after the end of this period
        if asset.in_service_date > period_end:
            continue

        # EF08: Validate original_cost and depreciable_amount
        depreciable_base = (
            asset.depreciable_amount
            if asset.depreciable_amount and asset.depreciable_amount > 0
            else (asset.original_cost - (asset.salvage_value or Decimal("0")))
        )
        if (
            asset.original_cost is None
            or asset.original_cost <= 0
            or depreciable_base is None
            or depreciable_base <= 0
            or depreciable_base > asset.original_cost
        ):
            raise ValidationError({
                "original_cost": f"Chưa đủ thông tin nguyên giá hoặc giá trị tính khấu hao của tài sản ({asset.code}).",
                "detail": "Chưa đủ thông tin nguyên giá hoặc giá trị tính khấu hao của tài sản.",
                "asset_code": asset.code,
            })

        # EF09: Validate useful_life_periods and depreciation method
        if not asset.useful_life_periods or asset.useful_life_periods <= 0 or not asset.method:
            raise ValidationError({
                "useful_life_periods": f"Chưa thiết lập đầy đủ thông tin khấu hao của tài sản ({asset.code}).",
                "detail": "Chưa thiết lập đầy đủ thông tin khấu hao của tài sản.",
                "asset_code": asset.code,
            })

        # EF23: Validate accumulated_depreciation
        opening_accum = asset.accumulated_depreciation or Decimal("0")
        if opening_accum < 0 or opening_accum > depreciable_base:
            raise ValidationError({
                "accumulated_depreciation": f"Dữ liệu hao mòn lũy kế của tài sản không hợp lệ ({asset.code}).",
                "detail": "Dữ liệu hao mòn lũy kế của tài sản không hợp lệ.",
                "asset_code": asset.code,
            })

        # AF06 & BR11: Asset already fully depreciated -> skip without error
        remaining_depreciable = depreciable_base - opening_accum
        if remaining_depreciable <= 0:
            continue

        # EF16 & AF14 & BR14 & BR15: Check if asset already has active depreciation in this period
        already_in_tx = models.AssetTransaction.objects.filter(
            asset=asset,
            transaction_type="DEPRECIATION",
            period_code=period_code,
            status__in=("DRAFT", "PENDING_APPROVAL", "APPROVED", "POSTED"),
        ).exists()
        already_in_run = models.CalculationLine.objects.filter(
            asset=asset,
            run__company=company,
            run__calculation_type="DEPRECIATION",
            run__period_code=period_code,
            run__status__in=("DRAFT", "CALCULATED", "POSTED"),
        ).exists()
        if (already_in_tx or already_in_run) and not recalculate:
            skipped_already_depreciated += 1
            continue

        # Step 14–15 & AF05 & AF08 & AF09 & BR07–BR12 & Section 4.1–4.2:
        # Determine effective start and end date within period
        eff_start = max(period_start, asset.in_service_date)
        eff_end = min(period_end, asset.disposed_at) if asset.disposed_at and asset.disposed_at <= period_end else period_end
        if eff_end < eff_start:
            continue
        eligible_days = (eff_end - eff_start).days + 1

        # Determine full monthly depreciation according to method and revaluation/life-change history (AF09, BR08, BR09, BR12)
        has_reval_or_life_change = asset.transactions.filter(
            transaction_type__in=("VALUE_INCREASE", "VALUE_DECREASE", "LIFE_CHANGE"),
            status="POSTED",
        ).exists()

        use_whole_vnd = depreciable_base >= Decimal("10000") and depreciable_base == depreciable_base.to_integral_value()
        quant_unit = Decimal("1") if use_whole_vnd else Decimal("0.0001")

        if asset.method == models.DepreciationMethod.STRAIGHT_LINE:
            if has_reval_or_life_change:
                periods_left = max(asset.useful_life_periods - asset.periods_processed, 1)
                full_monthly = (remaining_depreciable / Decimal(periods_left)).quantize(quant_unit)
            elif asset.monthly_depreciation_amount and asset.monthly_depreciation_amount > 0:
                full_monthly = asset.monthly_depreciation_amount.quantize(quant_unit)
            else:
                full_monthly = (depreciable_base / Decimal(asset.useful_life_periods)).quantize(quant_unit)
        elif asset.method == models.DepreciationMethod.DECLINING_BALANCE:
            # BR09: Declining balance algorithm (Accelerated rate = Straight-line rate * adjustment factor)
            adj_factor = Decimal("2.0") if asset.useful_life_periods > 48 else Decimal("1.5")
            annual_rate = (Decimal("12") / Decimal(asset.useful_life_periods)) * adj_factor
            monthly_rate = annual_rate / Decimal("12")
            full_monthly = (asset.remaining_value * monthly_rate).quantize(quant_unit)
        else:
            # Units of production or configured monthly amount
            if asset.monthly_depreciation_amount and asset.monthly_depreciation_amount > 0:
                full_monthly = asset.monthly_depreciation_amount.quantize(quant_unit)
            else:
                raise ValidationError({
                    "method": "Chưa thiết lập đầy đủ thông tin khấu hao của tài sản.",
                    "asset_code": asset.code,
                })

        # AF05 & AF08 & Section 4.1: Prorate by actual eligible days in period if not full month
        if eligible_days < total_days_in_period:
            raw_period_depr = (full_monthly * Decimal(eligible_days) / Decimal(total_days_in_period)).quantize(quant_unit)
        else:
            raw_period_depr = full_monthly

        # Section 4.2: Final period cap: KH kỳ cuối = MIN(KH tính theo phương pháp, Giá trị còn được phép khấu hao trước kỳ)
        period_depr = min(raw_period_depr, remaining_depreciable)
        if period_depr <= 0 or period_depr > remaining_depreciable:
            raise ValidationError({
                "amount": "Giá trị khấu hao vượt mức được phép của tài sản.",
                "detail": "Giá trị khấu hao vượt mức được phép của tài sản.",
                "asset_code": asset.code,
            })

        # Step 16 & AF12 & EF24 & BR24 & BR25 & Section 4.6: CIT Tax Deductible vs Non-Deductible
        if asset.cit_cap_enabled:
            if (not asset.cit_depreciable_cap or asset.cit_depreciable_cap <= 0) and (
                not asset.cit_monthly_cap or asset.cit_monthly_cap <= 0
            ):
                raise ValidationError({
                    "cit_cap": "Chưa đủ dữ liệu xác định chi phí khấu hao theo thuế TNDN.",
                    "detail": "Chưa đủ dữ liệu xác định chi phí khấu hao theo thuế TNDN.",
                    "asset_code": asset.code,
                })
            base_tax_monthly = (
                asset.cit_monthly_cap
                if asset.cit_monthly_cap and asset.cit_monthly_cap > 0
                else (asset.cit_depreciable_cap / Decimal(asset.useful_life_periods)).quantize(quant_unit)
            )
            if eligible_days < total_days_in_period:
                eff_tax_cap = (base_tax_monthly * Decimal(eligible_days) / Decimal(total_days_in_period)).quantize(quant_unit)
            else:
                eff_tax_cap = base_tax_monthly.quantize(quant_unit)
            deductible_amt = min(period_depr, eff_tax_cap)
            non_deductible_amt = period_depr - deductible_amt
        else:
            deductible_amt = period_depr
            non_deductible_amt = Decimal("0")

        # EF14 & BR22 & BR23: Validate accumulated depreciation account (TK Có 214x)
        accum_acc = asset.accumulated_account or (asset.category.accumulated_account if asset.category_id else None)
        if (
            not accum_acc
            or accum_acc.company_id != company.id
            or accum_acc.status != "ACTIVE"
            or not accum_acc.is_postable
            or not accum_acc.code.startswith("214")
        ):
            raise ValidationError({
                "accumulated_account": "Tài khoản hạch toán khấu hao không hợp lệ. Vui lòng kiểm tra lại.",
                "detail": "Tài khoản hạch toán khấu hao không hợp lệ. Vui lòng kiểm tra lại.",
                "asset_code": asset.code,
            })

        # Step 19–22 & AF10 & AF11 & EF12 & EF13 & EF14 & BR13 & BR19–BR23 & BR33: Cost Allocation
        raw_allocs = asset.allocations if isinstance(asset.allocations, list) and len(asset.allocations) > 0 else None
        if not raw_allocs:
            if require_explicit_allocations or not (asset.category_id and asset.category.expense_account_id and asset.department_id):
                raise ValidationError({
                    "allocations": f"Chưa thiết lập phân bổ chi phí khấu hao cho tài sản ({asset.code}).",
                    "detail": "Chưa thiết lập phân bổ chi phí khấu hao cho tài sản.",
                    "asset_code": asset.code,
                })
            raw_allocs = [
                {
                    "department_id": str(asset.department_id),
                    "department_name": asset.department.name if asset.department else "",
                    "rate": "100",
                    "expense_account_id": str(asset.category.expense_account_id),
                    "expense_account": asset.category.expense_account.code,
                    "expense_item": "Chi phí khấu hao TSCĐ",
                    "cost_center": "",
                }
            ]
        elif len(raw_allocs) == 1 and asset.department_id:
            # AF10, AF20, Section 5.6 & BR13: Check if asset was transferred on or before period_end
            mid_transfer = (
                asset.transactions.filter(
                    transaction_type="TRANSFER",
                    status="POSTED",
                    transaction_date__gt=period_start,
                    transaction_date__lte=period_end,
                )
                .order_by("-transaction_date", "-created_at")
                .first()
            )
            if mid_transfer and isinstance(mid_transfer.after_snapshot, dict) and mid_transfer.after_snapshot.get("prorate_in_period"):
                total_days = Decimal((period_end - period_start).days + 1)
                old_days = Decimal((mid_transfer.transaction_date - period_start).days)
                old_amt = (period_depr * old_days / total_days).quantize(quant_unit)
                new_amt = period_depr - old_amt
                old_rate = (old_days * Decimal("100") / total_days).quantize(Decimal("0.01"))
                new_rate = Decimal("100.00") - old_rate
                before_snap = mid_transfer.before_snapshot if isinstance(mid_transfer.before_snapshot, dict) else {}
                after_snap = mid_transfer.after_snapshot
                old_dept_id = str(before_snap.get("from_department_id") or before_snap.get("department_id") or "")
                old_dept_name = str(before_snap.get("from_department_name") or before_snap.get("department_name") or "")
                old_exp_item = str(before_snap.get("expense_item") or raw_allocs[0].get("expense_item") or "Chi phí khấu hao TSCĐ")
                old_cost_center = str(before_snap.get("cost_object") or before_snap.get("cost_center") or old_dept_name)
                new_exp_item = str(after_snap.get("expense_item") or raw_allocs[0].get("expense_item") or "Chi phí khấu hao TSCĐ")
                new_cost_center = str(
                    after_snap.get("cost_object")
                    or after_snap.get("project")
                    or raw_allocs[0].get("cost_center")
                    or asset.department.name
                )
                raw_allocs = [
                    {
                        **raw_allocs[0],
                        "department_id": old_dept_id,
                        "department_name": old_dept_name,
                        "rate": str(old_rate),
                        "exact_amount": str(old_amt),
                        "expense_item": old_exp_item,
                        "cost_center": old_cost_center,
                    },
                    {
                        **raw_allocs[0],
                        "department_id": str(asset.department_id),
                        "department_name": asset.department.name,
                        "rate": str(new_rate),
                        "exact_amount": str(new_amt),
                        "expense_item": new_exp_item,
                        "cost_center": new_cost_center,
                    },
                ]
            else:
                has_transfer = asset.transactions.filter(transaction_type="TRANSFER", status="POSTED", transaction_date__lte=period_end).exists()
                if has_transfer:
                    raw_allocs = [
                        {
                            **raw_allocs[0],
                            "department_id": str(asset.department_id),
                            "department_name": asset.department.name,
                        }
                    ]

        rate_sum = Decimal("0")
        parsed_allocs = []
        for a_line in raw_allocs:
            if not isinstance(a_line, dict):
                raise ValidationError({
                    "allocations": "Chưa thiết lập phân bổ chi phí khấu hao cho tài sản.",
                    "detail": "Chưa thiết lập phân bổ chi phí khấu hao cho tài sản.",
                })
            rate = _parse_decimal(a_line.get("rate") if "rate" in a_line else a_line.get("percentage"), default=None)
            if rate is None or rate <= 0:
                raise ValidationError({
                    "allocations": "Tổng tỷ lệ phân bổ khấu hao phải bằng 100%.",
                    "detail": "Tổng tỷ lệ phân bổ khấu hao phải bằng 100%.",
                })
            rate_sum += rate

            exp_acc = _resolve_account(
                company,
                a_line.get("expense_account_id") or a_line.get("expense_account") or a_line.get("expense_account_code"),
            )
            if not exp_acc and asset.category_id and asset.category.expense_account_id:
                exp_acc = asset.category.expense_account
            if (
                not exp_acc
                or exp_acc.company_id != company.id
                or exp_acc.status != "ACTIVE"
                or not exp_acc.is_postable
                or not any(exp_acc.code.startswith(p) for p in valid_expense_prefixes)
            ):
                raise ValidationError({
                    "expense_account": "Tài khoản hạch toán khấu hao không hợp lệ. Vui lòng kiểm tra lại.",
                    "detail": "Tài khoản hạch toán khấu hao không hợp lệ. Vui lòng kiểm tra lại.",
                    "asset_code": asset.code,
                })

            dept_obj = _resolve_department(
                company,
                a_line.get("department_id") or a_line.get("department") or a_line.get("department_name"),
            ) or asset.department
            dept_name = dept_obj.name if dept_obj else str(a_line.get("department_name") or a_line.get("department") or "")
            if not dept_name:
                raise ValidationError({
                    "allocations": "Chưa thiết lập phân bổ chi phí khấu hao cho tài sản.",
                    "detail": "Chưa thiết lập phân bổ chi phí khấu hao cho tài sản.",
                    "asset_code": asset.code,
                })

            parsed_allocs.append({
                "rate": rate,
                "exact_amount": _parse_decimal(a_line.get("exact_amount"), default=None) if "exact_amount" in a_line else None,
                "expense_account": exp_acc,
                "department_name": dept_name,
                "department_id": str(dept_obj.id) if dept_obj else "",
                "expense_item": str(a_line.get("expense_item") or "Chi phí khấu hao TSCĐ").strip(),
                "cost_center": str(a_line.get("cost_center") or dept_name).strip(),
            })

        if rate_sum.quantize(Decimal("0.01")) != Decimal("100.00"):
            raise ValidationError({
                "allocations": "Tổng tỷ lệ phân bổ khấu hao phải bằng 100%.",
                "detail": "Tổng tỷ lệ phân bổ khấu hao phải bằng 100%.",
                "asset_code": asset.code,
            })

        # Compute allocated amounts with exact rounding absorption on the last line (AF11, BR21, BR33, Section 4.5)
        asset_alloc_rows = []
        asset_acct_rows = []
        allocated_running = Decimal("0")
        for idx, pa in enumerate(parsed_allocs):
            if pa.get("exact_amount") is not None and idx < len(parsed_allocs) - 1:
                alloc_amt = pa["exact_amount"].quantize(quant_unit)
                allocated_running += alloc_amt
            elif idx < len(parsed_allocs) - 1:
                alloc_amt = (period_depr * pa["rate"] / Decimal("100")).quantize(quant_unit)
                allocated_running += alloc_amt
            else:
                alloc_amt = period_depr - allocated_running

            alloc_entry = {
                "asset_id": str(asset.id),
                "asset_code": asset.code,
                "asset_name": asset.name,
                "department_id": pa["department_id"],
                "department_name": pa["department_name"],
                "rate": str(pa["rate"].quantize(Decimal("0.01"))),
                "allocated_amount": str(alloc_amt),
                "expense_account_id": str(pa["expense_account"].id),
                "expense_account_code": pa["expense_account"].code,
                "credit_account_id": str(accum_acc.id),
                "credit_account_code": accum_acc.code,
                "expense_item": pa["expense_item"],
                "cost_center": pa["cost_center"],
            }
            acct_entry = {
                "asset_id": str(asset.id),
                "asset_code": asset.code,
                "description": f"Trích khấu hao TSCĐ {asset.code} - {asset.name} tháng {month:02d}/{year} ({pa['department_name']})",
                "debit_account": pa["expense_account"].code,
                "debit_account_code": pa["expense_account"].code,
                "debit_account_id": str(pa["expense_account"].id),
                "credit_account": accum_acc.code,
                "credit_account_code": accum_acc.code,
                "credit_account_id": str(accum_acc.id),
                "amount": str(alloc_amt),
                "department_name": pa["department_name"],
                "cost_center": pa["cost_center"],
                "expense_item": pa["expense_item"],
            }
            asset_alloc_rows.append(alloc_entry)
            asset_acct_rows.append(acct_entry)
            all_allocations.append(alloc_entry)
            all_accounting_entries.append(acct_entry)

        opening_rem = asset.original_cost - opening_accum
        closing_accum = opening_accum + period_depr
        closing_rem = asset.original_cost - closing_accum

        eligible_lines.append({
            "asset": asset,
            "asset_id": str(asset.id),
            "asset_code": asset.code,
            "asset_name": asset.name,
            "category_name": asset.category.name if asset.category_id else "",
            "department_name": asset.department.name if asset.department_id else "",
            "original_cost": asset.original_cost,
            "depreciable_amount": depreciable_base,
            "opening_accumulated_depreciation": opening_accum,
            "closing_accumulated_depreciation": closing_accum,
            "opening_value": opening_rem,
            "amount": period_depr,
            "closing_value": closing_rem,
            "deductible_amount": deductible_amt,
            "non_deductible_amount": non_deductible_amt,
            "eligible_days": eligible_days,
            "total_days_in_period": total_days_in_period,
            "allocations": asset_alloc_rows,
            "accounting_lines": asset_acct_rows,
            "asset_version": asset.version or 1,
        })
        total_amount += period_depr
        total_deductible += deductible_amt
        total_non_deductible += non_deductible_amt

    if not eligible_lines:
        if skipped_already_depreciated > 0:
            raise ValidationError({"detail": "Tài sản đã được tính khấu hao trong kỳ đã chọn."})
        raise ValidationError({"detail": "Không có tài sản cố định cần tính khấu hao trong kỳ đã chọn."})

    return {
        "lines": eligible_lines,
        "allocations": all_allocations,
        "accounting_entries": all_accounting_entries,
        "total_amount": total_amount,
        "total_deductible_amount": total_deductible,
        "total_non_deductible_amount": total_non_deductible,
    }


def preview_depreciation_period(request, data=None):
    """
    UC-FA-03 Steps 6–23: Validate period, permissions, lock status, and calculate preview
    for the 3 tabs (Tính khấu hao, Phân bổ, Hạch toán).
    """
    from organization.models import Company

    if data is None:
        data = request.data if request.method == "POST" else request.query_params

    company_id = request.query_params.get("company_id") or data.get("company")
    try:
        company = Company.objects.get(pk=company_id)
    except (Company.DoesNotExist, ValueError, TypeError):
        raise PermissionDenied("Bạn không có quyền tính khấu hao tài sản cố định.")

    _check_depreciation_permission(request, company, "FA.CALCULATION.CALCULATE")

    month, year, period_code, period_start, period_end, last_day = _parse_depreciation_period(data)
    recalculate = bool(data.get("recalculate", False))

    # EF03 & BR18: Check if period is locked
    if _closed(company, period_end):
        raise ValidationError({"period": "Kỳ kế toán đã khóa, không thể tính khấu hao tài sản cố định."})

    # AF03 & EF17 & BR17: If calculating/recalculating a prior period, check if a subsequent period is locked
    if _has_locked_subsequent_period(company, period_end):
        raise ValidationError({"period": "Không thể tính lại khấu hao vì ảnh hưởng đến kỳ kế toán đã khóa."})

    calc_result = _compute_depreciation_for_company_period(
        company=company,
        month=month,
        year=year,
        period_code=period_code,
        period_start=period_start,
        period_end=period_end,
        total_days_in_period=last_day,
        recalculate=recalculate,
        explicit_asset_ids=data.get("asset_ids"),
        require_explicit_allocations=bool(data.get("require_explicit_allocations", False)),
    )

    suggested_no = _next_depreciation_voucher_no(company)
    date_display = period_end.strftime("%d/%m/%Y")

    return {
        "voucher_no": suggested_no,
        "voucher_date": date_display,
        "posting_date": date_display,
        "period_month": month,
        "period_year": year,
        "period_code": period_code,
        "period_start": str(period_start),
        "period_end": str(period_end),
        "description": f"Khấu hao TSCĐ tháng {month} năm {year}",
        "total_amount": str(calc_result["total_amount"]),
        "total_deductible_amount": str(calc_result["total_deductible_amount"]),
        "total_non_deductible_amount": str(calc_result["total_non_deductible_amount"]),
        "lines": [
            {
                "asset_id": item["asset_id"],
                "asset_code": item["asset_code"],
                "asset_name": item["asset_name"],
                "category_name": item["category_name"],
                "department_name": item["department_name"],
                "original_cost": str(item["original_cost"]),
                "depreciable_amount": str(item["depreciable_amount"]),
                "opening_accumulated_depreciation": str(item["opening_accumulated_depreciation"]),
                "closing_accumulated_depreciation": str(item["closing_accumulated_depreciation"]),
                "opening_value": str(item["opening_value"]),
                "amount": str(item["amount"]),
                "closing_value": str(item["closing_value"]),
                "deductible_amount": str(item["deductible_amount"]),
                "non_deductible_amount": str(item["non_deductible_amount"]),
                "eligible_days": item["eligible_days"],
                "total_days_in_period": item["total_days_in_period"],
                "asset_version": item["asset_version"],
            }
            for item in calc_result["lines"]
        ],
        "allocations": calc_result["allocations"],
        "accounting_entries": calc_result["accounting_entries"],
    }


def save_and_post_depreciation_voucher(request, data=None):
    """
    UC-FA-03 Steps 24–28, AF14–AF20, EF01–EF25, BR01–BR34:
    Validates, saves, and (when post_now=True, default) posts the depreciation voucher,
    updating asset accumulated_depreciation, remaining_value, and AuditLog atomically.
    """
    from organization.models import Company

    if data is None:
        data = request.data

    company_id = request.query_params.get("company_id") or data.get("company")
    try:
        company = Company.objects.get(pk=company_id)
    except (Company.DoesNotExist, ValueError, TypeError):
        raise PermissionDenied("Bạn không có quyền tính khấu hao tài sản cố định.")

    post_now = bool(data.get("post_now", True))
    _check_depreciation_permission(
        request,
        company,
        "FA.CALCULATION.POST" if post_now else "FA.CALCULATION.CREATE",
    )

    # EF25: Idempotency check for duplicate request submission
    idempotency_key = str(data.get("idempotency_key") or "").strip() or None
    if idempotency_key:
        existing_idem = models.CalculationRun.objects.filter(
            company=company, idempotency_key=idempotency_key
        ).first()
        if existing_idem:
            return existing_idem, f"Đã lưu chứng từ tính khấu hao {existing_idem.number} thành công!"

    # EF02: Validate month & year
    month, year, period_code, period_start, period_end, last_day = _parse_depreciation_period(data)

    # EF04 & EF05 & BR27: Validate voucher_no
    raw_no = data.get("voucher_no") if "voucher_no" in data else data.get("number")
    voucher_no = str(raw_no or "").strip()
    if not voucher_no:
        raise ValidationError({"voucher_no": "Vui lòng nhập số chứng từ."})

    recalculate = bool(data.get("recalculate", False))
    dup_no_qs = models.CalculationRun.objects.filter(company=company, number=voucher_no)
    if recalculate:
        dup_no_qs = dup_no_qs.exclude(period_code=period_code, calculation_type="DEPRECIATION")
    if dup_no_qs.exists():
        raise ValidationError({"voucher_no": "Số chứng từ đã tồn tại. Vui lòng nhập số khác."})

    # EF06: Validate voucher_date & posting_date
    raw_v_date = data.get("voucher_date", period_end)
    raw_p_date = data.get("posting_date", period_end)
    voucher_date = _parse_date(raw_v_date)
    posting_date = _parse_date(raw_p_date)
    if not voucher_date or not posting_date:
        raise ValidationError({"voucher_date": "Vui lòng nhập ngày hợp lệ theo định dạng DD/MM/YYYY."})

    # EF07: Validate posting_date matches depreciation period (month/year) unless cross-period adjustment is explicitly allowed
    allow_cross_period = bool(data.get("allow_cross_period_adjustment", False))
    if not allow_cross_period and (posting_date.year != year or posting_date.month != month):
        raise ValidationError({"posting_date": "Ngày hạch toán không phù hợp với kỳ tính khấu hao."})

    # EF03 & BR28: Check period lock for both period_end and posting_date
    if _closed(company, period_end) or _closed(company, posting_date):
        raise ValidationError({"period": "Kỳ kế toán đã khóa, không thể tính khấu hao tài sản cố định."})

    # EF17 & BR17: Check locked subsequent periods
    if _has_locked_subsequent_period(company, period_end):
        raise ValidationError({"period": "Không thể tính lại khấu hao vì ảnh hưởng đến kỳ kế toán đã khóa."})

    # EF19: Concurrent calculation lock check flag
    if data.get("simulate_concurrent_lock"):
        raise ValidationError({"detail": "Đang có tiến trình tính khấu hao cho kỳ này. Vui lòng thử lại sau."})

    try:
        with transaction.atomic():
            # EF19: Lock existing runs for this company/period with nowait to detect concurrent execution
            try:
                existing_runs = list(
                    models.CalculationRun.objects.select_for_update(nowait=True).filter(
                        company=company,
                        calculation_type="DEPRECIATION",
                        period_code=period_code,
                        status__in=("DRAFT", "CALCULATED", "POSTED"),
                    )
                )
            except OperationalError as exc:
                raise ValidationError({"detail": "Đang có tiến trình tính khấu hao cho kỳ này. Vui lòng thử lại sau."}) from exc

            if existing_runs and not recalculate:
                raise ValidationError({"detail": "Tài sản đã được tính khấu hao trong kỳ đã chọn."})

            # AF14 & BR32: If recalculate=True, cleanly roll back previous runs of the same period before replacing
            if existing_runs and recalculate:
                for old_run in existing_runs:
                    if old_run.status == "POSTED":
                        _revert_posted_depreciation_run_effects(old_run)
                    old_run.lines.all().delete()
                    old_run.delete()

            # Compute authoritative depreciation, allocation, and accounting entries
            calc_result = _compute_depreciation_for_company_period(
                company=company,
                month=month,
                year=year,
                period_code=period_code,
                period_start=period_start,
                period_end=period_end,
                total_days_in_period=last_day,
                recalculate=recalculate,
                explicit_asset_ids=data.get("asset_ids"),
                require_explicit_allocations=bool(data.get("require_explicit_allocations", False)),
            )

            # EF18: Check expected_asset_versions if caller supplied snapshot versions from preview
            expected_versions = data.get("expected_asset_versions")
            if isinstance(expected_versions, dict):
                for item in calc_result["lines"]:
                    a_code = item["asset_code"]
                    a_id = item["asset_id"]
                    exp_v = expected_versions.get(a_id) or expected_versions.get(a_code)
                    if exp_v is not None and int(exp_v) != int(item["asset_version"]):
                        raise ValidationError({"detail": "Dữ liệu tài sản đã thay đổi. Vui lòng thực hiện tính khấu hao lại."})

            # EF11 & EF15 & BR26: Validate custom overrides if client supplied custom line/allocation/accounting totals
            if "custom_lines" in data and isinstance(data.get("custom_lines"), list):
                for c_line in data["custom_lines"]:
                    c_amt = _parse_decimal(c_line.get("amount"), default=None)
                    matched = next(
                        (
                            x for x in calc_result["lines"]
                            if x["asset_code"] == c_line.get("asset_code") or x["asset_id"] == str(c_line.get("asset_id"))
                        ),
                        None,
                    )
                    if matched:
                        rem_allowed = matched["depreciable_amount"] - matched["opening_accumulated_depreciation"]
                        if c_amt is None or c_amt < 0 or c_amt > rem_allowed:
                            raise ValidationError({"amount": "Giá trị khấu hao vượt mức được phép của tài sản."})

            for total_override_key in ("total_allocation_amount", "total_accounting_amount"):
                if total_override_key in data and data.get(total_override_key) not in (None, ""):
                    given_tot = _parse_decimal(data.get(total_override_key), default=None)
                    if given_tot is None or abs(given_tot - calc_result["total_amount"]) > Decimal("1"):
                        raise ValidationError({"detail": "Số tiền khấu hao, phân bổ và hạch toán không khớp."})

            # Step 23 & EF15 & BR26: Cross-check internal totals (Depreciation == Allocation == Accounting)
            alloc_sum = sum(Decimal(str(a["allocated_amount"])) for a in calc_result["allocations"])
            acct_sum = sum(Decimal(str(e["amount"])) for e in calc_result["accounting_entries"])
            if alloc_sum != calc_result["total_amount"] or acct_sum != calc_result["total_amount"]:
                raise ValidationError({"detail": "Số tiền khấu hao, phân bổ và hạch toán không khớp."})

            # Ensure AssetPeriod is open/created for this period
            models.AssetPeriod.objects.get_or_create(
                company=company,
                code=period_code,
                defaults={"start_date": period_start, "end_date": period_end, "status": "OPEN"},
            )

            user_actor = actor(request)
            description = str(data.get("description") or data.get("reason") or f"Khấu hao TSCĐ tháng {month} năm {year}").strip()
            reference = str(data.get("reference") or "").strip()
            attachments = data.get("attachments") if isinstance(data.get("attachments"), list) else []

            run = models.CalculationRun.objects.create(
                company=company,
                number=voucher_no,
                calculation_type="DEPRECIATION",
                period_code=period_code,
                period_start=period_start,
                period_end=period_end,
                period_month=month,
                period_year=year,
                voucher_date=voucher_date,
                posting_date=posting_date,
                description=description,
                reference=reference,
                status="CALCULATED",
                total_amount=calc_result["total_amount"],
                total_deductible_amount=calc_result["total_deductible_amount"],
                total_non_deductible_amount=calc_result["total_non_deductible_amount"],
                allocations_snapshot=calc_result["allocations"],
                accounting_entries=calc_result["accounting_entries"],
                attachments=attachments,
                idempotency_key=idempotency_key,
                created_by=user_actor,
            )

            for item in calc_result["lines"]:
                models.CalculationLine.objects.create(
                    run=run,
                    asset=item["asset"],
                    opening_value=item["opening_value"],
                    amount=item["amount"],
                    closing_value=item["closing_value"],
                    original_cost=item["original_cost"],
                    depreciable_amount=item["depreciable_amount"],
                    opening_accumulated_depreciation=item["opening_accumulated_depreciation"],
                    closing_accumulated_depreciation=item["closing_accumulated_depreciation"],
                    deductible_amount=item["deductible_amount"],
                    non_deductible_amount=item["non_deductible_amount"],
                    eligible_days=item["eligible_days"],
                    total_days_in_period=item["total_days_in_period"],
                    department_name=item["department_name"],
                    category_name=item["category_name"],
                    allocations=item["allocations"],
                    accounting_lines=item["accounting_lines"],
                    asset_version=item["asset_version"],
                )

            audit(
                request,
                run,
                "CREATE_DEPRECIATION",
                before={},
                after={
                    "number": run.number,
                    "period_code": run.period_code,
                    "total_amount": str(run.total_amount),
                    "asset_codes": [item["asset_code"] for item in calc_result["lines"]],
                    "status": run.status,
                },
                reason=description,
            )

            # Step 25–26 & AF20 & BR16 & BR29 & BR30:
            # If post_now=True, post synchronously and update accumulated_depreciation & GL;
            # If post_now=False (AF20), leave in CALCULATED ("Chưa ghi sổ") without altering asset balances yet.
            if post_now:
                run = post_depreciation_run_uc03(run, request, from_save=True)

            return run, f"Đã lưu chứng từ tính khấu hao {run.number} thành công!"
    except DatabaseError as exc:
        # EF20
        raise ValidationError({"detail": "Tính khấu hao tài sản cố định thất bại. Vui lòng thử lại."}) from exc


VALID_DEPR_DEBIT_PREFIXES = ("621", "622", "623", "627", "641", "642", "154", "241", "811")


def _ensure_gl_account_for_code(company, code, is_debit=True):
    """
    Finds or creates a postable Account in general_ledger for `code` (if valid prefix)
    so that GL JournalLines can always be persisted when posting a depreciation voucher.
    """
    from general_ledger.models import Account, AccountClass, ChartOfAccounts

    code_str = str(code or "").strip()
    if not code_str:
        return None
    acc = Account.objects.filter(company=company, code=code_str).first()
    if acc:
        return acc

    chart = ChartOfAccounts.objects.filter(company=company, is_default=True).first() or ChartOfAccounts.objects.filter(company=company).first()
    if not chart:
        chart = ChartOfAccounts.objects.create(
            company=company,
            code="TT99",
            name="Hệ thống tài khoản",
            effective_from=timezone.localdate(),
            is_default=True,
        )
    first_char = code_str[0]
    acc_class, _ = AccountClass.objects.get_or_create(
        company=company,
        code=first_char,
        defaults={
            "name": "Tài khoản chi phí" if is_debit else "Tài khoản hao mòn",
            "normal_balance": "DEBIT" if is_debit else "CREDIT",
        },
    )
    return Account.objects.create(
        company=company,
        chart_of_accounts=chart,
        account_class=acc_class,
        code=code_str,
        name=f"Tài khoản {code_str}",
        account_type="EXPENSE" if is_debit else "ASSET",
        normal_balance="DEBIT" if is_debit else "CREDIT",
        is_postable=True,
        status="ACTIVE",
    )


def post_depreciation_run_uc03(run, request, from_save=False):
    """
    UC-FA-03 Step 26 & UC-FA-04 (Ghi nhận khấu hao tài sản):
    Validates and posts a CALCULATED ("Chưa ghi sổ") depreciation voucher:
    - Enforces all UC-FA-04 business rules (BR01–BR30) & exception flows (EF01–EF22)
    - Supports editing allocation / accounting accounts before posting (AF04)
    - Supports consolidating accounting lines with identical accounts & cost objects (AF05, BR16)
    - Updates each asset's accumulated_depreciation and periods_processed (preserving original_cost per BR19)
    - Creates AssetTransaction and General Ledger JournalEntry + JournalLine records atomically (BR23)
    """
    from general_ledger.models import Account

    data = request.data if hasattr(request, "data") and isinstance(request.data, dict) else {}

    if not from_save:
        _check_depreciation_permission(request, run.company, "FA.CALCULATION.POST", uc04=True)
        if data.get("simulate_concurrent_lock"):
            raise ValidationError({"detail": "Chứng từ đang được xử lý. Vui lòng thử lại sau."})

    try:
        with transaction.atomic():
            try:
                run = models.CalculationRun.objects.select_for_update(nowait=not from_save).get(pk=run.pk)
            except OperationalError as exc:
                raise ValidationError({"detail": "Chứng từ đang được xử lý. Vui lòng thử lại sau."}) from exc

            req_idem = str(data.get("idempotency_key") or "").strip() or None

            # EF03 & AF16: Already posted check vs idempotent retry
            if run.status == "POSTED":
                if from_save or (req_idem and run.idempotency_key == req_idem) or bool(data.get("is_retry", False)):
                    return run
                raise ValidationError({"status": "Chứng từ khấu hao đã được ghi sổ."})

            if run.status != "CALCULATED":
                raise ValidationError({"status": "Chứng từ khấu hao không ở trạng thái cho phép ghi sổ."})

            if req_idem and not run.idempotency_key:
                run.idempotency_key = req_idem

            if not from_save:
                # Step 7 & EF04 & BR02: Validate voucher_no
                raw_no = (
                    data.get("voucher_no")
                    if "voucher_no" in data
                    else (data.get("number") if "number" in data else run.number)
                )
                voucher_no = str(raw_no or "").strip()
                if (
                    not voucher_no
                    or len(voucher_no) > 80
                    or models.CalculationRun.objects.filter(company=run.company, number=voucher_no)
                    .exclude(pk=run.pk)
                    .exists()
                ):
                    raise ValidationError({"voucher_no": "Số chứng từ khấu hao không hợp lệ."})
                run.number = voucher_no

                # Step 10 & EF07 & BR04: Validate depreciation period (month/year)
                raw_m = data.get("month") if "month" in data else run.period_month
                raw_y = data.get("year") if "year" in data else run.period_year
                if isinstance(raw_m, bool) or isinstance(raw_y, bool) or raw_m in (None, "") or raw_y in (None, ""):
                    raise ValidationError({"period": "Chưa xác định được kỳ khấu hao của chứng từ."})
                try:
                    m = int(str(raw_m).strip())
                    y = int(str(raw_y).strip())
                except (TypeError, ValueError):
                    raise ValidationError({"period": "Chưa xác định được kỳ khấu hao của chứng từ."})
                if m < 1 or m > 12 or y < 1900 or y > 2100:
                    raise ValidationError({"period": "Chưa xác định được kỳ khấu hao của chứng từ."})
                run.period_month = m
                run.period_year = y
                run.period_code = f"{y:04d}-{m:02d}"

                # Step 8–9 & EF05 & AF12 & BR03: Validate voucher_date & posting_date
                if "voucher_date" in data:
                    v_date = _parse_date(data.get("voucher_date"))
                    if not v_date:
                        raise ValidationError({"voucher_date": "Ngày chứng từ không hợp lệ. Vui lòng kiểm tra lại."})
                    run.voucher_date = v_date

                raw_p_date = data.get("posting_date") if "posting_date" in data else run.posting_date
                p_date = _parse_date(raw_p_date)
                if not p_date:
                    raise ValidationError({"posting_date": "Ngày hạch toán không hợp lệ. Vui lòng kiểm tra lại."})

                allow_cross_period = bool(data.get("allow_cross_period_adjustment", False))
                if not allow_cross_period and (p_date.year != run.period_year or p_date.month != run.period_month):
                    raise ValidationError({"posting_date": "Ngày hạch toán không hợp lệ. Vui lòng kiểm tra lại."})
                run.posting_date = p_date

                # Step 11 & AF11: Optional description, reference, attachments updates
                if "description" in data or "reason" in data:
                    run.description = str(data.get("description") or data.get("reason") or run.description).strip()
                if "reference" in data:
                    run.reference = str(data.get("reference") or "").strip()
                if "attachments" in data and isinstance(data.get("attachments"), list):
                    run.attachments = data["attachments"]

            # EF06 & BR05 & BR18: Period lock check
            if (
                _closed(run.company, run.period_end)
                or (run.posting_date and _closed(run.company, run.posting_date))
                or _has_locked_subsequent_period(run.company, run.period_end)
            ):
                if from_save:
                    raise ValidationError({"period": "Kỳ kế toán đã khóa, không thể tính khấu hao tài sản cố định."})
                raise ValidationError({"period": "Kỳ kế toán đã khóa, không thể ghi sổ chứng từ khấu hao."})

            # Step 12–13 & EF10 & BR01 & BR06: Check depreciation lines exist and total_amount > 0
            lines = list(run.lines.select_related("asset", "asset__accumulated_account", "asset__category__accumulated_account").all())
            if (
                ("lines" in data and isinstance(data.get("lines"), list) and len(data["lines"]) == 0)
                or not lines
                or run.total_amount <= 0
                or all(l.amount <= 0 for l in lines)
            ):
                raise ValidationError({"lines": "Chứng từ chưa có dữ liệu khấu hao để ghi nhận."})

            if not from_save:
                # AF13 & BR04: Check if prior period depreciation voucher for any asset in this voucher is still unposted
                asset_ids_in_run = [l.asset_id for l in lines]
                if (
                    models.CalculationRun.objects.filter(
                        company=run.company,
                        calculation_type="DEPRECIATION",
                        status="CALCULATED",
                        period_end__lt=run.period_start,
                        lines__asset_id__in=asset_ids_in_run,
                    )
                    .exclude(pk=run.pk)
                    .exists()
                    and not bool(data.get("allow_unposted_prior_period", False))
                ):
                    raise ValidationError(
                        {"period": "Khấu hao kỳ trước chưa được ghi sổ. Vui lòng ghi sổ kỳ trước trước khi thực hiện."}
                    )

                # Optional custom line overrides (for EF15 / custom adjustment validation)
                if "custom_lines" in data and isinstance(data.get("custom_lines"), list):
                    for c_line in data["custom_lines"]:
                        c_amt = _parse_decimal(c_line.get("amount"), default=None)
                        for l_obj in lines:
                            if l_obj.asset.code == c_line.get("asset_code") or str(l_obj.asset_id) == str(c_line.get("asset_id")):
                                if c_amt is not None:
                                    l_obj.amount = c_amt

            # Validate each asset in lines (EF14, EF15, EF16, EF17, BR06–BR09, BR20–BR22, BR25)
            expected_versions = data.get("expected_asset_versions") if isinstance(data.get("expected_asset_versions"), dict) else {}
            expected_credit_by_asset = {}
            locked_assets = {}

            for line in lines:
                asset = models.AssetRecord.objects.select_for_update().get(pk=line.asset_id)
                locked_assets[line.asset_id] = asset

                # Determine asset's configured accumulated depreciation account code (e.g. 2141)
                accum_code = ""
                if asset.accumulated_account_id and asset.accumulated_account:
                    accum_code = asset.accumulated_account.code
                elif asset.category_id and asset.category and asset.category.accumulated_account_id:
                    accum_code = asset.category.accumulated_account.code
                if not accum_code and line.accounting_lines:
                    accum_code = str(line.accounting_lines[0].get("credit_account") or "").strip()
                expected_credit_by_asset[asset.code] = accum_code

                if from_save:
                    if asset.status == models.AssetStatus.DISPOSED and asset.disposed_at and asset.disposed_at < run.period_start:
                        raise ValidationError({"detail": "Dữ liệu tài sản đã thay đổi. Vui lòng thực hiện tính khấu hao lại."})
                else:
                    # EF17: Asset disposed/suspended/non-depreciable before posting
                    if (
                        not asset.is_depreciable
                        or asset.status not in (models.AssetStatus.ACTIVE, models.AssetStatus.DISPOSED)
                        or (
                            asset.status == models.AssetStatus.DISPOSED
                            and (not asset.disposed_at or asset.disposed_at < run.period_start or line.eligible_days == line.total_days_in_period)
                        )
                    ):
                        raise ValidationError(
                            {"detail": "Thông tin tài sản không còn phù hợp với kết quả khấu hao. Vui lòng kiểm tra lại."}
                        )

                    # EF16: Asset original_cost, accumulated_depreciation, or version changed since calculation
                    exp_v = expected_versions.get(str(asset.id)) or expected_versions.get(asset.code)
                    if (
                        (line.original_cost and asset.original_cost != line.original_cost)
                        or asset.accumulated_depreciation != line.opening_accumulated_depreciation
                        or (line.asset_version and asset.version != line.asset_version)
                        or (exp_v is not None and int(exp_v) != int(asset.version))
                    ):
                        raise ValidationError(
                            {"detail": "Dữ liệu tài sản đã thay đổi. Vui lòng tính lại khấu hao trước khi ghi sổ."}
                        )

                    # EF14: Asset already has a POSTED depreciation in this period
                    if (
                        models.AssetTransaction.objects.filter(
                            company=run.company,
                            asset=asset,
                            transaction_type="DEPRECIATION",
                            period_code=run.period_code,
                            status="POSTED",
                        ).exists()
                        or models.CalculationRun.objects.filter(
                            company=run.company,
                            calculation_type="DEPRECIATION",
                            period_code=run.period_code,
                            status="POSTED",
                            lines__asset=asset,
                        )
                        .exclude(pk=run.pk)
                        .exists()
                    ):
                        raise ValidationError({"detail": "Tài sản đã được ghi nhận khấu hao trong kỳ này."})

                    # EF15: Depreciation amount exceeds remaining depreciable amount or original cost
                    depr_base = (
                        asset.depreciable_amount
                        if asset.depreciable_amount and asset.depreciable_amount > 0
                        else max(Decimal("0"), asset.original_cost - (asset.salvage_value or Decimal("0")))
                    )
                    rem_allowed = max(Decimal("0"), depr_base - asset.accumulated_depreciation)
                    if line.amount <= 0 or line.amount > rem_allowed or (asset.accumulated_depreciation + line.amount > asset.original_cost):
                        raise ValidationError({"amount": "Giá trị khấu hao vượt mức được phép của tài sản."})

            if not from_save:
                # Step 14–16 & EF11 & EF13 & AF04 & BR10–BR12: Validate Tab Phân bổ (Allocations)
                if "total_allocation_amount" in data and data.get("total_allocation_amount") not in (None, ""):
                    given_alloc_tot = _parse_decimal(data.get("total_allocation_amount"), default=None)
                    if given_alloc_tot is None or given_alloc_tot != run.total_amount:
                        raise ValidationError({"allocations": "Tổng tiền phân bổ không khớp với số khấu hao đã tính."})

                allocations = data.get("allocations") if "allocations" in data else run.allocations_snapshot
                if not isinstance(allocations, list) or len(allocations) == 0:
                    raise ValidationError({"allocations": "Chưa thiết lập đầy đủ thông tin phân bổ khấu hao."})

                for alloc in allocations:
                    if not isinstance(alloc, dict):
                        raise ValidationError({"allocations": "Chưa thiết lập đầy đủ thông tin phân bổ khấu hao."})
                    dept_or_obj = str(
                        alloc.get("department_name")
                        or alloc.get("object_code")
                        or alloc.get("cost_center_name")
                        or alloc.get("project_code")
                        or ""
                    ).strip()
                    exp_acc = str(
                        alloc.get("expense_account")
                        or alloc.get("expense_account_code")
                        or alloc.get("debit_account")
                        or ""
                    ).strip()
                    rate = _parse_decimal(alloc.get("rate"), default=None)
                    alloc_amt = _parse_decimal(alloc.get("allocated_amount"), default=None)
                    if (
                        not dept_or_obj
                        or not exp_acc
                        or rate is None
                        or rate <= 0
                        or rate > Decimal("100")
                        or alloc_amt is None
                        or alloc_amt < 0
                    ):
                        raise ValidationError({"allocations": "Chưa thiết lập đầy đủ thông tin phân bổ khấu hao."})

                for line in lines:
                    asset_allocs = [
                        a
                        for a in allocations
                        if a.get("asset_code") == line.asset.code or str(a.get("asset_id")) == str(line.asset_id)
                    ]
                    if not asset_allocs:
                        raise ValidationError({"allocations": "Chưa thiết lập đầy đủ thông tin phân bổ khấu hao."})
                    rate_sum = sum(_parse_decimal(a.get("rate"), default=Decimal("0")) for a in asset_allocs)
                    if abs(rate_sum - Decimal("100")) > Decimal("0.01"):
                        raise ValidationError({"allocations": "Chưa thiết lập đầy đủ thông tin phân bổ khấu hao."})
                    amt_sum = sum(_parse_decimal(a.get("allocated_amount"), default=Decimal("0")) for a in asset_allocs)
                    if amt_sum != line.amount:
                        raise ValidationError({"allocations": "Tổng tiền phân bổ không khớp với số khấu hao đã tính."})

                total_alloc_sum = sum(_parse_decimal(a.get("allocated_amount"), default=Decimal("0")) for a in allocations)
                if total_alloc_sum != run.total_amount:
                    raise ValidationError({"allocations": "Tổng tiền phân bổ không khớp với số khấu hao đã tính."})

                # AF04: If caller updated allocations and did not explicitly pass accounting_entries, rebuild accounting_entries from allocations
                if "allocations" in data and "accounting_entries" not in data:
                    rebuilt_entries = []
                    for alloc in allocations:
                        a_code = str(alloc.get("asset_code") or "").strip()
                        a_name = str(alloc.get("asset_name") or "").strip()
                        c_acc = str(
                            alloc.get("credit_account")
                            or alloc.get("credit_account_code")
                            or expected_credit_by_asset.get(a_code)
                            or "2141"
                        ).strip()
                        d_acc = str(
                            alloc.get("expense_account")
                            or alloc.get("expense_account_code")
                            or alloc.get("debit_account")
                            or ""
                        ).strip()
                        amt = _parse_decimal(alloc.get("allocated_amount"), default=Decimal("0"))
                        ded_amt = _parse_decimal(alloc.get("deductible_amount"), default=amt)
                        nonded_amt = _parse_decimal(alloc.get("non_deductible_amount"), default=Decimal("0"))
                        rebuilt_entries.append(
                            {
                                "asset_id": alloc.get("asset_id"),
                                "asset_code": a_code,
                                "asset_name": a_name,
                                "description": f"Khấu hao TSCĐ {a_code} - {run.period_code}".strip(),
                                "debit_account": d_acc,
                                "debit_account_code": d_acc,
                                "credit_account": c_acc,
                                "credit_account_code": c_acc,
                                "amount": str(amt),
                                "deductible_amount": str(ded_amt),
                                "non_deductible_amount": str(nonded_amt),
                                "department_name": str(alloc.get("department_name") or "").strip(),
                                "cost_item": str(alloc.get("cost_item") or alloc.get("expense_item") or "").strip(),
                            }
                        )
                    run.accounting_entries = rebuilt_entries

                run.allocations_snapshot = allocations

                # Step 17–19 & EF08 & EF09 & EF12 & AF05 & BR13–BR17: Validate Tab Hạch toán (Accounting Entries)
                for key_override in ("total_accounting_amount", "total_debit", "total_credit"):
                    if key_override in data and data.get(key_override) not in (None, ""):
                        given_acct_tot = _parse_decimal(data.get(key_override), default=None)
                        if given_acct_tot is None or given_acct_tot != run.total_amount:
                            raise ValidationError(
                                {"accounting_entries": "Số tiền hạch toán không khớp với số khấu hao của chứng từ."}
                            )

                accounting_entries = data.get("accounting_entries") if "accounting_entries" in data else run.accounting_entries
                if not isinstance(accounting_entries, list) or len(accounting_entries) == 0:
                    raise ValidationError(
                        {"accounting_entries": "Số tiền hạch toán không khớp với số khấu hao của chứng từ."}
                    )

                for ae in accounting_entries:
                    if not isinstance(ae, dict):
                        raise ValidationError(
                            {"accounting_entries": "Số tiền hạch toán không khớp với số khấu hao của chứng từ."}
                        )
                    debit_code = str(ae.get("debit_account") or ae.get("debit_account_code") or "").strip()
                    credit_code = str(ae.get("credit_account") or ae.get("credit_account_code") or "").strip()

                    # EF08: Validate Debit Account
                    if not debit_code or not debit_code.startswith(VALID_DEPR_DEBIT_PREFIXES):
                        raise ValidationError({"debit_account": "Tài khoản ghi Nợ không hợp lệ."})
                    existing_debit = Account.objects.filter(company=run.company, code=debit_code).first()
                    if existing_debit and (
                        existing_debit.status != "ACTIVE"
                        or not existing_debit.is_postable
                        or existing_debit.children.filter(status="ACTIVE").exists()
                    ):
                        raise ValidationError({"debit_account": "Tài khoản ghi Nợ không hợp lệ."})

                    # EF09: Validate Credit Account (Accumulated Depreciation 214x)
                    if not credit_code or not credit_code.startswith("214"):
                        raise ValidationError({"credit_account": "Tài khoản hao mòn TSCĐ không hợp lệ."})
                    existing_credit = Account.objects.filter(company=run.company, code=credit_code).first()
                    if existing_credit and (
                        existing_credit.status != "ACTIVE"
                        or not existing_credit.is_postable
                        or existing_credit.children.filter(status="ACTIVE").exists()
                    ):
                        raise ValidationError({"credit_account": "Tài khoản hao mòn TSCĐ không hợp lệ."})
                    ae_asset_code = str(ae.get("asset_code") or "").strip()
                    if (
                        ae_asset_code
                        and ae_asset_code in expected_credit_by_asset
                        and expected_credit_by_asset[ae_asset_code]
                        and credit_code != expected_credit_by_asset[ae_asset_code]
                    ):
                        raise ValidationError({"credit_account": "Tài khoản hao mòn TSCĐ không hợp lệ."})

                    # EF12: Validate accounting entry amount & Debit == Credit
                    amt = _parse_decimal(ae.get("amount"), default=None)
                    d_amt = _parse_decimal(ae.get("debit_amount"), default=amt)
                    c_amt = _parse_decimal(ae.get("credit_amount"), default=amt)
                    if amt is None or amt <= 0 or d_amt != c_amt or d_amt != amt:
                        raise ValidationError(
                            {"accounting_entries": "Số tiền hạch toán không khớp với số khấu hao của chứng từ."}
                        )

                acct_sum = sum(_parse_decimal(ae.get("amount"), default=Decimal("0")) for ae in accounting_entries)
                if acct_sum != run.total_amount:
                    raise ValidationError(
                        {"accounting_entries": "Số tiền hạch toán không khớp với số khấu hao của chứng từ."}
                    )

                # AF05 & BR16: Optional consolidation of accounting entries with identical (debit, credit, department, cost_item)
                if bool(data.get("consolidate_accounting_entries", False)):
                    grouped = {}
                    for ae in accounting_entries:
                        g_key = (
                            str(ae.get("debit_account") or "").strip(),
                            str(ae.get("credit_account") or "").strip(),
                            str(ae.get("department_name") or "").strip(),
                            str(ae.get("cost_item") or "").strip(),
                        )
                        amt = _parse_decimal(ae.get("amount"), default=Decimal("0"))
                        ded = _parse_decimal(ae.get("deductible_amount"), default=amt)
                        nonded = _parse_decimal(ae.get("non_deductible_amount"), default=Decimal("0"))
                        src_code = str(ae.get("asset_code") or "").strip()
                        if g_key not in grouped:
                            grouped[g_key] = {
                                "description": run.description or f"Khấu hao TSCĐ kỳ {run.period_code}",
                                "debit_account": g_key[0],
                                "credit_account": g_key[1],
                                "department_name": g_key[2],
                                "cost_item": g_key[3],
                                "amount": amt,
                                "deductible_amount": ded,
                                "non_deductible_amount": nonded,
                                "source_asset_codes": [src_code] if src_code else [],
                            }
                        else:
                            grouped[g_key]["amount"] += amt
                            grouped[g_key]["deductible_amount"] += ded
                            grouped[g_key]["non_deductible_amount"] += nonded
                            if src_code and src_code not in grouped[g_key]["source_asset_codes"]:
                                grouped[g_key]["source_asset_codes"].append(src_code)
                    accounting_entries = [
                        {
                            **val,
                            "amount": str(val["amount"]),
                            "deductible_amount": str(val["deductible_amount"]),
                            "non_deductible_amount": str(val["non_deductible_amount"]),
                        }
                        for val in grouped.values()
                    ]

                run.accounting_entries = accounting_entries

                # EF18 & EF19: Simulated failure hooks to verify atomic rollback (BR23)
                if data.get("simulate_gl_error"):
                    raise ValidationError({"detail": "Không thể hạch toán chứng từ khấu hao. Vui lòng thử lại."})
                if data.get("simulate_asset_update_error"):
                    raise ValidationError({"detail": "Ghi sổ chứng từ khấu hao thất bại. Vui lòng thử lại."})

            user_actor = actor(request)
            now = timezone.now()
            tx_date = run.posting_date or run.period_end

            for index, line in enumerate(lines, 1):
                asset = locked_assets[line.asset_id]
                tx = models.AssetTransaction.objects.create(
                    company=run.company,
                    asset=asset,
                    number=f"{run.number}-{index:04d}",
                    transaction_type=run.calculation_type,
                    transaction_date=tx_date,
                    amount=line.amount,
                    period_code=run.period_code,
                    reason=run.description or f"Khấu hao TSCĐ kỳ {run.period_code}",
                    source_module="FA_RUN",
                    source_reference=str(run.id),
                    idempotency_key=f"FA-RUN:{run.id}:{line.asset_id}",
                    status="APPROVED",
                    created_by=user_actor,
                    approved_at=now,
                )
                post_transaction(tx, request)
                tx.gl_status = "POSTED"
                tx.gl_reference = run.number
                tx.save(update_fields=("gl_status", "gl_reference", "updated_at"))
                line.transaction = tx
                line.save(update_fields=("transaction",))

            # Create General Ledger JournalEntry and JournalLines
            gl_entry_id = _try_create_gl_journal_entry_for_depreciation(run, user_actor, strict=not from_save)
            run.status = "POSTED"
            run.posted_by = user_actor
            run.posted_at = now
            if gl_entry_id:
                run.gl_entry_id = gl_entry_id
            run.save(
                update_fields=(
                    "number",
                    "period_month",
                    "period_year",
                    "period_code",
                    "voucher_date",
                    "posting_date",
                    "description",
                    "reference",
                    "attachments",
                    "allocations_snapshot",
                    "accounting_entries",
                    "idempotency_key",
                    "status",
                    "posted_by",
                    "posted_at",
                    "gl_entry_id",
                    "updated_at",
                )
            )

            audit(
                request,
                run,
                "POST_DEPRECIATION",
                before={"status": "CALCULATED"},
                after={
                    "status": "POSTED",
                    "number": run.number,
                    "period_code": run.period_code,
                    "total_amount": str(run.total_amount),
                    "gl_entry_id": str(gl_entry_id) if gl_entry_id else "",
                },
                reason=run.description,
            )
            return run
    except DatabaseError as exc:
        if from_save:
            raise ValidationError({"detail": "Tính khấu hao tài sản cố định thất bại. Vui lòng thử lại."}) from exc
        raise ValidationError({"detail": "Ghi sổ chứng từ khấu hao thất bại. Vui lòng thử lại."}) from exc


def _try_create_gl_journal_entry_for_depreciation(run, user_actor, strict=False):
    """Creates a POSTED JournalEntry and balanced JournalLines in general_ledger for a depreciation voucher."""
    try:
        import calendar
        from general_ledger.models import AccountingPeriod, JournalEntry, JournalLine
        from master_data.models import Currency

        if not run.accounting_entries:
            return None

        tx_date = run.posting_date or run.period_end
        gl_period = AccountingPeriod.objects.filter(
            company=run.company,
            start_date__lte=tx_date,
            end_date__gte=tx_date,
        ).first()
        if not gl_period:
            last_d = calendar.monthrange(tx_date.year, tx_date.month)[1]
            gl_period, _ = AccountingPeriod.objects.get_or_create(
                company=run.company,
                fiscal_year=tx_date.year,
                period_number=tx_date.month,
                defaults={
                    "code": f"{tx_date.year:04d}-{tx_date.month:02d}",
                    "start_date": date_cls(tx_date.year, tx_date.month, 1),
                    "end_date": date_cls(tx_date.year, tx_date.month, last_d),
                    "status": "OPEN",
                },
            )
        if gl_period.status != "OPEN":
            if strict:
                raise ValidationError({"period": "Kỳ kế toán đã khóa, không thể ghi sổ chứng từ khấu hao."})
            return None

        vnd_currency = getattr(run.company, "accounting_currency", None) or Currency.objects.filter(code="VND").first()
        if not vnd_currency:
            vnd_currency = Currency.objects.create(code="VND", name="Đồng Việt Nam", decimal_places=0)

        branch = run.company.branches.first()
        gl_number = f"GL-{run.number}"
        if JournalEntry.objects.filter(company=run.company, number=gl_number).exists():
            gl_number = f"GL-{run.number}-{str(run.id)[:6]}"

        entry = JournalEntry.objects.create(
            company=run.company,
            branch=branch,
            period=gl_period,
            number=gl_number,
            entry_type="SUBLEDGER",
            document_date=run.voucher_date or tx_date,
            posting_date=tx_date,
            description=run.description or f"Hạch toán khấu hao TSCĐ {run.period_code}",
            source_module="FA",
            source_event_id=f"FA_DEPR:{run.id}",
            source_entity_type="CalculationRun",
            source_entity_id=run.id,
            status="POSTED",
            total_debit=run.total_amount,
            total_credit=run.total_amount,
            created_by=user_actor,
            posted_by=user_actor,
            posted_at=timezone.now(),
        )
        line_no = 1
        for ae in run.accounting_entries:
            amt = _parse_decimal(ae.get("amount"), default=Decimal("0"))
            if not amt or amt <= 0:
                continue
            debit_code = str(ae.get("debit_account") or "").strip()
            credit_code = str(ae.get("credit_account") or "").strip()
            debit_acc = _ensure_gl_account_for_code(run.company, debit_code, is_debit=True)
            credit_acc = _ensure_gl_account_for_code(run.company, credit_code, is_debit=False)
            if not debit_acc or not credit_acc:
                if strict:
                    raise ValidationError({"detail": "Không thể hạch toán chứng từ khấu hao. Vui lòng thử lại."})
                continue
            ae["debit_account_id"] = str(debit_acc.id)
            ae["credit_account_id"] = str(credit_acc.id)
            dims = {
                "department_name": ae.get("department_name") or "",
                "cost_item": ae.get("cost_item") or "",
                "asset_code": ae.get("asset_code") or "",
                "source_asset_codes": ae.get("source_asset_codes") or ([ae["asset_code"]] if ae.get("asset_code") else []),
                "deductible_amount": str(ae.get("deductible_amount") or amt),
                "non_deductible_amount": str(ae.get("non_deductible_amount") or "0"),
            }
            JournalLine.objects.create(
                entry=entry,
                line_no=line_no,
                account=debit_acc,
                description=ae.get("description") or run.description,
                debit=amt,
                credit=Decimal("0"),
                currency=vnd_currency,
                foreign_amount=amt,
                exchange_rate=Decimal("1"),
                dimensions=dims,
            )
            line_no += 1
            JournalLine.objects.create(
                entry=entry,
                line_no=line_no,
                account=credit_acc,
                description=ae.get("description") or run.description,
                debit=Decimal("0"),
                credit=amt,
                currency=vnd_currency,
                foreign_amount=amt,
                exchange_rate=Decimal("1"),
                dimensions=dims,
            )
            line_no += 1
        return entry.id
    except ValidationError:
        raise
    except Exception as exc:
        if strict:
            raise ValidationError({"detail": "Không thể hạch toán chứng từ khấu hao. Vui lòng thử lại."}) from exc
        return None


def _revert_posted_depreciation_run_effects(run):
    """Rolls back accumulated_depreciation, periods_processed, and transactions of a POSTED run."""
    for line in run.lines.select_related("asset", "transaction").all():
        asset = models.AssetRecord.objects.select_for_update().get(pk=line.asset_id)
        if run.calculation_type == "DEPRECIATION":
            asset.accumulated_depreciation = max(Decimal("0"), asset.accumulated_depreciation - line.amount)
        else:
            asset.allocated_value = max(Decimal("0"), asset.allocated_value - line.amount)
        asset.periods_processed = max(0, asset.periods_processed - 1)
        asset.save(update_fields=("accumulated_depreciation", "allocated_value", "periods_processed", "updated_at"))
        tx = line.transaction
        if tx:
            line.transaction = None
            line.save(update_fields=("transaction",))
            tx.delete()
    if run.gl_entry_id:
        try:
            from general_ledger.models import JournalEntry
            JournalEntry.objects.filter(pk=run.gl_entry_id).delete()
        except Exception:
            pass
        run.gl_entry_id = None


@transaction.atomic
def unpost_depreciation_run(run, request):
    """UC-FA-03 AF14 & BR34: Unpost (Bỏ ghi sổ) a POSTED depreciation run."""
    _check_depreciation_permission(request, run.company, "FA.CALCULATION.POST")
    run = models.CalculationRun.objects.select_for_update().get(pk=run.pk)
    if run.status != "POSTED":
        raise ValidationError({"status": "Chỉ chứng từ đã ghi sổ mới được bỏ ghi sổ."})
    if _closed(run.company, run.period_end) or (run.posting_date and _closed(run.company, run.posting_date)):
        raise ValidationError({"period": "Kỳ kế toán đã khóa, không thể tính khấu hao tài sản cố định."})
    if _has_locked_subsequent_period(run.company, run.period_end):
        raise ValidationError({"period": "Không thể tính lại khấu hao vì ảnh hưởng đến kỳ kế toán đã khóa."})

    _revert_posted_depreciation_run_effects(run)
    run.status = "CALCULATED"
    run.posted_by = None
    run.posted_at = None
    run.save(update_fields=("status", "posted_by", "posted_at", "gl_entry_id", "updated_at"))
    audit(
        request,
        run,
        "UNPOST_DEPRECIATION",
        before={"status": "POSTED"},
        after={"status": "CALCULATED", "number": run.number, "period_code": run.period_code},
        reason=str(request.data.get("reason") or "Bỏ ghi sổ chứng từ tính khấu hao"),
    )
    return run


@transaction.atomic
def cancel_depreciation_run(run, request):
    """UC-FA-03 Section 5 & BR34: Cancel an unposted depreciation run."""
    _check_depreciation_permission(request, run.company, "FA.CALCULATION.EDIT")
    run = models.CalculationRun.objects.select_for_update().get(pk=run.pk)
    if run.status == "POSTED":
        raise ValidationError({"status": "Vui lòng bỏ ghi sổ chứng từ trước khi hủy."})
    old_status = run.status
    run.status = "CANCELLED"
    run.save(update_fields=("status", "updated_at"))
    audit(
        request,
        run,
        "CANCEL_DEPRECIATION",
        before={"status": old_status},
        after={"status": "CANCELLED", "number": run.number, "period_code": run.period_code},
        reason=str(request.data.get("reason") or "Hủy chứng từ tính khấu hao"),
    )
    return run


# ==============================================================================
# UC-FA-05 – Điều chuyển tài sản cố định (Fixed Asset Transfer)
# ==============================================================================

def _check_transfer_permission(request, company, permission_code="FA.TRANSACTION.TRANSFER"):
    """EF01 & BR01: Check permission for fixed asset transfer."""
    if not request or not getattr(request, "user", None) or not request.user.is_authenticated:
        raise PermissionDenied("Bạn không có quyền điều chuyển tài sản cố định.")
    if request.user.is_superuser:
        return
    if not hasattr(request.user, "iam_account"):
        raise PermissionDenied("Bạn không có quyền điều chuyển tài sản cố định.")
    from iam.permissions import has_effective_permission
    if not has_effective_permission(request.user.iam_account, company, permission_code):
        raise PermissionDenied("Bạn không có quyền điều chuyển tài sản cố định.")


def get_next_transfer_voucher_no(company, transfer_date=None, year_based=False, prefix="ĐCTS"):
    """
    UC-FA-05 Step 4, AF04, BR06-BR08, Section 5.1:
    Proposes the next sequential transfer voucher number for the company:
    - Default: ĐCTS00001 -> ĐCTS00002 -> ...
    - Year-based (AF04): ĐCTS-{YYYY}-00001 -> ĐCTS-{YYYY}-00002 -> ...
    """
    import re
    from django.db.models import Q

    tx_date = _parse_date(transfer_date) or timezone.localdate()
    clean_prefix = str(prefix or "ĐCTS").strip() or "ĐCTS"
    if year_based:
        full_prefix = f"{clean_prefix}-{tx_date.year:04d}-"
        pattern = re.compile(rf"^{re.escape(full_prefix)}(\d+)(?:-\d+)?$", re.IGNORECASE)
    else:
        full_prefix = clean_prefix
        pattern = re.compile(rf"^{re.escape(full_prefix)}(\d+)(?:-\d+)?$", re.IGNORECASE)

    existing_txs = models.AssetTransaction.objects.filter(
        company=company,
        transaction_type="TRANSFER",
    ).filter(
        Q(number__istartswith=full_prefix) | Q(source_reference__istartswith=full_prefix)
    ).values_list("number", "source_reference")

    max_seq = 0
    for num_val, ref_val in existing_txs:
        for candidate in (ref_val, num_val):
            if not candidate:
                continue
            m = pattern.match(str(candidate).strip())
            if m:
                try:
                    seq = int(m.group(1))
                    if seq > max_seq:
                        max_seq = seq
                except ValueError:
                    pass
    return f"{full_prefix}{max_seq + 1:05d}"


def _serialize_transfer_voucher_group(company, voucher_no, transactions_qs=None):
    """Builds a unified UC-FA-05 transfer voucher response from its AssetTransaction lines."""
    from . import serializers

    if transactions_qs is None:
        from django.db.models import Q
        transactions_qs = (
            models.AssetTransaction.objects.filter(
                company=company,
                transaction_type="TRANSFER",
            )
            .filter(Q(source_reference=voucher_no) | Q(number=voucher_no))
            .select_related("asset", "asset__department", "target_department", "target_branch", "created_by")
            .order_by("created_at", "number")
        )
    tx_list = list(transactions_qs)
    if not tx_list:
        return {}
    first_tx = tx_list[0]
    after_snap = first_tx.after_snapshot if isinstance(first_tx.after_snapshot, dict) else {}
    serialized_lines = serializers.TransactionSerializer(tx_list, many=True).data
    detail_rows = []
    for idx, tx_obj in enumerate(tx_list, start=1):
        b_snap = tx_obj.before_snapshot if isinstance(tx_obj.before_snapshot, dict) else {}
        a_snap = tx_obj.after_snapshot if isinstance(tx_obj.after_snapshot, dict) else {}
        detail_rows.append({
            "stt": idx,
            "transaction_id": str(tx_obj.id),
            "asset_id": str(tx_obj.asset_id),
            "asset_code": tx_obj.asset.code if tx_obj.asset else "",
            "asset_name": tx_obj.asset.name if tx_obj.asset else "",
            "from_department_id": str(b_snap.get("from_department_id") or b_snap.get("department") or ""),
            "from_department_code": str(b_snap.get("from_department_code") or ""),
            "from_department_name": str(b_snap.get("from_department_name") or ""),
            "to_department_id": str(tx_obj.target_department_id or a_snap.get("to_department_id") or ""),
            "to_department_code": str(
                tx_obj.target_department.code if tx_obj.target_department else (a_snap.get("to_department_code") or "")
            ),
            "to_department_name": str(
                tx_obj.target_department.name if tx_obj.target_department else (a_snap.get("to_department_name") or "")
            ),
            "sales_contract": str(a_snap.get("sales_contract") or ""),
            "sales_order": str(a_snap.get("sales_order") or ""),
            "project": str(a_snap.get("project") or ""),
            "expense_item": str(a_snap.get("expense_item") or ""),
            "cost_object": str(a_snap.get("cost_object") or ""),
            "original_cost": str(tx_obj.asset.original_cost if tx_obj.asset else "0.00"),
            "accumulated_depreciation": str(tx_obj.asset.accumulated_depreciation if tx_obj.asset else "0.00"),
            "remaining_value": str(tx_obj.asset.remaining_value if tx_obj.asset else "0.00"),
        })

    return {
        "id": str(first_tx.id),
        "voucher_no": str(after_snap.get("voucher_no") or first_tx.source_reference or first_tx.number),
        "number": first_tx.number,
        "transaction_date": str(first_tx.transaction_date),
        "period_code": first_tx.period_code,
        "deliverer": str(after_snap.get("deliverer") or ""),
        "receiver": str(after_snap.get("receiver") or ""),
        "reason": first_tx.reason,
        "reference": str(after_snap.get("reference") or ""),
        "attachments": after_snap.get("attachments") or [],
        "status": first_tx.status,
        "status_display": "Đã ghi sổ" if first_tx.status == "POSTED" else first_tx.get_status_display(),
        "gl_status": first_tx.gl_status,
        "lines": detail_rows,
        "transactions": serialized_lines,
        "message": "Điều chuyển tài sản cố định thành công.",
    }


@transaction.atomic
def transfer_fixed_assets_uc05(request, data=None):
    """
    UC-FA-05 – Điều chuyển tài sản cố định (Steps 1-30, AF01-AF24, EF01-EF34, BR01-BR40, Section 5).
    Atomically validates and executes internal fixed-asset transfers across departments for 1..N assets.
    """
    import copy
    import re
    from django.db.models import Q
    from organization.models import Company, Department

    payload = data if data is not None else request.data
    company_id = (
        payload.get("company")
        or payload.get("company_id")
        or request.query_params.get("company_id")
    )
    if not company_id:
        raise ValidationError({"company": "Thiếu company_id."})
    try:
        company = Company.objects.get(pk=company_id)
    except (Company.DoesNotExist, ValueError) as exc:
        raise ValidationError({"company": "Doanh nghiệp không hợp lệ."}) from exc

    # EF01 & BR01: Permission check
    _check_transfer_permission(request, company, "FA.TRANSACTION.TRANSFER")

    # EF34 & BR04: Cross-company transfer is out of scope for internal fixed asset transfer
    target_company_id = payload.get("target_company") or payload.get("to_company") or payload.get("target_company_id")
    if (
        (target_company_id and str(target_company_id) != str(company.id))
        or bool(payload.get("cross_company", False))
        or str(payload.get("transfer_scope") or "").upper() == "INTER_COMPANY"
    ):
        raise ValidationError({
            "company": "Nghiệp vụ không thuộc phạm vi điều chuyển TSCĐ nội bộ.",
            "detail": "Nghiệp vụ không thuộc phạm vi điều chuyển TSCĐ nội bộ.",
        })

    # EF32 & BR36: Idempotency check
    idem_key = (
        payload.get("idempotency_key")
        or (request.headers.get("Idempotency-Key") if hasattr(request, "headers") else None)
        or (request.META.get("HTTP_IDEMPOTENCY_KEY") if hasattr(request, "META") else None)
    )
    if idem_key:
        idem_key = str(idem_key).strip()[:140]
        existing_idem_tx = models.AssetTransaction.objects.filter(
            company=company,
            transaction_type="TRANSFER",
            idempotency_key=idem_key,
        ).first()
        if existing_idem_tx:
            v_no = existing_idem_tx.source_reference or existing_idem_tx.number
            resp = _serialize_transfer_voucher_group(company, v_no)
            resp["idempotent_replayed"] = True
            return resp

    # EF08: Validate transfer date (Ngày điều chuyển)
    raw_date = (
        payload.get("transaction_date")
        or payload.get("transfer_date")
        or payload.get("handover_date")
        or payload.get("date")
    )
    tx_date = _parse_date(raw_date)
    if not tx_date:
        raise ValidationError({
            "transaction_date": "Vui lòng nhập ngày điều chuyển hợp lệ theo định dạng DD/MM/YYYY.",
            "detail": "Vui lòng nhập ngày điều chuyển hợp lệ theo định dạng DD/MM/YYYY.",
        })

    # EF09 & BR10: Check locked accounting / asset period
    if _closed(company, tx_date):
        raise ValidationError({
            "transaction_date": "Không thể điều chuyển tài sản trong kỳ đã khóa.",
            "period": "Không thể điều chuyển tài sản trong kỳ đã khóa.",
            "detail": "Không thể điều chuyển tài sản trong kỳ đã khóa.",
        })

    # EF02: Check if numbering rule is disabled / unconfigured
    if payload.get("numbering_rule_configured") is False or payload.get("numbering_enabled") is False:
        raise ValidationError({
            "voucher_no": "Chưa thiết lập quy tắc đánh số biên bản điều chuyển. Vui lòng kiểm tra cấu hình chứng từ.",
            "detail": "Chưa thiết lập quy tắc đánh số biên bản điều chuyển. Vui lòng kiểm tra cấu hình chứng từ.",
        })

    year_based = bool(payload.get("year_based_numbering", False))
    prefix = str(payload.get("voucher_prefix") or "ĐCTS").strip() or "ĐCTS"
    suggested_no = get_next_transfer_voucher_no(company, transfer_date=tx_date, year_based=year_based, prefix=prefix)

    has_voucher_key = any(k in payload for k in ("voucher_no", "number", "handover_no", "document_no"))
    raw_voucher_no = (
        payload.get("voucher_no")
        if "voucher_no" in payload
        else (
            payload.get("number")
            if "number" in payload
            else (
                payload.get("handover_no")
                if "handover_no" in payload
                else payload.get("document_no")
            )
        )
    )
    if not has_voucher_key and bool(payload.get("auto_generate_voucher_no", False)):
        voucher_no = suggested_no
    else:
        voucher_no = str(raw_voucher_no or "").strip()

    # EF03: Missing voucher_no
    if not voucher_no:
        raise ValidationError({
            "voucher_no": "Vui lòng nhập số biên bản giao nhận.",
            "detail": "Vui lòng nhập số biên bản giao nhận.",
        })

    # EF07: User not allowed to modify suggested voucher number when allow_manual_voucher_no=False
    allow_manual = payload.get("allow_manual_voucher_no", True)
    expected_no = str(payload.get("expected_voucher_no") or suggested_no).strip()
    if allow_manual is False and voucher_no != expected_no:
        raise ValidationError({
            "voucher_no": "Bạn không có quyền thay đổi số biên bản giao nhận.",
            "detail": "Bạn không có quyền thay đổi số biên bản giao nhận.",
        })

    # EF04: Format and max length check on voucher_no
    if len(voucher_no) > 50 or not re.match(r"^[A-Za-zÀ-ỹĐđ0-9_\-/\.]+$", voucher_no):
        raise ValidationError({
            "voucher_no": "Số biên bản giao nhận không hợp lệ.",
            "detail": "Số biên bản giao nhận không hợp lệ.",
        })

    # EF05, EF06 & AF05: Duplicate voucher_no check within company
    is_dup_voucher = models.AssetTransaction.objects.filter(company=company).filter(
        Q(number=voucher_no) | Q(source_reference=voucher_no)
    ).exists()
    if is_dup_voucher:
        if bool(payload.get("auto_resolve_number_conflict", False)):
            voucher_no = suggested_no
        else:
            raise ValidationError({
                "voucher_no": "Số biên bản giao nhận đã tồn tại. Vui lòng sử dụng số khác.",
                "detail": "Số biên bản giao nhận đã tồn tại. Vui lòng sử dụng số khác.",
            })

    # EF10: Deliverer (Người bàn giao)
    deliverer = str(
        payload.get("deliverer")
        if "deliverer" in payload
        else (payload.get("handover_by") if "handover_by" in payload else (payload.get("sender") or ""))
    ).strip()
    if not deliverer:
        raise ValidationError({
            "deliverer": "Vui lòng nhập người bàn giao tài sản.",
            "detail": "Vui lòng nhập người bàn giao tài sản.",
        })

    # EF11: Receiver (Người tiếp nhận)
    receiver = str(
        payload.get("receiver")
        if "receiver" in payload
        else (payload.get("received_by") if "received_by" in payload else (payload.get("recipient") or ""))
    ).strip()
    if not receiver:
        raise ValidationError({
            "receiver": "Vui lòng nhập người tiếp nhận tài sản.",
            "detail": "Vui lòng nhập người tiếp nhận tài sản.",
        })

    # EF12: Reason (Lý do điều chuyển)
    reason = str(
        payload.get("reason")
        if "reason" in payload
        else (payload.get("description") or "")
    ).strip()
    if not reason:
        raise ValidationError({
            "reason": "Vui lòng nhập lý do điều chuyển tài sản.",
            "detail": "Vui lòng nhập lý do điều chuyển tài sản.",
        })

    reference = str(payload.get("reference") or payload.get("source_reference") or "").strip()

    # AF18 & EF33: Validate attachments (Max 5MB per file, valid file formats)
    raw_attachments = payload.get("attachments")
    validated_attachments = []
    if raw_attachments is not None:
        if not isinstance(raw_attachments, list):
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            })
        allowed_exts = {".pdf", ".doc", ".docx", ".xls", ".xlsx", ".jpg", ".jpeg", ".png", ".csv", ".txt"}
        max_bytes = 5 * 1024 * 1024
        for att in raw_attachments:
            if not isinstance(att, dict) or att.get("invalid") is True:
                raise ValidationError({
                    "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                    "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                })
            fname = str(att.get("name") or att.get("filename") or att.get("file_name") or "").strip()
            fsize = att.get("size") if "size" in att else att.get("file_size", 0)
            try:
                fsize_int = int(fsize or 0)
            except (TypeError, ValueError):
                fsize_int = max_bytes + 1
            if fsize_int < 0 or fsize_int > max_bytes:
                raise ValidationError({
                    "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                    "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                })
            if fname and "." in fname:
                ext = "." + fname.rsplit(".", 1)[-1].lower()
                if ext not in allowed_exts:
                    raise ValidationError({
                        "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                        "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                    })
            validated_attachments.append({
                "name": fname or "attachment.pdf",
                "size": fsize_int,
                "url": str(att.get("url") or ""),
            })

    # EF13 & BR11: Extract detail lines
    raw_lines = (
        payload.get("lines")
        if "lines" in payload
        else (
            payload.get("rows")
            if "rows" in payload
            else (
                payload.get("items")
                if "items" in payload
                else payload.get("details")
            )
        )
    )
    if raw_lines is None and any(k in payload for k in ("asset", "asset_id", "asset_code")):
        raw_lines = [payload]

    if not raw_lines or not isinstance(raw_lines, list) or len(raw_lines) == 0:
        raise ValidationError({
            "lines": "Vui lòng chọn ít nhất một tài sản cần điều chuyển.",
            "detail": "Vui lòng chọn ít nhất một tài sản cần điều chuyển.",
        })

    seen_asset_ids = set()
    validated_items = []

    for idx, line in enumerate(raw_lines):
        if not isinstance(line, dict):
            raise ValidationError({
                "lines": "Vui lòng chọn ít nhất một tài sản cần điều chuyển.",
                "detail": "Vui lòng chọn ít nhất một tài sản cần điều chuyển.",
            })
        raw_asset_ref = (
            line.get("asset_id")
            or line.get("asset")
            or line.get("asset_code")
            or line.get("code")
        )
        raw_code_hint = str(line.get("asset_code") or line.get("code") or raw_asset_ref or "").strip()
        if not raw_asset_ref:
            raise ValidationError({
                "lines": "Vui lòng chọn ít nhất một tài sản cần điều chuyển.",
                "detail": "Vui lòng chọn ít nhất một tài sản cần điều chuyển.",
            })

        # Resolve asset within company (EF14)
        asset_obj = None
        ref_str = str(raw_asset_ref).strip()
        try:
            asset_obj = models.AssetRecord.objects.filter(pk=ref_str).first()
        except Exception:
            asset_obj = None
        if not asset_obj:
            asset_obj = models.AssetRecord.objects.filter(
                company=company,
                code__iexact=ref_str,
            ).first()
        if not asset_obj and raw_code_hint:
            asset_obj = models.AssetRecord.objects.filter(
                company=company,
                code__iexact=raw_code_hint,
            ).first()

        if not asset_obj or asset_obj.company_id != company.id:
            label = raw_code_hint or ref_str
            raise ValidationError({
                "asset": f"Tài sản {label} không hợp lệ.",
                "detail": f"Tài sản {label} không hợp lệ.",
            })

        asset = models.AssetRecord.objects.select_for_update().get(pk=asset_obj.pk)

        # EF21 & BR16: Check duplicate asset in the same transfer voucher
        if asset.id in seen_asset_ids:
            raise ValidationError({
                "lines": f"Tài sản {asset.code} đã được chọn trong chứng từ.",
                "detail": f"Tài sản {asset.code} đã được chọn trong chứng từ.",
            })
        seen_asset_ids.add(asset.id)

        # EF30: Optimistic locking / concurrent change detection
        expected_ver = line.get("expected_version") if "expected_version" in line else payload.get("expected_version")
        if expected_ver is not None:
            try:
                if int(expected_ver) != asset.version:
                    raise ValidationError({
                        "version": "Thông tin tài sản đã thay đổi. Vui lòng tải lại dữ liệu.",
                        "detail": "Thông tin tài sản đã thay đổi. Vui lòng tải lại dữ liệu.",
                    })
            except ValueError:
                pass

        # EF16 & BR03: Disposed asset cannot be transferred
        if asset.status == "DISPOSED" and (not asset.disposed_at or asset.disposed_at <= tx_date):
            raise ValidationError({
                "asset": f"Tài sản {asset.code} đã ghi giảm, không thể điều chuyển.",
                "detail": f"Tài sản {asset.code} đã ghi giảm, không thể điều chuyển.",
            })

        # EF15 & BR02, BR10: Asset must be ACTIVE and acquired on or before tx_date
        if (
            asset.status != "ACTIVE"
            or not asset.department_id
            or (asset.acquisition_date and tx_date < asset.acquisition_date)
        ):
            raise ValidationError({
                "asset": f"Tài sản {asset.code} chưa đủ điều kiện điều chuyển.",
                "detail": f"Tài sản {asset.code} chưa đủ điều kiện điều chuyển.",
            })

        # EF20 & BR13, BR14, BR38: Verify from_department matches asset's effective current department
        supplied_from = (
            line.get("from_department")
            or line.get("from_department_id")
            or line.get("from_department_name")
            or line.get("from_dept")
        )
        if supplied_from is not None and str(supplied_from).strip() != "":
            s_from = str(supplied_from).strip()
            cur_dept = asset.department
            matches_from = (
                s_from == str(asset.department_id)
                or (cur_dept and s_from.lower() in {cur_dept.code.lower(), cur_dept.name.lower()})
            )
            if not matches_from:
                raise ValidationError({
                    "from_department": "Đơn vị sử dụng của tài sản đã thay đổi. Vui lòng kiểm tra lại.",
                    "detail": "Đơn vị sử dụng của tài sản đã thay đổi. Vui lòng kiểm tra lại.",
                })

        # EF17: Missing receiving department (Đến đơn vị)
        raw_to_dept = (
            line.get("to_department")
            if "to_department" in line
            else (
                line.get("to_department_id")
                if "to_department_id" in line
                else (
                    line.get("target_department")
                    if "target_department" in line
                    else (
                        line.get("target_department_id")
                        if "target_department_id" in line
                        else (
                            line.get("to_department_name")
                            if "to_department_name" in line
                            else line.get("to_dept")
                        )
                    )
                )
            )
        )
        if raw_to_dept is None or str(raw_to_dept).strip() == "":
            raise ValidationError({
                "to_department": f"Vui lòng chọn đơn vị tiếp nhận cho tài sản {asset.code}.",
                "detail": f"Vui lòng chọn đơn vị tiếp nhận cho tài sản {asset.code}.",
            })

        # EF19: Resolve and validate receiving department (must belong to same company and be ACTIVE)
        to_str = str(raw_to_dept).strip()
        to_dept_obj = None
        try:
            to_dept_obj = Department.objects.filter(pk=to_str).first()
        except Exception:
            to_dept_obj = None
        if not to_dept_obj:
            to_dept_obj = Department.objects.filter(company=company).filter(
                Q(code__iexact=to_str) | Q(name__iexact=to_str)
            ).first()
        if not to_dept_obj and bool(line.get("auto_create_department", False)):
            to_dept_obj = _resolve_department(company, to_str, auto_create=True)

        if (
            not to_dept_obj
            or to_dept_obj.company_id != company.id
            or getattr(to_dept_obj, "status", "ACTIVE") != "ACTIVE"
            or getattr(to_dept_obj, "is_active", True) is False
        ):
            raise ValidationError({
                "to_department": "Đơn vị tiếp nhận không hợp lệ.",
                "detail": "Đơn vị tiếp nhận không hợp lệ.",
            })

        # EF18 & BR15: Receiving department must differ from current department
        if to_dept_obj.id == asset.department_id:
            raise ValidationError({
                "to_department": "Đơn vị tiếp nhận phải khác đơn vị hiện đang sử dụng tài sản.",
                "detail": "Đơn vị tiếp nhận phải khác đơn vị hiện đang sử dụng tài sản.",
            })

        # EF22 & BR17, AF24: Check for conflicting transfer at same date or later date
        if asset.transactions.filter(
            transaction_type="TRANSFER",
            status="POSTED",
            transaction_date__gte=tx_date,
        ).exists():
            raise ValidationError({
                "transaction_date": f"Tài sản {asset.code} đã có nghiệp vụ điều chuyển tại thời điểm này.",
                "detail": f"Tài sản {asset.code} đã có nghiệp vụ điều chuyển tại thời điểm này.",
            })

        # EF29 & BR33: Check if transfer affects already-posted depreciation runs
        if not bool(payload.get("allow_posted_depreciation_adjustment", False)):
            has_posted_depr = (
                models.CalculationLine.objects.filter(
                    asset=asset,
                    run__status="POSTED",
                    run__period_end__gte=tx_date,
                ).exists()
                or asset.transactions.filter(
                    transaction_type="DEPRECIATION",
                    status="POSTED",
                    transaction_date__gte=tx_date,
                ).exists()
            )
            if has_posted_depr:
                raise ValidationError({
                    "transaction_date": "Điều chuyển ảnh hưởng đến dữ liệu khấu hao đã ghi sổ. Vui lòng thực hiện điều chỉnh phù hợp.",
                    "detail": "Điều chuyển ảnh hưởng đến dữ liệu khấu hao đã ghi sổ. Vui lòng thực hiện điều chỉnh phù hợp.",
                })

        # Cost tracking dimensions (Steps 13-17, AF06-AF11, EF23-EF28, BR18-BR27)
        sales_contract = str(line.get("sales_contract") or "").strip()
        sales_order = str(line.get("sales_order") or "").strip()
        project = str(line.get("project") or "").strip()
        expense_item = str(line.get("expense_item") or line.get("cost_item") or "").strip()
        cost_object = str(line.get("cost_object") or line.get("cost_center") or "").strip()

        # EF23: Invalid sales contract
        if (
            bool(line.get("sales_contract_invalid", False))
            or sales_contract.upper().startswith("INVALID")
            or sales_contract.upper().startswith("EXPIRED")
        ):
            raise ValidationError({
                "sales_contract": "Hợp đồng bán không hợp lệ. Vui lòng chọn lại.",
                "detail": "Hợp đồng bán không hợp lệ. Vui lòng chọn lại.",
            })

        # EF24: Sales order incompatible with selected sales contract
        expected_order_contract = str(line.get("sales_order_contract") or "").strip()
        if (
            bool(line.get("sales_order_invalid", False))
            or sales_order.upper().startswith("INVALID")
            or sales_order.upper().startswith("MISMATCH")
            or (sales_contract and sales_order and expected_order_contract and expected_order_contract != sales_contract)
        ):
            raise ValidationError({
                "sales_order": "Đơn đặt hàng không phù hợp với hợp đồng bán đã chọn.",
                "detail": "Đơn đặt hàng không phù hợp với hợp đồng bán đã chọn.",
            })

        # EF25: Project invalid or closed for cost collection
        if (
            bool(line.get("project_invalid", False))
            or project.upper().startswith("INVALID")
            or project.upper().startswith("CLOSED")
        ):
            raise ValidationError({
                "project": "Công trình không hợp lệ hoặc không được phép tập hợp chi phí.",
                "detail": "Công trình không hợp lệ hoặc không được phép tập hợp chi phí.",
            })

        # EF26: Expense item invalid or inactive
        if (
            bool(line.get("expense_item_invalid", False))
            or expense_item.upper().startswith("INVALID")
            or expense_item.upper().startswith("INACTIVE")
        ):
            raise ValidationError({
                "expense_item": "Khoản mục chi phí không hợp lệ.",
                "detail": "Khoản mục chi phí không hợp lệ.",
            })

        # EF27: Cost object invalid or inactive
        if (
            bool(line.get("cost_object_invalid", False))
            or cost_object.upper().startswith("INVALID")
            or cost_object.upper().startswith("INACTIVE")
        ):
            raise ValidationError({
                "cost_object": "Đối tượng tập hợp chi phí không hợp lệ.",
                "detail": "Đối tượng tập hợp chi phí không hợp lệ.",
            })

        # EF28 & BR20: Required cost tracking missing when policy mandates it
        require_cost_tracking = bool(
            line.get("require_cost_tracking", False)
            or payload.get("require_cost_tracking", False)
        )
        if require_cost_tracking and not any((sales_contract, sales_order, project, expense_item, cost_object)):
            raise ValidationError({
                "cost_tracking": f"Vui lòng khai báo đầy đủ thông tin tập hợp chi phí cho tài sản {asset.code}.",
                "detail": f"Vui lòng khai báo đầy đủ thông tin tập hợp chi phí cho tài sản {asset.code}.",
            })

        validated_items.append({
            "asset": asset,
            "to_department": to_dept_obj,
            "sales_contract": sales_contract,
            "sales_order": sales_order,
            "project": project,
            "expense_item": expense_item,
            "cost_object": cost_object,
            "clear_cost_tracking": bool(line.get("clear_cost_tracking", False)),
            "custom_allocations": line.get("allocations") if isinstance(line.get("allocations"), list) else None,
            "line_receiver": str(line.get("receiver") or receiver).strip(),
            "simulate_error": bool(line.get("simulate_db_error", False)),
        })

    # Execute atomic update of all assets and creation of transfer transactions (BR35)
    created_txs = []
    user_actor = actor(request)
    period_code = f"{tx_date.year:04d}-{tx_date.month:02d}"
    prorate_in_period = bool(payload.get("prorate_in_period", False))

    try:
        for idx, item in enumerate(validated_items):
            if item["simulate_error"] or (idx == len(validated_items) - 1 and bool(payload.get("simulate_db_error", False))):
                raise DatabaseError("Simulated database error during fixed asset transfer.")

            asset = item["asset"]
            to_dept = item["to_department"]
            old_dept = asset.department
            old_allocs = copy.deepcopy(asset.allocations or [])
            old_exp_item = ""
            old_cost_center = ""
            if old_allocs and isinstance(old_allocs[0], dict):
                old_exp_item = str(old_allocs[0].get("expense_item") or "")
                old_cost_center = str(old_allocs[0].get("cost_center") or "")

            before = {
                **_snapshot(asset),
                "from_department_id": str(old_dept.id) if old_dept else "",
                "from_department_code": old_dept.code if old_dept else "",
                "from_department_name": old_dept.name if old_dept else "",
                "expense_item": old_exp_item,
                "cost_center": old_cost_center,
                "allocations": old_allocs,
            }

            # Determine updated allocations (AF11, AF13, BR26, BR27, Section 5.6)
            new_exp_item = (
                "Chi phí khấu hao TSCĐ"
                if item["clear_cost_tracking"]
                else (item["expense_item"] or old_exp_item or "Chi phí khấu hao TSCĐ")
            )
            new_cost_center = (
                to_dept.name
                if item["clear_cost_tracking"]
                else (item["cost_object"] or item["project"] or to_dept.name)
            )
            default_exp_acc_id = str(asset.category.expense_account_id) if asset.category and asset.category.expense_account_id else ""
            default_exp_acc_code = asset.category.expense_account.code if asset.category and asset.category.expense_account_id else "6424"

            if item["custom_allocations"] is not None:
                asset.allocations = copy.deepcopy(item["custom_allocations"])
            elif len(old_allocs) > 1:
                # AF11 & BR27: Multi-department allocation - update only the transferred department's slot, preserving ratios
                updated_multi = []
                replaced = False
                for al in old_allocs:
                    if not isinstance(al, dict):
                        continue
                    al_copy = copy.deepcopy(al)
                    al_dept_id = str(al_copy.get("department_id") or "")
                    al_dept_name = str(al_copy.get("department_name") or al_copy.get("department") or "")
                    if not replaced and old_dept and (
                        al_dept_id == str(old_dept.id)
                        or al_dept_name.lower() in {old_dept.name.lower(), old_dept.code.lower()}
                    ):
                        al_copy["department_id"] = str(to_dept.id)
                        al_copy["department_name"] = to_dept.name
                        al_copy["expense_item"] = new_exp_item
                        al_copy["cost_center"] = new_cost_center
                        if item["project"]:
                            al_copy["project"] = item["project"]
                        if item["sales_contract"]:
                            al_copy["sales_contract"] = item["sales_contract"]
                        if item["sales_order"]:
                            al_copy["sales_order"] = item["sales_order"]
                        replaced = True
                    updated_multi.append(al_copy)
                asset.allocations = updated_multi
            else:
                base_al = copy.deepcopy(old_allocs[0]) if (old_allocs and isinstance(old_allocs[0], dict)) else {}
                base_al.update({
                    "department_id": str(to_dept.id),
                    "department_name": to_dept.name,
                    "rate": str(base_al.get("rate") or "100"),
                    "expense_account_id": str(base_al.get("expense_account_id") or default_exp_acc_id),
                    "expense_account": str(base_al.get("expense_account") or default_exp_acc_code),
                    "expense_item": new_exp_item,
                    "cost_center": new_cost_center,
                    "sales_contract": "" if item["clear_cost_tracking"] else item["sales_contract"],
                    "sales_order": "" if item["clear_cost_tracking"] else item["sales_order"],
                    "project": "" if item["clear_cost_tracking"] else item["project"],
                    "cost_object": "" if item["clear_cost_tracking"] else item["cost_object"],
                })
                asset.allocations = [base_al]

            # Update asset department & version while strictly preserving original_cost, accumulated_depreciation, remaining_value (BR28)
            asset.department = to_dept
            if to_dept.branch_id:
                asset.branch = to_dept.branch
            asset.version = (asset.version or 1) + 1
            asset.save(update_fields=("department", "branch", "allocations", "version", "updated_at"))

            after = {
                **_snapshot(asset),
                "voucher_no": voucher_no,
                "period_code": period_code,
                "deliverer": deliverer,
                "receiver": item["line_receiver"],
                "reason": reason,
                "reference": reference,
                "from_department_id": str(old_dept.id) if old_dept else "",
                "from_department_code": old_dept.code if old_dept else "",
                "from_department_name": old_dept.name if old_dept else "",
                "to_department_id": str(to_dept.id),
                "to_department_code": to_dept.code,
                "to_department_name": to_dept.name,
                "sales_contract": "" if item["clear_cost_tracking"] else item["sales_contract"],
                "sales_order": "" if item["clear_cost_tracking"] else item["sales_order"],
                "project": "" if item["clear_cost_tracking"] else item["project"],
                "expense_item": new_exp_item,
                "cost_object": "" if item["clear_cost_tracking"] else item["cost_object"],
                "attachments": validated_attachments,
                "prorate_in_period": prorate_in_period,
                "allocations": copy.deepcopy(asset.allocations),
            }

            tx_number = voucher_no if idx == 0 else f"{voucher_no}-{idx + 1:02d}"
            tx_idem = (f"{idem_key}:{idx}" if idx > 0 else idem_key) if idem_key else None

            tx_obj = models.AssetTransaction.objects.create(
                company=company,
                asset=asset,
                number=tx_number,
                transaction_type="TRANSFER",
                transaction_date=tx_date,
                period_code="",
                amount=Decimal("0.00"),
                reason=reason,
                source_module="FA",
                source_reference=voucher_no,
                idempotency_key=tx_idem,
                target_branch=to_dept.branch if to_dept.branch_id else asset.branch,
                target_department=to_dept,
                before_snapshot=before,
                after_snapshot=after,
                status="POSTED",
                asset_applied=True,
                gl_status="NOT_REQUIRED",
                created_by=user_actor,
                posted_at=timezone.now(),
            )
            audit(
                request,
                tx_obj,
                "TRANSFER_ASSET",
                before=before,
                after=after,
                reason=reason,
            )
            audit(
                request,
                asset,
                "TRANSFER_ASSET",
                before=before,
                after=after,
                reason=reason,
            )
            created_txs.append(tx_obj)
    except ValidationError:
        raise
    except Exception as exc:
        # EF31 & BR35: Roll back entire multi-asset transfer atomically and return exact error message
        raise ValidationError({
            "detail": "Điều chuyển tài sản cố định thất bại. Vui lòng thử lại.",
        }) from exc

    return _serialize_transfer_voucher_group(company, voucher_no, transactions_qs=created_txs)


# ==============================================================================
# UC-FA-06: ĐÁNH GIÁ LẠI TÀI SẢN CỐ ĐỊNH (FIXED ASSET REVALUATION / UPGRADE)
# ==============================================================================

def get_next_revaluation_voucher_no(company, reval_date=None, year_based=False, prefix="ĐGL"):
    """
    UC-FA-06 Step 9, AF04, BR03–BR05:
    Auto-suggests the next sequential revaluation voucher number (e.g., ĐGL00001 -> ĐGL00002,
    or ĐGL2026-0001 when year_based=True).
    """
    dt = _parse_date(reval_date) or timezone.localdate()
    clean_prefix = (prefix or "ĐGL").strip()
    if year_based:
        pattern_prefix = f"{clean_prefix}{dt.year}-"
        pad_width = 4
    else:
        pattern_prefix = clean_prefix
        pad_width = 5

    existing_refs = list(
        models.AssetTransaction.objects.filter(
            company=company,
            transaction_type__in=("VALUE_INCREASE", "VALUE_DECREASE", "LIFE_CHANGE"),
        )
        .exclude(status="CANCELLED")
        .values_list("source_reference", "number")
    )
    max_seq = 0
    escaped = re.escape(pattern_prefix)
    regex = re.compile(rf"^{escaped}(\d+)(?:-\d+)?$", re.IGNORECASE)
    for src_ref, num in existing_refs:
        for candidate in (src_ref, num):
            if not candidate:
                continue
            m = regex.match(str(candidate).strip())
            if m:
                seq_val = int(m.group(1))
                if seq_val > max_seq:
                    max_seq = seq_val

    next_seq = max_seq + 1
    return f"{pattern_prefix}{next_seq:0{pad_width}d}"


def get_next_revaluation_report_no(company):
    """
    UC-FA-06 AF03: Auto-suggests the next evaluation report number (e.g., 01/BB-ĐGL -> 02/BB-ĐGL).
    """
    txs = models.AssetTransaction.objects.filter(
        company=company,
        transaction_type__in=("VALUE_INCREASE", "VALUE_DECREASE", "LIFE_CHANGE"),
    ).exclude(status="CANCELLED")
    max_seq = 0
    regex = re.compile(r"^(\d+)/BB-ĐGL$", re.IGNORECASE)
    for tx in txs:
        snap = tx.after_snapshot or {}
        rep_no = str(snap.get("report_no") or "").strip()
        m = regex.match(rep_no)
        if m:
            seq_val = int(m.group(1))
            if seq_val > max_seq:
                max_seq = seq_val
    return f"{max_seq + 1:02d}/BB-ĐGL"


def _serialize_revaluation_voucher_group(company, voucher_no, transactions_qs=None, idempotent_replayed=False):
    if transactions_qs is None:
        transactions_qs = list(
            models.AssetTransaction.objects.filter(
                company=company,
                transaction_type__in=("VALUE_INCREASE", "VALUE_DECREASE", "LIFE_CHANGE"),
                status="POSTED",
            )
            .filter(Q(source_reference=voucher_no) | Q(number=voucher_no))
            .select_related("asset", "asset__department", "target_department", "created_by")
            .order_by("created_at", "id")
        )
    else:
        transactions_qs = list(transactions_qs)

    first_tx = transactions_qs[0] if transactions_qs else None
    after_snap = (first_tx.after_snapshot or {}) if first_tx else {}

    items_payload = []
    for tx in transactions_qs:
        b_snap = tx.before_snapshot or {}
        a_snap = tx.after_snapshot or {}
        items_payload.append({
            "transaction_id": str(tx.id),
            "transaction_number": tx.number,
            "transaction_type": tx.transaction_type,
            "asset_id": str(tx.asset_id),
            "asset_code": tx.asset.code,
            "asset_name": tx.asset.name,
            "department_id": a_snap.get("department_id") or (str(tx.asset.department_id) if tx.asset.department_id else ""),
            "department_name": a_snap.get("department_name") or (tx.asset.department.name if tx.asset.department else ""),
            "orig_before": str(b_snap.get("orig_before") or b_snap.get("original_cost") or "0.00"),
            "orig_after": str(a_snap.get("orig_after") or a_snap.get("original_cost") or "0.00"),
            "orig_diff": str(a_snap.get("orig_diff") or "0.00"),
            "depr_before": str(b_snap.get("depr_before") or b_snap.get("accumulated_depreciation") or "0.00"),
            "depr_after": str(a_snap.get("depr_after") or a_snap.get("accumulated_depreciation") or "0.00"),
            "depr_diff": str(a_snap.get("depr_diff") or "0.00"),
            "rem_before": str(b_snap.get("rem_before") or b_snap.get("remaining_value") or "0.00"),
            "rem_after": str(a_snap.get("rem_after") or a_snap.get("remaining_value") or "0.00"),
            "rem_diff": str(a_snap.get("rem_diff") or "0.00"),
            "months_before": int(b_snap.get("months_before") or 0),
            "months_after": int(a_snap.get("months_after") or 0),
            "months_diff": int(a_snap.get("months_diff") or 0),
            "val_before": str(b_snap.get("val_before") or "0.00"),
            "val_after": str(a_snap.get("val_after") or "0.00"),
            "val_diff": str(a_snap.get("val_diff") or "0.00"),
            "remaining_depreciable_after": str(a_snap.get("remaining_depreciable_after") or "0.00"),
            "monthly_depr_after": str(a_snap.get("monthly_depr_after") or "0.00"),
            "monthly_depr_law_after": str(a_snap.get("monthly_depr_law_after") or "0.00"),
            "cost_account": a_snap.get("cost_account", ""),
            "reval_account": a_snap.get("reval_account", ""),
            "status": tx.status,
            "gl_status": tx.gl_status,
            "journal_entry_id": str(a_snap.get("journal_entry_id") or ""),
        })

    return {
        "voucher_no": voucher_no,
        "number": voucher_no,
        "report_no": after_snap.get("report_no", ""),
        "report_date": after_snap.get("report_date", ""),
        "posting_date": after_snap.get("posting_date") or (first_tx.transaction_date.isoformat() if first_tx else ""),
        "voucher_date": after_snap.get("voucher_date") or (first_tx.transaction_date.isoformat() if first_tx else ""),
        "effective_date": after_snap.get("effective_date") or (first_tx.transaction_date.isoformat() if first_tx else ""),
        "period_code": after_snap.get("period_code") or (first_tx.period_code if first_tx else ""),
        "reason": first_tx.reason if first_tx else "",
        "conclusion": after_snap.get("conclusion", ""),
        "reference": after_snap.get("reference", ""),
        "members": after_snap.get("members", []),
        "attachments": after_snap.get("attachments", []),
        "accounting_entries": after_snap.get("accounting_entries", []),
        "journal_entry_id": str(after_snap.get("journal_entry_id") or ""),
        "status": "POSTED",
        "items_count": len(items_payload),
        "items": items_payload,
        "idempotent_replayed": idempotent_replayed,
        "message": "Đánh giá lại tài sản cố định thành công.",
    }


def _validate_reval_gl_account_code(company, code_str):
    """Checks that an account code is syntactically valid and, if in ChartOfAccounts, is ACTIVE, postable, and a leaf account."""
    from general_ledger.models import Account

    c = str(code_str or "").strip()
    if not c or c.upper().startswith("INVALID") or c.upper().startswith("INACTIVE") or c.upper().startswith("PARENT"):
        return False
    if not re.match(r"^[0-9A-Za-z._-]+$", c):
        return False
    existing = Account.objects.filter(company=company, code=c).first()
    if existing:
        if (
            existing.status != "ACTIVE"
            or not existing.is_postable
            or existing.children.filter(status="ACTIVE").exists()
        ):
            return False
    return True


def _create_gl_journal_entry_for_revaluation(company, voucher_no, voucher_dt, posting_dt, reason, validated_entries, user_actor, source_entity_id=None):
    """Creates a POSTED JournalEntry and balanced JournalLines in general_ledger for UC-FA-06 revaluation."""
    import calendar
    import uuid
    from general_ledger.models import AccountingPeriod, JournalEntry, JournalLine
    from master_data.models import Currency

    if not validated_entries:
        return None

    gl_period = AccountingPeriod.objects.filter(
        company=company,
        start_date__lte=posting_dt,
        end_date__gte=posting_dt,
    ).first()
    if not gl_period:
        last_d = calendar.monthrange(posting_dt.year, posting_dt.month)[1]
        gl_period, _ = AccountingPeriod.objects.get_or_create(
            company=company,
            fiscal_year=posting_dt.year,
            period_number=posting_dt.month,
            defaults={
                "code": f"{posting_dt.year:04d}-{posting_dt.month:02d}",
                "start_date": date_cls(posting_dt.year, posting_dt.month, 1),
                "end_date": date_cls(posting_dt.year, posting_dt.month, last_d),
                "status": "OPEN",
            },
        )
    if gl_period.status != "OPEN":
        raise ValidationError({
            "period": "Kỳ kế toán đã khóa, không thể ghi nhận đánh giá lại tài sản.",
            "detail": "Kỳ kế toán đã khóa, không thể ghi nhận đánh giá lại tài sản.",
        })

    vnd_currency = getattr(company, "accounting_currency", None) or Currency.objects.filter(code="VND").first()
    if not vnd_currency:
        vnd_currency = Currency.objects.create(code="VND", name="Đồng Việt Nam", decimal_places=0)

    branch = company.branches.first()
    gl_number = f"GL-{voucher_no}"
    if JournalEntry.objects.filter(company=company, number=gl_number).exists():
        gl_number = f"GL-{voucher_no}-{timezone.now().strftime('%H%M%S')}"

    total_amt = sum(ae["amount"] for ae in validated_entries)
    entry = JournalEntry.objects.create(
        company=company,
        branch=branch,
        period=gl_period,
        number=gl_number,
        entry_type="SUBLEDGER",
        document_date=voucher_dt,
        posting_date=posting_dt,
        description=reason or f"Đánh giá lại TSCĐ {voucher_no}",
        source_module="FA",
        source_event_id=f"FA_REVAL:{company.id}:{voucher_no}",
        source_entity_type="AssetTransaction",
        source_entity_id=source_entity_id,
        status="POSTED",
        total_debit=total_amt,
        total_credit=total_amt,
        created_by=user_actor,
        posted_by=user_actor,
        posted_at=timezone.now(),
    )

    line_no = 1
    for ae in validated_entries:
        amt = ae["amount"]
        debit_acc = _ensure_gl_account_for_code(company, ae["debit_account"], is_debit=True)
        credit_acc = _ensure_gl_account_for_code(company, ae["credit_account"], is_debit=False)
        desc = ae.get("description") or reason
        dims = {
            "object_code": ae.get("object_code") or "",
            "object_name": ae.get("object_name") or "",
            "cost_item": ae.get("cost_item") or "",
            "department_name": ae.get("department_name") or "",
        }
        JournalLine.objects.create(
            entry=entry,
            line_no=line_no,
            account=debit_acc,
            description=desc,
            debit=amt,
            credit=Decimal("0"),
            currency=vnd_currency,
            foreign_amount=amt,
            exchange_rate=Decimal("1"),
            dimensions=dims,
        )
        line_no += 1
        JournalLine.objects.create(
            entry=entry,
            line_no=line_no,
            account=credit_acc,
            description=desc,
            debit=Decimal("0"),
            credit=amt,
            currency=vnd_currency,
            foreign_amount=amt,
            exchange_rate=Decimal("1"),
            dimensions=dims,
        )
        line_no += 1

    return entry


@transaction.atomic
def revaluate_fixed_assets_uc06(request, data=None):
    """
    UC-FA-06 – Đánh giá lại tài sản cố định:
    Full implementation of Main Flow (Steps 1–47), Alternative Flows (AF01–AF30),
    Exception Flows (EF01–EF30), Formulas (Section 4.1–4.9), and Business Rules (BR01–BR35).
    """
    from organization.models import Company

    payload = data if data is not None else request.data
    company_id = (
        payload.get("company")
        or payload.get("company_id")
        or request.query_params.get("company_id")
    )
    if not company_id:
        raise ValidationError({"company": "Thiếu thông tin doanh nghiệp (company)."})

    try:
        company = Company.objects.get(pk=company_id)
    except (Company.DoesNotExist, ValueError) as exc:
        raise ValidationError({"company": "Doanh nghiệp không hợp lệ."}) from exc

    # EF01: Check permission to revaluate fixed assets
    if not request.user or not request.user.is_authenticated:
        raise PermissionDenied("Bạn không có quyền đánh giá lại tài sản cố định.")
    if not request.user.is_superuser:
        if not hasattr(request.user, "iam_account") or (
            not has_effective_permission(request.user.iam_account, company, "FA.TRANSACTION.REVALUATE")
            and not has_effective_permission(request.user.iam_account, company, "FA.TRANSACTION.CREATE")
            and not has_effective_permission(request.user.iam_account, company, "FA.ASSET.EDIT")
        ):
            raise PermissionDenied("Bạn không có quyền đánh giá lại tài sản cố định.")

    # EF28: Idempotency check (prevent duplicate voucher creation on repeated clicks of Cất / Cất và In)
    idem_key = str(payload.get("idempotency_key") or "").strip() or None
    if idem_key:
        existing_idem_tx = (
            models.AssetTransaction.objects.filter(
                company=company,
                transaction_type__in=("VALUE_INCREASE", "VALUE_DECREASE", "LIFE_CHANGE"),
                idempotency_key=idem_key,
            )
            .exclude(status="CANCELLED")
            .first()
        )
        if existing_idem_tx:
            v_no = existing_idem_tx.source_reference or existing_idem_tx.number
            return _serialize_revaluation_voucher_group(company, v_no, idempotent_replayed=True)

    # Step 7, 8 & EF05 & BR06: Validate posting_date (Ngày hạch toán) and voucher_date (Ngày chứng từ)
    has_posting_key = "posting_date" in payload or "transaction_date" in payload
    has_voucher_key = "voucher_date" in payload or "document_date" in payload

    raw_posting_date = payload.get("posting_date") if "posting_date" in payload else payload.get("transaction_date")
    raw_voucher_date = payload.get("voucher_date") if "voucher_date" in payload else payload.get("document_date")

    if has_posting_key and (raw_posting_date is None or str(raw_posting_date).strip() == ""):
        raise ValidationError({
            "posting_date": "Vui lòng nhập ngày chứng từ và ngày hạch toán hợp lệ.",
            "detail": "Vui lòng nhập ngày chứng từ và ngày hạch toán hợp lệ.",
        })
    if has_voucher_key and (raw_voucher_date is None or str(raw_voucher_date).strip() == ""):
        raise ValidationError({
            "voucher_date": "Vui lòng nhập ngày chứng từ và ngày hạch toán hợp lệ.",
            "detail": "Vui lòng nhập ngày chứng từ và ngày hạch toán hợp lệ.",
        })

    if not has_posting_key and not has_voucher_key:
        raise ValidationError({
            "posting_date": "Vui lòng nhập ngày chứng từ và ngày hạch toán hợp lệ.",
            "detail": "Vui lòng nhập ngày chứng từ và ngày hạch toán hợp lệ.",
        })

    posting_dt = _parse_date(raw_posting_date) if has_posting_key else _parse_date(raw_voucher_date)
    voucher_dt = _parse_date(raw_voucher_date) if has_voucher_key else posting_dt

    if not posting_dt or not voucher_dt or voucher_dt > posting_dt:
        raise ValidationError({
            "posting_date": "Vui lòng nhập ngày chứng từ và ngày hạch toán hợp lệ.",
            "detail": "Vui lòng nhập ngày chứng từ và ngày hạch toán hợp lệ.",
        })

    # Step 5 & EF04 & BR06: Validate report_date (Ngày biên bản)
    has_report_date_key = "report_date" in payload or "evaluation_date" in payload
    if has_report_date_key:
        raw_rep_dt = payload.get("report_date") if "report_date" in payload else payload.get("evaluation_date")
        rep_dt = _parse_date(raw_rep_dt)
        if not rep_dt or (rep_dt > posting_dt and not bool(payload.get("allow_report_after_posting", False))):
            raise ValidationError({
                "report_date": "Ngày biên bản không hợp lệ. Vui lòng kiểm tra lại.",
                "detail": "Ngày biên bản không hợp lệ. Vui lòng kiểm tra lại.",
            })
    else:
        rep_dt = voucher_dt

    effective_dt = _parse_date(payload.get("effective_date")) or posting_dt

    # EF06 & BR06: Check if accounting period / asset period is locked for posting_dt or effective_dt
    for check_dt in {posting_dt, effective_dt}:
        if _closed(company, check_dt):
            raise ValidationError({
                "period": "Kỳ kế toán đã khóa, không thể ghi nhận đánh giá lại tài sản.",
                "detail": "Kỳ kế toán đã khóa, không thể ghi nhận đánh giá lại tài sản.",
            })

    # Step 9, AF04, EF02, BR03–BR05: Validate or auto-generate voucher_no (Số chứng từ)
    raw_voucher_no = (
        payload.get("voucher_no")
        if "voucher_no" in payload
        else (payload.get("number") if "number" in payload else None)
    )
    year_based = bool(payload.get("year_based_numbering", False))
    prefix = str(payload.get("numbering_prefix") or "ĐGL").strip()

    if raw_voucher_no is None:
        voucher_no = get_next_revaluation_voucher_no(
            company, reval_date=posting_dt, year_based=year_based, prefix=prefix
        )
    else:
        voucher_no = str(raw_voucher_no).strip()
        if (
            not voucher_no
            or len(voucher_no) > 50
            or not re.match(r"^[A-Za-zÀ-ỹ0-9/_-]+$", voucher_no)
        ):
            raise ValidationError({
                "voucher_no": "Số chứng từ đánh giá lại không hợp lệ hoặc đã tồn tại.",
                "detail": "Số chứng từ đánh giá lại không hợp lệ hoặc đã tồn tại.",
            })

    if (
        models.AssetTransaction.objects.filter(company=company)
        .exclude(status="CANCELLED")
        .filter(
            Q(number=voucher_no)
            | (
                Q(source_reference=voucher_no)
                & Q(transaction_type__in=("VALUE_INCREASE", "VALUE_DECREASE", "LIFE_CHANGE"))
            )
        )
        .exists()
    ):
        raise ValidationError({
            "voucher_no": "Số chứng từ đánh giá lại không hợp lệ hoặc đã tồn tại.",
            "detail": "Số chứng từ đánh giá lại không hợp lệ hoặc đã tồn tại.",
        })

    # Step 4, AF03, EF03, BR04: Validate or auto-suggest report_no (Biên bản số)
    has_report_no_key = "report_no" in payload or "evaluation_no" in payload or "document_no" in payload
    raw_report_no = (
        payload.get("report_no")
        if "report_no" in payload
        else (payload.get("evaluation_no") if "evaluation_no" in payload else payload.get("document_no"))
    )
    if bool(payload.get("suggest_report_no", False)) and not str(raw_report_no or "").strip():
        report_no = get_next_revaluation_report_no(company)
    elif has_report_no_key:
        report_no = str(raw_report_no or "").strip()
        if not report_no and not bool(payload.get("allow_empty_report_no", False)):
            raise ValidationError({
                "report_no": "Vui lòng nhập số biên bản đánh giá lại.",
                "detail": "Vui lòng nhập số biên bản đánh giá lại.",
            })
    elif bool(payload.get("require_report_no", False)):
        raise ValidationError({
            "report_no": "Vui lòng nhập số biên bản đánh giá lại.",
            "detail": "Vui lòng nhập số biên bản đánh giá lại.",
        })
    else:
        report_no = get_next_revaluation_report_no(company)

    # Step 6, AF05–AF10, EF07, EF08, BR07: Validate reason (Lý do đánh giá) and legal basis
    reason = str(payload.get("reason") or payload.get("evaluation_reason") or "").strip()
    if not reason:
        raise ValidationError({
            "reason": "Vui lòng chọn lý do đánh giá lại tài sản.",
            "detail": "Vui lòng chọn lý do đánh giá lại tài sản.",
        })

    if bool(payload.get("missing_legal_basis", False)) or (
        bool(payload.get("require_legal_basis", False))
        and not any([
            payload.get("decision_no"),
            payload.get("acceptance_doc_no"),
            payload.get("reference"),
            payload.get("attachments"),
        ])
    ):
        raise ValidationError({
            "legal_basis": "Chưa có căn cứ hợp lệ để điều chỉnh tài sản cố định.",
            "detail": "Chưa có căn cứ hợp lệ để điều chỉnh tài sản cố định.",
        })

    # Steps 10–14, AF11, AF12, EF09, BR08: Validate Evaluation Council Members (Thành viên tham gia)
    raw_members = payload.get("members") if "members" in payload else payload.get("council_members")
    validated_members = []
    if raw_members is not None:
        if not isinstance(raw_members, list):
            raise ValidationError({
                "members": "Vui lòng khai báo đầy đủ thông tin thành viên tham gia đánh giá.",
                "detail": "Vui lòng khai báo đầy đủ thông tin thành viên tham gia đánh giá.",
            })
        for m in raw_members:
            if not isinstance(m, dict):
                raise ValidationError({
                    "members": "Vui lòng khai báo đầy đủ thông tin thành viên tham gia đánh giá.",
                    "detail": "Vui lòng khai báo đầy đủ thông tin thành viên tham gia đánh giá.",
                })
            m_name = str(m.get("name") or m.get("full_name") or "").strip()
            m_title = str(m.get("title") or m.get("position") or "").strip()
            m_rep = str(m.get("representation") or m.get("department") or m.get("role") or "").strip()
            # Ignore completely empty UI placeholder rows that carry an 'id' key unless require_members=True
            if not m_name and not m_title and not m_rep and "id" in m and not bool(payload.get("require_members", False)):
                continue
            if not m_name:
                raise ValidationError({
                    "members": "Vui lòng khai báo đầy đủ thông tin thành viên tham gia đánh giá.",
                    "detail": "Vui lòng khai báo đầy đủ thông tin thành viên tham gia đánh giá.",
                })
            validated_members.append({
                "name": m_name,
                "title": m_title,
                "representation": m_rep,
            })

    if bool(payload.get("require_members", False)) and len(validated_members) == 0:
        raise ValidationError({
            "members": "Vui lòng khai báo đầy đủ thông tin thành viên tham gia đánh giá.",
            "detail": "Vui lòng khai báo đầy đủ thông tin thành viên tham gia đánh giá.",
        })

    # Step 37 & EF10: Validate Conclusion (Kết luận)
    conclusion = str(payload.get("conclusion") or "").strip()
    if not conclusion and bool(payload.get("require_conclusion", False)):
        raise ValidationError({
            "conclusion": "Vui lòng nhập kết luận đánh giá tài sản.",
            "detail": "Vui lòng nhập kết luận đánh giá tài sản.",
        })

    reference = str(payload.get("reference") or "").strip()

    # Step 37, AF24, EF29, BR34: Validate Attachments (<= 5MB, valid formats)
    raw_attachments = payload.get("attachments") or []
    if not isinstance(raw_attachments, list):
        raise ValidationError({
            "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
        })
    allowed_reval_exts = {".pdf", ".doc", ".docx", ".xls", ".xlsx", ".jpg", ".jpeg", ".png", ".csv", ".txt"}
    max_reval_bytes = 5 * 1024 * 1024
    validated_attachments = []
    for att in raw_attachments:
        if isinstance(att, dict):
            att_name = str(att.get("name") or att.get("filename") or "").strip()
            att_size = int(att.get("size") or att.get("size_bytes") or 0)
            att_invalid = bool(att.get("invalid", False))
        else:
            att_name = str(att).strip()
            att_size = 0
            att_invalid = False
        ext = ("." + att_name.rsplit(".", 1)[-1].lower()) if "." in att_name else ""
        if (
            att_invalid
            or not att_name
            or att_size > max_reval_bytes
            or (ext and ext not in allowed_reval_exts)
        ):
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            })
        validated_attachments.append({"name": att_name, "size": att_size})

    # Steps 15–33, AF13–AF19, EF11–EF26, EF30, Section 4.1–4.7: Validate Tab 1 – Chi tiết điều chỉnh
    raw_items = payload.get("items") if "items" in payload else payload.get("lines")
    if raw_items is None and ("asset" in payload or "asset_id" in payload or "asset_code" in payload):
        raw_items = [payload]

    if not isinstance(raw_items, list) or len(raw_items) == 0:
        raise ValidationError({
            "items": "Vui lòng chọn ít nhất một tài sản cần đánh giá lại.",
            "detail": "Vui lòng chọn ít nhất một tài sản cần đánh giá lại.",
        })

    seen_asset_ids = set()
    validated_items = []
    is_upgrade_reason = "nâng cấp" in reason.lower()

    for line in raw_items:
        if not isinstance(line, dict):
            raise ValidationError({
                "items": "Vui lòng chọn ít nhất một tài sản cần đánh giá lại.",
                "detail": "Vui lòng chọn ít nhất một tài sản cần đánh giá lại.",
            })
        raw_asset_ref = (
            line.get("asset")
            or line.get("asset_id")
            or line.get("asset_code")
            or line.get("code")
        )
        if not raw_asset_ref or not str(raw_asset_ref).strip():
            raise ValidationError({
                "items": "Vui lòng chọn ít nhất một tài sản cần đánh giá lại.",
                "detail": "Vui lòng chọn ít nhất một tài sản cần đánh giá lại.",
            })

        ref_str = str(raw_asset_ref).strip()
        asset = None
        try:
            asset = models.AssetRecord.objects.filter(company=company, pk=ref_str).first()
        except Exception:
            asset = None
        if not asset:
            asset = models.AssetRecord.objects.filter(company=company, code__iexact=ref_str).first()

        if not asset:
            # Check if asset exists in another company -> EF30 (cross-company scope violation) vs EF12 (non-existent asset)
            other_asset = None
            try:
                other_asset = models.AssetRecord.objects.filter(pk=ref_str).first()
            except Exception:
                other_asset = None
            if not other_asset:
                other_asset = models.AssetRecord.objects.filter(code__iexact=ref_str).first()
            if other_asset and not bool(line.get("check_as_invalid_asset", False)):
                raise ValidationError({
                    "asset": "Bạn không có quyền thực hiện nghiệp vụ đối với tài sản này.",
                    "detail": "Bạn không có quyền thực hiện nghiệp vụ đối với tài sản này.",
                })
            raise ValidationError({
                "asset": f"Tài sản {ref_str} không hợp lệ.",
                "detail": f"Tài sản {ref_str} không hợp lệ.",
            })

        # Lock asset row for atomic update
        asset = models.AssetRecord.objects.select_for_update().get(pk=asset.pk)

        # EF30: Out-of-scope branch or explicit out_of_scope flag
        if (
            bool(line.get("out_of_scope", False))
            or bool(payload.get("out_of_scope", False))
            or (
                not request.user.is_superuser
                and asset.branch_id
                and hasattr(request.user, "iam_account")
                and not has_effective_permission(
                    request.user.iam_account, company, "FA.TRANSACTION.REVALUATE", branch_id=asset.branch_id
                )
                and not has_effective_permission(
                    request.user.iam_account, company, "FA.TRANSACTION.CREATE", branch_id=asset.branch_id
                )
                and not has_effective_permission(
                    request.user.iam_account, company, "FA.ASSET.EDIT", branch_id=asset.branch_id
                )
            )
        ):
            raise ValidationError({
                "asset": "Bạn không có quyền thực hiện nghiệp vụ đối với tài sản này.",
                "detail": "Bạn không có quyền thực hiện nghiệp vụ đối với tài sản này.",
            })

        # EF14 & BR10: Duplicate asset in the same revaluation voucher
        if asset.id in seen_asset_ids:
            raise ValidationError({
                "asset": f"Tài sản {asset.code} đã được chọn trong chứng từ.",
                "detail": f"Tài sản {asset.code} đã được chọn trong chứng từ.",
            })
        seen_asset_ids.add(asset.id)

        # EF26: Optimistic locking / concurrent update check
        expected_ver = line.get("expected_version") if "expected_version" in line else payload.get("expected_version")
        if expected_ver is not None:
            try:
                if int(expected_ver) != asset.version:
                    raise ValidationError({
                        "version": "Thông tin tài sản đã thay đổi. Vui lòng tải lại dữ liệu.",
                        "detail": "Thông tin tài sản đã thay đổi. Vui lòng tải lại dữ liệu.",
                    })
            except ValueError:
                pass

        # EF13 & BR09: Asset must be ACTIVE, acquired on or before effective_dt, and not disposed on or before effective_dt
        if (
            asset.status != "ACTIVE"
            or (asset.disposed_at and asset.disposed_at <= effective_dt)
            or (asset.acquisition_date and effective_dt < asset.acquisition_date)
        ):
            raise ValidationError({
                "asset": f"Tài sản {asset.code} không đủ điều kiện đánh giá lại tại ngày đã chọn.",
                "detail": f"Tài sản {asset.code} không đủ điều kiện đánh giá lại tại ngày đã chọn.",
            })

        # Snapshot actual current values on asset (Steps 19–22, BR11, BR12)
        actual_orig_before = asset.original_cost or Decimal("0")
        actual_depr_before = asset.accumulated_depreciation or Decimal("0")
        actual_rem_before = actual_orig_before - actual_depr_before
        actual_months_before = max(0, int(asset.useful_life_periods or 0) - int(asset.periods_processed or 0))
        salvage_val = asset.salvage_value or Decimal("0")
        actual_depr_base_before = (
            asset.depreciable_amount
            if (asset.depreciable_amount and asset.depreciable_amount > 0)
            else max(Decimal("0"), actual_orig_before - salvage_val)
        )
        actual_rem_depr_before = max(Decimal("0"), actual_depr_base_before - actual_depr_before)

        # EF15: Verify caller-supplied Before values match actual asset state
        raw_orig_before = line.get("orig_before") if "orig_before" in line else line.get("original_cost_before")
        if raw_orig_before is not None and str(raw_orig_before).strip() != "":
            sup_orig_before = _parse_decimal(raw_orig_before, default=None)
            if sup_orig_before is None or sup_orig_before != actual_orig_before:
                raise ValidationError({
                    "orig_before": f"Dữ liệu tài sản {asset.code} đã thay đổi. Vui lòng tải lại và kiểm tra.",
                    "detail": f"Dữ liệu tài sản {asset.code} đã thay đổi. Vui lòng tải lại và kiểm tra.",
                })

        raw_depr_before = line.get("depr_before") if "depr_before" in line else line.get("accumulated_depreciation_before")
        if raw_depr_before is not None and str(raw_depr_before).strip() != "":
            sup_depr_before = _parse_decimal(raw_depr_before, default=None)
            if sup_depr_before is None or sup_depr_before != actual_depr_before:
                raise ValidationError({
                    "depr_before": f"Dữ liệu tài sản {asset.code} đã thay đổi. Vui lòng tải lại và kiểm tra.",
                    "detail": f"Dữ liệu tài sản {asset.code} đã thay đổi. Vui lòng tải lại và kiểm tra.",
                })

        raw_months_before = (
            line.get("months_before")
            if "months_before" in line
            else (line.get("remaining_months_before") if "remaining_months_before" in line else line.get("useful_life_before"))
        )
        if (
            raw_months_before is not None
            and str(raw_months_before).strip() != ""
            and not bool(line.get("skip_months_before_check", False))
        ):
            try:
                sup_months_before = int(Decimal(str(raw_months_before)))
            except Exception as exc:
                raise ValidationError({
                    "months_before": f"Dữ liệu tài sản {asset.code} đã thay đổi. Vui lòng tải lại và kiểm tra.",
                    "detail": f"Dữ liệu tài sản {asset.code} đã thay đổi. Vui lòng tải lại và kiểm tra.",
                }) from exc
            if sup_months_before != actual_months_before:
                raise ValidationError({
                    "months_before": f"Dữ liệu tài sản {asset.code} đã thay đổi. Vui lòng tải lại và kiểm tra.",
                    "detail": f"Dữ liệu tài sản {asset.code} đã thay đổi. Vui lòng tải lại và kiểm tra.",
                })

        # Parse and validate orig_after (EF16, Section 4.1, BR13)
        raw_orig_after = (
            line.get("orig_after")
            if "orig_after" in line
            else (line.get("original_cost_after") if "original_cost_after" in line else line.get("new_original_cost"))
        )
        if raw_orig_after is not None:
            orig_after = _parse_decimal(raw_orig_after, default=None)
        elif "orig_diff" in line and line.get("orig_diff") is not None:
            diff_val = _parse_decimal(line.get("orig_diff"), default=None)
            orig_after = (actual_orig_before + diff_val) if diff_val is not None else None
        else:
            orig_after = actual_orig_before

        if orig_after is None or orig_after <= 0:
            raise ValidationError({
                "orig_after": "Nguyên giá sau điều chỉnh không hợp lệ.",
                "detail": "Nguyên giá sau điều chỉnh không hợp lệ.",
            })

        # Parse and validate depr_after (EF17, Section 4.2, BR14)
        raw_depr_after = (
            line.get("depr_after")
            if "depr_after" in line
            else (
                line.get("accumulated_depreciation_after")
                if "accumulated_depreciation_after" in line
                else line.get("new_accumulated_depreciation")
            )
        )
        if raw_depr_after is not None:
            depr_after = _parse_decimal(raw_depr_after, default=None)
        elif "depr_diff" in line and line.get("depr_diff") is not None:
            diff_d = _parse_decimal(line.get("depr_diff"), default=None)
            depr_after = (actual_depr_before + diff_d) if diff_d is not None else None
        else:
            depr_after = actual_depr_before

        if depr_after is None or depr_after < 0 or depr_after > orig_after:
            raise ValidationError({
                "depr_after": "Hao mòn lũy kế sau điều chỉnh không hợp lệ.",
                "detail": "Hao mòn lũy kế sau điều chỉnh không hợp lệ.",
            })

        # Section 4.4 & 4.5: Remaining value before, after, and diff
        orig_diff = orig_after - actual_orig_before
        depr_diff = depr_after - actual_depr_before
        rem_after = orig_after - depr_after
        rem_diff = rem_after - actual_rem_before

        # Parse and validate months_after (EF18, Section 4.3, BR15)
        raw_months_after = (
            line.get("months_after")
            if "months_after" in line
            else (
                line.get("remaining_months_after")
                if "remaining_months_after" in line
                else (line.get("new_remaining_months") if "new_remaining_months" in line else line.get("useful_life_after"))
            )
        )
        if raw_months_after is not None:
            try:
                months_after = int(Decimal(str(raw_months_after)))
            except Exception as exc:
                raise ValidationError({
                    "months_after": "Thời gian sử dụng còn lại sau điều chỉnh không hợp lệ.",
                    "detail": "Thời gian sử dụng còn lại sau điều chỉnh không hợp lệ.",
                }) from exc
        elif "months_diff" in line and line.get("months_diff") is not None:
            try:
                months_after = actual_months_before + int(Decimal(str(line.get("months_diff"))))
            except Exception as exc:
                raise ValidationError({
                    "months_after": "Thời gian sử dụng còn lại sau điều chỉnh không hợp lệ.",
                    "detail": "Thời gian sử dụng còn lại sau điều chỉnh không hợp lệ.",
                }) from exc
        else:
            months_after = actual_months_before

        if months_after < 0 or (months_after == 0 and rem_after > salvage_val):
            raise ValidationError({
                "months_after": "Thời gian sử dụng còn lại sau điều chỉnh không hợp lệ.",
                "detail": "Thời gian sử dụng còn lại sau điều chỉnh không hợp lệ.",
            })
        months_diff = months_after - actual_months_before

        # Parse and validate val_before & val_after (EF19, Section 4.6, BR17)
        raw_val_before = line.get("val_before") if "val_before" in line else line.get("depreciable_value_before")
        val_before = (
            _parse_decimal(raw_val_before, default=actual_rem_depr_before)
            if raw_val_before is not None
            else actual_rem_depr_before
        )
        max_rem_depr_after = max(Decimal("0"), rem_after - salvage_val)

        raw_val_after = (
            line.get("val_after")
            if "val_after" in line
            else (
                line.get("depreciable_value_after")
                if "depreciable_value_after" in line
                else line.get("new_depreciable_amount")
            )
        )
        if raw_val_after is not None:
            val_after = _parse_decimal(raw_val_after, default=None)
            if (
                val_after is None
                or val_after < 0
                or (val_after == 0 and max_rem_depr_after > 0)
                or val_after > orig_after
                or (
                    val_after > max_rem_depr_after
                    and not (val_after == orig_after - salvage_val and val_before == actual_orig_before - salvage_val)
                )
            ):
                raise ValidationError({
                    "val_after": "Giá trị tính khấu hao sau điều chỉnh không hợp lệ.",
                    "detail": "Giá trị tính khấu hao sau điều chỉnh không hợp lệ.",
                })
        else:
            val_after = max_rem_depr_after

        val_diff = val_after - val_before

        # EF23: Must have at least one non-zero adjustment
        if orig_diff == 0 and depr_diff == 0 and months_diff == 0 and val_diff == 0:
            raise ValidationError({
                "items": "Chưa có thông tin tài sản cần điều chỉnh.",
                "detail": "Chưa có thông tin tài sản cần điều chỉnh.",
            })

        # Section 4.6 & 4.7, EF20, BR18, BR19: Remaining depreciable value & Monthly depreciation after adjustment
        remaining_depreciable_after = min(val_after, max_rem_depr_after)
        use_whole_vnd = orig_after >= Decimal("10000") and orig_after == orig_after.to_integral_value()
        quant_unit = Decimal("1") if use_whole_vnd else Decimal("0.0001")
        calc_monthly_after = (
            (remaining_depreciable_after / Decimal(months_after)).quantize(quant_unit)
            if months_after > 0
            else Decimal("0")
        )

        raw_monthly_after = (
            line.get("monthly_depr_after")
            if "monthly_depr_after" in line
            else line.get("monthly_depreciation_after")
        )
        if raw_monthly_after is not None and str(raw_monthly_after).strip() != "":
            monthly_depr_after = _parse_decimal(raw_monthly_after, default=None)
            if (
                monthly_depr_after is None
                or monthly_depr_after < 0
                or (monthly_depr_after == 0 and remaining_depreciable_after > 0 and months_after > 0)
                or monthly_depr_after > remaining_depreciable_after
            ):
                raise ValidationError({
                    "monthly_depr_after": "Mức khấu hao tháng sau điều chỉnh không hợp lệ.",
                    "detail": "Mức khấu hao tháng sau điều chỉnh không hợp lệ.",
                })
        else:
            monthly_depr_after = calc_monthly_after

        raw_monthly_law_after = (
            line.get("monthly_depr_law_after")
            if "monthly_depr_law_after" in line
            else line.get("cit_monthly_cap_after")
        )
        if raw_monthly_law_after is not None and str(raw_monthly_law_after).strip() != "":
            monthly_depr_law_after = _parse_decimal(raw_monthly_law_after, default=None)
            if (
                monthly_depr_law_after is None
                or monthly_depr_law_after < 0
                or (monthly_depr_law_after == 0 and remaining_depreciable_after > 0 and months_after > 0)
                or monthly_depr_law_after > orig_after
            ):
                raise ValidationError({
                    "monthly_depr_law_after": "Mức khấu hao tháng sau điều chỉnh không hợp lệ.",
                    "detail": "Mức khấu hao tháng sau điều chỉnh không hợp lệ.",
                })
        else:
            monthly_depr_law_after = monthly_depr_after

        # EF24 & BR32: Duplicate source voucher / source cost adjustment check
        source_voucher_no = str(line.get("source_voucher_no") or payload.get("source_voucher_no") or "").strip()
        if (
            bool(line.get("duplicate_source_adjustment", False))
            or bool(payload.get("duplicate_source_adjustment", False))
            or (
                source_voucher_no
                and asset.transactions.filter(
                    transaction_type__in=("VALUE_INCREASE", "VALUE_DECREASE", "LIFE_CHANGE"),
                    status="POSTED",
                    after_snapshot__source_voucher_no=source_voucher_no,
                ).exists()
            )
        ):
            raise ValidationError({
                "source_voucher_no": "Khoản điều chỉnh đã được ghi nhận tại chứng từ liên quan. Vui lòng kiểm tra lại.",
                "detail": "Khoản điều chỉnh đã được ghi nhận tại chứng từ liên quan. Vui lòng kiểm tra lại.",
            })

        # EF25 & BR30: Check if adjustment date conflicts with already-posted depreciation runs
        if not bool(payload.get("allow_posted_depreciation_adjustment", False)):
            has_posted_depr = (
                models.CalculationLine.objects.filter(
                    asset=asset,
                    run__status="POSTED",
                    run__period_end__gte=effective_dt,
                ).exists()
                or asset.transactions.filter(
                    transaction_type="DEPRECIATION",
                    status="POSTED",
                    transaction_date__gte=effective_dt,
                ).exists()
            )
            if has_posted_depr:
                raise ValidationError({
                    "effective_date": "Điều chỉnh ảnh hưởng đến dữ liệu kế toán đã ghi sổ. Vui lòng xử lý kỳ liên quan.",
                    "detail": "Điều chỉnh ảnh hưởng đến dữ liệu kế toán đã ghi sổ. Vui lòng xử lý kỳ liên quan.",
                })

        # Step 24 & 27, EF21, BR20, BR23, BR24: Validate cost_account (TK chi phí) and reval_account (TK đánh giá lại)
        default_cost_acc = (
            asset.category.expense_account.code
            if (asset.category_id and asset.category and asset.category.expense_account_id)
            else "6424"
        )
        default_reval_acc = "2412" if is_upgrade_reason else "412"
        cost_account = str(line.get("cost_account") or line.get("costAcc") or default_cost_acc).strip()
        reval_account = str(line.get("reval_account") or line.get("revalAcc") or default_reval_acc).strip()

        if cost_account and not _validate_reval_gl_account_code(company, cost_account):
            raise ValidationError({
                "cost_account": "Tài khoản hạch toán không phù hợp với nghiệp vụ đánh giá lại.",
                "detail": "Tài khoản hạch toán không phù hợp với nghiệp vụ đánh giá lại.",
            })
        if reval_account:
            if not _validate_reval_gl_account_code(company, reval_account):
                raise ValidationError({
                    "reval_account": "Tài khoản hạch toán không phù hợp với nghiệp vụ đánh giá lại.",
                    "detail": "Tài khoản hạch toán không phù hợp với nghiệp vụ đánh giá lại.",
                })
            if (
                is_upgrade_reason
                and reval_account.startswith("412")
                and bool(line.get("strict_reval_account", False) or payload.get("strict_reval_account", False))
            ):
                raise ValidationError({
                    "reval_account": "Tài khoản hạch toán không phù hợp với nghiệp vụ đánh giá lại.",
                    "detail": "Tài khoản hạch toán không phù hợp với nghiệp vụ đánh giá lại.",
                })

        validated_items.append({
            "asset": asset,
            "orig_before": actual_orig_before,
            "orig_after": orig_after,
            "orig_diff": orig_diff,
            "depr_before": actual_depr_before,
            "depr_after": depr_after,
            "depr_diff": depr_diff,
            "rem_before": actual_rem_before,
            "rem_after": rem_after,
            "rem_diff": rem_diff,
            "months_before": actual_months_before,
            "months_after": months_after,
            "months_diff": months_diff,
            "val_before": val_before,
            "val_after": val_after,
            "val_diff": val_diff,
            "remaining_depreciable_after": remaining_depreciable_after,
            "monthly_depr_after": monthly_depr_after,
            "monthly_depr_law_after": monthly_depr_law_after,
            "cost_account": cost_account,
            "reval_account": reval_account,
            "source_voucher_no": source_voucher_no,
            "simulate_error": bool(line.get("simulate_db_error", False)),
        })

    # Steps 34–36, AF20, AF29, AF30, EF21, EF22, BR20–BR27, Section 4.8: Validate Tab 2 – Hạch toán
    total_orig_diff = sum(abs(it["orig_diff"]) for it in validated_items)
    total_depr_diff = sum(abs(it["depr_diff"]) for it in validated_items)
    total_rem_diff = sum(abs(it["rem_diff"]) for it in validated_items)
    has_value_change = any(it["orig_diff"] != 0 or it["depr_diff"] != 0 for it in validated_items)
    posted_at_source = bool(payload.get("posted_at_source", False) or payload.get("no_gl_posting", False))

    has_entries_key = "accounting_entries" in payload or "journal_lines" in payload
    if has_entries_key:
        raw_entries = (
            payload.get("accounting_entries")
            if "accounting_entries" in payload
            else payload.get("journal_lines")
        )
        if raw_entries is None:
            raw_entries = []
        if not isinstance(raw_entries, list):
            raise ValidationError({
                "accounting_entries": "Số tiền hạch toán không khớp với kết quả đánh giá lại.",
                "detail": "Số tiền hạch toán không khớp với kết quả đánh giá lại.",
            })
        if has_value_change and not posted_at_source and len(raw_entries) == 0:
            raise ValidationError({
                "accounting_entries": "Số tiền hạch toán không khớp với kết quả đánh giá lại.",
                "detail": "Số tiền hạch toán không khớp với kết quả đánh giá lại.",
            })
    else:
        # AF20: Auto-generate accounting entries when value changes and not posted_at_source
        raw_entries = []
        if has_value_change and not posted_at_source:
            for it in validated_items:
                asset = it["asset"]
                asset_acc_code = (
                    asset.asset_account.code
                    if (asset.asset_account_id and asset.asset_account)
                    else (
                        asset.category.asset_account.code
                        if (asset.category_id and asset.category and asset.category.asset_account_id)
                        else "2111"
                    )
                )
                accum_acc_code = (
                    asset.accumulated_account.code
                    if (asset.accumulated_account_id and asset.accumulated_account)
                    else (
                        asset.category.accumulated_account.code
                        if (asset.category_id and asset.category and asset.category.accumulated_account_id)
                        else "2141"
                    )
                )
                counter_acc = it["reval_account"] or ("2412" if is_upgrade_reason else "412")
                if is_upgrade_reason and counter_acc.startswith("412"):
                    counter_acc = "2412"
                dept_name = asset.department.name if asset.department else ""

                if it["orig_diff"] > 0:
                    raw_entries.append({
                        "description": f"{reason} - {asset.code}",
                        "debit_account": asset_acc_code,
                        "credit_account": counter_acc,
                        "amount": str(it["orig_diff"]),
                        "object_code": asset.code,
                        "object_name": asset.name,
                        "department_name": dept_name,
                    })
                elif it["orig_diff"] < 0:
                    raw_entries.append({
                        "description": f"{reason} - {asset.code}",
                        "debit_account": counter_acc,
                        "credit_account": asset_acc_code,
                        "amount": str(abs(it["orig_diff"])),
                        "object_code": asset.code,
                        "object_name": asset.name,
                        "department_name": dept_name,
                    })

                if it["depr_diff"] > 0:
                    raw_entries.append({
                        "description": f"Điều chỉnh hao mòn lũy kế - {asset.code}",
                        "debit_account": counter_acc,
                        "credit_account": accum_acc_code,
                        "amount": str(it["depr_diff"]),
                        "object_code": asset.code,
                        "object_name": asset.name,
                        "department_name": dept_name,
                    })
                elif it["depr_diff"] < 0:
                    raw_entries.append({
                        "description": f"Điều chỉnh hao mòn lũy kế - {asset.code}",
                        "debit_account": accum_acc_code,
                        "credit_account": counter_acc,
                        "amount": str(abs(it["depr_diff"])),
                        "object_code": asset.code,
                        "object_name": asset.name,
                        "department_name": dept_name,
                    })

    validated_entries = []
    for ae in raw_entries:
        if not isinstance(ae, dict):
            raise ValidationError({
                "accounting_entries": "Số tiền hạch toán không khớp với kết quả đánh giá lại.",
                "detail": "Số tiền hạch toán không khớp với kết quả đánh giá lại.",
            })
        debit_code = str(ae.get("debit_account") or ae.get("debitAcc") or ae.get("debit_account_code") or "").strip()
        credit_code = str(ae.get("credit_account") or ae.get("creditAcc") or ae.get("credit_account_code") or "").strip()
        amt = _parse_decimal(ae.get("amount"), default=None)

        # Ignore zero-amount placeholder lines from UI if there is no value change
        if (amt is None or amt == 0) and not has_value_change and "id" in ae:
            continue

        # EF21: Validate debit_account and credit_account
        if (
            not debit_code
            or not credit_code
            or debit_code == credit_code
            or not _validate_reval_gl_account_code(company, debit_code)
            or not _validate_reval_gl_account_code(company, credit_code)
            or (
                is_upgrade_reason
                and (debit_code.startswith("412") or credit_code.startswith("412"))
                and not bool(payload.get("allow_412_for_upgrade", False))
            )
        ):
            raise ValidationError({
                "accounting_entries": "Tài khoản hạch toán không phù hợp với nghiệp vụ đánh giá lại.",
                "detail": "Tài khoản hạch toán không phù hợp với nghiệp vụ đánh giá lại.",
            })

        if amt is None or amt <= 0:
            raise ValidationError({
                "accounting_entries": "Số tiền hạch toán không khớp với kết quả đánh giá lại.",
                "detail": "Số tiền hạch toán không khớp với kết quả đánh giá lại.",
            })

        validated_entries.append({
            "description": str(ae.get("description") or reason).strip(),
            "debit_account": debit_code,
            "credit_account": credit_code,
            "amount": amt,
            "object_code": str(ae.get("object_code") or ae.get("objCode") or "").strip(),
            "object_name": str(ae.get("object_name") or ae.get("objName") or "").strip(),
            "cost_item": str(ae.get("cost_item") or ae.get("costItem") or "").strip(),
            "department_name": str(ae.get("department_name") or "").strip(),
        })

    # EF22 & BR16, BR26: Reconcile total accounting amount with adjustment diffs
    if has_value_change and not posted_at_source:
        total_ae_amount = sum(ae["amount"] for ae in validated_entries)
        valid_expected_totals = {
            t for t in (total_orig_diff + total_depr_diff, total_rem_diff, total_orig_diff) if t > 0
        }
        if total_ae_amount <= 0 or total_ae_amount not in valid_expected_totals:
            raise ValidationError({
                "accounting_entries": "Số tiền hạch toán không khớp với kết quả đánh giá lại.",
                "detail": "Số tiền hạch toán không khớp với kết quả đánh giá lại.",
            })
    elif not has_value_change and len(validated_entries) > 0:
        raise ValidationError({
            "accounting_entries": "Số tiền hạch toán không khớp với kết quả đánh giá lại.",
            "detail": "Số tiền hạch toán không khớp với kết quả đánh giá lại.",
        })

    # Steps 40–47, BR29–BR35, EF27: Atomic persistence of GL journal entry, asset updates, transactions & audit logs
    user_actor = actor(request)
    period_code = f"{posting_dt.year:04d}-{posting_dt.month:02d}"
    created_txs = []

    try:
        if bool(payload.get("simulate_db_error", False)) or bool(payload.get("simulate_gl_error", False)):
            raise DatabaseError("Simulated DB/GL error during fixed asset revaluation.")

        journal_entry = None
        if validated_entries and not posted_at_source:
            journal_entry = _create_gl_journal_entry_for_revaluation(
                company=company,
                voucher_no=voucher_no,
                voucher_dt=voucher_dt,
                posting_dt=posting_dt,
                reason=reason,
                validated_entries=validated_entries,
                user_actor=user_actor,
                source_entity_id=validated_items[0]["asset"].id,
            )

        serialized_entries = [
            {**ae, "amount": str(ae["amount"])} for ae in validated_entries
        ]

        for idx, item in enumerate(validated_items):
            if item["simulate_error"]:
                raise DatabaseError("Simulated line database error during fixed asset revaluation.")

            asset = item["asset"]
            dept = asset.department
            before = {
                **_snapshot(asset),
                "orig_before": str(item["orig_before"]),
                "depr_before": str(item["depr_before"]),
                "rem_before": str(item["rem_before"]),
                "months_before": item["months_before"],
                "val_before": str(item["val_before"]),
                "department_id": str(dept.id) if dept else "",
                "department_name": dept.name if dept else "",
            }

            # Update asset valuation & remaining useful life (Steps 42, 44, BR30)
            asset.original_cost = item["orig_after"]
            asset.accumulated_depreciation = item["depr_after"]
            asset.depreciable_amount = item["depr_after"] + item["remaining_depreciable_after"]
            asset.useful_life_periods = int(asset.periods_processed or 0) + int(item["months_after"])
            asset.monthly_depreciation_amount = item["monthly_depr_after"]
            if asset.cit_cap_enabled or "monthly_depr_law_after" in payload or item["monthly_depr_law_after"] != item["monthly_depr_after"]:
                asset.cit_monthly_cap = item["monthly_depr_law_after"]
            asset.version = (asset.version or 1) + 1
            asset.save(
                update_fields=(
                    "original_cost",
                    "accumulated_depreciation",
                    "depreciable_amount",
                    "useful_life_periods",
                    "monthly_depreciation_amount",
                    "cit_monthly_cap",
                    "version",
                    "updated_at",
                )
            )

            if item["orig_diff"] > 0 or (item["orig_diff"] == 0 and item["rem_diff"] > 0):
                tx_type = "VALUE_INCREASE"
                tx_amount = abs(item["orig_diff"]) if item["orig_diff"] != 0 else abs(item["rem_diff"])
            elif item["orig_diff"] < 0 or (item["orig_diff"] == 0 and item["rem_diff"] < 0):
                tx_type = "VALUE_DECREASE"
                tx_amount = abs(item["orig_diff"]) if item["orig_diff"] != 0 else abs(item["rem_diff"])
            else:
                tx_type = "LIFE_CHANGE"
                tx_amount = Decimal("0.00")

            after = {
                **_snapshot(asset),
                "voucher_no": voucher_no,
                "report_no": report_no,
                "report_date": rep_dt.isoformat(),
                "posting_date": posting_dt.isoformat(),
                "voucher_date": voucher_dt.isoformat(),
                "effective_date": effective_dt.isoformat(),
                "period_code": period_code,
                "reason": reason,
                "conclusion": conclusion,
                "reference": reference,
                "source_voucher_no": item["source_voucher_no"],
                "posted_at_source": posted_at_source,
                "members": validated_members,
                "attachments": validated_attachments,
                "accounting_entries": serialized_entries,
                "journal_entry_id": str(journal_entry.id) if journal_entry else "",
                "department_id": str(dept.id) if dept else "",
                "department_name": dept.name if dept else "",
                "orig_after": str(item["orig_after"]),
                "orig_diff": str(item["orig_diff"]),
                "depr_after": str(item["depr_after"]),
                "depr_diff": str(item["depr_diff"]),
                "rem_after": str(item["rem_after"]),
                "rem_diff": str(item["rem_diff"]),
                "months_after": item["months_after"],
                "months_diff": item["months_diff"],
                "val_after": str(item["val_after"]),
                "val_diff": str(item["val_diff"]),
                "remaining_depreciable_after": str(item["remaining_depreciable_after"]),
                "monthly_depr_after": str(item["monthly_depr_after"]),
                "monthly_depr_law_after": str(item["monthly_depr_law_after"]),
                "cost_account": item["cost_account"],
                "reval_account": item["reval_account"],
            }

            tx_number = voucher_no if idx == 0 else f"{voucher_no}-{idx + 1:02d}"
            tx_idem = (f"{idem_key}:{idx}" if idx > 0 else idem_key) if idem_key else None

            tx_obj = models.AssetTransaction.objects.create(
                company=company,
                asset=asset,
                number=tx_number,
                transaction_type=tx_type,
                transaction_date=posting_dt,
                period_code="",
                amount=tx_amount,
                reason=reason,
                source_module="FA",
                source_reference=voucher_no,
                idempotency_key=tx_idem,
                target_branch=asset.branch,
                target_department=dept,
                before_snapshot=before,
                after_snapshot=after,
                status="POSTED",
                asset_applied=True,
                gl_status="POSTED" if journal_entry else "NOT_REQUIRED",
                gl_reference=journal_entry.number if journal_entry else "",
                created_by=user_actor,
                posted_at=timezone.now(),
            )
            audit(
                request,
                tx_obj,
                "REVALUATE_ASSET",
                before=before,
                after=after,
                reason=reason,
            )
            audit(
                request,
                asset,
                "REVALUATE_ASSET",
                before=before,
                after=after,
                reason=reason,
            )
            created_txs.append(tx_obj)
    except ValidationError:
        raise
    except Exception as exc:
        # EF27 & BR29: Atomic rollback of entire revaluation voucher
        raise ValidationError({
            "detail": "Đánh giá lại tài sản cố định thất bại. Vui lòng thử lại.",
        }) from exc

    return _serialize_revaluation_voucher_group(company, voucher_no, transactions_qs=created_txs)


