def get_next_disposal_voucher_no(
    company,
    disposal_date=None,
    year_based: bool = False,
    prefix: str = "GGTS",
) -> str:
    """
    Step 7, AF03, BR06 (UC-FA-07):
    Auto-suggest next disposal voucher number (e.g. GGTS00001 -> GGTS00002),
    or year-based (e.g. GGTS-2026-00001) when year_based=True.
    """
    dt = _parse_date(disposal_date) if disposal_date else timezone.localdate()
    if not dt:
        dt = timezone.localdate()

    clean_prefix = (prefix or "GGTS").strip().upper()
    if year_based:
        effective_prefix = f"{clean_prefix}-{dt.year}-"
    else:
        effective_prefix = clean_prefix

    existing_numbers = set()
    tx_qs = models.AssetTransaction.objects.filter(
        company=company,
        transaction_type="DISPOSAL",
    ).values_list("number", "source_reference", "after_snapshot")

    for num, src_ref, after_snap in tx_qs:
        if num:
            existing_numbers.add(str(num).strip().upper())
        if src_ref:
            existing_numbers.add(str(src_ref).strip().upper())
        if isinstance(after_snap, dict) and after_snap.get("voucher_no"):
            existing_numbers.add(str(after_snap["voucher_no"]).strip().upper())

    max_seq = 0
    pattern = re.compile(r"^" + re.escape(effective_prefix) + r"(\d+)$", re.IGNORECASE)
    for val in existing_numbers:
        m = pattern.match(val)
        if m:
            try:
                seq = int(m.group(1))
                if seq > max_seq:
                    max_seq = seq
            except ValueError:
                pass

    next_seq = max_seq + 1
    candidate = f"{effective_prefix}{next_seq:05d}"
    while candidate.upper() in existing_numbers:
        next_seq += 1
        candidate = f"{effective_prefix}{next_seq:05d}"
    return candidate


def _create_gl_journal_entry_for_disposal(
    company,
    voucher_no: str,
    voucher_date,
    posting_date,
    reason: str,
    accounting_entries: list,
    user_actor,
    simulate_gl_failure: bool = False,
):
    """
    Step 34, BR32, BR36, BR37, Section 4.6–4.9 (UC-FA-07):
    Creates a POSTED JournalEntry and corresponding JournalLine rows in the General Ledger
    for the fixed asset disposal voucher.
    """
    import calendar
    import uuid
    from general_ledger.models import AccountingPeriod, JournalEntry, JournalLine
    from master_data.models import Currency

    if simulate_gl_failure:
        raise RuntimeError("Simulated GL posting failure for disposal")

    if not accounting_entries:
        return None

    gl_period = AccountingPeriod.objects.filter(
        company=company,
        start_date__lte=posting_date,
        end_date__gte=posting_date,
    ).first()
    if not gl_period:
        last_d = calendar.monthrange(posting_date.year, posting_date.month)[1]
        gl_period, _ = AccountingPeriod.objects.get_or_create(
            company=company,
            fiscal_year=posting_date.year,
            period_number=posting_date.month,
            defaults={
                "code": f"{posting_date.year:04d}-{posting_date.month:02d}",
                "start_date": date_cls(posting_date.year, posting_date.month, 1),
                "end_date": date_cls(posting_date.year, posting_date.month, last_d),
                "status": "OPEN",
            },
        )
    if gl_period.status != "OPEN":
        raise ValidationError({
            "posting_date": "Kỳ kế toán đã khóa, không thể ghi giảm tài sản.",
            "detail": "Kỳ kế toán đã khóa, không thể ghi giảm tài sản.",
        })

    vnd_currency = getattr(company, "accounting_currency", None) or Currency.objects.filter(code="VND").first()
    if not vnd_currency:
        vnd_currency = Currency.objects.create(code="VND", name="Đồng Việt Nam", decimal_places=0)

    branch = company.branches.first()
    je_number = f"GL-GGTS-{voucher_no}"
    seq = 1
    while JournalEntry.objects.filter(company=company, number=je_number).exists():
        seq += 1
        je_number = f"GL-GGTS-{voucher_no}-{seq}"

    total_amt = sum(Decimal(str(item["amount"])).quantize(Decimal("0.0001")) for item in accounting_entries)
    entry = JournalEntry.objects.create(
        company=company,
        branch=branch,
        period=gl_period,
        number=je_number,
        entry_type="SUBLEDGER",
        document_date=voucher_date,
        posting_date=posting_date,
        description=f"Ghi giảm TSCĐ ({reason}) - {voucher_no}",
        source_module="FA",
        source_event_id=f"FA_DISPOSAL:{company.id}:{voucher_no}:{seq}",
        source_entity_type="AssetTransaction",
        source_entity_id=uuid.uuid4(),
        status="POSTED",
        total_debit=total_amt,
        total_credit=total_amt,
        created_by=user_actor,
        posted_by=user_actor,
        posted_at=timezone.now(),
    )

    line_no = 1
    for item in accounting_entries:
        amt = Decimal(str(item["amount"])).quantize(Decimal("0.0001"))
        if amt <= 0:
            continue
        dr_acc = _ensure_gl_account_for_code(company, item["debit_account"], is_debit=True)
        cr_acc = _ensure_gl_account_for_code(company, item["credit_account"], is_debit=False)
        desc = str(item.get("description") or reason)[:500]
        asset_code = str(item.get("asset_code") or "")
        dims = {"asset_code": asset_code, "voucher_no": voucher_no, "reason": reason}

        JournalLine.objects.create(
            entry=entry,
            line_no=line_no,
            account=dr_acc,
            description=desc,
            debit=amt,
            credit=Decimal("0"),
            currency=vnd_currency,
            exchange_rate=Decimal("1"),
            foreign_amount=amt,
            dimensions=dims,
        )
        line_no += 1

        JournalLine.objects.create(
            entry=entry,
            line_no=line_no,
            account=cr_acc,
            description=desc,
            debit=Decimal("0"),
            credit=amt,
            currency=vnd_currency,
            exchange_rate=Decimal("1"),
            foreign_amount=amt,
            dimensions=dims,
        )
        line_no += 1

    return entry


def _serialize_disposal_voucher_group(company, voucher_no: str, transactions_qs=None) -> dict:
    """
    Build structured UC-FA-07 response representing the disposal voucher,
    its asset lines (Tab Tài sản), accounting entries (Tab Hạch toán), and attachments.
    """
    if transactions_qs is None:
        transactions_qs = (
            models.AssetTransaction.objects.filter(
                company=company,
                transaction_type="DISPOSAL",
            )
            .filter(models.Q(source_reference=voucher_no) | models.Q(number=voucher_no))
            .select_related("asset", "asset__department", "target_department", "created_by")
            .order_by("created_at", "number")
        )
    tx_list = list(transactions_qs)
    if not tx_list:
        return {}

    first_tx = tx_list[0]
    after_snap = first_tx.after_snapshot if isinstance(first_tx.after_snapshot, dict) else {}

    rows = []
    total_original_cost = Decimal("0.00")
    total_depreciable = Decimal("0.00")
    total_accumulated = Decimal("0.00")
    total_remaining = Decimal("0.00")

    for idx, tx in enumerate(tx_list, start=1):
        b_snap = tx.before_snapshot if isinstance(tx.before_snapshot, dict) else {}
        a_snap = tx.after_snapshot if isinstance(tx.after_snapshot, dict) else {}

        orig_val = Decimal(str(b_snap.get("original_cost") or tx.amount or "0"))
        depr_base_val = Decimal(str(b_snap.get("depreciable_amount") or orig_val))
        accum_val = Decimal(str(b_snap.get("accumulated_depreciation") or "0"))
        rem_val = Decimal(str(b_snap.get("remaining_value") or (orig_val - accum_val)))

        total_original_cost += orig_val
        total_depreciable += depr_base_val
        total_accumulated += accum_val
        total_remaining += rem_val

        rows.append({
            "line_no": idx,
            "transaction_id": str(tx.id),
            "asset_id": str(tx.asset_id),
            "asset_code": tx.asset.code,
            "asset_name": tx.asset.name,
            "department_id": str(a_snap.get("department_id") or (tx.asset.department_id or "")),
            "department_name": a_snap.get("department_name") or (tx.asset.department.name if tx.asset.department else ""),
            "original_cost": str(orig_val),
            "depreciable_amount": str(depr_base_val),
            "accumulated_depreciation": str(accum_val),
            "remaining_value": str(rem_val),
            "asset_account": a_snap.get("asset_account", "2111"),
            "accumulated_account": a_snap.get("accumulated_account", "2141"),
            "disposal_account": a_snap.get("disposal_account", "811"),
            "status_after": tx.asset.status,
            "disposed_at": tx.asset.disposed_at.isoformat() if tx.asset.disposed_at else "",
        })

    return {
        "voucher_no": after_snap.get("voucher_no") or voucher_no,
        "reason": after_snap.get("reason") or first_tx.reason,
        "posting_date": after_snap.get("posting_date") or first_tx.transaction_date.isoformat(),
        "voucher_date": after_snap.get("voucher_date") or first_tx.transaction_date.isoformat(),
        "effective_date": after_snap.get("effective_date") or first_tx.transaction_date.isoformat(),
        "period_code": after_snap.get("period_code") or first_tx.period_code,
        "reference": after_snap.get("reference") or "",
        "total_amount": str(total_original_cost),
        "total_original_cost": str(total_original_cost),
        "total_depreciable_amount": str(total_depreciable),
        "total_accumulated_depreciation": str(total_accumulated),
        "total_remaining_value": str(total_remaining),
        "status": first_tx.status,
        "status_display": "Đã ghi sổ" if first_tx.status == "POSTED" else "Chưa ghi sổ",
        "gl_status": first_tx.gl_status,
        "gl_reference": first_tx.gl_reference,
        "journal_entry_id": after_snap.get("journal_entry_id") or "",
        "rows": rows,
        "accounting_entries": after_snap.get("accounting_entries") or [],
        "attachments": after_snap.get("attachments") or [],
        "created_at": first_tx.created_at.isoformat() if first_tx.created_at else None,
        "posted_at": first_tx.posted_at.isoformat() if first_tx.posted_at else None,
        "message": "Ghi giảm tài sản cố định thành công.",
    }


def dispose_fixed_assets_uc07(request, data: dict | None = None) -> dict:
    """
    UC-FA-07 – Ghi giảm tài sản:
    End-to-end validation, accounting entry verification, asset status transition to DISPOSED,
    depreciation termination from effective date, GL posting, and audit logging across all 8 reasons:
    1. Nhượng bán, thanh lý (AF04, AF05, BR18-BR20, Section 4.7)
    2. Phát hiện thiếu khi kiểm kê (AF06, AF07, BR21-BR23, Section 4.8)
    3. Góp vốn vào công ty con (AF08, BR24-BR26)
    4. Góp vốn công ty liên doanh (AF09, BR24-BR26)
    5. Góp vốn vào công ty liên kết (AF10, BR24-BR26)
    6. Đầu tư dài hạn khác (AF11, BR24-BR26)
    7. Trả lại TSCĐ thuê tài chính (AF12, BR27, BR28, EF20)
    8. Chuyển TSCĐ thành CCDC (AF13, BR29, BR30, EF21, Section 4.9)
    """
    from iam.models import CompanyMembership
    from iam.permissions import has_effective_permission
    from organization.models import Company

    payload = data if data is not None else request.data
    company_id = (
        payload.get("company")
        or payload.get("company_id")
        or request.query_params.get("company_id")
    )
    if not company_id:
        raise ValidationError({"company": "Thiếu thông tin doanh nghiệp (company_id)."})

    try:
        company = Company.objects.get(pk=company_id)
    except (Company.DoesNotExist, ValueError) as exc:
        raise ValidationError({"company": "Doanh nghiệp không hợp lệ."}) from exc

    # EF01 & EF30: Permission & company scope check
    user = getattr(request, "user", None)
    if not user or not user.is_authenticated:
        raise PermissionDenied("Bạn không có quyền ghi giảm tài sản cố định.")

    if not user.is_superuser:
        if not hasattr(user, "iam_account"):
            raise PermissionDenied("Bạn không có quyền ghi giảm tài sản cố định.")
        user_memberships = CompanyMembership.objects.filter(user=user.iam_account)
        if user_memberships.exists() and not user_memberships.filter(company_id=company.id).exists():
            raise PermissionDenied("Bạn không có quyền ghi giảm tài sản này.")
        if not has_effective_permission(user.iam_account, company, "FA.TRANSACTION.DISPOSE"):
            raise PermissionDenied("Bạn không có quyền ghi giảm tài sản cố định.")

    # EF28 & BR39: Idempotency check for duplicate click / retry
    idem_key = str(payload.get("idempotency_key") or "").strip()
    if idem_key:
        existing_idem = models.AssetTransaction.objects.filter(
            company=company,
            transaction_type="DISPOSAL",
            idempotency_key=idem_key,
        ).first()
        if existing_idem:
            v_no = existing_idem.source_reference or existing_idem.number
            res = _serialize_disposal_voucher_group(company, v_no)
            res["idempotent_replayed"] = True
            return res

    # Step 4, EF02, BR02, BR03: Validate Lý do ghi giảm (must be one of the 8 allowed reasons)
    reason = str(payload.get("reason") or payload.get("disposal_reason") or "").strip()
    if not reason or reason not in UC_FA_07_DISPOSAL_REASON_RULES:
        raise ValidationError({
            "reason": "Vui lòng chọn lý do ghi giảm tài sản cố định.",
            "detail": "Vui lòng chọn lý do ghi giảm tài sản cố định.",
        })
    reason_rule = UC_FA_07_DISPOSAL_REASON_RULES[reason]
    reason_code = reason_rule["code"]

    # Step 5, EF03, BR04: Validate Ngày hạch toán
    raw_posting_date = payload.get("posting_date") or payload.get("accounting_date") or payload.get("transaction_date")
    posting_dt = _parse_date(raw_posting_date)
    if not posting_dt:
        raise ValidationError({
            "posting_date": "Vui lòng nhập ngày hạch toán hợp lệ.",
            "detail": "Vui lòng nhập ngày hạch toán hợp lệ.",
        })

    # Step 6, EF04, BR04: Validate Ngày chứng từ (must be valid date and <= posting_date)
    raw_voucher_date = payload.get("voucher_date") or payload.get("document_date") or raw_posting_date
    voucher_dt = _parse_date(raw_voucher_date)
    if not voucher_dt or voucher_dt > posting_dt:
        raise ValidationError({
            "voucher_date": "Vui lòng nhập ngày chứng từ hợp lệ.",
            "detail": "Vui lòng nhập ngày chứng từ hợp lệ.",
        })

    raw_effective_date = payload.get("effective_date") or raw_posting_date
    effective_dt = _parse_date(raw_effective_date) or posting_dt
    if effective_dt > posting_dt:
        raise ValidationError({
            "effective_date": "Vui lòng nhập ngày hạch toán hợp lệ.",
            "detail": "Vui lòng nhập ngày hạch toán hợp lệ.",
        })

    # EF05 & BR05: Check if accounting period is closed
    for check_dt in {posting_dt, effective_dt}:
        if _closed(company, check_dt):
            raise ValidationError({
                "posting_date": "Kỳ kế toán đã khóa, không thể ghi giảm tài sản.",
                "period": "Kỳ kế toán đã khóa, không thể ghi giảm tài sản.",
                "detail": "Kỳ kế toán đã khóa, không thể ghi giảm tài sản.",
            })
    period_code = f"{posting_dt.year:04d}-{posting_dt.month:02d}"

    # Step 7, AF03, EF06, EF07, BR06: Validate Số chứng từ
    year_based = bool(payload.get("year_based_numbering", False))
    prefix = str(payload.get("voucher_prefix") or "GGTS").strip()
    if "voucher_no" in payload or "number" in payload:
        raw_vno = payload.get("voucher_no") if "voucher_no" in payload else payload.get("number")
        voucher_no = str(raw_vno or "").strip()
        if not voucher_no or len(voucher_no) > 50 or not re.match(r"^[A-Za-z0-9Đđ_-]+$", voucher_no):
            raise ValidationError({
                "voucher_no": "Số chứng từ ghi giảm không hợp lệ.",
                "detail": "Số chứng từ ghi giảm không hợp lệ.",
            })
    else:
        voucher_no = get_next_disposal_voucher_no(
            company, disposal_date=posting_dt, year_based=year_based, prefix=prefix
        )

    # EF07: Duplicate voucher_no check within company
    dup_exists = (
        models.AssetTransaction.objects.filter(
            company=company,
            transaction_type="DISPOSAL",
        )
        .filter(models.Q(number__iexact=voucher_no) | models.Q(source_reference__iexact=voucher_no))
        .exists()
    )
    if dup_exists:
        raise ValidationError({
            "voucher_no": "Số chứng từ ghi giảm đã tồn tại.",
            "detail": "Số chứng từ ghi giảm đã tồn tại.",
        })

    reference = str(payload.get("reference") or payload.get("source_reference") or "").strip()

    # Step 28, EF29: Validate attachments (<= 5MB and allowed formats)
    raw_attachments = payload.get("attachments") or []
    if not isinstance(raw_attachments, list):
        raise ValidationError({
            "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
        })
    max_file_bytes = 5 * 1024 * 1024
    allowed_exts = {".pdf", ".doc", ".docx", ".xls", ".xlsx", ".png", ".jpg", ".jpeg", ".csv", ".txt"}
    validated_attachments = []
    for att in raw_attachments:
        if not isinstance(att, dict):
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            })
        file_name = str(att.get("name") or att.get("file_name") or "").strip()
        file_size = int(att.get("size") or att.get("file_size") or 0)
        if not file_name or file_size < 0 or file_size > max_file_bytes:
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            })
        dot_idx = file_name.rfind(".")
        ext = file_name[dot_idx:].lower() if dot_idx != -1 else ""
        if ext and ext not in allowed_exts:
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            })
        validated_attachments.append({
            "name": file_name,
            "size": file_size,
            "type": str(att.get("type") or att.get("content_type") or ""),
            "url": str(att.get("url") or ""),
        })

    # EF17, EF18, EF19, EF21: Check reason-specific supporting documents / legal basis when required
    require_docs = bool(payload.get("require_supporting_docs", False))
    has_doc_basis = bool(
        reference
        or validated_attachments
        or str(payload.get("decision_no") or "").strip()
        or str(payload.get("minutes_no") or "").strip()
    )
    if reason_code == "SALE_LIQUIDATION":
        if require_docs and not has_doc_basis:
            raise ValidationError({
                "reason": "Chưa đủ hồ sơ nhượng bán, thanh lý tài sản.",
                "detail": "Chưa đủ hồ sơ nhượng bán, thanh lý tài sản.",
            })
    elif reason_code == "INVENTORY_SHORTAGE":
        has_inv_basis = bool(has_doc_basis or str(payload.get("inventory_minutes_no") or "").strip())
        if require_docs and not has_inv_basis:
            raise ValidationError({
                "reason": "Chưa đủ hồ sơ xác nhận tài sản thiếu khi kiểm kê.",
                "detail": "Chưa đủ hồ sơ xác nhận tài sản thiếu khi kiểm kê.",
            })
    elif reason_code in ("CAPITAL_SUBSIDIARY", "CAPITAL_JOINT_VENTURE", "CAPITAL_ASSOCIATE", "OTHER_LONG_TERM_INVESTMENT"):
        recipient_entity = str(payload.get("recipient_entity") or payload.get("investee_name") or "").strip()
        if (require_docs and (not recipient_entity or not has_doc_basis)) or payload.get("missing_capital_contribution_docs"):
            raise ValidationError({
                "reason": "Chưa đủ thông tin hoặc hồ sơ góp vốn bằng tài sản cố định.",
                "detail": "Chưa đủ thông tin hoặc hồ sơ góp vốn bằng tài sản cố định.",
            })
    elif reason_code == "CONVERT_TO_CCDC":
        conversion_basis = str(payload.get("conversion_basis") or payload.get("allocation_plan") or "").strip()
        if (require_docs and not (conversion_basis or has_doc_basis)) or payload.get("missing_ccdc_conversion_docs"):
            raise ValidationError({
                "reason": "Chưa đủ căn cứ hoặc thông tin chuyển TSCĐ thành CCDC.",
                "detail": "Chưa đủ căn cứ hoặc thông tin chuyển TSCĐ thành CCDC.",
            })

    # Step 9–23, EF08: Validate asset rows (Tab Tài sản)
    raw_rows = payload.get("rows") or payload.get("items") or payload.get("assets")
    if raw_rows is None and (payload.get("asset") or payload.get("asset_id") or payload.get("asset_code")):
        raw_rows = [payload]

    if not isinstance(raw_rows, list) or len(raw_rows) == 0:
        raise ValidationError({
            "rows": "Vui lòng chọn ít nhất một tài sản cần ghi giảm.",
            "detail": "Vui lòng chọn ít nhất một tài sản cần ghi giảm.",
        })

    non_empty_rows = [
        r for r in raw_rows
        if isinstance(r, dict) and (r.get("asset") or r.get("asset_id") or r.get("asset_code") or r.get("assetCode"))
    ]
    if not non_empty_rows:
        raise ValidationError({
            "rows": "Vui lòng chọn ít nhất một tài sản cần ghi giảm.",
            "detail": "Vui lòng chọn ít nhất một tài sản cần ghi giảm.",
        })

    seen_asset_ids = set()
    seen_asset_codes = set()
    validated_items = []
    auto_accounting_entries = []
    total_original_cost = Decimal("0.00")

    for idx, row in enumerate(non_empty_rows):
        asset_id = row.get("asset") or row.get("asset_id")
        asset_code = str(row.get("asset_code") or row.get("assetCode") or "").strip()

        asset = None
        if asset_id:
            asset = models.AssetRecord.objects.select_related(
                "department", "branch", "category", "asset_account", "accumulated_account", "category__expense_account"
            ).filter(pk=asset_id).first()
        if not asset and asset_code:
            asset = models.AssetRecord.objects.select_related(
                "department", "branch", "category", "asset_account", "accumulated_account", "category__expense_account"
            ).filter(company=company, code__iexact=asset_code).first()
            if not asset:
                asset = models.AssetRecord.objects.select_related(
                    "department", "branch", "category", "asset_account", "accumulated_account", "category__expense_account"
                ).filter(code__iexact=asset_code).first()

        display_code = asset.code if asset else (asset_code or str(asset_id or f"#{idx + 1}"))

        # EF09: Asset does not exist
        if not asset:
            raise ValidationError({
                "asset": f"Tài sản {display_code} không hợp lệ.",
                "detail": f"Tài sản {display_code} không hợp lệ.",
            })

        # EF30: Cross-company asset or out of user's branch scope
        if str(asset.company_id) != str(company.id):
            raise PermissionDenied("Bạn không có quyền ghi giảm tài sản này.")
        if not user.is_superuser and asset.branch_id:
            if not has_effective_permission(
                user.iam_account, company, "FA.TRANSACTION.DISPOSE", branch_id=str(asset.branch_id)
            ):
                raise PermissionDenied("Bạn không có quyền ghi giảm tài sản này.")

        # EF12 & BR09: Duplicate asset in the same disposal voucher
        if str(asset.id) in seen_asset_ids or asset.code.upper() in seen_asset_codes:
            raise ValidationError({
                "rows": f"Tài sản {asset.code} đã được chọn trong chứng từ.",
                "detail": f"Tài sản {asset.code} đã được chọn trong chứng từ.",
            })
        seen_asset_ids.add(str(asset.id))
        seen_asset_codes.add(asset.code.upper())

        # EF11 & BR08: Asset already disposed
        if asset.status == models.AssetStatus.DISPOSED:
            raise ValidationError({
                "asset": f"Tài sản {asset.code} đã được ghi giảm.",
                "detail": f"Tài sản {asset.code} đã được ghi giảm.",
            })

        # EF10 & BR07: Asset not yet eligible (e.g. DRAFT or acquired after effective_date)
        if asset.status == models.AssetStatus.DRAFT or (
            asset.acquisition_date and asset.acquisition_date > effective_dt
        ):
            raise ValidationError({
                "asset": f"Tài sản {asset.code} chưa đủ điều kiện ghi giảm.",
                "detail": f"Tài sản {asset.code} chưa đủ điều kiện ghi giảm.",
            })

        # EF26 & BR38: Concurrent/existing disposal transaction for this asset
        has_other_disposal = models.AssetTransaction.objects.filter(
            company=company,
            asset=asset,
            transaction_type="DISPOSAL",
            status__in=("DRAFT", "PENDING_APPROVAL", "APPROVED", "POSTED"),
        ).exists()
        if has_other_disposal or row.get("has_concurrent_disposal") or payload.get("has_concurrent_disposal"):
            raise ValidationError({
                "asset": "Tài sản đang có nghiệp vụ ghi giảm khác. Vui lòng kiểm tra lại.",
                "detail": "Tài sản đang có nghiệp vụ ghi giảm khác. Vui lòng kiểm tra lại.",
            })

        # EF16 & BR12: Pending/uncompleted related transactions (depreciation, transfer, revaluation)
        has_unposted_depr = models.CalculationLine.objects.filter(
            asset=asset,
            run__company=company,
            run__calculation_type="DEPRECIATION",
            run__period_code__lte=period_code,
            run__status__in=("DRAFT", "CALCULATED"),
        ).exists()
        has_pending_tx = models.AssetTransaction.objects.filter(
            company=company,
            asset=asset,
            transaction_date__lte=posting_dt,
            status__in=("DRAFT", "PENDING_APPROVAL", "APPROVED"),
        ).exists()
        if has_unposted_depr or has_pending_tx or row.get("has_pending_related_tx") or payload.get("has_pending_related_tx"):
            raise ValidationError({
                "asset": "Tài sản có nghiệp vụ liên quan chưa hoàn tất. Vui lòng kiểm tra lại.",
                "detail": "Tài sản có nghiệp vụ liên quan chưa hoàn tất. Vui lòng kiểm tra lại.",
            })

        orig_db = (asset.original_cost or Decimal("0")).quantize(Decimal("0.01"))
        depr_base_db = (asset.depreciable_amount or orig_db).quantize(Decimal("0.01"))
        accum_db = (asset.accumulated_depreciation or Decimal("0")).quantize(Decimal("0.01"))
        rem_db = (orig_db - accum_db).quantize(Decimal("0.01"))

        # EF14 & BR10 & BR11: Validate accumulated depreciation (0 <= accumulated_depreciation <= original_cost)
        supplied_orig = _parse_decimal(row.get("original_cost", row.get("originalCost")), default=None)
        supplied_accum = _parse_decimal(
            row.get("accumulated_depreciation", row.get("accumulatedDepr")), default=None
        )
        supplied_rem = _parse_decimal(
            row.get("remaining_value", row.get("remainingValue")), default=None
        )

        ref_orig_for_check = supplied_orig.quantize(Decimal("0.01")) if supplied_orig is not None else orig_db
        ref_accum_for_check = supplied_accum.quantize(Decimal("0.01")) if supplied_accum is not None else accum_db

        if (
            accum_db < Decimal("0")
            or accum_db > orig_db
            or ref_accum_for_check < Decimal("0")
            or ref_accum_for_check > ref_orig_for_check
        ):
            raise ValidationError({
                "accumulated_depreciation": "Hao mòn lũy kế của tài sản không hợp lệ.",
                "detail": "Hao mòn lũy kế của tài sản không hợp lệ.",
            })

        # EF15 & BR11 & Section 4.1: Validate remaining_value == original_cost - accumulated_depreciation and >= 0
        if rem_db < Decimal("0") or (
            supplied_rem is not None
            and (
                supplied_rem.quantize(Decimal("0.01")) < Decimal("0")
                or supplied_rem.quantize(Decimal("0.01")) != (ref_orig_for_check - ref_accum_for_check).quantize(Decimal("0.01"))
            )
        ):
            raise ValidationError({
                "remaining_value": "Giá trị còn lại của tài sản không hợp lệ.",
                "detail": "Giá trị còn lại của tài sản không hợp lệ.",
            })

        # EF13: Check if asset snapshot changed since loaded on form
        expected_version = row.get("expected_version") or payload.get("expected_version")
        if expected_version is not None and int(expected_version) != int(asset.version or 1):
            raise ValidationError({
                "asset": f"Số liệu tài sản {asset.code} đã thay đổi. Vui lòng tải lại dữ liệu.",
                "detail": f"Số liệu tài sản {asset.code} đã thay đổi. Vui lòng tải lại dữ liệu.",
            })
        if (supplied_orig is not None and supplied_orig.quantize(Decimal("0.01")) != orig_db) or (
            supplied_accum is not None and supplied_accum.quantize(Decimal("0.01")) != accum_db
        ):
            raise ValidationError({
                "asset": f"Số liệu tài sản {asset.code} đã thay đổi. Vui lòng tải lại dữ liệu.",
                "detail": f"Số liệu tài sản {asset.code} đã thay đổi. Vui lòng tải lại dữ liệu.",
            })

        # Step 19, 20, EF22, BR13, BR14: Validate TK Nguyên giá & TK Hao mòn
        default_asset_acc = (
            asset.asset_account.code
            if asset.asset_account
            else (asset.category.asset_account.code if asset.category and asset.category.asset_account else "2111")
        )
        default_accum_acc = (
            asset.accumulated_account.code
            if asset.accumulated_account
            else (asset.category.accumulated_account.code if asset.category and asset.category.accumulated_account else "2141")
        )

        asset_acc = str(
            row.get("asset_account")
            or row.get("cost_account")
            or row.get("costAcc")
            or default_asset_acc
        ).strip()
        accum_acc = str(
            row.get("accumulated_account")
            or row.get("depr_account")
            or row.get("accumulatedAcc")
            or default_accum_acc
        ).strip()

        if not asset_acc.startswith(("211", "212", "213")) or not accum_acc.startswith("214"):
            raise ValidationError({
                "asset_account": "Tài khoản nguyên giá hoặc hao mòn TSCĐ không hợp lệ.",
                "detail": "Tài khoản nguyên giá hoặc hao mòn TSCĐ không hợp lệ.",
            })

        # AF12, EF20, BR27, BR28: If reason is "Trả lại TSCĐ thuê tài chính", asset must be finance lease
        is_finance_lease = bool(
            asset_acc.startswith("212")
            or accum_acc.startswith("2142")
            or row.get("is_finance_lease")
            or payload.get("is_finance_lease")
            or (asset.category and "thuê tài chính" in (asset.category.name or "").lower())
        )
        if reason_code == "RETURN_FINANCE_LEASE" and not is_finance_lease:
            raise ValidationError({
                "reason": "Tài sản không thuộc loại TSCĐ thuê tài chính.",
                "detail": "Tài sản không thuộc loại TSCĐ thuê tài chính.",
            })

        # Step 21, 22, EF23, BR15, BR16: Determine & validate TK Xử lý giá trị (disposal_account)
        is_welfare_asset = bool(row.get("is_welfare_asset") or payload.get("is_welfare_asset"))
        has_processing_decision = bool(row.get("has_processing_decision") or payload.get("has_processing_decision"))
        immediate_expense = bool(row.get("immediate_expense") or payload.get("immediate_expense"))
        allocation_periods = int(row.get("allocation_periods") or payload.get("allocation_periods") or 12)

        if reason_code == "SALE_LIQUIDATION" and is_welfare_asset:
            proposed_disposal_acc = "3532"
        elif reason_code == "INVENTORY_SHORTAGE" and has_processing_decision:
            proposed_disposal_acc = "1388"
        elif reason_code == "CONVERT_TO_CCDC" and (immediate_expense or allocation_periods <= 1):
            cat_exp = asset.category.expense_account if (asset.category and asset.category.expense_account) else None
            proposed_disposal_acc = (
                cat_exp.code
                if cat_exp and cat_exp.code.startswith(("627", "641", "642"))
                else "642"
            )
        else:
            proposed_disposal_acc = reason_rule["default_account"]

        raw_disp_acc = (
            row.get("disposal_account")
            or row.get("handling_account")
            or row.get("handlingAcc")
            or payload.get("disposal_account")
        )
        disposal_acc = str(raw_disp_acc if raw_disp_acc is not None else proposed_disposal_acc).strip()

        if not disposal_acc or not disposal_acc.startswith(reason_rule["allowed_prefixes"]):
            raise ValidationError({
                "disposal_account": "Tài khoản xử lý giá trị không phù hợp với lý do ghi giảm.",
                "detail": "Tài khoản xử lý giá trị không phù hợp với lý do ghi giảm.",
            })

        total_original_cost += orig_db

        # Step 24–27, AF18–AF20, Section 4.5–4.9: Build automatic accounting entries for this asset
        # 1) Derecognize accumulated depreciation (if > 0)
        if accum_db > Decimal("0"):
            if reason_code == "SALE_LIQUIDATION":
                depr_desc = "Ghi giảm hao mòn lũy kế TSCĐ do nhượng bán, thanh lý"
            elif reason_code == "INVENTORY_SHORTAGE":
                depr_desc = "Ghi giảm hao mòn lũy kế TSCĐ thiếu khi kiểm kê"
            elif reason_code == "CONVERT_TO_CCDC":
                depr_desc = "Ghi giảm hao mòn lũy kế khi chuyển TSCĐ thành CCDC"
            elif reason_code == "RETURN_FINANCE_LEASE":
                depr_desc = "Ghi giảm hao mòn lũy kế khi trả lại TSCĐ thuê tài chính"
            else:
                depr_desc = f"Ghi giảm hao mòn lũy kế TSCĐ ({reason})"

            auto_accounting_entries.append({
                "asset_code": asset.code,
                "description": depr_desc,
                "debit_account": accum_acc,
                "credit_account": asset_acc,
                "amount": str(accum_db),
            })

        # 2) Handle remaining value (ONLY when remaining_value > 0 per AF18, or capital contribution difference per Section 4.5)
        agreed_inv_val = _parse_decimal(
            row.get("agreed_investment_value") or payload.get("agreed_investment_value"),
            default=None,
        )
        comp_val = _parse_decimal(
            row.get("compensation_amount") or payload.get("compensation_amount"),
            default=None,
        )

        if reason_code in ("CAPITAL_SUBSIDIARY", "CAPITAL_JOINT_VENTURE", "CAPITAL_ASSOCIATE", "OTHER_LONG_TERM_INVESTMENT") and agreed_inv_val is not None:
            agreed_inv_val = agreed_inv_val.quantize(Decimal("0.01"))
            diff_val = (agreed_inv_val - rem_db).quantize(Decimal("0.01"))
            diff_acc = str(row.get("difference_account") or payload.get("difference_account") or ("711" if diff_val >= 0 else "811")).strip()
            if diff_val >= Decimal("0"):
                if rem_db > Decimal("0"):
                    auto_accounting_entries.append({
                        "asset_code": asset.code,
                        "description": f"Ghi nhận giá trị còn lại của TSCĐ đem đi {reason.lower()}",
                        "debit_account": disposal_acc,
                        "credit_account": asset_acc,
                        "amount": str(rem_db),
                    })
                if diff_val > Decimal("0"):
                    auto_accounting_entries.append({
                        "asset_code": asset.code,
                        "description": f"Chênh lệch đánh giá tăng TSCĐ đem đi {reason.lower()}",
                        "debit_account": disposal_acc,
                        "credit_account": diff_acc,
                        "amount": str(diff_val),
                    })
            else:
                loss_diff = abs(diff_val)
                if agreed_inv_val > Decimal("0"):
                    auto_accounting_entries.append({
                        "asset_code": asset.code,
                        "description": f"Ghi nhận khoản đầu tư khi {reason.lower()}",
                        "debit_account": disposal_acc,
                        "credit_account": asset_acc,
                        "amount": str(agreed_inv_val),
                    })
                if loss_diff > Decimal("0"):
                    auto_accounting_entries.append({
                        "asset_code": asset.code,
                        "description": f"Chênh lệch đánh giá giảm TSCĐ đem đi {reason.lower()}",
                        "debit_account": diff_acc,
                        "credit_account": asset_acc,
                        "amount": str(loss_diff),
                    })
        elif reason_code == "INVENTORY_SHORTAGE" and has_processing_decision and comp_val is not None and rem_db > Decimal("0"):
            comp_val = comp_val.quantize(Decimal("0.01"))
            loss_val = max(Decimal("0.00"), rem_db - comp_val)
            comp_acc = str(row.get("compensation_account") or payload.get("compensation_account") or "1388").strip()
            loss_acc = str(row.get("loss_account") or payload.get("loss_account") or "811").strip()
            if comp_val > Decimal("0"):
                auto_accounting_entries.append({
                    "asset_code": asset.code,
                    "description": "Ghi nhận khoản phải thu bồi thường TSCĐ thiếu khi kiểm kê",
                    "debit_account": comp_acc,
                    "credit_account": asset_acc,
                    "amount": str(comp_val),
                })
            if loss_val > Decimal("0"):
                auto_accounting_entries.append({
                    "asset_code": asset.code,
                    "description": "Ghi nhận phần tổn thất giá trị còn lại TSCĐ thiếu vào chi phí khác",
                    "debit_account": loss_acc,
                    "credit_account": asset_acc,
                    "amount": str(loss_val),
                })
        elif rem_db > Decimal("0"):
            # AF18: Only generate 2nd line when remaining_value > 0
            if reason_code == "SALE_LIQUIDATION":
                rem_desc = (
                    "Ghi giảm nguồn hình thành TSCĐ dùng cho phúc lợi"
                    if is_welfare_asset
                    else "Ghi nhận giá trị còn lại của TSCĐ vào chi phí khác"
                )
            elif reason_code == "INVENTORY_SHORTAGE":
                rem_desc = "Ghi nhận giá trị còn lại của TSCĐ thiếu chờ xử lý"
            elif reason_code == "CONVERT_TO_CCDC":
                rem_desc = (
                    "Kết chuyển giá trị còn lại sang chi phí trả trước"
                    if disposal_acc.startswith("242")
                    else "Kết chuyển giá trị còn lại vào chi phí sản xuất kinh doanh"
                )
            elif reason_code == "RETURN_FINANCE_LEASE":
                rem_desc = "Ghi nhận giá trị còn lại khi trả lại TSCĐ thuê tài chính"
            else:
                rem_desc = f"Ghi nhận giá trị còn lại của TSCĐ ({reason})"

            auto_accounting_entries.append({
                "asset_code": asset.code,
                "description": rem_desc,
                "debit_account": disposal_acc,
                "credit_account": asset_acc,
                "amount": str(rem_db),
            })

        validated_items.append({
            "asset": asset,
            "original_cost": orig_db,
            "depreciable_amount": depr_base_db,
            "accumulated_depreciation": accum_db,
            "remaining_value": rem_db,
            "asset_account": asset_acc,
            "accumulated_account": accum_acc,
            "disposal_account": disposal_acc,
        })

    # Step 24–27, AF21, AF22, EF24, EF25, BR36, BR37: Validate Tab Hạch toán
    raw_entries = payload.get("accounting_entries")
    if raw_entries is not None:
        if not isinstance(raw_entries, list) or len(raw_entries) == 0:
            raise ValidationError({
                "accounting_entries": "Bút toán ghi giảm không cân đối. Vui lòng kiểm tra lại.",
                "detail": "Bút toán ghi giảm không cân đối. Vui lòng kiểm tra lại.",
            })
        serialized_entries = []
        total_debit = Decimal("0.00")
        total_credit = Decimal("0.00")
        total_asset_cost_credit = Decimal("0.00")

        for idx, entry_row in enumerate(raw_entries, start=1):
            if not isinstance(entry_row, dict):
                raise ValidationError({
                    "accounting_entries": "Bút toán ghi giảm không cân đối. Vui lòng kiểm tra lại.",
                    "detail": "Bút toán ghi giảm không cân đối. Vui lòng kiểm tra lại.",
                })
            dr_acc = str(entry_row.get("debit_account") or entry_row.get("debitAccount") or "").strip()
            cr_acc = str(entry_row.get("credit_account") or entry_row.get("creditAccount") or "").strip()
            amt = _parse_decimal(entry_row.get("amount"), default=Decimal("0"))
            dr_amt = _parse_decimal(entry_row.get("debit_amount"), default=amt).quantize(Decimal("0.01"))
            cr_amt = _parse_decimal(entry_row.get("credit_amount"), default=amt).quantize(Decimal("0.01"))

            if not dr_acc or not cr_acc or dr_acc == cr_acc or dr_amt <= Decimal("0") or cr_amt <= Decimal("0") or dr_amt != cr_amt:
                raise ValidationError({
                    "accounting_entries": "Bút toán ghi giảm không cân đối. Vui lòng kiểm tra lại.",
                    "detail": "Bút toán ghi giảm không cân đối. Vui lòng kiểm tra lại.",
                })

            total_debit += dr_amt
            total_credit += cr_amt
            if cr_acc.startswith(("211", "212", "213")):
                total_asset_cost_credit += cr_amt

            serialized_entries.append({
                "line_no": idx,
                "asset_code": str(entry_row.get("asset_code") or validated_items[0]["asset"].code),
                "description": str(entry_row.get("description") or reason),
                "debit_account": dr_acc,
                "credit_account": cr_acc,
                "amount": str(dr_amt),
            })

        if total_debit != total_credit:
            raise ValidationError({
                "accounting_entries": "Bút toán ghi giảm không cân đối. Vui lòng kiểm tra lại.",
                "detail": "Bút toán ghi giảm không cân đối. Vui lòng kiểm tra lại.",
            })

        # EF25 & BR37: Total derecognized original cost on TK Nguyên giá must equal sum(original_cost)
        if total_asset_cost_credit != total_original_cost:
            raise ValidationError({
                "accounting_entries": "Số tiền ghi giảm nguyên giá không khớp với danh sách tài sản.",
                "detail": "Số tiền ghi giảm nguyên giá không khớp với danh sách tài sản.",
            })
    else:
        serialized_entries = [
            {"line_no": i + 1, **entry}
            for i, entry in enumerate(auto_accounting_entries)
        ]

    # Step 29–40, EF27, BR32, BR33, BR38, BR40: Atomic persistence of disposal voucher, GL entry, asset state, and audit logs
    simulate_db_failure = bool(payload.get("simulate_db_failure", False))
    simulate_gl_failure = bool(payload.get("simulate_gl_failure", False))
    user_actor = actor(request)
    created_txs = []

    try:
        with transaction.atomic():
            if simulate_db_failure:
                raise RuntimeError("Simulated database failure during asset disposal")

            journal_entry = _create_gl_journal_entry_for_disposal(
                company=company,
                voucher_no=voucher_no,
                voucher_date=voucher_dt,
                posting_date=posting_dt,
                reason=reason,
                accounting_entries=serialized_entries,
                user_actor=user_actor,
                simulate_gl_failure=simulate_gl_failure,
            )

            for idx, item in enumerate(validated_items):
                asset = models.AssetRecord.objects.select_for_update().get(pk=item["asset"].pk)
                dept = asset.department
                before = {
                    **_snapshot(asset),
                    "department_id": str(dept.id) if dept else "",
                    "department_name": dept.name if dept else "",
                    "original_cost": str(item["original_cost"]),
                    "depreciable_amount": str(item["depreciable_amount"]),
                    "accumulated_depreciation": str(item["accumulated_depreciation"]),
                    "remaining_value": str(item["remaining_value"]),
                }

                # Step 35, 36, BR32, BR33: Transition asset to DISPOSED and stop depreciation from effective_dt
                asset.status = models.AssetStatus.DISPOSED
                asset.disposed_at = effective_dt
                asset.version = (asset.version or 1) + 1
                asset.save(update_fields=("status", "disposed_at", "version", "updated_at"))

                after = {
                    **_snapshot(asset),
                    "voucher_no": voucher_no,
                    "reason": reason,
                    "reason_code": reason_code,
                    "posting_date": posting_dt.isoformat(),
                    "voucher_date": voucher_dt.isoformat(),
                    "effective_date": effective_dt.isoformat(),
                    "period_code": period_code,
                    "reference": reference,
                    "department_id": str(dept.id) if dept else "",
                    "department_name": dept.name if dept else "",
                    "asset_account": item["asset_account"],
                    "accumulated_account": item["accumulated_account"],
                    "disposal_account": item["disposal_account"],
                    "accounting_entries": serialized_entries,
                    "attachments": validated_attachments,
                    "journal_entry_id": str(journal_entry.id) if journal_entry else "",
                }

                tx_number = voucher_no if idx == 0 else f"{voucher_no}-{idx + 1:02d}"
                tx_idem = (f"{idem_key}:{idx}" if idx > 0 else idem_key) if idem_key else None

                tx_obj = models.AssetTransaction.objects.create(
                    company=company,
                    asset=asset,
                    number=tx_number,
                    transaction_type="DISPOSAL",
                    transaction_date=posting_dt,
                    period_code="",
                    amount=item["original_cost"],
                    reason=reason,
                    source_module="FA",
                    source_reference=voucher_no,
                    idempotency_key=tx_idem,
                    target_branch=asset.branch,
                    target_department=dept,
                    before_snapshot=before,
                    after_snapshot=after,
                    status="POSTED",
                    asset_applied=True,
                    gl_status="POSTED" if journal_entry else "NOT_REQUIRED",
                    gl_reference=journal_entry.number if journal_entry else "",
                    created_by=user_actor,
                    posted_at=timezone.now(),
                )
                audit(
                    request,
                    tx_obj,
                    "DISPOSE_ASSET",
                    before=before,
                    after=after,
                    reason=reason,
                )
                audit(
                    request,
                    asset,
                    "DISPOSE_ASSET",
                    before=before,
                    after=after,
                    reason=reason,
                )
                created_txs.append(tx_obj)
    except ValidationError:
        raise
    except Exception as exc:
        # EF27 & BR32: Atomic rollback on DB/GL failure
        raise ValidationError({
            "detail": "Ghi giảm tài sản cố định thất bại. Vui lòng thử lại.",
        }) from exc

    return _serialize_disposal_voucher_group(company, voucher_no, transactions_qs=created_txs)


