def get_next_stocktake_voucher_no(
    company,
    count_date=None,
    year_based: bool = False,
    prefix: str = "KKTS",
) -> str:
    """
    Step 6, AF03, BR04, BR05:
    Auto-suggests the next sequential stocktake voucher number (e.g. KKTS00001 -> KKTS00002,
    or KKTS-YYYY-00001 when year_based=True).
    """
    clean_prefix = (prefix or "KKTS").strip() or "KKTS"
    target_year = None
    if year_based:
        parsed_dt = _parse_date(count_date) if count_date else None
        target_year = (parsed_dt or timezone.localdate()).year
        effective_prefix = f"{clean_prefix}-{target_year}-"
    else:
        effective_prefix = clean_prefix

    existing_numbers = list(
        models.AssetCount.objects.filter(
            company=company,
            number__istartswith=effective_prefix,
        ).values_list("number", flat=True)
    )
    pattern = re.compile(rf"^{re.escape(effective_prefix)}(\d+)(?:-\d+)?$", re.IGNORECASE)
    max_seq = 0
    for raw_no in existing_numbers:
        m = pattern.match(str(raw_no or "").strip())
        if m:
            try:
                seq = int(m.group(1))
                if seq > max_seq:
                    max_seq = seq
            except ValueError:
                pass
    next_seq = max_seq + 1
    return f"{effective_prefix}{next_seq:05d}"


def _parse_stocktake_report_datetime(value, default_date: date_cls):
    """
    Step 7, BR06, EF05:
    Parses report creation date/datetime ('Ngày' trên biên bản kiểm kê), which can be
    DD/MM/YYYY, DD/MM/YYYY HH:MM:SS, YYYY-MM-DD, or ISO datetime.
    Returns (report_date_obj, formatted_datetime_str).
    """
    if value in (None, ""):
        return default_date, f"{default_date.strftime('%d/%m/%Y')} 08:00:00"
    if isinstance(value, datetime):
        dt_local = value.date()
        return dt_local, value.strftime("%d/%m/%Y %H:%M:%S")
    if isinstance(value, date_cls):
        return value, f"{value.strftime('%d/%m/%Y')} 08:00:00"

    raw = str(value).strip()
    if not raw:
        return default_date, f"{default_date.strftime('%d/%m/%Y')} 08:00:00"

    # Try DD/MM/YYYY HH:MM(:SS)
    m_dmy_dt = re.match(
        r"^(\d{1,2})/(\d{1,2})/(\d{4})(?:\s+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?$",
        raw,
    )
    if m_dmy_dt:
        d_i, mo_i, y_i = int(m_dmy_dt.group(1)), int(m_dmy_dt.group(2)), int(m_dmy_dt.group(3))
        hh_i = int(m_dmy_dt.group(4) or 8)
        mm_i = int(m_dmy_dt.group(5) or 0)
        ss_i = int(m_dmy_dt.group(6) or 0)
        try:
            dt_obj = datetime(y_i, mo_i, d_i, hh_i, mm_i, ss_i)
            return dt_obj.date(), dt_obj.strftime("%d/%m/%Y %H:%M:%S")
        except ValueError:
            return None, None

    # Try YYYY-MM-DD or ISO datetime
    m_ymd_dt = re.match(
        r"^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T\s](\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?",
        raw,
    )
    if m_ymd_dt:
        y_i, mo_i, d_i = int(m_ymd_dt.group(1)), int(m_ymd_dt.group(2)), int(m_ymd_dt.group(3))
        hh_i = int(m_ymd_dt.group(4) or 8)
        mm_i = int(m_ymd_dt.group(5) or 0)
        ss_i = int(m_ymd_dt.group(6) or 0)
        try:
            dt_obj = datetime(y_i, mo_i, d_i, hh_i, mm_i, ss_i)
            return dt_obj.date(), dt_obj.strftime("%d/%m/%Y %H:%M:%S")
        except ValueError:
            return None, None

    return None, None


def _reconstruct_asset_book_snapshot_at_count_date(asset, count_dt: date_cls) -> dict:
    """
    Steps 18–22, Section 4.1, BR11, BR15, BR16, BR17:
    Reconstructs book department, original_cost, depreciable_amount, accumulated_depreciation,
    and remaining_value = original_cost - accumulated_depreciation at count_dt.
    """
    dept_obj = asset.department
    future_transfer = (
        asset.transactions.filter(
            transaction_type="TRANSFER",
            status="POSTED",
            transaction_date__gt=count_dt,
        )
        .order_by("transaction_date", "created_at")
        .first()
    )
    if future_transfer and isinstance(future_transfer.before_snapshot, dict):
        prev_dept_id = future_transfer.before_snapshot.get("from_department_id") or future_transfer.before_snapshot.get("department")
        if prev_dept_id:
            prev_dept = Department.objects.filter(pk=prev_dept_id).first()
            if prev_dept:
                dept_obj = prev_dept

    orig = Decimal(str(asset.original_cost or Decimal("0"))).quantize(Decimal("0.01"))
    depr_base = Decimal(
        str(asset.depreciable_amount if asset.depreciable_amount and asset.depreciable_amount > 0 else orig)
    ).quantize(Decimal("0.01"))
    accum = Decimal(str(asset.accumulated_depreciation or Decimal("0"))).quantize(Decimal("0.01"))
    if accum < Decimal("0"):
        accum = Decimal("0.00")
    if accum > orig:
        accum = orig
    rem = (orig - accum).quantize(Decimal("0.01"))
    return {
        "book_department_id": str(dept_obj.id) if dept_obj else "",
        "book_department_name": dept_obj.name if dept_obj else "",
        "original_cost": orig,
        "depreciable_amount": depr_base,
        "accumulated_depreciation": accum,
        "remaining_value": rem,
    }


def _validate_uc08_attachments(raw_attachments) -> list:
    """
    Step 33, AF24, EF26, BR39, BR40:
    Validates stocktake attachments (<= 5MB per file, valid extensions).
    """
    if raw_attachments is None:
        return []
    if not isinstance(raw_attachments, list):
        raise ValidationError({
            "attachments": "Tệp đính kèm không hợp lệ hoặc vượt quá dung lượng cho phép (tối đa 5MB).",
            "detail": "Tệp đính kèm không hợp lệ hoặc vượt quá dung lượng cho phép (tối đa 5MB).",
        })
    allowed_exts = {".pdf", ".doc", ".docx", ".xls", ".xlsx", ".jpg", ".jpeg", ".png", ".csv", ".txt"}
    max_bytes = 5 * 1024 * 1024
    validated = []
    for att in raw_attachments:
        if not isinstance(att, dict) or att.get("invalid") is True:
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt quá dung lượng cho phép (tối đa 5MB).",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt quá dung lượng cho phép (tối đa 5MB).",
            })
        fname = str(att.get("name") or att.get("filename") or att.get("file_name") or "").strip()
        fsize = att.get("size") if "size" in att else att.get("file_size", 0)
        try:
            fsize_int = int(fsize or 0)
        except (TypeError, ValueError):
            fsize_int = max_bytes + 1
        if fsize_int < 0 or fsize_int > max_bytes:
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt quá dung lượng cho phép (tối đa 5MB).",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt quá dung lượng cho phép (tối đa 5MB).",
            })
        if fname and "." in fname:
            ext = "." + fname.rsplit(".", 1)[-1].lower()
            if ext not in allowed_exts:
                raise ValidationError({
                    "attachments": "Tệp đính kèm không hợp lệ hoặc vượt quá dung lượng cho phép (tối đa 5MB).",
                    "detail": "Tệp đính kèm không hợp lệ hoặc vượt quá dung lượng cho phép (tối đa 5MB).",
                })
        validated.append({
            "name": fname or "bien_ban_kiem_ke.pdf",
            "size": fsize_int,
            "url": str(att.get("url") or ""),
        })
    return validated


def _is_asset_eligible_for_stocktake_at_date(asset, count_dt: date_cls) -> bool:
    """
    BR11, BR12, BR13:
    - Asset must be FIXED_ASSET (or matching requested type), not DRAFT/CANCELLED.
    - Must have acquisition_date <= count_dt.
    - Must NOT be disposed on or before count_dt (disposed_at is None or disposed_at > count_dt).
    - Fully depreciated assets (remaining_value == 0) that have not been disposed ARE included (BR13).
    """
    if asset.status in ("DRAFT", "CANCELLED"):
        return False
    if asset.acquisition_date and asset.acquisition_date > count_dt:
        return False
    if asset.status == models.AssetStatus.DISPOSED:
        if asset.disposed_at is None or asset.disposed_at <= count_dt:
            return False
    return True


def _has_abnormal_quality(quality_text: str, explicit_flag=None) -> bool:
    if explicit_flag is not None:
        return bool(explicit_flag)
    norm = (quality_text or "").strip().lower()
    if not norm or norm in ("bình thường", "binh thuong", "tốt", "tot", "đang sử dụng tốt", "hoạt động tốt"):
        return False
    return any(kw in norm for kw in STOCKTAKE_QUALITY_ISSUE_KEYWORDS)


def load_book_assets_for_stocktake_uc08(request, data=None) -> dict:
    """
    Steps 14–16, AF06, AF07, AF08, EF03, EF04, EF10, EF23, BR11–BR17:
    Loads the list of Fixed Assets tracked on the books as of `count_date` (`Kiểm kê đến ngày`),
    filtered by scope (`department_id` / `department_name`, `category_id` / `category_name`).
    Initializes every loaded asset row in state `UNCOUNTED` (`Chưa kiểm kê`, `exists = None`) per BR14.
    """
    payload = data if data is not None else getattr(request, "data", {})
    if hasattr(payload, "dict"):
        payload = payload.dict()
    else:
        payload = dict(payload or {})

    for k, v in getattr(request, "query_params", {}).items():
        if k not in payload:
            payload[k] = v

    company_id = payload.get("company") or payload.get("company_id") or request.query_params.get("company_id")
    if not company_id:
        raise ValidationError({"company": "Thiếu thông tin doanh nghiệp."})
    try:
        company = Company.objects.get(pk=company_id)
    except (Company.DoesNotExist, ValueError) as exc:
        raise ValidationError({"company": "Doanh nghiệp không hợp lệ."}) from exc

    # EF23: Check scope permission
    if str(payload.get("out_of_scope_permission", "")).lower() in ("true", "1"):
        raise ValidationError({
            "scope": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
            "detail": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
        })

    # EF03 & EF04: Validate count_date ('Kiểm kê đến ngày')
    raw_count_date = payload.get("count_date") or payload.get("audit_date") or payload.get("date")
    count_dt = _parse_date(raw_count_date)
    if not count_dt:
        raise ValidationError({
            "count_date": "Vui lòng nhập ngày kiểm kê hợp lệ theo định dạng DD/MM/YYYY.",
            "detail": "Vui lòng nhập ngày kiểm kê hợp lệ theo định dạng DD/MM/YYYY.",
        })
    allow_future = str(payload.get("allow_planned_future_count", "")).lower() in ("true", "1")
    if count_dt > timezone.localdate() and not allow_future:
        raise ValidationError({
            "count_date": "Ngày kiểm kê không được lớn hơn ngày hiện tại.",
            "detail": "Ngày kiểm kê không được lớn hơn ngày hiện tại.",
        })

    # EF10: Simulate or handle book load error
    if str(payload.get("simulate_load_error", "")).lower() in ("true", "1"):
        raise ValidationError({
            "detail": "Không thể lấy danh sách tài sản tại ngày kiểm kê. Vui lòng thử lại.",
        })

    asset_type = str(payload.get("asset_type") or "FIXED_ASSET").strip().upper()
    dept_id = str(payload.get("department_id") or payload.get("department") or "").strip()
    dept_name = str(payload.get("department_name") or "").strip()
    cat_id = str(payload.get("category_id") or payload.get("category") or "").strip()
    cat_name = str(payload.get("category_name") or "").strip()

    if dept_id:
        dept_obj = Department.objects.filter(pk=dept_id).first()
        if dept_obj and str(dept_obj.company_id) != str(company.id):
            raise ValidationError({
                "department": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
                "detail": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
            })

    qs = (
        models.AssetRecord.objects.filter(company=company, asset_type=asset_type)
        .select_related("category", "department", "branch")
        .order_by("code")
    )
    if cat_id:
        qs = qs.filter(category_id=cat_id)
    elif cat_name and cat_name.lower() != "all":
        qs = qs.filter(category__name__iexact=cat_name)

    loaded_lines = []
    tot_orig = Decimal("0.00")
    tot_depr_base = Decimal("0.00")
    tot_accum = Decimal("0.00")
    tot_rem = Decimal("0.00")

    for asset in qs:
        if not _is_asset_eligible_for_stocktake_at_date(asset, count_dt):
            continue
        snap = _reconstruct_asset_book_snapshot_at_count_date(asset, count_dt)
        if dept_id and snap["book_department_id"] != dept_id:
            continue
        if dept_name and dept_name.lower() != "all" and snap["book_department_name"].lower() != dept_name.lower():
            continue

        tot_orig += snap["original_cost"]
        tot_depr_base += snap["depreciable_amount"]
        tot_accum += snap["accumulated_depreciation"]
        tot_rem += snap["remaining_value"]

        loaded_lines.append({
            "line_no": len(loaded_lines) + 1,
            "asset": str(asset.id),
            "asset_id": str(asset.id),
            "asset_code": asset.code,
            "asset_name": asset.name,
            "category_id": str(asset.category_id) if asset.category_id else "",
            "category_name": asset.category.name if asset.category else "",
            "department_id": snap["book_department_id"],
            "department_name": snap["book_department_name"],
            "book_department_id": snap["book_department_id"],
            "book_department_name": snap["book_department_name"],
            "actual_department_id": snap["book_department_id"],
            "actual_department_name": snap["book_department_name"],
            "original_cost": str(snap["original_cost"]),
            "depreciable_amount": str(snap["depreciable_amount"]),
            "accumulated_depreciation": str(snap["accumulated_depreciation"]),
            "remaining_value": str(snap["remaining_value"]),
            "is_fully_depreciated": snap["remaining_value"] == Decimal("0.00"),
            "is_surplus": False,
            # BR14 & Step 15: Loaded rows start as UNCOUNTED (Chưa kiểm kê), NOT auto-checked True
            "existence_status": "UNCOUNTED",
            "existence_status_display": "Chưa kiểm kê",
            "exists": None,
            "current_quality": "",
            "has_quality_issue": False,
            "recommendation": "",
            "recommendation_status": "NONE",
            "note": "",
            "reconciliation_result": "UNCOUNTED",
            "reconciliation_result_display": "Chưa kiểm kê",
            "version": asset.version or 1,
        })

    return {
        "company": str(company.id),
        "count_date": count_dt.isoformat(),
        "count_date_display": count_dt.strftime("%d/%m/%Y"),
        "scope": {
            "department_id": dept_id,
            "department_name": dept_name,
            "category_id": cat_id,
            "category_name": cat_name,
        },
        "lines": loaded_lines,
        "summary": {
            "book_assets_count": len(loaded_lines),
            "verified_existing_count": 0,
            "matched_count": 0,
            "missing_count": 0,
            "department_mismatch_count": 0,
            "other_mismatch_count": 0,
            "surplus_count": 0,
            "diff_count": 0,
            "quality_issue_count": 0,
            "uncounted_count": len(loaded_lines),
            "total_original_cost": str(tot_orig.quantize(Decimal("0.01"))),
            "total_depreciable_amount": str(tot_depr_base.quantize(Decimal("0.01"))),
            "total_accumulated_depreciation": str(tot_accum.quantize(Decimal("0.01"))),
            "total_remaining_value": str(tot_rem.quantize(Decimal("0.01"))),
        },
        "message": (
            f"Đã nạp {len(loaded_lines)} tài sản cố định đang theo dõi tại ngày {count_dt.strftime('%d/%m/%Y')}."
            if loaded_lines
            else "Không có tài sản cố định thuộc phạm vi kiểm kê tại ngày đã chọn."
        ),
    }


def serialize_stocktake_voucher_uc08(count_obj: models.AssetCount) -> dict:
    """
    Serializes an AssetCount record into the full UC-FA-08 representation while
    keeping backward-compatible fields (`id`, `company`, `asset_type`, `number`, `count_date`,
    `purpose`, `conclusion`, `committee`, `lines`, `created_at`).
    """
    raw_committee = count_obj.committee
    if isinstance(raw_committee, dict) and raw_committee.get("_uc08"):
        meta = raw_committee
        members = meta.get("members") or []
        enriched_lines = meta.get("lines") or []
        surplus_lines = meta.get("surplus_lines") or []
        summary = meta.get("summary") or {}
        scope = meta.get("scope") or {}
        report_datetime = meta.get("report_datetime") or f"{count_obj.count_date.strftime('%d/%m/%Y')} 08:00:00"
        reference = meta.get("reference") or ""
        recommendations_processed = bool(meta.get("recommendations_processed", False))
        status_code = meta.get("status") or "CONFIRMED"
        status_display = meta.get("status_display") or ("Đã xử lý kiến nghị" if recommendations_processed else "Đã hoàn tất")
        attachments = meta.get("attachments") or []
        idempotency_key = meta.get("idempotency_key") or ""
    else:
        members = raw_committee if isinstance(raw_committee, list) else []
        surplus_lines = []
        scope = {"scope_type": "ALL"}
        report_datetime = f"{count_obj.count_date.strftime('%d/%m/%Y')} 08:00:00"
        reference = ""
        recommendations_processed = False
        status_code = "CONFIRMED"
        status_display = "Đã hoàn tất"
        attachments = []
        idempotency_key = ""
        enriched_lines = []
        tot_orig = Decimal("0.00")
        tot_depr = Decimal("0.00")
        tot_accum = Decimal("0.00")
        tot_rem = Decimal("0.00")
        matched_c = 0
        missing_c = 0
        for idx, ln in enumerate(count_obj.lines.select_related("asset", "asset__department").all()):
            diff_qty = ln.actual_quantity - ln.book_quantity
            exists_flag = ln.actual_quantity > 0
            if exists_flag:
                matched_c += 1
            else:
                missing_c += 1
            orig_v = ln.asset.original_cost if ln.asset else Decimal("0.00")
            depr_v = (ln.asset.depreciable_amount or orig_v) if ln.asset else Decimal("0.00")
            accum_v = ln.asset.accumulated_depreciation if ln.asset else Decimal("0.00")
            rem_v = ln.book_value
            tot_orig += orig_v
            tot_depr += depr_v
            tot_accum += accum_v
            tot_rem += rem_v
            enriched_lines.append({
                "id": str(ln.id),
                "line_no": idx + 1,
                "asset": str(ln.asset_id),
                "asset_id": str(ln.asset_id),
                "asset_code": ln.asset.code if ln.asset else "",
                "asset_name": ln.asset.name if ln.asset else "",
                "department_name": ln.asset.department.name if (ln.asset and ln.asset.department) else "",
                "book_department_name": ln.asset.department.name if (ln.asset and ln.asset.department) else "",
                "actual_department_name": ln.asset.department.name if (ln.asset and ln.asset.department) else "",
                "book_quantity": str(ln.book_quantity),
                "actual_quantity": str(ln.actual_quantity),
                "difference": str(diff_qty),
                "book_value": str(ln.book_value),
                "original_cost": str(orig_v.quantize(Decimal("0.01"))),
                "depreciable_amount": str(depr_v.quantize(Decimal("0.01"))),
                "accumulated_depreciation": str(accum_v.quantize(Decimal("0.01"))),
                "remaining_value": str(rem_v.quantize(Decimal("0.01"))),
                "exists": exists_flag,
                "existence_status": "EXISTS" if exists_flag else "MISSING",
                "condition": ln.condition,
                "current_quality": ln.condition,
                "recommendation": ln.recommendation,
                "note": ln.note,
                "reconciliation_result": "MATCHED" if exists_flag else "MISSING",
            })
        summary = {
            "book_assets_count": len(enriched_lines),
            "verified_existing_count": matched_c,
            "matched_count": matched_c,
            "missing_count": missing_c,
            "department_mismatch_count": 0,
            "other_mismatch_count": 0,
            "surplus_count": 0,
            "diff_count": missing_c,
            "quality_issue_count": 0,
            "uncounted_count": 0,
            "total_original_cost": str(tot_orig.quantize(Decimal("0.01"))),
            "total_depreciable_amount": str(tot_depr.quantize(Decimal("0.01"))),
            "total_accumulated_depreciation": str(tot_accum.quantize(Decimal("0.01"))),
            "total_remaining_value": str(tot_rem.quantize(Decimal("0.01"))),
        }

    return {
        "id": str(count_obj.id),
        "company": str(count_obj.company_id),
        "asset_type": count_obj.asset_type,
        "number": count_obj.number,
        "voucher_no": count_obj.number,
        "count_date": count_obj.count_date.isoformat(),
        "count_date_display": count_obj.count_date.strftime("%d/%m/%Y"),
        "report_datetime": report_datetime,
        "purpose": count_obj.purpose,
        "conclusion": count_obj.conclusion,
        "reference": reference,
        "scope": scope,
        "recommendations_processed": recommendations_processed,
        "status": status_code,
        "status_display": status_display,
        "committee": members,
        "members": members,
        "lines": enriched_lines,
        "book_lines": [r for r in enriched_lines if not r.get("is_surplus")],
        "surplus_lines": surplus_lines,
        "summary": summary,
        "attachments": attachments,
        "idempotency_key": idempotency_key,
        "created_at": count_obj.created_at.isoformat() if count_obj.created_at else "",
        "message": "Lưu biên bản kiểm kê tài sản cố định thành công.",
    }


def save_fixed_asset_stocktake_uc08(request, data=None, instance: models.AssetCount | None = None) -> dict:
    """
    UC-FA-08 – Kiểm kê tài sản cố định:
    Validates and saves/updates a Fixed Asset Physical Count (Biên bản kiểm kê TSCĐ)
    covering Main Flow (Steps 1–46), Alternative Flows (AF01–AF30), Exception Flows (EF01–EF28),
    Formulas (Section 4.1–4.8), State Transitions (Section 6), and Business Rules (BR01–BR45).
    Guarantees that AssetRecord book values, department, and status are NOT modified by stocktake (BR37).
    """
    payload = data if data is not None else getattr(request, "data", {})
    if hasattr(payload, "dict"):
        payload = payload.dict()
    else:
        payload = dict(payload or {})

    company_id = (
        payload.get("company")
        or payload.get("company_id")
        or request.query_params.get("company_id")
        or (str(instance.company_id) if instance else None)
    )
    if not company_id:
        raise ValidationError({"company": "Thiếu thông tin doanh nghiệp."})
    try:
        company = Company.objects.get(pk=company_id)
    except (Company.DoesNotExist, ValueError) as exc:
        raise ValidationError({"company": "Doanh nghiệp không hợp lệ."}) from exc

    # EF23: Check cross-company / scope permission
    if instance and str(instance.company_id) != str(company.id):
        raise ValidationError({
            "company": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
            "detail": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
        })
    if str(payload.get("out_of_scope_permission", "")).lower() in ("true", "1"):
        raise ValidationError({
            "scope": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
            "detail": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
        })

    # EF27 & BR44: Prevent unauthorized modification of an already-confirmed stocktake
    if instance is not None:
        raw_comm = instance.committee if isinstance(instance.committee, dict) else {}
        existing_status = raw_comm.get("status", "CONFIRMED")
        allow_confirmed_edit = str(payload.get("allow_confirmed_edit", "")).lower() in ("true", "1")
        if existing_status in ("CONFIRMED", "POSTED", "COMPLETED", "PROCESSED") and not allow_confirmed_edit:
            raise ValidationError({
                "status": "Bạn không có quyền điều chỉnh biên bản kiểm kê đã xác nhận.",
                "detail": "Bạn không có quyền điều chỉnh biên bản kiểm kê đã xác nhận.",
            })

    # EF28 & BR21 & BR37: Reject direct/auto disposal from stocktake without approved post-stocktake resolution
    if (
        str(payload.get("auto_dispose_missing", "")).lower() in ("true", "1")
        or str(payload.get("action") or "").strip().upper() == "DISPOSE_MISSING"
    ) and str(payload.get("approved_resolution_basis", "")).lower() not in ("true", "1"):
        raise ValidationError({
            "disposal": "Chưa đủ căn cứ ghi giảm tài sản. Vui lòng hoàn tất hồ sơ xử lý sau kiểm kê.",
            "detail": "Chưa đủ căn cứ ghi giảm tài sản. Vui lòng hoàn tất hồ sơ xử lý sau kiểm kê.",
        })

    # EF25: Idempotency check before validation or after basic company lookup
    idem_key = str(payload.get("idempotency_key") or "").strip()
    if idem_key and instance is None:
        for existing_cnt in models.AssetCount.objects.filter(company=company).order_by("-created_at")[:50]:
            if isinstance(existing_cnt.committee, dict) and existing_cnt.committee.get("idempotency_key") == idem_key:
                res = serialize_stocktake_voucher_uc08(existing_cnt)
                res["idempotent_replayed"] = True
                return res

    # Step 4, EF02, BR02: Validate Mục đích kiểm kê (purpose)
    purpose = str(payload.get("purpose") or "").strip()
    if not purpose:
        raise ValidationError({
            "purpose": "Vui lòng nhập mục đích kiểm kê.",
            "detail": "Vui lòng nhập mục đích kiểm kê.",
        })

    # Step 5, EF03, EF04, BR03: Validate Kiểm kê đến ngày (count_date)
    raw_count_date = payload.get("count_date") or payload.get("audit_date") or payload.get("auditDate")
    if raw_count_date in (None, "") and payload.get("date") and not payload.get("report_datetime"):
        # Fallback if caller passed `date` as count_date
        raw_count_date = str(payload.get("date")).split(" ")[0]
    count_dt = _parse_date(raw_count_date)
    if not count_dt:
        raise ValidationError({
            "count_date": "Vui lòng nhập ngày kiểm kê hợp lệ theo định dạng DD/MM/YYYY.",
            "detail": "Vui lòng nhập ngày kiểm kê hợp lệ theo định dạng DD/MM/YYYY.",
        })

    is_draft = (
        str(payload.get("status") or "").strip().upper() == "DRAFT"
        or str(payload.get("is_draft", "")).lower() in ("true", "1")
    )
    allow_future = str(payload.get("allow_planned_future_count", "")).lower() in ("true", "1")
    if count_dt > timezone.localdate() and not (is_draft or allow_future):
        raise ValidationError({
            "count_date": "Ngày kiểm kê không được lớn hơn ngày hiện tại.",
            "detail": "Ngày kiểm kê không được lớn hơn ngày hiện tại.",
        })

    # Step 7, EF05, BR06: Validate Ngày lập biên bản (report_datetime / report_date)
    raw_report_dt = (
        payload.get("report_datetime")
        or payload.get("report_date")
        or payload.get("voucher_date")
        or (payload.get("date") if payload.get("count_date") or payload.get("audit_date") else None)
    )
    report_dt, report_datetime_str = _parse_stocktake_report_datetime(raw_report_dt, count_dt)
    allow_early_report = str(payload.get("allow_early_report_date", "")).lower() in ("true", "1")
    if report_dt is None or (report_dt < count_dt and not allow_early_report):
        raise ValidationError({
            "report_date": "Ngày lập biên bản không phù hợp với ngày kiểm kê.",
            "detail": "Ngày lập biên bản không phù hợp với ngày kiểm kê.",
        })

    # Step 6, AF03, EF06, EF07, BR04, BR05: Validate Số chứng từ / Số biên bản
    raw_no = payload.get("voucher_no") if "voucher_no" in payload else payload.get("number")
    auto_number = str(payload.get("auto_number", "")).lower() in ("true", "1")
    if raw_no is None and auto_number:
        voucher_no = get_next_stocktake_voucher_no(company, count_date=count_dt)
    else:
        voucher_no = str(raw_no or "").strip()

    if not voucher_no or len(voucher_no) > 50 or not re.match(r"^[A-Za-z0-9Đđ/_-]+$", voucher_no):
        raise ValidationError({
            "voucher_no": "Vui lòng nhập số chứng từ kiểm kê hợp lệ.",
            "number": "Vui lòng nhập số chứng từ kiểm kê hợp lệ.",
            "detail": "Vui lòng nhập số chứng từ kiểm kê hợp lệ.",
        })

    dup_qs = models.AssetCount.objects.filter(company=company, number__iexact=voucher_no)
    if instance is not None:
        dup_qs = dup_qs.exclude(pk=instance.pk)
    if dup_qs.exists():
        raise ValidationError({
            "voucher_no": "Số chứng từ kiểm kê đã tồn tại.",
            "number": "Số chứng từ kiểm kê đã tồn tại.",
            "detail": "Số chứng từ kiểm kê đã tồn tại.",
        })

    # Steps 8–13, AF04, AF05, EF08, BR09, BR10: Validate Thành viên tham gia (committee / members)
    raw_members = payload.get("members") if "members" in payload else payload.get("committee")
    require_committee = str(payload.get("require_committee", "")).lower() in ("true", "1")
    allow_dup_member = str(payload.get("allow_duplicate_member", "")).lower() in ("true", "1")
    validated_members = []
    seen_members = set()

    if raw_members is not None:
        if not isinstance(raw_members, list):
            raise ValidationError({
                "committee": "Vui lòng khai báo đầy đủ thành viên tham gia kiểm kê.",
                "detail": "Vui lòng khai báo đầy đủ thành viên tham gia kiểm kê.",
            })
        for idx, m in enumerate(raw_members):
            if not isinstance(m, dict):
                raise ValidationError({
                    "committee": "Vui lòng khai báo đầy đủ thành viên tham gia kiểm kê.",
                    "detail": "Vui lòng khai báo đầy đủ thành viên tham gia kiểm kê.",
                })
            m_name = str(m.get("name") or m.get("full_name") or "").strip()
            m_pos = str(m.get("position") or m.get("title") or "").strip()
            m_rep = str(m.get("represent") or m.get("representation") or m.get("department") or "").strip()
            m_role = str(m.get("role") or "").strip()
            # If row is partially filled without name, or explicitly empty when committee list was submitted
            if not m_name:
                if m_pos or m_rep or m_role or len(raw_members) == 1 or require_committee:
                    raise ValidationError({
                        "committee": "Vui lòng khai báo đầy đủ thành viên tham gia kiểm kê.",
                        "detail": "Vui lòng khai báo đầy đủ thành viên tham gia kiểm kê.",
                    })
                continue
            member_key = m_name.lower()
            if member_key in seen_members and not allow_dup_member:
                raise ValidationError({
                    "committee": "Vui lòng khai báo đầy đủ thành viên tham gia kiểm kê.",
                    "detail": "Vui lòng khai báo đầy đủ thành viên tham gia kiểm kê.",
                })
            seen_members.add(member_key)
            validated_members.append({
                "line_no": len(validated_members) + 1,
                "name": m_name,
                "position": m_pos,
                "represent": m_rep,
                "role": m_role or "Thành viên",
            })

    if require_committee and not validated_members:
        raise ValidationError({
            "committee": "Vui lòng khai báo đầy đủ thành viên tham gia kiểm kê.",
            "detail": "Vui lòng khai báo đầy đủ thành viên tham gia kiểm kê.",
        })

    # Step 33, AF24, EF26, BR39, BR40: Validate attachments (<= 5MB, valid formats)
    validated_attachments = _validate_uc08_attachments(payload.get("attachments"))

    # Steps 14–30, EF09: Validate asset lines
    raw_lines = payload.get("lines") if "lines" in payload else payload.get("rows")
    if not isinstance(raw_lines, list) or len(raw_lines) == 0:
        raise ValidationError({
            "lines": "Chưa có tài sản trong bảng kiểm kê.",
            "detail": "Chưa có tài sản trong bảng kiểm kê.",
        })

    asset_type = str(payload.get("asset_type") or "FIXED_ASSET").strip().upper()
    if asset_type not in ("FIXED_ASSET", "TOOL"):
        raise ValidationError({"asset_type": "Chọn kiểm kê TSCĐ hoặc CCDC."})

    # Scope metadata (AF06, AF07)
    scope_info = payload.get("scope") if isinstance(payload.get("scope"), dict) else {}
    scope_dept_id = str(scope_info.get("department_id") or payload.get("department_id") or "").strip()
    scope_dept_name = str(scope_info.get("department_name") or payload.get("department_name") or "").strip()
    scope_cat_id = str(scope_info.get("category_id") or payload.get("category_id") or "").strip()
    scope_cat_name = str(scope_info.get("category_name") or payload.get("category_name") or "").strip()
    if scope_dept_id:
        s_dept = Department.objects.filter(pk=scope_dept_id).first()
        if s_dept and str(s_dept.company_id) != str(company.id):
            raise ValidationError({
                "scope": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
                "detail": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
            })

    seen_book_asset_ids = set()
    db_line_specs = []
    enriched_lines = []
    surplus_lines = []

    book_assets_count = 0
    verified_existing_count = 0
    matched_count = 0
    missing_count = 0
    department_mismatch_count = 0
    other_mismatch_count = 0
    surplus_count = 0
    quality_issue_count = 0
    uncounted_count = 0

    tot_orig = Decimal("0.00")
    tot_depr_base = Decimal("0.00")
    tot_accum = Decimal("0.00")
    tot_rem = Decimal("0.00")

    for idx, row in enumerate(raw_lines):
        if not isinstance(row, dict):
            raise ValidationError({
                "lines": "Dữ liệu dòng kiểm kê không hợp lệ.",
                "detail": "Dữ liệu dòng kiểm kê không hợp lệ.",
            })

        is_surplus = (
            bool(row.get("is_surplus"))
            or str(row.get("row_type") or "").strip().upper() == "SURPLUS"
            or str(row.get("existence_status") or "").strip().upper() == "SURPLUS"
        )

        if is_surplus:
            # AF11, EF17, BR22, BR32, Section 4.4: Surplus asset discovered outside book records
            s_code = str(row.get("temp_code") or row.get("asset_code") or row.get("assetCode") or f"THUA-{idx + 1:03d}").strip()
            s_name = str(row.get("asset_name") or row.get("assetName") or row.get("name") or "").strip()
            s_dept = str(
                row.get("actual_department_name")
                or row.get("actualDept")
                or row.get("department_name")
                or row.get("dept")
                or scope_dept_name
                or ""
            ).strip()
            s_ident = str(
                row.get("identification_info")
                or row.get("note")
                or row.get("description")
                or row.get("current_quality")
                or row.get("currentQuality")
                or ""
            ).strip()
            s_rec = str(row.get("recommendation") or "Xác minh nguồn gốc để ghi tăng").strip()
            s_qual = str(row.get("current_quality") or row.get("currentQuality") or row.get("condition") or "Bình thường").strip()

            # EF17: Require name, actual department/location, and identification note/characteristic
            if not s_name or not s_dept or not (s_ident or row.get("temp_code") or row.get("asset_code")):
                raise ValidationError({
                    "lines": "Vui lòng bổ sung thông tin nhận dạng tài sản thừa.",
                    "detail": "Vui lòng bổ sung thông tin nhận dạng tài sản thừa.",
                })

            has_qual_issue = _has_abnormal_quality(s_qual, row.get("has_quality_issue"))
            if has_qual_issue:
                quality_issue_count += 1

            rec_status = str(row.get("recommendation_status") or "").strip().upper()
            if not rec_status:
                rec_status = (
                    "VERIFYING"
                    if "xác minh" in s_rec.lower() and not row.get("resolution_voucher_no") and not row.get("resolution_result")
                    else ("PROCESSED" if (row.get("resolution_voucher_no") or row.get("resolution_result")) else "PENDING")
                )

            surplus_count += 1
            surplus_entry = {
                "line_no": len(enriched_lines) + 1,
                "asset": None,
                "asset_id": "",
                "asset_code": s_code,
                "temp_code": s_code,
                "asset_name": s_name,
                "department_name": "",
                "book_department_name": "",
                "actual_department_name": s_dept,
                "book_quantity": "0",
                "actual_quantity": "1",
                "difference": "1",
                "book_value": "0.00",
                "original_cost": "0.00",
                "depreciable_amount": "0.00",
                "accumulated_depreciation": "0.00",
                "remaining_value": "0.00",
                "is_surplus": True,
                "exists": True,
                "existence_status": "EXISTS",
                "existence_status_display": "Phát hiện thừa ngoài sổ",
                "condition": s_qual,
                "current_quality": s_qual,
                "has_quality_issue": has_qual_issue,
                "recommendation": s_rec,
                "recommendation_status": rec_status,
                "resolution_voucher_no": str(row.get("resolution_voucher_no") or "").strip(),
                "resolution_result": str(row.get("resolution_result") or "").strip(),
                "identification_info": s_ident,
                "note": str(row.get("note") or s_ident).strip(),
                "reconciliation_result": "SURPLUS",
                "reconciliation_result_display": "Thừa ngoài sổ",
            }
            surplus_lines.append(surplus_entry)
            enriched_lines.append(surplus_entry)
            continue

        # Book asset lookup (EF11, EF23)
        raw_asset_id = row.get("asset") or row.get("asset_id")
        raw_asset_code = str(row.get("asset_code") or row.get("assetCode") or row.get("code") or "").strip()
        asset = None
        if raw_asset_id:
            try:
                asset = models.AssetRecord.objects.select_related("category", "department", "branch").filter(pk=raw_asset_id).first()
            except Exception:
                asset = None
        if asset is None and raw_asset_code:
            asset = (
                models.AssetRecord.objects.select_related("category", "department", "branch")
                .filter(company=company, code__iexact=raw_asset_code)
                .first()
            )
            if asset is None:
                other_company_asset = models.AssetRecord.objects.filter(code__iexact=raw_asset_code).first()
                if other_company_asset is not None:
                    raise ValidationError({
                        "asset": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
                        "detail": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
                    })

        code_label = asset.code if asset else (raw_asset_code or str(raw_asset_id or f"dòng {idx + 1}"))
        if asset is None:
            raise ValidationError({
                "lines": f"Tài sản {code_label} không hợp lệ.",
                "detail": f"Tài sản {code_label} không hợp lệ.",
            })

        # EF23: Cross-company asset check
        if str(asset.company_id) != str(company.id):
            raise ValidationError({
                "asset": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
                "detail": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
            })

        # EF11: Asset type mismatch
        if asset.asset_type != asset_type:
            raise ValidationError({
                "lines": f"Tài sản {asset.code} không hợp lệ.",
                "detail": f"Tài sản {asset.code} không hợp lệ.",
            })

        # EF13 & BR18: Duplicate asset in the same stocktake sheet
        if asset.pk in seen_book_asset_ids:
            raise ValidationError({
                "lines": f"Tài sản {asset.code} đã có trong bảng kiểm kê.",
                "detail": f"Tài sản {asset.code} đã có trong bảng kiểm kê.",
            })
        seen_book_asset_ids.add(asset.pk)

        # EF12 & BR11 & BR12: Check if asset was tracked on the books as of count_dt
        if not _is_asset_eligible_for_stocktake_at_date(asset, count_dt):
            raise ValidationError({
                "lines": f"Tài sản {asset.code} không thuộc danh sách tài sản đang theo dõi tại ngày kiểm kê.",
                "detail": f"Tài sản {asset.code} không thuộc danh sách tài sản đang theo dõi tại ngày kiểm kê.",
            })

        snap = _reconstruct_asset_book_snapshot_at_count_date(asset, count_dt)

        # EF18 & BR15–BR17: Check if book values changed since snapshot was loaded on form
        expected_version = row.get("expected_version") or payload.get("expected_version")
        if expected_version is not None and int(expected_version) != int(asset.version or 1):
            raise ValidationError({
                "lines": "Số liệu tài sản đã thay đổi. Vui lòng cập nhật lại dữ liệu theo ngày kiểm kê.",
                "detail": "Số liệu tài sản đã thay đổi. Vui lòng cập nhật lại dữ liệu theo ngày kiểm kê.",
            })
        for exp_field, auth_val in (
            ("expected_original_cost", snap["original_cost"]),
            ("expected_accumulated_depreciation", snap["accumulated_depreciation"]),
            ("expected_remaining_value", snap["remaining_value"]),
        ):
            if row.get(exp_field) is not None:
                supplied_val = _parse_decimal(row.get(exp_field), default=Decimal("-1"))
                if supplied_val.quantize(Decimal("0.01")) != auth_val:
                    raise ValidationError({
                        "lines": "Số liệu tài sản đã thay đổi. Vui lòng cập nhật lại dữ liệu theo ngày kiểm kê.",
                        "detail": "Số liệu tài sản đã thay đổi. Vui lòng cập nhật lại dữ liệu theo ngày kiểm kê.",
                    })

        # Determine existence state (Step 24, BR14, BR19: UNCOUNTED vs EXISTS vs MISSING)
        raw_status = str(row.get("existence_status") or row.get("existenceStatus") or "").strip().upper()
        raw_exists = row.get("exists")
        raw_actual_qty = row.get("actual_quantity") if "actual_quantity" in row else row.get("actualQty")

        if raw_actual_qty is not None and str(raw_actual_qty).strip() != "":
            actual_qty_dec = _parse_decimal(raw_actual_qty, default=Decimal("-1"))
            if actual_qty_dec < Decimal("0"):
                raise ValidationError({
                    "lines": f"Kết quả kiểm kê của tài sản {asset.code} không nhất quán.",
                    "detail": f"Kết quả kiểm kê của tài sản {asset.code} không nhất quán.",
                })
        else:
            actual_qty_dec = None

        if raw_status in ("UNCOUNTED", "CHUA_KIEM_KE", "PENDING", "NONE"):
            existence_status = "UNCOUNTED"
        elif raw_status in ("MISSING", "KHONG_TON_TAI", "NOT_FOUND", "LOST"):
            existence_status = "MISSING"
        elif raw_status in ("EXISTS", "TON_TAI", "FOUND", "PRESENT"):
            existence_status = "EXISTS"
        elif "exists" in row and raw_exists is None and actual_qty_dec is None:
            existence_status = "UNCOUNTED"
        elif raw_exists is False or (actual_qty_dec is not None and actual_qty_dec == Decimal("0")):
            existence_status = "MISSING"
        elif raw_exists is True or (actual_qty_dec is not None and actual_qty_dec > Decimal("0")):
            existence_status = "EXISTS"
        else:
            # Neither existence_status, exists, nor actual_quantity specified -> UNCOUNTED per BR14
            existence_status = "UNCOUNTED"

        # EF14 & BR19: Reject unconfirmed row when saving completed stocktake
        if existence_status == "UNCOUNTED" and not is_draft:
            raise ValidationError({
                "lines": "Còn tài sản chưa được xác nhận kết quả kiểm kê. Vui lòng kiểm tra lại.",
                "detail": "Còn tài sản chưa được xác nhận kết quả kiểm kê. Vui lòng kiểm tra lại.",
            })

        cur_quality = str(
            row.get("current_quality") if "current_quality" in row else (row.get("currentQuality") or row.get("condition") or "")
        ).strip()
        recommendation = str(row.get("recommendation") or row.get("solution") or "").strip()
        note = str(row.get("note") or "").strip()

        book_dept_name = snap["book_department_name"]
        actual_dept_name = str(
            row.get("actual_department_name")
            or row.get("actualDept")
            or row.get("actual_department")
            or book_dept_name
        ).strip()
        if row.get("actual_department_id"):
            act_dept_obj = Department.objects.filter(pk=row.get("actual_department_id")).first()
            if act_dept_obj:
                if str(act_dept_obj.company_id) != str(company.id):
                    raise ValidationError({
                        "department": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
                        "detail": "Bạn không có quyền kiểm kê tài sản thuộc phạm vi này.",
                    })
                actual_dept_name = act_dept_obj.name

        # EF19: Logical consistency check between existence state, quality, and recommendation
        qual_lower = cur_quality.lower()
        rec_lower = recommendation.lower()
        if existence_status == "MISSING":
            if (
                raw_exists is True
                or (actual_qty_dec is not None and actual_qty_dec > Decimal("0"))
                or rec_lower in ("tiếp tục sử dụng", "tiep tuc su dung", "đang sử dụng bình thường")
                or qual_lower in ("đang sử dụng tốt", "hoạt động tốt", "bình thường tại bộ phận")
            ):
                raise ValidationError({
                    "lines": f"Kết quả kiểm kê của tài sản {asset.code} không nhất quán.",
                    "detail": f"Kết quả kiểm kê của tài sản {asset.code} không nhất quán.",
                })
        elif existence_status == "EXISTS":
            if (
                raw_exists is False
                or (actual_qty_dec is not None and actual_qty_dec == Decimal("0"))
                or any(
                    bad_rec in rec_lower
                    for bad_rec in (
                        "ghi giảm do mất",
                        "ghi giảm tscđ thiếu",
                        "truy tìm tài sản mất",
                        "xử lý tài sản mất",
                        "báo mất",
                    )
                )
            ):
                raise ValidationError({
                    "lines": f"Kết quả kiểm kê của tài sản {asset.code} không nhất quán.",
                    "detail": f"Kết quả kiểm kê của tài sản {asset.code} không nhất quán.",
                })

        # EF15, AF09, BR21: Missing asset requires condition/note AND recommendation
        if existence_status == "MISSING" and not is_draft:
            if not (cur_quality or note) or not recommendation:
                raise ValidationError({
                    "lines": f"Vui lòng ghi rõ tình trạng và kiến nghị xử lý đối với tài sản {asset.code}.",
                    "detail": f"Vui lòng ghi rõ tình trạng và kiến nghị xử lý đối với tài sản {asset.code}.",
                })

        # AF13, AF14, EF16, BR24, BR25, BR31: Quality issue check on existing assets
        has_qual_issue = (
            _has_abnormal_quality(cur_quality, row.get("has_quality_issue"))
            if existence_status == "EXISTS"
            else False
        )
        if existence_status == "EXISTS" and has_qual_issue and not is_draft:
            if not cur_quality or not recommendation:
                raise ValidationError({
                    "lines": f"Vui lòng bổ sung tình trạng và kiến nghị xử lý cho tài sản {asset.code}.",
                    "detail": f"Vui lòng bổ sung tình trạng và kiến nghị xử lý cho tài sản {asset.code}.",
                })

        # Classification & Metrics (Section 4.1–4.8, BR20–BR32)
        book_assets_count += 1
        tot_orig += snap["original_cost"]
        tot_depr_base += snap["depreciable_amount"]
        tot_accum += snap["accumulated_depreciation"]
        tot_rem += snap["remaining_value"]

        is_dept_mismatch = False
        is_other_mismatch = bool(row.get("identity_mismatch") or row.get("other_mismatch"))

        if existence_status == "UNCOUNTED":
            uncounted_count += 1
            reconciliation_result = "UNCOUNTED"
            reconciliation_display = "Chưa kiểm kê"
            exists_bool = None
            eff_actual_qty = Decimal("0")
        elif existence_status == "MISSING":
            missing_count += 1
            reconciliation_result = "MISSING"
            reconciliation_display = "Thiếu theo kiểm kê"
            exists_bool = False
            eff_actual_qty = Decimal("0")
        else:
            verified_existing_count += 1
            exists_bool = True
            eff_actual_qty = actual_qty_dec if actual_qty_dec is not None else asset.quantity
            if (
                bool(row.get("department_mismatch"))
                or (actual_dept_name and book_dept_name and actual_dept_name.lower() != book_dept_name.lower())
            ):
                is_dept_mismatch = True
                department_mismatch_count += 1
                reconciliation_result = "DEPARTMENT_MISMATCH"
                reconciliation_display = "Chênh lệch đơn vị sử dụng"
                if not recommendation:
                    recommendation = f"Điều chuyển từ {book_dept_name} sang {actual_dept_name}"
            elif is_other_mismatch:
                other_mismatch_count += 1
                reconciliation_result = "OTHER_MISMATCH"
                reconciliation_display = "Chênh lệch nhận dạng khác"
            else:
                matched_count += 1
                reconciliation_result = "MATCHED"
                reconciliation_display = "Khớp"

            if has_qual_issue:
                quality_issue_count += 1

        # Determine recommendation status (AF18–AF22)
        has_actionable_rec = (
            reconciliation_result in ("MISSING", "DEPARTMENT_MISMATCH", "OTHER_MISMATCH")
            or has_qual_issue
            or (
                bool(recommendation)
                and recommendation.lower() not in ("tiếp tục sử dụng", "tiep tuc su dung", "bình thường", "không")
            )
        )
        raw_rec_status = str(row.get("recommendation_status") or "").strip().upper()
        res_voucher = str(row.get("resolution_voucher_no") or "").strip()
        res_result = str(row.get("resolution_result") or "").strip()
        if not has_actionable_rec:
            rec_status = "NONE"
        elif raw_rec_status:
            rec_status = raw_rec_status
        elif "tiếp tục xác minh" in recommendation.lower() or "tiep tuc xac minh" in recommendation.lower():
            rec_status = "VERIFYING"
        elif res_voucher or res_result:
            rec_status = "PROCESSED"
        else:
            rec_status = "PENDING"

        diff_qty = eff_actual_qty - asset.quantity
        db_line_specs.append({
            "asset": asset,
            "book_quantity": asset.quantity,
            "actual_quantity": eff_actual_qty,
            "book_value": snap["remaining_value"],
            "condition": (cur_quality or ("Bình thường" if exists_bool else "Không tìm thấy"))[:255],
            "recommendation": recommendation[:255],
            "note": note[:500],
        })

        enriched_lines.append({
            "line_no": len(enriched_lines) + 1,
            "asset": str(asset.id),
            "asset_id": str(asset.id),
            "asset_code": asset.code,
            "asset_name": asset.name,
            "category_id": str(asset.category_id) if asset.category_id else "",
            "category_name": asset.category.name if asset.category else "",
            "department_id": snap["book_department_id"],
            "department_name": book_dept_name,
            "book_department_id": snap["book_department_id"],
            "book_department_name": book_dept_name,
            "actual_department_name": actual_dept_name,
            "book_quantity": str(asset.quantity),
            "actual_quantity": str(eff_actual_qty),
            "difference": str(diff_qty),
            "book_value": str(snap["remaining_value"]),
            "original_cost": str(snap["original_cost"]),
            "depreciable_amount": str(snap["depreciable_amount"]),
            "accumulated_depreciation": str(snap["accumulated_depreciation"]),
            "remaining_value": str(snap["remaining_value"]),
            "is_fully_depreciated": snap["remaining_value"] == Decimal("0.00"),
            "is_surplus": False,
            "exists": exists_bool,
            "existence_status": existence_status,
            "existence_status_display": (
                "Tồn tại" if existence_status == "EXISTS" else ("Không tồn tại" if existence_status == "MISSING" else "Chưa kiểm kê")
            ),
            "condition": cur_quality,
            "current_quality": cur_quality,
            "has_quality_issue": has_qual_issue,
            "department_mismatch": is_dept_mismatch,
            "other_mismatch": is_other_mismatch,
            "recommendation": recommendation,
            "recommendation_status": rec_status,
            "resolution_voucher_no": res_voucher,
            "resolution_result": res_result,
            "note": note,
            "reconciliation_result": reconciliation_result,
            "reconciliation_result_display": reconciliation_display,
        })

    # Section 4.6 & BR30: diff_count = missing + surplus + department_mismatch + other_mismatch
    diff_count = missing_count + surplus_count + department_mismatch_count + other_mismatch_count

    # Step 31, EF20, BR34: Validate Conclusion against detailed reconciliation results
    conclusion = str(payload.get("conclusion") or "").strip()
    conclusion_lower = conclusion.lower()
    if conclusion_lower:
        claims_no_diff = any(phrase in conclusion_lower for phrase in STOCKTAKE_CONCLUSION_NO_DIFF_PHRASES)
        if claims_no_diff and diff_count > 0:
            raise ValidationError({
                "conclusion": "Kết luận kiểm kê không khớp với kết quả đối chiếu. Vui lòng kiểm tra lại.",
                "detail": "Kết luận kiểm kê không khớp với kết quả đối chiếu. Vui lòng kiểm tra lại.",
            })
        if str(payload.get("contradictory_conclusion", "")).lower() in ("true", "1"):
            raise ValidationError({
                "conclusion": "Kết luận kiểm kê không khớp với kết quả đối chiếu. Vui lòng kiểm tra lại.",
                "detail": "Kết luận kiểm kê không khớp với kết quả đối chiếu. Vui lòng kiểm tra lại.",
            })

    # Step 32, AF18–AF22, EF21, EF22, BR35, BR36: Validate 'Đã xử lý kiến nghị' & recommendation statuses
    recommendations_processed = bool(
        payload.get("recommendations_processed")
        if "recommendations_processed" in payload
        else payload.get("stocktakeProcessed", False)
    )
    reference = str(payload.get("reference") or "").strip()
    resolution_vouchers = payload.get("resolution_vouchers") or []
    has_header_resolution_basis = bool(
        reference
        or resolution_vouchers
        or str(payload.get("resolution_result") or "").strip()
    )

    actionable_rows = [
        r for r in enriched_lines if r.get("recommendation_status", "NONE") != "NONE"
    ]

    # Check if any individual row is explicitly marked PROCESSED without any resolution voucher/result (EF22)
    for r in actionable_rows:
        if r.get("recommendation_status") == "PROCESSED":
            if not (r.get("resolution_voucher_no") or r.get("resolution_result") or has_header_resolution_basis):
                raise ValidationError({
                    "recommendations_processed": "Vui lòng bổ sung chứng từ hoặc kết quả xử lý kiến nghị.",
                    "detail": "Vui lòng bổ sung chứng từ hoặc kết quả xử lý kiến nghị.",
                })

    if recommendations_processed:
        if str(payload.get("has_unprocessed_recommendations", "")).lower() in ("true", "1"):
            raise ValidationError({
                "recommendations_processed": "Còn kiến nghị kiểm kê chưa được xử lý. Không thể xác nhận đã xử lý kiến nghị.",
                "detail": "Còn kiến nghị kiểm kê chưa được xử lý. Không thể xác nhận đã xử lý kiến nghị.",
            })
        # Check if any actionable row is explicitly in PENDING or VERIFYING ("Tiếp tục xác minh", AF18)
        for r in actionable_rows:
            r_stat = r.get("recommendation_status")
            raw_row_stat = next(
                (
                    str(raw_r.get("recommendation_status") or "").strip().upper()
                    for raw_r in raw_lines
                    if isinstance(raw_r, dict)
                    and str(raw_r.get("asset_code") or raw_r.get("assetCode") or raw_r.get("temp_code") or "").strip().lower()
                    == str(r.get("asset_code") or "").strip().lower()
                ),
                "",
            )
            if r_stat == "VERIFYING" or raw_row_stat in ("PENDING", "CHUA_XU_LY", "VERIFYING", "TIEP_TUC_XAC_MINH", "UNPROCESSED"):
                raise ValidationError({
                    "recommendations_processed": "Còn kiến nghị kiểm kê chưa được xử lý. Không thể xác nhận đã xử lý kiến nghị.",
                    "detail": "Còn kiến nghị kiểm kê chưa được xử lý. Không thể xác nhận đã xử lý kiến nghị.",
                })

        # EF22: If there are actionable rows and recommendations_processed=True, require resolution voucher/result
        if actionable_rows:
            all_rows_have_basis = all(
                bool(r.get("resolution_voucher_no") or r.get("resolution_result") or has_header_resolution_basis)
                for r in actionable_rows
            )
            if not all_rows_have_basis:
                raise ValidationError({
                    "recommendations_processed": "Vui lòng bổ sung chứng từ hoặc kết quả xử lý kiến nghị.",
                    "detail": "Vui lòng bổ sung chứng từ hoặc kết quả xử lý kiến nghị.",
                })
            for r in actionable_rows:
                r["recommendation_status"] = "PROCESSED"

    summary = {
        "book_assets_count": book_assets_count,
        "verified_existing_count": verified_existing_count,
        "matched_count": matched_count,
        "missing_count": missing_count,
        "department_mismatch_count": department_mismatch_count,
        "other_mismatch_count": other_mismatch_count,
        "surplus_count": surplus_count,
        "diff_count": diff_count,
        "quality_issue_count": quality_issue_count,
        "uncounted_count": uncounted_count,
        "total_original_cost": str(tot_orig.quantize(Decimal("0.01"))),
        "total_depreciable_amount": str(tot_depr_base.quantize(Decimal("0.01"))),
        "total_accumulated_depreciation": str(tot_accum.quantize(Decimal("0.01"))),
        "total_remaining_value": str(tot_rem.quantize(Decimal("0.01"))),
    }

    status_code = "DRAFT" if is_draft else ("PROCESSED" if recommendations_processed else "CONFIRMED")
    status_display = (
        "Bản nháp"
        if is_draft
        else ("Đã xử lý kiến nghị" if recommendations_processed else "Đã hoàn tất")
    )

    committee_meta = {
        "_uc08": True,
        "members": validated_members,
        "lines": enriched_lines,
        "surplus_lines": surplus_lines,
        "summary": summary,
        "scope": {
            "scope_type": str(scope_info.get("scope_type") or payload.get("scope_type") or ("DEPARTMENT" if (scope_dept_id or scope_dept_name) else ("CATEGORY" if (scope_cat_id or scope_cat_name) else "ALL"))),
            "department_id": scope_dept_id,
            "department_name": scope_dept_name,
            "category_id": scope_cat_id,
            "category_name": scope_cat_name,
        },
        "report_datetime": report_datetime_str,
        "reference": reference,
        "recommendations_processed": recommendations_processed,
        "status": status_code,
        "status_display": status_display,
        "attachments": validated_attachments,
        "idempotency_key": idem_key,
    }

    # Steps 39–43, EF24, BR37, BR41, BR45: Persist atomically without altering AssetRecord
    try:
        with transaction.atomic():
            if str(payload.get("simulate_db_error", "")).lower() in ("true", "1"):
                raise RuntimeError("Simulated database error during stocktake save.")

            user_actor = actor(request)
            if instance is None:
                count_obj = models.AssetCount.objects.create(
                    company=company,
                    asset_type=asset_type,
                    number=voucher_no,
                    count_date=count_dt,
                    purpose=purpose[:500],
                    conclusion=conclusion,
                    committee=committee_meta,
                    created_by=user_actor,
                )
                action_code = "STOCKTAKE_ASSET"
                before_snap = None
            else:
                before_snap = serialize_stocktake_voucher_uc08(instance)
                instance.number = voucher_no
                instance.count_date = count_dt
                instance.purpose = purpose[:500]
                instance.conclusion = conclusion
                instance.committee = committee_meta
                instance.save(update_fields=("number", "count_date", "purpose", "conclusion", "committee"))
                instance.lines.all().delete()
                count_obj = instance
                action_code = "UPDATE_STOCKTAKE_ASSET"

            created_db_lines = []
            for spec in db_line_specs:
                ln_obj = models.AssetCountLine.objects.create(
                    count=count_obj,
                    asset=spec["asset"],
                    book_quantity=spec["book_quantity"],
                    actual_quantity=spec["actual_quantity"],
                    book_value=spec["book_value"],
                    condition=spec["condition"],
                    recommendation=spec["recommendation"],
                    note=spec["note"],
                )
                created_db_lines.append(ln_obj)

            # Sync DB line IDs back into committee_meta["lines"]
            db_line_idx = 0
            for entry in committee_meta["lines"]:
                if not entry.get("is_surplus") and db_line_idx < len(created_db_lines):
                    entry["id"] = str(created_db_lines[db_line_idx].id)
                    db_line_idx += 1
            count_obj.committee = committee_meta
            count_obj.save(update_fields=("committee",))

            after_snap = serialize_stocktake_voucher_uc08(count_obj)
            audit(
                request,
                count_obj,
                action_code,
                before=before_snap,
                after={
                    "voucher_no": voucher_no,
                    "count_date": count_dt.isoformat(),
                    "purpose": purpose,
                    "summary": summary,
                    "status": status_code,
                },
                reason=purpose,
            )
    except ValidationError:
        raise
    except Exception as exc:
        raise ValidationError({
            "detail": "Lưu biên bản kiểm kê thất bại. Vui lòng thử lại.",
        }) from exc

    return after_snap


