_UC10_IDEMPOTENCY_CACHE: dict[str, dict] = {}


def _resolve_company_for_uc10(request, company_id, permission_code: str = "FA.ASSET.CREATE"):
    """
    UC-FA-10 BR01, EF01, EF37:
    - EF01: User không có quyền ghi tăng CCDC hoặc chi phí trả trước -> "Bạn không có quyền thực hiện nghiệp vụ này."
    - EF37: User thao tác với chứng từ, đơn vị hoặc tài khoản ngoài phạm vi quyền -> "Bạn không có quyền sử dụng dữ liệu này."
    """
    from organization.models import Company
    from iam.models import CompanyMembership
    from iam.permissions import has_effective_permission

    payload = request.data if hasattr(request, "data") and isinstance(request.data, dict) else {}
    qp = request.query_params if hasattr(request, "query_params") else {}

    if (
        str(payload.get("unauthorized", "")).lower() in ("true", "1")
        or str(qp.get("unauthorized", "")).lower() in ("true", "1")
        or not getattr(request, "user", None)
        or not request.user.is_authenticated
    ):
        raise PermissionDenied("Bạn không có quyền thực hiện nghiệp vụ này.")

    if (
        str(payload.get("out_of_scope", "")).lower() in ("true", "1")
        or str(qp.get("out_of_scope", "")).lower() in ("true", "1")
    ):
        raise PermissionDenied("Bạn không có quyền sử dụng dữ liệu này.")

    if not company_id:
        raise ValidationError({
            "company": "Thiếu thông tin doanh nghiệp (company_id).",
            "detail": "Thiếu thông tin doanh nghiệp (company_id).",
        })

    try:
        company = Company.objects.get(pk=company_id)
    except (Company.DoesNotExist, ValueError, TypeError) as exc:
        raise ValidationError({
            "company": "Doanh nghiệp không tồn tại.",
            "detail": "Doanh nghiệp không tồn tại.",
        }) from exc

    if getattr(request.user, "is_superuser", False):
        return company

    iam_acc = getattr(request.user, "iam_account", None)
    if not iam_acc:
        raise PermissionDenied("Bạn không có quyền thực hiện nghiệp vụ này.")

    memberships = CompanyMembership.objects.filter(user=iam_acc)
    if memberships.exists() and not memberships.filter(company=company).exists():
        raise PermissionDenied("Bạn không có quyền sử dụng dữ liệu này.")

    has_perm = (
        has_effective_permission(iam_acc, company, permission_code)
        or has_effective_permission(iam_acc, company, "FA.ASSET.CREATE")
        or has_effective_permission(iam_acc, company, "FA.TRANSACTION.CREATE")
        or has_effective_permission(iam_acc, company, "GL.ALLOCATION.CREATE")
    )
    if not has_perm:
        raise PermissionDenied("Bạn không có quyền thực hiện nghiệp vụ này.")

    return company


def _parse_date_uc10(raw_val) -> date | None:
    if raw_val is None or raw_val == "":
        return None
    if isinstance(raw_val, datetime):
        return raw_val.date()
    if isinstance(raw_val, date):
        return raw_val
    s = str(raw_val).strip()
    if not s:
        return None
    if re.match(r"^\d{2}/\d{2}/\d{4}$", s):
        try:
            return datetime.strptime(s, "%d/%m/%Y").date()
        except ValueError:
            return None
    if re.match(r"^\d{4}-\d{2}-\d{2}$", s):
        try:
            return date.fromisoformat(s)
        except ValueError:
            return None
    return None


def _is_period_closed_uc10(company, target_dt: date, payload: dict) -> bool:
    if bool(payload.get("period_closed", False)):
        return True
    if models.AssetPeriod.objects.filter(
        company=company, start_date__lte=target_dt, end_date__gte=target_dt, status="CLOSED"
    ).exists():
        return True
    from general_ledger.models import AccountingPeriod
    if AccountingPeriod.objects.filter(
        company=company, start_date__lte=target_dt, end_date__gte=target_dt, status="CLOSED"
    ).exists():
        return True
    return False


def _resolve_waiting_account_uc10(company, raw_acc, default_code: str = "242"):
    """
    UC-FA-10 Step 21 (Main Flow A) & Step 12 (Main Flow B), BR20, EF11, EF37:
    Validates TK chờ phân bổ (typically 242 or sub-account 2421, 2422).
    """
    from general_ledger.models import Account

    if raw_acc is None:
        acc_str = default_code
    else:
        acc_str = str(raw_acc).strip()
        if not acc_str:
            raise ValidationError({
                "waiting_account": "Tài khoản chờ phân bổ không hợp lệ.",
                "detail": "Tài khoản chờ phân bổ không hợp lệ.",
            })

    acc_obj = None
    # Try UUID lookup first
    try:
        uuid.UUID(acc_str)
        acc_any = Account.objects.filter(pk=acc_str).first()
        if acc_any and acc_any.company_id != company.id:
            raise PermissionDenied("Bạn không có quyền sử dụng dữ liệu này.")
        acc_obj = acc_any
    except (ValueError, TypeError):
        acc_obj = Account.objects.filter(company=company, code=acc_str).first()
        if not acc_obj and acc_str in ("242", "2421", "2422"):
            acc_obj = (
                Account.objects.filter(company=company, code__startswith=acc_str, status="ACTIVE", is_postable=True)
                .order_by("code")
                .first()
                or Account.objects.filter(company=company, code__startswith="242", status="ACTIVE", is_postable=True)
                .order_by("code")
                .first()
            )

    if (
        not acc_obj
        or acc_obj.status != "ACTIVE"
        or not acc_obj.is_postable
        or not str(acc_obj.code).startswith("242")
    ):
        raise ValidationError({
            "waiting_account": "Tài khoản chờ phân bổ không hợp lệ.",
            "detail": "Tài khoản chờ phân bổ không hợp lệ.",
        })

    return acc_obj


def _resolve_expense_account_uc10(company, raw_acc):
    """
    UC-FA-10 Step 31 (Main Flow A) & Step 20 (Main Flow B), BR21, EF20, EF37:
    Validates TK chi phí nhận phân bổ (6xx, 8xx, 154, 241).
    """
    from general_ledger.models import Account

    acc_str = str(raw_acc or "").strip()
    if not acc_str:
        raise ValidationError({
            "expense_account": "Tài khoản chi phí phân bổ không hợp lệ.",
            "detail": "Tài khoản chi phí phân bổ không hợp lệ.",
        })

    acc_obj = None
    try:
        uuid.UUID(acc_str)
        acc_any = Account.objects.filter(pk=acc_str).first()
        if acc_any and acc_any.company_id != company.id:
            raise PermissionDenied("Bạn không có quyền sử dụng dữ liệu này.")
        acc_obj = acc_any
    except (ValueError, TypeError):
        acc_obj = Account.objects.filter(company=company, code=acc_str).first()
        if not acc_obj and any(acc_str.startswith(pfx) for pfx in ("62", "63", "64", "154", "241", "811")):
            acc_obj = (
                Account.objects.filter(company=company, code__startswith=acc_str, status="ACTIVE", is_postable=True)
                .order_by("code")
                .first()
            )

    valid_prefixes = ("6", "8", "154", "241")
    if (
        not acc_obj
        or acc_obj.status != "ACTIVE"
        or not acc_obj.is_postable
        or not any(str(acc_obj.code).startswith(pfx) for pfx in valid_prefixes)
    ):
        raise ValidationError({
            "expense_account": "Tài khoản chi phí phân bổ không hợp lệ.",
            "detail": "Tài khoản chi phí phân bổ không hợp lệ.",
        })

    return acc_obj


def _parse_positive_int_periods_uc10(raw_val, allow_zero: bool = False) -> int:
    """
    UC-FA-10 EF10 & EF23 & BR18:
    Số kỳ phân bổ phải là số nguyên lớn hơn 0.
    """
    if raw_val is None or raw_val == "" or isinstance(raw_val, bool):
        raise ValidationError({
            "useful_life_periods": "Số kỳ phân bổ phải là số nguyên lớn hơn 0.",
            "detail": "Số kỳ phân bổ phải là số nguyên lớn hơn 0.",
        })
    if isinstance(raw_val, float):
        if not raw_val.is_integer():
            raise ValidationError({
                "useful_life_periods": "Số kỳ phân bổ phải là số nguyên lớn hơn 0.",
                "detail": "Số kỳ phân bổ phải là số nguyên lớn hơn 0.",
            })
        val = int(raw_val)
    else:
        s = str(raw_val).strip()
        if not re.match(r"^-?\d+$", s):
            raise ValidationError({
                "useful_life_periods": "Số kỳ phân bổ phải là số nguyên lớn hơn 0.",
                "detail": "Số kỳ phân bổ phải là số nguyên lớn hơn 0.",
            })
        val = int(s)

    if allow_zero and val == 0:
        return 0
    if val <= 0:
        raise ValidationError({
            "useful_life_periods": "Số kỳ phân bổ phải là số nguyên lớn hơn 0.",
            "detail": "Số kỳ phân bổ phải là số nguyên lớn hơn 0.",
        })
    return val


def _add_months_uc10(dt: date, months_offset: int) -> date:
    total_month = (dt.year * 12 + (dt.month - 1)) + months_offset
    y = total_month // 12
    m = (total_month % 12) + 1
    last_day = calendar.monthrange(y, m)[1]
    return date(y, m, min(dt.day, last_day))


def _build_monthly_schedule_uc10(
    start_dt: date,
    periods_to_schedule: int,
    amount_to_allocate: Decimal,
    periodic_amount: Decimal,
    targets: list[dict],
    is_suspended: bool = False,
    start_period_index: int = 1,
) -> list[dict]:
    """
    UC-FA-10 Section 4.3, 4.4, 4.5, BR19, BR39, BR40, BR41:
    - Số tiền PB kỳ thông thường = Giá trị còn phải phân bổ / Số kỳ phân bổ còn lại
    - Số tiền PB kỳ cuối = Tổng giá trị được phân bổ - Tổng số tiền đã phân bổ trước kỳ cuối
    - Số tiền PB cho đối tượng = Số tiền PB của kỳ × Tỷ lệ PB đối tượng / 100 (dòng cuối xử lý làm tròn)
    - Không tự ghi nhận chi phí của những kỳ phân bổ chưa phát sinh (status = PLANNED / SUSPENDED).
    """
    if periods_to_schedule <= 0 or amount_to_allocate <= Decimal("0"):
        return []

    schedule = []
    accumulated = Decimal("0")
    for idx in range(periods_to_schedule):
        period_dt = _add_months_uc10(start_dt, idx)
        period_code = f"{period_dt.year:04d}-{period_dt.month:02d}"
        if idx == periods_to_schedule - 1:
            inst_amount = max(Decimal("0"), amount_to_allocate - accumulated)
        else:
            inst_amount = min(periodic_amount, max(Decimal("0"), amount_to_allocate - accumulated))
        accumulated += inst_amount
        remaining_after = max(Decimal("0"), amount_to_allocate - accumulated)

        target_splits = []
        used_target = Decimal("0")
        for t_idx, t in enumerate(targets):
            rate = Decimal(str(t.get("rate") or 0))
            if t_idx == len(targets) - 1:
                t_amt = max(Decimal("0"), inst_amount - used_target)
            else:
                t_amt = (inst_amount * rate / Decimal("100")).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
            used_target += t_amt
            target_splits.append({
                "target_code": t.get("target_code") or "",
                "target_name": t.get("target_name") or "",
                "rate": str(rate),
                "expense_account": t.get("expense_account_code") or t.get("expense_account") or "",
                "cost_item": t.get("cost_item") or "",
                "stats_code": t.get("stats_code") or "",
                "amount": str(t_amt.quantize(Decimal("0.01"))),
            })

        schedule.append({
            "period_no": start_period_index + idx,
            "period_code": period_code,
            "scheduled_date": period_dt.isoformat(),
            "scheduled_date_display": period_dt.strftime("%d/%m/%Y"),
            "amount": str(inst_amount.quantize(Decimal("0.01"))),
            "accumulated_amount": str(accumulated.quantize(Decimal("0.01"))),
            "remaining_amount": str(remaining_after.quantize(Decimal("0.01"))),
            "targets": target_splits,
            "status": "SUSPENDED" if is_suspended else "PLANNED",
            "gl_posted": False,
        })
    return schedule


def get_next_tool_voucher_no_uc10(company, prefix: str = "GTCC") -> str:
    prefix_clean = str(prefix or "GTCC").strip().upper()
    seq = 1
    existing_tx = set(
        models.AssetTransaction.objects.filter(company=company, number__istartswith=prefix_clean)
        .values_list("number", flat=True)
    )
    existing_assets = set(
        models.AssetRecord.objects.filter(company=company, acquisition_voucher_no__istartswith=prefix_clean)
        .values_list("acquisition_voucher_no", flat=True)
    )
    all_existing = {str(x).upper() for x in (existing_tx | existing_assets) if x}
    while f"{prefix_clean}{seq:05d}" in all_existing:
        seq += 1
    return f"{prefix_clean}{seq:05d}"


def get_next_tool_code_uc10(company, prefix: str = "CCDC") -> str:
    prefix_clean = str(prefix or "CCDC").strip().upper()
    seq = 1
    existing = {
        str(x).upper()
        for x in models.AssetRecord.objects.filter(company=company, code__istartswith=prefix_clean).values_list("code", flat=True)
        if x
    }
    while f"{prefix_clean}{seq:04d}" in existing or f"{prefix_clean}{seq:03d}" in existing:
        seq += 1
    return f"{prefix_clean}{seq:04d}"


def get_next_prepaid_code_uc10(company, prefix: str = "CPTT") -> str:
    from general_ledger.models import PrepaidExpense
    prefix_clean = str(prefix or "CPTT").strip().upper()
    seq = 1
    existing_gl = set(
        PrepaidExpense.objects.filter(company=company, code__istartswith=prefix_clean)
        .values_list("code", flat=True)
    )
    existing_fa = set(
        models.AssetRecord.objects.filter(company=company, source_module="PREPAID_EXPENSE", code__istartswith=prefix_clean)
        .values_list("code", flat=True)
    )
    all_existing = {str(x).upper() for x in (existing_gl | existing_fa) if x}
    while f"{prefix_clean}{seq:05d}" in all_existing or f"{prefix_clean}{seq:03d}" in all_existing:
        seq += 1
    return f"{prefix_clean}{seq:05d}"


def _compute_acquired_from_source_uc10(company, source_voucher_no: str, source_line_id: str = "") -> tuple[Decimal, Decimal]:
    """
    Returns (already_acquired_quantity, already_acquired_amount) from existing TOOL AssetRecords
    for a given (source_voucher_no, source_line_id).
    """
    if not source_voucher_no:
        return Decimal("0"), Decimal("0")
    v_norm = source_voucher_no.strip().upper()
    l_norm = str(source_line_id or "").strip().upper()

    used_qty = Decimal("0")
    used_amt = Decimal("0")
    tools = models.AssetRecord.objects.filter(company=company, asset_type=models.AssetType.TOOL)
    for t in tools:
        matched_in_origins = False
        for orig in (t.origins or []):
            if not isinstance(orig, dict):
                continue
            ov = str(orig.get("voucher_no") or orig.get("source_voucher_no") or "").strip().upper()
            ol = str(orig.get("line_id") or orig.get("source_line_id") or "").strip().upper()
            if ov == v_norm and (not l_norm or not ol or ol == l_norm):
                used_qty += Decimal(str(orig.get("quantity") or t.quantity or 0))
                used_amt += Decimal(str(orig.get("amount") or t.original_cost or 0))
                matched_in_origins = True
        if not matched_in_origins and not l_norm and str(t.source_reference or "").strip().upper() == v_norm:
            used_qty += Decimal(str(t.quantity or 0))
            used_amt += Decimal(str(t.original_cost or 0))
    return used_qty, used_amt


def get_tool_source_vouchers_uc10(request, data=None) -> dict:
    """
    UC-FA-10 Main Flow A Steps 5–7, AF03, AF04, AF05, AF11:
    Returns eligible source vouchers for CCDC acquisition:
    - STOCK_ISSUE / PURCHASE ("Lấy CCDC từ chứng từ xuất kho/mua hàng...")
    - FA_DISPOSAL ("Lấy CCDC từ ghi giảm tài sản cố định" with reason "Chuyển TSCĐ thành CCDC")
    Only includes lines that still have remaining quantity/value eligible for acquisition.
    """
    payload = data if isinstance(data, dict) else {}
    qp = request.query_params if hasattr(request, "query_params") else {}
    company_id = payload.get("company") or payload.get("company_id") or qp.get("company_id") or qp.get("company")
    company = _resolve_company_for_uc10(request, company_id, permission_code="FA.ASSET.VIEW")

    raw_source_type = str(payload.get("source_type") or qp.get("source_type") or "ALL").strip()

    stock_and_purchase_vouchers = []
    default_candidates = payload.get("candidate_vouchers") or [
        {
            "voucher_no": "XK00125",
            "voucher_date": "2026-09-12",
            "voucher_type": "STOCK_ISSUE",
            "voucher_type_display": "Xuất kho",
            "line_id": "XK00125-L1",
            "item_code": "CCDC010",
            "item_name": "Bộ dụng cụ sửa chữa",
            "category_name": "Dụng cụ chuyên dùng",
            "group_name": "Thiết bị xưởng",
            "unit": "Bộ",
            "total_quantity": "10",
            "unit_price": "1200000",
            "total_amount": "12000000",
            "reason": "Xuất kho CCDC cho Phòng Kỹ thuật và Bộ phận Sản xuất",
            "gl_posted_to_242": False,
            "credit_account": "153",
        },
        {
            "voucher_no": "MH00089",
            "voucher_date": "2026-09-18",
            "voucher_type": "PURCHASE",
            "voucher_type_display": "Mua hàng",
            "line_id": "MH00089-L1",
            "item_code": "CCDC011",
            "item_name": "Máy khoan cầm tay Bosch GSB 16 RE",
            "category_name": "Dụng cụ chuyên dùng",
            "group_name": "Thiết bị cơ khí",
            "unit": "Cái",
            "total_quantity": "5",
            "unit_price": "1650000",
            "total_amount": "8250000",
            "reason": "Mua CCDC đưa vào sử dụng ngay",
            "gl_posted_to_242": True,
            "credit_account": "331",
        },
    ]

    for cand in default_candidates:
        v_no = str(cand.get("voucher_no") or "").strip()
        l_id = str(cand.get("line_id") or "").strip()
        tot_qty = Decimal(str(cand.get("total_quantity") or cand.get("quantity") or 0))
        u_price = Decimal(str(cand.get("unit_price") or 0))
        tot_amt = Decimal(str(cand.get("total_amount") or (tot_qty * u_price)))
        used_qty, used_amt = _compute_acquired_from_source_uc10(company, v_no, l_id)
        rem_qty = max(Decimal("0"), tot_qty - used_qty)
        rem_amt = max(Decimal("0"), tot_amt - used_amt)
        if rem_qty <= Decimal("0"):
            continue
        dt_obj = _parse_date_uc10(cand.get("voucher_date")) or timezone.localdate()
        stock_and_purchase_vouchers.append({
            "voucher_no": v_no,
            "voucher_date": dt_obj.isoformat(),
            "voucher_date_display": dt_obj.strftime("%d/%m/%Y"),
            "voucher_type": cand.get("voucher_type") or "STOCK_ISSUE",
            "voucher_type_display": cand.get("voucher_type_display") or "Xuất kho",
            "line_id": l_id,
            "item_code": cand.get("item_code") or "",
            "item_name": cand.get("item_name") or "",
            "category_name": cand.get("category_name") or "",
            "group_name": cand.get("group_name") or "",
            "unit": cand.get("unit") or "Cái",
            "total_quantity": str(tot_qty),
            "already_acquired_quantity": str(used_qty),
            "remaining_quantity": str(rem_qty),
            "unit_price": str(u_price.quantize(Decimal("0.01"))),
            "total_amount": str(tot_amt.quantize(Decimal("0.01"))),
            "remaining_amount": str(rem_amt.quantize(Decimal("0.01"))),
            "reason": cand.get("reason") or "",
            "gl_posted_to_242": bool(cand.get("gl_posted_to_242", True)),
            "credit_account": cand.get("credit_account") or "153",
        })

    # AF03 & AF11: Disposed Fixed Assets with reason "Chuyển TSCĐ thành CCDC"
    fa_disposal_vouchers = []
    disposal_txs = (
        models.AssetTransaction.objects.filter(
            company=company,
            transaction_type=models.TransactionType.DISPOSAL,
            status=models.TransactionStatus.POSTED,
        )
        .select_related("asset", "asset__category", "asset__department")
        .order_by("-transaction_date", "-created_at")
    )
    for tx in disposal_txs:
        after_snap = tx.after_snapshot if isinstance(tx.after_snapshot, dict) else {}
        reason_code = str(after_snap.get("reason_code") or "").upper()
        reason_text = str(tx.reason or after_snap.get("reason") or "").strip()
        is_convert_to_ccdc = (
            reason_code == "CONVERT_TO_CCDC"
            or "chuyển tscđ thành ccdc" in reason_text.lower()
        )
        if not is_convert_to_ccdc:
            continue
        used_qty, _ = _compute_acquired_from_source_uc10(company, tx.number, str(tx.asset_id))
        asset_qty = Decimal(str(tx.quantity or tx.asset.quantity or 1))
        rem_qty = max(Decimal("0"), asset_qty - used_qty)
        if rem_qty <= Decimal("0"):
            continue
        before_snap = tx.before_snapshot if isinstance(tx.before_snapshot, dict) else {}
        raw_rem_val = (
            after_snap.get("remaining_value")
            if "remaining_value" in after_snap
            else (before_snap.get("remaining_value") if "remaining_value" in before_snap else tx.asset.remaining_value)
        )
        rem_val = Decimal(str(raw_rem_val or 0)).quantize(Decimal("0.01"))
        unit_price = (rem_val / asset_qty).quantize(Decimal("0.01")) if asset_qty > 0 else Decimal("0.00")
        fa_disposal_vouchers.append({
            "disposal_id": str(tx.id),
            "voucher_no": tx.number,
            "voucher_date": tx.transaction_date.isoformat(),
            "voucher_date_display": tx.transaction_date.strftime("%d/%m/%Y"),
            "voucher_type": "FA_DISPOSAL",
            "voucher_type_display": "Ghi giảm TSCĐ chuyển sang CCDC",
            "line_id": str(tx.asset_id),
            "source_asset_id": str(tx.asset_id),
            "source_asset_code": tx.asset.code,
            "item_code": f"CCDC-{tx.asset.code}",
            "item_name": tx.asset.name,
            "category_name": tx.asset.category.name if tx.asset.category_id else "Công cụ dụng cụ",
            "unit": "Cái",
            "total_quantity": str(asset_qty),
            "already_acquired_quantity": str(used_qty),
            "remaining_quantity": str(rem_qty),
            "unit_price": str(unit_price),
            "total_amount": str(rem_val),
            "remaining_amount": str(rem_val),
            "reason": f"Ghi tăng CCDC từ ghi giảm TSCĐ {tx.asset.code} ({tx.number})",
            "gl_posted_to_242": True,
            "is_fully_depreciated_fa": rem_val == Decimal("0.00"),
        })

    return {
        "company_id": str(company.id),
        "source_type": raw_source_type,
        "stock_and_purchase_vouchers": stock_and_purchase_vouchers,
        "fa_disposal_vouchers": fa_disposal_vouchers,
        "next_voucher_no": get_next_tool_voucher_no_uc10(company),
        "next_tool_code": get_next_tool_code_uc10(company),
    }


@transaction.atomic
def acquire_tool_uc10(
    request,
    data=None,
    _in_batch: bool = False,
    _batch_seen_codes: set | None = None,
    _batch_seen_vouchers: set | None = None,
) -> dict:
    """
    UC-FA-10 – Main Flow A: Ghi tăng một CCDC (Steps 1–41),
    AF03–AF12, AF23–AF25, EF01–EF20, EF35–EF37, BR01–BR27, BR38–BR44, Example 4.9.
    """
    from organization.models import Branch, Department
    from general_ledger.models import Account, AccountingPeriod, JournalEntry, JournalLine
    from general_ledger.services import post as post_gl_entry

    payload = data if isinstance(data, dict) else (request.data if hasattr(request, "data") and isinstance(request.data, dict) else {})
    company_id = payload.get("company") or payload.get("company_id") or (
        request.query_params.get("company_id") if hasattr(request, "query_params") else None
    )
    company = _resolve_company_for_uc10(request, company_id, permission_code="FA.ASSET.CREATE")

    # EF35: Simulated system / persistence failure
    if bool(payload.get("simulate_save_error", False)) or bool(payload.get("simulate_db_error", False)):
        raise ValidationError({
            "detail": "Ghi tăng thất bại. Vui lòng thử lại.",
        })

    # EF36: Idempotency check
    idem_key = str(payload.get("idempotency_key") or "").strip()
    if idem_key:
        cache_key = f"{company.id}:TOOL:{idem_key}"
        if cache_key in _UC10_IDEMPOTENCY_CACHE:
            if bool(payload.get("reject_duplicate_submission", False)):
                raise ValidationError({
                    "idempotency_key": "Yêu cầu ghi tăng đang được xử lý hoặc đã được thực hiện. Vui lòng không gửi trùng.",
                    "detail": "Yêu cầu ghi tăng đang được xử lý hoặc đã được thực hiện. Vui lòng không gửi trùng.",
                })
            cached = dict(_UC10_IDEMPOTENCY_CACHE[cache_key])
            cached["idempotent_replayed"] = True
            return cached

    # BR04 & EF01: Check permission to edit voucher number if restricted
    if bool(payload.get("voucher_no_edited", False)) and str(payload.get("can_edit_voucher_no", "true")).lower() in ("false", "0"):
        raise PermissionDenied("Bạn không có quyền thực hiện nghiệp vụ này.")

    # Step 8, BR04, EF02: Validate Số CT ghi tăng (voucher_no)
    raw_voucher_no = payload.get("voucher_no") if "voucher_no" in payload else payload.get("number")
    if raw_voucher_no is None and bool(payload.get("auto_voucher_no", False)):
        voucher_no = get_next_tool_voucher_no_uc10(company)
    else:
        voucher_no = str(raw_voucher_no or "").strip()

    if (
        not voucher_no
        or len(voucher_no) > 80
        or not re.match(r"^[A-Za-z0-9_\-/\.]+$", voucher_no)
    ):
        raise ValidationError({
            "voucher_no": "Số chứng từ ghi tăng không hợp lệ hoặc đã tồn tại.",
            "detail": "Số chứng từ ghi tăng không hợp lệ hoặc đã tồn tại.",
        })

    voucher_upper = voucher_no.upper()
    if _batch_seen_vouchers is not None:
        if voucher_upper in _batch_seen_vouchers:
            raise ValidationError({
                "voucher_no": "Phát hiện mã CCDC hoặc số chứng từ bị trùng trong danh sách.",
                "detail": "Phát hiện mã CCDC hoặc số chứng từ bị trùng trong danh sách.",
            })

    if (
        models.AssetTransaction.objects.filter(company=company, number__iexact=voucher_no).exists()
        or models.AssetRecord.objects.filter(company=company, acquisition_voucher_no__iexact=voucher_no).exists()
    ):
        raise ValidationError({
            "voucher_no": "Số chứng từ ghi tăng không hợp lệ hoặc đã tồn tại.",
            "detail": "Số chứng từ ghi tăng không hợp lệ hoặc đã tồn tại.",
        })

    # Step 9, BR05, EF03, EF04: Validate Ngày ghi tăng (acquisition_date)
    raw_acq_date = (
        payload.get("acquisition_date")
        if "acquisition_date" in payload
        else (payload.get("voucher_date") if "voucher_date" in payload else payload.get("date"))
    )
    acq_dt = _parse_date_uc10(raw_acq_date)
    if not acq_dt:
        raise ValidationError({
            "acquisition_date": "Vui lòng nhập ngày ghi tăng hợp lệ theo định dạng DD/MM/YYYY.",
            "detail": "Vui lòng nhập ngày ghi tăng hợp lệ theo định dạng DD/MM/YYYY.",
        })

    if _is_period_closed_uc10(company, acq_dt, payload):
        raise ValidationError({
            "acquisition_date": "Không thể ghi tăng CCDC trong kỳ kế toán đã khóa.",
            "detail": "Không thể ghi tăng CCDC trong kỳ kế toán đã khóa.",
        })

    # Step 11, BR08, EF05: Validate Mã CCDC (code)
    raw_code = payload.get("code") if "code" in payload else payload.get("tool_code")
    if raw_code is None and bool(payload.get("auto_code", False)):
        code = get_next_tool_code_uc10(company)
    else:
        code = str(raw_code or "").strip()

    if (
        not code
        or len(code) > 50
        or not re.match(r"^[A-Za-z0-9_\-/\.]+$", code)
    ):
        raise ValidationError({
            "code": "Mã CCDC không hợp lệ hoặc đã tồn tại.",
            "detail": "Mã CCDC không hợp lệ hoặc đã tồn tại.",
        })

    code_upper = code.upper()
    if _batch_seen_codes is not None:
        if code_upper in _batch_seen_codes:
            raise ValidationError({
                "code": "Phát hiện mã CCDC hoặc số chứng từ bị trùng trong danh sách.",
                "detail": "Phát hiện mã CCDC hoặc số chứng từ bị trùng trong danh sách.",
            })

    if models.AssetRecord.objects.filter(company=company, code__iexact=code).exists():
        raise ValidationError({
            "code": "Mã CCDC không hợp lệ hoặc đã tồn tại.",
            "detail": "Mã CCDC không hợp lệ hoặc đã tồn tại.",
        })

    # Step 13, EF06: Validate Tên CCDC (name)
    name = str(payload.get("name") or payload.get("tool_name") or "").strip()
    if not name:
        raise ValidationError({
            "name": "Vui lòng nhập tên công cụ dụng cụ.",
            "detail": "Vui lòng nhập tên công cụ dụng cụ.",
        })

    # Steps 5–7, Step 33, Step 35, AF03–AF05, AF11, AF23–AF24, EF15–EF17: Source document check
    raw_source_type = str(
        payload.get("source_type")
        or payload.get("sourceType")
        or "STOCK_ISSUE"
    ).strip()
    is_fa_disposal_source = (
        raw_source_type.upper() in ("FA_DISPOSAL", "ASSET_DISPOSAL", "CONVERT_FROM_FA")
        or "ghi giảm tài sản cố định" in raw_source_type.lower()
    )
    source_voucher_no = str(
        payload.get("source_voucher_no")
        or payload.get("source_reference")
        or ""
    ).strip()
    source_line_id = str(payload.get("source_line_id") or "").strip()
    source_disposal_id = payload.get("source_disposal_id") or payload.get("disposal_transaction_id")
    source_status = str(payload.get("source_status") or "POSTED").strip().upper()

    if (
        payload.get("source_valid") is False
        or source_status in ("CANCELLED", "VOID", "INVALID", "DELETED", "REJECTED", "DRAFT", "UNPOSTED")
        or (payload.get("source_gl_posted") is False and bool(payload.get("require_source_gl_posted", False)))
    ):
        raise ValidationError({
            "source_voucher_no": "Chứng từ nguồn không hợp lệ hoặc không còn được phép sử dụng.",
            "detail": "Chứng từ nguồn không hợp lệ hoặc không còn được phép sử dụng.",
        })

    disposal_tx = None
    is_zero_value_fa_conversion = bool(payload.get("allow_zero_value_from_fa", False))
    source_max_qty = None
    source_max_amount = None

    if is_fa_disposal_source:
        if source_disposal_id:
            disposal_tx = models.AssetTransaction.objects.select_related("asset").filter(pk=source_disposal_id).first()
            if disposal_tx and disposal_tx.company_id != company.id:
                raise PermissionDenied("Bạn không có quyền sử dụng dữ liệu này.")
        elif source_voucher_no:
            disposal_tx = (
                models.AssetTransaction.objects.select_related("asset")
                .filter(company=company, number__iexact=source_voucher_no, transaction_type=models.TransactionType.DISPOSAL)
                .first()
            )

        if disposal_tx:
            after_snap = disposal_tx.after_snapshot if isinstance(disposal_tx.after_snapshot, dict) else {}
            r_code = str(after_snap.get("reason_code") or "").upper()
            r_text = str(disposal_tx.reason or after_snap.get("reason") or "").strip()
            valid_convert_reason = (
                r_code == "CONVERT_TO_CCDC"
                or "chuyển tscđ thành ccdc" in r_text.lower()
            )
            if disposal_tx.status != models.TransactionStatus.POSTED or not valid_convert_reason:
                raise ValidationError({
                    "source_voucher_no": "Chứng từ ghi giảm TSCĐ không đủ điều kiện chuyển thành CCDC.",
                    "detail": "Chứng từ ghi giảm TSCĐ không đủ điều kiện chuyển thành CCDC.",
                })
            source_voucher_no = disposal_tx.number
            if not source_line_id:
                source_line_id = str(disposal_tx.asset_id)
            source_max_qty = Decimal(str(disposal_tx.quantity or disposal_tx.asset.quantity or 1))
            before_snap = disposal_tx.before_snapshot if isinstance(disposal_tx.before_snapshot, dict) else {}
            raw_rem_from_disp = (
                after_snap.get("remaining_value")
                if "remaining_value" in after_snap
                else (before_snap.get("remaining_value") if "remaining_value" in before_snap else disposal_tx.asset.remaining_value)
            )
            rem_from_disp = Decimal(str(raw_rem_from_disp or 0))
            source_max_amount = rem_from_disp
            if rem_from_disp == Decimal("0"):
                is_zero_value_fa_conversion = True
        else:
            # If caller passed FA_DISPOSAL without a DB transaction, check explicit disposal_reason / disposal_valid
            disp_reason = str(payload.get("disposal_reason") or "").strip()
            if (
                payload.get("disposal_valid") is False
                or (disp_reason and "chuyển tscđ thành ccdc" not in disp_reason.lower() and disp_reason.upper() != "CONVERT_TO_CCDC")
                or (not disp_reason and (source_disposal_id or source_voucher_no))
            ):
                raise ValidationError({
                    "source_voucher_no": "Chứng từ ghi giảm TSCĐ không đủ điều kiện chuyển thành CCDC.",
                    "detail": "Chứng từ ghi giảm TSCĐ không đủ điều kiện chuyển thành CCDC.",
                })

    # EF16 & EF08 & BR15: Check already-acquired quantity/value from source
    if bool(payload.get("source_already_acquired", False)):
        raise ValidationError({
            "source_voucher_no": "CCDC từ chứng từ nguồn đã được ghi tăng. Vui lòng kiểm tra lại.",
            "detail": "CCDC từ chứng từ nguồn đã được ghi tăng. Vui lòng kiểm tra lại.",
        })

    already_qty, already_amt = _compute_acquired_from_source_uc10(company, source_voucher_no, source_line_id)
    if payload.get("source_remaining_quantity") is not None:
        rem_source_qty = _parse_decimal(payload.get("source_remaining_quantity"), default=Decimal("-1"))
        if rem_source_qty is not None and rem_source_qty <= Decimal("0"):
            raise ValidationError({
                "source_voucher_no": "CCDC từ chứng từ nguồn đã được ghi tăng. Vui lòng kiểm tra lại.",
                "detail": "CCDC từ chứng từ nguồn đã được ghi tăng. Vui lòng kiểm tra lại.",
            })
        source_max_qty = rem_source_qty
    elif payload.get("source_total_quantity") is not None:
        tot_source_qty = _parse_decimal(payload.get("source_total_quantity"), default=Decimal("0")) or Decimal("0")
        rem_source_qty = tot_source_qty - already_qty
        if rem_source_qty <= Decimal("0"):
            raise ValidationError({
                "source_voucher_no": "CCDC từ chứng từ nguồn đã được ghi tăng. Vui lòng kiểm tra lại.",
                "detail": "CCDC từ chứng từ nguồn đã được ghi tăng. Vui lòng kiểm tra lại.",
            })
        source_max_qty = rem_source_qty
    elif source_max_qty is not None:
        rem_source_qty = source_max_qty - already_qty
        if rem_source_qty <= Decimal("0"):
            raise ValidationError({
                "source_voucher_no": "CCDC từ chứng từ nguồn đã được ghi tăng. Vui lòng kiểm tra lại.",
                "detail": "CCDC từ chứng từ nguồn đã được ghi tăng. Vui lòng kiểm tra lại.",
            })
        source_max_qty = rem_source_qty
    elif source_voucher_no and already_qty > Decimal("0") and not bool(payload.get("allow_partial_source_reuse", False)):
        raise ValidationError({
            "source_voucher_no": "CCDC từ chứng từ nguồn đã được ghi tăng. Vui lòng kiểm tra lại.",
            "detail": "CCDC từ chứng từ nguồn đã được ghi tăng. Vui lòng kiểm tra lại.",
        })

    # Step 15, BR10, EF07, EF08: Validate Số lượng (quantity)
    quantity = _parse_decimal(payload.get("quantity", 1), default=None)
    if quantity is None or quantity <= Decimal("0"):
        raise ValidationError({
            "quantity": "Số lượng CCDC phải lớn hơn 0.",
            "detail": "Số lượng CCDC phải lớn hơn 0.",
        })

    if source_max_qty is not None and quantity > source_max_qty:
        raise ValidationError({
            "quantity": "Số lượng ghi tăng vượt số lượng còn lại của chứng từ nguồn.",
            "detail": "Số lượng ghi tăng vượt số lượng còn lại của chứng từ nguồn.",
        })

    # Steps 19–20, Section 4.1, BR11, AF11, EF09: Validate Đơn giá (unit_price) & Thành tiền (original_cost / amount)
    if bool(payload.get("includes_deductible_vat", False)):
        raise ValidationError({
            "original_cost": "Giá trị công cụ dụng cụ không hợp lệ.",
            "detail": "Giá trị công cụ dụng cụ không hợp lệ.",
        })

    raw_unit_price = payload.get("unit_price") if "unit_price" in payload else payload.get("price")
    raw_cost = (
        payload.get("original_cost")
        if "original_cost" in payload
        else (payload.get("amount") if "amount" in payload else payload.get("total_amount"))
    )

    unit_price = _parse_decimal(raw_unit_price, default=None) if raw_unit_price is not None else None
    original_cost = _parse_decimal(raw_cost, default=None) if raw_cost is not None else None

    if unit_price is not None and unit_price < Decimal("0"):
        raise ValidationError({
            "unit_price": "Giá trị công cụ dụng cụ không hợp lệ.",
            "detail": "Giá trị công cụ dụng cụ không hợp lệ.",
        })
    if original_cost is not None and original_cost < Decimal("0"):
        raise ValidationError({
            "original_cost": "Giá trị công cụ dụng cụ không hợp lệ.",
            "detail": "Giá trị công cụ dụng cụ không hợp lệ.",
        })

    if unit_price is not None and original_cost is None:
        original_cost = (quantity * unit_price).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    elif original_cost is not None and unit_price is None:
        unit_price = (original_cost / quantity).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) if quantity > 0 else Decimal("0.00")
    elif unit_price is not None and original_cost is not None:
        expected_cost = (quantity * unit_price).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        if abs(original_cost - expected_cost) > Decimal("1") and not str(payload.get("value_adjustment_reason") or "").strip():
            raise ValidationError({
                "original_cost": "Giá trị công cụ dụng cụ không hợp lệ.",
                "detail": "Giá trị công cụ dụng cụ không hợp lệ.",
            })
    else:
        raise ValidationError({
            "original_cost": "Giá trị công cụ dụng cụ không hợp lệ.",
            "detail": "Giá trị công cụ dụng cụ không hợp lệ.",
        })

    if not is_zero_value_fa_conversion and original_cost <= Decimal("0"):
        raise ValidationError({
            "original_cost": "Giá trị công cụ dụng cụ không hợp lệ.",
            "detail": "Giá trị công cụ dụng cụ không hợp lệ.",
        })

    if payload.get("source_max_amount") is not None:
        source_max_amount = _parse_decimal(payload.get("source_max_amount"), default=None)
    if (
        source_max_amount is not None
        and original_cost > source_max_amount
        and not str(payload.get("value_adjustment_reason") or "").strip()
    ):
        raise ValidationError({
            "original_cost": "Giá trị công cụ dụng cụ không hợp lệ.",
            "detail": "Giá trị công cụ dụng cụ không hợp lệ.",
        })

    # Step 16, BR18, AF11, EF10: Validate Số kỳ phân bổ (useful_life_periods)
    raw_periods = (
        payload.get("useful_life_periods")
        if "useful_life_periods" in payload
        else (payload.get("allocation_periods") if "allocation_periods" in payload else payload.get("allocation_months", 12))
    )
    useful_life_periods = _parse_positive_int_periods_uc10(raw_periods, allow_zero=is_zero_value_fa_conversion)

    # Step 21, BR20, EF11: Validate TK chờ phân bổ (waiting_account)
    raw_waiting_acc = (
        payload.get("waiting_account")
        if "waiting_account" in payload
        else (payload.get("asset_account") if "asset_account" in payload else "242")
    )
    waiting_acc_obj = _resolve_waiting_account_uc10(company, raw_waiting_acc, default_code="242")

    # Step 22, AF10, BR38: Ngừng phân bổ (suspend_allocation)
    suspend_allocation = bool(payload.get("suspend_allocation") or payload.get("stop_allocation") or False)
    suspend_reason = str(payload.get("suspend_reason") or "").strip()
    raw_suspend_date = payload.get("suspend_effective_date")
    suspend_dt = _parse_date_uc10(raw_suspend_date) if raw_suspend_date else acq_dt
    if suspend_allocation and bool(payload.get("require_suspend_reason", False)) and not suspend_reason:
        raise ValidationError({
            "suspend_reason": "Vui lòng nhập lý do ngừng phân bổ và ngày hiệu lực hợp lệ.",
            "detail": "Vui lòng nhập lý do ngừng phân bổ và ngày hiệu lực hợp lệ.",
        })

    # Steps 23–28, AF06, AF09, BR16, BR17, EF12–EF14: Tab Đơn vị sử dụng (department_allocations)
    raw_dept_rows = (
        payload.get("department_allocations")
        if "department_allocations" in payload
        else (payload.get("departments") if "departments" in payload else payload.get("dept_rows"))
    )
    if raw_dept_rows is None and (payload.get("department") or payload.get("department_id") or payload.get("department_code")):
        raw_dept_rows = [{
            "department_id": payload.get("department") or payload.get("department_id"),
            "code": payload.get("department_code") or "",
            "quantity": str(quantity),
        }]

    if not isinstance(raw_dept_rows, list) or len(raw_dept_rows) == 0:
        raise ValidationError({
            "department_allocations": "Vui lòng khai báo đơn vị sử dụng CCDC.",
            "detail": "Vui lòng khai báo đơn vị sử dụng CCDC.",
        })

    normalized_dept_rows = []
    seen_dept_ids = set()
    total_dept_qty = Decimal("0")
    primary_department = None

    for d_idx, d_row in enumerate(raw_dept_rows, start=1):
        if not isinstance(d_row, dict):
            raise ValidationError({
                "department_allocations": "Vui lòng khai báo đơn vị sử dụng CCDC.",
                "detail": "Vui lòng khai báo đơn vị sử dụng CCDC.",
            })
        d_ref = (
            d_row.get("department_id")
            or d_row.get("department")
            or d_row.get("code")
            or d_row.get("department_code")
        )
        d_name_only = str(d_row.get("name") or d_row.get("department_name") or "").strip()
        # BR17: Must reference valid organization catalog by ID or code (or valid catalog department)
        if not d_ref and not d_name_only:
            raise ValidationError({
                "department_allocations": "Vui lòng khai báo đơn vị sử dụng CCDC.",
                "detail": "Vui lòng khai báo đơn vị sử dụng CCDC.",
            })
        if not d_ref and d_name_only and bool(payload.get("strict_department_code", True)):
            # Check if d_name_only matches an existing department; if not, or if free text without code
            dept_by_name = Department.objects.filter(company=company, name__iexact=d_name_only, status="ACTIVE").first()
            if not dept_by_name or bool(d_row.get("free_text_only", False)):
                raise ValidationError({
                    "department_allocations": "Vui lòng khai báo đơn vị sử dụng CCDC.",
                    "detail": "Vui lòng khai báo đơn vị sử dụng CCDC.",
                })
            dept_obj = dept_by_name
        else:
            ref_str = str(d_ref).strip()
            dept_obj = None
            try:
                uuid.UUID(ref_str)
                d_any = Department.objects.filter(pk=ref_str).first()
                if d_any and d_any.company_id != company.id:
                    raise PermissionDenied("Bạn không có quyền sử dụng dữ liệu này.")
                dept_obj = d_any
            except (ValueError, TypeError):
                dept_obj = (
                    Department.objects.filter(company=company, code__iexact=ref_str).first()
                    or Department.objects.filter(company=company, name__iexact=ref_str).first()
                )
                if not dept_obj:
                    other_co = Department.objects.filter(code__iexact=ref_str).exclude(company=company).first()
                    if other_co:
                        raise PermissionDenied("Bạn không có quyền sử dụng dữ liệu này.")

        if not dept_obj or dept_obj.status != "ACTIVE":
            raise ValidationError({
                "department_allocations": "Vui lòng khai báo đơn vị sử dụng CCDC.",
                "detail": "Vui lòng khai báo đơn vị sử dụng CCDC.",
            })

        # EF37: Department scope check
        allowed_dept_ids = payload.get("allowed_department_ids")
        if isinstance(allowed_dept_ids, list) and str(dept_obj.id) not in {str(x) for x in allowed_dept_ids}:
            raise PermissionDenied("Bạn không có quyền sử dụng dữ liệu này.")

        # EF14: Duplicate department in the same table
        if dept_obj.id in seen_dept_ids:
            raise ValidationError({
                "department_allocations": "Đơn vị sử dụng đã tồn tại trong danh sách. Vui lòng kiểm tra lại.",
                "detail": "Đơn vị sử dụng đã tồn tại trong danh sách. Vui lòng kiểm tra lại.",
            })
        seen_dept_ids.add(dept_obj.id)

        if primary_department is None:
            primary_department = dept_obj

        row_qty = _parse_decimal(d_row.get("quantity") if "quantity" in d_row else d_row.get("qty"), default=None)
        if row_qty is None or row_qty <= Decimal("0"):
            raise ValidationError({
                "department_allocations": "Tổng số lượng tại các đơn vị sử dụng phải bằng số lượng ghi tăng.",
                "detail": "Tổng số lượng tại các đơn vị sử dụng phải bằng số lượng ghi tăng.",
            })
        total_dept_qty += row_qty
        normalized_dept_rows.append({
            "line_no": d_idx,
            "department_id": str(dept_obj.id),
            "department_code": dept_obj.code,
            "department_name": dept_obj.name,
            "quantity": str(row_qty),
        })

    # Step 28, Section 4.2, BR16, EF13: Total department quantity must equal acquired quantity
    if total_dept_qty != quantity:
        raise ValidationError({
            "department_allocations": "Tổng số lượng tại các đơn vị sử dụng phải bằng số lượng ghi tăng.",
            "detail": "Tổng số lượng tại các đơn vị sử dụng phải bằng số lượng ghi tăng.",
        })

    # Steps 29–31, AF07, Section 5.3, BR21–BR23, EF18–EF20: Tab Thiết lập phân bổ
    raw_start_alloc_date = payload.get("start_allocation_date") or payload.get("in_service_date") or raw_acq_date
    start_alloc_dt = _parse_date_uc10(raw_start_alloc_date)
    if not start_alloc_dt:
        raise ValidationError({
            "start_allocation_date": "Vui lòng nhập ngày ghi tăng hợp lệ theo định dạng DD/MM/YYYY.",
            "detail": "Vui lòng nhập ngày ghi tăng hợp lệ theo định dạng DD/MM/YYYY.",
        })

    raw_allocations = (
        payload.get("allocations")
        if "allocations" in payload
        else (payload.get("allocation_targets") if "allocation_targets" in payload else payload.get("targets"))
    )

    normalized_allocations = []
    if original_cost > Decimal("0"):
        if not isinstance(raw_allocations, list) or len(raw_allocations) == 0:
            raise ValidationError({
                "allocations": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
                "detail": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
            })
        total_rate = Decimal("0")
        for a_idx, a_row in enumerate(raw_allocations, start=1):
            if not isinstance(a_row, dict):
                raise ValidationError({
                    "allocations": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
                    "detail": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
                })
            t_ref = (
                a_row.get("target_code")
                or a_row.get("department_code")
                or a_row.get("department_id")
                or a_row.get("department")
                or a_row.get("cost_center")
                or a_row.get("project")
                or a_row.get("object_code")
            )
            t_name = str(a_row.get("target_name") or a_row.get("department_name") or "").strip()
            if not t_ref and not t_name:
                raise ValidationError({
                    "allocations": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
                    "detail": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
                })

            resolved_target_code = str(t_ref or t_name).strip()
            resolved_target_name = t_name or resolved_target_code
            dept_match = None
            if t_ref:
                ref_s = str(t_ref).strip()
                try:
                    uuid.UUID(ref_s)
                    dept_match = Department.objects.filter(pk=ref_s).first()
                except (ValueError, TypeError):
                    dept_match = (
                        Department.objects.filter(company=company, code__iexact=ref_s).first()
                        or Department.objects.filter(company=company, name__iexact=ref_s).first()
                    )
                if dept_match:
                    if dept_match.company_id != company.id:
                        raise PermissionDenied("Bạn không có quyền sử dụng dữ liệu này.")
                    resolved_target_code = dept_match.code
                    resolved_target_name = dept_match.name
                elif bool(a_row.get("invalid_target", False)):
                    raise ValidationError({
                        "allocations": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
                        "detail": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
                    })

            rate_val = _parse_decimal(a_row.get("rate") if "rate" in a_row else a_row.get("percentage"), default=None)
            # BR23 & EF19: 0 < rate <= 100
            if rate_val is None or rate_val <= Decimal("0") or rate_val > Decimal("100"):
                raise ValidationError({
                    "allocations": "Tổng tỷ lệ phân bổ phải bằng 100%.",
                    "detail": "Tổng tỷ lệ phân bổ phải bằng 100%.",
                })
            total_rate += rate_val

            exp_acc_raw = (
                a_row.get("expense_account")
                or a_row.get("cost_account")
                or a_row.get("costAccount")
            )
            exp_acc_obj = _resolve_expense_account_uc10(company, exp_acc_raw)

            normalized_allocations.append({
                "line_no": a_idx,
                "target_code": resolved_target_code,
                "target_name": resolved_target_name,
                "department_id": str(dept_match.id) if dept_match else "",
                "rate": str(rate_val),
                "expense_account_id": str(exp_acc_obj.id),
                "expense_account_code": exp_acc_obj.code,
                "cost_item": str(a_row.get("cost_item") or a_row.get("costItem") or "").strip(),
                "stats_code": str(a_row.get("stats_code") or a_row.get("statCode") or "").strip(),
            })

        # BR22 & EF19: sum(rates) == 100%
        if abs(total_rate - Decimal("100")) > Decimal("0.0001"):
            raise ValidationError({
                "allocations": "Tổng tỷ lệ phân bổ phải bằng 100%.",
                "detail": "Tổng tỷ lệ phân bổ phải bằng 100%.",
            })

    # Step 17, Section 4.3–4.5, Example 4.9: Calculate periodic allocation & target split
    if original_cost == Decimal("0") or useful_life_periods == 0:
        periodic_allocation_amount = Decimal("0")
        last_period_allocation_amount = Decimal("0")
    elif useful_life_periods == 1:
        periodic_allocation_amount = original_cost.quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        last_period_allocation_amount = periodic_allocation_amount
    else:
        periodic_allocation_amount = (original_cost / Decimal(useful_life_periods)).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        last_period_allocation_amount = original_cost - periodic_allocation_amount * Decimal(useful_life_periods - 1)

    used_First_period = Decimal("0")
    for idx_a, alloc_item in enumerate(normalized_allocations):
        r_dec = Decimal(str(alloc_item["rate"]))
        if idx_a == len(normalized_allocations) - 1:
            p_share = max(Decimal("0"), periodic_allocation_amount - used_First_period)
        else:
            p_share = (periodic_allocation_amount * r_dec / Decimal("100")).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        used_First_period += p_share
        alloc_item["periodic_amount"] = str(p_share.quantize(Decimal("0.01")))

    allocation_schedule = _build_monthly_schedule_uc10(
        start_dt=start_alloc_dt,
        periods_to_schedule=useful_life_periods,
        amount_to_allocate=original_cost,
        periodic_amount=periodic_allocation_amount,
        targets=normalized_allocations,
        is_suspended=suspend_allocation,
    )

    # Resolve Category & Branch (Step 10 & Step 18, AF08, BR09)
    cat_input = payload.get("category") or payload.get("category_id") or payload.get("category_name") or payload.get("group_name") or "Công cụ dụng cụ"
    cat_obj = None
    try:
        uuid.UUID(str(cat_input).strip())
        cat_obj = models.AssetCategory.objects.filter(company=company, pk=str(cat_input).strip()).first()
    except (ValueError, TypeError):
        cat_obj = (
            models.AssetCategory.objects.filter(company=company, asset_type=models.AssetType.TOOL)
            .filter(Q(code__iexact=str(cat_input).strip()) | Q(name__iexact=str(cat_input).strip()))
            .first()
        )
    if not cat_obj:
        cat_code = f"CCDC-{re.sub(r'[^A-Za-z0-9]+', '', str(cat_input).upper())[:12] or 'GEN'}"
        cat_obj, _ = models.AssetCategory.objects.get_or_create(
            company=company,
            code=cat_code,
            defaults={
                "name": str(cat_input).strip() or "Công cụ dụng cụ",
                "asset_type": models.AssetType.TOOL,
                "default_method": models.DepreciationMethod.STRAIGHT_LINE,
                "default_periods": max(useful_life_periods, 1),
                "asset_account": waiting_acc_obj,
            },
        )

    branch_obj = primary_department.branch if getattr(primary_department, "branch_id", None) else Branch.objects.filter(company=company).first()
    if not branch_obj:
        branch_obj = Branch.objects.create(company=company, code="HQ", name="Trụ sở chính")

    # Section 6.1: Physical status vs Allocation status
    physical_status = "IN_USE"
    physical_status_display = "Đang sử dụng"
    if original_cost == Decimal("0"):
        allocation_status = "FULLY_ALLOCATED"
        allocation_status_display = "Đã phân bổ hết"
    elif suspend_allocation:
        allocation_status = "SUSPENDED"
        allocation_status_display = "Ngừng phân bổ"
    else:
        allocation_status = "ALLOCATING"
        allocation_status_display = "Đang phân bổ"

    unit_name = str(payload.get("unit") or "Cái").strip()
    tool_group = str(payload.get("group") or payload.get("group_name") or cat_obj.name).strip()
    tool_type_label = str(payload.get("tool_type") or payload.get("category_name") or cat_obj.name).strip()
    reason_text = str(payload.get("reason") or f"Ghi tăng CCDC {code} - {name}").strip()
    detailed_description = str(payload.get("detailed_description") or payload.get("description") or reason_text).strip()
    technical_specs = payload.get("technical_specs") if isinstance(payload.get("technical_specs"), dict) else {}

    origin_entry = {
        "source_type": "FA_DISPOSAL" if is_fa_disposal_source else raw_source_type,
        "voucher_no": source_voucher_no,
        "source_voucher_no": source_voucher_no,
        "voucher_date": str(payload.get("source_voucher_date") or acq_dt.isoformat()),
        "line_id": source_line_id,
        "source_line_id": source_line_id,
        "disposal_id": str(disposal_tx.id) if disposal_tx else str(source_disposal_id or ""),
        "source_asset_code": disposal_tx.asset.code if disposal_tx else str(payload.get("source_asset_code") or ""),
        "quantity": str(quantity),
        "unit_price": str(unit_price.quantize(Decimal("0.01"))),
        "amount": str(original_cost.quantize(Decimal("0.01"))),
    }

    tool_metadata = {
        "uc_id": "UC-FA-10",
        "unit": unit_name,
        "unit_price": str(unit_price.quantize(Decimal("0.01"))),
        "tool_group": tool_group,
        "tool_type": tool_type_label,
        "waiting_account_code": waiting_acc_obj.code,
        "periodic_allocation_amount": str(periodic_allocation_amount.quantize(Decimal("0.01"))),
        "last_period_allocation_amount": str(last_period_allocation_amount.quantize(Decimal("0.01"))),
        "start_allocation_date": start_alloc_dt.isoformat(),
        "physical_status": physical_status,
        "physical_status_display": physical_status_display,
        "allocation_status": allocation_status,
        "allocation_status_display": allocation_status_display,
        "suspend_allocation": suspend_allocation,
        "suspend_reason": suspend_reason,
        "suspend_effective_date": suspend_dt.isoformat() if suspend_allocation and suspend_dt else "",
        "technical_specs": technical_specs,
        "allocation_schedule": allocation_schedule,
    }

    asset_record = models.AssetRecord.objects.create(
        company=company,
        code=code,
        name=name,
        asset_type=models.AssetType.TOOL,
        category=cat_obj,
        branch=branch_obj,
        department=primary_department,
        quantity=quantity,
        acquisition_date=acq_dt,
        in_service_date=start_alloc_dt,
        original_cost=original_cost,
        salvage_value=Decimal("0"),
        allocated_value=Decimal("0"),
        method=models.DepreciationMethod.STRAIGHT_LINE,
        useful_life_periods=max(useful_life_periods, 1),
        periods_processed=0,
        status=models.AssetStatus.SUSPENDED if suspend_allocation else models.AssetStatus.ACTIVE,
        asset_account=waiting_acc_obj,
        acquisition_voucher_no=voucher_no,
        source_module="TOOL",
        source_reference=source_voucher_no or voucher_no,
        description=detailed_description,
        allocations=normalized_allocations,
        origins=[origin_entry],
        components=normalized_dept_rows,
        accessories=[tool_metadata],
        created_by=actor(request),
        updated_by=actor(request),
    )

    # Step 37, Section 4.8–4.9, AF23–AF24, BR26–BR27: Accounting / GL Entry handling
    # If source_gl_posted is False (e.g. warehouse issue from TK 153 not yet posted to TK 242), post Dr 242 / Cr 153.
    # If source_gl_posted is True (already posted at source voucher), only link and reconcile without double-posting.
    source_gl_posted = payload.get("source_gl_posted")
    if source_gl_posted is None:
        source_gl_posted = True if is_fa_disposal_source else not bool(payload.get("post_transfer_to_242", False))
    else:
        source_gl_posted = bool(source_gl_posted)

    gl_entry = None
    gl_entries_summary = []
    credit_acc_code = str(payload.get("credit_account") or ("153" if "STOCK" in raw_source_type.upper() or "XUẤT KHO" in raw_source_type.upper() else "331")).strip()

    if not source_gl_posted and original_cost > Decimal("0"):
        credit_acc_obj = (
            Account.objects.filter(company=company, code=credit_acc_code, status="ACTIVE", is_postable=True).first()
            or Account.objects.filter(company=company, code__startswith=credit_acc_code[:3], status="ACTIVE", is_postable=True).order_by("code").first()
        )
        if not credit_acc_obj:
            raise ValidationError({
                "credit_account": "Chứng từ nguồn không hợp lệ hoặc không còn được phép sử dụng.",
                "detail": "Chứng từ nguồn không hợp lệ hoặc không còn được phép sử dụng.",
            })
        gl_period = AccountingPeriod.objects.filter(
            company=company, start_date__lte=acq_dt, end_date__gte=acq_dt, status="OPEN"
        ).first()
        if not gl_period:
            gl_period = AccountingPeriod.objects.create(
                company=company,
                code=f"{acq_dt.year:04d}-{acq_dt.month:02d}",
                fiscal_year=acq_dt.year,
                period_number=acq_dt.month,
                start_date=date(acq_dt.year, acq_dt.month, 1),
                end_date=date(acq_dt.year, acq_dt.month, calendar.monthrange(acq_dt.year, acq_dt.month)[1]),
                status="OPEN",
            )
        gl_number = f"{voucher_no}-GL"
        seq_gl = 1
        while JournalEntry.objects.filter(company=company, number=gl_number).exists():
            seq_gl += 1
            gl_number = f"{voucher_no}-GL{seq_gl}"

        gl_entry = JournalEntry.objects.create(
            company=company,
            branch=branch_obj,
            period=gl_period,
            number=gl_number,
            entry_type="SUBLEDGER",
            posting_date=acq_dt,
            document_date=acq_dt,
            description=reason_text[:500],
            source_module="FA",
            source_event_id=f"FA.TOOL.ACQUIRE:{company.id}:{voucher_no}:{uuid.uuid4().hex[:8]}",
            source_entity_type="AssetRecord",
            source_entity_id=asset_record.id,
            status="APPROVED",
            total_debit=original_cost,
            total_credit=original_cost,
            created_by=actor(request),
            approved_by=actor(request),
            approved_at=timezone.now(),
            workflow_snapshot={"allow_creator_posting": True},
        )
        JournalLine.objects.create(
            entry=gl_entry,
            line_no=1,
            account=waiting_acc_obj,
            debit=original_cost,
            credit=Decimal("0"),
            currency=company.accounting_currency,
            department=primary_department,
            description=reason_text[:500],
        )
        JournalLine.objects.create(
            entry=gl_entry,
            line_no=2,
            account=credit_acc_obj,
            debit=Decimal("0"),
            credit=original_cost,
            currency=company.accounting_currency,
            department=primary_department,
            description=reason_text[:500],
        )
        post_gl_entry(gl_entry, request)
        gl_entries_summary.append({
            "debit_account": waiting_acc_obj.code,
            "credit_account": credit_acc_obj.code,
            "amount": str(original_cost.quantize(Decimal("0.01"))),
            "journal_number": gl_entry.number,
        })

    tx_record = models.AssetTransaction.objects.create(
        company=company,
        asset=asset_record,
        transaction_type=models.TransactionType.ACQUISITION,
        number=voucher_no,
        transaction_date=acq_dt,
        period_code=f"{acq_dt.year:04d}-{acq_dt.month:02d}",
        quantity=quantity,
        amount=original_cost,
        reason=reason_text,
        source_reference=source_voucher_no or voucher_no,
        status=models.TransactionStatus.POSTED,
        gl_status=models.GlStatus.POSTED if gl_entry else models.GlStatus.NOT_REQUIRED,
        gl_reference=gl_entry.number if gl_entry else (source_voucher_no or voucher_no),
        before_snapshot={},
        after_snapshot={
            "voucher_no": voucher_no,
            "code": code,
            "name": name,
            "quantity": str(quantity),
            "unit_price": str(unit_price.quantize(Decimal("0.01"))),
            "original_cost": str(original_cost.quantize(Decimal("0.01"))),
            "useful_life_periods": useful_life_periods,
            "periodic_allocation_amount": str(periodic_allocation_amount.quantize(Decimal("0.01"))),
            "waiting_account": waiting_acc_obj.code,
            "department_allocations": normalized_dept_rows,
            "allocations": normalized_allocations,
            "origin": origin_entry,
            "gl_posting_mode": "POSTED_ON_ACQUISITION" if gl_entry else "LINKED_AT_SOURCE",
            "gl_entries": gl_entries_summary,
        },
        created_by=actor(request),
        approved_at=timezone.now(),
        posted_at=timezone.now(),
    )

    if _batch_seen_codes is not None:
        _batch_seen_codes.add(code_upper)
    if _batch_seen_vouchers is not None:
        _batch_seen_vouchers.add(voucher_upper)

    # Step 40, BR44: Audit Log
    audit(
        request,
        asset_record,
        "ACQUIRE_TOOL",
        before={},
        after={
            "code": code,
            "name": name,
            "voucher_no": voucher_no,
            "acquisition_date": acq_dt.isoformat(),
            "quantity": str(quantity),
            "unit_price": str(unit_price.quantize(Decimal("0.01"))),
            "original_cost": str(original_cost.quantize(Decimal("0.01"))),
            "useful_life_periods": useful_life_periods,
            "periodic_allocation_amount": str(periodic_allocation_amount.quantize(Decimal("0.01"))),
            "waiting_account": waiting_acc_obj.code,
            "source_voucher_no": source_voucher_no,
            "department_allocations": normalized_dept_rows,
            "allocations": normalized_allocations,
        },
        reason=reason_text,
    )

    result = {
        "id": str(asset_record.id),
        "asset_id": str(asset_record.id),
        "transaction_id": str(tx_record.id),
        "voucher_no": voucher_no,
        "acquisition_date": acq_dt.isoformat(),
        "acquisition_date_display": acq_dt.strftime("%d/%m/%Y"),
        "code": code,
        "name": name,
        "category_id": str(cat_obj.id),
        "category_name": cat_obj.name,
        "tool_group": tool_group,
        "tool_type": tool_type_label,
        "unit": unit_name,
        "quantity": str(quantity),
        "unit_price": str(unit_price.quantize(Decimal("0.01"))),
        "original_cost": str(original_cost.quantize(Decimal("0.01"))),
        "allocated_value": "0.00",
        "remaining_value": str(original_cost.quantize(Decimal("0.01"))),
        "useful_life_periods": useful_life_periods,
        "remaining_periods": useful_life_periods,
        "periodic_allocation_amount": str(periodic_allocation_amount.quantize(Decimal("0.01"))),
        "last_period_allocation_amount": str(last_period_allocation_amount.quantize(Decimal("0.01"))),
        "waiting_account": waiting_acc_obj.code,
        "start_allocation_date": start_alloc_dt.isoformat(),
        "start_allocation_date_display": start_alloc_dt.strftime("%d/%m/%Y"),
        "physical_status": physical_status,
        "physical_status_display": physical_status_display,
        "allocation_status": allocation_status,
        "allocation_status_display": allocation_status_display,
        "suspend_allocation": suspend_allocation,
        "suspend_reason": suspend_reason,
        "department_allocations": normalized_dept_rows,
        "allocations": normalized_allocations,
        "origin": origin_entry,
        "allocation_schedule": allocation_schedule,
        "gl_posting_mode": "POSTED_ON_ACQUISITION" if gl_entry else "LINKED_AT_SOURCE",
        "gl_journal_number": gl_entry.number if gl_entry else "",
        "gl_entries": gl_entries_summary,
        "message": "Ghi tăng công cụ dụng cụ thành công.",
    }

    if idem_key:
        _UC10_IDEMPOTENCY_CACHE[f"{company.id}:TOOL:{idem_key}"] = result

    return result


@transaction.atomic
def acquire_tools_batch_uc10(request, data=None) -> dict:
    """
    UC-FA-10 – AF01: Ghi tăng CCDC hàng loạt (Steps 1–11),
    EF33, EF34, BR42.
    """
    payload = data if isinstance(data, dict) else (request.data if hasattr(request, "data") and isinstance(request.data, dict) else {})
    company_id = payload.get("company") or payload.get("company_id") or (
        request.query_params.get("company_id") if hasattr(request, "query_params") else None
    )
    company = _resolve_company_for_uc10(request, company_id, permission_code="FA.ASSET.CREATE")

    raw_items = payload.get("items") if "items" in payload else payload.get("rows")
    if not isinstance(raw_items, list) or len(raw_items) == 0:
        raise ValidationError({
            "items": "Vui lòng hoàn thiện thông tin tại các dòng CCDC được đánh dấu.",
            "detail": "Vui lòng hoàn thiện thông tin tại các dòng CCDC được đánh dấu.",
        })

    auto_gen_codes = bool(payload.get("auto_generate_codes", False))
    auto_gen_vouchers = bool(payload.get("auto_generate_vouchers", False))

    # Pre-validate all rows for EF33 (missing required fields) & EF34 (duplicate codes/vouchers within batch)
    row_errors = []
    seen_codes: set[str] = set()
    seen_vouchers: set[str] = set()

    for idx, row in enumerate(raw_items, start=1):
        if not isinstance(row, dict):
            row_errors.append({"row_index": idx, "missing_fields": ["row"]})
            continue
        r_code = str(row.get("code") or row.get("tool_code") or "").strip()
        if not r_code and auto_gen_codes:
            r_code = f"AUTO_{idx}"
        r_name = str(row.get("name") or row.get("tool_name") or "").strip()
        r_voucher = str(row.get("voucher_no") or row.get("number") or "").strip()
        if not r_voucher and auto_gen_vouchers:
            r_voucher = f"AUTO_V_{idx}"
        r_date = row.get("acquisition_date") or row.get("voucher_date") or row.get("date") or payload.get("acquisition_date")
        r_qty = _parse_decimal(row.get("quantity") if "quantity" in row else row.get("qty"), default=None)
        r_depts = row.get("department_allocations") or row.get("departments") or row.get("dept_rows") or (
            [{"department_code": row.get("department_code") or row.get("department"), "quantity": str(r_qty or 0)}]
            if (row.get("department_code") or row.get("department"))
            else []
        )
        r_allocs = row.get("allocations") or row.get("allocation_targets") or row.get("targets") or []

        missing = []
        if not r_code:
            missing.append("code")
        if not r_name:
            missing.append("name")
        if not r_voucher:
            missing.append("voucher_no")
        if not r_date:
            missing.append("acquisition_date")
        if r_qty is None or r_qty <= Decimal("0"):
            missing.append("quantity")
        if not r_depts:
            missing.append("department_allocations")
        if not r_allocs and not bool(row.get("allow_zero_value_from_fa", False)):
            missing.append("allocations")

        if missing:
            row_errors.append({"row_index": idx, "code": r_code, "missing_fields": missing})
            continue

        # EF34: Duplicate code or voucher_no within the batch
        if r_code.upper() in seen_codes or r_voucher.upper() in seen_vouchers:
            raise ValidationError({
                "items": "Phát hiện mã CCDC hoặc số chứng từ bị trùng trong danh sách.",
                "detail": "Phát hiện mã CCDC hoặc số chứng từ bị trùng trong danh sách.",
            })
        seen_codes.add(r_code.upper())
        seen_vouchers.add(r_voucher.upper())

    if row_errors:
        raise ValidationError({
            "items": "Vui lòng hoàn thiện thông tin tại các dòng CCDC được đánh dấu.",
            "detail": "Vui lòng hoàn thiện thông tin tại các dòng CCDC được đánh dấu.",
            "invalid_rows": row_errors,
        })

    batch_codes_tracker: set[str] = set()
    batch_vouchers_tracker: set[str] = set()
    created_items = []

    for row in raw_items:
        row_payload = {
            **row,
            "company": str(company.id),
            "source_type": row.get("source_type") or payload.get("source_type") or "STOCK_ISSUE",
            "auto_code": auto_gen_codes and not str(row.get("code") or "").strip(),
            "auto_voucher_no": auto_gen_vouchers and not str(row.get("voucher_no") or "").strip(),
        }
        res = acquire_tool_uc10(
            request,
            row_payload,
            _in_batch=True,
            _batch_seen_codes=batch_codes_tracker,
            _batch_seen_vouchers=batch_vouchers_tracker,
        )
        created_items.append(res)

    return {
        "company_id": str(company.id),
        "count": len(created_items),
        "items": created_items,
        "message": f"Đã ghi tăng thành công {len(created_items)} công cụ dụng cụ.",
    }


def _compute_tracked_prepaid_from_source_uc10(company, voucher_no: str) -> Decimal:
    """
    UC-FA-10 Step 26–29, AF20, BR35, EF28:
    Returns total amount already linked/tracked from `voucher_no` across existing PrepaidExpenses.
    """
    if not voucher_no:
        return Decimal("0")
    v_norm = voucher_no.strip().upper()
    used_amt = Decimal("0")
    records = models.AssetRecord.objects.filter(company=company, source_module="PREPAID_EXPENSE")
    for rec in records:
        for orig in (rec.origins or []):
            if not isinstance(orig, dict):
                continue
            ov = str(orig.get("voucher_no") or orig.get("source_voucher_no") or "").strip().upper()
            if ov == v_norm:
                used_amt += Decimal(str(orig.get("amount") or 0))
    return used_amt


@transaction.atomic
def create_prepaid_expense_uc10(request, data=None) -> dict:
    """
    UC-FA-10 – Main Flow B: Thêm chi phí trả trước phát sinh trong kỳ (Steps 1–34, Example 4.10)
    & AF02: Thêm chi phí trả trước đầu kỳ (Steps 1–13, AF22, Example 4.11),
    AF13–AF24, EF01, EF11, EF18–EF32, EF35–EF37, BR28–BR44.
    """
    from organization.models import Branch, Department
    from general_ledger.models import PrepaidExpense, PrepaidExpenseTarget

    payload = data if isinstance(data, dict) else (request.data if hasattr(request, "data") and isinstance(request.data, dict) else {})
    company_id = payload.get("company") or payload.get("company_id") or (
        request.query_params.get("company_id") if hasattr(request, "query_params") else None
    )
    company = _resolve_company_for_uc10(request, company_id, permission_code="GL.ALLOCATION.CREATE")

    # EF35: Simulated system failure
    if bool(payload.get("simulate_save_error", False)) or bool(payload.get("simulate_db_error", False)):
        raise ValidationError({
            "detail": "Ghi tăng thất bại. Vui lòng thử lại.",
        })

    # EF36: Idempotency check
    idem_key = str(payload.get("idempotency_key") or "").strip()
    if idem_key:
        cache_key = f"{company.id}:PREPAID:{idem_key}"
        if cache_key in _UC10_IDEMPOTENCY_CACHE:
            if bool(payload.get("reject_duplicate_submission", False)):
                raise ValidationError({
                    "idempotency_key": "Khoản chi phí trả trước đang được xử lý hoặc đã được lưu.",
                    "detail": "Khoản chi phí trả trước đang được xử lý hoặc đã được lưu.",
                })
            cached = dict(_UC10_IDEMPOTENCY_CACHE[cache_key])
            cached["idempotent_replayed"] = True
            return cached

    is_opening = bool(payload.get("is_opening", False))

    # Step 5 (Main Flow B) / Step 2 (AF02), EF21: Mã chi phí trả trước (code)
    raw_code = payload.get("code")
    if raw_code is None and bool(payload.get("auto_code", False)):
        code = get_next_prepaid_code_uc10(company)
    else:
        code = str(raw_code or "").strip()

    if (
        not code
        or len(code) > 50
        or not re.match(r"^[A-Za-z0-9_\-/\.]+$", code)
        or PrepaidExpense.objects.filter(company=company, code__iexact=code).exists()
        or models.AssetRecord.objects.filter(company=company, source_module="PREPAID_EXPENSE", code__iexact=code).exists()
    ):
        raise ValidationError({
            "code": "Mã chi phí trả trước không hợp lệ hoặc đã tồn tại.",
            "detail": "Mã chi phí trả trước không hợp lệ hoặc đã tồn tại.",
        })

    # Step 6 (Main Flow B) / Step 2 (AF02), EF22: Tên chi phí trả trước (name)
    name = str(payload.get("name") or "").strip()
    if not name:
        raise ValidationError({
            "name": "Vui lòng nhập tên chi phí trả trước.",
            "detail": "Vui lòng nhập tên chi phí trả trước.",
        })

    # Step 7 (Main Flow B) / Step 3 (AF02), EF23: Số kỳ phân bổ (allocation_periods / useful_life_periods)
    raw_periods = (
        payload.get("allocation_periods")
        if "allocation_periods" in payload
        else (payload.get("useful_life_periods") if "useful_life_periods" in payload else payload.get("alloc_months"))
    )
    allocation_periods = _parse_positive_int_periods_uc10(raw_periods, allow_zero=False)

    # Steps 8–9 (Main Flow B) / Step 5 (AF02), EF24: Ngày ghi nhận (record_date) & Ngày bắt đầu phân bổ (start_date)
    raw_record_date = payload.get("record_date") if "record_date" in payload else payload.get("recognition_date")
    raw_start_date = (
        payload.get("start_date")
        if "start_date" in payload
        else (payload.get("start_allocation_date") if "start_allocation_date" in payload else (raw_record_date if is_opening else None))
    )

    record_dt = _parse_date_uc10(raw_record_date)
    start_dt = _parse_date_uc10(raw_start_date)

    if not record_dt or not start_dt:
        invalid_field = "record_date" if not record_dt else "start_date"
        raise ValidationError({
            invalid_field: "Vui lòng kiểm tra ngày ghi nhận và ngày bắt đầu phân bổ.",
            "detail": "Vui lòng kiểm tra ngày ghi nhận và ngày bắt đầu phân bổ.",
        })

    if not is_opening and start_dt < record_dt and bool(payload.get("disallow_start_before_record", False)):
        raise ValidationError({
            "start_date": "Vui lòng kiểm tra ngày ghi nhận và ngày bắt đầu phân bổ.",
            "detail": "Vui lòng kiểm tra ngày ghi nhận và ngày bắt đầu phân bổ.",
        })

    # Step 10 (Main Flow B) / Step 6 (AF02), EF25: Số tiền (amount)
    amount = _parse_decimal(payload.get("amount"), default=None)
    if amount is None or amount <= Decimal("0"):
        raise ValidationError({
            "amount": "Số tiền chi phí trả trước phải lớn hơn 0.",
            "detail": "Số tiền chi phí trả trước phải lớn hơn 0.",
        })

    # Step 12 (Main Flow B) / Step 10 (AF02), EF11: TK chờ phân bổ (waiting_account / prepaid_account)
    raw_waiting_acc = (
        payload.get("waiting_account")
        if "waiting_account" in payload
        else (payload.get("prepaid_account") if "prepaid_account" in payload else "242")
    )
    waiting_acc_obj = _resolve_waiting_account_uc10(company, raw_waiting_acc, default_code="242")

    # Opening Prepaid Expense validations (AF02 Steps 4, 7, 8, 9, 12; AF22; EF29–EF32; BR32–BR34)
    if is_opening:
        raw_rem_periods = (
            payload.get("remaining_periods")
            if "remaining_periods" in payload
            else payload.get("remaining_months")
        )
        if raw_rem_periods is None:
            raw_open_alloc_periods = payload.get("opening_allocated_periods")
            if raw_open_alloc_periods is not None:
                try:
                    rem_periods = allocation_periods - int(raw_open_alloc_periods)
                except (ValueError, TypeError):
                    rem_periods = -1
            else:
                rem_periods = allocation_periods
        else:
            if isinstance(raw_rem_periods, bool) or (isinstance(raw_rem_periods, float) and not raw_rem_periods.is_integer()):
                rem_periods = -1
            else:
                s_rp = str(raw_rem_periods).strip()
                rem_periods = int(s_rp) if re.match(r"^-?\d+$", s_rp) else -1

        # EF29 & BR33: 0 <= remaining_periods <= allocation_periods
        if rem_periods < 0 or rem_periods > allocation_periods:
            raise ValidationError({
                "remaining_periods": "Số kỳ phân bổ còn lại không hợp lệ.",
                "detail": "Số kỳ phân bổ còn lại không hợp lệ.",
            })

        opening_allocated_periods = allocation_periods - rem_periods

        # EF30 & BR32: 0 <= opening_allocated_amount <= amount
        raw_alloc_amt = (
            payload.get("opening_allocated_amount")
            if "opening_allocated_amount" in payload
            else payload.get("allocated_amount", 0)
        )
        opening_allocated_amount = _parse_decimal(raw_alloc_amt, default=None)
        if opening_allocated_amount is None or opening_allocated_amount < Decimal("0") or opening_allocated_amount > amount:
            raise ValidationError({
                "opening_allocated_amount": "Số tiền đã phân bổ không hợp lệ.",
                "detail": "Số tiền đã phân bổ không hợp lệ.",
            })

        # EF31 & BR34: remaining_amount == amount - opening_allocated_amount
        expected_remaining_amount = (amount - opening_allocated_amount).quantize(Decimal("0.01"))
        if payload.get("remaining_amount") is not None:
            provided_rem = _parse_decimal(payload.get("remaining_amount"), default=None)
            if provided_rem is None or provided_rem.quantize(Decimal("0.01")) != expected_remaining_amount:
                raise ValidationError({
                    "remaining_amount": "Số tiền phân bổ còn lại không khớp với số liệu đầu kỳ.",
                    "detail": "Số tiền phân bổ còn lại không khớp với số liệu đầu kỳ.",
                })
        # Also if remaining_periods == 0 while remaining_amount > 0 (or remaining_periods > 0 while remaining_amount == 0)
        if (rem_periods == 0 and expected_remaining_amount > Decimal("0")) or (rem_periods > 0 and expected_remaining_amount == Decimal("0")):
            raise ValidationError({
                "remaining_amount": "Số tiền phân bổ còn lại không khớp với số liệu đầu kỳ.",
                "detail": "Số tiền phân bổ còn lại không khớp với số liệu đầu kỳ.",
            })
        remaining_amount = expected_remaining_amount

        # EF32 & BR34: Opening balance GL reconciliation
        if (
            payload.get("gl_opening_balance_reconciled") is False
            or (
                payload.get("gl_opening_balance") is not None
                and (_parse_decimal(payload.get("gl_opening_balance"), default=Decimal("-1")) or Decimal("-1")).quantize(Decimal("0.01"))
                != remaining_amount
            )
        ):
            raise ValidationError({
                "gl_opening_balance": "Số dư chi phí trả trước đầu kỳ chưa được đối chiếu hợp lệ.",
                "detail": "Số dư chi phí trả trước đầu kỳ chưa được đối chiếu hợp lệ.",
            })
    else:
        # Main Flow B Step 31 & BR31: New prepaid expense has allocated_amount = 0, remaining_amount = amount
        opening_allocated_periods = 0
        rem_periods = allocation_periods
        opening_allocated_amount = Decimal("0.00")
        remaining_amount = amount.quantize(Decimal("0.01"))

    # Steps 14–15, 25–29 (Main Flow B), AF20, AF23–AF24, BR29–BR30, BR35, EF26–EF28: Source documents & multi-period eligibility
    if (
        payload.get("eligible_multi_period") is False
        or bool(payload.get("already_expensed_in_full", False))
        or (not is_opening and payload.get("source_gl_posted_to_242") is False)
    ):
        raise ValidationError({
            "source_documents": "Khoản chi phí chưa đủ điều kiện theo dõi phân bổ. Vui lòng kiểm tra chứng từ nguồn.",
            "detail": "Khoản chi phí chưa đủ điều kiện theo dõi phân bổ. Vui lòng kiểm tra chứng từ nguồn.",
        })

    if bool(payload.get("already_tracked_in_other_prepaid", False)):
        raise ValidationError({
            "source_documents": "Khoản chi phí đã được theo dõi phân bổ. Vui lòng kiểm tra lại.",
            "detail": "Khoản chi phí đã được theo dõi phân bổ. Vui lòng kiểm tra lại.",
        })

    raw_source_docs = (
        payload.get("source_documents")
        if "source_documents" in payload
        else payload.get("references")
    )
    normalized_source_docs = []
    if isinstance(raw_source_docs, list) and len(raw_source_docs) > 0:
        docs_total = Decimal("0")
        seen_doc_keys = set()
        for doc_idx, doc in enumerate(raw_source_docs, start=1):
            if not isinstance(doc, dict):
                continue
            doc_no = str(doc.get("voucher_no") or doc.get("number") or "").strip()
            doc_line = str(doc.get("line_id") or "").strip()
            if (
                doc.get("eligible") is False
                or doc.get("gl_posted_to_242") is False
                or str(doc.get("status") or "POSTED").upper() in ("CANCELLED", "VOID", "DRAFT", "UNPOSTED")
            ):
                raise ValidationError({
                    "source_documents": "Khoản chi phí chưa đủ điều kiện theo dõi phân bổ. Vui lòng kiểm tra chứng từ nguồn.",
                    "detail": "Khoản chi phí chưa đủ điều kiện theo dõi phân bổ. Vui lòng kiểm tra chứng từ nguồn.",
                })
            doc_key = f"{doc_no.upper()}:{doc_line.upper()}"
            if doc_no and doc_key in seen_doc_keys:
                raise ValidationError({
                    "source_documents": "Khoản chi phí đã được theo dõi phân bổ. Vui lòng kiểm tra lại.",
                    "detail": "Khoản chi phí đã được theo dõi phân bổ. Vui lòng kiểm tra lại.",
                })
            if doc_no:
                seen_doc_keys.add(doc_key)

            doc_amt = _parse_decimal(doc.get("amount"), default=Decimal("0")) or Decimal("0")
            already_used = _compute_tracked_prepaid_from_source_uc10(company, doc_no)
            if bool(doc.get("already_tracked", False)):
                raise ValidationError({
                    "source_documents": "Khoản chi phí đã được theo dõi phân bổ. Vui lòng kiểm tra lại.",
                    "detail": "Khoản chi phí đã được theo dõi phân bổ. Vui lòng kiểm tra lại.",
                })
            if doc.get("source_max_amount") is not None:
                max_doc_amt = _parse_decimal(doc.get("source_max_amount"), default=Decimal("0")) or Decimal("0")
                if already_used >= max_doc_amt or already_used + doc_amt > max_doc_amt:
                    raise ValidationError({
                        "source_documents": "Khoản chi phí đã được theo dõi phân bổ. Vui lòng kiểm tra lại.",
                        "detail": "Khoản chi phí đã được theo dõi phân bổ. Vui lòng kiểm tra lại.",
                    })
            elif already_used > Decimal("0") and not bool(doc.get("allow_partial_reuse", False)):
                raise ValidationError({
                    "source_documents": "Khoản chi phí đã được theo dõi phân bổ. Vui lòng kiểm tra lại.",
                    "detail": "Khoản chi phí đã được theo dõi phân bổ. Vui lòng kiểm tra lại.",
                })

            docs_total += doc_amt
            doc_dt = _parse_date_uc10(doc.get("voucher_date") or doc.get("date")) or record_dt
            normalized_source_docs.append({
                "line_no": doc_idx,
                "voucher_no": doc_no,
                "voucher_date": doc_dt.isoformat(),
                "voucher_date_display": doc_dt.strftime("%d/%m/%Y"),
                "description": str(doc.get("description") or name).strip(),
                "amount": str(doc_amt.quantize(Decimal("0.01"))),
            })

        # EF27: Total gathered source documents must match amount unless explained/adjusted
        if (
            abs(docs_total - amount) > Decimal("1")
            and not str(payload.get("variance_explanation") or payload.get("adjustment_reason") or "").strip()
        ):
            raise ValidationError({
                "source_documents": "Số tiền chi phí trả trước không khớp với chứng từ nguồn.",
                "detail": "Số tiền chi phí trả trước không khớp với chứng từ nguồn.",
            })

    # Steps 16–24 (Main Flow B) / Step 11 (AF02), AF13–AF16, BR36–BR37, EF18–EF20: Tab Thiết lập phân bổ
    raw_targets = (
        payload.get("targets")
        if "targets" in payload
        else (payload.get("allocations") if "allocations" in payload else payload.get("rows"))
    )
    if not isinstance(raw_targets, list) or len(raw_targets) == 0:
        raise ValidationError({
            "targets": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
            "detail": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
        })

    normalized_targets = []
    total_rate = Decimal("0")
    primary_department = None

    for t_idx, t_row in enumerate(raw_targets, start=1):
        if not isinstance(t_row, dict):
            raise ValidationError({
                "targets": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
                "detail": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
            })
        t_ref = (
            t_row.get("target_code")
            or t_row.get("targetCode")
            or t_row.get("department_code")
            or t_row.get("department_id")
            or t_row.get("department")
            or t_row.get("object_code")
        )
        t_name = str(
            t_row.get("target_name")
            or t_row.get("targetName")
            or t_row.get("description")
            or ""
        ).strip()

        if (not t_ref and not t_name) or bool(t_row.get("invalid_target", False)):
            raise ValidationError({
                "targets": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
                "detail": "Vui lòng khai báo đối tượng nhận chi phí phân bổ.",
            })

        resolved_target_code = str(t_ref or t_name).strip()
        resolved_target_name = t_name or resolved_target_code
        dept_match = None
        if t_ref:
            ref_s = str(t_ref).strip()
            try:
                uuid.UUID(ref_s)
                dept_match = Department.objects.filter(pk=ref_s).first()
            except (ValueError, TypeError):
                dept_match = (
                    Department.objects.filter(company=company, code__iexact=ref_s).first()
                    or Department.objects.filter(company=company, name__iexact=ref_s).first()
                )
            if dept_match:
                if dept_match.company_id != company.id:
                    raise PermissionDenied("Bạn không có quyền sử dụng dữ liệu này.")
                resolved_target_code = dept_match.code
                resolved_target_name = dept_match.name
                if primary_department is None:
                    primary_department = dept_match

        rate_val = _parse_decimal(t_row.get("rate") if "rate" in t_row else t_row.get("percentage"), default=None)
        if rate_val is None or rate_val <= Decimal("0") or rate_val > Decimal("100"):
            raise ValidationError({
                "targets": "Tổng tỷ lệ phân bổ phải bằng 100%.",
                "detail": "Tổng tỷ lệ phân bổ phải bằng 100%.",
            })
        total_rate += rate_val

        exp_raw = (
            t_row.get("expense_account")
            or t_row.get("cost_account")
            or t_row.get("costAccount")
        )
        exp_acc_obj = _resolve_expense_account_uc10(company, exp_raw)

        cost_item = str(t_row.get("cost_item") or t_row.get("costItem") or "").strip()
        stats_code = str(t_row.get("stats_code") or t_row.get("statCode") or "").strip()
        if bool(payload.get("require_cost_item", False)) and not cost_item:
            raise ValidationError({
                "cost_item": "Vui lòng chọn khoản mục chi phí theo chính sách của doanh nghiệp.",
                "detail": "Vui lòng chọn khoản mục chi phí theo chính sách của doanh nghiệp.",
            })

        normalized_targets.append({
            "line_no": t_idx,
            "target_code": resolved_target_code,
            "target_name": resolved_target_name,
            "rate": str(rate_val),
            "expense_account_id": str(exp_acc_obj.id),
            "expense_account_code": exp_acc_obj.code,
            "expense_account_obj": exp_acc_obj,
            "cost_item": cost_item,
            "stats_code": stats_code,
        })

    if abs(total_rate - Decimal("100")) > Decimal("0.0001"):
        raise ValidationError({
            "targets": "Tổng tỷ lệ phân bổ phải bằng 100%.",
            "detail": "Tổng tỷ lệ phân bổ phải bằng 100%.",
        })

    # Formula Section 4.3–4.7, Examples 4.10 & 4.11: Periodic allocation amount & schedule
    if rem_periods <= 0 or remaining_amount <= Decimal("0"):
        periodic_allocation_amount = Decimal("0")
        last_period_allocation_amount = Decimal("0")
    elif rem_periods == 1:
        periodic_allocation_amount = remaining_amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        last_period_allocation_amount = periodic_allocation_amount
    else:
        periodic_allocation_amount = (remaining_amount / Decimal(rem_periods)).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        last_period_allocation_amount = remaining_amount - periodic_allocation_amount * Decimal(rem_periods - 1)

    used_period_share = Decimal("0")
    for idx_t, t_item in enumerate(normalized_targets):
        r_dec = Decimal(str(t_item["rate"]))
        if idx_t == len(normalized_targets) - 1:
            t_share = max(Decimal("0"), periodic_allocation_amount - used_period_share)
        else:
            t_share = (periodic_allocation_amount * r_dec / Decimal("100")).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        used_period_share += t_share
        t_item["periodic_amount"] = str(t_share.quantize(Decimal("0.01")))

    stop_allocation = bool(payload.get("stop_allocation") or payload.get("suspend_allocation") or False)
    suspend_reason = str(payload.get("suspend_reason") or "").strip()
    raw_suspend_dt = payload.get("suspend_effective_date")
    suspend_dt = _parse_date_uc10(raw_suspend_dt) if raw_suspend_dt else record_dt

    # Section 6.2 & AF22: Determine Prepaid Expense status
    if rem_periods == 0 or remaining_amount == Decimal("0"):
        db_status = PrepaidExpense.Status.COMPLETED
        status_code = "FULLY_ALLOCATED"
        status_display = "Đã phân bổ hết"
    elif stop_allocation:
        db_status = PrepaidExpense.Status.STOPPED
        status_code = "SUSPENDED"
        status_display = "Ngừng phân bổ"
    elif start_dt > record_dt and not is_opening:
        db_status = PrepaidExpense.Status.ACTIVE
        status_code = "NOT_STARTED"
        status_display = "Chưa đến kỳ phân bổ"
    else:
        db_status = PrepaidExpense.Status.ACTIVE
        status_code = "ALLOCATING"
        status_display = "Đang phân bổ"

    targets_for_json = [
        {k: v for k, v in item.items() if k != "expense_account_obj"}
        for item in normalized_targets
    ]

    allocation_schedule = _build_monthly_schedule_uc10(
        start_dt=start_dt,
        periods_to_schedule=rem_periods,
        amount_to_allocate=remaining_amount,
        periodic_amount=periodic_allocation_amount,
        targets=targets_for_json,
        is_suspended=stop_allocation,
        start_period_index=opening_allocated_periods + 1,
    )

    # Persist in general_ledger.PrepaidExpense & PrepaidExpenseTarget
    prepaid_obj = PrepaidExpense.objects.create(
        company=company,
        code=code,
        name=name,
        record_date=record_dt,
        start_date=start_dt,
        amount=amount,
        allocation_periods=allocation_periods,
        prepaid_account=waiting_acc_obj,
        is_opening=is_opening,
        opening_allocated_amount=opening_allocated_amount,
        opening_allocated_periods=opening_allocated_periods,
        allocated_amount=Decimal("0"),
        allocated_periods=0,
        status=db_status,
        created_by=actor(request),
    )

    for item in normalized_targets:
        desc_parts = [item["target_name"]]
        if item["cost_item"]:
            desc_parts.append(f"KM:{item['cost_item']}")
        if item["stats_code"]:
            desc_parts.append(f"MTK:{item['stats_code']}")
        PrepaidExpenseTarget.objects.create(
            prepaid=prepaid_obj,
            line_no=item["line_no"],
            expense_account=item["expense_account_obj"],
            rate=Decimal(str(item["rate"])),
            description=" | ".join([p for p in desc_parts if p])[:255],
        )

    # Also store rich metadata in companion AssetRecord(source_module="PREPAID_EXPENSE") for source_documents & schedule tracking
    cat_obj, _ = models.AssetCategory.objects.get_or_create(
        company=company,
        code="CPTT-DEFAULT",
        defaults={
            "name": "Chi phí trả trước",
            "asset_type": models.AssetType.TOOL,
            "default_method": models.DepreciationMethod.STRAIGHT_LINE,
            "default_periods": allocation_periods,
            "asset_account": waiting_acc_obj,
        },
    )
    branch_obj = primary_department.branch if getattr(primary_department, "branch_id", None) else Branch.objects.filter(company=company).first()
    if not branch_obj:
        branch_obj = Branch.objects.create(company=company, code="HQ", name="Trụ sở chính")

    prepaid_meta = {
        "uc_id": "UC-FA-10",
        "prepaid_id": str(prepaid_obj.id),
        "is_opening": is_opening,
        "status_code": status_code,
        "status_display": status_display,
        "periodic_allocation_amount": str(periodic_allocation_amount.quantize(Decimal("0.01"))),
        "last_period_allocation_amount": str(last_period_allocation_amount.quantize(Decimal("0.01"))),
        "stop_allocation": stop_allocation,
        "suspend_reason": suspend_reason,
        "suspend_effective_date": suspend_dt.isoformat() if stop_allocation and suspend_dt else "",
        "allocation_schedule": allocation_schedule,
    }

    models.AssetRecord.objects.create(
        company=company,
        code=code,
        name=name,
        asset_type=models.AssetType.TOOL,
        category=cat_obj,
        branch=branch_obj,
        department=primary_department,
        quantity=Decimal("1"),
        acquisition_date=record_dt,
        in_service_date=start_dt,
        original_cost=amount,
        salvage_value=Decimal("0"),
        allocated_value=opening_allocated_amount,
        method=models.DepreciationMethod.STRAIGHT_LINE,
        useful_life_periods=allocation_periods,
        periods_processed=opening_allocated_periods,
        status=models.AssetStatus.SUSPENDED if stop_allocation else models.AssetStatus.ACTIVE,
        asset_account=waiting_acc_obj,
        acquisition_voucher_no=normalized_source_docs[0]["voucher_no"] if normalized_source_docs else code,
        source_module="PREPAID_EXPENSE",
        source_reference=normalized_source_docs[0]["voucher_no"] if normalized_source_docs else code,
        description=name,
        allocations=targets_for_json,
        origins=normalized_source_docs,
        accessories=[prepaid_meta],
        created_by=actor(request),
        updated_by=actor(request),
    )

    # Step 33 (Main Flow B) / BR44: Audit Log
    audit(
        request,
        prepaid_obj,
        "CREATE_PREPAID_OPENING" if is_opening else "CREATE_PREPAID",
        before={},
        after={
            "code": code,
            "name": name,
            "is_opening": is_opening,
            "record_date": record_dt.isoformat(),
            "start_date": start_dt.isoformat(),
            "amount": str(amount.quantize(Decimal("0.01"))),
            "allocated_amount": str(opening_allocated_amount.quantize(Decimal("0.01"))),
            "remaining_amount": str(remaining_amount.quantize(Decimal("0.01"))),
            "allocation_periods": allocation_periods,
            "remaining_periods": rem_periods,
            "periodic_allocation_amount": str(periodic_allocation_amount.quantize(Decimal("0.01"))),
            "waiting_account": waiting_acc_obj.code,
            "targets": targets_for_json,
            "source_documents": normalized_source_docs,
        },
        reason=name,
    )

    msg = "Đã lưu chi phí trả trước đầu kỳ thành công." if is_opening else "Đã lưu chi phí trả trước thành công."
    result = {
        "id": str(prepaid_obj.id),
        "prepaid_id": str(prepaid_obj.id),
        "code": code,
        "name": name,
        "is_opening": is_opening,
        "record_date": record_dt.isoformat(),
        "record_date_display": record_dt.strftime("%d/%m/%Y"),
        "start_date": start_dt.isoformat(),
        "start_date_display": start_dt.strftime("%d/%m/%Y"),
        "amount": str(amount.quantize(Decimal("0.01"))),
        "opening_allocated_amount": str(opening_allocated_amount.quantize(Decimal("0.01"))),
        "allocated_amount": str(opening_allocated_amount.quantize(Decimal("0.01"))),
        "remaining_amount": str(remaining_amount.quantize(Decimal("0.01"))),
        "allocation_periods": allocation_periods,
        "opening_allocated_periods": opening_allocated_periods,
        "allocated_periods": opening_allocated_periods,
        "remaining_periods": rem_periods,
        "periodic_allocation_amount": str(periodic_allocation_amount.quantize(Decimal("0.01"))),
        "last_period_allocation_amount": str(last_period_allocation_amount.quantize(Decimal("0.01"))),
        "waiting_account": waiting_acc_obj.code,
        "prepaid_account": str(waiting_acc_obj.id),
        "prepaid_account_code": waiting_acc_obj.code,
        "stop_allocation": stop_allocation,
        "status": prepaid_obj.status,
        "status_code": status_code,
        "status_display": status_display,
        "targets": targets_for_json,
        "source_documents": normalized_source_docs,
        "allocation_schedule": allocation_schedule,
        "next_prepaid_code": get_next_prepaid_code_uc10(company),
        "message": msg,
    }

    if idem_key:
        _UC10_IDEMPOTENCY_CACHE[f"{company.id}:PREPAID:{idem_key}"] = result

    return result


@transaction.atomic
def import_prepaid_expenses_excel_uc10(request, data=None) -> dict:
    """
    UC-FA-10 – AF18: Nhập chi phí trả trước từ Excel & EF38 (Tệp sai định dạng, thiếu cột bắt buộc,
    hoặc có giá trị không hợp lệ; báo lỗi theo dòng và cột; không tự tạo hồ sơ từ dòng không hợp lệ).
    """
    payload = data if isinstance(data, dict) else (request.data if hasattr(request, "data") and isinstance(request.data, dict) else {})
    company_id = payload.get("company") or payload.get("company_id") or (
        request.query_params.get("company_id") if hasattr(request, "query_params") else None
    )
    company = _resolve_company_for_uc10(request, company_id, permission_code="GL.ALLOCATION.CREATE")

    filename = str(payload.get("filename") or payload.get("file_name") or "Mau_Chi_Phi_Tra_Truoc.xlsx").strip()
    if not filename.lower().endswith((".xlsx", ".xls")):
        raise ValidationError({
            "filename": "Tệp nhập khẩu không đúng định dạng Excel (.xlsx, .xls).",
            "detail": "Tệp nhập khẩu không đúng định dạng Excel (.xlsx, .xls).",
            "file_error": "Tệp nhập khẩu không đúng định dạng Excel (.xlsx, .xls).",
        })

    required_columns = [
        "code", "name", "amount", "allocation_periods", "record_date", "start_date", "waiting_account", "target_code", "rate", "expense_account"
    ]
    provided_columns = payload.get("columns")
    if isinstance(provided_columns, list):
        col_set = {str(c).strip().lower() for c in provided_columns}
        missing_cols = [c for c in required_columns if c not in col_set]
        if missing_cols:
            raise ValidationError({
                "columns": f"Thiếu các cột bắt buộc trên tệp Excel: {', '.join(missing_cols)}.",
                "detail": f"Thiếu các cột bắt buộc trên tệp Excel: {', '.join(missing_cols)}.",
                "missing_columns": missing_cols,
            })

    rows = payload.get("rows") or payload.get("items") or []
    if not isinstance(rows, list) or len(rows) == 0:
        raise ValidationError({
            "rows": "Tệp Excel không có dữ liệu hợp lệ để nhập khẩu.",
            "detail": "Tệp Excel không có dữ liệu hợp lệ để nhập khẩu.",
        })

    row_errors = []
    valid_created = []
    seen_codes_in_file: set[str] = set()
    seen_sources_in_file: set[str] = set()

    for r_idx, row in enumerate(rows, start=1):
        if not isinstance(row, dict):
            row_errors.append({"row": r_idx, "column": "row", "message": "Dòng dữ liệu không đúng cấu trúc."})
            continue

        r_code = str(row.get("code") or "").strip()
        r_source = str(row.get("source_voucher_no") or "").strip()

        if r_code and r_code.upper() in seen_codes_in_file:
            row_errors.append({
                "row": r_idx,
                "column": "code",
                "message": "Mã chi phí trả trước bị trùng trong tệp Excel.",
            })
            continue
        if r_source and r_source.upper() in seen_sources_in_file:
            row_errors.append({
                "row": r_idx,
                "column": "source_voucher_no",
                "message": "Chứng từ nguồn bị trùng trong tệp Excel.",
            })
            continue

        row_payload = dict(row)
        row_payload["company"] = str(company.id)
        if "targets" not in row_payload and "allocations" not in row_payload:
            row_payload["targets"] = [{
                "target_code": row.get("target_code") or "",
                "target_name": row.get("target_name") or "",
                "rate": row.get("rate", 100),
                "expense_account": row.get("expense_account") or "",
                "cost_item": row.get("cost_item") or "",
                "stats_code": row.get("stats_code") or "",
            }]
        if r_source and "source_documents" not in row_payload:
            row_payload["source_documents"] = [{
                "voucher_no": r_source,
                "voucher_date": row.get("record_date"),
                "amount": row.get("amount"),
            }]

        try:
            with transaction.atomic():
                res = create_prepaid_expense_uc10(request, row_payload)
                valid_created.append(res)
                if r_code:
                    seen_codes_in_file.add(r_code.upper())
                if r_source:
                    seen_sources_in_file.add(r_source.upper())
        except ValidationError as exc:
            detail_dict = exc.detail if isinstance(exc.detail, dict) else {"detail": str(exc.detail)}
            col_name = next((k for k in detail_dict.keys() if k != "detail"), "detail")
            msg_val = detail_dict.get(col_name) or detail_dict.get("detail")
            if isinstance(msg_val, list) and msg_val:
                msg_val = str(msg_val[0])
            row_errors.append({
                "row": r_idx,
                "column": col_name,
                "message": str(msg_val),
            })

    if row_errors and bool(payload.get("strict_atomic", False)):
        raise ValidationError({
            "detail": "Tệp Excel có dòng dữ liệu không hợp lệ.",
            "row_errors": row_errors,
        })

    return {
        "company_id": str(company.id),
        "filename": filename,
        "sheet": str(payload.get("sheet") or "Sheet1"),
        "header_row": int(payload.get("header_row") or 1),
        "total_rows": len(rows),
        "success_count": len(valid_created),
        "error_count": len(row_errors),
        "created_items": valid_created,
        "row_errors": row_errors,
        "message": (
            f"Đã nhập thành công {len(valid_created)}/{len(rows)} khoản chi phí trả trước từ Excel."
            if valid_created
            else "Không có dòng chi phí trả trước nào hợp lệ để nhập."
        ),
    }


def get_tool_and_prepaid_register_uc10(request, data=None) -> dict:
    """
    UC-FA-10 – AF25: Xem lại đối tượng trên Sổ theo dõi CCDC và Danh sách chi phí trả trước.
    Returns both CCDC records (with independent physical_status and allocation_status per Section 6.1)
    and Prepaid Expense records (with status_display, remaining_amount, remaining_periods, schedule, source_documents).
    """
    from general_ledger.models import PrepaidExpense

    payload = data if isinstance(data, dict) else {}
    qp = request.query_params if hasattr(request, "query_params") else {}
    company_id = payload.get("company") or payload.get("company_id") or qp.get("company_id") or qp.get("company")
    company = _resolve_company_for_uc10(request, company_id, permission_code="FA.ASSET.VIEW")

    tools_qs = (
        models.AssetRecord.objects.filter(
            company=company,
            asset_type=models.AssetType.TOOL,
        )
        .exclude(source_module="PREPAID_EXPENSE")
        .select_related("category", "department", "asset_account")
        .order_by("code")
    )

    tool_items = []
    for t in tools_qs:
        meta = (t.accessories or [{}])[0] if isinstance(t.accessories, list) and t.accessories and isinstance(t.accessories[0], dict) else {}
        orig = (t.origins or [{}])[0] if isinstance(t.origins, list) and t.origins and isinstance(t.origins[0], dict) else {}
        rem_val = max(Decimal("0"), t.remaining_value).quantize(Decimal("0.01"))
        rem_periods = max(0, int(t.useful_life_periods or 0) - int(t.periods_processed or 0))

        # Section 6.1: Physical status vs Allocation status are independent
        phys_status = meta.get("physical_status") or ("DISPOSED" if t.status == models.AssetStatus.DISPOSED else "IN_USE")
        phys_display = "Đã ghi giảm" if phys_status == "DISPOSED" else "Đang sử dụng"
        in_use_qty_str = (
            str(meta.get("in_use_quantity"))
            if meta.get("in_use_quantity") is not None
            else ("0" if phys_status == "DISPOSED" else str(t.quantity))
        )

        if rem_val == Decimal("0.00"):
            alloc_status = "FULLY_ALLOCATED"
            alloc_display = "Đã phân bổ hết"
        elif t.status == models.AssetStatus.SUSPENDED or bool(meta.get("suspend_allocation")) or phys_status == "DISPOSED":
            alloc_status = "SUSPENDED"
            alloc_display = "Ngừng phân bổ"
        else:
            alloc_status = "ALLOCATING"
            alloc_display = "Đang phân bổ"

        tool_items.append({
            "id": str(t.id),
            "code": t.code,
            "name": t.name,
            "voucher_no": t.acquisition_voucher_no,
            "acquisition_date": t.acquisition_date.isoformat() if t.acquisition_date else "",
            "acquisition_date_display": t.acquisition_date.strftime("%d/%m/%Y") if t.acquisition_date else "",
            "category_name": t.category.name if t.category_id else "",
            "unit": meta.get("unit") or "Cái",
            "quantity": in_use_qty_str,
            "in_use_quantity": in_use_qty_str,
            "unit_price": meta.get("unit_price") or str((t.original_cost / t.quantity).quantize(Decimal("0.01")) if t.quantity else t.original_cost),
            "original_cost": str(t.original_cost.quantize(Decimal("0.01"))),
            "allocated_value": str(t.allocated_value.quantize(Decimal("0.01"))),
            "disposed_unallocated_value": str(Decimal(str(meta.get("disposed_unallocated_value") or "0")).quantize(Decimal("0.01"))),
            "remaining_value": str(rem_val),
            "useful_life_periods": t.useful_life_periods,
            "periods_processed": t.periods_processed,
            "remaining_periods": rem_periods,
            "periodic_allocation_amount": meta.get("periodic_allocation_amount") or "0.00",
            "waiting_account": t.asset_account.code if t.asset_account_id else "242",
            "physical_status": phys_status,
            "physical_status_display": phys_display,
            "allocation_status": alloc_status,
            "allocation_status_display": alloc_display,
            "department_allocations": t.components or [],
            "allocations": t.allocations or [],
            "origin": orig,
            "allocation_schedule": meta.get("allocation_schedule") or [],
            "disposal_history": meta.get("disposal_history") or [],
        })

    prepaid_qs = (
        PrepaidExpense.objects.filter(company=company)
        .select_related("prepaid_account")
        .prefetch_related("targets__expense_account")
        .order_by("code")
    )
    companion_map = {
        rec.code.upper(): rec
        for rec in models.AssetRecord.objects.filter(company=company, source_module="PREPAID_EXPENSE")
    }

    prepaid_items = []
    for p in prepaid_qs:
        comp = companion_map.get(p.code.upper())
        comp_meta = (comp.accessories or [{}])[0] if comp and isinstance(comp.accessories, list) and comp.accessories else {}
        tot_alloc = (p.opening_allocated_amount + p.allocated_amount).quantize(Decimal("0.01"))
        rem_amt = p.remaining_amount.quantize(Decimal("0.01"))
        rem_p = p.remaining_periods

        if p.status == PrepaidExpense.Status.DECREASED:
            st_display = "Đã ghi giảm"
        elif rem_amt <= Decimal("0") or p.status == PrepaidExpense.Status.COMPLETED:
            st_display = "Đã phân bổ hết"
        elif p.status == PrepaidExpense.Status.STOPPED:
            st_display = "Ngừng phân bổ"
        elif p.start_date > p.record_date and p.allocated_periods == 0 and not p.is_opening:
            st_display = "Chưa đến kỳ phân bổ"
        else:
            st_display = "Đang phân bổ"

        prepaid_items.append({
            "id": str(p.id),
            "code": p.code,
            "name": p.name,
            "is_opening": p.is_opening,
            "record_date": p.record_date.isoformat(),
            "record_date_display": p.record_date.strftime("%d/%m/%Y"),
            "start_date": p.start_date.isoformat(),
            "start_date_display": p.start_date.strftime("%d/%m/%Y"),
            "amount": str(p.amount.quantize(Decimal("0.01"))),
            "allocated_amount": str(tot_alloc),
            "remaining_amount": str(rem_amt),
            "allocation_periods": p.allocation_periods,
            "remaining_periods": rem_p,
            "waiting_account": p.prepaid_account.code,
            "status": p.status,
            "status_display": st_display,
            "targets": comp.allocations if comp and comp.allocations else [
                {
                    "line_no": t.line_no,
                    "target_name": t.description,
                    "rate": str(t.rate),
                    "expense_account_code": t.expense_account.code,
                }
                for t in p.targets.all()
            ],
            "source_documents": comp.origins if comp else [],
            "allocation_schedule": comp_meta.get("allocation_schedule") or [],
        })

    return {
        "company_id": str(company.id),
        "tools": tool_items,
        "prepaid_expenses": prepaid_items,
        "next_voucher_no": get_next_tool_voucher_no_uc10(company),
        "next_tool_code": get_next_tool_code_uc10(company),
        "next_prepaid_code": get_next_prepaid_code_uc10(company),
    }


# ==============================================================================
# UC-FA-11: THIẾT LẬP KỲ PHÂN BỔ (CCDC & CHI PHÍ TRẢ TRƯỚC)
# ==============================================================================

_UC11_IDEMPOTENCY_STORE = {}


def _normalize_uc11_allocation_type(raw_type):
    t = str(raw_type or "TOOL").strip().upper()
    if t in ("PREPAID", "CPTT", "PREPAID_EXPENSE", "CHI_PHI_TRA_TRUOC"):
        return "PREPAID"
    return "TOOL"


def _check_uc11_permission_and_scope(request, company, data=None):
    """
    EF01: Bạn không có quyền lập chứng từ phân bổ chi phí.
    EF17: Bạn không có quyền thực hiện phân bổ cho dữ liệu này.
    """
    from iam.permissions import has_effective_permission
    from general_ledger.models import PrepaidExpense

    payload = data if isinstance(data, dict) else {}
    err_perm = "Bạn không có quyền lập chứng từ phân bổ chi phí."
    err_scope = "Bạn không có quyền thực hiện phân bổ cho dữ liệu này."

    if str(payload.get("has_allocation_permission", "true")).lower() in ("false", "0") or str(
        payload.get("has_permission", "true")
    ).lower() in ("false", "0"):
        raise PermissionDenied(err_perm)

    if str(payload.get("has_scope_permission", "true")).lower() in ("false", "0") or str(
        payload.get("cross_company", "false")
    ).lower() in ("true", "1"):
        raise PermissionDenied(err_scope)

    target_company_id = payload.get("target_company_id") or payload.get("data_company_id")
    if target_company_id and str(target_company_id) != str(company.id):
        raise PermissionDenied(err_scope)

    if not request or not getattr(request, "user", None) or not request.user.is_authenticated:
        raise PermissionDenied(err_perm)

    if not getattr(request.user, "is_superuser", False):
        iam_acc = getattr(request.user, "iam_account", None)
        if not iam_acc:
            raise PermissionDenied(err_perm)
        if not iam_acc.company_memberships.filter(company=company).exists():
            if iam_acc.company_memberships.exists():
                raise PermissionDenied(err_scope)
            raise PermissionDenied(err_perm)
        candidate_codes = (
            "FA.CALCULATION.CALCULATE",
            "FA.CALCULATION.CREATE",
            "FA.ASSET.CREATE",
            "GL.JOURNAL.CREATE",
        )
        if not any(has_effective_permission(iam_acc, company, code) for code in candidate_codes):
            raise PermissionDenied(err_perm)

    # EF17: Verify explicit item_ids / tool_ids / prepaid_ids belong to company
    item_ids = payload.get("item_ids") or payload.get("tool_ids") or payload.get("prepaid_ids")
    if isinstance(item_ids, list) and item_ids:
        alloc_type = _normalize_uc11_allocation_type(payload.get("allocation_type") or payload.get("type"))
        clean_ids = [str(x).strip() for x in item_ids if str(x).strip()]
        if alloc_type == "TOOL":
            matched = models.AssetRecord.objects.filter(company=company, id__in=clean_ids).count()
            if matched != len(set(clean_ids)):
                raise PermissionDenied(err_scope)
        else:
            matched_p = PrepaidExpense.objects.filter(company=company, id__in=clean_ids).count()
            matched_a = models.AssetRecord.objects.filter(company=company, id__in=clean_ids).count()
            if max(matched_p, matched_a) != len(set(clean_ids)):
                raise PermissionDenied(err_scope)


def _get_working_period_uc11(company, data=None):
    """BR06: Determine default working month and year of the company."""
    from general_ledger.models import AccountingPeriod

    payload = data if isinstance(data, dict) else {}
    if payload.get("working_month") and payload.get("working_year"):
        try:
            wm = int(payload["working_month"])
            wy = int(payload["working_year"])
            if 1 <= wm <= 12 and 1900 <= wy <= 2100:
                return wm, wy
        except (TypeError, ValueError):
            pass

    open_ap = (
        models.AssetPeriod.objects.filter(company=company, status="OPEN")
        .order_by("-code")
        .first()
    )
    if open_ap and open_ap.start_date:
        return open_ap.start_date.month, open_ap.start_date.year

    open_glp = (
        AccountingPeriod.objects.filter(company=company, status="OPEN")
        .order_by("-fiscal_year", "-period_number")
        .first()
    )
    if open_glp and open_glp.start_date:
        return open_glp.start_date.month, open_glp.start_date.year

    today = timezone.localdate()
    return today.month, today.year


def _compute_period_dates_uc11(month, year):
    """
    Section 4.1, 4.2, 4.3 & BR08, BR09:
    Exact start date, leap year check, and end date of the selected allocation period.
    """
    is_leap_year = (year % 400 == 0) or (year % 4 == 0 and year % 100 != 0)
    if month in (1, 3, 5, 7, 8, 10, 12):
        last_day = 31
    elif month in (4, 6, 9, 11):
        last_day = 30
    else:
        last_day = 29 if is_leap_year else 28

    period_start = date_cls(year, month, 1)
    period_end = date_cls(year, month, last_day)
    period_code = f"{year:04d}-{month:02d}"
    return {
        "month": month,
        "year": year,
        "is_leap_year": is_leap_year,
        "days_in_month": last_day,
        "period_code": period_code,
        "period_start": period_start,
        "period_end": period_end,
        "period_start_display": period_start.strftime("%d/%m/%Y"),
        "period_end_display": period_end.strftime("%d/%m/%Y"),
    }


def _parse_and_validate_uc11_period(company, data):
    """
    Validates month (EF02, EF03), year (EF04, EF05), fiscal year setup (EF08),
    company data scope (EF06), locked period status (EF07), and period nature (AF08, AF09).
    """
    from general_ledger.models import AccountingPeriod

    payload = data if isinstance(data, dict) else {}
    raw_month = payload.get("month") if "month" in payload else payload.get("period_month")
    raw_year = payload.get("year") if "year" in payload else payload.get("period_year")

    # EF02: Tháng phân bổ bị bỏ trống
    if raw_month is None or str(raw_month).strip() == "":
        raise ValidationError({
            "month": "Vui lòng chọn tháng phân bổ.",
            "detail": "Vui lòng chọn tháng phân bổ.",
        })

    # EF03: Tháng phân bổ ngoài khoảng 1–12 hoặc không phải số nguyên
    if isinstance(raw_month, bool):
        raise ValidationError({
            "month": "Tháng phân bổ phải có giá trị từ 1 đến 12.",
            "detail": "Tháng phân bổ phải có giá trị từ 1 đến 12.",
        })
    try:
        month_str = str(raw_month).strip()
        if "." in month_str or "," in month_str:
            raise ValueError("Float not allowed")
        month = int(month_str)
    except (TypeError, ValueError):
        raise ValidationError({
            "month": "Tháng phân bổ phải có giá trị từ 1 đến 12.",
            "detail": "Tháng phân bổ phải có giá trị từ 1 đến 12.",
        })
    if month < 1 or month > 12:
        raise ValidationError({
            "month": "Tháng phân bổ phải có giá trị từ 1 đến 12.",
            "detail": "Tháng phân bổ phải có giá trị từ 1 đến 12.",
        })

    # EF04: Năm phân bổ bị bỏ trống
    if raw_year is None or str(raw_year).strip() == "":
        raise ValidationError({
            "year": "Vui lòng nhập năm phân bổ.",
            "detail": "Vui lòng nhập năm phân bổ.",
        })

    # EF05: Năm phân bổ sai định dạng hoặc không hợp lệ
    if isinstance(raw_year, bool):
        raise ValidationError({
            "year": "Năm phân bổ không hợp lệ.",
            "detail": "Năm phân bổ không hợp lệ.",
        })
    try:
        year_str = str(raw_year).strip()
        if "." in year_str or "," in year_str:
            raise ValueError("Float not allowed")
        year = int(year_str)
    except (TypeError, ValueError):
        raise ValidationError({
            "year": "Năm phân bổ không hợp lệ.",
            "detail": "Năm phân bổ không hợp lệ.",
        })
    if year < 1900 or year > 2100:
        raise ValidationError({
            "year": "Năm phân bổ không hợp lệ.",
            "detail": "Năm phân bổ không hợp lệ.",
        })

    period_info = _compute_period_dates_uc11(month, year)
    period_start = period_info["period_start"]
    period_end = period_info["period_end"]
    period_code = period_info["period_code"]

    # EF08: Chưa thiết lập niên độ kế toán hoặc kỳ kế toán tương ứng
    if str(payload.get("fiscal_year_configured", "true")).lower() in ("false", "0"):
        raise ValidationError({
            "period": "Chưa có thiết lập niên độ kế toán cho kỳ phân bổ đã chọn.",
            "detail": "Chưa có thiết lập niên độ kế toán cho kỳ phân bổ đã chọn.",
        })
    if str(payload.get("require_fiscal_year_setup", "false")).lower() in ("true", "1"):
        has_gl_fy = AccountingPeriod.objects.filter(company=company, fiscal_year=year).exists()
        has_fa_fy = models.AssetPeriod.objects.filter(
            company=company, start_date__year=year
        ).exists()
        if not has_gl_fy and not has_fa_fy:
            raise ValidationError({
                "period": "Chưa có thiết lập niên độ kế toán cho kỳ phân bổ đã chọn.",
                "detail": "Chưa có thiết lập niên độ kế toán cho kỳ phân bổ đã chọn.",
            })

    # EF06: Năm hoặc kỳ nằm ngoài phạm vi dữ liệu của doanh nghiệp
    if str(payload.get("out_of_company_scope", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "period": "Kỳ phân bổ không thuộc phạm vi dữ liệu kế toán của doanh nghiệp.",
            "detail": "Kỳ phân bổ không thuộc phạm vi dữ liệu kế toán của doanh nghiệp.",
        })
    min_year = payload.get("company_start_year")
    max_year = payload.get("company_end_year")
    if min_year is not None and str(min_year).strip() != "":
        try:
            if year < int(min_year):
                raise ValidationError({
                    "period": "Kỳ phân bổ không thuộc phạm vi dữ liệu kế toán của doanh nghiệp.",
                    "detail": "Kỳ phân bổ không thuộc phạm vi dữ liệu kế toán của doanh nghiệp.",
                })
        except ValueError:
            pass
    if max_year is not None and str(max_year).strip() != "":
        try:
            if year > int(max_year):
                raise ValidationError({
                    "period": "Kỳ phân bổ không thuộc phạm vi dữ liệu kế toán của doanh nghiệp.",
                    "detail": "Kỳ phân bổ không thuộc phạm vi dữ liệu kế toán của doanh nghiệp.",
                })
        except ValueError:
            pass

    company_start_date = _parse_date(payload.get("company_start_date"))
    company_end_date = _parse_date(payload.get("company_end_date"))
    if company_start_date and period_end < company_start_date:
        raise ValidationError({
            "period": "Kỳ phân bổ không thuộc phạm vi dữ liệu kế toán của doanh nghiệp.",
            "detail": "Kỳ phân bổ không thuộc phạm vi dữ liệu kế toán của doanh nghiệp.",
        })
    if company_end_date and period_start > company_end_date:
        raise ValidationError({
            "period": "Kỳ phân bổ không thuộc phạm vi dữ liệu kế toán của doanh nghiệp.",
            "detail": "Kỳ phân bổ không thuộc phạm vi dữ liệu kế toán của doanh nghiệp.",
        })

    # EF07: Kỳ kế toán đã khóa sổ
    is_locked = (
        str(payload.get("period_locked", "false")).lower() in ("true", "1")
        or _closed(company, period_end)
        or _closed(company, period_start)
        or models.AssetPeriod.objects.filter(
            company=company, code=period_code, status__in=("CLOSED", "LOCKED")
        ).exists()
        or AccountingPeriod.objects.filter(
            company=company, fiscal_year=year, period_number=month, status__in=("CLOSED", "LOCKED")
        ).exists()
    )
    if is_locked:
        raise ValidationError({
            "period": "Kỳ kế toán đã khóa, không thể lập chứng từ phân bổ trong kỳ này.",
            "detail": "Kỳ kế toán đã khóa, không thể lập chứng từ phân bổ trong kỳ này.",
        })

    # AF08 & AF09: Determine period nature (PAST, CURRENT, FUTURE)
    work_month, work_year = _get_working_period_uc11(company, payload)
    if (year, month) < (work_year, work_month):
        period_nature = "PAST"
    elif (year, month) > (work_year, work_month):
        period_nature = "FUTURE"
    else:
        period_nature = "CURRENT"

    future_policy = str(payload.get("future_period_policy") or "ALLOW").strip().upper()
    if period_nature == "FUTURE" and future_policy == "BLOCK":
        raise ValidationError({
            "period": "Kỳ phân bổ không thuộc phạm vi dữ liệu kế toán của doanh nghiệp.",
            "detail": "Kỳ phân bổ không thuộc phạm vi dữ liệu kế toán của doanh nghiệp.",
        })

    can_post_immediately = True
    if period_nature == "FUTURE" and future_policy == "DRAFT_ONLY":
        can_post_immediately = False

    period_info["period_nature"] = period_nature
    period_info["working_month"] = work_month
    period_info["working_year"] = work_year
    period_info["can_post_immediately"] = can_post_immediately
    return period_info


def get_next_tool_allocation_voucher_no_uc11(company, prefix="PBCC"):
    """BR26 & BR27: Propose unique voucher number for CCDC allocation (PBCC00001)."""
    from general_ledger.models import JournalEntry

    prefix_u = str(prefix or "PBCC").strip().upper()
    existing_calc = set(
        models.CalculationRun.objects.filter(company=company).values_list("number", flat=True)
    )
    existing_tx = set(
        models.AssetTransaction.objects.filter(company=company).values_list("number", flat=True)
    )
    existing_je = set(
        JournalEntry.objects.filter(company=company).values_list("number", flat=True)
    )
    all_existing = {str(x).strip().upper() for x in (existing_calc | existing_tx | existing_je) if x}

    max_seq = 0
    for code_str in all_existing:
        if code_str.startswith(prefix_u):
            tail = code_str[len(prefix_u):]
            if tail.isdigit():
                max_seq = max(max_seq, int(tail))
    seq = max_seq + 1
    while True:
        cand = f"{prefix_u}{seq:05d}"
        if cand.upper() not in all_existing:
            return cand
        seq += 1


