def _resolve_company_for_uc11(request, data=None):
    from organization.models import Company

    payload = data if isinstance(data, dict) else {}
    company_id = (
        request.query_params.get("company_id")
        or request.query_params.get("company")
        or payload.get("company_id")
        or payload.get("company")
    )
    if not company_id:
        raise PermissionDenied("Bạn không có quyền lập chứng từ phân bổ chi phí.")
    try:
        return Company.objects.get(pk=company_id)
    except (Company.DoesNotExist, ValueError, TypeError):
        raise PermissionDenied("Bạn không có quyền lập chứng từ phân bổ chi phí.")


def get_default_allocation_period_uc11(request, data=None):
    """
    UC-FA-11 Step 4 & BR06, BR07:
    Returns the default suggested Month/Year for the Period Selection dialog.
    """
    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc11(request, payload)
    _check_uc11_permission_and_scope(request, company, payload)

    alloc_type = _normalize_uc11_allocation_type(
        payload.get("allocation_type") or request.query_params.get("allocation_type")
    )
    default_month, default_year = _get_working_period_uc11(company, payload)
    dialog_title = (
        "Chọn kỳ phân bổ chi phí CCDC"
        if alloc_type == "TOOL"
        else "Chọn kỳ phân bổ chi phí"
    )
    return {
        "company_id": str(company.id),
        "allocation_type": alloc_type,
        "dialog_title": dialog_title,
        "default_month": default_month,
        "default_year": default_year,
        "months": list(range(1, 13)),
    }


def _prepare_tool_allocation_tabs_uc11(company, period_info, payload):
    """
    Prepares the 3 tabs (Xác định chi phí, Phân bổ, Hạch toán) for CCDC allocation (Main Flow A)
    with all integrity checks EF10, EF11, EF12, EF13 and alternative flows AF10–AF14, BR12–BR25.
    """
    period_start = period_info["period_start"]
    period_end = period_info["period_end"]
    period_code = period_info["period_code"]
    month = period_info["month"]
    year = period_info["year"]

    qs = (
        models.AssetRecord.objects.filter(company=company, asset_type=models.AssetType.TOOL)
        .exclude(source_module="PREPAID_EXPENSE")
        .select_related("category", "department", "asset_account")
        .order_by("code")
    )
    item_ids = payload.get("item_ids") or payload.get("tool_ids")
    if isinstance(item_ids, list) and item_ids:
        qs = qs.filter(id__in=[str(x).strip() for x in item_ids if str(x).strip()])

    tools = list(qs)
    valid_expense_prefixes = ("621", "622", "623", "627", "641", "642", "154", "241", "811")

    # Check posted CalculationRuns in this period for TOOL
    posted_lines_in_period = {}
    calc_lines_qs = models.CalculationLine.objects.filter(
        run__company=company,
        run__period_code=period_code,
        run__status="POSTED",
        asset__asset_type=models.AssetType.TOOL,
    ).select_related("run")
    for cl in calc_lines_qs:
        posted_lines_in_period[str(cl.asset_id)] = (
            posted_lines_in_period.get(str(cl.asset_id), Decimal("0")) + (cl.amount or Decimal("0"))
        )

    identify_rows = []
    allocation_rows = []
    accounting_rows = []
    total_allocation_amount = Decimal("0.00")
    total_active_amount = Decimal("0.00")
    total_disposed_remaining_amount = Decimal("0.00")
    fully_allocated_in_period_count = 0

    for tool in tools:
        meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
        if not isinstance(meta, dict):
            meta = {}

        # BR12 & BR17: Check start allocation date <= period_end
        start_alloc_date = tool.in_service_date or tool.acquisition_date
        if not start_alloc_date or start_alloc_date > period_end:
            continue

        # AF13 & BR19: Check suspended / stop_allocation status and effective date
        stop_alloc = bool(meta.get("stop_allocation", False)) or tool.status == models.AssetStatus.SUSPENDED or not tool.is_depreciable
        stop_eff_date = _parse_date(meta.get("stop_effective_date"))
        if stop_alloc:
            if not stop_eff_date or stop_eff_date <= period_start:
                continue

        # AF13 & BR20: Check disposed before period_start
        if tool.status == models.AssetStatus.DISPOSED:
            if not tool.disposed_at or tool.disposed_at < period_start:
                continue

        # EF13: Check consistency with adjustment or disposal vouchers
        if bool(meta.get("schedule_mismatch_with_adjustment", False)) or bool(
            payload.get("simulate_schedule_mismatch", False)
        ):
            raise ValidationError({
                "schedule": "Lịch phân bổ chưa khớp với chứng từ điều chỉnh hoặc ghi giảm.",
                "detail": "Lịch phân bổ chưa khớp với chứng từ điều chỉnh hoặc ghi giảm.",
                "item_code": tool.code,
            })

        unposted_conflict = tool.transactions.filter(
            transaction_type__in=(
                models.TransactionType.VALUE_INCREASE,
                models.TransactionType.VALUE_DECREASE,
                models.TransactionType.LIFE_CHANGE,
                "REVALUATION",
                models.TransactionType.DISPOSAL,
            ),
            status__in=("DRAFT", "PENDING_APPROVAL"),
            transaction_date__lte=period_end,
        ).exists()
        if unposted_conflict:
            raise ValidationError({
                "schedule": "Lịch phân bổ chưa khớp với chứng từ điều chỉnh hoặc ghi giảm.",
                "detail": "Lịch phân bổ chưa khớp với chứng từ điều chỉnh hoặc ghi giảm.",
                "item_code": tool.code,
            })

        # AF14 & BR21: Apply latest posted adjustments effective <= period_end
        total_allocatable = tool.original_cost if tool.original_cost is not None else Decimal("0")
        prior_allocated = tool.allocated_value if tool.allocated_value is not None else Decimal("0")
        total_periods = tool.useful_life_periods if tool.useful_life_periods is not None else 0
        periods_done = tool.periods_processed if tool.periods_processed is not None else 0

        if meta.get("adjusted_total_amount") is not None:
            total_allocatable = _parse_decimal(meta.get("adjusted_total_amount"), default=total_allocatable)
        if meta.get("prior_allocated_amount") is not None:
            prior_allocated = _parse_decimal(meta.get("prior_allocated_amount"), default=prior_allocated)

        # Subtract any amount already allocated IN this period from prior_allocated if it was already included in tool.allocated_value
        already_in_period_db = posted_lines_in_period.get(str(tool.id), Decimal("0"))
        period_alloc_map = meta.get("period_allocations") if isinstance(meta.get("period_allocations"), dict) else {}
        already_in_period_meta = _parse_decimal(period_alloc_map.get(period_code), default=Decimal("0")) or Decimal("0")
        already_in_period = max(already_in_period_db, already_in_period_meta)

        if already_in_period_db > Decimal("0") and prior_allocated >= already_in_period_db:
            prior_allocated_before_period = prior_allocated - already_in_period_db
        else:
            prior_allocated_before_period = prior_allocated

        # Section 4.5: Số tiền chưa phân bổ đầu kỳ = Tổng giá trị phân bổ sau điều chỉnh - Giá trị đã phân bổ lũy kế trước kỳ
        opening_remaining = (total_allocatable - prior_allocated_before_period).quantize(Decimal("0.01"))

        # EF11: Validate allocation numbers (non-negative remaining, valid total & prior allocated)
        if (
            bool(meta.get("invalid_allocation_numbers", False))
            or bool(payload.get("simulate_invalid_numbers", False))
            or total_allocatable <= Decimal("0")
            or prior_allocated_before_period < Decimal("0")
            or opening_remaining < Decimal("0")
            or total_periods < 0
            or (opening_remaining > Decimal("0") and periods_done > total_periods)
        ):
            raise ValidationError({
                "amount": "Số liệu phân bổ không hợp lệ. Vui lòng kiểm tra lịch sử phân bổ.",
                "detail": "Số liệu phân bổ không hợp lệ. Vui lòng kiểm tra lịch sử phân bổ.",
                "item_code": tool.code,
            })

        # AF12 & BR18: Exclude items already fully allocated prior to this period
        if opening_remaining == Decimal("0"):
            continue

        # EF10 & BR25: Check completeness of allocation setup
        raw_allocs = tool.allocations if isinstance(tool.allocations, list) else []
        if (
            bool(meta.get("incomplete_allocation_setup", False))
            or bool(payload.get("simulate_incomplete_setup", False))
            or total_periods <= 0
            or not tool.asset_account_id
            or not raw_allocs
        ):
            raise ValidationError({
                "allocations": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                "detail": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                "item_code": tool.code,
            })

        parsed_targets = []
        rate_sum = Decimal("0")
        for a_line in raw_allocs:
            if not isinstance(a_line, dict):
                raise ValidationError({
                    "allocations": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                    "detail": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                    "item_code": tool.code,
                })
            r_val = _parse_decimal(a_line.get("rate") if "rate" in a_line else a_line.get("percentage"), default=None)
            exp_acc = _resolve_account(
                company,
                a_line.get("expense_account_id") or a_line.get("expense_account") or a_line.get("expense_account_code") or a_line.get("costAccount"),
            )
            t_name = str(
                a_line.get("target_name") or a_line.get("department_name") or a_line.get("target_code") or a_line.get("department_code") or ""
            ).strip()
            if (
                r_val is None
                or r_val <= Decimal("0")
                or not exp_acc
                or exp_acc.company_id != company.id
                or exp_acc.status != "ACTIVE"
                or not exp_acc.is_postable
                or not any(exp_acc.code.startswith(p) for p in valid_expense_prefixes)
                or not t_name
            ):
                raise ValidationError({
                    "allocations": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                    "detail": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                    "item_code": tool.code,
                })
            rate_sum += r_val
            parsed_targets.append({
                "target_code": str(a_line.get("target_code") or a_line.get("department_code") or t_name).strip(),
                "target_name": t_name,
                "rate": r_val,
                "expense_account": exp_acc,
                "expense_item": str(a_line.get("expense_item") or a_line.get("costItem") or "Chi phí phân bổ CCDC").strip(),
                "statistical_code": str(a_line.get("statistical_code") or a_line.get("statCode") or "").strip(),
            })

        if abs(rate_sum - Decimal("100")) > Decimal("0.01"):
            raise ValidationError({
                "allocations": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                "detail": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                "item_code": tool.code,
            })

        # Compute full period allocation amount
        rem_periods = max(total_periods - periods_done, 1)
        has_adjusted_total = meta.get("adjusted_total_amount") is not None
        custom_periodic = (
            _parse_decimal(meta.get("adjusted_periodic_amount"), default=None)
            if has_adjusted_total
            else _parse_decimal(meta.get("periodic_allocation_amount"), default=None)
        )
        if rem_periods <= 1 or (tool.status == models.AssetStatus.DISPOSED and tool.disposed_at and period_start <= tool.disposed_at <= period_end):
            full_period_amt = opening_remaining
        elif custom_periodic is not None and custom_periodic > Decimal("0"):
            full_period_amt = min(opening_remaining, custom_periodic.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
        else:
            full_period_amt = min(
                opening_remaining,
                (opening_remaining / Decimal(rem_periods)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP),
            )

        # EF11: Periodic allocation amount must be > 0 and <= opening_remaining
        if full_period_amt <= Decimal("0") or full_period_amt > opening_remaining:
            raise ValidationError({
                "amount": "Số liệu phân bổ không hợp lệ. Vui lòng kiểm tra lịch sử phân bổ.",
                "detail": "Số liệu phân bổ không hợp lệ. Vui lòng kiểm tra lịch sử phân bổ.",
                "item_code": tool.code,
            })

        # Check period status: CHUA_PHAN_BO / DA_PHAN_BO_MOT_PHAN / DA_PHAN_BO_DU (AF10, EF12, BR14–BR16, BR22)
        explicit_status = str(meta.get("period_status", {}).get(period_code, "") if isinstance(meta.get("period_status"), dict) else "").upper()
        if explicit_status == "DA_PHAN_BO_DU" or already_in_period >= full_period_amt:
            fully_allocated_in_period_count += 1
            continue
        elif already_in_period > Decimal("0") or explicit_status == "DA_PHAN_BO_MOT_PHAN":
            period_alloc_status = "DA_PHAN_BO_MOT_PHAN"
            eligible_period_amt = min(opening_remaining - already_in_period, full_period_amt - already_in_period).quantize(Decimal("0.01"))
        else:
            period_alloc_status = "CHUA_PHAN_BO"
            eligible_period_amt = full_period_amt

        if eligible_period_amt <= Decimal("0") or eligible_period_amt > (opening_remaining - already_in_period):
            fully_allocated_in_period_count += 1
            continue

        is_disposed_in_period = bool(
            tool.status == models.AssetStatus.DISPOSED and tool.disposed_at and period_start <= tool.disposed_at <= period_end
        )
        active_amt = Decimal("0.00") if is_disposed_in_period else eligible_period_amt
        disposed_rem_amt = eligible_period_amt if is_disposed_in_period else Decimal("0.00")
        unallocated_before_this_voucher = (opening_remaining - already_in_period).quantize(Decimal("0.01"))

        identify_rows.append({
            "line_no": len(identify_rows) + 1,
            "item_id": str(tool.id),
            "code": tool.code,
            "name": tool.name,
            "category_name": tool.category.name if tool.category_id else "",
            "original_cost": str(total_allocatable.quantize(Decimal("0.01"))),
            "prior_allocated_amount": str(prior_allocated_before_period.quantize(Decimal("0.01"))),
            "already_allocated_in_period": str(already_in_period.quantize(Decimal("0.01"))),
            "opening_remaining_amount": str(opening_remaining),
            "unallocated_amount": str(unallocated_before_this_voucher),
            "total_allocation_amount": str(eligible_period_amt),
            "active_allocation_amount": str(active_amt),
            "disposed_remaining_amount": str(disposed_rem_amt),
            "useful_life_periods": total_periods,
            "remaining_periods": rem_periods,
            "waiting_account": tool.asset_account.code,
            "period_allocation_status": period_alloc_status,
        })

        total_allocation_amount += eligible_period_amt
        total_active_amount += active_amt
        total_disposed_remaining_amount += disposed_rem_amt

        # Tab 2 (Phân bổ) & Tab 3 (Hạch toán)
        running_split = Decimal("0.00")
        for idx, pt in enumerate(parsed_targets):
            if idx < len(parsed_targets) - 1:
                split_amt = (eligible_period_amt * pt["rate"] / Decimal("100")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                running_split += split_amt
            else:
                split_amt = (eligible_period_amt - running_split).quantize(Decimal("0.01"))

            allocation_rows.append({
                "line_no": len(allocation_rows) + 1,
                "item_id": str(tool.id),
                "code": tool.code,
                "name": tool.name,
                "target_code": pt["target_code"],
                "target_name": pt["target_name"],
                "department_name": pt["target_name"],
                "original_cost": str(total_allocatable.quantize(Decimal("0.01"))),
                "allocated_amount": str((prior_allocated_before_period + already_in_period).quantize(Decimal("0.01"))),
                "remaining_amount": str(unallocated_before_this_voucher),
                "allocation_periods": total_periods,
                "remaining_periods": rem_periods,
                "rate": str(pt["rate"].quantize(Decimal("0.01"))),
                "period_allocation_amount": str(split_amt),
                "waiting_account": tool.asset_account.code,
                "expense_account": pt["expense_account"].code,
                "expense_item": pt["expense_item"],
                "statistical_code": pt["statistical_code"],
            })

            accounting_rows.append({
                "line_no": len(accounting_rows) + 1,
                "item_id": str(tool.id),
                "code": tool.code,
                "description": f"Phân bổ chi phí CCDC {tool.code} - {tool.name} tháng {month:02d}/{year} ({pt['target_name']})",
                "debit_account": pt["expense_account"].code,
                "credit_account": tool.asset_account.code,
                "amount": str(split_amt),
                "expense_item": pt["expense_item"],
                "target_code": pt["target_code"],
                "target_name": pt["target_name"],
                "statistical_code": pt["statistical_code"],
            })

    if not identify_rows and fully_allocated_in_period_count > 0:
        # EF12 & BR16: Khoản chi phí đã được phân bổ đủ 100% trong kỳ đã chọn
        raise ValidationError({
            "period": "Khoản chi phí đã được phân bổ trong kỳ đã chọn.",
            "detail": "Khoản chi phí đã được phân bổ trong kỳ đã chọn.",
        })

    return {
        "identify_rows": identify_rows,
        "allocation_rows": allocation_rows,
        "accounting_rows": accounting_rows,
        "total_amount": str(total_allocation_amount.quantize(Decimal("0.01"))),
        "total_active_amount": str(total_active_amount.quantize(Decimal("0.01"))),
        "total_disposed_remaining_amount": str(total_disposed_remaining_amount.quantize(Decimal("0.01"))),
        "fully_allocated_in_period_count": fully_allocated_in_period_count,
    }


def _prepare_prepaid_allocation_tabs_uc11(company, period_info, payload):
    """
    Prepares the 3 tabs (Xác định chi phí, Phân bổ, Hạch toán) for Prepaid Expense allocation (Main Flow B)
    with all integrity checks EF10, EF11, EF12, EF13 and alternative flows AF10–AF14, BR12–BR25.
    """
    from general_ledger.models import PrepaidAllocation, PrepaidAllocationLine, PrepaidExpense

    period_start = period_info["period_start"]
    period_end = period_info["period_end"]
    period_code = period_info["period_code"]
    month = period_info["month"]
    year = period_info["year"]

    qs = (
        PrepaidExpense.objects.filter(company=company)
        .select_related("prepaid_account")
        .prefetch_related("targets__expense_account")
        .order_by("code")
    )
    item_ids = payload.get("item_ids") or payload.get("prepaid_ids")
    if isinstance(item_ids, list) and item_ids:
        qs = qs.filter(id__in=[str(x).strip() for x in item_ids if str(x).strip()])

    prepaid_list = list(qs)
    companion_map = {
        rec.code.upper(): rec
        for rec in models.AssetRecord.objects.filter(company=company, source_module="PREPAID_EXPENSE")
    }

    # Check posted PrepaidAllocationLines in this period (month, year)
    posted_in_period_map = {}
    pa_lines = PrepaidAllocationLine.objects.filter(
        allocation__company=company,
        allocation__kind=PrepaidAllocation.Kind.ALLOCATION,
        allocation__period__fiscal_year=year,
        allocation__period__period_number=month,
    )
    for pal in pa_lines:
        posted_in_period_map[str(pal.prepaid_id)] = (
            posted_in_period_map.get(str(pal.prepaid_id), Decimal("0")) + (pal.amount or Decimal("0"))
        )

    # Also check PrepaidDecrease vouchers in or before period
    decreases_before_period = set(
        PrepaidAllocationLine.objects.filter(
            allocation__company=company,
            allocation__kind=PrepaidAllocation.Kind.DECREASE,
            allocation__posting_date__lt=period_start,
        ).values_list("prepaid_id", flat=True)
    )

    valid_expense_prefixes = ("621", "622", "623", "627", "641", "642", "154", "241", "811")

    identify_rows = []
    allocation_rows = []
    accounting_rows = []
    total_prepaid_amount = Decimal("0.00")
    total_unallocated_amount = Decimal("0.00")
    total_period_allocation_amount = Decimal("0.00")
    fully_allocated_in_period_count = 0

    for item in prepaid_list:
        comp = companion_map.get(item.code.upper())
        comp_meta = (comp.accessories or [{}])[0] if comp and isinstance(comp.accessories, list) and comp.accessories else {}
        if not isinstance(comp_meta, dict):
            comp_meta = {}

        # BR12 & BR17: Check start_date <= period_end
        if not item.start_date or item.start_date > period_end:
            continue

        # AF13 & BR19: Check STOPPED / stop_allocation status and effective date
        stop_alloc = (
            item.status == PrepaidExpense.Status.STOPPED
            or bool(comp_meta.get("stop_allocation", False))
        )
        stop_eff_date = _parse_date(comp_meta.get("stop_effective_date"))
        if stop_alloc:
            if not stop_eff_date or stop_eff_date <= period_start:
                continue

        # AF13 & BR20: Check DECREASED before period_start
        if item.status == PrepaidExpense.Status.DECREASED or (
            item.id in decreases_before_period and comp_meta.get("decreased_amount") is None
        ):
            dec_date = _parse_date(comp_meta.get("decrease_effective_date"))
            if not dec_date or dec_date < period_start:
                continue

        # EF13: Check consistency with adjustment or decrease vouchers
        if bool(comp_meta.get("schedule_mismatch_with_adjustment", False)) or bool(
            payload.get("simulate_schedule_mismatch", False)
        ):
            raise ValidationError({
                "schedule": "Lịch phân bổ chưa khớp với chứng từ điều chỉnh hoặc ghi giảm.",
                "detail": "Lịch phân bổ chưa khớp với chứng từ điều chỉnh hoặc ghi giảm.",
                "item_code": item.code,
            })

        total_allocatable = item.amount if item.amount is not None else Decimal("0")
        if comp_meta.get("adjusted_total_amount") is not None:
            total_allocatable = _parse_decimal(comp_meta.get("adjusted_total_amount"), default=total_allocatable)

        already_in_period_db = posted_in_period_map.get(str(item.id), Decimal("0"))
        period_alloc_map = comp_meta.get("period_allocations") if isinstance(comp_meta.get("period_allocations"), dict) else {}
        already_in_period_meta = _parse_decimal(period_alloc_map.get(period_code), default=Decimal("0")) or Decimal("0")
        already_in_period = max(already_in_period_db, already_in_period_meta)

        total_allocated_so_far = (item.opening_allocated_amount or Decimal("0")) + (item.allocated_amount or Decimal("0"))
        if already_in_period_db > Decimal("0") and total_allocated_so_far >= already_in_period_db:
            prior_allocated_before_period = total_allocated_so_far - already_in_period_db
        else:
            prior_allocated_before_period = total_allocated_so_far

        if comp_meta.get("prior_allocated_amount") is not None:
            prior_allocated_before_period = _parse_decimal(comp_meta.get("prior_allocated_amount"), default=prior_allocated_before_period)

        # Section 4.5: Số tiền chưa phân bổ đầu kỳ = Tổng giá trị phân bổ sau điều chỉnh - Giá trị đã phân bổ lũy kế trước kỳ
        opening_remaining = (total_allocatable - prior_allocated_before_period).quantize(Decimal("0.01"))
        total_periods = item.allocation_periods or 0
        periods_done = (item.opening_allocated_periods or 0) + (item.allocated_periods or 0)
        if already_in_period_db > Decimal("0") and periods_done > 0:
            periods_done -= 1

        # EF11: Validate allocation numbers
        if (
            bool(comp_meta.get("invalid_allocation_numbers", False))
            or bool(payload.get("simulate_invalid_numbers", False))
            or total_allocatable <= Decimal("0")
            or prior_allocated_before_period < Decimal("0")
            or opening_remaining < Decimal("0")
            or total_periods < 0
            or (opening_remaining > Decimal("0") and periods_done > total_periods)
        ):
            raise ValidationError({
                "amount": "Số liệu phân bổ không hợp lệ. Vui lòng kiểm tra lịch sử phân bổ.",
                "detail": "Số liệu phân bổ không hợp lệ. Vui lòng kiểm tra lịch sử phân bổ.",
                "item_code": item.code,
            })

        # AF12 & BR18: Exclude items already fully allocated prior to this period
        if opening_remaining == Decimal("0") or (item.status == PrepaidExpense.Status.COMPLETED and opening_remaining == Decimal("0")):
            continue

        # EF10 & BR25: Check completeness of allocation setup
        targets_list = list(item.targets.all())
        if (
            bool(comp_meta.get("incomplete_allocation_setup", False))
            or bool(payload.get("simulate_incomplete_setup", False))
            or total_periods <= 0
            or not item.prepaid_account_id
            or not targets_list
        ):
            raise ValidationError({
                "allocations": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                "detail": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                "item_code": item.code,
            })

        parsed_targets = []
        rate_sum = Decimal("0")
        comp_allocs = comp.allocations if comp and isinstance(comp.allocations, list) else []
        for idx, t in enumerate(targets_list):
            ca = comp_allocs[idx] if idx < len(comp_allocs) and isinstance(comp_allocs[idx], dict) else {}
            r_val = t.rate
            exp_acc = t.expense_account
            t_name = str(t.description or ca.get("target_name") or ca.get("target_code") or "").strip()
            if (
                r_val is None
                or r_val <= Decimal("0")
                or not exp_acc
                or exp_acc.company_id != company.id
                or exp_acc.status != "ACTIVE"
                or not exp_acc.is_postable
                or not any(exp_acc.code.startswith(p) for p in valid_expense_prefixes)
                or not t_name
            ):
                raise ValidationError({
                    "allocations": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                    "detail": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                    "item_code": item.code,
                })
            rate_sum += r_val
            parsed_targets.append({
                "target_code": str(ca.get("target_code") or t_name).strip(),
                "target_name": t_name,
                "rate": r_val,
                "expense_account": exp_acc,
                "expense_item": str(ca.get("expense_item") or "Chi phí trả trước phân bổ").strip(),
                "statistical_code": str(ca.get("statistical_code") or "").strip(),
            })

        if abs(rate_sum - Decimal("100")) > Decimal("0.01"):
            raise ValidationError({
                "allocations": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                "detail": "Thiết lập phân bổ của đối tượng chưa đầy đủ. Vui lòng kiểm tra hồ sơ.",
                "item_code": item.code,
            })

        rem_periods = max(total_periods - periods_done, 1)
        custom_periodic = _parse_decimal(comp_meta.get("periodic_allocation_amount"), default=None)
        if rem_periods <= 1:
            full_period_amt = opening_remaining
        elif custom_periodic is not None and custom_periodic > Decimal("0"):
            full_period_amt = min(opening_remaining, custom_periodic.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
        else:
            full_period_amt = min(
                opening_remaining,
                (opening_remaining / Decimal(rem_periods)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP),
            )

        if full_period_amt <= Decimal("0") or full_period_amt > opening_remaining:
            raise ValidationError({
                "amount": "Số liệu phân bổ không hợp lệ. Vui lòng kiểm tra lịch sử phân bổ.",
                "detail": "Số liệu phân bổ không hợp lệ. Vui lòng kiểm tra lịch sử phân bổ.",
                "item_code": item.code,
            })

        # Check period status: CHUA_PHAN_BO / DA_PHAN_BO_MOT_PHAN / DA_PHAN_BO_DU
        explicit_status = str(comp_meta.get("period_status", {}).get(period_code, "") if isinstance(comp_meta.get("period_status"), dict) else "").upper()
        if explicit_status == "DA_PHAN_BO_DU" or already_in_period >= full_period_amt:
            fully_allocated_in_period_count += 1
            continue
        elif already_in_period > Decimal("0") or explicit_status == "DA_PHAN_BO_MOT_PHAN":
            period_alloc_status = "DA_PHAN_BO_MOT_PHAN"
            eligible_period_amt = min(opening_remaining - already_in_period, full_period_amt - already_in_period).quantize(Decimal("0.01"))
        else:
            period_alloc_status = "CHUA_PHAN_BO"
            eligible_period_amt = full_period_amt

        if eligible_period_amt <= Decimal("0") or eligible_period_amt > (opening_remaining - already_in_period):
            fully_allocated_in_period_count += 1
            continue

        unallocated_before_this_voucher = (opening_remaining - already_in_period).quantize(Decimal("0.01"))

        identify_rows.append({
            "line_no": len(identify_rows) + 1,
            "item_id": str(item.id),
            "code": item.code,
            "name": item.name,
            "total_amount": str(total_allocatable.quantize(Decimal("0.01"))),
            "prior_allocated_amount": str(prior_allocated_before_period.quantize(Decimal("0.01"))),
            "already_allocated_in_period": str(already_in_period.quantize(Decimal("0.01"))),
            "opening_remaining_amount": str(opening_remaining),
            "unallocated_amount": str(unallocated_before_this_voucher),
            "period_allocation_amount": str(eligible_period_amt),
            "allocation_periods": total_periods,
            "remaining_periods": rem_periods,
            "waiting_account": item.prepaid_account.code,
            "period_allocation_status": period_alloc_status,
        })

        total_prepaid_amount += total_allocatable.quantize(Decimal("0.01"))
        total_unallocated_amount += unallocated_before_this_voucher
        total_period_allocation_amount += eligible_period_amt

        running_split = Decimal("0.00")
        for idx, pt in enumerate(parsed_targets):
            if idx < len(parsed_targets) - 1:
                split_amt = (eligible_period_amt * pt["rate"] / Decimal("100")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                running_split += split_amt
            else:
                split_amt = (eligible_period_amt - running_split).quantize(Decimal("0.01"))

            allocation_rows.append({
                "line_no": len(allocation_rows) + 1,
                "item_id": str(item.id),
                "code": item.code,
                "name": item.name,
                "target_code": pt["target_code"],
                "target_name": pt["target_name"],
                "department_name": pt["target_name"],
                "total_amount": str(total_allocatable.quantize(Decimal("0.01"))),
                "allocated_amount": str((prior_allocated_before_period + already_in_period).quantize(Decimal("0.01"))),
                "remaining_amount": str(unallocated_before_this_voucher),
                "allocation_periods": total_periods,
                "remaining_periods": rem_periods,
                "rate": str(pt["rate"].quantize(Decimal("0.01"))),
                "period_allocation_amount": str(split_amt),
                "waiting_account": item.prepaid_account.code,
                "expense_account": pt["expense_account"].code,
                "expense_item": pt["expense_item"],
                "statistical_code": pt["statistical_code"],
            })

            accounting_rows.append({
                "line_no": len(accounting_rows) + 1,
                "item_id": str(item.id),
                "code": item.code,
                "description": f"Phân bổ chi phí trả trước {item.code} - {item.name} tháng {month:02d}/{year} ({pt['target_name']})",
                "debit_account": pt["expense_account"].code,
                "credit_account": item.prepaid_account.code,
                "amount": str(split_amt),
                "expense_item": pt["expense_item"],
                "target_code": pt["target_code"],
                "target_name": pt["target_name"],
                "statistical_code": pt["statistical_code"],
            })

    if not identify_rows and fully_allocated_in_period_count > 0:
        # EF12 & BR16: Khoản chi phí đã được phân bổ đủ 100% trong kỳ đã chọn
        raise ValidationError({
            "period": "Khoản chi phí đã được phân bổ trong kỳ đã chọn.",
            "detail": "Khoản chi phí đã được phân bổ trong kỳ đã chọn.",
        })

    return {
        "identify_rows": identify_rows,
        "allocation_rows": allocation_rows,
        "accounting_rows": accounting_rows,
        "total_amount": str(total_period_allocation_amount.quantize(Decimal("0.01"))),
        "total_prepaid_amount": str(total_prepaid_amount.quantize(Decimal("0.01"))),
        "total_unallocated_amount": str(total_unallocated_amount.quantize(Decimal("0.01"))),
        "fully_allocated_in_period_count": fully_allocated_in_period_count,
    }


def setup_allocation_period_uc11(request, data=None):
    """
    UC-FA-11 – Thiết lập kỳ phân bổ:
    - Main Flow A (Steps 1–11): Thiết lập kỳ phân bổ CCDC (`allocation_type="TOOL"` / `"CCDC"`).
    - Main Flow B (Steps 1–11): Thiết lập kỳ phân bổ chi phí trả trước (`allocation_type="PREPAID"` / `"CPTT"`).
    - Alternative Flows AF01–AF18 & Exception Flows EF01–EF17 & Business Rules BR01–BR34.
    - Pure preparation (BR29–BR31): Does NOT post GL entries or mutate allocated_value/remaining_value.
    """
    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc11(request, payload)
    _check_uc11_permission_and_scope(request, company, payload)

    alloc_type = _normalize_uc11_allocation_type(
        payload.get("allocation_type") or payload.get("type") or request.query_params.get("allocation_type")
    )
    period_info = _parse_and_validate_uc11_period(company, payload)
    month = period_info["month"]
    year = period_info["year"]

    # EF16: Idempotency check on rapid duplicate clicks of Đồng ý
    idem_key = str(payload.get("idempotency_key") or payload.get("request_id") or "").strip()
    cache_key = (str(company.id), alloc_type, month, year, idem_key) if idem_key else None
    if cache_key and cache_key in _UC11_IDEMPOTENCY_STORE:
        cached = dict(_UC11_IDEMPOTENCY_STORE[cache_key])
        cached["idempotent_replayed"] = True
        return cached

    # EF09: Lỗi truy xuất dữ liệu nguồn khi xác nhận kỳ
    if str(payload.get("simulate_source_load_error", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "detail": "Không thể tải dữ liệu phân bổ. Vui lòng thử lại.",
        })

    # EF14: Lỗi sinh số chứng từ đề xuất
    if (
        str(payload.get("simulate_numbering_error", "false")).lower() in ("true", "1")
        or str(payload.get("numbering_rule_configured", "true")).lower() in ("false", "0")
    ):
        raise ValidationError({
            "voucher_no": "Không thể đề xuất số chứng từ phân bổ. Vui lòng thử lại.",
            "detail": "Không thể đề xuất số chứng từ phân bổ. Vui lòng thử lại.",
        })

    # EF15: Không mở được form chứng từ sau khi chọn kỳ
    if str(payload.get("simulate_form_open_error", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "detail": "Không thể mở chứng từ phân bổ. Vui lòng thử lại.",
        })

    if alloc_type == "TOOL":
        suggested_voucher_no = get_next_tool_allocation_voucher_no_uc11(
            company, prefix=payload.get("prefix") or "PBCC"
        )
        default_description = f"Phân bổ chi phí CCDC tháng {month} năm {year}"
        form_title = f"Phân bổ chi phí CCDC {suggested_voucher_no}"
        tabs_data = _prepare_tool_allocation_tabs_uc11(company, period_info, payload)
    else:
        suggested_voucher_no = get_next_prepaid_allocation_voucher_no_uc11(
            company, prefix=payload.get("prefix") or "PBCP"
        )
        default_description = f"Phân bổ chi phí trả trước tháng {month} năm {year}"
        form_title = f"Phân bổ chi phí trả trước {suggested_voucher_no}"
        tabs_data = _prepare_prepaid_allocation_tabs_uc11(company, period_info, payload)

    has_eligible_items = len(tabs_data["identify_rows"]) > 0
    can_save = has_eligible_items
    empty_warning = "" if has_eligible_items else "Không có khoản chi phí cần phân bổ trong kỳ đã chọn."
    message = (
        f"Đã chuẩn bị chứng từ {form_title} cho kỳ tháng {month:02d}/{year}."
        if has_eligible_items
        else "Không có khoản chi phí cần phân bổ trong kỳ đã chọn."
    )

    ai_assisted = str(payload.get("ai_assisted", "false")).lower() in ("true", "1")
    result = {
        "company_id": str(company.id),
        "allocation_type": alloc_type,
        "form_title": form_title,
        "voucher_no": suggested_voucher_no,
        "posting_date": period_info["period_end_display"],
        "voucher_date": period_info["period_end_display"],
        "posting_date_iso": str(period_info["period_end"]),
        "voucher_date_iso": str(period_info["period_end"]),
        "month": month,
        "year": year,
        "period_code": period_info["period_code"],
        "period_start": period_info["period_start_display"],
        "period_end": period_info["period_end_display"],
        "period_start_iso": str(period_info["period_start"]),
        "period_end_iso": str(period_info["period_end"]),
        "is_leap_year": period_info["is_leap_year"],
        "days_in_month": period_info["days_in_month"],
        "period_nature": period_info["period_nature"],
        "can_post_immediately": period_info["can_post_immediately"],
        "description": default_description,
        "reference": str(payload.get("reference") or "").strip(),
        "default_tab": "identify",
        "tabs": ["identify", "allocation", "accounting"],
        "identify_rows": tabs_data["identify_rows"],
        "allocation_rows": tabs_data["allocation_rows"],
        "accounting_rows": tabs_data["accounting_rows"],
        "total_amount": tabs_data["total_amount"],
        "can_save": can_save,
        "empty_period_warning": empty_warning,
        "message": message,
        "ai_assisted": ai_assisted,
        "gl_posted": False,
        "state_mutated": False,
        "idempotent_replayed": False,
    }
    if alloc_type == "TOOL":
        result["total_active_amount"] = tabs_data["total_active_amount"]
        result["total_disposed_remaining_amount"] = tabs_data["total_disposed_remaining_amount"]
    else:
        result["total_prepaid_amount"] = tabs_data["total_prepaid_amount"]
        result["total_unallocated_amount"] = tabs_data["total_unallocated_amount"]

    if ai_assisted:
        result["ai_summary"] = (
            f"Sổ Việt AI đã đề xuất kỳ phân bổ {month:02d}/{year} với {len(tabs_data['identify_rows'])} khoản đủ điều kiện."
        )

    if cache_key:
        _UC11_IDEMPOTENCY_STORE[cache_key] = dict(result)
    return result


def validate_allocation_voucher_before_save_uc11(request, data=None):
    """
    UC-FA-11 AF17, EF18, EF19, BR27, BR34, BR35:
    Re-validates period, dates, voucher number uniqueness, source data freshness, and non-empty lines
    when the user edits header fields or clicks Lưu / Cất on the allocation voucher form.
    """
    from general_ledger.models import JournalEntry, PrepaidAllocation

    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc11(request, payload)
    _check_uc11_permission_and_scope(request, company, payload)

    alloc_type = _normalize_uc11_allocation_type(payload.get("allocation_type") or payload.get("type"))
    period_info = _parse_and_validate_uc11_period(company, payload)
    month = period_info["month"]
    year = period_info["year"]
    period_start = period_info["period_start"]
    period_end = period_info["period_end"]

    # EF18: Dữ liệu nguồn thay đổi sau khi mở form
    if str(payload.get("source_data_stale", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "detail": "Dữ liệu phân bổ đã thay đổi hoặc kỳ đã bị khóa sau khi mở form. Vui lòng tải lại dữ liệu.",
        })

    # AF17 & BR11 & BR35: Validate posting_date and voucher_date
    raw_posting_date = payload.get("posting_date") or period_info["period_end_display"]
    raw_voucher_date = payload.get("voucher_date") or raw_posting_date
    posting_date = _parse_date(raw_posting_date)
    voucher_date = _parse_date(raw_voucher_date)
    if not posting_date:
        raise ValidationError({
            "posting_date": "Ngày hạch toán không hợp lệ.",
            "detail": "Ngày hạch toán không hợp lệ.",
        })
    if not voucher_date:
        raise ValidationError({
            "voucher_date": "Ngày chứng từ không hợp lệ.",
            "detail": "Ngày chứng từ không hợp lệ.",
        })
    if posting_date < period_start or posting_date > period_end:
        raise ValidationError({
            "posting_date": "Ngày hạch toán phải thuộc kỳ phân bổ đã chọn.",
            "detail": "Ngày hạch toán phải thuộc kỳ phân bổ đã chọn.",
        })
    if voucher_date > posting_date:
        raise ValidationError({
            "voucher_date": "Ngày chứng từ không được lớn hơn ngày hạch toán.",
            "detail": "Ngày chứng từ không được lớn hơn ngày hạch toán.",
        })
    if _closed(company, posting_date):
        raise ValidationError({
            "period": "Kỳ kế toán đã khóa, không thể lập chứng từ phân bổ trong kỳ này.",
            "detail": "Kỳ kế toán đã khóa, không thể lập chứng từ phân bổ trong kỳ này.",
        })

    # EF19 & BR27: Check duplicate voucher_no
    voucher_no = str(payload.get("voucher_no") or payload.get("number") or "").strip()
    if not voucher_no:
        voucher_no = (
            get_next_tool_allocation_voucher_no_uc11(company)
            if alloc_type == "TOOL"
            else get_next_prepaid_allocation_voucher_no_uc11(company)
        )
    else:
        is_dup = (
            models.CalculationRun.objects.filter(company=company, number__iexact=voucher_no).exists()
            or models.AssetTransaction.objects.filter(company=company, number__iexact=voucher_no).exists()
            or PrepaidAllocation.objects.filter(company=company, number__iexact=voucher_no).exists()
            or JournalEntry.objects.filter(company=company, number__iexact=voucher_no).exists()
        )
        if is_dup:
            new_suggested = (
                get_next_tool_allocation_voucher_no_uc11(company)
                if alloc_type == "TOOL"
                else get_next_prepaid_allocation_voucher_no_uc11(company)
            )
            raise ValidationError({
                "voucher_no": "Số chứng từ đã tồn tại. Vui lòng chọn số khác hoặc sử dụng số được đề xuất mới.",
                "detail": "Số chứng từ đã tồn tại. Vui lòng chọn số khác hoặc sử dụng số được đề xuất mới.",
                "suggested_voucher_no": new_suggested,
            })

    # Re-evaluate current eligible items to ensure not empty (AF11 & BR34) and not stale (EF18)
    tabs_data = (
        _prepare_tool_allocation_tabs_uc11(company, period_info, payload)
        if alloc_type == "TOOL"
        else _prepare_prepaid_allocation_tabs_uc11(company, period_info, payload)
    )
    if not tabs_data["identify_rows"]:
        raise ValidationError({
            "items": "Không có khoản chi phí cần phân bổ trong kỳ đã chọn.",
            "detail": "Không có khoản chi phí cần phân bổ trong kỳ đã chọn.",
        })

    expected_count = payload.get("expected_item_count")
    if expected_count is not None and int(expected_count) != len(tabs_data["identify_rows"]):
        raise ValidationError({
            "detail": "Dữ liệu phân bổ đã thay đổi hoặc kỳ đã bị khóa sau khi mở form. Vui lòng tải lại dữ liệu.",
        })

    description = str(payload.get("description") or "").strip() or (
        f"Phân bổ chi phí CCDC tháng {month} năm {year}"
        if alloc_type == "TOOL"
        else f"Phân bổ chi phí trả trước tháng {month} năm {year}"
    )

    return {
        "valid": True,
        "company_id": str(company.id),
        "allocation_type": alloc_type,
        "voucher_no": voucher_no,
        "posting_date": posting_date.strftime("%d/%m/%Y"),
        "voucher_date": voucher_date.strftime("%d/%m/%Y"),
        "month": month,
        "year": year,
        "period_code": period_info["period_code"],
        "description": description,
        "total_amount": tabs_data["total_amount"],
        "identify_rows": tabs_data["identify_rows"],
        "allocation_rows": tabs_data["allocation_rows"],
        "accounting_rows": tabs_data["accounting_rows"],
    }


# ==============================================================================
# UC-FA-12 – TÍNH VÀ GHI NHẬN PHÂN BỔ (CCDC & CHI PHÍ TRẢ TRƯỚC)
# ==============================================================================

_UC12_IDEMPOTENCY_STORE: dict[tuple, dict] = {}


def _check_uc12_permission_and_scope(request, company, payload=None):
    """
    UC-FA-12 EF01 & BR01:
    Validates that the user has permission to calculate and post allocation vouchers for the company.
    """
    payload = payload or {}
    if not request or not getattr(request, "user", None) or not request.user.is_authenticated:
        raise PermissionDenied("Bạn không có quyền ghi nhận chứng từ phân bổ chi phí.")

    if str(payload.get("simulate_permission_denied", "false")).lower() in ("true", "1"):
        raise PermissionDenied("Bạn không có quyền ghi nhận chứng từ phân bổ chi phí.")

    if request.user.is_superuser:
        return

    iam_acc = getattr(request.user, "iam_account", None)
    if not iam_acc:
        raise PermissionDenied("Bạn không có quyền ghi nhận chứng từ phân bổ chi phí.")

    from iam.models import CompanyMembership
    from iam.permissions import has_effective_permission

    memberships = CompanyMembership.objects.filter(user=iam_acc)
    if memberships.exists() and not memberships.filter(company=company).exists():
        raise PermissionDenied("Bạn không có quyền ghi nhận chứng từ phân bổ chi phí.")

    candidate_codes = (
        "FA.CALCULATION.CALCULATE",
        "FA.CALCULATION.CREATE",
        "FA.CALCULATION.POST",
        "FA.ASSET.CREATE",
        "GL.JOURNAL.CREATE",
    )
    if not any(has_effective_permission(iam_acc, company, c) for c in candidate_codes):
        raise PermissionDenied("Bạn không có quyền ghi nhận chứng từ phân bổ chi phí.")


def _parse_and_validate_uc12_period(company, payload):
    """
    UC-FA-12 EF02 & EF06:
    Validates month (1..12), year (valid integer in allowed fiscal range), and period lock status.
    """
    raw_month = payload.get("month") if "month" in payload else payload.get("period_month")
    raw_year = payload.get("year") if "year" in payload else payload.get("period_year")

    if raw_month is None or raw_year is None or str(raw_month).strip() == "" or str(raw_year).strip() == "":
        raise ValidationError({
            "period": "Tháng hoặc năm phân bổ không hợp lệ.",
            "detail": "Tháng hoặc năm phân bổ không hợp lệ.",
        })

    if isinstance(raw_month, bool) or isinstance(raw_year, bool):
        raise ValidationError({
            "period": "Tháng hoặc năm phân bổ không hợp lệ.",
            "detail": "Tháng hoặc năm phân bổ không hợp lệ.",
        })

    try:
        m_str = str(raw_month).strip()
        y_str = str(raw_year).strip()
        if not re.match(r"^-?\d+$", m_str) or not re.match(r"^-?\d+$", y_str):
            raise ValueError("Invalid integer")
        month = int(m_str)
        year = int(y_str)
    except (ValueError, TypeError):
        raise ValidationError({
            "period": "Tháng hoặc năm phân bổ không hợp lệ.",
            "detail": "Tháng hoặc năm phân bổ không hợp lệ.",
        })

    if month < 1 or month > 12 or year < 1900 or year > 9999:
        raise ValidationError({
            "period": "Tháng hoặc năm phân bổ không hợp lệ.",
            "detail": "Tháng hoặc năm phân bổ không hợp lệ.",
        })

    min_year = payload.get("min_fiscal_year")
    max_year = payload.get("max_fiscal_year")
    if (min_year is not None and year < int(min_year)) or (max_year is not None and year > int(max_year)):
        raise ValidationError({
            "period": "Tháng hoặc năm phân bổ không hợp lệ.",
            "detail": "Tháng hoặc năm phân bổ không hợp lệ.",
        })

    days_in_month = calendar.monthrange(year, month)[1]
    period_start = date(year, month, 1)
    period_end = date(year, month, days_in_month)
    period_code = f"{year:04d}-{month:02d}"

    # EF06: Check if period is locked
    if (
        str(payload.get("period_locked", "false")).lower() in ("true", "1")
        or _closed(company, period_end)
        or models.AssetPeriod.objects.filter(
            company=company, code=period_code, status__in=("LOCKED", "CLOSED")
        ).exists()
    ):
        raise ValidationError({
            "period": "Kỳ kế toán đã khóa, không thể ghi nhận chứng từ phân bổ.",
            "detail": "Kỳ kế toán đã khóa, không thể ghi nhận chứng từ phân bổ.",
        })

    return {
        "month": month,
        "year": year,
        "days_in_month": days_in_month,
        "is_leap_year": calendar.isleap(year),
        "period_start": period_start,
        "period_end": period_end,
        "period_start_display": period_start.strftime("%d/%m/%Y"),
        "period_end_display": period_end.strftime("%d/%m/%Y"),
        "period_code": period_code,
    }


def _validate_uc12_attachments(payload):
    """
    UC-FA-12 AF19, EF27, BR30, BR31:
    Validates attachments (max 5MB per file, valid extensions).
    """
    if str(payload.get("simulate_attachment_error", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng cho phép.",
            "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng cho phép.",
        })

    raw_attachments = payload.get("attachments") or payload.get("files") or []
    if not isinstance(raw_attachments, list):
        raise ValidationError({
            "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng cho phép.",
            "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng cho phép.",
        })

    allowed_exts = {".pdf", ".doc", ".docx", ".xls", ".xlsx", ".jpg", ".jpeg", ".png", ".csv", ".txt", ".zip"}
    max_bytes = 5 * 1024 * 1024  # 5MB
    normalized = []

    for att in raw_attachments:
        if not isinstance(att, dict):
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng cho phép.",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng cho phép.",
            })
        file_name = str(att.get("file_name") or att.get("name") or "").strip()
        file_size = att.get("file_size") if "file_size" in att else att.get("size", 0)
        try:
            size_int = int(file_size or 0)
        except (ValueError, TypeError):
            size_int = max_bytes + 1

        ext = ""
        if "." in file_name:
            ext = "." + file_name.rsplit(".", 1)[-1].lower()

        if (
            not file_name
            or size_int < 0
            or size_int > max_bytes
            or (ext and ext not in allowed_exts)
            or bool(att.get("invalid", False))
        ):
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng cho phép.",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng cho phép.",
            })
        normalized.append({
            "file_name": file_name,
            "file_size": size_int,
            "file_type": ext.lstrip(".") or "pdf",
            "url": str(att.get("url") or f"/media/attachments/{file_name}"),
        })
    return normalized


def get_allocation_reference_vouchers_uc12(request, data=None):
    """
    UC-FA-12 AF01–AF03, EF24–EF26, BR26–BR29:
    Searches and validates reference vouchers for an allocation voucher without altering allocation amounts.
    """
    from general_ledger.models import JournalEntry, PrepaidAllocation

    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc11(request, payload)
    _check_uc12_permission_and_scope(request, company, payload)

    # EF26: Lỗi truy xuất dữ liệu chứng từ tham chiếu
    if str(payload.get("simulate_reference_load_error", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "reference": "Không thể tải danh sách chứng từ tham chiếu. Vui lòng thử lại.",
            "detail": "Không thể tải danh sách chứng từ tham chiếu. Vui lòng thử lại.",
        })

    # EF24: Không có quyền truy cập chứng từ tham chiếu
    if str(payload.get("simulate_reference_permission_error", "false")).lower() in ("true", "1"):
        raise PermissionDenied("Bạn không có quyền tham chiếu chứng từ này.")

    # Validate selected reference vouchers if provided
    selected_vouchers = payload.get("selected_vouchers") or payload.get("references")
    if isinstance(selected_vouchers, list):
        validated_refs = []
        for ref_item in selected_vouchers:
            if isinstance(ref_item, dict):
                if bool(ref_item.get("no_permission", False)):
                    raise PermissionDenied("Bạn không có quyền tham chiếu chứng từ này.")
                ref_company = ref_item.get("company_id") or ref_item.get("company")
                if ref_company and str(ref_company) != str(company.id):
                    raise PermissionDenied("Bạn không có quyền tham chiếu chứng từ này.")
                ref_status = str(ref_item.get("status") or "POSTED").upper()
                ref_no = str(ref_item.get("voucher_no") or ref_item.get("number") or "").strip()
                if (
                    bool(ref_item.get("invalid", False))
                    or bool(ref_item.get("is_deleted", False))
                    or ref_status in ("CANCELLED", "DELETED", "VOID", "REJECTED")
                    or not ref_no
                ):
                    raise ValidationError({
                        "reference": "Chứng từ tham chiếu không hợp lệ. Vui lòng chọn chứng từ khác.",
                        "detail": "Chứng từ tham chiếu không hợp lệ. Vui lòng chọn chứng từ khác.",
                    })
                validated_refs.append({
                    "voucher_no": ref_no,
                    "voucher_date": str(ref_item.get("voucher_date") or ref_item.get("date") or ""),
                    "description": str(ref_item.get("description") or ""),
                    "amount": str(ref_item.get("amount") or "0.00"),
                })
            elif isinstance(ref_item, str):
                r_no = ref_item.strip()
                if not r_no:
                    continue
                # Check if belongs to another company
                other_tx = models.AssetTransaction.objects.filter(number__iexact=r_no).exclude(company=company).first()
                other_je = JournalEntry.objects.filter(number__iexact=r_no).exclude(company=company).first()
                if other_tx or other_je:
                    raise PermissionDenied("Bạn không có quyền tham chiếu chứng từ này.")
                cancelled_tx = models.AssetTransaction.objects.filter(
                    company=company, number__iexact=r_no, status__in=("CANCELLED", "REJECTED")
                ).exists()
                if cancelled_tx:
                    raise ValidationError({
                        "reference": "Chứng từ tham chiếu không hợp lệ. Vui lòng chọn chứng từ khác.",
                        "detail": "Chứng từ tham chiếu không hợp lệ. Vui lòng chọn chứng từ khác.",
                    })
                validated_refs.append({"voucher_no": r_no})
    else:
        validated_refs = []

    from_date = _parse_date(payload.get("from_date"))
    to_date = _parse_date(payload.get("to_date"))
    voucher_type = str(payload.get("voucher_type") or "ALL").strip().upper()
    keyword = str(payload.get("keyword") or payload.get("search") or "").strip().lower()

    results = []
    if voucher_type in ("ALL", "ASSET_TX", "TOOL", "CCDC"):
        tx_qs = models.AssetTransaction.objects.filter(
            company=company, status="POSTED"
        ).select_related("asset").order_by("-transaction_date", "-created_at")
        if from_date:
            tx_qs = tx_qs.filter(transaction_date__gte=from_date)
        if to_date:
            tx_qs = tx_qs.filter(transaction_date__lte=to_date)
        for tx in tx_qs[:50]:
            desc = tx.reason or f"Chứng từ {tx.transaction_type} - {tx.asset.code}"
            if keyword and keyword not in tx.number.lower() and keyword not in desc.lower():
                continue
            results.append({
                "id": str(tx.id),
                "voucher_no": tx.number,
                "voucher_date": tx.transaction_date.strftime("%d/%m/%Y"),
                "posting_date": tx.transaction_date.strftime("%d/%m/%Y"),
                "voucher_type": tx.transaction_type,
                "description": desc,
                "amount": str((tx.amount or Decimal("0")).quantize(Decimal("0.01"))),
            })

    if voucher_type in ("ALL", "JOURNAL", "GL"):
        je_qs = JournalEntry.objects.filter(
            company=company, status="POSTED"
        ).order_by("-posting_date", "-created_at")
        if from_date:
            je_qs = je_qs.filter(posting_date__gte=from_date)
        if to_date:
            je_qs = je_qs.filter(posting_date__lte=to_date)
        for je in je_qs[:50]:
            desc = je.description or ""
            if keyword and keyword not in je.number.lower() and keyword not in desc.lower():
                continue
            results.append({
                "id": str(je.id),
                "voucher_no": je.number,
                "voucher_date": (je.document_date or je.posting_date).strftime("%d/%m/%Y"),
                "posting_date": je.posting_date.strftime("%d/%m/%Y"),
                "voucher_type": je.entry_type,
                "description": desc,
                "amount": str((je.total_debit or Decimal("0")).quantize(Decimal("0.01"))),
            })

    return {
        "company_id": str(company.id),
        "count": len(results),
        "vouchers": results,
        "validated_references": validated_refs,
        "reference_display": ", ".join(r["voucher_no"] for r in validated_refs),
    }


def _prepare_tool_allocation_tabs_uc12(company, period_info, payload):
    """
    UC-FA-12 Main Flow A (Steps 3–13), Section 4.1–4.5, AF06–AF16, EF11–EF23, EF28:
    Calculates the 3 tabs (Xác định chi phí, Phân bổ, Hạch toán) for CCDC allocation
    with exact UC-FA-12 exception messages.
    """
    from organization.models import Department

    period_start = period_info["period_start"]
    period_end = period_info["period_end"]
    period_code = period_info["period_code"]
    month = period_info["month"]
    year = period_info["year"]

    qs = (
        models.AssetRecord.objects.filter(company=company, asset_type=models.AssetType.TOOL)
        .select_related("category", "department", "asset_account", "accumulated_account")
        .order_by("code")
    )
    item_ids = payload.get("item_ids") or payload.get("asset_ids")
    if isinstance(item_ids, list) and item_ids:
        qs = qs.filter(id__in=[str(x).strip() for x in item_ids if str(x).strip()])

    tools = list(qs)
    valid_expense_prefixes = ("621", "622", "623", "627", "641", "642", "154", "241", "632", "811")

    posted_lines_in_period = {}
    calc_lines_qs = models.CalculationLine.objects.filter(
        run__company=company,
        run__period_code=period_code,
        run__status="POSTED",
        asset__asset_type=models.AssetType.TOOL,
    ).select_related("run")
    for cl in calc_lines_qs:
        posted_lines_in_period[str(cl.asset_id)] = (
            posted_lines_in_period.get(str(cl.asset_id), Decimal("0")) + (cl.amount or Decimal("0"))
        )

    # Map overrides if user adjusted amounts on the form (AF09, AF10)
    identify_overrides = {}
    if isinstance(payload.get("identify_rows_override"), list):
        for ov in payload["identify_rows_override"]:
            if isinstance(ov, dict) and (ov.get("code") or ov.get("item_id")):
                key = str(ov.get("code") or ov.get("item_id")).strip().upper()
                identify_overrides[key] = ov

    allocation_overrides_by_code = {}
    if isinstance(payload.get("allocation_rows_override"), list):
        for ov in payload["allocation_rows_override"]:
            if isinstance(ov, dict) and (ov.get("code") or ov.get("item_id")):
                key = str(ov.get("code") or ov.get("item_id")).strip().upper()
                allocation_overrides_by_code.setdefault(key, []).append(ov)

    identify_rows = []
    allocation_rows = []
    accounting_rows = []
    total_allocation_amount = Decimal("0.00")
    total_active_amount = Decimal("0.00")
    total_disposed_remaining_amount = Decimal("0.00")
    fully_allocated_codes = []

    for tool in tools:
        meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
        if not isinstance(meta, dict):
            meta = {}

        start_alloc_date = tool.in_service_date or tool.acquisition_date
        if not start_alloc_date or start_alloc_date > period_end:
            continue

        # AF12 & BR17: Check suspended / stop_allocation status and effective date
        stop_alloc = bool(meta.get("stop_allocation", False)) or tool.status == models.AssetStatus.SUSPENDED or not tool.is_depreciable
        stop_eff_date = _parse_date(meta.get("stop_effective_date"))
        if stop_alloc:
            if not stop_eff_date or stop_eff_date <= period_start:
                continue

        # Check disposed before period_start
        if tool.status == models.AssetStatus.DISPOSED:
            if not tool.disposed_at or tool.disposed_at < period_start:
                continue

        # EF16: Có kỳ phân bổ trước chưa hoàn tất
        if bool(meta.get("unallocated_prior_period", False)) or bool(payload.get("simulate_unallocated_prior_period", False)):
            raise ValidationError({
                "schedule": f"Có kỳ phân bổ trước chưa hoàn tất. Vui lòng kiểm tra lịch phân bổ của {tool.code}.",
                "detail": f"Có kỳ phân bổ trước chưa hoàn tất. Vui lòng kiểm tra lịch phân bổ của {tool.code}.",
                "item_code": tool.code,
            })

        # EF17: Lịch phân bổ của [Mã] chưa khớp với chứng từ điều chỉnh hoặc ghi giảm
        if bool(meta.get("schedule_mismatch_with_adjustment", False)) or bool(payload.get("simulate_schedule_mismatch", False)):
            raise ValidationError({
                "schedule": f"Lịch phân bổ của {tool.code} chưa khớp với chứng từ điều chỉnh hoặc ghi giảm.",
                "detail": f"Lịch phân bổ của {tool.code} chưa khớp với chứng từ điều chỉnh hoặc ghi giảm.",
                "item_code": tool.code,
            })

        unposted_conflict = tool.transactions.filter(
            transaction_type__in=(
                models.TransactionType.VALUE_INCREASE,
                models.TransactionType.VALUE_DECREASE,
                models.TransactionType.LIFE_CHANGE,
                "REVALUATION",
                models.TransactionType.DISPOSAL,
            ),
            status__in=("DRAFT", "PENDING_APPROVAL"),
            transaction_date__lte=period_end,
        ).exists()
        if unposted_conflict:
            raise ValidationError({
                "schedule": f"Lịch phân bổ của {tool.code} chưa khớp với chứng từ điều chỉnh hoặc ghi giảm.",
                "detail": f"Lịch phân bổ của {tool.code} chưa khớp với chứng từ điều chỉnh hoặc ghi giảm.",
                "item_code": tool.code,
            })

        total_allocatable = tool.original_cost if tool.original_cost is not None else Decimal("0")
        prior_allocated = tool.allocated_value if tool.allocated_value is not None else Decimal("0")
        total_periods = tool.useful_life_periods if tool.useful_life_periods is not None else 0
        periods_done = tool.periods_processed if tool.periods_processed is not None else 0

        if meta.get("adjusted_total_amount") is not None:
            total_allocatable = _parse_decimal(meta.get("adjusted_total_amount"), default=total_allocatable)
        if meta.get("prior_allocated_amount") is not None:
            prior_allocated = _parse_decimal(meta.get("prior_allocated_amount"), default=prior_allocated)

        already_in_period_db = posted_lines_in_period.get(str(tool.id), Decimal("0"))
        period_alloc_map = meta.get("period_allocations") if isinstance(meta.get("period_allocations"), dict) else {}
        already_in_period_meta = _parse_decimal(period_alloc_map.get(period_code), default=Decimal("0")) or Decimal("0")
        already_in_period = max(already_in_period_db, already_in_period_meta)

        if already_in_period_db > Decimal("0") and prior_allocated >= already_in_period_db:
            prior_allocated_before_period = prior_allocated - already_in_period_db
        else:
            prior_allocated_before_period = prior_allocated
        if meta.get("prior_allocated_amount") is not None:
            prior_allocated_before_period = _parse_decimal(meta.get("prior_allocated_amount"), default=prior_allocated_before_period)

        # EF12: Số tiền đã phân bổ của [Mã] vượt giá trị được phép phân bổ
        if prior_allocated_before_period > total_allocatable or bool(meta.get("exceed_allocatable", False)):
            raise ValidationError({
                "amount": f"Số tiền đã phân bổ của {tool.code} vượt giá trị được phép phân bổ.",
                "detail": f"Số tiền đã phân bổ của {tool.code} vượt giá trị được phép phân bổ.",
                "item_code": tool.code,
            })

        opening_remaining = (total_allocatable - prior_allocated_before_period).quantize(Decimal("0.01"))
        if meta.get("opening_remaining_override") is not None:
            opening_remaining = _parse_decimal(meta.get("opening_remaining_override"), default=opening_remaining)

        # EF13: Giá trị còn lại của [Mã] không hợp lệ
        expected_opening_rem = (total_allocatable - prior_allocated_before_period).quantize(Decimal("0.01"))
        if (
            opening_remaining < Decimal("0")
            or opening_remaining != expected_opening_rem
            or bool(meta.get("invalid_remaining_value", False))
            or bool(meta.get("invalid_allocation_numbers", False))
            or total_allocatable <= Decimal("0")
            or prior_allocated_before_period < Decimal("0")
        ):
            raise ValidationError({
                "amount": f"Giá trị còn lại của {tool.code} không hợp lệ.",
                "detail": f"Giá trị còn lại của {tool.code} không hợp lệ.",
                "item_code": tool.code,
            })

        # AF11 & BR07: Exclude items already fully allocated prior to this period
        if opening_remaining == Decimal("0") and already_in_period == Decimal("0"):
            continue

        # EF15: If explicitly flagged as already allocated in period
        if bool(meta.get("already_allocated_in_period_error", False)):
            raise ValidationError({
                "period": f"Khoản chi phí của {tool.code} đã được phân bổ trong kỳ.",
                "detail": f"Khoản chi phí của {tool.code} đã được phân bổ trong kỳ.",
                "item_code": tool.code,
            })

        # EF11: Thiết lập phân bổ của [Mã] chưa đầy đủ
        raw_allocs = tool.allocations if isinstance(tool.allocations, list) else []
        if (
            bool(meta.get("incomplete_allocation_setup", False))
            or bool(payload.get("simulate_incomplete_setup", False))
            or total_periods <= 0
            or not tool.asset_account_id
            or not raw_allocs
        ):
            raise ValidationError({
                "allocations": f"Thiết lập phân bổ của {tool.code} chưa đầy đủ.",
                "detail": f"Thiết lập phân bổ của {tool.code} chưa đầy đủ.",
                "item_code": tool.code,
            })

        # EF21: Check waiting account validity (must be active, postable, 242*)
        wait_acc = tool.asset_account
        if (
            not wait_acc
            or wait_acc.company_id != company.id
            or wait_acc.status != "ACTIVE"
            or not wait_acc.is_postable
            or not wait_acc.code.startswith("242")
            or bool(meta.get("invalid_waiting_account", False))
        ):
            raise ValidationError({
                "account": "Tài khoản phân bổ không hợp lệ. Vui lòng kiểm tra TK chờ và TK chi phí.",
                "detail": "Tài khoản phân bổ không hợp lệ. Vui lòng kiểm tra TK chờ và TK chi phí.",
                "item_code": tool.code,
            })

        parsed_targets = []
        rate_sum = Decimal("0")
        for a_line in raw_allocs:
            if not isinstance(a_line, dict):
                raise ValidationError({
                    "allocations": f"Thiết lập phân bổ của {tool.code} chưa đầy đủ.",
                    "detail": f"Thiết lập phân bổ của {tool.code} chưa đầy đủ.",
                    "item_code": tool.code,
                })
            r_val = _parse_decimal(a_line.get("rate") if "rate" in a_line else a_line.get("percentage"), default=None)
            raw_exp_ref = (
                a_line.get("expense_account_id")
                or a_line.get("expense_account")
                or a_line.get("expense_account_code")
                or a_line.get("costAccount")
            )
            if not raw_exp_ref and r_val is None:
                raise ValidationError({
                    "allocations": f"Thiết lập phân bổ của {tool.code} chưa đầy đủ.",
                    "detail": f"Thiết lập phân bổ của {tool.code} chưa đầy đủ.",
                    "item_code": tool.code,
                })
            t_code = str(a_line.get("target_code") or a_line.get("department_code") or "").strip()
            t_name = str(
                a_line.get("target_name") or a_line.get("department_name") or t_code or ""
            ).strip()
            dept_id = a_line.get("department_id")

            # EF19: Đối tượng hoặc đơn vị chịu chi phí của [Mã] không hợp lệ
            if not t_name or bool(a_line.get("invalid_target", False)) or bool(meta.get("invalid_target_department", False)):
                raise ValidationError({
                    "target": f"Đối tượng hoặc đơn vị chịu chi phí của {tool.code} không hợp lệ.",
                    "detail": f"Đối tượng hoặc đơn vị chịu chi phí của {tool.code} không hợp lệ.",
                    "item_code": tool.code,
                })
            if dept_id:
                dept_obj = Department.objects.filter(pk=dept_id).first()
                if not dept_obj or dept_obj.company_id != company.id or getattr(dept_obj, "status", "ACTIVE") != "ACTIVE" or not getattr(dept_obj, "is_active", True):
                    raise ValidationError({
                        "target": f"Đối tượng hoặc đơn vị chịu chi phí của {tool.code} không hợp lệ.",
                        "detail": f"Đối tượng hoặc đơn vị chịu chi phí của {tool.code} không hợp lệ.",
                        "item_code": tool.code,
                    })
            elif t_code:
                dept_by_code = Department.objects.filter(company=company, code__iexact=t_code).first()
                if dept_by_code and (getattr(dept_by_code, "status", "ACTIVE") != "ACTIVE" or not getattr(dept_by_code, "is_active", True)):
                    raise ValidationError({
                        "target": f"Đối tượng hoặc đơn vị chịu chi phí của {tool.code} không hợp lệ.",
                        "detail": f"Đối tượng hoặc đơn vị chịu chi phí của {tool.code} không hợp lệ.",
                        "item_code": tool.code,
                    })

            if not raw_exp_ref:
                raise ValidationError({
                    "allocations": f"Thiết lập phân bổ của {tool.code} chưa đầy đủ.",
                    "detail": f"Thiết lập phân bổ của {tool.code} chưa đầy đủ.",
                    "item_code": tool.code,
                })

            exp_acc = _resolve_account(company, raw_exp_ref)
            # EF21: Tài khoản phân bổ không hợp lệ. Vui lòng kiểm tra TK chờ và TK chi phí.
            if (
                not exp_acc
                or exp_acc.company_id != company.id
                or exp_acc.status != "ACTIVE"
                or not exp_acc.is_postable
                or not any(exp_acc.code.startswith(p) for p in valid_expense_prefixes)
                or exp_acc.code == wait_acc.code
                or bool(a_line.get("invalid_expense_account", False))
            ):
                raise ValidationError({
                    "account": "Tài khoản phân bổ không hợp lệ. Vui lòng kiểm tra TK chờ và TK chi phí.",
                    "detail": "Tài khoản phân bổ không hợp lệ. Vui lòng kiểm tra TK chờ và TK chi phí.",
                    "item_code": tool.code,
                })

            if r_val is None or r_val <= Decimal("0"):
                raise ValidationError({
                    "rate": f"Tổng tỷ lệ phân bổ của {tool.code} phải bằng 100%.",
                    "detail": f"Tổng tỷ lệ phân bổ của {tool.code} phải bằng 100%.",
                    "item_code": tool.code,
                })
            rate_sum += r_val
            parsed_targets.append({
                "target_code": t_code or t_name,
                "target_name": t_name,
                "rate": r_val,
                "expense_account": exp_acc,
                "expense_item": str(a_line.get("expense_item") or a_line.get("cost_item") or a_line.get("costItem") or "Chi phí phân bổ CCDC").strip(),
                "statistical_code": str(a_line.get("statistical_code") or a_line.get("stats_code") or a_line.get("statCode") or "").strip(),
            })

        # EF18: Tổng tỷ lệ phân bổ của [Mã] phải bằng 100%
        if abs(rate_sum - Decimal("100")) > Decimal("0.01"):
            raise ValidationError({
                "rate": f"Tổng tỷ lệ phân bổ của {tool.code} phải bằng 100%.",
                "detail": f"Tổng tỷ lệ phân bổ của {tool.code} phải bằng 100%.",
                "item_code": tool.code,
            })

        # Check CCDC disposal in period (Main Flow A Step 6, AF07, AF08, EF28, BR11–BR13)
        is_disposed_in_period = bool(
            (tool.status == models.AssetStatus.DISPOSED and tool.disposed_at and period_start <= tool.disposed_at <= period_end)
            or bool(meta.get("disposed_in_period", False))
        )
        disposal_handled_elsewhere = bool(meta.get("disposal_handled_on_disposal_voucher", False)) or bool(
            meta.get("disposal_remaining_allocated_by_voucher")
        )
        if is_disposed_in_period and disposal_handled_elsewhere:
            if bool(payload.get("force_disposed_remaining_allocation", False)) or bool(meta.get("force_disposed_remaining_allocation", False)):
                # EF28: Giá trị còn lại của CCDC đã được xử lý ở chứng từ ghi giảm.
                raise ValidationError({
                    "disposal": "Giá trị còn lại của CCDC đã được xử lý ở chứng từ ghi giảm.",
                    "detail": "Giá trị còn lại của CCDC đã được xử lý ở chứng từ ghi giảm.",
                    "item_code": tool.code,
                })

        rem_periods = max(total_periods - periods_done, 1)
        has_adjusted_total = meta.get("adjusted_total_amount") is not None
        custom_periodic = (
            _parse_decimal(meta.get("adjusted_periodic_amount"), default=None)
            if has_adjusted_total
            else _parse_decimal(meta.get("periodic_allocation_amount"), default=None)
        )

        if is_disposed_in_period:
            active_in_period = _parse_decimal(meta.get("active_allocation_in_disposal_period"), default=Decimal("0.00")) or Decimal("0.00")
            if disposal_handled_elsewhere:
                disposed_rem_in_period = Decimal("0.00")
            else:
                disposed_rem_in_period = max(Decimal("0.00"), opening_remaining - active_in_period)
            full_period_amt = (active_in_period + disposed_rem_in_period).quantize(Decimal("0.01"))
            if full_period_amt == Decimal("0.00"):
                continue
        else:
            if rem_periods <= 1:
                full_period_amt = opening_remaining
            elif custom_periodic is not None and custom_periodic > Decimal("0"):
                full_period_amt = min(opening_remaining, custom_periodic.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
            else:
                full_period_amt = min(
                    opening_remaining,
                    (opening_remaining / Decimal(rem_periods)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP),
                )
            active_in_period = full_period_amt
            disposed_rem_in_period = Decimal("0.00")

        # Check period status (AF14, AF15, EF15)
        explicit_status = str(meta.get("period_status", {}).get(period_code, "") if isinstance(meta.get("period_status"), dict) else "").upper()
        if explicit_status == "DA_PHAN_BO_DU" or (already_in_period > Decimal("0") and already_in_period >= full_period_amt):
            fully_allocated_codes.append(tool.code)
            if bool(payload.get("strict_duplicate_period", False)):
                raise ValidationError({
                    "period": f"Khoản chi phí của {tool.code} đã được phân bổ trong kỳ.",
                    "detail": f"Khoản chi phí của {tool.code} đã được phân bổ trong kỳ.",
                    "item_code": tool.code,
                })
            continue
        elif already_in_period > Decimal("0") or explicit_status == "DA_PHAN_BO_MOT_PHAN":
            period_alloc_status = "DA_PHAN_BO_MOT_PHAN"
            eligible_period_amt = min(opening_remaining - already_in_period, full_period_amt - already_in_period).quantize(Decimal("0.01"))
            if not is_disposed_in_period:
                active_in_period = eligible_period_amt
        else:
            period_alloc_status = "CHUA_PHAN_BO"
            eligible_period_amt = full_period_amt

        unallocated_before_this_voucher = (opening_remaining - already_in_period).quantize(Decimal("0.01"))

        # Check if user overrode the period allocation amount for this item (AF09, EF14)
        ov_item = identify_overrides.get(tool.code.upper()) or identify_overrides.get(str(tool.id).upper())
        if ov_item:
            ov_amt = _parse_decimal(
                ov_item.get("total_allocation_amount")
                if "total_allocation_amount" in ov_item
                else ov_item.get("period_allocation_amount"),
                default=eligible_period_amt,
            )
            if ov_amt is None or ov_amt <= Decimal("0") or ov_amt > unallocated_before_this_voucher:
                # EF14: Số tiền phân bổ kỳ này vượt giá trị còn lại của [Mã].
                raise ValidationError({
                    "amount": f"Số tiền phân bổ kỳ này vượt giá trị còn lại của {tool.code}.",
                    "detail": f"Số tiền phân bổ kỳ này vượt giá trị còn lại của {tool.code}.",
                    "item_code": tool.code,
                })
            eligible_period_amt = ov_amt.quantize(Decimal("0.01"))
            if not is_disposed_in_period:
                active_in_period = eligible_period_amt
            else:
                disposed_rem_in_period = max(Decimal("0.00"), eligible_period_amt - active_in_period)

        if eligible_period_amt > unallocated_before_this_voucher:
            raise ValidationError({
                "amount": f"Số tiền phân bổ kỳ này vượt giá trị còn lại của {tool.code}.",
                "detail": f"Số tiền phân bổ kỳ này vượt giá trị còn lại của {tool.code}.",
                "item_code": tool.code,
            })

        closing_remaining = (unallocated_before_this_voucher - eligible_period_amt).quantize(Decimal("0.01"))

        identify_rows.append({
            "line_no": len(identify_rows) + 1,
            "item_id": str(tool.id),
            "code": tool.code,
            "name": tool.name,
            "category_name": tool.category.name if tool.category_id else "",
            "original_cost": str(total_allocatable.quantize(Decimal("0.01"))),
            "prior_allocated_amount": str(prior_allocated_before_period.quantize(Decimal("0.01"))),
            "already_allocated_in_period": str(already_in_period.quantize(Decimal("0.01"))),
            "opening_remaining_amount": str(opening_remaining),
            "unallocated_amount": str(unallocated_before_this_voucher),
            "total_allocation_amount": str(eligible_period_amt),
            "active_allocation_amount": str(active_in_period.quantize(Decimal("0.01"))),
            "disposed_remaining_amount": str(disposed_rem_in_period.quantize(Decimal("0.01"))),
            "closing_remaining_amount": str(closing_remaining),
            "useful_life_periods": total_periods,
            "remaining_periods": rem_periods,
            "waiting_account": wait_acc.code,
            "period_allocation_status": period_alloc_status,
        })

        total_allocation_amount += eligible_period_amt
        total_active_amount += active_in_period
        total_disposed_remaining_amount += disposed_rem_in_period

        # Tab 2 (Phân bổ) & Tab 3 (Hạch toán)
        ov_alloc_rows = allocation_overrides_by_code.get(tool.code.upper()) or allocation_overrides_by_code.get(str(tool.id).upper())
        running_split = Decimal("0.00")
        item_split_sum = Decimal("0.00")

        for idx, pt in enumerate(parsed_targets):
            if ov_alloc_rows and idx < len(ov_alloc_rows) and ov_alloc_rows[idx].get("period_allocation_amount") is not None:
                split_amt = _parse_decimal(ov_alloc_rows[idx].get("period_allocation_amount"), default=Decimal("0")).quantize(Decimal("0.01"))
            else:
                if idx < len(parsed_targets) - 1:
                    split_amt = (eligible_period_amt * pt["rate"] / Decimal("100")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                    running_split += split_amt
                else:
                    split_amt = (eligible_period_amt - running_split).quantize(Decimal("0.01"))

            item_split_sum += split_amt

            allocation_rows.append({
                "line_no": len(allocation_rows) + 1,
                "item_id": str(tool.id),
                "code": tool.code,
                "name": tool.name,
                "target_code": pt["target_code"],
                "target_name": pt["target_name"],
                "department_name": pt["target_name"],
                "original_cost": str(total_allocatable.quantize(Decimal("0.01"))),
                "allocated_amount": str((prior_allocated_before_period + already_in_period).quantize(Decimal("0.01"))),
                "remaining_amount": str(unallocated_before_this_voucher),
                "allocation_periods": total_periods,
                "remaining_periods": rem_periods,
                "rate": str(pt["rate"].quantize(Decimal("0.01"))),
                "period_allocation_amount": str(split_amt),
                "waiting_account": wait_acc.code,
                "expense_account": pt["expense_account"].code,
                "expense_item": pt["expense_item"],
                "statistical_code": pt["statistical_code"],
            })

            accounting_rows.append({
                "line_no": len(accounting_rows) + 1,
                "item_id": str(tool.id),
                "code": tool.code,
                "description": f"Phân bổ chi phí CCDC {tool.code} - {tool.name} tháng {month:02d}/{year} ({pt['target_name']})",
                "debit_account": pt["expense_account"].code,
                "credit_account": wait_acc.code,
                "amount": str(split_amt),
                "expense_item": pt["expense_item"],
                "target_code": pt["target_code"],
                "target_name": pt["target_name"],
                "statistical_code": pt["statistical_code"],
            })

        # EF20: Số tiền phân bổ theo đối tượng không khớp với số tiền phân bổ kỳ này.
        if item_split_sum.quantize(Decimal("0.01")) != eligible_period_amt.quantize(Decimal("0.01")):
            raise ValidationError({
                "allocation_rows": "Số tiền phân bổ theo đối tượng không khớp với số tiền phân bổ kỳ này.",
                "detail": "Số tiền phân bổ theo đối tượng không khớp với số tiền phân bổ kỳ này.",
                "item_code": tool.code,
            })

    # EF15: If all items were already allocated in the selected period
    if not identify_rows and fully_allocated_codes:
        first_code = fully_allocated_codes[0]
        raise ValidationError({
            "period": f"Khoản chi phí của {first_code} đã được phân bổ trong kỳ.",
            "detail": f"Khoản chi phí của {first_code} đã được phân bổ trong kỳ.",
            "item_code": first_code,
        })

    # Validate accounting_rows_override if provided (EF21, EF22, EF23)
    if isinstance(payload.get("accounting_rows_override"), list):
        ov_acc_rows = []
        acc_sum = Decimal("0.00")
        for idx, ar in enumerate(payload["accounting_rows_override"], start=1):
            if not isinstance(ar, dict):
                raise ValidationError({
                    "accounting_rows": "Bút toán phân bổ không hợp lệ. Vui lòng kiểm tra tài khoản và số tiền.",
                    "detail": "Bút toán phân bổ không hợp lệ. Vui lòng kiểm tra tài khoản và số tiền.",
                })
            d_code = str(ar.get("debit_account") or "").strip()
            c_code = str(ar.get("credit_account") or "").strip()
            amt_val = _parse_decimal(ar.get("amount"), default=None)
            if not d_code or not c_code or d_code == c_code or amt_val is None or amt_val <= Decimal("0"):
                raise ValidationError({
                    "accounting_rows": "Bút toán phân bổ không hợp lệ. Vui lòng kiểm tra tài khoản và số tiền.",
                    "detail": "Bút toán phân bổ không hợp lệ. Vui lòng kiểm tra tài khoản và số tiền.",
                })
            d_acc = _resolve_account(company, d_code)
            c_acc = _resolve_account(company, c_code)
            if (
                not d_acc or not d_acc.is_postable or d_acc.status != "ACTIVE"
                or not c_acc or not c_acc.is_postable or c_acc.status != "ACTIVE"
                or not c_acc.code.startswith("242")
                or not any(d_acc.code.startswith(p) for p in valid_expense_prefixes)
            ):
                raise ValidationError({
                    "account": "Tài khoản phân bổ không hợp lệ. Vui lòng kiểm tra TK chờ và TK chi phí.",
                    "detail": "Tài khoản phân bổ không hợp lệ. Vui lòng kiểm tra TK chờ và TK chi phí.",
                })
            acc_sum += amt_val.quantize(Decimal("0.01"))
            ov_acc_rows.append({
                "line_no": idx,
                "item_id": str(ar.get("item_id") or ""),
                "code": str(ar.get("code") or ""),
                "description": str(ar.get("description") or f"Phân bổ chi phí CCDC tháng {month:02d}/{year}"),
                "debit_account": d_acc.code,
                "credit_account": c_acc.code,
                "amount": str(amt_val.quantize(Decimal("0.01"))),
                "expense_item": str(ar.get("expense_item") or ""),
                "target_code": str(ar.get("target_code") or ""),
                "target_name": str(ar.get("target_name") or ""),
                "statistical_code": str(ar.get("statistical_code") or ""),
            })
        if acc_sum.quantize(Decimal("0.01")) != total_allocation_amount.quantize(Decimal("0.01")):
            raise ValidationError({
                "accounting_rows": "Tổng tiền hạch toán không khớp với tổng tiền phân bổ.",
                "detail": "Tổng tiền hạch toán không khớp với tổng tiền phân bổ.",
            })
        accounting_rows = ov_acc_rows

    return {
        "identify_rows": identify_rows,
        "allocation_rows": allocation_rows,
        "accounting_rows": accounting_rows,
        "total_amount": str(total_allocation_amount.quantize(Decimal("0.01"))),
        "total_active_amount": str(total_active_amount.quantize(Decimal("0.01"))),
        "total_disposed_remaining_amount": str(total_disposed_remaining_amount.quantize(Decimal("0.01"))),
        "fully_allocated_in_period_count": len(fully_allocated_codes),
    }


def _prepare_prepaid_allocation_tabs_uc12(company, period_info, payload):
    """
    UC-FA-12 Main Flow B (Steps 3–12), Section 4.6–4.10, AF06, AF09–AF16, EF11–EF23:
    Calculates the 3 tabs (Xác định chi phí, Phân bổ, Hạch toán) for Chi phí trả trước
    with exact UC-FA-12 exception messages.
    """
    from general_ledger.models import PrepaidAllocation, PrepaidAllocationLine, PrepaidExpense
    from organization.models import Department

    period_start = period_info["period_start"]
    period_end = period_info["period_end"]
    period_code = period_info["period_code"]
    month = period_info["month"]
    year = period_info["year"]

    qs = (
        PrepaidExpense.objects.filter(company=company)
        .select_related("prepaid_account")
        .prefetch_related("targets__expense_account")
        .order_by("code")
    )
    item_ids = payload.get("item_ids") or payload.get("prepaid_ids")
    if isinstance(item_ids, list) and item_ids:
        qs = qs.filter(id__in=[str(x).strip() for x in item_ids if str(x).strip()])

    prepaid_list = list(qs)
    companion_map = {
        rec.code.upper(): rec
        for rec in models.AssetRecord.objects.filter(company=company, source_module="PREPAID_EXPENSE")
    }

    posted_in_period_map = {}
    pa_lines = PrepaidAllocationLine.objects.filter(
        allocation__company=company,
        allocation__kind=PrepaidAllocation.Kind.ALLOCATION,
        allocation__period__fiscal_year=year,
        allocation__period__period_number=month,
    )
    for pal in pa_lines:
        posted_in_period_map[str(pal.prepaid_id)] = (
            posted_in_period_map.get(str(pal.prepaid_id), Decimal("0")) + (pal.amount or Decimal("0"))
        )

    decreases_before_period = set(
        PrepaidAllocationLine.objects.filter(
            allocation__company=company,
            allocation__kind=PrepaidAllocation.Kind.DECREASE,
            allocation__posting_date__lt=period_start,
        ).values_list("prepaid_id", flat=True)
    )

    valid_expense_prefixes = ("621", "622", "623", "627", "641", "642", "154", "241", "632", "811")

    identify_overrides = {}
    if isinstance(payload.get("identify_rows_override"), list):
        for ov in payload["identify_rows_override"]:
            if isinstance(ov, dict) and (ov.get("code") or ov.get("item_id")):
                key = str(ov.get("code") or ov.get("item_id")).strip().upper()
                identify_overrides[key] = ov

    allocation_overrides_by_code = {}
    if isinstance(payload.get("allocation_rows_override"), list):
        for ov in payload["allocation_rows_override"]:
            if isinstance(ov, dict) and (ov.get("code") or ov.get("item_id")):
                key = str(ov.get("code") or ov.get("item_id")).strip().upper()
                allocation_overrides_by_code.setdefault(key, []).append(ov)

    identify_rows = []
    allocation_rows = []
    accounting_rows = []
    total_prepaid_amount = Decimal("0.00")
    total_unallocated_amount = Decimal("0.00")
    total_period_allocation_amount = Decimal("0.00")
    fully_allocated_codes = []

    for item in prepaid_list:
        comp = companion_map.get(item.code.upper())
        comp_meta = (comp.accessories or [{}])[0] if comp and isinstance(comp.accessories, list) and comp.accessories else {}
        if not isinstance(comp_meta, dict):
            comp_meta = {}

        if not item.start_date or item.start_date > period_end:
            continue

        stop_alloc = (
            item.status == PrepaidExpense.Status.STOPPED
            or bool(comp_meta.get("stop_allocation", False))
        )
        stop_eff_date = _parse_date(comp_meta.get("stop_effective_date"))
        if stop_alloc:
            if not stop_eff_date or stop_eff_date <= period_start:
                continue

        if item.status == PrepaidExpense.Status.DECREASED or (
            item.id in decreases_before_period and comp_meta.get("decreased_amount") is None
        ):
            dec_date = _parse_date(comp_meta.get("decrease_effective_date"))
            if not dec_date or dec_date < period_start:
                continue

        # EF16: Có kỳ phân bổ trước chưa hoàn tất
        if bool(comp_meta.get("unallocated_prior_period", False)) or bool(payload.get("simulate_unallocated_prior_period", False)):
            raise ValidationError({
                "schedule": f"Có kỳ phân bổ trước chưa hoàn tất. Vui lòng kiểm tra lịch phân bổ của {item.code}.",
                "detail": f"Có kỳ phân bổ trước chưa hoàn tất. Vui lòng kiểm tra lịch phân bổ của {item.code}.",
                "item_code": item.code,
            })

        # EF17: Lịch phân bổ của [Mã] chưa khớp với chứng từ điều chỉnh hoặc ghi giảm
        if bool(comp_meta.get("schedule_mismatch_with_adjustment", False)) or bool(payload.get("simulate_schedule_mismatch", False)):
            raise ValidationError({
                "schedule": f"Lịch phân bổ của {item.code} chưa khớp với chứng từ điều chỉnh hoặc ghi giảm.",
                "detail": f"Lịch phân bổ của {item.code} chưa khớp với chứng từ điều chỉnh hoặc ghi giảm.",
                "item_code": item.code,
            })

        total_allocatable = item.amount if item.amount is not None else Decimal("0")
        if comp_meta.get("adjusted_total_amount") is not None:
            total_allocatable = _parse_decimal(comp_meta.get("adjusted_total_amount"), default=total_allocatable)

        already_in_period_db = posted_in_period_map.get(str(item.id), Decimal("0"))
        period_alloc_map = comp_meta.get("period_allocations") if isinstance(comp_meta.get("period_allocations"), dict) else {}
        already_in_period_meta = _parse_decimal(period_alloc_map.get(period_code), default=Decimal("0")) or Decimal("0")
        already_in_period = max(already_in_period_db, already_in_period_meta)

        total_allocated_so_far = (item.opening_allocated_amount or Decimal("0")) + (item.allocated_amount or Decimal("0"))
        if already_in_period_db > Decimal("0") and total_allocated_so_far >= already_in_period_db:
            prior_allocated_before_period = total_allocated_so_far - already_in_period_db
        else:
            prior_allocated_before_period = total_allocated_so_far

        if comp_meta.get("prior_allocated_amount") is not None:
            prior_allocated_before_period = _parse_decimal(comp_meta.get("prior_allocated_amount"), default=prior_allocated_before_period)

        # EF12: Số tiền đã phân bổ của [Mã] vượt giá trị được phép phân bổ
        if prior_allocated_before_period > total_allocatable or bool(comp_meta.get("exceed_allocatable", False)):
            raise ValidationError({
                "amount": f"Số tiền đã phân bổ của {item.code} vượt giá trị được phép phân bổ.",
                "detail": f"Số tiền đã phân bổ của {item.code} vượt giá trị được phép phân bổ.",
                "item_code": item.code,
            })

        opening_remaining = (total_allocatable - prior_allocated_before_period).quantize(Decimal("0.01"))
        if comp_meta.get("opening_remaining_override") is not None:
            opening_remaining = _parse_decimal(comp_meta.get("opening_remaining_override"), default=opening_remaining)

        expected_opening_rem = (total_allocatable - prior_allocated_before_period).quantize(Decimal("0.01"))
        total_periods = item.allocation_periods or 0
        periods_done = (item.opening_allocated_periods or 0) + (item.allocated_periods or 0)
        if already_in_period_db > Decimal("0") and periods_done > 0:
            periods_done -= 1

        # EF13: Giá trị còn lại của [Mã] không hợp lệ
        if (
            opening_remaining < Decimal("0")
            or opening_remaining != expected_opening_rem
            or bool(comp_meta.get("invalid_remaining_value", False))
            or bool(comp_meta.get("invalid_allocation_numbers", False))
            or total_allocatable <= Decimal("0")
            or prior_allocated_before_period < Decimal("0")
        ):
            raise ValidationError({
                "amount": f"Giá trị còn lại của {item.code} không hợp lệ.",
                "detail": f"Giá trị còn lại của {item.code} không hợp lệ.",
                "item_code": item.code,
            })

        # AF11 & BR15: Exclude items already fully allocated prior to this period
        if (opening_remaining == Decimal("0") or item.status == PrepaidExpense.Status.COMPLETED) and already_in_period == Decimal("0"):
            continue

        if bool(comp_meta.get("already_allocated_in_period_error", False)):
            raise ValidationError({
                "period": f"Khoản chi phí của {item.code} đã được phân bổ trong kỳ.",
                "detail": f"Khoản chi phí của {item.code} đã được phân bổ trong kỳ.",
                "item_code": item.code,
            })

        # EF11: Thiết lập phân bổ của [Mã] chưa đầy đủ
        targets_list = list(item.targets.all())
        if (
            bool(comp_meta.get("incomplete_allocation_setup", False))
            or bool(payload.get("simulate_incomplete_setup", False))
            or total_periods <= 0
            or not item.prepaid_account_id
            or not targets_list
        ):
            raise ValidationError({
                "allocations": f"Thiết lập phân bổ của {item.code} chưa đầy đủ.",
                "detail": f"Thiết lập phân bổ của {item.code} chưa đầy đủ.",
                "item_code": item.code,
            })

        wait_acc = item.prepaid_account
        if (
            not wait_acc
            or wait_acc.company_id != company.id
            or wait_acc.status != "ACTIVE"
            or not wait_acc.is_postable
            or not wait_acc.code.startswith("242")
            or bool(comp_meta.get("invalid_waiting_account", False))
        ):
            raise ValidationError({
                "account": "Tài khoản phân bổ không hợp lệ. Vui lòng kiểm tra TK chờ và TK chi phí.",
                "detail": "Tài khoản phân bổ không hợp lệ. Vui lòng kiểm tra TK chờ và TK chi phí.",
                "item_code": item.code,
            })

        parsed_targets = []
        rate_sum = Decimal("0")
        comp_allocs = comp.allocations if comp and isinstance(comp.allocations, list) else []
        for idx, t in enumerate(targets_list):
            ca = comp_allocs[idx] if idx < len(comp_allocs) and isinstance(comp_allocs[idx], dict) else {}
            r_val = t.rate
            exp_acc = t.expense_account
            t_code = str(ca.get("target_code") or "").strip()
            t_name = str(t.description or ca.get("target_name") or t_code or "").strip()

            # EF19: Đối tượng hoặc đơn vị chịu chi phí của [Mã] không hợp lệ
            if not t_name or bool(ca.get("invalid_target", False)) or bool(comp_meta.get("invalid_target_department", False)):
                raise ValidationError({
                    "target": f"Đối tượng hoặc đơn vị chịu chi phí của {item.code} không hợp lệ.",
                    "detail": f"Đối tượng hoặc đơn vị chịu chi phí của {item.code} không hợp lệ.",
                    "item_code": item.code,
                })
            if t_code:
                dept_by_code = Department.objects.filter(company=company, code__iexact=t_code).first()
                if dept_by_code and (getattr(dept_by_code, "status", "ACTIVE") != "ACTIVE" or not getattr(dept_by_code, "is_active", True)):
                    raise ValidationError({
                        "target": f"Đối tượng hoặc đơn vị chịu chi phí của {item.code} không hợp lệ.",
                        "detail": f"Đối tượng hoặc đơn vị chịu chi phí của {item.code} không hợp lệ.",
                        "item_code": item.code,
                    })

            # EF21: Tài khoản phân bổ không hợp lệ
            if (
                not exp_acc
                or exp_acc.company_id != company.id
                or exp_acc.status != "ACTIVE"
                or not exp_acc.is_postable
                or not any(exp_acc.code.startswith(p) for p in valid_expense_prefixes)
                or exp_acc.code == wait_acc.code
                or bool(ca.get("invalid_expense_account", False))
            ):
                raise ValidationError({
                    "account": "Tài khoản phân bổ không hợp lệ. Vui lòng kiểm tra TK chờ và TK chi phí.",
                    "detail": "Tài khoản phân bổ không hợp lệ. Vui lòng kiểm tra TK chờ và TK chi phí.",
                    "item_code": item.code,
                })

            if r_val is None or r_val <= Decimal("0"):
                raise ValidationError({
                    "rate": f"Tổng tỷ lệ phân bổ của {item.code} phải bằng 100%.",
                    "detail": f"Tổng tỷ lệ phân bổ của {item.code} phải bằng 100%.",
                    "item_code": item.code,
                })
            rate_sum += r_val
            parsed_targets.append({
                "target_code": t_code or t_name,
                "target_name": t_name,
                "rate": r_val,
                "expense_account": exp_acc,
                "expense_item": str(ca.get("expense_item") or ca.get("cost_item") or "Chi phí trả trước phân bổ").strip(),
                "statistical_code": str(ca.get("statistical_code") or ca.get("stats_code") or "").strip(),
            })

        # EF18: Tổng tỷ lệ phân bổ của [Mã] phải bằng 100%
        if abs(rate_sum - Decimal("100")) > Decimal("0.01"):
            raise ValidationError({
                "rate": f"Tổng tỷ lệ phân bổ của {item.code} phải bằng 100%.",
                "detail": f"Tổng tỷ lệ phân bổ của {item.code} phải bằng 100%.",
                "item_code": item.code,
            })

        rem_periods = max(total_periods - periods_done, 1)
        custom_periodic = _parse_decimal(comp_meta.get("periodic_allocation_amount"), default=None)
        if rem_periods <= 1:
            full_period_amt = opening_remaining
        elif custom_periodic is not None and custom_periodic > Decimal("0"):
            full_period_amt = min(opening_remaining, custom_periodic.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
        else:
            full_period_amt = min(
                opening_remaining,
                (opening_remaining / Decimal(rem_periods)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP),
            )

        explicit_status = str(comp_meta.get("period_status", {}).get(period_code, "") if isinstance(comp_meta.get("period_status"), dict) else "").upper()
        if explicit_status == "DA_PHAN_BO_DU" or (already_in_period > Decimal("0") and already_in_period >= full_period_amt):
            fully_allocated_codes.append(item.code)
            if bool(payload.get("strict_duplicate_period", False)):
                raise ValidationError({
                    "period": f"Khoản chi phí của {item.code} đã được phân bổ trong kỳ.",
                    "detail": f"Khoản chi phí của {item.code} đã được phân bổ trong kỳ.",
                    "item_code": item.code,
                })
            continue
        elif already_in_period > Decimal("0") or explicit_status == "DA_PHAN_BO_MOT_PHAN":
            period_alloc_status = "DA_PHAN_BO_MOT_PHAN"
            eligible_period_amt = min(opening_remaining - already_in_period, full_period_amt - already_in_period).quantize(Decimal("0.01"))
        else:
            period_alloc_status = "CHUA_PHAN_BO"
            eligible_period_amt = full_period_amt

        unallocated_before_this_voucher = (opening_remaining - already_in_period).quantize(Decimal("0.01"))

        ov_item = identify_overrides.get(item.code.upper()) or identify_overrides.get(str(item.id).upper())
        if ov_item:
            ov_amt = _parse_decimal(
                ov_item.get("period_allocation_amount")
                if "period_allocation_amount" in ov_item
                else ov_item.get("total_allocation_amount"),
                default=eligible_period_amt,
            )
            if ov_amt is None or ov_amt <= Decimal("0") or ov_amt > unallocated_before_this_voucher:
                # EF14: Số tiền phân bổ kỳ này vượt giá trị còn lại của [Mã].
                raise ValidationError({
                    "amount": f"Số tiền phân bổ kỳ này vượt giá trị còn lại của {item.code}.",
                    "detail": f"Số tiền phân bổ kỳ này vượt giá trị còn lại của {item.code}.",
                    "item_code": item.code,
                })
            eligible_period_amt = ov_amt.quantize(Decimal("0.01"))

        if eligible_period_amt > unallocated_before_this_voucher:
            raise ValidationError({
                "amount": f"Số tiền phân bổ kỳ này vượt giá trị còn lại của {item.code}.",
                "detail": f"Số tiền phân bổ kỳ này vượt giá trị còn lại của {item.code}.",
                "item_code": item.code,
            })

        closing_remaining = (unallocated_before_this_voucher - eligible_period_amt).quantize(Decimal("0.01"))

        identify_rows.append({
            "line_no": len(identify_rows) + 1,
            "item_id": str(item.id),
            "code": item.code,
            "name": item.name,
            "start_date": item.start_date.strftime("%d/%m/%Y") if item.start_date else "",
            "total_amount": str(total_allocatable.quantize(Decimal("0.01"))),
            "prior_allocated_amount": str(prior_allocated_before_period.quantize(Decimal("0.01"))),
            "already_allocated_in_period": str(already_in_period.quantize(Decimal("0.01"))),
            "opening_remaining_amount": str(opening_remaining),
            "unallocated_amount": str(unallocated_before_this_voucher),
            "period_allocation_amount": str(eligible_period_amt),
            "closing_remaining_amount": str(closing_remaining),
            "allocation_periods": total_periods,
            "remaining_periods": rem_periods,
            "waiting_account": wait_acc.code,
            "period_allocation_status": period_alloc_status,
        })

        total_prepaid_amount += total_allocatable.quantize(Decimal("0.01"))
        total_unallocated_amount += unallocated_before_this_voucher
        total_period_allocation_amount += eligible_period_amt

        ov_alloc_rows = allocation_overrides_by_code.get(item.code.upper()) or allocation_overrides_by_code.get(str(item.id).upper())
        running_split = Decimal("0.00")
        item_split_sum = Decimal("0.00")

        for idx, pt in enumerate(parsed_targets):
            if ov_alloc_rows and idx < len(ov_alloc_rows) and ov_alloc_rows[idx].get("period_allocation_amount") is not None:
                split_amt = _parse_decimal(ov_alloc_rows[idx].get("period_allocation_amount"), default=Decimal("0")).quantize(Decimal("0.01"))
            else:
                if idx < len(parsed_targets) - 1:
                    split_amt = (eligible_period_amt * pt["rate"] / Decimal("100")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                    running_split += split_amt
                else:
                    split_amt = (eligible_period_amt - running_split).quantize(Decimal("0.01"))

            item_split_sum += split_amt

            allocation_rows.append({
                "line_no": len(allocation_rows) + 1,
                "item_id": str(item.id),
                "code": item.code,
                "name": item.name,
                "target_code": pt["target_code"],
                "target_name": pt["target_name"],
                "department_name": pt["target_name"],
                "total_amount": str(total_allocatable.quantize(Decimal("0.01"))),
                "allocated_amount": str((prior_allocated_before_period + already_in_period).quantize(Decimal("0.01"))),
                "remaining_amount": str(unallocated_before_this_voucher),
                "allocation_periods": total_periods,
                "remaining_periods": rem_periods,
                "rate": str(pt["rate"].quantize(Decimal("0.01"))),
                "period_allocation_amount": str(split_amt),
                "waiting_account": wait_acc.code,
                "expense_account": pt["expense_account"].code,
                "expense_item": pt["expense_item"],
                "statistical_code": pt["statistical_code"],
            })

            accounting_rows.append({
                "line_no": len(accounting_rows) + 1,
                "item_id": str(item.id),
                "code": item.code,
                "description": f"Phân bổ chi phí trả trước {item.code} - {item.name} tháng {month:02d}/{year} ({pt['target_name']})",
                "debit_account": pt["expense_account"].code,
                "credit_account": wait_acc.code,
                "amount": str(split_amt),
                "expense_item": pt["expense_item"],
                "target_code": pt["target_code"],
                "target_name": pt["target_name"],
                "statistical_code": pt["statistical_code"],
            })

        # EF20: Số tiền phân bổ theo đối tượng không khớp với số tiền phân bổ kỳ này.
        if item_split_sum.quantize(Decimal("0.01")) != eligible_period_amt.quantize(Decimal("0.01")):
            raise ValidationError({
                "allocation_rows": "Số tiền phân bổ theo đối tượng không khớp với số tiền phân bổ kỳ này.",
                "detail": "Số tiền phân bổ theo đối tượng không khớp với số tiền phân bổ kỳ này.",
                "item_code": item.code,
            })

    if not identify_rows and fully_allocated_codes:
        first_code = fully_allocated_codes[0]
        raise ValidationError({
            "period": f"Khoản chi phí của {first_code} đã được phân bổ trong kỳ.",
            "detail": f"Khoản chi phí của {first_code} đã được phân bổ trong kỳ.",
            "item_code": first_code,
        })

    if isinstance(payload.get("accounting_rows_override"), list):
        ov_acc_rows = []
        acc_sum = Decimal("0.00")
        for idx, ar in enumerate(payload["accounting_rows_override"], start=1):
            if not isinstance(ar, dict):
                raise ValidationError({
                    "accounting_rows": "Bút toán phân bổ không hợp lệ. Vui lòng kiểm tra tài khoản và số tiền.",
                    "detail": "Bút toán phân bổ không hợp lệ. Vui lòng kiểm tra tài khoản và số tiền.",
                })
            d_code = str(ar.get("debit_account") or "").strip()
            c_code = str(ar.get("credit_account") or "").strip()
            amt_val = _parse_decimal(ar.get("amount"), default=None)
            if not d_code or not c_code or d_code == c_code or amt_val is None or amt_val <= Decimal("0"):
                raise ValidationError({
                    "accounting_rows": "Bút toán phân bổ không hợp lệ. Vui lòng kiểm tra tài khoản và số tiền.",
                    "detail": "Bút toán phân bổ không hợp lệ. Vui lòng kiểm tra tài khoản và số tiền.",
                })
            d_acc = _resolve_account(company, d_code)
            c_acc = _resolve_account(company, c_code)
            if (
                not d_acc or not d_acc.is_postable or d_acc.status != "ACTIVE"
                or not c_acc or not c_acc.is_postable or c_acc.status != "ACTIVE"
                or not c_acc.code.startswith("242")
                or not any(d_acc.code.startswith(p) for p in valid_expense_prefixes)
            ):
                raise ValidationError({
                    "account": "Tài khoản phân bổ không hợp lệ. Vui lòng kiểm tra TK chờ và TK chi phí.",
                    "detail": "Tài khoản phân bổ không hợp lệ. Vui lòng kiểm tra TK chờ và TK chi phí.",
                })
            acc_sum += amt_val.quantize(Decimal("0.01"))
            ov_acc_rows.append({
                "line_no": idx,
                "item_id": str(ar.get("item_id") or ""),
                "code": str(ar.get("code") or ""),
                "description": str(ar.get("description") or f"Phân bổ chi phí trả trước tháng {month:02d}/{year}"),
                "debit_account": d_acc.code,
                "credit_account": c_acc.code,
                "amount": str(amt_val.quantize(Decimal("0.01"))),
                "expense_item": str(ar.get("expense_item") or ""),
                "target_code": str(ar.get("target_code") or ""),
                "target_name": str(ar.get("target_name") or ""),
                "statistical_code": str(ar.get("statistical_code") or ""),
            })
        if acc_sum.quantize(Decimal("0.01")) != total_period_allocation_amount.quantize(Decimal("0.01")):
            raise ValidationError({
                "accounting_rows": "Tổng tiền hạch toán không khớp với tổng tiền phân bổ.",
                "detail": "Tổng tiền hạch toán không khớp với tổng tiền phân bổ.",
            })
        accounting_rows = ov_acc_rows

    return {
        "identify_rows": identify_rows,
        "allocation_rows": allocation_rows,
        "accounting_rows": accounting_rows,
        "total_amount": str(total_period_allocation_amount.quantize(Decimal("0.01"))),
        "total_prepaid_amount": str(total_prepaid_amount.quantize(Decimal("0.01"))),
        "total_unallocated_amount": str(total_unallocated_amount.quantize(Decimal("0.01"))),
        "fully_allocated_in_period_count": len(fully_allocated_codes),
    }


def calculate_allocation_voucher_uc12(request, data=None):
    """
    UC-FA-12 Main Flow A (Steps 1–13) & Main Flow B (Steps 1–12),
    AF04–AF16, EF01, EF02, EF06, EF09–EF23, EF28:
    Calculates or recalculates the 3 tabs (Xác định chi phí, Phân bổ, Hạch toán) for CCDC or Chi phí trả trước.
    Does not mutate DB state until `save_and_post_allocation_voucher_uc12` is called.
    """
    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc11(request, payload)
    _check_uc12_permission_and_scope(request, company, payload)

    alloc_type = _normalize_uc11_allocation_type(
        payload.get("allocation_type") or payload.get("type") or (
            request.query_params.get("allocation_type") if hasattr(request, "query_params") else None
        )
    )
    period_info = _parse_and_validate_uc12_period(company, payload)
    month = period_info["month"]
    year = period_info["year"]

    # EF09: Lỗi truy xuất dữ liệu nguồn để tính phân bổ
    if str(payload.get("simulate_source_load_error", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "detail": "Không thể tải dữ liệu phân bổ. Vui lòng thử lại.",
        })

    if alloc_type == "TOOL":
        suggested_voucher_no = str(payload.get("voucher_no") or "").strip() or get_next_tool_allocation_voucher_no_uc11(
            company, prefix=payload.get("prefix") or "PBCC"
        )
        default_description = f"Phân bổ chi phí CCDC tháng {month} năm {year}"
        form_title = f"Phân bổ chi phí CCDC {suggested_voucher_no}"
        tabs_data = _prepare_tool_allocation_tabs_uc12(company, period_info, payload)
    else:
        suggested_voucher_no = str(payload.get("voucher_no") or "").strip() or get_next_prepaid_allocation_voucher_no_uc11(
            company, prefix=payload.get("prefix") or "PBCP"
        )
        default_description = f"Phân bổ chi phí trả trước tháng {month} năm {year}"
        form_title = f"Phân bổ chi phí trả trước {suggested_voucher_no}"
        tabs_data = _prepare_prepaid_allocation_tabs_uc12(company, period_info, payload)

    has_eligible = len(tabs_data["identify_rows"]) > 0
    if not has_eligible and bool(payload.get("strict_empty", False)):
        # EF10: Không có khoản chi phí cần phân bổ trong kỳ đã chọn.
        raise ValidationError({
            "items": "Không có khoản chi phí cần phân bổ trong kỳ đã chọn.",
            "detail": "Không có khoản chi phí cần phân bổ trong kỳ đã chọn.",
        })

    description = str(payload.get("description") or "").strip() or default_description
    result = {
        "company_id": str(company.id),
        "allocation_type": alloc_type,
        "form_title": form_title,
        "voucher_no": suggested_voucher_no,
        "posting_date": period_info["period_end_display"],
        "voucher_date": period_info["period_end_display"],
        "month": month,
        "year": year,
        "period_code": period_info["period_code"],
        "period_start": period_info["period_start_display"],
        "period_end": period_info["period_end_display"],
        "description": description,
        "reference": str(payload.get("reference") or "").strip(),
        "identify_rows": tabs_data["identify_rows"],
        "allocation_rows": tabs_data["allocation_rows"],
        "accounting_rows": tabs_data["accounting_rows"],
        "total_amount": tabs_data["total_amount"],
        "can_save": has_eligible,
        "empty_period_warning": "" if has_eligible else "Không có khoản chi phí cần phân bổ trong kỳ đã chọn.",
        "message": (
            f"Đã tính phân bổ kỳ tháng {month:02d}/{year}."
            if has_eligible
            else "Không có khoản chi phí cần phân bổ trong kỳ đã chọn."
        ),
        "gl_posted": False,
        "state_mutated": False,
    }
    if alloc_type == "TOOL":
        result["total_active_amount"] = tabs_data["total_active_amount"]
        result["total_disposed_remaining_amount"] = tabs_data["total_disposed_remaining_amount"]
    else:
        result["total_prepaid_amount"] = tabs_data["total_prepaid_amount"]
        result["total_unallocated_amount"] = tabs_data["total_unallocated_amount"]
    return result


def save_and_post_allocation_voucher_uc12(request, data=None):
    """
    UC-FA-12 Main Flow A (Steps 14–29) & Main Flow B (Steps 13–25),
    AF01–AF21, EF01–EF32, BR01–BR42:
    Validates header, references, attachments, calculation, and accounting entries;
    saves & posts the allocation voucher atomically; updates CCDC / PrepaidExpense balances,
    creates GL JournalEntry (Dr Expense / Cr 242), records AuditLog, and supports Cất và In.
    """
    from general_ledger.models import (
        Account,
        AccountingPeriod,
        JournalEntry,
        JournalLine,
        PrepaidAllocation,
        PrepaidAllocationLine,
        PrepaidExpense,
    )
    from general_ledger.services import post as post_gl_entry

    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc11(request, payload)
    _check_uc12_permission_and_scope(request, company, payload)

    alloc_type = _normalize_uc11_allocation_type(
        payload.get("allocation_type") or payload.get("type")
    )
    period_info = _parse_and_validate_uc12_period(company, payload)
    month = period_info["month"]
    year = period_info["year"]
    period_start = period_info["period_start"]
    period_end = period_info["period_end"]
    period_code = period_info["period_code"]

    # Idempotency check on duplicate click of Cất (EF30 / AF20)
    idem_key = str(payload.get("idempotency_key") or payload.get("request_id") or "").strip()
    cache_key = (str(company.id), alloc_type, period_code, idem_key) if idem_key else None
    if cache_key and cache_key in _UC12_IDEMPOTENCY_STORE:
        if bool(payload.get("reject_duplicate_submission", False)):
            raise ValidationError({
                "detail": "Khoản phân bổ đã được xử lý bởi chứng từ khác. Vui lòng tải lại dữ liệu.",
            })
        cached = dict(_UC12_IDEMPOTENCY_STORE[cache_key])
        cached["idempotent_replayed"] = True
        return cached

    # EF30: Concurrent voucher already processed this allocation
    if str(payload.get("concurrent_processed", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "detail": "Khoản phân bổ đã được xử lý bởi chứng từ khác. Vui lòng tải lại dữ liệu.",
        })

    # EF29: Dữ liệu nguồn thay đổi sau khi tính nhưng trước khi cất
    if str(payload.get("source_data_changed", "false")).lower() in ("true", "1") or str(payload.get("source_data_stale", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "detail": "Dữ liệu phân bổ đã thay đổi. Vui lòng tính lại trước khi ghi nhận.",
        })

    # EF03: Thiếu diễn giải chứng từ
    if "description" in payload:
        raw_desc = str(payload.get("description") or "").strip()
        if not raw_desc:
            raise ValidationError({
                "description": "Vui lòng nhập diễn giải chứng từ.",
                "detail": "Vui lòng nhập diễn giải chứng từ.",
            })
        description = raw_desc
    else:
        if bool(payload.get("require_description", False)):
            raise ValidationError({
                "description": "Vui lòng nhập diễn giải chứng từ.",
                "detail": "Vui lòng nhập diễn giải chứng từ.",
            })
        description = (
            f"Phân bổ chi phí CCDC tháng {month} năm {year}"
            if alloc_type == "TOOL"
            else f"Phân bổ chi phí trả trước tháng {month} năm {year}"
        )

    # EF04: Ngày hạch toán không hợp lệ
    if "posting_date" in payload and not str(payload.get("posting_date") or "").strip():
        raise ValidationError({
            "posting_date": "Vui lòng nhập ngày hạch toán hợp lệ.",
            "detail": "Vui lòng nhập ngày hạch toán hợp lệ.",
        })
    raw_posting_date = payload.get("posting_date") or period_info["period_end_display"]
    posting_date = _parse_date(raw_posting_date)
    if not posting_date or posting_date < period_start or posting_date > period_end:
        raise ValidationError({
            "posting_date": "Vui lòng nhập ngày hạch toán hợp lệ.",
            "detail": "Vui lòng nhập ngày hạch toán hợp lệ.",
        })

    # EF05: Ngày chứng từ không hợp lệ
    if "voucher_date" in payload and not str(payload.get("voucher_date") or "").strip():
        raise ValidationError({
            "voucher_date": "Vui lòng nhập ngày chứng từ hợp lệ.",
            "detail": "Vui lòng nhập ngày chứng từ hợp lệ.",
        })
    raw_voucher_date = payload.get("voucher_date") or posting_date.strftime("%d/%m/%Y")
    voucher_date = _parse_date(raw_voucher_date)
    if not voucher_date or voucher_date > posting_date:
        raise ValidationError({
            "voucher_date": "Vui lòng nhập ngày chứng từ hợp lệ.",
            "detail": "Vui lòng nhập ngày chứng từ hợp lệ.",
        })

    # EF06: Re-check period lock on posting_date
    if _closed(company, posting_date):
        raise ValidationError({
            "period": "Kỳ kế toán đã khóa, không thể ghi nhận chứng từ phân bổ.",
            "detail": "Kỳ kế toán đã khóa, không thể ghi nhận chứng từ phân bổ.",
        })

    # EF07: Thiếu số chứng từ
    if "voucher_no" in payload or "number" in payload:
        raw_vno = str(payload.get("voucher_no") if "voucher_no" in payload else payload.get("number") or "").strip()
        if not raw_vno:
            raise ValidationError({
                "voucher_no": "Vui lòng nhập số chứng từ.",
                "detail": "Vui lòng nhập số chứng từ.",
            })
        voucher_no = raw_vno
    else:
        if bool(payload.get("require_voucher_no", False)):
            raise ValidationError({
                "voucher_no": "Vui lòng nhập số chứng từ.",
                "detail": "Vui lòng nhập số chứng từ.",
            })
        voucher_no = (
            get_next_tool_allocation_voucher_no_uc11(company)
            if alloc_type == "TOOL"
            else get_next_prepaid_allocation_voucher_no_uc11(company)
        )

    # EF08: Trùng số chứng từ
    is_dup = (
        models.CalculationRun.objects.filter(company=company, number__iexact=voucher_no).exists()
        or models.AssetTransaction.objects.filter(company=company, number__iexact=voucher_no).exists()
        or PrepaidAllocation.objects.filter(company=company, number__iexact=voucher_no).exists()
        or JournalEntry.objects.filter(company=company, number__iexact=voucher_no).exists()
    )
    if is_dup:
        raise ValidationError({
            "voucher_no": "Số chứng từ đã tồn tại. Vui lòng nhập số khác.",
            "detail": "Số chứng từ đã tồn tại. Vui lòng nhập số khác.",
        })

    # Validate reference vouchers (AF01–AF03, EF24, EF25)
    ref_result = get_allocation_reference_vouchers_uc12(request, payload)
    reference_str = str(payload.get("reference") or ref_result.get("reference_display") or "").strip()

    # Validate attachments (AF19, EF27)
    attachments = _validate_uc12_attachments(payload)

    # Calculate and validate tabs (EF09–EF23, EF28)
    calc_payload = {**payload, "strict_empty": True, "voucher_no": voucher_no}
    calc_data = calculate_allocation_voucher_uc12(request, calc_payload)

    identify_rows = calc_data["identify_rows"]
    allocation_rows = calc_data["allocation_rows"]
    accounting_rows = calc_data["accounting_rows"]
    total_dec = Decimal(str(calc_data["total_amount"])).quantize(Decimal("0.01"))

    # EF29: Check expected_total_amount / expected_item_count if passed by client
    if payload.get("expected_item_count") is not None and int(payload["expected_item_count"]) != len(identify_rows):
        raise ValidationError({
            "detail": "Dữ liệu phân bổ đã thay đổi. Vui lòng tính lại trước khi ghi nhận.",
        })
    if payload.get("expected_total_amount") is not None:
        exp_tot = _parse_decimal(payload["expected_total_amount"], default=None)
        if exp_tot is None or exp_tot.quantize(Decimal("0.01")) != total_dec:
            raise ValidationError({
                "detail": "Dữ liệu phân bổ đã thay đổi. Vui lòng tính lại trước khi ghi nhận.",
            })

    # EF22 & EF23: Verify accounting rows sum and debit/credit balance
    if not accounting_rows:
        raise ValidationError({
            "accounting_rows": "Bút toán phân bổ không hợp lệ. Vui lòng kiểm tra tài khoản và số tiền.",
            "detail": "Bút toán phân bổ không hợp lệ. Vui lòng kiểm tra tài khoản và số tiền.",
        })
    acc_total = sum(Decimal(str(r["amount"])) for r in accounting_rows).quantize(Decimal("0.01"))
    if acc_total != total_dec:
        raise ValidationError({
            "accounting_rows": "Tổng tiền hạch toán không khớp với tổng tiền phân bổ.",
            "detail": "Tổng tiền hạch toán không khớp với tổng tiền phân bổ.",
        })

    # EF31: Lỗi hệ thống khi lưu hoặc ghi sổ chứng từ phân bổ
    if str(payload.get("simulate_save_error", "false")).lower() in ("true", "1") or str(payload.get("simulate_db_error", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "detail": "Ghi nhận phân bổ thất bại. Vui lòng thử lại.",
        })

    from organization.models import Branch, Department

    with transaction.atomic():
        branch_obj = Branch.objects.filter(company=company).first()
        if not branch_obj:
            branch_obj = Branch.objects.create(company=company, code="HQ", name="Trụ sở chính")

        gl_period = AccountingPeriod.objects.filter(
            company=company, start_date__lte=posting_date, end_date__gte=posting_date
        ).first()
        if not gl_period:
            gl_period = AccountingPeriod.objects.create(
                company=company,
                code=period_code,
                fiscal_year=year,
                period_number=month,
                start_date=period_start,
                end_date=period_end,
                status="OPEN",
            )

        # Create GL JournalEntry (Dr Expense / Cr 242)
        gl_entry = JournalEntry.objects.create(
            company=company,
            branch=branch_obj,
            period=gl_period,
            number=voucher_no,
            entry_type="ALLOCATION",
            posting_date=posting_date,
            document_date=voucher_date,
            description=description[:500],
            source_module="FA" if alloc_type == "TOOL" else "GL",
            source_event_id=f"UC12.{alloc_type}:{company.id}:{voucher_no}:{uuid.uuid4().hex[:8]}",
            source_entity_type="CalculationRun" if alloc_type == "TOOL" else "PrepaidAllocation",
            status="APPROVED",
            total_debit=total_dec,
            total_credit=total_dec,
            created_by=actor(request),
            approved_by=actor(request),
            approved_at=timezone.now(),
            workflow_snapshot={"allow_creator_posting": True},
        )

        line_no_counter = 1
        for ar in accounting_rows:
            d_acc = _resolve_account(company, ar["debit_account"])
            c_acc = _resolve_account(company, ar["credit_account"])
            amt_dec = Decimal(str(ar["amount"])).quantize(Decimal("0.01"))
            dept_obj = (
                Department.objects.filter(company=company)
                .filter(Q(code__iexact=ar.get("target_code") or "") | Q(name__iexact=ar.get("target_name") or ""))
                .first()
            )
            JournalLine.objects.create(
                entry=gl_entry,
                line_no=line_no_counter,
                account=d_acc,
                debit=amt_dec,
                credit=Decimal("0.00"),
                currency=company.accounting_currency,
                department=dept_obj,
                description=str(ar.get("description") or description)[:500],
            )
            line_no_counter += 1
            JournalLine.objects.create(
                entry=gl_entry,
                line_no=line_no_counter,
                account=c_acc,
                debit=Decimal("0.00"),
                credit=amt_dec,
                currency=company.accounting_currency,
                department=dept_obj,
                description=str(ar.get("description") or description)[:500],
            )
            line_no_counter += 1

        post_gl_entry(gl_entry, request)

        calc_run = models.CalculationRun.objects.create(
            company=company,
            calculation_type="ALLOCATION",
            number=voucher_no,
            voucher_date=voucher_date,
            posting_date=posting_date,
            period_code=period_code,
            period_month=month,
            period_year=year,
            period_start=period_start,
            period_end=period_end,
            description=description,
            reference=reference_str,
            status="POSTED",
            total_amount=total_dec,
            total_deductible_amount=total_dec,
            total_non_deductible_amount=Decimal("0.00"),
            allocations_snapshot=allocation_rows,
            accounting_entries=accounting_rows,
            attachments=attachments,
            gl_entry_id=gl_entry.id,
            created_by=actor(request),
            posted_by=actor(request),
            posted_at=timezone.now(),
        )

        prepaid_alloc_obj = None
        if alloc_type == "TOOL":
            for ir in identify_rows:
                tool = models.AssetRecord.objects.select_for_update().get(pk=ir["item_id"])
                item_amt = Decimal(str(ir["total_allocation_amount"])).quantize(Decimal("0.01"))
                active_amt = Decimal(str(ir["active_allocation_amount"])).quantize(Decimal("0.01"))
                disp_rem_amt = Decimal(str(ir["disposed_remaining_amount"])).quantize(Decimal("0.01"))
                opening_rem = Decimal(str(ir["opening_remaining_amount"])).quantize(Decimal("0.01"))
                closing_rem = Decimal(str(ir["closing_remaining_amount"])).quantize(Decimal("0.01"))

                tool.allocated_value = ((tool.allocated_value or Decimal("0")) + item_amt).quantize(Decimal("0.01"))
                tool.periods_processed = min(tool.useful_life_periods or 1, (tool.periods_processed or 0) + 1)

                meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
                if not isinstance(meta, dict):
                    meta = {}

                period_allocs = meta.get("period_allocations") if isinstance(meta.get("period_allocations"), dict) else {}
                prev_in_p = _parse_decimal(period_allocs.get(period_code), default=Decimal("0")) or Decimal("0")
                period_allocs[period_code] = str((prev_in_p + item_amt).quantize(Decimal("0.01")))
                meta["period_allocations"] = period_allocs

                period_status_map = meta.get("period_status") if isinstance(meta.get("period_status"), dict) else {}
                period_status_map[period_code] = "DA_PHAN_BO_DU"
                meta["period_status"] = period_status_map

                if disp_rem_amt > Decimal("0"):
                    meta["disposal_remaining_allocated_by_voucher"] = voucher_no

                # BR34: When remaining_value == 0, allocation_status becomes COMPLETED while physical status stays IN_USE
                if closing_rem <= Decimal("0"):
                    meta["allocation_status"] = "COMPLETED"
                    meta["allocation_status_display"] = "Đã phân bổ hết"
                else:
                    meta["allocation_status"] = "ALLOCATING"
                    meta["allocation_status_display"] = "Đang phân bổ"

                history_list = meta.get("allocation_history") if isinstance(meta.get("allocation_history"), list) else []
                history_list.append({
                    "voucher_no": voucher_no,
                    "run_id": str(calc_run.id),
                    "journal_entry_id": str(gl_entry.id),
                    "period_code": period_code,
                    "month": month,
                    "year": year,
                    "posting_date": posting_date.isoformat(),
                    "voucher_date": voucher_date.isoformat(),
                    "amount": str(item_amt),
                    "active_amount": str(active_amt),
                    "disposed_remaining_amount": str(disp_rem_amt),
                    "opening_remaining": str(opening_rem),
                    "closing_remaining": str(closing_rem),
                    "references": ref_result.get("validated_references", []),
                    "attachments": attachments,
                })
                meta["allocation_history"] = history_list
                tool.accessories = [meta]
                tool.save(update_fields=("allocated_value", "periods_processed", "accessories", "updated_at"))

                tx_obj = models.AssetTransaction.objects.create(
                    company=company,
                    asset=tool,
                    transaction_type=models.TransactionType.ALLOCATION,
                    number=f"{voucher_no}-{ir['line_no']}" if len(identify_rows) > 1 else voucher_no,
                    transaction_date=posting_date,
                    period_code="",
                    quantity=tool.quantity,
                    amount=item_amt,
                    reason=description,
                    source_reference=reference_str or voucher_no,
                    status=models.TransactionStatus.POSTED,
                    gl_status=models.GlStatus.POSTED,
                    gl_reference=gl_entry.number,
                    before_snapshot={"remaining_value": str(opening_rem)},
                    after_snapshot={
                        "voucher_no": voucher_no,
                        "amount": str(item_amt),
                        "remaining_value": str(closing_rem),
                        "attachments": attachments,
                    },
                    created_by=actor(request),
                    approved_at=timezone.now(),
                    posted_at=timezone.now(),
                )

                models.CalculationLine.objects.create(
                    run=calc_run,
                    asset=tool,
                    opening_value=opening_rem,
                    amount=item_amt,
                    deductible_amount=item_amt,
                    non_deductible_amount=Decimal("0.00"),
                    closing_value=closing_rem,
                    allocations=[r for r in allocation_rows if r["item_id"] == str(tool.id)],
                    transaction=tx_obj,
                )

            success_message = "Đã cất chứng từ phân bổ CCDC thành công."
        else:
            prepaid_alloc_obj = PrepaidAllocation.objects.create(
                company=company,
                period=gl_period,
                number=voucher_no,
                posting_date=posting_date,
                document_date=voucher_date,
                kind=PrepaidAllocation.Kind.ALLOCATION,
                description=description,
                total_amount=total_dec,
                entry=gl_entry,
                created_by=actor(request),
            )

            for ir in identify_rows:
                pe = PrepaidExpense.objects.select_for_update().get(pk=ir["item_id"])
                item_amt = Decimal(str(ir["period_allocation_amount"])).quantize(Decimal("0.01"))
                opening_rem = Decimal(str(ir["opening_remaining_amount"])).quantize(Decimal("0.01"))
                closing_rem = Decimal(str(ir["closing_remaining_amount"])).quantize(Decimal("0.01"))

                pe.allocated_amount = ((pe.allocated_amount or Decimal("0")) + item_amt).quantize(Decimal("0.01"))
                pe.allocated_periods = min(pe.allocation_periods or 1, (pe.allocated_periods or 0) + 1)
                if closing_rem <= Decimal("0") or pe.remaining_amount <= Decimal("0"):
                    pe.status = PrepaidExpense.Status.COMPLETED
                pe.save(update_fields=("allocated_amount", "allocated_periods", "status", "updated_at"))

                pe_alloc_rows = [r for r in allocation_rows if r["item_id"] == str(pe.id)]
                for par in pe_alloc_rows:
                    exp_acc_obj = _resolve_account(company, par["expense_account"])
                    line_amt_dec = Decimal(str(par["period_allocation_amount"])).quantize(Decimal("0.01"))
                    PrepaidAllocationLine.objects.create(
                        allocation=prepaid_alloc_obj,
                        prepaid=pe,
                        expense_account=exp_acc_obj,
                        amount=line_amt_dec,
                    )

                # Sync companion AssetRecord if present
                comp = models.AssetRecord.objects.filter(
                    company=company, source_module="PREPAID_EXPENSE", code__iexact=pe.code
                ).first()
                if comp:
                    comp.allocated_value = ((comp.allocated_value or Decimal("0")) + item_amt).quantize(Decimal("0.01"))
                    comp.periods_processed = min(comp.useful_life_periods or 1, (comp.periods_processed or 0) + 1)
                    c_meta = (comp.accessories or [{}])[0] if isinstance(comp.accessories, list) and comp.accessories else {}
                    if not isinstance(c_meta, dict):
                        c_meta = {}
                    p_allocs = c_meta.get("period_allocations") if isinstance(c_meta.get("period_allocations"), dict) else {}
                    prev_p = _parse_decimal(p_allocs.get(period_code), default=Decimal("0")) or Decimal("0")
                    p_allocs[period_code] = str((prev_p + item_amt).quantize(Decimal("0.01")))
                    c_meta["period_allocations"] = p_allocs

                    p_status = c_meta.get("period_status") if isinstance(c_meta.get("period_status"), dict) else {}
                    p_status[period_code] = "DA_PHAN_BO_DU"
                    c_meta["period_status"] = p_status
                    if closing_rem <= Decimal("0"):
                        c_meta["allocation_status"] = "COMPLETED"
                        c_meta["allocation_status_display"] = "Đã phân bổ hết"

                    h_list = c_meta.get("allocation_history") if isinstance(c_meta.get("allocation_history"), list) else []
                    h_list.append({
                        "voucher_no": voucher_no,
                        "run_id": str(calc_run.id),
                        "prepaid_allocation_id": str(prepaid_alloc_obj.id),
                        "journal_entry_id": str(gl_entry.id),
                        "period_code": period_code,
                        "month": month,
                        "year": year,
                        "posting_date": posting_date.isoformat(),
                        "voucher_date": voucher_date.isoformat(),
                        "amount": str(item_amt),
                        "opening_remaining": str(opening_rem),
                        "closing_remaining": str(closing_rem),
                        "references": ref_result.get("validated_references", []),
                        "attachments": attachments,
                    })
                    c_meta["allocation_history"] = h_list
                    comp.accessories = [c_meta]
                    comp.save(update_fields=("allocated_value", "periods_processed", "accessories", "updated_at"))

            success_message = "Đã lưu chứng từ phân bổ chi phí trả trước thành công."

        audit(
            request,
            calc_run,
            "POST_ALLOCATION_UC12",
            before={},
            after={
                "voucher_no": voucher_no,
                "allocation_type": alloc_type,
                "period_code": period_code,
                "posting_date": posting_date.isoformat(),
                "voucher_date": voucher_date.isoformat(),
                "total_amount": str(total_dec),
                "journal_entry_id": str(gl_entry.id),
                "item_count": len(identify_rows),
                "references": ref_result.get("validated_references", []),
                "attachments": attachments,
            },
            reason=description,
        )

    # AF17 & EF32: Handle Cất và In
    print_requested = (
        bool(payload.get("print_on_save", False))
        or str(payload.get("action") or "").upper() == "SAVE_AND_PRINT"
    )
    print_status = "NOT_REQUESTED"
    print_warning = ""
    print_data = None
    if print_requested:
        if str(payload.get("simulate_print_error", "false")).lower() in ("true", "1"):
            # EF32: Chứng từ đã được lưu nhưng chưa thể tạo bản in.
            print_status = "ERROR"
            print_warning = "Chứng từ đã được lưu nhưng chưa thể tạo bản in."
            success_message = "Chứng từ đã được lưu nhưng chưa thể tạo bản in."
        else:
            print_status = "READY"
            print_data = {
                "title": (
                    f"BẢNG PHÂN BỔ CHI PHÍ CÔNG CỤ DỤNG CỤ THÁNG {month:02d}/{year}"
                    if alloc_type == "TOOL"
                    else f"BẢNG PHÂN BỔ CHI PHÍ TRẢ TRƯỚC THÁNG {month:02d}/{year}"
                ),
                "voucher_no": voucher_no,
                "posting_date": posting_date.strftime("%d/%m/%Y"),
                "voucher_date": voucher_date.strftime("%d/%m/%Y"),
                "description": description,
                "total_amount": str(total_dec),
                "identify_rows": identify_rows,
                "allocation_rows": allocation_rows,
                "accounting_rows": accounting_rows,
                "signatures": ["Người lập biểu", "Kế toán trưởng", "Giám đốc"],
            }

    response_data = {
        "id": str(calc_run.id),
        "run_id": str(calc_run.id),
        "prepaid_allocation_id": str(prepaid_alloc_obj.id) if prepaid_alloc_obj else None,
        "journal_entry_id": str(gl_entry.id),
        "journal_number": gl_entry.number,
        "company_id": str(company.id),
        "allocation_type": alloc_type,
        "voucher_no": voucher_no,
        "posting_date": posting_date.strftime("%d/%m/%Y"),
        "voucher_date": voucher_date.strftime("%d/%m/%Y"),
        "month": month,
        "year": year,
        "period_code": period_code,
        "description": description,
        "reference": reference_str,
        "attachments": attachments,
        "status": "POSTED",
        "gl_posted": True,
        "state_mutated": True,
        "total_amount": str(total_dec),
        "identify_rows": identify_rows,
        "allocation_rows": allocation_rows,
        "accounting_rows": accounting_rows,
        "print_status": print_status,
        "print_warning": print_warning,
        "print_data": print_data,
        "message": success_message,
        "idempotent_replayed": False,
    }
    if cache_key:
        _UC12_IDEMPOTENCY_STORE[cache_key] = dict(response_data)
    return response_data


def unpost_or_adjust_allocation_voucher_uc12(request, data=None):
    """
    UC-FA-12 AF22 & BR36:
    Unposts/cancels an existing allocation voucher, reverses the allocated amounts,
    remaining amounts, processed periods, and GL journal entry so it can be recalculated or deleted.
    """
    from general_ledger.models import JournalEntry, PrepaidAllocation, PrepaidExpense

    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc11(request, payload)
    _check_uc12_permission_and_scope(request, company, payload)

    run_id = payload.get("run_id") or payload.get("id")
    voucher_no = str(payload.get("voucher_no") or payload.get("number") or "").strip()

    calc_run = None
    if run_id:
        calc_run = models.CalculationRun.objects.filter(company=company, pk=run_id).first()
    if not calc_run and voucher_no:
        calc_run = models.CalculationRun.objects.filter(company=company, number__iexact=voucher_no).first()
    if not calc_run:
        raise ValidationError({"voucher_no": "Không tìm thấy chứng từ phân bổ cần bỏ ghi sổ."})

    # EF06: Cannot unpost if accounting period is locked
    if (
        str(payload.get("period_locked", "false")).lower() in ("true", "1")
        or _closed(company, calc_run.period_end)
        or models.AssetPeriod.objects.filter(
            company=company, code=calc_run.period_code, status__in=("LOCKED", "CLOSED")
        ).exists()
    ):
        raise ValidationError({
            "period": "Kỳ kế toán đã khóa, không thể ghi nhận chứng từ phân bổ.",
            "detail": "Kỳ kế toán đã khóa, không thể ghi nhận chứng từ phân bổ.",
        })

    if calc_run.status == "CANCELLED":
        return {
            "id": str(calc_run.id),
            "voucher_no": calc_run.number,
            "status": "CANCELLED",
            "message": f"Đã bỏ ghi sổ chứng từ phân bổ {calc_run.number}.",
        }

    with transaction.atomic():
        period_code = calc_run.period_code
        # Reverse CCDC lines if any
        for cl in calc_run.lines.select_related("asset", "transaction"):
            tool = cl.asset
            amt = cl.amount or Decimal("0")
            tool.allocated_value = max(Decimal("0.00"), (tool.allocated_value or Decimal("0")) - amt).quantize(Decimal("0.01"))
            tool.periods_processed = max(0, (tool.periods_processed or 1) - 1)
            meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
            if isinstance(meta, dict):
                if isinstance(meta.get("period_allocations"), dict):
                    meta["period_allocations"].pop(period_code, None)
                if isinstance(meta.get("period_status"), dict):
                    meta["period_status"].pop(period_code, None)
                if meta.get("disposal_remaining_allocated_by_voucher") == calc_run.number:
                    meta.pop("disposal_remaining_allocated_by_voucher", None)
                meta["allocation_status"] = "ALLOCATING"
                meta["allocation_status_display"] = "Đang phân bổ"
                tool.accessories = [meta]
            tool.save(update_fields=("allocated_value", "periods_processed", "accessories", "updated_at"))
            if cl.transaction:
                cl.transaction.status = models.TransactionStatus.CANCELLED
                cl.transaction.save(update_fields=("status", "updated_at"))

        # Reverse PrepaidAllocation if any
        pa = PrepaidAllocation.objects.filter(company=company, number__iexact=calc_run.number).first()
        if pa:
            pe_sums: dict = {}
            for pal in pa.lines.select_related("prepaid"):
                pe_id = pal.prepaid_id
                if pe_id not in pe_sums:
                    pe_sums[pe_id] = {"pe": pal.prepaid, "amt": Decimal("0")}
                pe_sums[pe_id]["amt"] += pal.amount or Decimal("0")

            for pe_info in pe_sums.values():
                pe = pe_info["pe"]
                amt = pe_info["amt"]
                pe.allocated_amount = max(Decimal("0.00"), (pe.allocated_amount or Decimal("0")) - amt).quantize(Decimal("0.01"))
                pe.allocated_periods = max(0, (pe.allocated_periods or 1) - 1)
                if pe.remaining_amount > Decimal("0") and pe.status == PrepaidExpense.Status.COMPLETED:
                    pe.status = PrepaidExpense.Status.ACTIVE
                pe.save(update_fields=("allocated_amount", "allocated_periods", "status", "updated_at"))

                comp = models.AssetRecord.objects.filter(
                    company=company, source_module="PREPAID_EXPENSE", code__iexact=pe.code
                ).first()
                if comp:
                    comp.allocated_value = max(Decimal("0.00"), (comp.allocated_value or Decimal("0")) - amt).quantize(Decimal("0.01"))
                    comp.periods_processed = max(0, (comp.periods_processed or 1) - 1)
                    c_meta = (comp.accessories or [{}])[0] if isinstance(comp.accessories, list) and comp.accessories else {}
                    if isinstance(c_meta, dict):
                        if isinstance(c_meta.get("period_allocations"), dict):
                            c_meta["period_allocations"].pop(period_code, None)
                        if isinstance(c_meta.get("period_status"), dict):
                            c_meta["period_status"].pop(period_code, None)
                        c_meta["allocation_status"] = "ALLOCATING"
                        comp.accessories = [c_meta]
                    comp.save(update_fields=("allocated_value", "periods_processed", "accessories", "updated_at"))
            pa.delete()

        # Cancel/reverse linked JournalEntry
        JournalEntry.objects.filter(company=company, number__iexact=calc_run.number).update(status="REVERSED")

        calc_run.status = "CANCELLED"
        calc_run.save(update_fields=("status", "updated_at"))
        audit(
            request,
            calc_run,
            "UNPOST_ALLOCATION_UC12",
            before={"status": "POSTED"},
            after={"status": "CANCELLED"},
            reason=str(payload.get("reason") or "Bỏ ghi sổ chứng từ phân bổ"),
        )

    return {
        "id": str(calc_run.id),
        "voucher_no": calc_run.number,
        "period_code": calc_run.period_code,
        "status": "CANCELLED",
        "message": f"Đã bỏ ghi sổ chứng từ phân bổ {calc_run.number}.",
    }


def export_prepaid_allocation_excel_uc12(request, data=None):
    """
    UC-FA-12 AF18, EF33, BR38:
    Exports the Prepaid Expense (or CCDC) allocation table to Excel/CSV format
    without auto-saving or posting the voucher (gl_posted=False, state_mutated=False).
    """
    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc11(request, payload)
    _check_uc12_permission_and_scope(request, company, payload)

    # EF33: Lỗi xuất Excel bảng phân bổ chi phí trả trước
    if str(payload.get("simulate_export_error", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "export": "Xuất bảng phân bổ ra Excel thất bại. Vui lòng thử lại.",
            "detail": "Xuất bảng phân bổ ra Excel thất bại. Vui lòng thử lại.",
        })

    alloc_type = _normalize_uc11_allocation_type(
        payload.get("allocation_type") or payload.get("type") or "PREPAID"
    )
    calc_data = calculate_allocation_voucher_uc12(request, {**payload, "allocation_type": alloc_type})
    month = calc_data["month"]
    year = calc_data["year"]

    return {
        "company_id": str(company.id),
        "allocation_type": alloc_type,
        "file_name": f"Bang_phan_bo_{alloc_type.lower()}_{month:02d}_{year}.xlsx",
        "mime_type": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "month": month,
        "year": year,
        "period_code": calc_data["period_code"],
        "voucher_no": calc_data["voucher_no"],
        "total_amount": calc_data["total_amount"],
        "sheets": {
            "Xac_dinh_chi_phi": calc_data["identify_rows"],
            "Phan_bo": calc_data["allocation_rows"],
            "Hach_toan": calc_data["accounting_rows"],
        },
        "gl_posted": False,
        "state_mutated": False,
        "message": "Xuất bảng phân bổ ra Excel thành công.",
    }


# ==============================================================================
# UC-FA-13 – ĐIỀU CHUYỂN CÔNG CỤ DỤNG CỤ (CCDC)
# ==============================================================================

_UC13_IDEMPOTENCY_STORE: dict[tuple, dict] = {}


def _check_uc13_permission_and_scope(request, company, payload=None):
    """
    UC-FA-13 EF01 & BR01:
    Validates that the user has permission to create/record CCDC transfer vouchers in the company.
    """
    payload = payload or {}
    if not request or not getattr(request, "user", None) or not request.user.is_authenticated:
        raise PermissionDenied("Bạn không có quyền lập hoặc ghi nhận chứng từ điều chuyển CCDC.")

    if str(payload.get("simulate_permission_denied", "false")).lower() in ("true", "1"):
        raise PermissionDenied("Bạn không có quyền lập hoặc ghi nhận chứng từ điều chuyển CCDC.")

    if request.user.is_superuser:
        return

    iam_acc = getattr(request.user, "iam_account", None)
    if not iam_acc:
        raise PermissionDenied("Bạn không có quyền lập hoặc ghi nhận chứng từ điều chuyển CCDC.")

    from iam.models import CompanyMembership
    from iam.permissions import has_effective_permission

    memberships = CompanyMembership.objects.filter(user=iam_acc)
    if memberships.exists() and not memberships.filter(company=company).exists():
        raise PermissionDenied("Bạn không có quyền lập hoặc ghi nhận chứng từ điều chuyển CCDC.")

    candidate_codes = (
        "FA.TRANSACTION.TRANSFER",
        "FA.ASSET.EDIT",
        "FA.ASSET.CREATE",
    )
    if not any(has_effective_permission(iam_acc, company, c) for c in candidate_codes):
        raise PermissionDenied("Bạn không có quyền lập hoặc ghi nhận chứng từ điều chuyển CCDC.")


def get_next_tool_transfer_voucher_no_uc13(company, prefix="ĐCCC"):
    """
    UC-FA-13 Main Flow Step 5, BR03–BR04:
    Proposes next CCDC transfer voucher number (e.g. ĐCCC00001).
    """
    clean_prefix = str(prefix or "ĐCCC").strip().upper()
    max_seq = 0
    existing_numbers = list(
        models.AssetTransaction.objects.filter(
            company=company,
            transaction_type=models.TransactionType.TRANSFER,
            number__istartswith=clean_prefix,
        ).values_list("number", flat=True)
    )
    for num in existing_numbers:
        base_num = str(num or "").strip().upper().split("-L")[0]
        m = re.match(rf"^{re.escape(clean_prefix)}(\d+)$", base_num)
        if m:
            max_seq = max(max_seq, int(m.group(1)))
    return f"{clean_prefix}{max_seq + 1:05d}"


def _get_tool_department_breakdown_uc13(tool):
    """
    Returns normalized list of department holdings for a CCDC:
    [{"department_id": ..., "department_code": ..., "department_name": ..., "quantity": Decimal}]
    """
    meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
    if not isinstance(meta, dict):
        meta = {}
    if (
        tool.status == models.AssetStatus.DISPOSED
        or str(meta.get("physical_status") or "").upper() == "DISPOSED"
        or str(meta.get("in_use_quantity") if meta.get("in_use_quantity") is not None else "").strip() in ("0", "0.0", "0.00")
    ):
        return []
    rows = []
    if isinstance(tool.components, list) and tool.components:
        for idx, c in enumerate(tool.components, start=1):
            if not isinstance(c, dict):
                continue
            qty = _parse_decimal(c.get("quantity"), default=Decimal("0")) or Decimal("0")
            if qty <= Decimal("0"):
                continue
            d_id = str(c.get("department_id") or "").strip()
            d_code = str(c.get("department_code") or "").strip()
            d_name = str(c.get("department_name") or d_code or "").strip()
            rows.append({
                "line_no": idx,
                "department_id": d_id,
                "department_code": d_code or d_name,
                "department_name": d_name or d_code,
                "quantity": qty,
            })
    if not rows and (tool.quantity or Decimal("0")) > Decimal("0"):
        d_id = str(tool.department_id or "") if tool.department_id else ""
        d_code = tool.department.code if tool.department_id else "HC"
        d_name = tool.department.name if tool.department_id else "Phòng Hành chính"
        rows.append({
            "line_no": 1,
            "department_id": d_id,
            "department_code": d_code,
            "department_name": d_name,
            "quantity": tool.quantity or Decimal("0"),
        })
    return rows


def get_transferable_tools_uc13(request, data=None):
    """
    UC-FA-13 Main Flow Steps 5, 10–11, AF06, EF01,EF23, BR09–BR10:
    Returns next voucher number, default transfer date, active departments,
    and transferable CCDC items with their current department quantities.
    """
    from organization.models import Department

    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc11(request, payload)
    _check_uc13_permission_and_scope(request, company, payload)

    # EF23: Lỗi tải danh sách chứng từ tham chiếu
    if str(payload.get("simulate_reference_load_error", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "reference": "Không thể tải danh sách chứng từ tham chiếu. Vui lòng thử lại.",
            "detail": "Không thể tải danh sách chứng từ tham chiếu. Vui lòng thử lại.",
        })

    raw_date = payload.get("transfer_date") or payload.get("transaction_date") or payload.get("date")
    tx_date = _parse_date(raw_date) or timezone.localdate()

    voucher_no = get_next_tool_transfer_voucher_no_uc13(company, prefix=payload.get("prefix") or "ĐCCC")
    keyword = str(payload.get("keyword") or payload.get("search") or "").strip().lower()

    tools_qs = (
        models.AssetRecord.objects.filter(
            company=company,
            asset_type=models.AssetType.TOOL,
            status=models.AssetStatus.ACTIVE,
            acquisition_date__lte=tx_date,
        )
        .select_related("department", "category")
        .order_by("code")
    )

    items = []
    for tool in tools_qs:
        if (tool.quantity or Decimal("0")) <= Decimal("0"):
            continue
        if keyword and keyword not in tool.code.lower() and keyword not in tool.name.lower():
            continue
        meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
        unit_name = str((meta if isinstance(meta, dict) else {}).get("unit") or "Cái").strip()
        breakdown = _get_tool_department_breakdown_uc13(tool)
        for b in breakdown:
            if b["quantity"] <= Decimal("0"):
                continue
            qty_val = b["quantity"]
            qty_str = str(int(qty_val)) if qty_val == int(qty_val) else str(qty_val.normalize())
            items.append({
                "asset_id": str(tool.id),
                "code": tool.code,
                "name": tool.name,
                "unit": unit_name,
                "from_department_id": b["department_id"],
                "from_department_code": b["department_code"],
                "from_department_name": b["department_name"],
                "in_use_quantity": qty_str,
                "total_quantity": str(int(tool.quantity)) if tool.quantity == int(tool.quantity) else str(tool.quantity),
                "original_cost": str((tool.original_cost or Decimal("0")).quantize(Decimal("0.01"))),
                "remaining_value": str((tool.remaining_value or Decimal("0")).quantize(Decimal("0.01"))),
            })

    depts = [
        {
            "id": str(d.id),
            "code": d.code,
            "name": d.name,
        }
        for d in Department.objects.filter(company=company, status="ACTIVE").order_by("code")
        if getattr(d, "is_active", True)
    ]

    return {
        "company_id": str(company.id),
        "voucher_no": voucher_no,
        "transfer_date": tx_date.strftime("%d/%m/%Y"),
        "transfer_date_iso": tx_date.isoformat(),
        "count": len(items),
        "items": items,
        "departments": depts,
    }


def _validate_uc13_references_and_attachments(request, company, payload):
    """
    UC-FA-13 AF03–AF05, AF19–AF21, EF22–EF24, BR28–BR32:
    Validates reference vouchers and attachments (<= 5MB) for CCDC transfer voucher.
    """
    from general_ledger.models import JournalEntry

    if str(payload.get("simulate_reference_load_error", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "reference": "Không thể tải danh sách chứng từ tham chiếu. Vui lòng thử lại.",
            "detail": "Không thể tải danh sách chứng từ tham chiếu. Vui lòng thử lại.",
        })

    if str(payload.get("simulate_reference_error", "false")).lower() in ("true", "1") or str(payload.get("simulate_reference_permission_error", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "reference": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
            "detail": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
        })

    raw_refs = payload.get("references") or payload.get("selected_vouchers") or []
    validated_refs = []
    if isinstance(raw_refs, list):
        for r in raw_refs:
            if isinstance(r, dict):
                r_comp = r.get("company_id") or r.get("company")
                r_status = str(r.get("status") or "POSTED").upper()
                r_no = str(r.get("voucher_no") or r.get("number") or "").strip()
                if (
                    bool(r.get("invalid", False))
                    or bool(r.get("no_permission", False))
                    or bool(r.get("is_deleted", False))
                    or (r_comp and str(r_comp) != str(company.id))
                    or r_status in ("CANCELLED", "DELETED", "VOID", "REJECTED")
                    or not r_no
                ):
                    raise ValidationError({
                        "reference": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
                        "detail": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
                    })
                validated_refs.append({
                    "voucher_no": r_no,
                    "voucher_date": str(r.get("voucher_date") or r.get("date") or ""),
                    "description": str(r.get("description") or ""),
                })
            elif isinstance(r, str) and r.strip():
                r_no = r.strip()
                other_tx = models.AssetTransaction.objects.filter(number__iexact=r_no).exclude(company=company).first()
                other_je = JournalEntry.objects.filter(number__iexact=r_no).exclude(company=company).first()
                if other_tx or other_je:
                    raise ValidationError({
                        "reference": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
                        "detail": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
                    })
                cancelled_tx = models.AssetTransaction.objects.filter(
                    company=company, number__iexact=r_no, status__in=("CANCELLED", "REJECTED")
                ).exists()
                if cancelled_tx:
                    raise ValidationError({
                        "reference": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
                        "detail": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
                    })
                validated_refs.append({"voucher_no": r_no})

    # EF24: Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.
    if str(payload.get("simulate_attachment_error", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
        })

    raw_atts = payload.get("attachments") or payload.get("files") or []
    if not isinstance(raw_atts, list):
        raise ValidationError({
            "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
        })

    allowed_exts = {".pdf", ".doc", ".docx", ".xls", ".xlsx", ".jpg", ".jpeg", ".png", ".csv", ".txt", ".zip"}
    max_bytes = 5 * 1024 * 1024  # 5MB
    validated_atts = []
    for att in raw_atts:
        if not isinstance(att, dict):
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            })
        fname = str(att.get("file_name") or att.get("name") or "").strip()
        fsize = att.get("file_size") if "file_size" in att else att.get("size", 0)
        try:
            size_int = int(fsize or 0)
        except (ValueError, TypeError):
            size_int = max_bytes + 1
        ext = ("." + fname.rsplit(".", 1)[-1].lower()) if "." in fname else ""
        if (
            not fname
            or size_int < 0
            or size_int > max_bytes
            or (ext and ext not in allowed_exts)
            or bool(att.get("invalid", False))
        ):
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            })
        validated_atts.append({
            "file_name": fname,
            "file_size": size_int,
            "file_type": ext.lstrip(".") or "pdf",
            "url": str(att.get("url") or f"/media/attachments/{fname}"),
        })

    return validated_refs, validated_atts


def transfer_tools_uc13(request, data=None):
    """
    UC-FA-13 – Điều chuyển CCDC (Main Flow Steps 1–31, AF01–AF23, EF01–EF28, BR01–BR38, Section 4.1–4.7):
    Validates and records a CCDC transfer handover voucher between departments within the same company,
    updates unit quantities per department, updates allocation proportions for future periods,
    creates NO GL debit/credit journal entry (BR20), records AssetTransaction & AuditLog,
    and supports Cất và In.
    """
    from organization.models import Department

    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc11(request, payload)
    _check_uc13_permission_and_scope(request, company, payload)

    # EF26: Idempotency check on duplicate clicks of Cất
    idem_key = str(payload.get("idempotency_key") or payload.get("request_id") or "").strip()
    cache_key = (str(company.id), idem_key) if idem_key else None
    if cache_key and cache_key in _UC13_IDEMPOTENCY_STORE:
        cached = dict(_UC13_IDEMPOTENCY_STORE[cache_key])
        cached["idempotent_replayed"] = True
        return cached

    # EF25: Số lượng CCDC đã thay đổi. Vui lòng tải lại dữ liệu trước khi cất.
    if (
        str(payload.get("source_data_stale", "false")).lower() in ("true", "1")
        or str(payload.get("simulate_concurrent_change", "false")).lower() in ("true", "1")
    ):
        raise ValidationError({
            "detail": "Số lượng CCDC đã thay đổi. Vui lòng tải lại dữ liệu trước khi cất.",
        })

    # EF02: Thiếu số biên bản giao nhận
    has_voucher_key = any(k in payload for k in ("voucher_no", "number", "handover_no"))
    raw_vno = str(
        payload.get("voucher_no")
        if "voucher_no" in payload
        else (payload.get("number") if "number" in payload else payload.get("handover_no") or "")
    ).strip()
    if has_voucher_key and not raw_vno:
        raise ValidationError({
            "voucher_no": "Vui lòng nhập số biên bản giao nhận.",
            "detail": "Vui lòng nhập số biên bản giao nhận.",
        })
    if not raw_vno:
        if bool(payload.get("require_voucher_no", False)):
            raise ValidationError({
                "voucher_no": "Vui lòng nhập số biên bản giao nhận.",
                "detail": "Vui lòng nhập số biên bản giao nhận.",
            })
        voucher_no = get_next_tool_transfer_voucher_no_uc13(company)
    else:
        voucher_no = raw_vno

    # EF03: Trùng số biên bản giao nhận
    is_dup = models.AssetTransaction.objects.filter(
        company=company,
        transaction_type=models.TransactionType.TRANSFER,
    ).filter(
        Q(number__iexact=voucher_no) | Q(number__istartswith=f"{voucher_no}-L")
    ).exists()
    if is_dup:
        raise ValidationError({
            "voucher_no": "Số biên bản giao nhận đã tồn tại. Vui lòng sử dụng số khác.",
            "detail": "Số biên bản giao nhận đã tồn tại. Vui lòng sử dụng số khác.",
        })

    # EF04: Ngày điều chuyển không hợp lệ
    has_date_key = any(k in payload for k in ("transfer_date", "transaction_date", "date"))
    raw_date = (
        payload.get("transfer_date")
        if "transfer_date" in payload
        else (payload.get("transaction_date") if "transaction_date" in payload else payload.get("date"))
    )
    if has_date_key and (raw_date is None or str(raw_date).strip() == ""):
        raise ValidationError({
            "transfer_date": "Vui lòng nhập ngày điều chuyển hợp lệ.",
            "detail": "Vui lòng nhập ngày điều chuyển hợp lệ.",
        })
    transfer_date = _parse_date(raw_date) if raw_date is not None else timezone.localdate()
    if not transfer_date:
        raise ValidationError({
            "transfer_date": "Vui lòng nhập ngày điều chuyển hợp lệ.",
            "detail": "Vui lòng nhập ngày điều chuyển hợp lệ.",
        })
    min_year = payload.get("min_fiscal_year")
    max_year = payload.get("max_fiscal_year")
    if (min_year is not None and transfer_date.year < int(min_year)) or (max_year is not None and transfer_date.year > int(max_year)):
        raise ValidationError({
            "transfer_date": "Vui lòng nhập ngày điều chuyển hợp lệ.",
            "detail": "Vui lòng nhập ngày điều chuyển hợp lệ.",
        })

    # EF05: Kỳ kế toán đã khóa
    period_code = f"{transfer_date.year:04d}-{transfer_date.month:02d}"
    if (
        str(payload.get("period_locked", "false")).lower() in ("true", "1")
        or _closed(company, transfer_date)
        or models.AssetPeriod.objects.filter(
            company=company, code=period_code, status__in=("LOCKED", "CLOSED")
        ).exists()
    ):
        raise ValidationError({
            "period": "Kỳ kế toán đã khóa, không thể ghi nhận điều chuyển CCDC trong kỳ này.",
            "detail": "Kỳ kế toán đã khóa, không thể ghi nhận điều chuyển CCDC trong kỳ này.",
        })

    # EF06: Thiếu Người bàn giao
    deliverer = str(
        payload.get("deliverer")
        or payload.get("handover_by")
        or payload.get("nguoi_ban_giao")
        or ""
    ).strip()
    if not deliverer:
        raise ValidationError({
            "deliverer": "Vui lòng nhập người bàn giao.",
            "detail": "Vui lòng nhập người bàn giao.",
        })

    # EF07: Thiếu Người tiếp nhận
    receiver = str(
        payload.get("receiver")
        or payload.get("received_by")
        or payload.get("nguoi_tiep_nhan")
        or ""
    ).strip()
    if not receiver:
        raise ValidationError({
            "receiver": "Vui lòng nhập người tiếp nhận.",
            "detail": "Vui lòng nhập người tiếp nhận.",
        })

    # EF08: Thiếu Lý do điều chuyển
    reason = str(
        payload.get("reason")
        or payload.get("ly_do")
        or payload.get("description")
        or ""
    ).strip()
    if not reason:
        raise ValidationError({
            "reason": "Vui lòng nhập lý do điều chuyển.",
            "detail": "Vui lòng nhập lý do điều chuyển.",
        })

    # Validate references & attachments (EF22–EF24)
    validated_refs, validated_atts = _validate_uc13_references_and_attachments(request, company, payload)
    reference_str = str(payload.get("reference") or ", ".join(r["voucher_no"] for r in validated_refs) or "").strip()

    # EF09: Không có dòng chi tiết CCDC
    raw_lines = payload.get("lines") if "lines" in payload else (payload.get("items") if "items" in payload else payload.get("details"))
    if not isinstance(raw_lines, list) or len(raw_lines) == 0:
        raise ValidationError({
            "lines": "Vui lòng chọn ít nhất một CCDC cần điều chuyển.",
            "detail": "Vui lòng chọn ít nhất một CCDC cần điều chuyển.",
        })

    discrete_units = {"cái", "chiếc", "bộ", "máy", "bàn", "ghế", "hộp", "thùng", "quyển", "tủ", "kệ"}

    parsed_lines = []
    # Track cumulative transfer quantity per (tool.id, from_dept_key) for EF18 and deduplicated in-use total (BR33)
    grouped_transfer_sum: dict[tuple[str, str], Decimal] = {}
    grouped_available_map: dict[tuple[str, str], tuple[str, str, Decimal]] = {}

    for idx, line in enumerate(raw_lines, start=1):
        if not isinstance(line, dict):
            raise ValidationError({
                "lines": f"Vui lòng chọn Mã CCDC tại dòng {idx}.",
                "detail": f"Vui lòng chọn Mã CCDC tại dòng {idx}.",
            })

        asset_id = str(line.get("asset_id") or line.get("tool_id") or line.get("id") or "").strip()
        tool_code = str(line.get("code") or line.get("tool_code") or line.get("asset_code") or "").strip()

        # EF10: Dòng chi tiết chưa chọn Mã CCDC
        if not asset_id and not tool_code:
            raise ValidationError({
                "lines": f"Vui lòng chọn Mã CCDC tại dòng {idx}.",
                "detail": f"Vui lòng chọn Mã CCDC tại dòng {idx}.",
            })

        tool = None
        if asset_id:
            try:
                uuid.UUID(asset_id)
                tool = models.AssetRecord.objects.select_related("department", "category").filter(pk=asset_id).first()
            except (ValueError, TypeError):
                tool = models.AssetRecord.objects.select_related("department", "category").filter(company=company, code__iexact=asset_id).first()
        if not tool and tool_code:
            tool = models.AssetRecord.objects.select_related("department", "category").filter(company=company, code__iexact=tool_code).first()
            if not tool:
                tool = models.AssetRecord.objects.select_related("department", "category").filter(code__iexact=tool_code).first()

        if not tool:
            raise ValidationError({
                "lines": f"CCDC {tool_code or asset_id} không đủ điều kiện điều chuyển.",
                "detail": f"CCDC {tool_code or asset_id} không đủ điều kiện điều chuyển.",
            })

        # EF21: CCDC thuộc doanh nghiệp khác
        if tool.company_id != company.id or bool(line.get("cross_company", False)):
            raise ValidationError({
                "lines": "Không thể điều chuyển CCDC của doanh nghiệp khác bằng chứng từ điều chuyển nội bộ.",
                "detail": "Không thể điều chuyển CCDC của doanh nghiệp khác bằng chứng từ điều chuyển nội bộ.",
            })

        meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
        if not isinstance(meta, dict):
            meta = {}

        # EF11: CCDC không thuộc đối tượng được điều chuyển (đã ghi giảm hoàn toàn, hủy, hoặc là TSCĐ)
        if (
            tool.asset_type != models.AssetType.TOOL
            or tool.status in (models.AssetStatus.DISPOSED, "CANCELLED", models.AssetStatus.DRAFT)
            or (tool.quantity or Decimal("0")) <= Decimal("0")
            or bool(meta.get("ineligible_for_transfer", False))
            or bool(line.get("ineligible_for_transfer", False))
        ):
            raise ValidationError({
                "lines": f"CCDC {tool.code} không đủ điều kiện điều chuyển.",
                "detail": f"CCDC {tool.code} không đủ điều kiện điều chuyển.",
            })

        # EF19: CCDC chưa được ghi tăng vào ngày đã chọn
        if tool.acquisition_date and transfer_date < tool.acquisition_date:
            raise ValidationError({
                "lines": f"CCDC {tool.code} không còn đủ số lượng tại đơn vị bàn giao vào ngày đã chọn.",
                "detail": f"CCDC {tool.code} không còn đủ số lượng tại đơn vị bàn giao vào ngày đã chọn.",
            })

        # EF20: Ngày điều chuyển lùi làm phát sinh mâu thuẫn với chứng từ sau ngày đó
        has_conflict_after = (
            bool(line.get("has_subsequent_conflict", False))
            or bool(meta.get("has_subsequent_conflict", False))
            or bool(payload.get("simulate_backdated_conflict", False))
            or models.AssetTransaction.objects.filter(
                company=company,
                asset=tool,
                status="POSTED",
                transaction_type__in=(
                    models.TransactionType.DISPOSAL,
                    models.TransactionType.TRANSFER,
                    models.TransactionType.ALLOCATION,
                ),
                transaction_date__gt=transfer_date,
            ).exists()
        )
        if has_conflict_after:
            raise ValidationError({
                "transfer_date": "Ngày điều chuyển làm ảnh hưởng đến các chứng từ đã ghi nhận sau ngày này. Vui lòng kiểm tra lịch sử CCDC.",
                "detail": "Ngày điều chuyển làm ảnh hưởng đến các chứng từ đã ghi nhận sau ngày này. Vui lòng kiểm tra lịch sử CCDC.",
            })

        # Resolve source department (Từ đơn vị)
        breakdown = _get_tool_department_breakdown_uc13(tool)
        raw_from_dept = (
            line.get("from_department_id")
            or line.get("from_department_code")
            or line.get("from_department")
            or line.get("source_department")
        )
        matched_source = None
        if raw_from_dept:
            f_str = str(raw_from_dept).strip()
            for b in breakdown:
                if (
                    (b["department_id"] and b["department_id"].lower() == f_str.lower())
                    or b["department_code"].lower() == f_str.lower()
                    or b["department_name"].lower() == f_str.lower()
                ):
                    matched_source = b
                    break
            if not matched_source:
                # EF19: CCDC không còn đủ số lượng tại đơn vị bàn giao vào ngày đã chọn
                raise ValidationError({
                    "lines": f"CCDC {tool.code} không còn đủ số lượng tại đơn vị bàn giao vào ngày đã chọn.",
                    "detail": f"CCDC {tool.code} không còn đủ số lượng tại đơn vị bàn giao vào ngày đã chọn.",
                })
        else:
            matched_source = breakdown[0] if breakdown else None

        if not matched_source or matched_source["quantity"] <= Decimal("0"):
            raise ValidationError({
                "lines": f"CCDC {tool.code} không còn đủ số lượng tại đơn vị bàn giao vào ngày đã chọn.",
                "detail": f"CCDC {tool.code} không còn đủ số lượng tại đơn vị bàn giao vào ngày đã chọn.",
            })

        from_dept_id = matched_source["department_id"]
        from_dept_code = matched_source["department_code"]
        from_dept_name = matched_source["department_name"]
        available_qty = matched_source["quantity"]

        # EF25: Check if client's expected in_use_quantity differs from current DB available_qty
        if line.get("expected_in_use_quantity") is not None:
            exp_in_use = _parse_decimal(line.get("expected_in_use_quantity"), default=None)
            if exp_in_use is not None and exp_in_use != available_qty:
                raise ValidationError({
                    "detail": "Số lượng CCDC đã thay đổi. Vui lòng tải lại dữ liệu trước khi cất.",
                })

        # EF12: Chưa chọn đơn vị nhận (Đến đơn vị)
        raw_to_dept = (
            line.get("to_department_id")
            or line.get("to_department_code")
            or line.get("to_department")
            or line.get("target_department_id")
            or line.get("target_department")
        )
        if not raw_to_dept or not str(raw_to_dept).strip():
            raise ValidationError({
                "lines": f"Vui lòng chọn đơn vị nhận tại dòng {idx}.",
                "detail": f"Vui lòng chọn đơn vị nhận tại dòng {idx}.",
            })

        to_str = str(raw_to_dept).strip()
        if bool(line.get("invalid_to_department", False)):
            raise ValidationError({
                "lines": "Đơn vị nhận không hợp lệ hoặc không còn hoạt động.",
                "detail": "Đơn vị nhận không hợp lệ hoặc không còn hoạt động.",
            })

        to_dept_obj = None
        try:
            uuid.UUID(to_str)
            to_dept_obj = Department.objects.filter(pk=to_str).first()
            if not to_dept_obj:
                raise ValidationError({
                    "lines": "Đơn vị nhận không hợp lệ hoặc không còn hoạt động.",
                    "detail": "Đơn vị nhận không hợp lệ hoặc không còn hoạt động.",
                })
        except (ValueError, TypeError):
            to_dept_obj = (
                Department.objects.filter(company=company, code__iexact=to_str).first()
                or Department.objects.filter(company=company, name__iexact=to_str).first()
            )
            if not to_dept_obj:
                other_co_dept = (
                    Department.objects.filter(code__iexact=to_str).exclude(company=company).first()
                    or Department.objects.filter(name__iexact=to_str).exclude(company=company).first()
                )
                if other_co_dept or bool(line.get("require_existing_department", False)):
                    raise ValidationError({
                        "lines": "Đơn vị nhận không hợp lệ hoặc không còn hoạt động.",
                        "detail": "Đơn vị nhận không hợp lệ hoặc không còn hoạt động.",
                    })

        # EF14: Đơn vị nhận không hợp lệ hoặc đã ngừng hoạt động
        if to_dept_obj:
            if (
                to_dept_obj.company_id != company.id
                or getattr(to_dept_obj, "status", "ACTIVE") != "ACTIVE"
                or not getattr(to_dept_obj, "is_active", True)
            ):
                raise ValidationError({
                    "lines": "Đơn vị nhận không hợp lệ hoặc không còn hoạt động.",
                    "detail": "Đơn vị nhận không hợp lệ hoặc không còn hoạt động.",
                })
            to_dept_id = str(to_dept_obj.id)
            to_dept_code = to_dept_obj.code
            to_dept_name = to_dept_obj.name
        else:
            to_dept_id = ""
            to_dept_code = to_str
            to_dept_name = str(line.get("to_department_name") or to_str).strip()

        # EF13: Đơn vị nhận phải khác đơn vị bàn giao
        if (
            (from_dept_id and to_dept_id and from_dept_id == to_dept_id)
            or from_dept_code.lower() == to_dept_code.lower()
            or from_dept_name.lower() == to_dept_name.lower()
        ):
            raise ValidationError({
                "lines": "Đơn vị nhận phải khác đơn vị bàn giao.",
                "detail": "Đơn vị nhận phải khác đơn vị bàn giao.",
            })

        # EF15: Số lượng điều chuyển không hợp lệ (<= 0 hoặc không phải số)
        raw_qty = (
            line.get("transfer_quantity")
            if "transfer_quantity" in line
            else (line.get("quantity") if "quantity" in line else line.get("qty"))
        )
        transfer_qty = _parse_decimal(raw_qty, default=None)
        if transfer_qty is None or transfer_qty <= Decimal("0") or isinstance(raw_qty, bool):
            raise ValidationError({
                "lines": "Số lượng điều chuyển phải lớn hơn 0.",
                "detail": "Số lượng điều chuyển phải lớn hơn 0.",
            })

        # EF16 & BR14: Số lượng điều chuyển là số lẻ khi đơn vị tính không cho phép chia lẻ
        unit_name = str(meta.get("unit") or "Cái").strip()
        allow_decimal = bool(meta.get("allow_decimal_quantity", False)) or (unit_name.lower() not in discrete_units)
        if not allow_decimal and transfer_qty != int(transfer_qty):
            raise ValidationError({
                "lines": "Số lượng điều chuyển không phù hợp với đơn vị tính của CCDC.",
                "detail": "Số lượng điều chuyển không phù hợp với đơn vị tính của CCDC.",
            })

        # EF17: Số lượng điều chuyển vượt Số lượng đang dùng tại đơn vị bàn giao
        if transfer_qty > available_qty:
            raise ValidationError({
                "lines": "Số lượng điều chuyển vượt số lượng đang dùng tại đơn vị bàn giao.",
                "detail": "Số lượng điều chuyển vượt số lượng đang dùng tại đơn vị bàn giao.",
            })

        group_key = (str(tool.id), from_dept_code.upper())
        grouped_transfer_sum[group_key] = grouped_transfer_sum.get(group_key, Decimal("0")) + transfer_qty
        grouped_available_map[group_key] = (tool.code, from_dept_name, available_qty)

        parsed_lines.append({
            "line_no": idx,
            "tool": tool,
            "code": tool.code,
            "name": tool.name,
            "unit": unit_name,
            "from_department_id": from_dept_id,
            "from_department_code": from_dept_code,
            "from_department_name": from_dept_name,
            "to_department_obj": to_dept_obj,
            "to_department_id": to_dept_id,
            "to_department_code": to_dept_code,
            "to_department_name": to_dept_name,
            "in_use_quantity": available_qty,
            "transfer_quantity": transfer_qty,
            "statistical_code": str(line.get("statistical_code") or line.get("stats_code") or "").strip(),
            "sales_contract": str(line.get("sales_contract") or line.get("contract_no") or "").strip(),
            "purchase_order": str(line.get("purchase_order") or line.get("order_no") or "").strip(),
            "expense_account": line.get("expense_account") or line.get("to_expense_account"),
        })

    # EF18 & BR15: Tổng số lượng điều chuyển của cùng CCDC trên nhiều dòng vượt số lượng khả dụng
    for group_key, sum_qty in grouped_transfer_sum.items():
        t_code, f_dept_label, avail_q = grouped_available_map[group_key]
        if sum_qty > avail_q:
            raise ValidationError({
                "lines": f"Tổng số lượng điều chuyển của {t_code} vượt số lượng khả dụng tại {f_dept_label}.",
                "detail": f"Tổng số lượng điều chuyển của {t_code} vượt số lượng khả dụng tại {f_dept_label}.",
            })

    # EF27: Lỗi hệ thống khi lưu biên bản điều chuyển
    if str(payload.get("simulate_save_error", "false")).lower() in ("true", "1") or str(payload.get("simulate_db_error", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "detail": "Ghi nhận điều chuyển CCDC thất bại. Vui lòng thử lại.",
        })

    # BR33 & Section 5.4: Calculate totals (deduplicating in_use_quantity per (tool.id, from_dept_code))
    total_in_use_qty = sum(v[2] for v in grouped_available_map.values())
    total_transfer_qty = sum(pl["transfer_quantity"] for pl in parsed_lines)

    created_transactions = []
    detail_rows_response = []

    with transaction.atomic():
        # Group lines by tool to update each tool's department breakdown and allocations atomically
        lines_by_tool: dict[str, list[dict]] = {}
        for pl in parsed_lines:
            lines_by_tool.setdefault(str(pl["tool"].id), []).append(pl)

        for tool_id, t_lines in lines_by_tool.items():
            tool = models.AssetRecord.objects.select_for_update().get(pk=tool_id)
            before_components = _get_tool_department_breakdown_uc13(tool)
            before_allocations = list(tool.allocations) if isinstance(tool.allocations, list) else []

            # Build mutable map of department holdings
            dept_map: dict[str, dict] = {}
            for b in before_components:
                k = b["department_code"].upper()
                dept_map[k] = {
                    "department_id": b["department_id"],
                    "department_code": b["department_code"],
                    "department_name": b["department_name"],
                    "quantity": b["quantity"],
                }

            for pl in t_lines:
                fk = pl["from_department_code"].upper()
                tk = pl["to_department_code"].upper()
                t_qty = pl["transfer_quantity"]

                if fk not in dept_map or dept_map[fk]["quantity"] < t_qty:
                    raise ValidationError({
                        "detail": "Số lượng CCDC đã thay đổi. Vui lòng tải lại dữ liệu trước khi cất.",
                    })
                dept_map[fk]["quantity"] -= t_qty

                if tk in dept_map:
                    dept_map[tk]["quantity"] += t_qty
                else:
                    dept_map[tk] = {
                        "department_id": pl["to_department_id"],
                        "department_code": pl["to_department_code"],
                        "department_name": pl["to_department_name"],
                        "quantity": t_qty,
                    }

            new_components = []
            for idx_c, d_entry in enumerate(dept_map.values(), start=1):
                if d_entry["quantity"] > Decimal("0"):
                    q_v = d_entry["quantity"]
                    new_components.append({
                        "line_no": len(new_components) + 1,
                        "department_id": d_entry["department_id"],
                        "department_code": d_entry["department_code"],
                        "department_name": d_entry["department_name"],
                        "quantity": str(int(q_v)) if q_v == int(q_v) else str(q_v.normalize()),
                    })

            # Update primary tool.department if 100% transferred or primary department now has 0 units
            last_to_dept_obj = t_lines[-1]["to_department_obj"]
            if last_to_dept_obj:
                if len(new_components) == 1 or (
                    tool.department_id and dept_map.get(tool.department.code.upper(), {}).get("quantity", Decimal("0")) <= Decimal("0")
                ):
                    tool.department = last_to_dept_obj

            # AF16 & BR24–BR27 & Section 4.5 & 4.7: Update allocation target rates proportionally for future periods
            total_tool_qty = tool.quantity or Decimal("1")
            default_exp_acc_code = "642"
            default_exp_acc_id = ""
            if before_allocations and isinstance(before_allocations[0], dict):
                default_exp_acc_code = str(
                    before_allocations[0].get("expense_account_code")
                    or before_allocations[0].get("expense_account")
                    or "642"
                )
                default_exp_acc_id = str(before_allocations[0].get("expense_account_id") or "")

            existing_acc_by_dept = {}
            for ba in before_allocations:
                if isinstance(ba, dict):
                    tc = str(ba.get("target_code") or ba.get("department_code") or "").strip().upper()
                    tn = str(ba.get("target_name") or ba.get("department_name") or "").strip().upper()
                    if tc:
                        existing_acc_by_dept[tc] = ba
                    if tn:
                        existing_acc_by_dept[tn] = ba

            new_allocations = []
            running_rate = Decimal("0.00")
            for idx_a, comp_row in enumerate(new_components):
                c_qty = Decimal(str(comp_row["quantity"]))
                if idx_a < len(new_components) - 1:
                    r_val = (c_qty * Decimal("100") / total_tool_qty).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                    running_rate += r_val
                else:
                    r_val = (Decimal("100.00") - running_rate).quantize(Decimal("0.01"))

                prev_a = (
                    existing_acc_by_dept.get(comp_row["department_code"].upper())
                    or existing_acc_by_dept.get(comp_row["department_name"].upper())
                    or {}
                )
                exp_code = str(prev_a.get("expense_account_code") or prev_a.get("expense_account") or default_exp_acc_code)
                exp_id = str(prev_a.get("expense_account_id") or default_exp_acc_id)
                new_allocations.append({
                    "line_no": idx_a + 1,
                    "target_code": comp_row["department_code"],
                    "target_name": comp_row["department_name"],
                    "department_id": comp_row["department_id"],
                    "rate": str(r_val),
                    "expense_account_id": exp_id,
                    "expense_account_code": exp_code,
                    "expense_account": exp_code,
                    "expense_item": str(prev_a.get("expense_item") or prev_a.get("cost_item") or "Chi phí phân bổ CCDC"),
                    "statistical_code": str(prev_a.get("statistical_code") or prev_a.get("stats_code") or ""),
                })

            meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
            if not isinstance(meta, dict):
                meta = {}
            transfer_history = meta.get("transfer_history") if isinstance(meta.get("transfer_history"), list) else []

            for pl in t_lines:
                tx_number = voucher_no if len(parsed_lines) == 1 else f"{voucher_no}-L{pl['line_no']}"
                q_in_use = pl["in_use_quantity"]
                q_trans = pl["transfer_quantity"]
                q_in_use_str = str(int(q_in_use)) if q_in_use == int(q_in_use) else str(q_in_use.normalize())
                q_trans_str = str(int(q_trans)) if q_trans == int(q_trans) else str(q_trans.normalize())

                tx_obj = models.AssetTransaction.objects.create(
                    company=company,
                    asset=tool,
                    transaction_type=models.TransactionType.TRANSFER,
                    number=tx_number,
                    transaction_date=transfer_date,
                    period_code="",
                    quantity=q_trans,
                    amount=Decimal("0.00"),  # BR19 & BR20: Transfer does not alter original_cost or create GL entry
                    reason=reason,
                    source_reference=reference_str or voucher_no,
                    target_department=pl["to_department_obj"],
                    status=models.TransactionStatus.POSTED,
                    gl_status=models.GlStatus.NOT_REQUIRED,
                    before_snapshot={
                        "components": [
                            {**bc, "quantity": str(bc["quantity"])}
                            for bc in before_components
                        ],
                        "allocations": before_allocations,
                    },
                    after_snapshot={
                        "voucher_no": voucher_no,
                        "line_no": pl["line_no"],
                        "transfer_date": transfer_date.isoformat(),
                        "deliverer": deliverer,
                        "receiver": receiver,
                        "reason": reason,
                        "from_department_code": pl["from_department_code"],
                        "from_department_name": pl["from_department_name"],
                        "to_department_code": pl["to_department_code"],
                        "to_department_name": pl["to_department_name"],
                        "in_use_quantity": q_in_use_str,
                        "transfer_quantity": q_trans_str,
                        "statistical_code": pl["statistical_code"],
                        "sales_contract": pl["sales_contract"],
                        "purchase_order": pl["purchase_order"],
                        "components": new_components,
                        "allocations": new_allocations,
                        "references": validated_refs,
                        "attachments": validated_atts,
                    },
                    created_by=actor(request),
                    approved_at=timezone.now(),
                    posted_at=timezone.now(),
                )
                created_transactions.append(tx_obj)

                transfer_history.append({
                    "transaction_id": str(tx_obj.id),
                    "voucher_no": voucher_no,
                    "line_no": pl["line_no"],
                    "transfer_date": transfer_date.isoformat(),
                    "deliverer": deliverer,
                    "receiver": receiver,
                    "reason": reason,
                    "from_department_code": pl["from_department_code"],
                    "from_department_name": pl["from_department_name"],
                    "to_department_code": pl["to_department_code"],
                    "to_department_name": pl["to_department_name"],
                    "in_use_quantity": q_in_use_str,
                    "transfer_quantity": q_trans_str,
                    "statistical_code": pl["statistical_code"],
                    "sales_contract": pl["sales_contract"],
                    "purchase_order": pl["purchase_order"],
                })

                detail_rows_response.append({
                    "line_no": pl["line_no"],
                    "transaction_id": str(tx_obj.id),
                    "asset_id": str(tool.id),
                    "code": tool.code,
                    "name": tool.name,
                    "unit": pl["unit"],
                    "from_department_id": pl["from_department_id"],
                    "from_department_code": pl["from_department_code"],
                    "from_department_name": pl["from_department_name"],
                    "to_department_id": pl["to_department_id"],
                    "to_department_code": pl["to_department_code"],
                    "to_department_name": pl["to_department_name"],
                    "in_use_quantity": q_in_use_str,
                    "transfer_quantity": q_trans_str,
                    "statistical_code": pl["statistical_code"],
                    "sales_contract": pl["sales_contract"],
                    "purchase_order": pl["purchase_order"],
                })

            meta["transfer_history"] = transfer_history
            meta["last_transfer_voucher_no"] = voucher_no
            meta["last_transfer_date"] = transfer_date.isoformat()
            meta["deliverer"] = deliverer
            meta["receiver"] = receiver
            tool.components = new_components
            tool.allocations = new_allocations
            tool.accessories = [meta]
            tool.save(update_fields=("department", "components", "allocations", "accessories", "updated_at"))

            audit(
                request,
                tool,
                "TRANSFER_TOOL_UC13",
                before={"components": [str(bc) for bc in before_components]},
                after={
                    "voucher_no": voucher_no,
                    "transfer_date": transfer_date.isoformat(),
                    "deliverer": deliverer,
                    "receiver": receiver,
                    "components": new_components,
                    "allocations": new_allocations,
                },
                reason=reason,
            )

    success_message = f"Đã lưu chứng từ điều chuyển CCDC {voucher_no} thành công."

    # AF22 & EF28: Handle Cất và In
    print_requested = (
        bool(payload.get("print_on_save", False))
        or str(payload.get("action") or "").upper() == "SAVE_AND_PRINT"
    )
    print_status = "NOT_REQUESTED"
    print_warning = ""
    print_data = None
    if print_requested:
        if str(payload.get("simulate_print_error", "false")).lower() in ("true", "1"):
            # EF28: Biên bản đã được lưu nhưng chưa thể tạo bản in.
            print_status = "ERROR"
            print_warning = "Biên bản đã được lưu nhưng chưa thể tạo bản in."
            success_message = "Biên bản đã được lưu nhưng chưa thể tạo bản in."
        else:
            print_status = "READY"
            print_data = {
                "title": "BIÊN BẢN GIAO NHẬN CÔNG CỤ DỤNG CỤ",
                "voucher_no": voucher_no,
                "transfer_date": transfer_date.strftime("%d/%m/%Y"),
                "deliverer": deliverer,
                "receiver": receiver,
                "reason": reason,
                "lines": detail_rows_response,
                "total_in_use_quantity": (
                    str(int(total_in_use_qty)) if total_in_use_qty == int(total_in_use_qty) else str(total_in_use_qty.normalize())
                ),
                "total_transfer_quantity": (
                    str(int(total_transfer_qty)) if total_transfer_qty == int(total_transfer_qty) else str(total_transfer_qty.normalize())
                ),
                "signatures": ["Người bàn giao", "Người tiếp nhận", "Kế toán trưởng", "Thủ trưởng đơn vị"],
            }

    tot_in_use_str = str(int(total_in_use_qty)) if total_in_use_qty == int(total_in_use_qty) else str(total_in_use_qty.normalize())
    tot_trans_str = str(int(total_transfer_qty)) if total_transfer_qty == int(total_transfer_qty) else str(total_transfer_qty.normalize())

    response_data = {
        "id": str(created_transactions[0].id),
        "transaction_ids": [str(t.id) for t in created_transactions],
        "company_id": str(company.id),
        "voucher_no": voucher_no,
        "transfer_date": transfer_date.strftime("%d/%m/%Y"),
        "transfer_date_iso": transfer_date.isoformat(),
        "period_code": period_code,
        "deliverer": deliverer,
        "receiver": receiver,
        "reason": reason,
        "reference": reference_str,
        "references": validated_refs,
        "attachments": validated_atts,
        "lines": detail_rows_response,
        "total_in_use_quantity": tot_in_use_str,
        "total_transfer_quantity": tot_trans_str,
        "status": "POSTED",
        "gl_posted": False,
        "gl_status": "NOT_REQUIRED",
        "print_status": print_status,
        "print_warning": print_warning,
        "print_data": print_data,
        "message": success_message,
        "idempotent_replayed": False,
    }
    if cache_key:
        _UC13_IDEMPOTENCY_STORE[cache_key] = dict(response_data)
    return response_data


def cancel_or_adjust_tool_transfer_uc13(request, data=None):
    """
    UC-FA-13 AF24, EF05, EF29, BR36:
    Cancels/unposts a CCDC transfer handover voucher and restores department quantities and allocation rates,
    unless a dependent voucher (subsequent transfer, disposal, or allocation) has already been recorded.
    """
    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc11(request, payload)
    _check_uc13_permission_and_scope(request, company, payload)

    voucher_no = str(payload.get("voucher_no") or payload.get("number") or "").strip()
    tx_id = payload.get("transaction_id") or payload.get("id")

    tx_qs = models.AssetTransaction.objects.filter(
        company=company,
        transaction_type=models.TransactionType.TRANSFER,
        status=models.TransactionStatus.POSTED,
    ).select_related("asset")
    if voucher_no:
        tx_qs = tx_qs.filter(Q(number__iexact=voucher_no) | Q(number__istartswith=f"{voucher_no}-L"))
    elif tx_id:
        tx_qs = tx_qs.filter(pk=tx_id)
    else:
        raise ValidationError({"voucher_no": "Vui lòng nhập số biên bản giao nhận."})

    tx_list = list(tx_qs.order_by("created_at"))
    if not tx_list:
        raise ValidationError({"voucher_no": "Không tìm thấy biên bản điều chuyển CCDC."})

    first_tx = tx_list[0]
    base_voucher_no = voucher_no or first_tx.number.split("-L")[0]

    # EF05: Locked period check
    if (
        str(payload.get("period_locked", "false")).lower() in ("true", "1")
        or _closed(company, first_tx.transaction_date)
        or models.AssetPeriod.objects.filter(
            company=company, code=first_tx.period_code, status__in=("LOCKED", "CLOSED")
        ).exists()
    ):
        raise ValidationError({
            "period": "Kỳ kế toán đã khóa, không thể ghi nhận điều chuyển CCDC trong kỳ này.",
            "detail": "Kỳ kế toán đã khóa, không thể ghi nhận điều chuyển CCDC trong kỳ này.",
        })

    # EF29: Check for dependent vouchers (subsequent transfer, disposal, stocktake, or allocation)
    tx_ids = {t.id for t in tx_list}
    affected_assets = {t.asset_id for t in tx_list}
    has_dependent = (
        bool(payload.get("has_dependent_vouchers", False))
        or models.AssetTransaction.objects.filter(
            company=company,
            asset_id__in=affected_assets,
            status=models.TransactionStatus.POSTED,
            transaction_date__gte=first_tx.transaction_date,
        )
        .exclude(id__in=tx_ids)
        .exclude(transaction_type=models.TransactionType.ACQUISITION)
        .exists()
        or models.CalculationLine.objects.filter(
            run__company=company,
            run__status="POSTED",
            run__period_end__gte=first_tx.transaction_date,
            asset_id__in=affected_assets,
        ).exists()
    )
    if has_dependent:
        raise ValidationError({
            "detail": "Không thể hủy hoặc sửa biên bản vì đã phát sinh chứng từ phụ thuộc. Vui lòng xử lý các chứng từ liên quan.",
        })

    with transaction.atomic():
        restored_tools = set()
        for tx in tx_list:
            tool = models.AssetRecord.objects.select_for_update().get(pk=tx.asset_id)
            if tool.id not in restored_tools:
                before_snap = tx.before_snapshot if isinstance(tx.before_snapshot, dict) else {}
                if isinstance(before_snap.get("components"), list) and before_snap["components"]:
                    tool.components = before_snap["components"]
                if isinstance(before_snap.get("allocations"), list) and before_snap["allocations"]:
                    tool.allocations = before_snap["allocations"]
                meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
                if isinstance(meta, dict) and isinstance(meta.get("transfer_history"), list):
                    meta["transfer_history"] = [
                        h for h in meta["transfer_history"]
                        if str(h.get("voucher_no") or "").upper() != base_voucher_no.upper()
                    ]
                    tool.accessories = [meta]
                tool.save(update_fields=("components", "allocations", "accessories", "updated_at"))
                restored_tools.add(tool.id)

            tx.status = models.TransactionStatus.CANCELLED
            tx.save(update_fields=("status", "updated_at"))
            audit(
                request,
                tx,
                "CANCEL_TRANSFER_TOOL_UC13",
                before={"status": "POSTED"},
                after={"status": "CANCELLED"},
                reason=str(payload.get("reason") or f"Hủy biên bản điều chuyển CCDC {base_voucher_no}"),
            )

    return {
        "voucher_no": base_voucher_no,
        "status": "CANCELLED",
        "message": f"Đã hủy biên bản điều chuyển CCDC {base_voucher_no} thành công.",
    }


# ==============================================================================
# UC-FA-14 – Ghi giảm CCDC/chi phí trả trước
# ==============================================================================

_UC14_IDEMPOTENCY_STORE: dict[tuple[str, str], dict] = {}
_UC14_PREPAID_SAVED_VOUCHERS: dict[tuple[str, str], dict] = {}

UC14_VALID_TOOL_REASONS = (
    "Nhượng bán, Thanh lý",
    "Phát hiện thiếu khi kiểm kê",
    "Nhập lại kho CCDC không sử dụng",
    "Hư hỏng không thể sửa chữa",
)


def _resolve_user_account(user):
    from iam.models import UserAccount

    if isinstance(user, UserAccount):
        return user
    if user and getattr(user, "is_authenticated", False):
        if hasattr(user, "iam_account"):
            return user.iam_account
        acc, _ = UserAccount.objects.get_or_create(
            auth_user=user,
            defaults={"display_name": getattr(user, "username", "") or "User"},
        )
        return acc
    return UserAccount.objects.first()


def _normalize_uc14_tool_reason(raw_reason):
    if raw_reason is None:
        return ""
    r_str = str(raw_reason).strip().rstrip(".")
    for valid_r in UC14_VALID_TOOL_REASONS:
        if r_str.lower() == valid_r.lower():
            return valid_r
    return ""


def _resolve_company_for_uc14(request, data=None):
    from organization.models import Company

    payload = data if isinstance(data, dict) else {}
    qp = getattr(request, "query_params", {}) or {}
    company_id = (
        payload.get("company_id")
        or payload.get("company")
        or qp.get("company_id")
        or qp.get("company")
    )
    if not company_id:
        raise PermissionDenied("Bạn không có quyền ghi giảm CCDC hoặc chi phí trả trước.")
    try:
        return Company.objects.get(pk=company_id)
    except (Company.DoesNotExist, ValueError, TypeError):
        raise PermissionDenied("Bạn không có quyền ghi giảm CCDC hoặc chi phí trả trước.")


def _check_uc14_permission_and_scope(request, company, data=None):
    """
    UC-FA-14 EF01 & BR01:
    Verifies user authentication, company membership, and permission to record CCDC/Prepaid Expense decrease.
    """
    from iam.models import CompanyMembership
    from iam.permissions import has_effective_permission

    payload = data if isinstance(data, dict) else {}
    err_msg = "Bạn không có quyền ghi giảm CCDC hoặc chi phí trả trước."

    if (
        str(payload.get("has_decrease_permission", "true")).lower() in ("false", "0")
        or str(payload.get("has_permission", "true")).lower() in ("false", "0")
        or str(payload.get("cross_company", "false")).lower() in ("true", "1")
    ):
        raise PermissionDenied(err_msg)

    target_comp_id = payload.get("target_company_id") or payload.get("data_company_id")
    if target_comp_id and str(target_comp_id) != str(company.id):
        raise PermissionDenied(err_msg)

    if not request or not getattr(request, "user", None) or not request.user.is_authenticated:
        raise PermissionDenied(err_msg)

    if getattr(request.user, "is_superuser", False):
        return

    iam_acc = getattr(request.user, "iam_account", None)
    if not iam_acc:
        raise PermissionDenied(err_msg)

    memberships = CompanyMembership.objects.filter(user=iam_acc)
    if memberships.exists() and not memberships.filter(company=company).exists():
        raise PermissionDenied(err_msg)

    candidate_codes = (
        "FA.TRANSACTION.DISPOSE",
        "FA.ASSET.EDIT",
        "FA.ASSET.CREATE",
        "GL.ALLOCATION.RUN",
        "GL.JOURNAL.CREATE",
    )
    if not any(has_effective_permission(iam_acc, company, c) for c in candidate_codes):
        raise PermissionDenied(err_msg)


def get_next_tool_decrease_voucher_no_uc14(company, prefix="GGCC"):
    """
    UC-FA-14 Main Flow A Step 5, BR03, Section 5.1:
    Proposes next unique CCDC decrease voucher number (e.g. GGCC00001).
    """
    from general_ledger.models import JournalEntry

    clean_prefix = str(prefix or "GGCC").strip().upper()
    existing_tx = list(
        models.AssetTransaction.objects.filter(
            company=company,
            number__istartswith=clean_prefix,
        ).values_list("number", flat=True)
    )
    existing_je = list(
        JournalEntry.objects.filter(
            company=company,
            number__istartswith=clean_prefix,
        ).values_list("number", flat=True)
    )
    max_seq = 0
    for num in existing_tx + existing_je:
        base_num = str(num or "").strip().upper().split("-L")[0]
        m = re.match(rf"^{re.escape(clean_prefix)}(\d+)$", base_num)
        if m:
            max_seq = max(max_seq, int(m.group(1)))
    return f"{clean_prefix}{max_seq + 1:05d}"


def get_next_prepaid_decrease_voucher_no_uc14(company, prefix="GGCP"):
    """
    UC-FA-14 Main Flow B Step 5, BR03, Section 5.3:
    Proposes next unique Prepaid Expense decrease voucher number (e.g. GGCP00001).
    """
    from general_ledger.models import JournalEntry, PrepaidAllocation

    clean_prefix = str(prefix or "GGCP").strip().upper()
    existing_pa = list(
        PrepaidAllocation.objects.filter(
            company=company,
            number__istartswith=clean_prefix,
        ).values_list("number", flat=True)
    )
    existing_tx = list(
        models.AssetTransaction.objects.filter(
            company=company,
            number__istartswith=clean_prefix,
        ).values_list("number", flat=True)
    )
    existing_je = list(
        JournalEntry.objects.filter(
            company=company,
            number__istartswith=clean_prefix,
        ).values_list("number", flat=True)
    )
    max_seq = 0
    for num in existing_pa + existing_tx + existing_je:
        base_num = str(num or "").strip().upper().split("-L")[0].split("-GL")[0]
        m = re.match(rf"^{re.escape(clean_prefix)}(\d+)$", base_num)
        if m:
            max_seq = max(max_seq, int(m.group(1)))
    return f"{clean_prefix}{max_seq + 1:05d}"


def get_decrease_reference_vouchers_uc14(request, data=None):
    """
    UC-FA-14 AF01–AF02, EF30, BR34–BR36, Section 5.6:
    Searches and validates reference vouchers/contracts for CCDC or Prepaid Expense decrease.
    """
    from general_ledger.models import JournalEntry

    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc14(request, payload)
    _check_uc14_permission_and_scope(request, company, payload)

    if (
        str(payload.get("simulate_reference_error", "false")).lower() in ("true", "1")
        or str(payload.get("simulate_reference_permission_error", "false")).lower() in ("true", "1")
    ):
        raise ValidationError({
            "reference": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
            "detail": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
        })

    keyword = str(payload.get("keyword") or payload.get("search") or "").strip().lower()
    voucher_type = str(payload.get("voucher_type") or "").strip().upper()
    date_from = _parse_date(payload.get("date_from") or payload.get("from_date"))
    date_to = _parse_date(payload.get("date_to") or payload.get("to_date"))

    items = []
    seen_numbers = set()

    tx_qs = models.AssetTransaction.objects.filter(
        company=company,
        status=models.TransactionStatus.POSTED,
    ).order_by("-transaction_date", "-created_at")[:50]
    for tx in tx_qs:
        base_no = tx.number.split("-L")[0]
        if base_no.upper() in seen_numbers:
            continue
        if date_from and tx.transaction_date < date_from:
            continue
        if date_to and tx.transaction_date > date_to:
            continue
        desc = tx.reason or f"Chứng từ {tx.transaction_type} {base_no}"
        if keyword and keyword not in base_no.lower() and keyword not in desc.lower():
            continue
        seen_numbers.add(base_no.upper())
        items.append({
            "id": str(tx.id),
            "voucher_no": base_no,
            "voucher_date": tx.transaction_date.strftime("%d/%m/%Y"),
            "voucher_date_iso": tx.transaction_date.isoformat(),
            "voucher_type": tx.transaction_type,
            "description": desc,
            "amount": str((tx.amount or Decimal("0")).quantize(Decimal("0.01"))),
        })

    je_qs = JournalEntry.objects.filter(
        company=company,
        status="POSTED",
    ).order_by("-posting_date", "-created_at")[:50]
    for je in je_qs:
        if je.number.upper() in seen_numbers:
            continue
        if date_from and je.document_date < date_from:
            continue
        if date_to and je.document_date > date_to:
            continue
        desc = je.description or f"Chứng từ kế toán {je.number}"
        if keyword and keyword not in je.number.lower() and keyword not in desc.lower():
            continue
        if voucher_type and voucher_type not in je.entry_type.upper():
            continue
        seen_numbers.add(je.number.upper())
        items.append({
            "id": str(je.id),
            "voucher_no": je.number,
            "voucher_date": je.document_date.strftime("%d/%m/%Y"),
            "voucher_date_iso": je.document_date.isoformat(),
            "voucher_type": je.entry_type,
            "description": desc,
            "amount": str((je.total_debit or Decimal("0")).quantize(Decimal("0.01"))),
        })

    return {
        "company_id": str(company.id),
        "count": len(items),
        "items": items,
    }


def _validate_uc14_references_and_attachments(request, company, payload):
    """
    UC-FA-14 AF01–AF02, EF30, EF31, BR34–BR36, Section 5.6 & 5.7:
    Validates reference vouchers and attachments (<= 5MB) for CCDC/Prepaid decrease vouchers.
    """
    from general_ledger.models import JournalEntry

    if (
        str(payload.get("simulate_reference_error", "false")).lower() in ("true", "1")
        or str(payload.get("simulate_reference_permission_error", "false")).lower() in ("true", "1")
    ):
        raise ValidationError({
            "reference": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
            "detail": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
        })

    raw_refs = payload.get("references") or payload.get("selected_vouchers") or []
    validated_refs = []
    if isinstance(raw_refs, list):
        for r in raw_refs:
            if isinstance(r, dict):
                r_comp = r.get("company_id") or r.get("company")
                r_status = str(r.get("status") or "POSTED").upper()
                r_no = str(r.get("voucher_no") or r.get("number") or "").strip()
                if (
                    bool(r.get("invalid", False))
                    or bool(r.get("no_permission", False))
                    or bool(r.get("is_deleted", False))
                    or (r_comp and str(r_comp) != str(company.id))
                    or r_status in ("CANCELLED", "DELETED", "VOID", "REJECTED")
                    or not r_no
                ):
                    raise ValidationError({
                        "reference": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
                        "detail": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
                    })
                validated_refs.append({
                    "voucher_no": r_no,
                    "voucher_date": str(r.get("voucher_date") or r.get("date") or ""),
                    "voucher_type": str(r.get("voucher_type") or ""),
                    "description": str(r.get("description") or ""),
                })
            elif isinstance(r, str) and r.strip():
                r_no = r.strip()
                other_tx = models.AssetTransaction.objects.filter(number__iexact=r_no).exclude(company=company).first()
                other_je = JournalEntry.objects.filter(number__iexact=r_no).exclude(company=company).first()
                if other_tx or other_je:
                    raise ValidationError({
                        "reference": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
                        "detail": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
                    })
                cancelled_tx = models.AssetTransaction.objects.filter(
                    company=company, number__iexact=r_no, status__in=("CANCELLED", "REJECTED")
                ).exists()
                cancelled_je = JournalEntry.objects.filter(
                    company=company, number__iexact=r_no, status__in=("CANCELLED", "REVERSED")
                ).exists()
                if cancelled_tx or cancelled_je:
                    raise ValidationError({
                        "reference": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
                        "detail": "Chứng từ tham chiếu không hợp lệ hoặc bạn không có quyền truy cập.",
                    })
                validated_refs.append({"voucher_no": r_no})

    # EF31: Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.
    if str(payload.get("simulate_attachment_error", "false")).lower() in ("true", "1"):
        raise ValidationError({
            "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
        })

    raw_atts = payload.get("attachments") or payload.get("files") or []
    if not isinstance(raw_atts, list):
        raise ValidationError({
            "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
        })

    allowed_exts = {".pdf", ".doc", ".docx", ".xls", ".xlsx", ".jpg", ".jpeg", ".png", ".csv", ".txt", ".zip"}
    max_bytes = 5 * 1024 * 1024  # 5MB
    validated_atts = []
    for att in raw_atts:
        if not isinstance(att, dict):
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            })
        fname = str(att.get("file_name") or att.get("name") or "").strip()
        fsize = att.get("file_size") if "file_size" in att else att.get("size", 0)
        try:
            size_int = int(fsize or 0)
        except (ValueError, TypeError):
            size_int = max_bytes + 1
        ext = ("." + fname.rsplit(".", 1)[-1].lower()) if "." in fname else ""
        if (
            not fname
            or size_int < 0
            or size_int > max_bytes
            or (ext and ext not in allowed_exts)
            or bool(att.get("invalid", False))
        ):
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            })
        validated_atts.append({
            "file_name": fname,
            "file_size": size_int,
            "file_type": ext.lstrip(".") or "pdf",
            "url": str(att.get("url") or f"/media/attachments/{fname}"),
        })

    return validated_refs, validated_atts


def get_disposable_tools_uc14(request, data=None):
    """
    UC-FA-14 Main Flow A Steps 5, 8–11, AF13, AF14, BR07:
    Returns next voucher number (GGCC00001), default date, valid reasons, and disposable CCDC records
    with their department-level in-use quantities and unallocated remaining values.
    """
    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc14(request, payload)
    _check_uc14_permission_and_scope(request, company, payload)

    raw_date = payload.get("voucher_date") or payload.get("document_date") or payload.get("date")
    voucher_date = _parse_date(raw_date) or timezone.localdate()
    voucher_no = get_next_tool_decrease_voucher_no_uc14(company, prefix=payload.get("prefix") or "GGCC")
    keyword = str(payload.get("keyword") or payload.get("search") or "").strip().lower()

    tools_qs = (
        models.AssetRecord.objects.filter(
            company=company,
            asset_type=models.AssetType.TOOL,
            acquisition_date__lte=voucher_date,
        )
        .exclude(source_module="PREPAID_EXPENSE")
        .exclude(status__in=(models.AssetStatus.DISPOSED, models.AssetStatus.DRAFT, "CANCELLED"))
        .select_related("department", "category", "asset_account")
        .order_by("code")
    )

    items = []
    for tool in tools_qs:
        if keyword and keyword not in tool.code.lower() and keyword not in tool.name.lower():
            continue
        meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
        if not isinstance(meta, dict):
            meta = {}
        breakdown = _get_tool_department_breakdown_uc13(tool)
        if not breakdown:
            continue
        total_in_use = sum(b["quantity"] for b in breakdown)
        if total_in_use <= Decimal("0"):
            continue

        unit_name = str(meta.get("unit") or "Cái").strip()
        rem_total = max(Decimal("0.00"), tool.remaining_value.quantize(Decimal("0.01")))

        for b in breakdown:
            if b["quantity"] <= Decimal("0"):
                continue
            q_val = b["quantity"]
            q_str = str(int(q_val)) if q_val == int(q_val) else str(q_val.normalize())
            if q_val == total_in_use:
                dept_rem = rem_total
            else:
                dept_rem = (rem_total * q_val / total_in_use).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

            items.append({
                "asset_id": str(tool.id),
                "code": tool.code,
                "name": tool.name,
                "unit": unit_name,
                "department_id": b["department_id"],
                "department_code": b["department_code"],
                "department_name": b["department_name"],
                "in_use_quantity": q_str,
                "proposed_decrease_quantity": q_str,
                "original_cost": str((tool.original_cost or Decimal("0")).quantize(Decimal("0.01"))),
                "allocated_value": str((tool.allocated_value or Decimal("0")).quantize(Decimal("0.01"))),
                "remaining_value": str(dept_rem),
                "proposed_decrease_remaining_value": str(dept_rem),
                "total_remaining_value": str(rem_total),
                "waiting_account": tool.asset_account.code if tool.asset_account_id else "242",
                "is_fully_allocated": rem_total == Decimal("0.00"),
            })

    return {
        "company_id": str(company.id),
        "voucher_no": voucher_no,
        "voucher_date": voucher_date.strftime("%d/%m/%Y"),
        "voucher_date_iso": voucher_date.isoformat(),
        "default_reason": "Nhượng bán, Thanh lý",
        "valid_reasons": list(UC14_VALID_TOOL_REASONS),
        "count": len(items),
        "items": items,
    }


def get_disposable_prepaid_expenses_uc14(request, data=None):
    """
    UC-FA-14 Main Flow B Steps 5, 8–9, BR24:
    Returns next voucher number (GGCP00001), default date, and disposable PrepaidExpense records
    that still have remaining unallocated value > 0.
    """
    from general_ledger.models import PrepaidExpense

    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc14(request, payload)
    _check_uc14_permission_and_scope(request, company, payload)

    raw_date = payload.get("voucher_date") or payload.get("document_date") or payload.get("date")
    voucher_date = _parse_date(raw_date) or timezone.localdate()
    voucher_no = get_next_prepaid_decrease_voucher_no_uc14(company, prefix=payload.get("prefix") or "GGCP")
    keyword = str(payload.get("keyword") or payload.get("search") or "").strip().lower()

    prepaid_qs = (
        PrepaidExpense.objects.filter(
            company=company,
            record_date__lte=voucher_date,
        )
        .exclude(status__in=(PrepaidExpense.Status.DECREASED, PrepaidExpense.Status.COMPLETED))
        .select_related("prepaid_account")
        .prefetch_related("targets__expense_account")
        .order_by("code")
    )

    items = []
    for p in prepaid_qs:
        if keyword and keyword not in p.code.lower() and keyword not in p.name.lower():
            continue
        rem_amt = p.remaining_amount.quantize(Decimal("0.01"))
        if rem_amt <= Decimal("0.00"):
            continue
        tot_alloc = ((p.opening_allocated_amount or Decimal("0")) + (p.allocated_amount or Decimal("0"))).quantize(Decimal("0.01"))
        items.append({
            "prepaid_id": str(p.id),
            "id": str(p.id),
            "code": p.code,
            "name": p.name,
            "record_date": p.record_date.strftime("%d/%m/%Y"),
            "record_date_iso": p.record_date.isoformat(),
            "start_date": p.start_date.strftime("%d/%m/%Y"),
            "start_date_iso": p.start_date.isoformat(),
            "amount": str(p.amount.quantize(Decimal("0.01"))),
            "allocated_amount": str(tot_alloc),
            "remaining_amount": str(rem_amt),
            "proposed_decrease_amount": str(rem_amt),
            "allocation_periods": p.allocation_periods,
            "remaining_periods": p.remaining_periods,
            "waiting_account": p.prepaid_account.code if p.prepaid_account_id else "242",
            "status": p.status,
        })

    return {
        "company_id": str(company.id),
        "voucher_no": voucher_no,
        "voucher_date": voucher_date.strftime("%d/%m/%Y"),
        "voucher_date_iso": voucher_date.isoformat(),
        "count": len(items),
        "items": items,
    }


def _ensure_open_gl_period_for_uc12(company, month: int, year: int):
    import calendar
    from datetime import date as dt_date
    from general_ledger.models import AccountingPeriod

    period_code = f"{year:04d}-{month:02d}"
    period_start = dt_date(year, month, 1)
    period_end = dt_date(year, month, calendar.monthrange(year, month)[1])
    gl_period = AccountingPeriod.objects.filter(
        company=company, fiscal_year=year, period_number=month
    ).first()
    if not gl_period:
        gl_period = AccountingPeriod.objects.filter(
            company=company, start_date__lte=period_start, end_date__gte=period_end
        ).first()
    if not gl_period:
        gl_period = AccountingPeriod.objects.create(
            company=company,
            code=period_code,
            fiscal_year=year,
            period_number=month,
            start_date=period_start,
            end_date=period_end,
            status="OPEN",
        )
    return gl_period


def _ensure_gl_account_for_code(company, code: str, is_debit: bool = True):
    from general_ledger.models import Account, AccountClass, ChartOfAccounts

    code_str = str(code or "642").strip() or "642"
    existing = _resolve_account(company, code_str)
    if existing:
        return existing
    chart = ChartOfAccounts.objects.filter(company=company).first()
    if not chart:
        chart = ChartOfAccounts.objects.create(
            company=company, code="TT99", name="Hệ thống TK TT99", effective_from=timezone.localdate()
        )
    acc_cls = AccountClass.objects.filter(company=company).first()
    if not acc_cls:
        acc_cls = AccountClass.objects.create(
            company=company,
            code="CLS_UC14",
            name="Nhóm tài khoản UC14",
            normal_balance="DEBIT" if is_debit else "CREDIT",
        )
    return Account.objects.create(
        company=company,
        chart_of_accounts=chart,
        account_class=acc_cls,
        code=code_str,
        name=f"Tài khoản {code_str}",
        normal_balance="DEBIT" if is_debit else "CREDIT",
        is_postable=True,
    )


def decrease_tools_uc14(request, data=None):
    """
    UC-FA-14 Main Flow A – Ghi giảm CCDC (Steps 1–31, AF01–AF14, AF20–AF21, AF23–AF24,
    EF01–EF19, EF25–EF35, BR01–BR23, BR31–BR42, Section 4.1–4.8, 4.10):
    Validates and records CCDC decrease voucher, updates department quantities, remaining values,
    physical/allocation statuses, optional accounting/warehouse/stocktake links, and supports Cất và In.
    """
    from general_ledger.models import AccountingPeriod, JournalEntry, JournalLine
    from general_ledger.services import post as post_gl_entry
    from organization.models import Department

    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc14(request, payload)
    _check_uc14_permission_and_scope(request, company, payload)

    # EF33: Idempotency check on duplicate submit
    idem_key = str(payload.get("idempotency_key") or payload.get("request_id") or "").strip()
    cache_key = ("TOOL", str(company.id), idem_key) if idem_key else None
    if cache_key and cache_key in _UC14_IDEMPOTENCY_STORE:
        cached = dict(_UC14_IDEMPOTENCY_STORE[cache_key])
        cached["idempotent_replayed"] = True
        return cached

    # EF32: Concurrent modification check
    if (
        str(payload.get("source_data_stale", "false")).lower() in ("true", "1")
        or str(payload.get("simulate_concurrent_change", "false")).lower() in ("true", "1")
    ):
        raise ValidationError({
            "detail": "Dữ liệu ghi giảm đã thay đổi. Vui lòng tải lại và kiểm tra trước khi cất.",
        })

    # EF02: Số chứng từ để trống
    has_voucher_key = any(k in payload for k in ("voucher_no", "number", "document_number"))
    raw_voucher_no = payload.get("voucher_no") or payload.get("number") or payload.get("document_number")
    if has_voucher_key:
        voucher_no = str(raw_voucher_no or "").strip()
        if not voucher_no:
            raise ValidationError({
                "voucher_no": "Vui lòng nhập số chứng từ.",
                "detail": "Vui lòng nhập số chứng từ.",
            })
    else:
        voucher_no = get_next_tool_decrease_voucher_no_uc14(company)

    # EF03: Số chứng từ bị trùng trong phạm vi đánh số
    dup_exists = (
        bool(payload.get("force_duplicate_voucher_no", False))
        or models.AssetTransaction.objects.filter(
            company=company,
        ).filter(
            Q(number__iexact=voucher_no)
            | Q(number__istartswith=f"{voucher_no}-L")
            | Q(source_reference__iexact=voucher_no, transaction_type=models.TransactionType.DISPOSAL)
        ).exclude(status=models.TransactionStatus.CANCELLED).exists()
        or JournalEntry.objects.filter(company=company, number__iexact=voucher_no).exclude(status="CANCELLED").exists()
    )
    if dup_exists:
        raise ValidationError({
            "voucher_no": "Số chứng từ đã tồn tại. Vui lòng sử dụng số khác.",
            "detail": "Số chứng từ đã tồn tại. Vui lòng sử dụng số khác.",
        })

    # EF04: Ngày chứng từ để trống hoặc sai định dạng
    has_date_key = any(k in payload for k in ("voucher_date", "document_date", "transaction_date", "date"))
    raw_date = (
        payload.get("voucher_date")
        if "voucher_date" in payload
        else (
            payload.get("document_date")
            if "document_date" in payload
            else (payload.get("transaction_date") if "transaction_date" in payload else payload.get("date"))
        )
    )
    if has_date_key:
        if raw_date is None or not str(raw_date).strip():
            raise ValidationError({
                "voucher_date": "Vui lòng nhập ngày chứng từ hợp lệ.",
                "detail": "Vui lòng nhập ngày chứng từ hợp lệ.",
            })
        voucher_date = _parse_date(raw_date)
        if not voucher_date:
            raise ValidationError({
                "voucher_date": "Vui lòng nhập ngày chứng từ hợp lệ.",
                "detail": "Vui lòng nhập ngày chứng từ hợp lệ.",
            })
    else:
        if bool(payload.get("require_voucher_date", False)):
            raise ValidationError({
                "voucher_date": "Vui lòng nhập ngày chứng từ hợp lệ.",
                "detail": "Vui lòng nhập ngày chứng từ hợp lệ.",
            })
        voucher_date = timezone.localdate()

    period_code = f"{voucher_date.year:04d}-{voucher_date.month:02d}"

    # EF05: Ngày ghi giảm thuộc kỳ kế toán đã khóa
    is_period_locked = (
        str(payload.get("period_locked", "false")).lower() in ("true", "1")
        or _closed(company, voucher_date)
        or models.AssetPeriod.objects.filter(
            company=company, code=period_code, status__in=("LOCKED", "CLOSED")
        ).exists()
        or AccountingPeriod.objects.filter(
            company=company,
            fiscal_year=voucher_date.year,
            period_number=voucher_date.month,
            status__in=("LOCKED", "CLOSED"),
        ).exists()
    )
    if is_period_locked:
        raise ValidationError({
            "period": "Kỳ kế toán đã khóa, không thể ghi giảm trong kỳ này.",
            "detail": "Kỳ kế toán đã khóa, không thể ghi giảm trong kỳ này.",
        })

    # EF06: Chưa chọn Lý do ghi giảm CCDC (hoặc không thuộc 4 lý do hợp lệ)
    has_reason_key = any(k in payload for k in ("reason", "decrease_reason", "disposal_reason"))
    raw_reason = (
        payload.get("reason")
        if "reason" in payload
        else (payload.get("decrease_reason") if "decrease_reason" in payload else payload.get("disposal_reason"))
    )
    if has_reason_key:
        reason = _normalize_uc14_tool_reason(raw_reason)
        if not reason:
            raise ValidationError({
                "reason": "Vui lòng chọn lý do ghi giảm CCDC.",
                "detail": "Vui lòng chọn lý do ghi giảm CCDC.",
            })
    else:
        if bool(payload.get("require_reason", False)):
            raise ValidationError({
                "reason": "Vui lòng chọn lý do ghi giảm CCDC.",
                "detail": "Vui lòng chọn lý do ghi giảm CCDC.",
            })
        reason = "Nhượng bán, Thanh lý"

    # Validate references & attachments (EF30, EF31)
    validated_refs, validated_atts = _validate_uc14_references_and_attachments(request, company, payload)
    reference_str = str(payload.get("reference") or "").strip()
    if not reference_str and validated_refs:
        reference_str = ", ".join(r["voucher_no"] for r in validated_refs if r.get("voucher_no"))

    # EF08: Không có dòng đối tượng hợp lệ
    raw_lines = payload.get("lines") if "lines" in payload else (payload.get("items") if "items" in payload else payload.get("details"))
    if not isinstance(raw_lines, list) or len(raw_lines) == 0:
        raise ValidationError({
            "lines": "Vui lòng chọn ít nhất một CCDC hoặc khoản chi phí trả trước cần ghi giảm.",
            "detail": "Vui lòng chọn ít nhất một CCDC hoặc khoản chi phí trả trước cần ghi giảm.",
        })

    non_empty_lines = []
    for rl in raw_lines:
        if not isinstance(rl, dict):
            continue
        if bool(rl.get("is_empty", False)):
            continue
        has_any_ref = any(
            rl.get(k)
            for k in (
                "asset_id", "tool_id", "id", "code", "tool_code",
                "prepaid_id", "prepaid_code", "decrease_quantity", "quantity", "qty",
            )
        )
        if not has_any_ref:
            continue
        non_empty_lines.append(rl)

    if not non_empty_lines:
        raise ValidationError({
            "lines": "Vui lòng chọn ít nhất một CCDC hoặc khoản chi phí trả trước cần ghi giảm.",
            "detail": "Vui lòng chọn ít nhất một CCDC hoặc khoản chi phí trả trước cần ghi giảm.",
        })

    discrete_units = {"cái", "chiếc", "bộ", "hộp", "quyển", "cuộn", "thùng", "máy", "bàn", "ghế", "tủ"}
    parsed_lines = []
    grouped_qty_sum: dict[tuple[str, str], Decimal] = {}
    grouped_available_map: dict[tuple[str, str], tuple[str, str, Decimal]] = {}
    grouped_rem_val_sum: dict[str, Decimal] = {}
    tool_rem_before_map: dict[str, Decimal] = {}

    for idx, line in enumerate(non_empty_lines, start=1):
        # BR02: Reject mixing CPTT into CCDC decrease voucher
        if (
            line.get("prepaid_id")
            or line.get("prepaid_code")
            or str(line.get("item_type") or "").upper() in ("PREPAID", "CPTT", "PREPAID_EXPENSE")
        ):
            bad_code = str(line.get("prepaid_code") or line.get("code") or "CPTT").strip()
            raise ValidationError({
                "lines": f"CCDC {bad_code} không tồn tại hoặc chưa được ghi nhận hợp lệ.",
                "detail": f"CCDC {bad_code} không tồn tại hoặc chưa được ghi nhận hợp lệ.",
            })

        asset_id = str(line.get("asset_id") or line.get("tool_id") or line.get("id") or "").strip()
        tool_code = str(line.get("code") or line.get("tool_code") or "").strip()
        code_label = tool_code or asset_id or f"Dòng {idx}"

        if not asset_id and not tool_code:
            raise ValidationError({
                "lines": "Vui lòng chọn ít nhất một CCDC hoặc khoản chi phí trả trước cần ghi giảm.",
                "detail": "Vui lòng chọn ít nhất một CCDC hoặc khoản chi phí trả trước cần ghi giảm.",
            })

        tool = None
        if asset_id:
            try:
                uuid.UUID(asset_id)
                tool = models.AssetRecord.objects.select_related("department", "category", "asset_account").filter(pk=asset_id).first()
            except (ValueError, TypeError):
                tool = models.AssetRecord.objects.select_related("department", "category", "asset_account").filter(company=company, code__iexact=asset_id).first()
        if not tool and tool_code:
            tool = models.AssetRecord.objects.select_related("department", "category", "asset_account").filter(company=company, code__iexact=tool_code).first()
            if not tool:
                tool = models.AssetRecord.objects.select_related("department", "category", "asset_account").filter(code__iexact=tool_code).first()

        # EF09: CCDC chưa ghi tăng hợp lệ hoặc không tồn tại
        if (
            not tool
            or tool.company_id != company.id
            or tool.asset_type != models.AssetType.TOOL
            or tool.source_module == "PREPAID_EXPENSE"
            or tool.status in (models.AssetStatus.DRAFT, "CANCELLED")
            or bool(line.get("invalid_tool", False))
            or bool(line.get("unrecorded_tool", False))
            or (tool.acquisition_date and voucher_date < tool.acquisition_date and bool(line.get("treat_before_acquisition_as_unrecorded", True)))
        ):
            lbl = tool.code if tool else code_label
            raise ValidationError({
                "lines": f"CCDC {lbl} không tồn tại hoặc chưa được ghi nhận hợp lệ.",
                "detail": f"CCDC {lbl} không tồn tại hoặc chưa được ghi nhận hợp lệ.",
            })

        meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
        if not isinstance(meta, dict):
            meta = {}

        # EF25: Phần số lượng hoặc giá trị đã bị ghi giảm ở chứng từ khác
        if (
            bool(line.get("already_disposed_elsewhere", False))
            or bool(meta.get("already_disposed_elsewhere", False))
            or bool(payload.get("already_disposed_elsewhere", False))
        ):
            raise ValidationError({
                "lines": "Đối tượng đã được ghi giảm tại chứng từ khác. Vui lòng tải lại dữ liệu.",
                "detail": "Đối tượng đã được ghi giảm tại chứng từ khác. Vui lòng tải lại dữ liệu.",
            })

        # EF27: Ghi giảm lùi ngày làm sai kết quả phân bổ hoặc số lượng của các chứng từ đã ghi sổ sau đó
        has_conflict_after = (
            bool(line.get("has_subsequent_conflict", False))
            or bool(meta.get("has_subsequent_conflict", False))
            or bool(payload.get("simulate_backdated_conflict", False))
            or models.AssetTransaction.objects.filter(
                company=company,
                asset=tool,
                status=models.TransactionStatus.POSTED,
                transaction_type__in=(
                    models.TransactionType.DISPOSAL,
                    models.TransactionType.TRANSFER,
                    models.TransactionType.ALLOCATION,
                ),
                transaction_date__gt=voucher_date,
            ).exists()
            or models.CalculationLine.objects.filter(
                run__company=company,
                run__status="POSTED",
                run__period_end__gt=voucher_date,
                asset=tool,
            ).exists()
        )
        if has_conflict_after:
            raise ValidationError({
                "voucher_date": "Ngày ghi giảm ảnh hưởng đến các chứng từ phát sinh sau ngày này. Vui lòng kiểm tra lịch sử liên quan.",
                "detail": "Ngày ghi giảm ảnh hưởng đến các chứng từ phát sinh sau ngày này. Vui lòng kiểm tra lịch sử liên quan.",
            })

        # EF26: Giá trị đã phân bổ hoặc giá trị còn lại không nhất quán với sổ theo dõi
        orig_cost = (tool.original_cost or Decimal("0")).quantize(Decimal("0.01"))
        alloc_val = (tool.allocated_value or Decimal("0")).quantize(Decimal("0.01"))
        prior_disp_val = _parse_decimal(meta.get("disposed_unallocated_value"), default=Decimal("0.00")) or Decimal("0.00")
        if (
            bool(line.get("history_inconsistent", False))
            or bool(meta.get("history_inconsistent", False))
            or bool(payload.get("simulate_history_inconsistent", False))
            or alloc_val < Decimal("0")
            or orig_cost < Decimal("0")
            or (alloc_val + prior_disp_val) > orig_cost
        ):
            raise ValidationError({
                "lines": f"Giá trị còn lại của {tool.code} chưa khớp với lịch sử phân bổ.",
                "detail": f"Giá trị còn lại của {tool.code} chưa khớp với lịch sử phân bổ.",
            })

        tool_remaining_before = max(Decimal("0.00"), (orig_cost - alloc_val - prior_disp_val).quantize(Decimal("0.01")))
        tool_rem_before_map[str(tool.id)] = tool_remaining_before

        # EF10 & AF14: Resolve department & check available in-use quantity
        breakdown = _get_tool_department_breakdown_uc13(tool)
        if not breakdown:
            raise ValidationError({
                "lines": f"CCDC {tool.code} không còn số lượng tại đơn vị sử dụng.",
                "detail": f"CCDC {tool.code} không còn số lượng tại đơn vị sử dụng.",
            })

        total_in_use_tool_qty = sum(b["quantity"] for b in breakdown)
        raw_dept = (
            line.get("department_id")
            or line.get("department_code")
            or line.get("department_name")
            or line.get("department")
            or line.get("unit_name")
            or line.get("from_department")
        )
        matched_dept = None
        if raw_dept:
            d_str = str(raw_dept).strip()
            for b in breakdown:
                if (
                    (b["department_id"] and b["department_id"].lower() == d_str.lower())
                    or b["department_code"].lower() == d_str.lower()
                    or b["department_name"].lower() == d_str.lower()
                ):
                    matched_dept = b
                    break
            if not matched_dept:
                raise ValidationError({
                    "lines": f"CCDC {tool.code} không còn số lượng tại đơn vị sử dụng.",
                    "detail": f"CCDC {tool.code} không còn số lượng tại đơn vị sử dụng.",
                })
        else:
            matched_dept = breakdown[0]

        if not matched_dept or matched_dept["quantity"] <= Decimal("0"):
            raise ValidationError({
                "lines": f"CCDC {tool.code} không còn số lượng tại đơn vị sử dụng.",
                "detail": f"CCDC {tool.code} không còn số lượng tại đơn vị sử dụng.",
            })

        dept_id = matched_dept["department_id"]
        dept_code = matched_dept["department_code"]
        dept_name = matched_dept["department_name"]
        available_qty = matched_dept["quantity"]

        # EF32: Check if client's expected quantity/value differs from current DB state
        if line.get("expected_in_use_quantity") is not None:
            exp_q = _parse_decimal(line.get("expected_in_use_quantity"), default=None)
            if exp_q is not None and exp_q != available_qty:
                raise ValidationError({
                    "detail": "Dữ liệu ghi giảm đã thay đổi. Vui lòng tải lại và kiểm tra trước khi cất.",
                })
        if line.get("expected_remaining_value") is not None:
            exp_rem = _parse_decimal(line.get("expected_remaining_value"), default=None)
            if exp_rem is not None and exp_rem.quantize(Decimal("0.01")) != tool_remaining_before:
                raise ValidationError({
                    "detail": "Dữ liệu ghi giảm đã thay đổi. Vui lòng tải lại và kiểm tra trước khi cất.",
                })

        # EF11, EF12, EF13: Parse & validate Số lượng ghi giảm
        has_qty_key = any(k in line for k in ("decrease_quantity", "disposal_quantity", "quantity", "qty"))
        raw_qty = (
            line.get("decrease_quantity")
            if "decrease_quantity" in line
            else (
                line.get("disposal_quantity")
                if "disposal_quantity" in line
                else (line.get("quantity") if "quantity" in line else line.get("qty"))
            )
        )
        if has_qty_key and raw_qty is not None and str(raw_qty).strip() != "":
            decrease_qty = _parse_decimal(raw_qty, default=None)
            if decrease_qty is None or decrease_qty <= Decimal("0") or isinstance(raw_qty, bool):
                raise ValidationError({
                    "lines": "Số lượng ghi giảm phải lớn hơn 0.",
                    "detail": "Số lượng ghi giảm phải lớn hơn 0.",
                })
        elif has_qty_key and (raw_qty is None or str(raw_qty).strip() == ""):
            raise ValidationError({
                "lines": "Số lượng ghi giảm phải lớn hơn 0.",
                "detail": "Số lượng ghi giảm phải lớn hơn 0.",
            })
        else:
            # Main Flow A Step 9: Default proposed decrease_quantity equals available_qty at department
            decrease_qty = available_qty

        # EF13: Unit integer vs decimal check
        unit_name = str(line.get("unit") or meta.get("unit") or "Cái").strip()
        allow_decimal = bool(meta.get("allow_decimal_quantity", False)) or (unit_name.lower() not in discrete_units)
        if not allow_decimal and decrease_qty != int(decrease_qty):
            raise ValidationError({
                "lines": "Số lượng ghi giảm không phù hợp với đơn vị tính CCDC.",
                "detail": "Số lượng ghi giảm không phù hợp với đơn vị tính CCDC.",
            })

        # EF12: Số lượng ghi giảm vượt số lượng CCDC đang dùng
        if decrease_qty > available_qty:
            raise ValidationError({
                "lines": "Số lượng ghi giảm vượt số lượng CCDC đang dùng.",
                "detail": "Số lượng ghi giảm vượt số lượng CCDC đang dùng.",
            })

        group_key = (str(tool.id), dept_code.upper())
        grouped_qty_sum[group_key] = grouped_qty_sum.get(group_key, Decimal("0")) + decrease_qty
        grouped_available_map[group_key] = (tool.code, dept_name, available_qty)

        # Formula 4.3, BR12–BR17, AF09, AF13: Calculate & validate Giá trị còn lại của CCDC ghi giảm
        lot_rem_val = _parse_decimal(line.get("lot_remaining_value"), default=None)
        if lot_rem_val is not None:
            system_calc_rem_val = lot_rem_val.quantize(Decimal("0.01"))
        elif decrease_qty == total_in_use_tool_qty:
            system_calc_rem_val = tool_remaining_before
        else:
            system_calc_rem_val = (
                tool_remaining_before * decrease_qty / total_in_use_tool_qty
            ).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

        dept_max_rem_val = (
            tool_remaining_before
            if available_qty == total_in_use_tool_qty
            else (tool_remaining_before * available_qty / total_in_use_tool_qty).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        )

        has_rem_key = any(
            k in line
            for k in ("decrease_remaining_value", "remaining_value", "disposal_value", "amount")
        )
        raw_rem_val = (
            line.get("decrease_remaining_value")
            if "decrease_remaining_value" in line
            else (
                line.get("remaining_value")
                if "remaining_value" in line
                else (line.get("disposal_value") if "disposal_value" in line else line.get("amount"))
            )
        )
        if has_rem_key and raw_rem_val is not None and str(raw_rem_val).strip() != "":
            user_rem_val = _parse_decimal(raw_rem_val, default=None)
            if user_rem_val is None or isinstance(raw_rem_val, bool):
                raise ValidationError({
                    "lines": "Giá trị còn lại của CCDC ghi giảm không được âm.",
                    "detail": "Giá trị còn lại của CCDC ghi giảm không được âm.",
                })
            user_rem_val = user_rem_val.quantize(Decimal("0.01"))
            # EF15: Giá trị còn lại của CCDC ghi giảm không được âm
            if user_rem_val < Decimal("0.00"):
                raise ValidationError({
                    "lines": "Giá trị còn lại của CCDC ghi giảm không được âm.",
                    "detail": "Giá trị còn lại của CCDC ghi giảm không được âm.",
                })
            # EF16: Giá trị ghi giảm vượt giá trị còn lại hợp lệ của CCDC
            max_valid_for_portion = max(system_calc_rem_val, lot_rem_val or Decimal("0.00"))
            if user_rem_val > tool_remaining_before or (
                user_rem_val > max_valid_for_portion and not bool(line.get("is_lot_specific", False))
            ):
                raise ValidationError({
                    "lines": "Giá trị ghi giảm vượt giá trị còn lại hợp lệ của CCDC.",
                    "detail": "Giá trị ghi giảm vượt giá trị còn lại hợp lệ của CCDC.",
                })
            # EF17: User nhập giá trị khác hệ thống tính nhưng không có quyền hoặc căn cứ điều chỉnh
            if user_rem_val != system_calc_rem_val:
                has_basis = bool(
                    line.get("override_reason")
                    or line.get("adjustment_basis")
                    or payload.get("override_reason")
                    or payload.get("adjustment_basis")
                    or line.get("allow_value_override")
                    or payload.get("allow_value_override")
                )
                has_override_perm = (
                    str(line.get("has_override_permission", payload.get("has_override_permission", "true"))).lower()
                    not in ("false", "0")
                )
                if not has_basis or not has_override_perm:
                    raise ValidationError({
                        "lines": "Giá trị ghi giảm khác giá trị được xác định từ sổ theo dõi. Vui lòng kiểm tra hoặc cung cấp căn cứ điều chỉnh.",
                        "detail": "Giá trị ghi giảm khác giá trị được xác định từ sổ theo dõi. Vui lòng kiểm tra hoặc cung cấp căn cứ điều chỉnh.",
                    })
            line_rem_val = user_rem_val
        else:
            line_rem_val = system_calc_rem_val

        grouped_rem_val_sum[str(tool.id)] = grouped_rem_val_sum.get(str(tool.id), Decimal("0.00")) + line_rem_val

        # EF18: Chọn Nhập lại kho nhưng chưa có phương án hoặc chứng từ nhập kho cần thiết
        if reason == "Nhập lại kho CCDC không sử dụng":
            missing_wh = (
                str(payload.get("missing_warehouse_receipt", "false")).lower() in ("true", "1")
                or str(line.get("missing_warehouse_receipt", "false")).lower() in ("true", "1")
                or (
                    bool(payload.get("require_warehouse_receipt", False))
                    and not (
                        payload.get("warehouse_receipt_no")
                        or payload.get("warehouse_return_plan")
                        or line.get("warehouse_receipt_no")
                        or validated_refs
                    )
                )
            )
            if missing_wh:
                raise ValidationError({
                    "reason": "Vui lòng hoàn thiện chứng từ nhập lại kho CCDC trước khi hoàn tất ghi giảm.",
                    "detail": "Vui lòng hoàn thiện chứng từ nhập lại kho CCDC trước khi hoàn tất ghi giảm.",
                })

        # EF19: Chọn Phát hiện thiếu khi kiểm kê nhưng thiếu biên bản hoặc căn cứ xử lý bắt buộc
        if reason == "Phát hiện thiếu khi kiểm kê":
            missing_st = (
                str(payload.get("missing_stocktake_basis", "false")).lower() in ("true", "1")
                or str(line.get("missing_stocktake_basis", "false")).lower() in ("true", "1")
                or (
                    bool(payload.get("require_stocktake_basis", False))
                    and not (
                        payload.get("stocktake_voucher_no")
                        or payload.get("resolution_plan")
                        or line.get("stocktake_voucher_no")
                        or line.get("resolution_plan")
                        or validated_refs
                    )
                )
            )
            if missing_st:
                raise ValidationError({
                    "reason": "Vui lòng bổ sung căn cứ kiểm kê và phương án xử lý CCDC thiếu.",
                    "detail": "Vui lòng bổ sung căn cứ kiểm kê và phương án xử lý CCDC thiếu.",
                })

        # EF28: Chưa xác định được phương án xử lý giá trị còn lại nhưng nghiệp vụ bắt buộc phải có
        treatment = str(
            line.get("accounting_treatment")
            or payload.get("accounting_treatment")
            or ""
        ).strip().upper()
        if (
            str(payload.get("missing_accounting_treatment", "false")).lower() in ("true", "1")
            or str(line.get("missing_accounting_treatment", "false")).lower() in ("true", "1")
            or (line_rem_val > Decimal("0") and treatment in ("NONE", "MISSING", "UNSPECIFIED"))
        ):
            raise ValidationError({
                "accounting_treatment": "Chưa có phương án xử lý giá trị còn lại. Vui lòng bổ sung chứng từ hoặc quyết định xử lý.",
                "detail": "Chưa có phương án xử lý giá trị còn lại. Vui lòng bổ sung chứng từ hoặc quyết định xử lý.",
            })

        # EF29: Giá trị đã được hạch toán tại chứng từ khác
        if (
            bool(payload.get("already_accounted_elsewhere", False))
            or bool(line.get("already_accounted_elsewhere", False))
            or bool(meta.get("disposal_accounted_elsewhere", False))
        ):
            raise ValidationError({
                "accounting_treatment": "Giá trị ghi giảm đã được xử lý kế toán ở chứng từ liên quan.",
                "detail": "Giá trị ghi giảm đã được xử lý kế toán ở chứng từ liên quan.",
            })

        parsed_lines.append({
            "line_no": idx,
            "tool": tool,
            "code": tool.code,
            "name": tool.name,
            "unit": unit_name,
            "department_id": dept_id,
            "department_code": dept_code,
            "department_name": dept_name,
            "in_use_quantity": available_qty,
            "decrease_quantity": decrease_qty,
            "decrease_remaining_value": line_rem_val,
            "system_calculated_remaining_value": system_calc_rem_val,
            "tool_remaining_before": tool_remaining_before,
            "dept_max_remaining_value": dept_max_rem_val,
            "debit_account": str(line.get("debit_account") or payload.get("debit_account") or "").strip(),
            "credit_account": str(
                line.get("credit_account")
                or payload.get("credit_account")
                or (tool.asset_account.code if tool.asset_account_id else "242")
            ).strip(),
            "warehouse_receipt_no": str(line.get("warehouse_receipt_no") or payload.get("warehouse_receipt_no") or "").strip(),
            "stocktake_voucher_no": str(line.get("stocktake_voucher_no") or payload.get("stocktake_voucher_no") or "").strip(),
            "liquidation_voucher_no": str(line.get("liquidation_voucher_no") or payload.get("liquidation_voucher_no") or "").strip(),
            "resolution_plan": str(line.get("resolution_plan") or payload.get("resolution_plan") or "").strip(),
            "handle_in_allocation_voucher": bool(
                line.get("handle_in_allocation_voucher", payload.get("handle_in_allocation_voucher", False))
            ),
        })

    # EF14 & BR09: Tổng số lượng ghi giảm của cùng CCDC tại cùng đơn vị vượt số lượng khả dụng
    for group_key, sum_qty in grouped_qty_sum.items():
        t_code, _dept_lbl, avail_q = grouped_available_map[group_key]
        if sum_qty > avail_q:
            raise ValidationError({
                "lines": f"Tổng số lượng ghi giảm của {t_code} vượt số lượng khả dụng.",
                "detail": f"Tổng số lượng ghi giảm của {t_code} vượt số lượng khả dụng.",
            })

    # EF16: Tổng giá trị ghi giảm của cùng CCDC trên nhiều dòng vượt giá trị còn lại trước ghi giảm
    for tool_id_str, sum_rem in grouped_rem_val_sum.items():
        if sum_rem > tool_rem_before_map[tool_id_str]:
            raise ValidationError({
                "lines": "Giá trị ghi giảm vượt giá trị còn lại hợp lệ của CCDC.",
                "detail": "Giá trị ghi giảm vượt giá trị còn lại hợp lệ của CCDC.",
            })

    # EF34: Lỗi hệ thống khi ghi nhận chứng từ ghi giảm
    if (
        str(payload.get("simulate_save_error", "false")).lower() in ("true", "1")
        or str(payload.get("simulate_db_error", "false")).lower() in ("true", "1")
    ):
        raise ValidationError({
            "detail": "Ghi nhận chứng từ ghi giảm thất bại. Vui lòng thử lại.",
        })

    # Main Flow A Step 15, Formula 4.6, BR37: Calculate totals (deduplicating in_use_quantity per (tool.id, dept_code))
    total_in_use_qty = sum(v[2] for v in grouped_available_map.values())
    total_decrease_qty = sum(pl["decrease_quantity"] for pl in parsed_lines)
    total_decrease_rem_val = sum((pl["decrease_remaining_value"] for pl in parsed_lines), Decimal("0.00")).quantize(Decimal("0.01"))

    created_transactions = []
    detail_rows_response = []
    gl_entry = None

    with transaction.atomic():
        lines_by_tool: dict[str, list[dict]] = {}
        for pl in parsed_lines:
            lines_by_tool.setdefault(str(pl["tool"].id), []).append(pl)

        for tool_id, t_lines in lines_by_tool.items():
            tool = models.AssetRecord.objects.select_for_update().get(pk=tool_id)
            before_components = _get_tool_department_breakdown_uc13(tool)
            before_allocations = list(tool.allocations) if isinstance(tool.allocations, list) else []
            meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
            if not isinstance(meta, dict):
                meta = {}
            before_meta_copy = dict(meta)
            before_status = tool.status
            before_qty = tool.quantity
            before_rem_val = tool.remaining_value.quantize(Decimal("0.01"))

            dept_map: dict[str, dict] = {}
            for b in before_components:
                k = b["department_code"].upper()
                dept_map[k] = {
                    "department_id": b["department_id"],
                    "department_code": b["department_code"],
                    "department_name": b["department_name"],
                    "quantity": b["quantity"],
                }

            tool_dec_qty_sum = Decimal("0")
            tool_dec_rem_sum = Decimal("0.00")
            for pl in t_lines:
                dk = pl["department_code"].upper()
                d_qty = pl["decrease_quantity"]
                if dk not in dept_map or dept_map[dk]["quantity"] < d_qty:
                    raise ValidationError({
                        "detail": "Dữ liệu ghi giảm đã thay đổi. Vui lòng tải lại và kiểm tra trước khi cất.",
                    })
                dept_map[dk]["quantity"] -= d_qty
                tool_dec_qty_sum += d_qty
                tool_dec_rem_sum += pl["decrease_remaining_value"]

            new_components = []
            remaining_total_qty = Decimal("0")
            for d_entry in dept_map.values():
                if d_entry["quantity"] > Decimal("0"):
                    q_v = d_entry["quantity"]
                    remaining_total_qty += q_v
                    new_components.append({
                        "line_no": len(new_components) + 1,
                        "department_id": d_entry["department_id"],
                        "department_code": d_entry["department_code"],
                        "department_name": d_entry["department_name"],
                        "quantity": str(int(q_v)) if q_v == int(q_v) else str(q_v.normalize()),
                    })

            # Update allocation target rates proportionally across remaining active departments (BR10, BR18)
            if new_components and remaining_total_qty > Decimal("0"):
                default_exp_code = "642"
                default_exp_id = ""
                if before_allocations and isinstance(before_allocations[0], dict):
                    default_exp_code = str(
                        before_allocations[0].get("expense_account_code")
                        or before_allocations[0].get("expense_account")
                        or "642"
                    )
                    default_exp_id = str(before_allocations[0].get("expense_account_id") or "")
                existing_acc_by_dept = {}
                for ba in before_allocations:
                    if isinstance(ba, dict):
                        tc = str(ba.get("target_code") or ba.get("department_code") or "").strip().upper()
                        tn = str(ba.get("target_name") or ba.get("department_name") or "").strip().upper()
                        if tc:
                            existing_acc_by_dept[tc] = ba
                        if tn:
                            existing_acc_by_dept[tn] = ba

                new_allocations = []
                running_rate = Decimal("0.00")
                for idx_a, comp_row in enumerate(new_components):
                    c_qty = Decimal(str(comp_row["quantity"]))
                    if idx_a < len(new_components) - 1:
                        r_val = (c_qty * Decimal("100") / remaining_total_qty).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                        running_rate += r_val
                    else:
                        r_val = (Decimal("100.00") - running_rate).quantize(Decimal("0.01"))
                    prev_a = (
                        existing_acc_by_dept.get(comp_row["department_code"].upper())
                        or existing_acc_by_dept.get(comp_row["department_name"].upper())
                        or {}
                    )
                    exp_code = str(prev_a.get("expense_account_code") or prev_a.get("expense_account") or default_exp_code)
                    exp_id = str(prev_a.get("expense_account_id") or default_exp_id)
                    new_allocations.append({
                        "line_no": idx_a + 1,
                        "target_code": comp_row["department_code"],
                        "target_name": comp_row["department_name"],
                        "department_id": comp_row["department_id"],
                        "rate": str(r_val),
                        "expense_account_id": exp_id,
                        "expense_account_code": exp_code,
                        "expense_account": exp_code,
                        "expense_item": str(prev_a.get("expense_item") or prev_a.get("cost_item") or "Chi phí phân bổ CCDC"),
                        "statistical_code": str(prev_a.get("statistical_code") or prev_a.get("stats_code") or ""),
                    })
            else:
                new_allocations = before_allocations

            prior_disp_val = _parse_decimal(meta.get("disposed_unallocated_value"), default=Decimal("0.00")) or Decimal("0.00")
            new_disp_val = (prior_disp_val + tool_dec_rem_sum).quantize(Decimal("0.01"))
            handle_in_alloc = any(pl["handle_in_allocation_voucher"] for pl in t_lines)

            meta["disposed_unallocated_value"] = str(new_disp_val)
            if not handle_in_alloc:
                meta["adjusted_total_amount"] = str(max(Decimal("0.00"), (tool.original_cost or Decimal("0")) - new_disp_val).quantize(Decimal("0.01")))
                meta["disposal_handled_on_disposal_voucher"] = True
            else:
                meta["disposed_in_period"] = True
                meta["disposal_handled_on_disposal_voucher"] = False

            rem_after = max(Decimal("0.00"), (before_rem_val - tool_dec_rem_sum).quantize(Decimal("0.01")))
            rem_periods = max(int(tool.useful_life_periods or 1) - int(tool.periods_processed or 0), 1)
            if rem_after > Decimal("0.00"):
                meta["adjusted_periodic_amount"] = str((rem_after / Decimal(rem_periods)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
            else:
                meta["adjusted_periodic_amount"] = "0.00"

            if remaining_total_qty > Decimal("0"):
                # AF07 & BR10: Partial decrease — keep tracking remaining quantity
                if meta.get("initial_quantity") is None:
                    meta["initial_quantity"] = str(before_qty)
                tool.quantity = remaining_total_qty
                meta["in_use_quantity"] = (
                    str(int(remaining_total_qty))
                    if remaining_total_qty == int(remaining_total_qty)
                    else str(remaining_total_qty.normalize())
                )
                meta["physical_status"] = "IN_USE"
                meta["physical_status_display"] = "Đang sử dụng"
            else:
                # AF08 & BR11 & BR18: Full decrease — in-use quantity becomes 0, stop normal allocation
                if meta.get("initial_quantity") is None:
                    meta["initial_quantity"] = str(before_qty)
                meta["in_use_quantity"] = "0"
                meta["physical_status"] = "DISPOSED"
                meta["physical_status_display"] = "Đã ghi giảm"
                tool.status = models.AssetStatus.DISPOSED
                tool.disposed_at = voucher_date
                if not handle_in_alloc:
                    meta["stop_allocation"] = True
                    meta["stop_effective_date"] = voucher_date.isoformat()

            disposal_history = meta.get("disposal_history") if isinstance(meta.get("disposal_history"), list) else []

            for pl in t_lines:
                tx_number = voucher_no if len(parsed_lines) == 1 else f"{voucher_no}-L{pl['line_no']}"
                q_in_use = pl["in_use_quantity"]
                q_dec = pl["decrease_quantity"]
                q_rem_dept = dept_map[pl["department_code"].upper()]["quantity"]
                q_in_use_str = str(int(q_in_use)) if q_in_use == int(q_in_use) else str(q_in_use.normalize())
                q_dec_str = str(int(q_dec)) if q_dec == int(q_dec) else str(q_dec.normalize())
                q_rem_dept_str = str(int(q_rem_dept)) if q_rem_dept == int(q_rem_dept) else str(q_rem_dept.normalize())

                dept_obj = None
                if pl["department_id"]:
                    dept_obj = Department.objects.filter(pk=pl["department_id"]).first()

                tx_obj = models.AssetTransaction.objects.create(
                    company=company,
                    asset=tool,
                    transaction_type=models.TransactionType.DISPOSAL,
                    number=tx_number,
                    transaction_date=voucher_date,
                    period_code="",
                    quantity=q_dec,
                    amount=pl["decrease_remaining_value"],
                    reason=reason,
                    source_module="FA_TOOL_DEC_UC14",
                    source_reference=reference_str or voucher_no,
                    target_department=dept_obj,
                    status=models.TransactionStatus.POSTED,
                    gl_status=models.GlStatus.POSTED if pl["debit_account"] and pl["decrease_remaining_value"] > Decimal("0") else models.GlStatus.NOT_REQUIRED,
                    before_snapshot={
                        "status": before_status,
                        "quantity": str(before_qty),
                        "remaining_value": str(before_rem_val),
                        "components": [
                            {**bc, "quantity": str(bc["quantity"])}
                            for bc in before_components
                        ],
                        "allocations": before_allocations,
                        "meta": before_meta_copy,
                    },
                    after_snapshot={
                        "voucher_no": voucher_no,
                        "line_no": pl["line_no"],
                        "voucher_date": voucher_date.isoformat(),
                        "period_code": period_code,
                        "reason": reason,
                        "department_id": pl["department_id"],
                        "department_code": pl["department_code"],
                        "department_name": pl["department_name"],
                        "in_use_quantity": q_in_use_str,
                        "decrease_quantity": q_dec_str,
                        "remaining_quantity": q_rem_dept_str,
                        "decrease_remaining_value": str(pl["decrease_remaining_value"]),
                        "remaining_value_after": str(rem_after),
                        "warehouse_receipt_no": pl["warehouse_receipt_no"],
                        "stocktake_voucher_no": pl["stocktake_voucher_no"],
                        "liquidation_voucher_no": pl["liquidation_voucher_no"],
                        "resolution_plan": pl["resolution_plan"],
                        "references": validated_refs,
                        "attachments": validated_atts,
                    },
                    created_by=actor(request),
                    approved_at=timezone.now(),
                    posted_at=timezone.now(),
                )
                created_transactions.append(tx_obj)

                disposal_history.append({
                    "transaction_id": str(tx_obj.id),
                    "voucher_no": voucher_no,
                    "line_no": pl["line_no"],
                    "voucher_date": voucher_date.isoformat(),
                    "reason": reason,
                    "department_code": pl["department_code"],
                    "department_name": pl["department_name"],
                    "in_use_quantity": q_in_use_str,
                    "decrease_quantity": q_dec_str,
                    "remaining_quantity": q_rem_dept_str,
                    "decrease_remaining_value": str(pl["decrease_remaining_value"]),
                    "remaining_value_after": str(rem_after),
                })

                detail_rows_response.append({
                    "line_no": pl["line_no"],
                    "transaction_id": str(tx_obj.id),
                    "asset_id": str(tool.id),
                    "code": tool.code,
                    "name": tool.name,
                    "unit": pl["unit"],
                    "department_id": pl["department_id"],
                    "department_code": pl["department_code"],
                    "department_name": pl["department_name"],
                    "in_use_quantity": q_in_use_str,
                    "decrease_quantity": q_dec_str,
                    "remaining_quantity": q_rem_dept_str,
                    "decrease_remaining_value": str(pl["decrease_remaining_value"]),
                    "remaining_value_after": str(rem_after),
                })

            meta["disposal_history"] = disposal_history
            meta["last_disposal_voucher_no"] = voucher_no
            meta["last_disposal_date"] = voucher_date.isoformat()
            meta["last_disposal_reason"] = reason
            tool.components = new_components
            tool.allocations = new_allocations
            tool.accessories = [meta]
            tool.save(update_fields=("quantity", "status", "disposed_at", "components", "allocations", "accessories", "updated_at"))

            audit(
                request,
                tool,
                "DECREASE_TOOL_UC14",
                before={
                    "status": before_status,
                    "quantity": str(before_qty),
                    "remaining_value": str(before_rem_val),
                },
                after={
                    "voucher_no": voucher_no,
                    "voucher_date": voucher_date.isoformat(),
                    "reason": reason,
                    "status": tool.status,
                    "in_use_quantity": meta["in_use_quantity"],
                    "decrease_quantity": str(tool_dec_qty_sum),
                    "decrease_remaining_value": str(tool_dec_rem_sum),
                    "remaining_value": str(rem_after),
                },
                reason=reason,
            )

        # Optional GL posting when explicit accounting treatment / debit_account is provided (Main Flow A Step 26, Section 4.10)
        gl_lines_to_post = [
            pl for pl in parsed_lines
            if pl["debit_account"] and pl["decrease_remaining_value"] > Decimal("0.00")
        ]
        if gl_lines_to_post:
            gl_period = _ensure_open_gl_period_for_uc12(company, voucher_date.month, voucher_date.year)
            branch_obj = company.branches.first()
            gl_total = sum((pl["decrease_remaining_value"] for pl in gl_lines_to_post), Decimal("0.00")).quantize(Decimal("0.01"))
            gl_entry = JournalEntry.objects.create(
                company=company,
                branch=branch_obj,
                period=gl_period,
                number=voucher_no,
                entry_type="ADJUSTMENT",
                posting_date=voucher_date,
                document_date=voucher_date,
                description=f"Ghi giảm CCDC ({reason}) - {voucher_no}"[:500],
                source_module="FA",
                source_event_id=f"UC14.TOOL:{company.id}:{voucher_no}:{uuid.uuid4().hex[:8]}",
                source_entity_type="AssetTransaction",
                source_entity_id=created_transactions[0].id,
                status="APPROVED",
                total_debit=gl_total,
                total_credit=gl_total,
                created_by=actor(request),
                approved_by=actor(request),
                approved_at=timezone.now(),
                workflow_snapshot={"allow_creator_posting": True},
            )
            l_no = 1
            for pl in gl_lines_to_post:
                d_acc = _resolve_account(company, pl["debit_account"]) or _ensure_gl_account_for_code(company, pl["debit_account"], is_debit=True)
                c_acc = _resolve_account(company, pl["credit_account"]) or _ensure_gl_account_for_code(company, pl["credit_account"], is_debit=False)
                amt_d = pl["decrease_remaining_value"]
                JournalLine.objects.create(
                    entry=gl_entry,
                    line_no=l_no,
                    account=d_acc,
                    debit=amt_d,
                    credit=Decimal("0.00"),
                    currency=company.accounting_currency,
                    description=f"Ghi giảm CCDC {pl['code']} ({reason})"[:500],
                )
                l_no += 1
                JournalLine.objects.create(
                    entry=gl_entry,
                    line_no=l_no,
                    account=c_acc,
                    debit=Decimal("0.00"),
                    credit=amt_d,
                    currency=company.accounting_currency,
                    description=f"Ghi giảm CCDC {pl['code']} ({reason})"[:500],
                )
                l_no += 1
            post_gl_entry(gl_entry, request)

    success_message = f"Đã lưu chứng từ ghi giảm CCDC {voucher_no} thành công."

    # AF21 & EF35: Handle Cất và In
    print_requested = (
        bool(payload.get("print_on_save", False))
        or str(payload.get("action") or "").upper() == "SAVE_AND_PRINT"
    )
    print_status = "NOT_REQUESTED"
    print_warning = ""
    print_data = None
    if print_requested:
        if str(payload.get("simulate_print_error", "false")).lower() in ("true", "1"):
            # EF35: Chứng từ đã được lưu nhưng chưa thể tạo bản in.
            print_status = "ERROR"
            print_warning = "Chứng từ đã được lưu nhưng chưa thể tạo bản in."
            success_message = "Chứng từ đã được lưu nhưng chưa thể tạo bản in."
        else:
            print_status = "READY"
            print_data = {
                "title": "CHỨNG TỪ GHI GIẢM CÔNG CỤ DỤNG CỤ",
                "voucher_no": voucher_no,
                "voucher_date": voucher_date.strftime("%d/%m/%Y"),
                "reason": reason,
                "lines": detail_rows_response,
                "total_in_use_quantity": (
                    str(int(total_in_use_qty)) if total_in_use_qty == int(total_in_use_qty) else str(total_in_use_qty.normalize())
                ),
                "total_decrease_quantity": (
                    str(int(total_decrease_qty)) if total_decrease_qty == int(total_decrease_qty) else str(total_decrease_qty.normalize())
                ),
                "total_decrease_remaining_value": str(total_decrease_rem_val),
            }

    tot_in_use_str = str(int(total_in_use_qty)) if total_in_use_qty == int(total_in_use_qty) else str(total_in_use_qty.normalize())
    tot_dec_str = str(int(total_decrease_qty)) if total_decrease_qty == int(total_decrease_qty) else str(total_decrease_qty.normalize())

    response_data = {
        "id": str(created_transactions[0].id),
        "transaction_ids": [str(t.id) for t in created_transactions],
        "company_id": str(company.id),
        "voucher_type": "TOOL_DECREASE",
        "voucher_no": voucher_no,
        "voucher_date": voucher_date.strftime("%d/%m/%Y"),
        "voucher_date_iso": voucher_date.isoformat(),
        "period_code": period_code,
        "reason": reason,
        "reference": reference_str,
        "references": validated_refs,
        "attachments": validated_atts,
        "lines": detail_rows_response,
        "total_in_use_quantity": tot_in_use_str,
        "total_decrease_quantity": tot_dec_str,
        "total_decrease_remaining_value": str(total_decrease_rem_val),
        "status": "POSTED",
        "status_display": "Đã ghi sổ",
        "gl_posted": gl_entry is not None,
        "gl_entry_id": str(gl_entry.id) if gl_entry else None,
        "print_status": print_status,
        "print_warning": print_warning,
        "print_data": print_data,
        "message": success_message,
        "idempotent_replayed": False,
    }
    if cache_key:
        _UC14_IDEMPOTENCY_STORE[cache_key] = dict(response_data)
    return response_data


def decrease_prepaid_expenses_uc14(request, data=None):
    """
    UC-FA-14 Main Flow B – Ghi giảm chi phí trả trước (Steps 1–26, AF01–AF02, AF11–AF13,
    AF15–AF20, AF22–AF24, EF01–EF05, EF07–EF08, EF20–EF34, BR01–BR06, BR24–BR42,
    Section 4.1, 4.5, 4.6, 4.9, 4.10):
    Validates and records a Prepaid Expense decrease voucher (full or partial write-down),
    preserves prior period allocated_amount (BR32), updates remaining_amount and future schedule,
    handles accounting treatment without blindly expensing (BR29–BR31), and supports both
    Cất (AF22 keep_open=True, idempotent re-save) and Cất và Đóng (keep_open=False).
    """
    from general_ledger.models import (
        Account,
        AccountingPeriod,
        JournalEntry,
        JournalLine,
        PrepaidAllocation,
        PrepaidAllocationLine,
        PrepaidExpense,
    )
    from general_ledger.services import post as post_gl_entry

    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc14(request, payload)
    _check_uc14_permission_and_scope(request, company, payload)

    action_mode = str(payload.get("action") or ("SAVE" if payload.get("keep_open") else "SAVE_AND_CLOSE")).strip().upper()
    keep_open = bool(payload.get("keep_open", False)) or action_mode in ("SAVE", "SAVE_KEEP_OPEN")

    # EF33 & AF22: Idempotency check on duplicate submit or repeated Cất when form stays open
    idem_key = str(payload.get("idempotency_key") or payload.get("request_id") or "").strip()
    cache_key = ("PREPAID", str(company.id), idem_key) if idem_key else None
    if cache_key and cache_key in _UC14_IDEMPOTENCY_STORE:
        cached = dict(_UC14_IDEMPOTENCY_STORE[cache_key])
        cached["idempotent_replayed"] = True
        cached["keep_open"] = keep_open
        return cached

    raw_voucher_no_check = str(payload.get("voucher_no") or payload.get("number") or "").strip().upper()
    saved_voucher_key = (str(company.id), raw_voucher_no_check) if raw_voucher_no_check else None
    if (
        saved_voucher_key
        and saved_voucher_key in _UC14_PREPAID_SAVED_VOUCHERS
        and (
            bool(payload.get("allow_idempotent_voucher_resave", False))
            or bool(payload.get("already_saved_in_session", False))
            or str(payload.get("saved_voucher_id") or "") == str(_UC14_PREPAID_SAVED_VOUCHERS[saved_voucher_key].get("id") or "")
        )
    ):
        cached = dict(_UC14_PREPAID_SAVED_VOUCHERS[saved_voucher_key])
        cached["idempotent_replayed"] = True
        cached["keep_open"] = keep_open
        return cached

    # EF32: Concurrent modification check
    if (
        str(payload.get("source_data_stale", "false")).lower() in ("true", "1")
        or str(payload.get("simulate_concurrent_change", "false")).lower() in ("true", "1")
    ):
        raise ValidationError({
            "detail": "Dữ liệu ghi giảm đã thay đổi. Vui lòng tải lại và kiểm tra trước khi cất.",
        })

    # EF02: Số chứng từ để trống
    has_voucher_key = any(k in payload for k in ("voucher_no", "number", "document_number"))
    raw_voucher_no = payload.get("voucher_no") or payload.get("number") or payload.get("document_number")
    if has_voucher_key:
        voucher_no = str(raw_voucher_no or "").strip()
        if not voucher_no:
            raise ValidationError({
                "voucher_no": "Vui lòng nhập số chứng từ.",
                "detail": "Vui lòng nhập số chứng từ.",
            })
    else:
        voucher_no = get_next_prepaid_decrease_voucher_no_uc14(company)

    # EF03: Số chứng từ bị trùng trong phạm vi đánh số
    dup_exists = (
        bool(payload.get("force_duplicate_voucher_no", False))
        or PrepaidAllocation.objects.filter(company=company, number__iexact=voucher_no).exists()
        or models.AssetTransaction.objects.filter(
            company=company,
        ).filter(
            Q(number__iexact=voucher_no) | Q(number__istartswith=f"{voucher_no}-L")
        ).exclude(status=models.TransactionStatus.CANCELLED).exists()
        or JournalEntry.objects.filter(company=company, number__iexact=voucher_no).exclude(status="CANCELLED").exists()
    )
    if dup_exists:
        raise ValidationError({
            "voucher_no": "Số chứng từ đã tồn tại. Vui lòng sử dụng số khác.",
            "detail": "Số chứng từ đã tồn tại. Vui lòng sử dụng số khác.",
        })

    # EF04: Ngày chứng từ để trống hoặc sai định dạng
    has_date_key = any(k in payload for k in ("voucher_date", "document_date", "transaction_date", "date"))
    raw_date = (
        payload.get("voucher_date")
        if "voucher_date" in payload
        else (
            payload.get("document_date")
            if "document_date" in payload
            else (payload.get("transaction_date") if "transaction_date" in payload else payload.get("date"))
        )
    )
    if has_date_key:
        if raw_date is None or not str(raw_date).strip():
            raise ValidationError({
                "voucher_date": "Vui lòng nhập ngày chứng từ hợp lệ.",
                "detail": "Vui lòng nhập ngày chứng từ hợp lệ.",
            })
        voucher_date = _parse_date(raw_date)
        if not voucher_date:
            raise ValidationError({
                "voucher_date": "Vui lòng nhập ngày chứng từ hợp lệ.",
                "detail": "Vui lòng nhập ngày chứng từ hợp lệ.",
            })
    else:
        if bool(payload.get("require_voucher_date", False)):
            raise ValidationError({
                "voucher_date": "Vui lòng nhập ngày chứng từ hợp lệ.",
                "detail": "Vui lòng nhập ngày chứng từ hợp lệ.",
            })
        voucher_date = timezone.localdate()

    period_code = f"{voucher_date.year:04d}-{voucher_date.month:02d}"

    # EF05: Ngày ghi giảm thuộc kỳ kế toán đã khóa
    is_period_locked = (
        str(payload.get("period_locked", "false")).lower() in ("true", "1")
        or _closed(company, voucher_date)
        or models.AssetPeriod.objects.filter(
            company=company, code=period_code, status__in=("LOCKED", "CLOSED")
        ).exists()
        or AccountingPeriod.objects.filter(
            company=company,
            fiscal_year=voucher_date.year,
            period_number=voucher_date.month,
            status__in=("LOCKED", "CLOSED"),
        ).exists()
    )
    if is_period_locked:
        raise ValidationError({
            "period": "Kỳ kế toán đã khóa, không thể ghi giảm trong kỳ này.",
            "detail": "Kỳ kế toán đã khóa, không thể ghi giảm trong kỳ này.",
        })

    # EF07: Lý do ghi giảm chi phí trả trước để trống (Text field per Section 5.3)
    raw_reason = (
        payload.get("reason")
        if "reason" in payload
        else (payload.get("decrease_reason") if "decrease_reason" in payload else payload.get("description"))
    )
    reason = str(raw_reason or "").strip()
    if not reason:
        raise ValidationError({
            "reason": "Vui lòng nhập lý do ghi giảm chi phí trả trước.",
            "detail": "Vui lòng nhập lý do ghi giảm chi phí trả trước.",
        })

    # Validate references & attachments (EF30, EF31)
    validated_refs, validated_atts = _validate_uc14_references_and_attachments(request, company, payload)
    reference_str = str(payload.get("reference") or "").strip()
    if not reference_str and validated_refs:
        reference_str = ", ".join(r["voucher_no"] for r in validated_refs if r.get("voucher_no"))

    # EF08: Không có dòng đối tượng hợp lệ
    raw_lines = payload.get("lines") if "lines" in payload else (payload.get("items") if "items" in payload else payload.get("details"))
    if not isinstance(raw_lines, list) or len(raw_lines) == 0:
        raise ValidationError({
            "lines": "Vui lòng chọn ít nhất một CCDC hoặc khoản chi phí trả trước cần ghi giảm.",
            "detail": "Vui lòng chọn ít nhất một CCDC hoặc khoản chi phí trả trước cần ghi giảm.",
        })

    non_empty_lines = []
    for rl in raw_lines:
        if not isinstance(rl, dict) or bool(rl.get("is_empty", False)):
            continue
        has_any_ref = any(
            rl.get(k)
            for k in ("prepaid_id", "prepaid", "item_id", "id", "code", "prepaid_code", "decrease_amount", "remaining_amount", "amount")
        )
        if not has_any_ref:
            continue
        non_empty_lines.append(rl)

    if not non_empty_lines:
        raise ValidationError({
            "lines": "Vui lòng chọn ít nhất một CCDC hoặc khoản chi phí trả trước cần ghi giảm.",
            "detail": "Vui lòng chọn ít nhất một CCDC hoặc khoản chi phí trả trước cần ghi giảm.",
        })

    parsed_lines = []
    grouped_dec_sum: dict[str, Decimal] = {}
    grouped_rem_map: dict[str, tuple[str, Decimal]] = {}

    for idx, line in enumerate(non_empty_lines, start=1):
        # BR02: Reject mixing CCDC into CPTT decrease voucher
        if (
            line.get("tool_id")
            or line.get("tool_code")
            or str(line.get("item_type") or "").upper() in ("TOOL", "CCDC")
        ):
            raise ValidationError({
                "lines": "Khoản chi phí trả trước không hợp lệ.",
                "detail": "Khoản chi phí trả trước không hợp lệ.",
            })

        prepaid_id = str(
            line.get("prepaid_id") or line.get("prepaid") or line.get("item_id") or line.get("id") or ""
        ).strip()
        prepaid_code = str(line.get("code") or line.get("prepaid_code") or "").strip()

        if not prepaid_id and not prepaid_code:
            raise ValidationError({
                "lines": "Vui lòng chọn ít nhất một CCDC hoặc khoản chi phí trả trước cần ghi giảm.",
                "detail": "Vui lòng chọn ít nhất một CCDC hoặc khoản chi phí trả trước cần ghi giảm.",
            })

        prepaid = None
        if prepaid_id:
            try:
                uuid.UUID(prepaid_id)
                prepaid = (
                    PrepaidExpense.objects.select_related("prepaid_account")
                    .prefetch_related("targets__expense_account")
                    .filter(pk=prepaid_id)
                    .first()
                )
            except (ValueError, TypeError):
                prepaid = (
                    PrepaidExpense.objects.select_related("prepaid_account")
                    .prefetch_related("targets__expense_account")
                    .filter(company=company, code__iexact=prepaid_id)
                    .first()
                )
        if not prepaid and prepaid_code:
            prepaid = (
                PrepaidExpense.objects.select_related("prepaid_account")
                .prefetch_related("targets__expense_account")
                .filter(company=company, code__iexact=prepaid_code)
                .first()
            )
            if not prepaid:
                prepaid = (
                    PrepaidExpense.objects.select_related("prepaid_account")
                    .prefetch_related("targets__expense_account")
                    .filter(code__iexact=prepaid_code)
                    .first()
                )

        # EF20: CPTT không tồn tại hoặc chưa được ghi nhận hợp lệ
        if (
            not prepaid
            or prepaid.company_id != company.id
            or bool(line.get("invalid_prepaid", False))
            or (prepaid.record_date and voucher_date < prepaid.record_date and bool(line.get("treat_before_record_as_invalid", True)))
        ):
            raise ValidationError({
                "lines": "Khoản chi phí trả trước không hợp lệ.",
                "detail": "Khoản chi phí trả trước không hợp lệ.",
            })

        comp = models.AssetRecord.objects.filter(
            company=company,
            source_module="PREPAID_EXPENSE",
            code__iexact=prepaid.code,
        ).first()
        comp_meta = (comp.accessories or [{}])[0] if comp and isinstance(comp.accessories, list) and comp.accessories else {}
        if not isinstance(comp_meta, dict):
            comp_meta = {}

        # EF25: Phần số lượng hoặc giá trị đã bị ghi giảm ở chứng từ khác
        if (
            bool(line.get("already_disposed_elsewhere", False))
            or bool(comp_meta.get("already_disposed_elsewhere", False))
            or bool(payload.get("already_disposed_elsewhere", False))
        ):
            raise ValidationError({
                "lines": "Đối tượng đã được ghi giảm tại chứng từ khác. Vui lòng tải lại dữ liệu.",
                "detail": "Đối tượng đã được ghi giảm tại chứng từ khác. Vui lòng tải lại dữ liệu.",
            })

        # EF27: Ghi giảm lùi ngày làm sai kết quả phân bổ của các chứng từ đã ghi sổ sau đó
        has_conflict_after = (
            bool(line.get("has_subsequent_conflict", False))
            or bool(comp_meta.get("has_subsequent_conflict", False))
            or bool(payload.get("simulate_backdated_conflict", False))
            or PrepaidAllocationLine.objects.filter(
                prepaid=prepaid,
                allocation__company=company,
                allocation__posting_date__gt=voucher_date,
            ).exists()
        )
        if has_conflict_after:
            raise ValidationError({
                "voucher_date": "Ngày ghi giảm ảnh hưởng đến các chứng từ phát sinh sau ngày này. Vui lòng kiểm tra lịch sử liên quan.",
                "detail": "Ngày ghi giảm ảnh hưởng đến các chứng từ phát sinh sau ngày này. Vui lòng kiểm tra lịch sử liên quan.",
            })

        # EF26: Giá trị đã phân bổ hoặc giá trị còn lại không nhất quán với sổ theo dõi
        tot_alloc = (prepaid.opening_allocated_amount or Decimal("0")) + (prepaid.allocated_amount or Decimal("0"))
        prior_dec_val = _parse_decimal(comp_meta.get("decreased_amount"), default=Decimal("0.00")) or Decimal("0.00")
        if (
            bool(line.get("history_inconsistent", False))
            or bool(comp_meta.get("history_inconsistent", False))
            or bool(payload.get("simulate_history_inconsistent", False))
            or tot_alloc < Decimal("0")
            or (tot_alloc + prior_dec_val) > prepaid.amount
        ):
            raise ValidationError({
                "lines": f"Giá trị còn lại của {prepaid.code} chưa khớp với lịch sử phân bổ.",
                "detail": f"Giá trị còn lại của {prepaid.code} chưa khớp với lịch sử phân bổ.",
            })

        current_rem = prepaid.remaining_amount.quantize(Decimal("0.01"))

        # EF32: Check if client's expected remaining amount differs from current DB state
        if line.get("expected_remaining_amount") is not None:
            exp_rem = _parse_decimal(line.get("expected_remaining_amount"), default=None)
            if exp_rem is not None and exp_rem.quantize(Decimal("0.01")) != current_rem:
                raise ValidationError({
                    "detail": "Dữ liệu ghi giảm đã thay đổi. Vui lòng tải lại và kiểm tra trước khi cất.",
                })

        # EF21: CPTT đã giảm hết hoặc không còn giá trị chưa phân bổ
        if (
            prepaid.status in (PrepaidExpense.Status.DECREASED, PrepaidExpense.Status.COMPLETED)
            or current_rem <= Decimal("0.00")
        ):
            raise ValidationError({
                "lines": "Khoản chi phí trả trước không còn giá trị để ghi giảm.",
                "detail": "Khoản chi phí trả trước không còn giá trị để ghi giảm.",
            })

        # EF22 & EF23: Parse & validate Số tiền còn lại của CPTT ghi giảm
        has_amt_key = any(k in line for k in ("decrease_amount", "remaining_amount", "amount", "value"))
        raw_amt = (
            line.get("decrease_amount")
            if "decrease_amount" in line
            else (
                line.get("remaining_amount")
                if "remaining_amount" in line
                else (line.get("amount") if "amount" in line else line.get("value"))
            )
        )
        if has_amt_key and raw_amt is not None and str(raw_amt).strip() != "":
            dec_amt = _parse_decimal(raw_amt, default=None)
            if dec_amt is None or dec_amt <= Decimal("0") or isinstance(raw_amt, bool):
                raise ValidationError({
                    "lines": "Số tiền ghi giảm phải lớn hơn 0.",
                    "detail": "Số tiền ghi giảm phải lớn hơn 0.",
                })
            dec_amt = dec_amt.quantize(Decimal("0.01"))
        elif has_amt_key and (raw_amt is None or str(raw_amt).strip() == ""):
            raise ValidationError({
                "lines": "Số tiền ghi giảm phải lớn hơn 0.",
                "detail": "Số tiền ghi giảm phải lớn hơn 0.",
            })
        else:
            # Main Flow B Step 9: Defaults to current unallocated remaining amount
            dec_amt = current_rem

        # EF23: Số tiền ghi giảm vượt giá trị còn lại hợp lệ
        if dec_amt > current_rem:
            raise ValidationError({
                "lines": "Số tiền ghi giảm vượt số tiền chưa phân bổ của khoản chi phí.",
                "detail": "Số tiền ghi giảm vượt số tiền chưa phân bổ của khoản chi phí.",
            })

        grouped_dec_sum[str(prepaid.id)] = grouped_dec_sum.get(str(prepaid.id), Decimal("0.00")) + dec_amt
        grouped_rem_map[str(prepaid.id)] = (prepaid.code, current_rem)

        # EF28: Chưa xác định được phương án xử lý giá trị còn lại
        treatment = str(
            line.get("accounting_treatment")
            or payload.get("accounting_treatment")
            or "EXPENSE_WRITEOFF"
        ).strip().upper()
        if (
            str(payload.get("missing_accounting_treatment", "false")).lower() in ("true", "1")
            or str(line.get("missing_accounting_treatment", "false")).lower() in ("true", "1")
            or treatment in ("NONE", "MISSING", "UNSPECIFIED")
        ):
            raise ValidationError({
                "accounting_treatment": "Chưa có phương án xử lý giá trị còn lại. Vui lòng bổ sung chứng từ hoặc quyết định xử lý.",
                "detail": "Chưa có phương án xử lý giá trị còn lại. Vui lòng bổ sung chứng từ hoặc quyết định xử lý.",
            })

        # EF29: Giá trị đã được hạch toán tại chứng từ khác
        if (
            bool(payload.get("already_accounted_elsewhere", False))
            or bool(line.get("already_accounted_elsewhere", False))
            or bool(comp_meta.get("decrease_accounted_elsewhere", False))
        ):
            raise ValidationError({
                "accounting_treatment": "Giá trị ghi giảm đã được xử lý kế toán ở chứng từ liên quan.",
                "detail": "Giá trị ghi giảm đã được xử lý kế toán ở chứng từ liên quan.",
            })

        parsed_lines.append({
            "line_no": idx,
            "prepaid": prepaid,
            "companion": comp,
            "code": prepaid.code,
            "name": prepaid.name,  # Section 5.4 & 9: Synced from source, never overwritten by arbitrary input
            "remaining_before": current_rem,
            "decrease_amount": dec_amt,
            "treatment": treatment,
            "debit_account": str(line.get("debit_account") or payload.get("debit_account") or "").strip(),
            "credit_account": str(
                line.get("credit_account")
                or payload.get("credit_account")
                or (prepaid.prepaid_account.code if prepaid.prepaid_account_id else "242")
            ).strip(),
            "refund_voucher_no": str(line.get("refund_voucher_no") or payload.get("refund_voucher_no") or "").strip(),
            "reclassification_target": str(line.get("reclassification_target") or payload.get("reclassification_target") or "").strip(),
            "new_allocation_periods": line.get("new_allocation_periods") or payload.get("new_allocation_periods"),
        })

    # EF24: Cùng một CPTT xuất hiện nhiều dòng, tổng tiền ghi giảm vượt giá trị còn lại
    for pid_str, sum_dec in grouped_dec_sum.items():
        p_code, avail_rem = grouped_rem_map[pid_str]
        if sum_dec > avail_rem:
            raise ValidationError({
                "lines": f"Tổng số tiền ghi giảm của {p_code} vượt giá trị còn lại.",
                "detail": f"Tổng số tiền ghi giảm của {p_code} vượt giá trị còn lại.",
            })

    # EF34: Lỗi hệ thống khi ghi nhận chứng từ ghi giảm
    if (
        str(payload.get("simulate_save_error", "false")).lower() in ("true", "1")
        or str(payload.get("simulate_db_error", "false")).lower() in ("true", "1")
    ):
        raise ValidationError({
            "detail": "Ghi nhận chứng từ ghi giảm thất bại. Vui lòng thử lại.",
        })

    total_decrease_amount = sum((pl["decrease_amount"] for pl in parsed_lines), Decimal("0.00")).quantize(Decimal("0.01"))
    detail_rows_response = []
    allocation_record = None
    gl_entry = None

    with transaction.atomic():
        gl_period = _ensure_open_gl_period_for_uc12(company, voucher_date.month, voucher_date.year)
        branch_obj = company.branches.first()

        lines_by_prepaid: dict[str, list[dict]] = {}
        for pl in parsed_lines:
            lines_by_prepaid.setdefault(str(pl["prepaid"].id), []).append(pl)

        # Build GL entry lines according to accounting treatment (AF17, AF18, AF19, BR29–BR31, Section 4.10)
        gl_tuples = []
        pa_lines_to_create = []

        for pid_str, p_lines in lines_by_prepaid.items():
            prepaid = PrepaidExpense.objects.select_for_update().select_related("prepaid_account").prefetch_related("targets__expense_account").get(pk=pid_str)
            comp = models.AssetRecord.objects.select_for_update().filter(
                company=company,
                source_module="PREPAID_EXPENSE",
                code__iexact=prepaid.code,
            ).first()
            if not comp:
                # Create companion AssetRecord if it wasn't created via UC-FA-10
                cat_obj = models.AssetCategory.objects.filter(company=company, asset_type=models.AssetType.TOOL).first()
                if not cat_obj:
                    cat_obj = models.AssetCategory.objects.create(
                        company=company,
                        code="CPTT_CAT",
                        name="Chi phí trả trước",
                        asset_type=models.AssetType.TOOL,
                        default_periods=prepaid.allocation_periods or 12,
                    )
                comp = models.AssetRecord.objects.create(
                    company=company,
                    branch=branch_obj,
                    code=prepaid.code,
                    name=prepaid.name,
                    asset_type=models.AssetType.TOOL,
                    category=cat_obj,
                    quantity=Decimal("1"),
                    acquisition_date=prepaid.record_date,
                    in_service_date=prepaid.start_date,
                    original_cost=prepaid.amount,
                    allocated_value=(prepaid.opening_allocated_amount or Decimal("0")) + (prepaid.allocated_amount or Decimal("0")),
                    useful_life_periods=prepaid.allocation_periods or 1,
                    periods_processed=(prepaid.opening_allocated_periods or 0) + (prepaid.allocated_periods or 0),
                    asset_account=prepaid.prepaid_account,
                    source_module="PREPAID_EXPENSE",
                    status=models.AssetStatus.ACTIVE,
                    created_by=actor(request),
                )

            comp_meta = dict((comp.accessories or [{}])[0]) if isinstance(comp.accessories, list) and comp.accessories and isinstance(comp.accessories[0], dict) else {}
            before_comp_meta = {k: v for k, v in comp_meta.items() if k != "decrease_history"}
            before_rem = prepaid.remaining_amount.quantize(Decimal("0.01"))
            before_status = prepaid.status

            item_dec_sum = sum((pl["decrease_amount"] for pl in p_lines), Decimal("0.00")).quantize(Decimal("0.01"))
            if item_dec_sum > before_rem:
                raise ValidationError({
                    "detail": "Dữ liệu ghi giảm đã thay đổi. Vui lòng tải lại và kiểm tra trước khi cất.",
                })

            prior_dec = _parse_decimal(comp_meta.get("decreased_amount"), default=Decimal("0.00")) or Decimal("0.00")
            new_dec = (prior_dec + item_dec_sum).quantize(Decimal("0.01"))
            rem_after = max(Decimal("0.00"), (before_rem - item_dec_sum).quantize(Decimal("0.01")))

            comp_meta["initial_amount"] = str(prepaid.amount.quantize(Decimal("0.01")))
            comp_meta["decreased_amount"] = str(new_dec)
            comp_meta["adjusted_total_amount"] = str(max(Decimal("0.00"), prepaid.amount - new_dec).quantize(Decimal("0.01")))
            comp_meta["prior_allocated_amount"] = str(((prepaid.opening_allocated_amount or Decimal("0")) + (prepaid.allocated_amount or Decimal("0"))).quantize(Decimal("0.01")))
            comp_meta["last_decrease_voucher_no"] = voucher_no
            comp_meta["last_decrease_date"] = voucher_date.isoformat()
            comp_meta["last_decrease_reason"] = reason

            first_treatment = p_lines[0]["treatment"]
            if first_treatment == "RECLASSIFICATION":
                # AF18 & BR30: Reclassify short-term <-> long-term or update allocation periods
                comp_meta["classification"] = p_lines[0]["reclassification_target"] or "LONG_TERM"
                if p_lines[0]["new_allocation_periods"]:
                    try:
                        new_p = int(p_lines[0]["new_allocation_periods"])
                        if new_p > 0:
                            prepaid.allocation_periods = new_p
                            comp.useful_life_periods = new_p
                    except (ValueError, TypeError):
                        pass

            if rem_after == Decimal("0.00"):
                # AF15 & BR27: Full write-down ends normal allocation
                prepaid.status = PrepaidExpense.Status.DECREASED
                comp.status = models.AssetStatus.DISPOSED
                comp.disposed_at = voucher_date
                comp_meta["stop_allocation"] = True
                comp_meta["stop_effective_date"] = voucher_date.isoformat()
                comp_meta["decrease_effective_date"] = voucher_date.isoformat()
            else:
                # AF16 & BR28: Partial write-down keeps remaining amount active for future periods
                rem_periods = max(prepaid.remaining_periods, 1)
                comp_meta["adjusted_periodic_amount"] = str((rem_after / Decimal(rem_periods)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

            prepaid._decreased_amount_cache = new_dec
            prepaid.save(update_fields=("allocation_periods", "status", "updated_at"))

            dec_history = list(comp_meta.get("decrease_history")) if isinstance(comp_meta.get("decrease_history"), list) else []
            for pl in p_lines:
                dec_history.append({
                    "voucher_no": voucher_no,
                    "line_no": pl["line_no"],
                    "voucher_date": voucher_date.isoformat(),
                    "reason": reason,
                    "treatment": pl["treatment"],
                    "remaining_before": str(before_rem),
                    "decrease_amount": str(pl["decrease_amount"]),
                    "remaining_after": str(rem_after),
                    "before_meta": before_comp_meta,
                    "before_status": before_status,
                })
                detail_rows_response.append({
                    "line_no": pl["line_no"],
                    "prepaid_id": str(prepaid.id),
                    "code": prepaid.code,
                    "name": prepaid.name,
                    "remaining_before": str(before_rem),
                    "decrease_amount": str(pl["decrease_amount"]),
                    "remaining_amount": str(pl["decrease_amount"]),
                    "remaining_after": str(rem_after),
                    "treatment": pl["treatment"],
                })

                # Determine accounting entry lines per treatment (Section 4.10, BR29–BR31)
                t_mode = pl["treatment"]
                post_gl_flag = bool(payload.get("create_gl_entry", True)) and t_mode not in ("LINKED_VOUCHER", "DEFERRED", "NO_GL")
                if post_gl_flag:
                    wait_acc = prepaid.prepaid_account
                    if pl["debit_account"]:
                        d_acc = _resolve_account(company, pl["debit_account"]) or _ensure_gl_account_for_code(company, pl["debit_account"], is_debit=True)
                        gl_tuples.append((d_acc, wait_acc, pl["decrease_amount"], f"Ghi giảm CPTT {prepaid.code} ({reason})"[:500]))
                        pa_lines_to_create.append((prepaid, d_acc, pl["decrease_amount"]))
                    elif t_mode == "REFUND_OR_RECEIVABLE":
                        ref_acc_code = str(payload.get("refund_account") or "1388").strip()
                        d_acc = _resolve_account(company, ref_acc_code) or _ensure_gl_account_for_code(company, ref_acc_code, is_debit=True)
                        gl_tuples.append((d_acc, wait_acc, pl["decrease_amount"], f"Thu hồi/công nợ khi ghi giảm CPTT {prepaid.code}"[:500]))
                        pa_lines_to_create.append((prepaid, d_acc, pl["decrease_amount"]))
                    elif t_mode == "EXPENSE_WRITEOFF":
                        targets = list(prepaid.targets.select_related("expense_account").all())
                        if targets:
                            used_amt = Decimal("0.00")
                            for idx_t, t_row in enumerate(targets):
                                if idx_t < len(targets) - 1:
                                    s_val = (pl["decrease_amount"] * t_row.rate / Decimal("100")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                                    used_amt += s_val
                                else:
                                    s_val = (pl["decrease_amount"] - used_amt).quantize(Decimal("0.01"))
                                if s_val > Decimal("0.00"):
                                    gl_tuples.append((t_row.expense_account, wait_acc, s_val, f"Ghi giảm CPTT {prepaid.code} - {prepaid.name}"[:500]))
                                    pa_lines_to_create.append((prepaid, t_row.expense_account, s_val))
                        else:
                            default_exp = Account.objects.filter(company=company, code__startswith="642", is_postable=True).first() or wait_acc
                            gl_tuples.append((default_exp, wait_acc, pl["decrease_amount"], f"Ghi giảm CPTT {prepaid.code} - {prepaid.name}"[:500]))
                            pa_lines_to_create.append((prepaid, default_exp, pl["decrease_amount"]))

            comp_meta["decrease_history"] = dec_history
            comp_meta["references"] = validated_refs
            comp_meta["attachments"] = validated_atts
            comp.accessories = [comp_meta]
            comp.save(update_fields=("useful_life_periods", "status", "disposed_at", "accessories", "updated_at"))

            audit(
                request,
                prepaid,
                "DECREASE_PREPAID_UC14",
                before={
                    "status": before_status,
                    "remaining_amount": str(before_rem),
                    "allocated_amount": str(prepaid.allocated_amount),
                },
                after={
                    "voucher_no": voucher_no,
                    "voucher_date": voucher_date.isoformat(),
                    "reason": reason,
                    "status": prepaid.status,
                    "decrease_amount": str(item_dec_sum),
                    "remaining_amount": str(rem_after),
                    "allocated_amount": str(prepaid.allocated_amount),
                },
                reason=reason,
            )

        if gl_tuples:
            gl_total = sum((t[2] for t in gl_tuples), Decimal("0.00")).quantize(Decimal("0.01"))
            gl_entry = JournalEntry.objects.create(
                company=company,
                branch=branch_obj,
                period=gl_period,
                number=f"{voucher_no}-GL",
                entry_type="ALLOCATION",
                posting_date=voucher_date,
                document_date=voucher_date,
                description=reason[:500],
                source_module="GL",
                source_event_id=f"UC14.PREPAID:{company.id}:{voucher_no}:{uuid.uuid4().hex[:8]}",
                source_entity_type="PrepaidAllocation",
                status="APPROVED",
                total_debit=gl_total,
                total_credit=gl_total,
                created_by=actor(request),
                approved_by=actor(request),
                approved_at=timezone.now(),
                workflow_snapshot={"allow_creator_posting": True},
            )
            l_no = 1
            for d_acc, c_acc, amt_v, desc_txt in gl_tuples:
                JournalLine.objects.create(
                    entry=gl_entry,
                    line_no=l_no,
                    account=d_acc,
                    debit=amt_v,
                    credit=Decimal("0.00"),
                    currency=company.accounting_currency,
                    description=desc_txt,
                )
                l_no += 1
                JournalLine.objects.create(
                    entry=gl_entry,
                    line_no=l_no,
                    account=c_acc,
                    debit=Decimal("0.00"),
                    credit=amt_v,
                    currency=company.accounting_currency,
                    description=desc_txt,
                )
                l_no += 1
            post_gl_entry(gl_entry, request)

            allocation_record = PrepaidAllocation.objects.create(
                company=company,
                kind=PrepaidAllocation.Kind.DECREASE,
                number=voucher_no,
                period=gl_period,
                document_date=voucher_date,
                posting_date=voucher_date,
                description=reason[:500],
                total_amount=total_decrease_amount,
                entry=gl_entry,
                created_by=actor(request),
            )
            for pe_obj, exp_acc_obj, amt_v in pa_lines_to_create:
                PrepaidAllocationLine.objects.create(
                    allocation=allocation_record,
                    prepaid=pe_obj,
                    expense_account=exp_acc_obj,
                    amount=amt_v,
                )

    success_message = f"Đã lưu chứng từ ghi giảm chi phí trả trước {voucher_no} thành công."
    response_data = {
        "id": str(allocation_record.id) if allocation_record else str(parsed_lines[0]["prepaid"].id),
        "company_id": str(company.id),
        "voucher_type": "PREPAID_DECREASE",
        "voucher_no": voucher_no,
        "voucher_date": voucher_date.strftime("%d/%m/%Y"),
        "voucher_date_iso": voucher_date.isoformat(),
        "period_code": period_code,
        "reason": reason,
        "reference": reference_str,
        "references": validated_refs,
        "attachments": validated_atts,
        "lines": detail_rows_response,
        "total_decrease_amount": str(total_decrease_amount),
        "total_amount": str(total_decrease_amount),
        "status": "POSTED",
        "status_display": "Đã ghi sổ",
        "gl_posted": gl_entry is not None,
        "gl_entry_id": str(gl_entry.id) if gl_entry else None,
        "keep_open": keep_open,
        "close_on_save": not keep_open,
        "message": success_message,
        "idempotent_replayed": False,
    }
    if cache_key:
        _UC14_IDEMPOTENCY_STORE[cache_key] = dict(response_data)
    _UC14_PREPAID_SAVED_VOUCHERS[(str(company.id), voucher_no.upper())] = dict(response_data)
    return response_data


def cancel_or_adjust_decrease_voucher_uc14(request, data=None):
    """
    UC-FA-14 AF25, EF05, EF36, BR40:
    Cancels or reverses a CCDC or Prepaid Expense decrease voucher after checking
    accounting period lock (EF05) and dependent subsequent vouchers (EF36).
    """
    from general_ledger.models import AccountingPeriod, JournalEntry, PrepaidAllocation, PrepaidExpense

    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc14(request, payload)
    _check_uc14_permission_and_scope(request, company, payload)

    voucher_no = str(payload.get("voucher_no") or payload.get("number") or "").strip()
    if not voucher_no:
        raise ValidationError({"voucher_no": "Vui lòng nhập số chứng từ."})

    # Check if this is a CCDC decrease voucher
    tx_list = list(
        models.AssetTransaction.objects.filter(
            company=company,
            transaction_type=models.TransactionType.DISPOSAL,
            status=models.TransactionStatus.POSTED,
        )
        .filter(
            Q(number__iexact=voucher_no)
            | Q(number__istartswith=f"{voucher_no}-L")
            | Q(source_reference__iexact=voucher_no)
        )
        .select_related("asset")
        .order_by("created_at")
    )

    if tx_list:
        first_tx = tx_list[0]
        v_date = first_tx.transaction_date
        p_code = f"{v_date.year:04d}-{v_date.month:02d}"

        # EF05: Locked period check
        if (
            str(payload.get("period_locked", "false")).lower() in ("true", "1")
            or _closed(company, v_date)
            or models.AssetPeriod.objects.filter(company=company, code=p_code, status__in=("LOCKED", "CLOSED")).exists()
            or AccountingPeriod.objects.filter(
                company=company, fiscal_year=v_date.year, period_number=v_date.month, status__in=("LOCKED", "CLOSED")
            ).exists()
        ):
            raise ValidationError({
                "period": "Kỳ kế toán đã khóa, không thể ghi giảm trong kỳ này.",
                "detail": "Kỳ kế toán đã khóa, không thể ghi giảm trong kỳ này.",
            })

        # EF36: Dependent voucher check
        tx_ids = {t.id for t in tx_list}
        affected_assets = {t.asset_id for t in tx_list}
        has_dependent = (
            bool(payload.get("has_dependent_vouchers", False))
            or models.AssetTransaction.objects.filter(
                company=company,
                asset_id__in=affected_assets,
                status=models.TransactionStatus.POSTED,
                transaction_date__gt=v_date,
            )
            .exclude(id__in=tx_ids)
            .exists()
            or models.CalculationLine.objects.filter(
                run__company=company,
                run__status="POSTED",
                run__period_end__gte=v_date,
                asset_id__in=affected_assets,
            ).exists()
        )
        if has_dependent:
            raise ValidationError({
                "detail": "Không thể hủy hoặc sửa chứng từ vì đã phát sinh nghiệp vụ liên quan. Vui lòng xử lý chứng từ phụ thuộc trước.",
            })

        with transaction.atomic():
            restored_tools = set()
            for tx in tx_list:
                tool = models.AssetRecord.objects.select_for_update().get(pk=tx.asset_id)
                if tool.id not in restored_tools:
                    b_snap = tx.before_snapshot if isinstance(tx.before_snapshot, dict) else {}
                    if b_snap.get("status"):
                        tool.status = b_snap["status"]
                        if tool.status != models.AssetStatus.DISPOSED:
                            tool.disposed_at = None
                    if b_snap.get("quantity") is not None:
                        q_prev = _parse_decimal(b_snap.get("quantity"), default=tool.quantity)
                        if q_prev and q_prev > Decimal("0"):
                            tool.quantity = q_prev
                    if isinstance(b_snap.get("components"), list):
                        tool.components = b_snap["components"]
                    if isinstance(b_snap.get("allocations"), list):
                        tool.allocations = b_snap["allocations"]
                    if isinstance(b_snap.get("meta"), dict):
                        tool.accessories = [dict(b_snap["meta"])]
                    tool.save(update_fields=("status", "disposed_at", "quantity", "components", "allocations", "accessories", "updated_at"))
                    restored_tools.add(tool.id)

                tx.status = models.TransactionStatus.CANCELLED
                tx.save(update_fields=("status", "updated_at"))
                audit(
                    request,
                    tx,
                    "CANCEL_DECREASE_TOOL_UC14",
                    before={"status": "POSTED"},
                    after={"status": "CANCELLED"},
                    reason=str(payload.get("reason") or f"Hủy chứng từ ghi giảm CCDC {voucher_no}"),
                )

            JournalEntry.objects.filter(company=company, number__iexact=voucher_no).delete()

        return {
            "voucher_no": voucher_no,
            "voucher_type": "TOOL_DECREASE",
            "status": "CANCELLED",
            "message": f"Đã hủy chứng từ ghi giảm CCDC {voucher_no} thành công.",
        }

    # Check if this is a Prepaid Expense decrease voucher
    pa = PrepaidAllocation.objects.filter(
        company=company,
        kind=PrepaidAllocation.Kind.DECREASE,
        number__iexact=voucher_no,
    ).select_related("entry").first()

    # Also find companion AssetRecords that recorded this voucher in decrease_history
    companions_with_voucher = []
    for comp in models.AssetRecord.objects.filter(company=company, source_module="PREPAID_EXPENSE"):
        c_meta = (comp.accessories or [{}])[0] if isinstance(comp.accessories, list) and comp.accessories else {}
        if isinstance(c_meta, dict):
            hist = c_meta.get("decrease_history") if isinstance(c_meta.get("decrease_history"), list) else []
            if any(str(h.get("voucher_no") or "").upper() == voucher_no.upper() for h in hist):
                companions_with_voucher.append(comp)

    if not pa and not companions_with_voucher:
        raise ValidationError({"voucher_no": "Không tìm thấy chứng từ ghi giảm."})

    v_date = pa.posting_date if pa else (_parse_date((companions_with_voucher[0].accessories[0]).get("last_decrease_date")) or timezone.localdate())
    p_code = f"{v_date.year:04d}-{v_date.month:02d}"

    # EF05: Locked period check
    if (
        str(payload.get("period_locked", "false")).lower() in ("true", "1")
        or _closed(company, v_date)
        or models.AssetPeriod.objects.filter(company=company, code=p_code, status__in=("LOCKED", "CLOSED")).exists()
        or AccountingPeriod.objects.filter(
            company=company, fiscal_year=v_date.year, period_number=v_date.month, status__in=("LOCKED", "CLOSED")
        ).exists()
    ):
        raise ValidationError({
            "period": "Kỳ kế toán đã khóa, không thể ghi giảm trong kỳ này.",
            "detail": "Kỳ kế toán đã khóa, không thể ghi giảm trong kỳ này.",
        })

    # EF36: Dependent voucher check
    affected_codes = [c.code for c in companions_with_voucher]
    if pa:
        for pal in pa.lines.select_related("prepaid"):
            affected_codes.append(pal.prepaid.code)
    has_dependent = (
        bool(payload.get("has_dependent_vouchers", False))
        or PrepaidAllocation.objects.filter(
            company=company,
            posting_date__gt=v_date,
            lines__prepaid__code__in=affected_codes,
        ).exists()
    )
    if has_dependent:
        raise ValidationError({
            "detail": "Không thể hủy hoặc sửa chứng từ vì đã phát sinh nghiệp vụ liên quan. Vui lòng xử lý chứng từ phụ thuộc trước.",
        })

    with transaction.atomic():
        for comp in companions_with_voucher:
            c_meta = (comp.accessories or [{}])[0] if isinstance(comp.accessories, list) and comp.accessories else {}
            hist = c_meta.get("decrease_history") if isinstance(c_meta.get("decrease_history"), list) else []
            matching_entries = [h for h in hist if str(h.get("voucher_no") or "").upper() == voucher_no.upper()]
            remaining_entries = [h for h in hist if str(h.get("voucher_no") or "").upper() != voucher_no.upper()]
            reverted_amt = sum((_parse_decimal(h.get("decrease_amount"), default=Decimal("0")) or Decimal("0")) for h in matching_entries)

            prepaid = PrepaidExpense.objects.select_for_update().filter(company=company, code__iexact=comp.code).first()
            cur_dec = _parse_decimal(c_meta.get("decreased_amount"), default=Decimal("0")) or Decimal("0")
            new_dec = max(Decimal("0.00"), (cur_dec - reverted_amt).quantize(Decimal("0.01")))
            c_meta["decreased_amount"] = str(new_dec)
            if prepaid:
                c_meta["adjusted_total_amount"] = str(max(Decimal("0.00"), prepaid.amount - new_dec).quantize(Decimal("0.01")))
                prepaid._decreased_amount_cache = new_dec
                if prepaid.remaining_amount > Decimal("0"):
                    prepaid.status = PrepaidExpense.Status.ACTIVE
                    comp.status = models.AssetStatus.ACTIVE
                    comp.disposed_at = None
                    c_meta.pop("stop_allocation", None)
                    c_meta.pop("stop_effective_date", None)
                prepaid.save(update_fields=("status", "updated_at"))
            c_meta["decrease_history"] = remaining_entries
            comp.accessories = [c_meta]
            comp.save(update_fields=("status", "disposed_at", "accessories", "updated_at"))

        if pa:
            entry_to_del = pa.entry
            pa.delete()
            if entry_to_del:
                entry_to_del.delete()

        _UC14_PREPAID_SAVED_VOUCHERS.pop((str(company.id), voucher_no.upper()), None)

    return {
        "voucher_no": voucher_no,
        "voucher_type": "PREPAID_DECREASE",
        "status": "CANCELLED",
        "message": f"Đã hủy chứng từ ghi giảm chi phí trả trước {voucher_no} thành công.",
    }


# ============================================================================
# UC-FA-15: KIỂM KÊ CCDC (TOOLS & EQUIPMENT PHYSICAL COUNT / STOCKTAKE)
# ============================================================================

_UC15_IDEMPOTENCY_STORE: dict[tuple[str, str], dict] = {}

UC15_VALID_COMMITTEE_ROLES = (
    "Trưởng ban",
    "Phó ban",
    "Ủy viên",
    "Thư ký",
)


def _is_discrete_unit_uc13(unit: str) -> bool:
    u_low = str(unit or "").strip().lower()
    if u_low in ("kg", "m", "m2", "m3", "lít", "lit", "tấn", "tan", "km", "giờ", "gio"):
        return False
    return True


def _resolve_company_for_uc15(request, payload: dict):
    company_id = (
        payload.get("company_id")
        or payload.get("company")
        or (request.query_params.get("company_id") if hasattr(request, "query_params") else None)
        or (request.query_params.get("company") if hasattr(request, "query_params") else None)
    )
    if not company_id:
        raise ValidationError({
            "company": "Bạn không có quyền lập biên bản kiểm kê CCDC.",
            "detail": "Bạn không có quyền lập biên bản kiểm kê CCDC.",
        })
    try:
        return Company.objects.get(pk=company_id)
    except (Company.DoesNotExist, ValueError, TypeError):
        raise ValidationError({
            "company": "Bạn không có quyền lập biên bản kiểm kê CCDC.",
            "detail": "Bạn không có quyền lập biên bản kiểm kê CCDC.",
        })


def _check_uc15_permission_and_scope(request, company, payload: dict):
    """
    EF01 & BR01: Kiểm tra quyền lập biên bản kiểm kê CCDC.
    """
    if (
        str(payload.get("simulate_permission_denied", "false")).lower() in ("true", "1")
        or (hasattr(request, "query_params") and str(request.query_params.get("simulate_permission_denied", "false")).lower() in ("true", "1"))
    ):
        raise PermissionDenied("Bạn không có quyền lập biên bản kiểm kê CCDC.")

    user = getattr(request, "user", None)
    if not user or not getattr(user, "is_authenticated", False):
        raise PermissionDenied("Bạn không có quyền lập biên bản kiểm kê CCDC.")
    if getattr(user, "is_superuser", False):
        return

    iam_acc = _resolve_user_account(request)
    if not iam_acc:
        raise PermissionDenied("Bạn không có quyền lập biên bản kiểm kê CCDC.")

    from iam.models import CompanyMembership
    from iam.permissions import has_effective_permission

    memberships = CompanyMembership.objects.filter(user=iam_acc)
    if memberships.exists() and not memberships.filter(company=company).exists():
        raise PermissionDenied("Bạn không có quyền lập biên bản kiểm kê CCDC.")

    allowed_codes = (
        "FA.COUNT.CREATE",
        "FA.COUNT.EDIT",
        "FA.COUNT.VIEW",
        "FA.ASSET.CREATE",
        "FA.ASSET.EDIT",
        "FA.ASSET.VIEW",
    )
    if not any(has_effective_permission(iam_acc, company, c) for c in allowed_codes):
        raise PermissionDenied("Bạn không có quyền lập biên bản kiểm kê CCDC.")


def _validate_uc15_count_to_date(payload: dict, company, request=None, require_explicit: bool = False):
    """
    Validates 'Kiểm kê đến ngày' per Main Flow Steps 5–7, AF03, AF04, BR03, BR04, EF02–EF05.
    """
    has_date_key = any(
        k in payload for k in ("count_to_date", "count_date", "to_date", "date", "as_of_date")
    )
    raw_date = (
        payload.get("count_to_date")
        if "count_to_date" in payload
        else (
            payload.get("count_date")
            if "count_date" in payload
            else (
                payload.get("to_date")
                if "to_date" in payload
                else (
                    payload.get("date")
                    if "date" in payload
                    else payload.get("as_of_date")
                )
            )
        )
    )
    if not has_date_key and hasattr(request, "query_params"):
        for qk in ("count_to_date", "count_date", "to_date", "date", "as_of_date"):
            if qk in request.query_params:
                has_date_key = True
                raw_date = request.query_params.get(qk)
                break

    if has_date_key or require_explicit:
        if raw_date is None or not str(raw_date).strip():
            # EF02: Trường Kiểm kê đến ngày để trống
            raise ValidationError({
                "count_to_date": "Vui lòng nhập ngày kiểm kê.",
                "count_date": "Vui lòng nhập ngày kiểm kê.",
                "detail": "Vui lòng nhập ngày kiểm kê.",
            })
        count_dt = _parse_date(raw_date)
        if not count_dt:
            # EF03: Ngày nhập không tồn tại hoặc sai định dạng
            raise ValidationError({
                "count_to_date": "Ngày kiểm kê không hợp lệ.",
                "count_date": "Ngày kiểm kê không hợp lệ.",
                "detail": "Ngày kiểm kê không hợp lệ.",
            })
    else:
        # AF03: Tự động đề xuất theo ngày làm việc hiện tại
        count_dt = timezone.localdate()

    # EF04 & BR04: Kiểm kê đến ngày lớn hơn ngày hiện tại
    current_dt = _parse_date(payload.get("current_date")) or timezone.localdate()
    if count_dt > current_dt:
        raise ValidationError({
            "count_to_date": "Ngày kiểm kê không được lớn hơn ngày hiện tại.",
            "count_date": "Ngày kiểm kê không được lớn hơn ngày hiện tại.",
            "detail": "Ngày kiểm kê không được lớn hơn ngày hiện tại.",
        })

    # EF05: Ngày kiểm kê không thuộc phạm vi dữ liệu CCDC hoặc doanh nghiệp được phép xử lý
    min_managed_dt = _parse_date(payload.get("min_managed_date")) or date(1990, 1, 1)
    max_managed_dt = _parse_date(payload.get("max_managed_date"))
    if (
        str(payload.get("out_of_scope_date", "false")).lower() in ("true", "1")
        or (hasattr(request, "query_params") and str(request.query_params.get("out_of_scope_date", "false")).lower() in ("true", "1"))
        or count_dt < min_managed_dt
        or (max_managed_dt and count_dt > max_managed_dt)
    ):
        raise ValidationError({
            "count_to_date": "Ngày kiểm kê không thuộc phạm vi dữ liệu được quản lý.",
            "count_date": "Ngày kiểm kê không thuộc phạm vi dữ liệu được quản lý.",
            "detail": "Ngày kiểm kê không thuộc phạm vi dữ liệu được quản lý.",
        })

    return count_dt


def get_next_tool_stocktake_voucher_no_uc15(company, prefix: str = "BBKK") -> str:
    """
    Main Flow Step 9 & BR07: Tự động đề xuất Số biên bản tiếp theo theo quy tắc đánh số
    của doanh nghiệp (mặc định BBKK00001).
    """
    clean_prefix = (prefix or "BBKK").strip().upper()
    existing_numbers = list(
        models.AssetCount.objects.filter(
            company=company,
            number__istartswith=clean_prefix,
        ).values_list("number", flat=True)
    )
    max_seq = 0
    pattern = re.compile(rf"^{re.escape(clean_prefix)}[-/]?(\d+)$", re.IGNORECASE)
    for num in existing_numbers:
        m = pattern.match(str(num or "").strip())
        if m:
            seq = int(m.group(1))
            if seq > max_seq:
                max_seq = seq
    next_seq = max_seq + 1
    while True:
        candidate = f"{clean_prefix}{next_seq:05d}"
        if not models.AssetCount.objects.filter(company=company, number__iexact=candidate).exists():
            return candidate
        next_seq += 1


def _reconstruct_tool_book_quantities_at_date_uc15(tool: models.AssetRecord, count_to_date: date, row_or_payload: dict | None = None) -> list[dict]:
    """
    Main Flow Steps 7, 13, AF04, BR05, BR06, BR35, Formula 4.1, EF17, EF18:
    Reconstructs book quantities of `tool` by department (`Đơn vị sử dụng`) as of the end of `count_to_date`:
        SL sổ sách = SL đầu kỳ + SL ghi tăng + SL điều chuyển đến - SL điều chuyển đi - SL ghi giảm
    Transactions recorded AFTER `count_to_date` are excluded from the book snapshot at `count_to_date`.
    Tools that are 100% allocated (`remaining_value == 0`) but still in use (`book_quantity > 0`) are included per BR35.
    """
    ctx = row_or_payload if isinstance(row_or_payload, dict) else {}
    meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
    if not isinstance(meta, dict):
        meta = {}

    # EF17: Không thể xác định số lượng của CCDC tại ngày kiểm kê
    if (
        bool(meta.get("cannot_determine_book_qty", False))
        or bool(meta.get("book_quantity_undetermined", False))
        or bool(ctx.get("cannot_determine_book_qty", False))
        or bool(ctx.get("simulate_undetermined_book_qty", False))
    ):
        raise ValidationError({
            "lines": f"Không thể xác định số lượng sổ sách của {tool.code} tại ngày kiểm kê.",
            "detail": f"Không thể xác định số lượng sổ sách của {tool.code} tại ngày kiểm kê.",
        })

    # EF18: Dữ liệu ghi tăng, điều chuyển hoặc ghi giảm chưa nhất quán khiến số lượng sổ sách âm hoặc sai lệch bất thường
    if (
        bool(meta.get("inconsistent_book_history", False))
        or bool(meta.get("invalid_book_quantity", False))
        or bool(ctx.get("inconsistent_book_history", False))
        or bool(ctx.get("simulate_invalid_book_qty", False))
    ):
        raise ValidationError({
            "lines": f"Số lượng sổ sách của {tool.code} không hợp lệ. Vui lòng kiểm tra lịch sử CCDC.",
            "detail": f"Số lượng sổ sách của {tool.code} không hợp lệ. Vui lòng kiểm tra lịch sử CCDC.",
        })

    acq_date = tool.acquisition_date or tool.in_service_date
    if acq_date and acq_date > count_to_date:
        return []

    if tool.status == models.AssetStatus.DRAFT:
        return []

    # Check if there are any POSTED transactions (TRANSFER / DISPOSAL) AFTER count_to_date
    future_txs = list(
        models.AssetTransaction.objects.filter(
            asset=tool,
            status=models.TransactionStatus.POSTED,
            transaction_date__gt=count_to_date,
            transaction_type__in=(models.TransactionType.TRANSFER, models.TransactionType.DISPOSAL),
        )
        .select_related("target_department")
        .order_by("transaction_date", "created_at")
    )

    if future_txs:
        # The first transaction after count_to_date holds before_snapshot["components"] at the end of count_to_date
        first_future = future_txs[0]
        b_snap = first_future.before_snapshot if isinstance(first_future.before_snapshot, dict) else {}
        snap_comps = b_snap.get("components")
        if isinstance(snap_comps, list) and snap_comps:
            breakdown = []
            for sc in snap_comps:
                if not isinstance(sc, dict):
                    continue
                q_val = _parse_decimal(sc.get("quantity"), default=Decimal("0"))
                if q_val is None:
                    raise ValidationError({
                        "lines": f"Không thể xác định số lượng sổ sách của {tool.code} tại ngày kiểm kê.",
                        "detail": f"Không thể xác định số lượng sổ sách của {tool.code} tại ngày kiểm kê.",
                    })
                if q_val < Decimal("0"):
                    raise ValidationError({
                        "lines": f"Số lượng sổ sách của {tool.code} không hợp lệ. Vui lòng kiểm tra lịch sử CCDC.",
                        "detail": f"Số lượng sổ sách của {tool.code} không hợp lệ. Vui lòng kiểm tra lịch sử CCDC.",
                    })
                if q_val > Decimal("0"):
                    breakdown.append({
                        "department_id": str(sc.get("department_id") or ""),
                        "department_code": str(sc.get("department_code") or "").strip(),
                        "department_name": str(sc.get("department_name") or "").strip(),
                        "quantity": q_val,
                    })
            return breakdown

        # Fallback if legacy future transaction did not have before_snapshot["components"]:
        cur_breakdown = _get_tool_department_breakdown_uc13(tool)
        dept_qty_map: dict[str, dict] = {}
        for cb in cur_breakdown:
            k = (cb["department_code"] or cb["department_name"]).upper()
            dept_qty_map[k] = dict(cb)

        for ftx in reversed(future_txs):
            q_tx = _parse_decimal(ftx.quantity, default=Decimal("0")) or Decimal("0")
            if ftx.transaction_type == models.TransactionType.DISPOSAL:
                t_dept = ftx.target_department or tool.department
                d_code = t_dept.code if t_dept else "DEFAULT"
                d_name = t_dept.name if t_dept else "Bộ phận sử dụng"
                d_id = str(t_dept.id) if t_dept else ""
                k = d_code.upper()
                if k in dept_qty_map:
                    dept_qty_map[k]["quantity"] += q_tx
                else:
                    dept_qty_map[k] = {
                        "department_id": d_id,
                        "department_code": d_code,
                        "department_name": d_name,
                        "quantity": q_tx,
                    }
        return [v for v in dept_qty_map.values() if v["quantity"] > Decimal("0")]

    # No transactions after count_to_date: check if already disposed on/before count_to_date
    if tool.status == models.AssetStatus.DISPOSED and (not tool.disposed_at or tool.disposed_at <= count_to_date):
        return []
    if str(meta.get("physical_status") or "").upper() == "DISPOSED":
        last_disp_dt = _parse_date(meta.get("last_disposal_date"))
        if not last_disp_dt or last_disp_dt <= count_to_date:
            return []

    raw_comps = tool.components if isinstance(tool.components, list) else []
    for rc in raw_comps:
        if isinstance(rc, dict):
            rq = _parse_decimal(rc.get("quantity") if "quantity" in rc else rc.get("qty"), default=Decimal("0"))
            if rq is not None and rq < Decimal("0"):
                raise ValidationError({
                    "lines": f"Số lượng sổ sách của {tool.code} không hợp lệ. Vui lòng kiểm tra lịch sử CCDC.",
                    "detail": f"Số lượng sổ sách của {tool.code} không hợp lệ. Vui lòng kiểm tra lịch sử CCDC.",
                })

    if meta.get("in_use_quantity") is not None:
        in_use_q = _parse_decimal(meta.get("in_use_quantity"), default=None)
        if in_use_q is not None and in_use_q < Decimal("0"):
            raise ValidationError({
                "lines": f"Số lượng sổ sách của {tool.code} không hợp lệ. Vui lòng kiểm tra lịch sử CCDC.",
                "detail": f"Số lượng sổ sách của {tool.code} không hợp lệ. Vui lòng kiểm tra lịch sử CCDC.",
            })
        if in_use_q is not None and in_use_q == Decimal("0"):
            return []

    return _get_tool_department_breakdown_uc13(tool)


def validate_tool_stocktake_date_uc15(request, data=None) -> dict:
    """
    UC-FA-15 Main Flow Steps 4–9, AF03, AF04, EF01–EF05, BR01, BR03–BR07:
    Validates 'Kiểm kê đến ngày' on the Hộp thoại Kiểm kê CCDC and prepares initial metadata
    (proposed Số biên bản BBKK00001, formatted count_to_date) to open the form.
    """
    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc15(request, payload)
    _check_uc15_permission_and_scope(request, company, payload)

    count_dt = _validate_uc15_count_to_date(payload, company, request=request, require_explicit=bool(payload.get("require_explicit_date", False)))
    prefix = str(payload.get("prefix") or "BBKK").strip() or "BBKK"
    voucher_no = get_next_tool_stocktake_voucher_no_uc15(company, prefix=prefix)

    return {
        "valid": True,
        "company_id": str(company.id),
        "voucher_no": voucher_no,
        "number": voucher_no,
        "count_to_date": count_dt.strftime("%d/%m/%Y"),
        "count_to_date_iso": count_dt.isoformat(),
        "count_date": count_dt.strftime("%d/%m/%Y"),
        "count_date_iso": count_dt.isoformat(),
        "default_tab": "detail",
        "valid_committee_roles": list(UC15_VALID_COMMITTEE_ROLES),
    }


def get_in_use_tools_for_stocktake_uc15(request, data=None) -> dict:
    """
    UC-FA-15 Main Flow Steps 11–13, AF04, AF05, AF06, EF01–EF05, EF17–EF21, BR05, BR06, BR10, BR11, BR35:
    Retrieves all CCDC currently tracked in use as of `count_to_date` across the company
    (or filtered by department/keyword).
    Note per BR11: `actual_quantity` is returned as `None` (`""`) until entered/confirmed by the user;
    `book_quantity` is NEVER pre-marked as already counted.
    """
    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc15(request, payload)
    _check_uc15_permission_and_scope(request, company, payload)

    count_dt = _validate_uc15_count_to_date(payload, company, request=request)

    # EF19: Không thể tải danh sách CCDC
    if (
        str(payload.get("simulate_load_error", "false")).lower() in ("true", "1")
        or (hasattr(request, "query_params") and str(request.query_params.get("simulate_load_error", "false")).lower() in ("true", "1"))
    ):
        raise ValidationError({
            "detail": "Không thể tải danh sách CCDC đang dùng. Vui lòng thử lại.",
        })

    # EF21: Thay đổi Kiểm kê đến ngày làm thay đổi số lượng sổ sách đã tải
    prev_date_raw = payload.get("previous_count_to_date") or payload.get("loaded_count_to_date")
    confirm_date_change = str(payload.get("confirm_date_change_reload", "false")).lower() in ("true", "1")
    if prev_date_raw and not confirm_date_change:
        prev_dt = _parse_date(prev_date_raw)
        if prev_dt and prev_dt != count_dt:
            raise ValidationError({
                "count_to_date": "Ngày kiểm kê đã thay đổi. Vui lòng xác nhận tải lại dữ liệu và đối chiếu lại kết quả kiểm kê.",
                "detail": "Ngày kiểm kê đã thay đổi. Vui lòng xác nhận tải lại dữ liệu và đối chiếu lại kết quả kiểm kê.",
                "requires_reload_confirmation": "true",
            })

    # EF20 & AF06: Lấy toàn bộ CCDC đang dùng khi bảng đã có dữ liệu kiểm kê
    existing_rows = payload.get("existing_rows") if isinstance(payload.get("existing_rows"), list) else []
    has_counted_data = bool(payload.get("has_existing_counted_data", False)) or any(
        isinstance(r, dict)
        and (r.get("code") or r.get("asset_code") or r.get("asset_id"))
        and r.get("actual_quantity") is not None
        and str(r.get("actual_quantity")).strip() != ""
        for r in existing_rows
    )
    confirm_overwrite = str(payload.get("confirm_overwrite", "false")).lower() in ("true", "1")
    merge_existing = str(payload.get("merge_existing", "false")).lower() in ("true", "1")
    if has_counted_data and not confirm_overwrite and not merge_existing:
        raise ValidationError({
            "existing_rows": "Danh sách đã có dữ liệu kiểm kê. Bạn có muốn tải lại dữ liệu không?",
            "detail": "Danh sách đã có dữ liệu kiểm kê. Bạn có muốn tải lại dữ liệu không?",
        })

    dept_filter = str(
        payload.get("department_id")
        or payload.get("department")
        or (request.query_params.get("department") if hasattr(request, "query_params") else "")
        or ""
    ).strip()
    search_kw = str(
        payload.get("search")
        or (request.query_params.get("search") if hasattr(request, "query_params") else "")
        or ""
    ).strip().lower()

    tools_qs = (
        models.AssetRecord.objects.filter(
            company=company,
            asset_type=models.AssetType.TOOL,
        )
        .exclude(source_module="PREPAID_EXPENSE")
        .select_related("department", "category")
        .order_by("code")
    )

    existing_map: dict[tuple[str, str], dict] = {}
    if merge_existing:
        for er in existing_rows:
            if isinstance(er, dict) and (er.get("code") or er.get("asset_code")):
                c_key = str(er.get("code") or er.get("asset_code")).strip().upper()
                d_key = str(er.get("department_code") or er.get("dept") or er.get("department_name") or "").strip().upper()
                existing_map[(c_key, d_key)] = er

    items = []
    for tool in tools_qs:
        if search_kw and search_kw not in tool.code.lower() and search_kw not in tool.name.lower():
            continue

        breakdown = _reconstruct_tool_book_quantities_at_date_uc15(tool, count_dt, payload)
        if not breakdown:
            continue

        meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
        unit = str(meta.get("unit") or "Cái").strip() if isinstance(meta, dict) else "Cái"

        for b in breakdown:
            if dept_filter:
                df_low = dept_filter.lower()
                if (
                    df_low != str(b["department_id"]).lower()
                    and df_low != str(b["department_code"]).lower()
                    and df_low != str(b["department_name"]).lower()
                ):
                    continue

            q_book = b["quantity"]
            q_book_str = str(int(q_book)) if q_book == int(q_book) else str(q_book.normalize())
            c_key = tool.code.upper()
            d_code_key = b["department_code"].upper()
            d_name_key = b["department_name"].upper()

            preserved = existing_map.get((c_key, d_code_key)) or existing_map.get((c_key, d_name_key))
            if preserved and preserved.get("actual_quantity") is not None and str(preserved.get("actual_quantity")).strip() != "":
                act_q_dec = _parse_decimal(preserved.get("actual_quantity"), default=q_book) or Decimal("0")
                act_q_str = str(int(act_q_dec)) if act_q_dec == int(act_q_dec) else str(act_q_dec.normalize())
                diff_dec = act_q_dec - q_book
                exc_dec = max(diff_dec, Decimal("0"))
                sho_dec = max(-diff_dec, Decimal("0"))
                sol_str = str(preserved.get("solution") or preserved.get("recommendation") or (
                    "Khớp sổ sách" if diff_dec == Decimal("0") else ("Ghi tăng CCDC thừa" if exc_dec > Decimal("0") else "Lập chứng từ ghi giảm")
                )).strip()
                confirmed = True
            else:
                act_q_str = None
                exc_dec = Decimal("0")
                sho_dec = Decimal("0")
                sol_str = ""
                confirmed = False

            items.append({
                "line_no": len(items) + 1,
                "asset_id": str(tool.id),
                "tool_id": str(tool.id),
                "code": tool.code,
                "name": tool.name,
                "unit": unit,
                "is_discrete_unit": _is_discrete_unit_uc13(unit),
                "department_id": b["department_id"],
                "department_code": b["department_code"],
                "department_name": b["department_name"],
                "book_quantity": q_book_str,
                "expected_book_quantity": q_book_str,
                "actual_quantity": act_q_str,
                "counted_confirmed": confirmed,
                "excess_quantity": str(int(exc_dec)) if exc_dec == int(exc_dec) else str(exc_dec.normalize()),
                "shortage_quantity": str(int(sho_dec)) if sho_dec == int(sho_dec) else str(sho_dec.normalize()),
                "solution": sol_str,
                "recommendation": sol_str,
                "remaining_value": str(tool.remaining_value.quantize(Decimal("0.01"))),
                "is_fully_allocated_in_use": tool.remaining_value <= Decimal("0"),
            })

    voucher_no = get_next_tool_stocktake_voucher_no_uc15(company)
    return {
        "company_id": str(company.id),
        "voucher_no": voucher_no,
        "count_to_date": count_dt.strftime("%d/%m/%Y"),
        "count_to_date_iso": count_dt.isoformat(),
        "count": len(items),
        "items": items,
    }


def _validate_uc15_committee(raw_committee, single_chair_required: bool = True) -> list[dict]:
    """
    Main Flow Steps 21–23, AF14, AF15, BR30–BR32, EF22–EF25:
    Validates the stocktake committee (`Ban kiểm kê`).
    """
    if not isinstance(raw_committee, list) or len(raw_committee) == 0:
        raise ValidationError({
            "committee": "Vui lòng nhập thông tin Ban kiểm kê.",
            "detail": "Vui lòng nhập thông tin Ban kiểm kê.",
        })

    non_empty_rows = []
    for idx, m in enumerate(raw_committee, start=1):
        if not isinstance(m, dict):
            continue
        name_val = str(m.get("name") or m.get("full_name") or "").strip()
        title_val = str(m.get("title") or m.get("position") or "").strip()
        dept_val = str(m.get("department") or m.get("dept") or m.get("represent") or m.get("representation") or "").strip()
        role_val = str(m.get("role") or "").strip()
        if not name_val and not title_val and not dept_val and not role_val:
            continue
        non_empty_rows.append((idx, name_val, title_val, dept_val, role_val))

    if not non_empty_rows:
        raise ValidationError({
            "committee": "Vui lòng nhập thông tin Ban kiểm kê.",
            "detail": "Vui lòng nhập thông tin Ban kiểm kê.",
        })

    validated_members = []
    chair_count = 0

    for stt, name_val, title_val, dept_val, role_val in non_empty_rows:
        # EF23: Dòng thành viên thiếu Họ và tên
        if not name_val:
            raise ValidationError({
                "committee": f"Vui lòng nhập họ và tên thành viên tại dòng {stt}.",
                "detail": f"Vui lòng nhập họ và tên thành viên tại dòng {stt}.",
            })

        # EF24: Vai trò trong Ban kiểm kê chưa được xác định hoặc không hợp lệ
        if not role_val or role_val not in UC15_VALID_COMMITTEE_ROLES:
            raise ValidationError({
                "committee": f"Vui lòng chọn vai trò trong Ban kiểm kê tại dòng {stt}.",
                "detail": f"Vui lòng chọn vai trò trong Ban kiểm kê tại dòng {stt}.",
            })

        if role_val == "Trưởng ban":
            chair_count += 1

        validated_members.append({
            "stt": len(validated_members) + 1,
            "name": name_val,
            "title": title_val,
            "department": dept_val,
            "role": role_val,
        })

    # EF25 & BR31: Không có Trưởng ban hoặc có nhiều Trưởng ban khi doanh nghiệp quy định chỉ một người
    if chair_count == 0 or (single_chair_required and chair_count > 1):
        raise ValidationError({
            "committee": "Ban kiểm kê phải có một Trưởng ban hợp lệ.",
            "detail": "Ban kiểm kê phải có một Trưởng ban hợp lệ.",
        })

    return validated_members


def _validate_uc15_attachments(raw_attachments) -> list[dict]:
    """
    Main Flow Step 24, AF16, EF28, Section 5.8:
    Validates attachments (max 5MB, valid file name & extension).
    """
    if not raw_attachments:
        return []
    if not isinstance(raw_attachments, list):
        raise ValidationError({
            "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
        })

    max_bytes = 5 * 1024 * 1024
    disallowed_exts = (".exe", ".bat", ".cmd", ".sh", ".msi", ".vbs", ".js")
    validated = []
    for att in raw_attachments:
        if not isinstance(att, dict):
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            })
        f_name = str(att.get("name") or att.get("file_name") or att.get("filename") or "").strip()
        f_size = att.get("size") if "size" in att else att.get("file_size", 0)
        try:
            f_size_int = int(f_size or 0)
        except (ValueError, TypeError):
            f_size_int = -1
        if (
            not f_name
            or f_size_int < 0
            or f_size_int > max_bytes
            or bool(att.get("invalid_format", False))
            or any(f_name.lower().endswith(ext) for ext in disallowed_exts)
        ):
            raise ValidationError({
                "attachments": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
                "detail": "Tệp đính kèm không hợp lệ hoặc vượt dung lượng tối đa 5MB.",
            })
        validated.append({
            "name": f_name,
            "size": f_size_int,
            "content_type": str(att.get("content_type") or att.get("mime_type") or "application/octet-stream"),
            "url": str(att.get("url") or ""),
        })
    return validated


def _propose_uc15_solution_text(excess_qty: Decimal, shortage_qty: Decimal) -> str:
    """
    Main Flow Step 17, AF07, AF08, AF09, BR21:
    - SL thực tế == SL sổ sách -> "Khớp sổ sách"
    - SL thực tế > SL sổ sách  -> "Ghi tăng CCDC thừa"
    - SL thực tế < SL sổ sách  -> "Lập chứng từ ghi giảm"
    """
    if excess_qty > Decimal("0"):
        return "Ghi tăng CCDC thừa"
    if shortage_qty > Decimal("0"):
        return "Lập chứng từ ghi giảm"
    return "Khớp sổ sách"


def serialize_tool_stocktake_voucher_uc15(instance: models.AssetCount) -> dict:
    """
    Serializes a saved UC-FA-15 CCDC stocktake voucher (`AssetCount`) with full detail lines,
    committee, discrepancy tracking, and summary metrics.
    """
    meta = instance.committee if isinstance(instance.committee, dict) else {}
    members = meta.get("members") if isinstance(meta.get("members"), list) else (
        instance.committee if isinstance(instance.committee, list) else []
    )
    saved_lines = meta.get("lines") if isinstance(meta.get("lines"), list) else []
    if not saved_lines:
        for idx, ln in enumerate(instance.lines.select_related("asset", "asset__department").all(), start=1):
            b_q = ln.book_quantity or Decimal("0")
            a_q = ln.actual_quantity or Decimal("0")
            diff = a_q - b_q
            exc = max(diff, Decimal("0"))
            sho = max(-diff, Decimal("0"))
            saved_lines.append({
                "line_no": idx,
                "id": str(ln.id),
                "asset_id": str(ln.asset_id),
                "code": ln.asset.code,
                "name": ln.asset.name,
                "department_name": ln.condition or (ln.asset.department.name if ln.asset.department else ""),
                "book_quantity": str(int(b_q)) if b_q == int(b_q) else str(b_q.normalize()),
                "actual_quantity": str(int(a_q)) if a_q == int(a_q) else str(a_q.normalize()),
                "difference": str(int(diff)) if diff == int(diff) else str(diff.normalize()),
                "excess_quantity": str(int(exc)) if exc == int(exc) else str(exc.normalize()),
                "shortage_quantity": str(int(sho)) if sho == int(sho) else str(sho.normalize()),
                "solution": ln.recommendation or _propose_uc15_solution_text(exc, sho),
                "recommendation": ln.recommendation or _propose_uc15_solution_text(exc, sho),
                "discrepancy_status": "NO_DISCREPANCY" if diff == Decimal("0") else "PENDING_VERIFICATION",
            })

    summary = meta.get("summary") if isinstance(meta.get("summary"), dict) else {}
    status_code = str(meta.get("status") or "COMPLETED")
    status_display = "Đã xử lý chênh lệch" if status_code == "DISCREPANCY_RESOLVED" else "Đã hoàn thành"
    count_to_date_str = instance.count_date.strftime("%d/%m/%Y") if instance.count_date else ""

    return {
        "id": str(instance.id),
        "company": str(instance.company_id),
        "company_id": str(instance.company_id),
        "asset_type": "TOOL",
        "voucher_no": instance.number,
        "number": instance.number,
        "count_to_date": count_to_date_str,
        "count_to_date_iso": instance.count_date.isoformat() if instance.count_date else "",
        "count_date": count_to_date_str,
        "count_date_iso": instance.count_date.isoformat() if instance.count_date else "",
        "purpose": instance.purpose or "",
        "conclusion": instance.conclusion or "",
        "status": status_code,
        "status_display": status_display,
        "discrepancy_status": str(meta.get("discrepancy_status") or "NO_DISCREPANCY"),
        "discrepancy_status_display": str(meta.get("discrepancy_status_display") or "Không có chênh lệch"),
        "lines": saved_lines,
        "committee": members,
        "attachments": meta.get("attachments") if isinstance(meta.get("attachments"), list) else [],
        "linked_vouchers": meta.get("linked_vouchers") if isinstance(meta.get("linked_vouchers"), list) else [],
        "summary": summary,
        "total_book_quantity": summary.get("total_book_quantity", "0"),
        "total_actual_quantity": summary.get("total_actual_quantity", "0"),
        "total_excess_quantity": summary.get("total_excess_quantity", "0"),
        "total_shortage_quantity": summary.get("total_shortage_quantity", "0"),
        "net_difference": summary.get("net_difference", "0"),
        "created_at": instance.created_at.isoformat() if instance.created_at else "",
    }


def save_tool_stocktake_uc15(request, data=None, instance: models.AssetCount | None = None) -> dict:
    """
    UC-FA-15 Main Flow Steps 14–33, AF07–AF19, EF01–EF18, EF21–EF32, EF35,
    BR01–BR36, BR40–BR42, Section 4.1–4.7:
    Validates and saves a CCDC stocktake voucher (`Biên bản kiểm kê công cụ dụng cụ`).
    Strictly preserves `AssetRecord` book quantities, original cost, allocated value,
    remaining value, and GL entries (`Step 31, BR02, BR33, BR34`).
    """
    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc15(request, payload)
    _check_uc15_permission_and_scope(request, company, payload)

    # EF30: Idempotency check on duplicate submit
    idem_key = str(payload.get("idempotency_key") or payload.get("request_id") or "").strip()
    cache_key = (str(company.id), idem_key) if idem_key else None
    if cache_key and cache_key in _UC15_IDEMPOTENCY_STORE:
        cached = dict(_UC15_IDEMPOTENCY_STORE[cache_key])
        cached["idempotent_replayed"] = True
        return cached

    # EF35 & BR40: Check if updating an existing stocktake voucher that already has dependent resolution vouchers
    if instance is not None:
        inst_meta = instance.committee if isinstance(instance.committee, dict) else {}
        linked_vouchers = inst_meta.get("linked_vouchers") if isinstance(inst_meta.get("linked_vouchers"), list) else []
        has_dependent = (
            bool(payload.get("has_dependent_vouchers", False))
            or len(linked_vouchers) > 0
            or inst_meta.get("status") == "DISCREPANCY_RESOLVED"
            or models.AssetTransaction.objects.filter(
                company=company,
                status=models.TransactionStatus.POSTED,
                source_reference__iexact=instance.number,
            ).exists()
        )
        if has_dependent:
            raise ValidationError({
                "detail": "Không thể sửa hoặc hủy biên bản khi đã có chứng từ xử lý chênh lệch liên quan.",
            })

    # EF21: Check if count_to_date changed since book quantities were loaded without reload confirmation
    prev_date_raw = payload.get("previous_count_to_date") or payload.get("loaded_count_to_date")
    confirm_date_change = str(payload.get("confirm_date_change_reload", "false")).lower() in ("true", "1")
    count_dt = _validate_uc15_count_to_date(payload, company, request=request, require_explicit=True)
    if prev_date_raw and not confirm_date_change:
        prev_dt = _parse_date(prev_date_raw)
        if prev_dt and prev_dt != count_dt:
            raise ValidationError({
                "count_to_date": "Ngày kiểm kê đã thay đổi. Vui lòng xác nhận tải lại dữ liệu và đối chiếu lại kết quả kiểm kê.",
                "detail": "Ngày kiểm kê đã thay đổi. Vui lòng xác nhận tải lại dữ liệu và đối chiếu lại kết quả kiểm kê.",
            })

    # EF06 & BR08: Mục đích kiểm kê để trống
    purpose = str(payload.get("purpose") or payload.get("description") or "").strip()
    if not purpose:
        raise ValidationError({
            "purpose": "Vui lòng nhập mục đích kiểm kê.",
            "detail": "Vui lòng nhập mục đích kiểm kê.",
        })

    # EF07 & BR07: Số biên bản để trống
    has_no_key = any(k in payload for k in ("voucher_no", "number", "document_number"))
    raw_voucher_no = payload.get("voucher_no") if "voucher_no" in payload else (
        payload.get("number") if "number" in payload else payload.get("document_number")
    )
    if has_no_key:
        voucher_no = str(raw_voucher_no or "").strip()
        if not voucher_no:
            raise ValidationError({
                "voucher_no": "Vui lòng nhập số biên bản kiểm kê.",
                "number": "Vui lòng nhập số biên bản kiểm kê.",
                "detail": "Vui lòng nhập số biên bản kiểm kê.",
            })
    elif instance is not None:
        voucher_no = instance.number
    else:
        voucher_no = get_next_tool_stocktake_voucher_no_uc15(company)

    # EF08 & BR07: Số biên bản đã tồn tại trong phạm vi đánh số
    dup_qs = models.AssetCount.objects.filter(company=company, number__iexact=voucher_no)
    if instance is not None:
        dup_qs = dup_qs.exclude(pk=instance.pk)
    if dup_qs.exists():
        raise ValidationError({
            "voucher_no": "Số biên bản kiểm kê đã tồn tại. Vui lòng sử dụng số khác.",
            "number": "Số biên bản kiểm kê đã tồn tại. Vui lòng sử dụng số khác.",
            "detail": "Số biên bản kiểm kê đã tồn tại. Vui lòng sử dụng số khác.",
        })

    # EF29: Dữ liệu sổ sách đã thay đổi so với thời điểm tải
    if (
        str(payload.get("source_data_stale", "false")).lower() in ("true", "1")
        or str(payload.get("simulate_concurrent_change", "false")).lower() in ("true", "1")
    ):
        raise ValidationError({
            "detail": "Dữ liệu sổ sách đã thay đổi. Vui lòng tải lại và kiểm tra kết quả kiểm kê.",
        })

    # EF09 & BR09: Không có dòng CCDC hợp lệ trong phạm vi kiểm kê
    raw_lines = payload.get("lines") if "lines" in payload else payload.get("rows")
    if not isinstance(raw_lines, list) or len(raw_lines) == 0:
        raise ValidationError({
            "lines": "Vui lòng chọn ít nhất một CCDC cần kiểm kê.",
            "detail": "Vui lòng chọn ít nhất một CCDC cần kiểm kê.",
        })

    non_empty_lines = [
        r for r in raw_lines
        if isinstance(r, dict)
        and (
            r.get("asset")
            or r.get("asset_id")
            or r.get("tool_id")
            or r.get("code")
            or r.get("asset_code")
            or r.get("temp_code")
            or r.get("is_unlisted_surplus")
            or r.get("actual_quantity") is not None
        )
    ]
    if not non_empty_lines:
        raise ValidationError({
            "lines": "Vui lòng chọn ít nhất một CCDC cần kiểm kê.",
            "detail": "Vui lòng chọn ít nhất một CCDC cần kiểm kê.",
        })

    seen_scope_keys: set[tuple[str, str, str]] = set()
    parsed_lines = []

    total_book_qty = Decimal("0")
    total_actual_qty = Decimal("0")
    total_excess_qty = Decimal("0")
    total_shortage_qty = Decimal("0")

    for idx, line in enumerate(non_empty_lines, start=1):
        # Support unlisted surplus CCDC discovered physically (Section 9: CCDC thừa chưa có mã)
        is_unlisted = bool(line.get("is_unlisted_surplus", False))
        if is_unlisted:
            temp_code = str(line.get("temp_code") or line.get("code") or f"CCDC-THUA-{idx:03d}").strip()
            temp_name = str(line.get("name") or line.get("asset_name") or "CCDC phát hiện thừa chờ xác minh").strip()
            dept_name = str(line.get("department_name") or line.get("dept") or "").strip()
            dept_code = str(line.get("department_code") or dept_name or "DEFAULT").strip()
            raw_act = line.get("actual_quantity") if "actual_quantity" in line else line.get("actualQty")
            if raw_act is None or str(raw_act).strip() == "":
                raise ValidationError({
                    "lines": f"Vui lòng nhập số lượng thực tế của {temp_code}.",
                    "detail": f"Vui lòng nhập số lượng thực tế của {temp_code}.",
                })
            act_dec = _parse_decimal(raw_act, default=None)
            if act_dec is None:
                raise ValidationError({
                    "lines": f"Số lượng thực tế của {temp_code} không hợp lệ.",
                    "detail": f"Số lượng thực tế của {temp_code} không hợp lệ.",
                })
            if act_dec < Decimal("0"):
                raise ValidationError({
                    "lines": "Số lượng thực tế không được âm.",
                    "detail": "Số lượng thực tế không được âm.",
                })
            sol = str(line.get("solution") or line.get("recommendation") or "Ghi tăng CCDC thừa").strip()
            total_actual_qty += act_dec
            total_excess_qty += act_dec
            parsed_lines.append({
                "line_no": idx,
                "tool": None,
                "asset_id": "",
                "code": temp_code,
                "name": temp_name,
                "unit": str(line.get("unit") or "Cái"),
                "department_id": "",
                "department_code": dept_code,
                "department_name": dept_name,
                "lot_code": "",
                "book_quantity": Decimal("0"),
                "actual_quantity": act_dec,
                "difference": act_dec,
                "excess_quantity": act_dec,
                "shortage_quantity": Decimal("0"),
                "solution": sol,
                "discrepancy_status": "PENDING_VERIFICATION",
                "verification_note": str(line.get("verification_note") or "").strip(),
                "is_unlisted_surplus": True,
            })
            continue

        asset_id = str(line.get("asset") or line.get("asset_id") or line.get("tool_id") or "").strip()
        tool_code = str(line.get("code") or line.get("asset_code") or line.get("tool_code") or "").strip()
        if not asset_id and not tool_code:
            raise ValidationError({
                "lines": "Vui lòng chọn ít nhất một CCDC cần kiểm kê.",
                "detail": "Vui lòng chọn ít nhất một CCDC cần kiểm kê.",
            })

        tool = None
        if asset_id:
            try:
                uuid.UUID(asset_id)
                tool = models.AssetRecord.objects.select_related("department", "category").filter(pk=asset_id).first()
            except (ValueError, TypeError):
                tool = models.AssetRecord.objects.select_related("department", "category").filter(company=company, code__iexact=asset_id).first()
        if not tool and tool_code:
            tool = models.AssetRecord.objects.select_related("department", "category").filter(company=company, code__iexact=tool_code).first()
            if not tool:
                tool = models.AssetRecord.objects.select_related("department", "category").filter(code__iexact=tool_code).first()

        # EF10: CCDC không tồn tại hoặc không thuộc doanh nghiệp hiện tại
        if (
            not tool
            or str(tool.company_id) != str(company.id)
            or tool.asset_type != models.AssetType.TOOL
            or tool.source_module == "PREPAID_EXPENSE"
        ):
            raise ValidationError({
                "lines": "CCDC không tồn tại hoặc không thuộc doanh nghiệp đang làm việc.",
                "detail": "CCDC không tồn tại hoặc không thuộc doanh nghiệp đang làm việc.",
            })

        code_label = tool.code

        # EF17 & EF18: Reconstruct book quantities at count_to_date
        breakdown = _reconstruct_tool_book_quantities_at_date_uc15(tool, count_dt, line)

        # EF11: CCDC đã ghi giảm toàn bộ trước ngày kiểm kê và không thuộc phạm vi cần đối chiếu hiện vật
        if not breakdown:
            raise ValidationError({
                "lines": "CCDC không còn được theo dõi sử dụng tại ngày kiểm kê đã chọn.",
                "detail": "CCDC không còn được theo dõi sử dụng tại ngày kiểm kê đã chọn.",
            })

        # Match department for this line (BR06)
        req_dept_raw = str(
            line.get("department_id")
            or line.get("department_code")
            or line.get("department_name")
            or line.get("dept")
            or line.get("department")
            or ""
        ).strip()
        matched_dept = None
        if req_dept_raw:
            req_low = req_dept_raw.lower()
            for b in breakdown:
                if (
                    req_low == str(b["department_id"]).lower()
                    or req_low == str(b["department_code"]).lower()
                    or req_low == str(b["department_name"]).lower()
                ):
                    matched_dept = b
                    break
            if not matched_dept:
                # If tool is not tracked at the requested department on count_dt:
                raise ValidationError({
                    "lines": "CCDC không còn được theo dõi sử dụng tại ngày kiểm kê đã chọn.",
                    "detail": "CCDC không còn được theo dõi sử dụng tại ngày kiểm kê đã chọn.",
                })
        else:
            matched_dept = breakdown[0]

        dept_code = matched_dept["department_code"]
        dept_name = matched_dept["department_name"]
        dept_id = matched_dept["department_id"]
        lot_code = str(line.get("lot_code") or line.get("tracking_object") or "").strip().upper()
        book_qty = matched_dept["quantity"]

        # EF12 & BR20: Cùng CCDC, cùng đơn vị và cùng đối tượng theo dõi bị thêm trùng dòng
        scope_key = (str(tool.id), dept_code.upper(), lot_code)
        if scope_key in seen_scope_keys:
            raise ValidationError({
                "lines": "CCDC này đã có trong danh sách kiểm kê tại đơn vị sử dụng tương ứng.",
                "detail": "CCDC này đã có trong danh sách kiểm kê tại đơn vị sử dụng tương ứng.",
            })
        seen_scope_keys.add(scope_key)

        # EF29: Kiểm tra dữ liệu số lượng CCDC đã thay đổi so với thời điểm tải
        if line.get("expected_book_quantity") is not None and str(line.get("expected_book_quantity")).strip() != "":
            exp_book = _parse_decimal(line.get("expected_book_quantity"), default=None)
            if exp_book is None or exp_book != book_qty:
                raise ValidationError({
                    "lines": "Dữ liệu sổ sách đã thay đổi. Vui lòng tải lại và kiểm tra kết quả kiểm kê.",
                    "detail": "Dữ liệu sổ sách đã thay đổi. Vui lòng tải lại và kiểm tra kết quả kiểm kê.",
                })

        # EF13 & BR11 & BR12: SL thực tế chưa được nhập hoặc chưa xác nhận
        # Note: 0 or "0" is a valid counted result (AF10, BR12) and MUST be distinguished from None / "" / unconfirmed!
        has_act_key = any(k in line for k in ("actual_quantity", "actualQty", "counted_quantity"))
        raw_act = (
            line.get("actual_quantity")
            if "actual_quantity" in line
            else (line.get("actualQty") if "actualQty" in line else line.get("counted_quantity"))
        )
        unconfirmed = (
            str(line.get("counted_confirmed", "true")).lower() in ("false", "0")
            or str(line.get("unconfirmed", "false")).lower() in ("true", "1")
        )
        if not has_act_key or raw_act is None or str(raw_act).strip() == "" or unconfirmed:
            raise ValidationError({
                "actual_quantity": f"Vui lòng nhập số lượng thực tế của {code_label}.",
                "lines": f"Vui lòng nhập số lượng thực tế của {code_label}.",
                "detail": f"Vui lòng nhập số lượng thực tế của {code_label}.",
            })

        # EF15: Giá trị không phải số hợp lệ
        if isinstance(raw_act, bool):
            act_dec = None
        else:
            act_dec = _parse_decimal(raw_act, default=None)
        if act_dec is None:
            raise ValidationError({
                "actual_quantity": f"Số lượng thực tế của {code_label} không hợp lệ.",
                "lines": f"Số lượng thực tế của {code_label} không hợp lệ.",
                "detail": f"Số lượng thực tế của {code_label} không hợp lệ.",
            })

        # EF14 & BR13: SL thực tế nhỏ hơn 0
        if act_dec < Decimal("0"):
            raise ValidationError({
                "actual_quantity": "Số lượng thực tế không được âm.",
                "lines": "Số lượng thực tế không được âm.",
                "detail": "Số lượng thực tế không được âm.",
            })

        # EF16 & BR13: Số lượng không phù hợp đơn vị tính CCDC
        t_meta = (tool.accessories or [{}])[0] if isinstance(tool.accessories, list) and tool.accessories else {}
        unit = str((t_meta.get("unit") if isinstance(t_meta, dict) else None) or line.get("unit") or "Cái").strip()
        is_discrete = _is_discrete_unit_uc13(unit)
        if str(line.get("allow_decimal_unit") or "").lower() in ("true", "1"):
            is_discrete = False
        elif str(line.get("allow_decimal_unit") or "").lower() in ("false", "0"):
            is_discrete = True
        if is_discrete and act_dec != int(act_dec):
            raise ValidationError({
                "actual_quantity": "Số lượng kiểm kê không phù hợp với đơn vị tính CCDC.",
                "lines": "Số lượng kiểm kê không phù hợp với đơn vị tính CCDC.",
                "detail": "Số lượng kiểm kê không phù hợp với đơn vị tính CCDC.",
            })

        # Formula 4.2, 4.3, 4.4 & BR14–BR17: Calculate difference, excess (Thừa), shortage (Thiếu)
        diff_dec = act_dec - book_qty
        excess_dec = max(diff_dec, Decimal("0"))
        shortage_dec = max(-diff_dec, Decimal("0"))

        # Step 17–18, AF07–AF11, BR21–BR22, EF26, EF27: Xử lý chênh lệch
        has_sol_key = "solution" in line or "recommendation" in line
        raw_sol = line.get("solution") if "solution" in line else line.get("recommendation")
        sol_str = str(raw_sol or "").strip()

        if excess_dec > Decimal("0") or shortage_dec > Decimal("0"):
            # EF26: Có dòng Thừa/Thiếu nhưng chưa có nội dung đề xuất xử lý
            if (
                bool(line.get("require_explicit_solution", False)) and not sol_str
            ) or (has_sol_key and not sol_str and not bool(line.get("auto_propose_solution", False))):
                raise ValidationError({
                    "solution": f"Vui lòng nhập đề xuất xử lý chênh lệch của {code_label}.",
                    "lines": f"Vui lòng nhập đề xuất xử lý chênh lệch của {code_label}.",
                    "detail": f"Vui lòng nhập đề xuất xử lý chênh lệch của {code_label}.",
                })
            if not sol_str:
                sol_str = _propose_uc15_solution_text(excess_dec, shortage_dec)
        else:
            if not sol_str:
                sol_str = "Khớp sổ sách"

        # EF27: User ghi nội dung "Đã xử lý" nhưng chưa có chứng từ hoặc kết quả xử lý hợp lệ
        res_voucher_no = str(line.get("resolution_voucher_no") or line.get("linked_voucher_no") or "").strip()
        raw_disc_status = str(line.get("discrepancy_status") or "").strip().upper()
        if (
            (excess_dec > Decimal("0") or shortage_dec > Decimal("0"))
            and (
                sol_str.lower() in ("đã xử lý", "da xu ly", "đã xử lý chênh lệch")
                or raw_disc_status in ("RESOLVED", "PROCESSED", "ĐÃ XỬ LÝ", "ĐÃ XỬ LÝ CHÊNH LỆCH")
            )
            and not res_voucher_no
        ):
            raise ValidationError({
                "solution": "Chênh lệch chưa có căn cứ xác nhận đã xử lý.",
                "lines": "Chênh lệch chưa có căn cứ xác nhận đã xử lý.",
                "detail": "Chênh lệch chưa có căn cứ xác nhận đã xử lý.",
            })

        if excess_dec == Decimal("0") and shortage_dec == Decimal("0"):
            disc_status = "NO_DISCREPANCY"
            disc_status_display = "Không có chênh lệch"
        elif res_voucher_no:
            disc_status = "RESOLVED"
            disc_status_display = "Đã xử lý"
        elif bool(line.get("approved_for_resolution", False)):
            disc_status = "IN_PROGRESS"
            disc_status_display = "Đang xử lý"
        elif line.get("verification_note"):
            disc_status = "PENDING_APPROVAL"
            disc_status_display = "Chờ phê duyệt xử lý"
        else:
            disc_status = "PENDING_VERIFICATION"
            disc_status_display = "Chờ xác minh"

        total_book_qty += book_qty
        total_actual_qty += act_dec
        total_excess_qty += excess_dec
        total_shortage_qty += shortage_dec

        parsed_lines.append({
            "line_no": idx,
            "tool": tool,
            "asset_id": str(tool.id),
            "code": tool.code,
            "name": tool.name,
            "unit": unit,
            "department_id": dept_id,
            "department_code": dept_code,
            "department_name": dept_name,
            "lot_code": lot_code,
            "book_quantity": book_qty,
            "actual_quantity": act_dec,
            "difference": diff_dec,
            "excess_quantity": excess_dec,
            "shortage_quantity": shortage_dec,
            "solution": sol_str,
            "discrepancy_status": disc_status,
            "discrepancy_status_display": disc_status_display,
            "verification_note": str(line.get("verification_note") or "").strip(),
            "resolution_voucher_no": res_voucher_no,
            "is_unlisted_surplus": False,
        })

    # Validate Tab 2: Ban kiểm kê (EF22–EF25, BR30–BR32)
    single_chair = str(payload.get("single_chair_required", "true")).lower() not in ("false", "0")
    validated_committee = _validate_uc15_committee(payload.get("committee"), single_chair_required=single_chair)

    # Validate Attachments (EF28, AF16)
    validated_attachments = _validate_uc15_attachments(payload.get("attachments"))

    # EF31: Lỗi hệ thống khi lưu biên bản kiểm kê
    if (
        str(payload.get("simulate_save_error", "false")).lower() in ("true", "1")
        or str(payload.get("simulate_db_error", "false")).lower() in ("true", "1")
    ):
        raise ValidationError({
            "detail": "Lưu biên bản kiểm kê thất bại. Vui lòng thử lại.",
        })

    # Formula 4.5 & BR18, BR19: Totals
    net_diff = total_actual_qty - total_book_qty

    def _fmt_qty(val: Decimal) -> str:
        return str(int(val)) if val == int(val) else str(val.normalize())

    has_any_discrepancy = (total_excess_qty > Decimal("0")) or (total_shortage_qty > Decimal("0"))
    all_discrepancies_resolved = has_any_discrepancy and all(
        pl["discrepancy_status"] == "RESOLVED"
        for pl in parsed_lines
        if (pl["excess_quantity"] > Decimal("0") or pl["shortage_quantity"] > Decimal("0"))
    )

    if not has_any_discrepancy:
        overall_disc_status = "NO_DISCREPANCY"
        overall_disc_display = "Không có chênh lệch"
        voucher_status = "COMPLETED"
        voucher_status_display = "Đã hoàn thành"
    elif all_discrepancies_resolved:
        overall_disc_status = "RESOLVED"
        overall_disc_display = "Đã xử lý"
        voucher_status = "DISCREPANCY_RESOLVED"
        voucher_status_display = "Đã xử lý chênh lệch"
    else:
        overall_disc_status = "PENDING_VERIFICATION"
        overall_disc_display = "Chờ xác minh"
        voucher_status = "COMPLETED"
        voucher_status_display = "Đã hoàn thành"

    serialized_lines = []
    for pl in parsed_lines:
        serialized_lines.append({
            "line_no": pl["line_no"],
            "asset_id": pl["asset_id"],
            "code": pl["code"],
            "name": pl["name"],
            "unit": pl["unit"],
            "department_id": pl["department_id"],
            "department_code": pl["department_code"],
            "department_name": pl["department_name"],
            "lot_code": pl["lot_code"],
            "book_quantity": _fmt_qty(pl["book_quantity"]),
            "actual_quantity": _fmt_qty(pl["actual_quantity"]),
            "difference": _fmt_qty(pl["difference"]),
            "excess_quantity": _fmt_qty(pl["excess_quantity"]),
            "shortage_quantity": _fmt_qty(pl["shortage_quantity"]),
            "solution": pl["solution"],
            "recommendation": pl["solution"],
            "discrepancy_status": pl["discrepancy_status"],
            "discrepancy_status_display": pl.get("discrepancy_status_display", ""),
            "verification_note": pl["verification_note"],
            "resolution_voucher_no": pl.get("resolution_voucher_no", ""),
            "is_unlisted_surplus": pl["is_unlisted_surplus"],
        })

    summary_data = {
        "item_count": len(parsed_lines),
        "total_book_quantity": _fmt_qty(total_book_qty),
        "total_actual_quantity": _fmt_qty(total_actual_qty),
        "total_excess_quantity": _fmt_qty(total_excess_qty),
        "total_shortage_quantity": _fmt_qty(total_shortage_qty),
        "net_difference": _fmt_qty(net_diff),
        "has_discrepancy": has_any_discrepancy,
    }

    committee_payload = {
        "_uc15": True,
        "status": voucher_status,
        "status_display": voucher_status_display,
        "discrepancy_status": overall_disc_status,
        "discrepancy_status_display": overall_disc_display,
        "count_to_date": count_dt.isoformat(),
        "members": validated_committee,
        "lines": serialized_lines,
        "attachments": validated_attachments,
        "linked_vouchers": [],
        "summary": summary_data,
    }

    with transaction.atomic():
        if instance is not None:
            count_obj = instance
            count_obj.number = voucher_no
            count_obj.count_date = count_dt
            count_obj.purpose = purpose[:500]
            count_obj.conclusion = str(payload.get("conclusion") or "")
            count_obj.committee = committee_payload
            count_obj.save()
            count_obj.lines.all().delete()
        else:
            count_obj = models.AssetCount.objects.create(
                company=company,
                asset_type=models.AssetType.TOOL,
                number=voucher_no,
                count_date=count_dt,
                purpose=purpose[:500],
                conclusion=str(payload.get("conclusion") or ""),
                committee=committee_payload,
                created_by=actor(request),
            )

        # Save AssetCountLine rows per unique AssetRecord (consolidating if multi-dept of same AssetRecord)
        lines_by_asset: dict[str, dict] = {}
        for pl in parsed_lines:
            if not pl["tool"]:
                continue
            tid = str(pl["tool"].id)
            if tid not in lines_by_asset:
                lines_by_asset[tid] = {
                    "tool": pl["tool"],
                    "book_quantity": pl["book_quantity"],
                    "actual_quantity": pl["actual_quantity"],
                    "department_name": pl["department_name"],
                    "solution": pl["solution"],
                }
            else:
                lines_by_asset[tid]["book_quantity"] += pl["book_quantity"]
                lines_by_asset[tid]["actual_quantity"] += pl["actual_quantity"]

        for tid, l_spec in lines_by_asset.items():
            t_obj = l_spec["tool"]
            models.AssetCountLine.objects.create(
                count=count_obj,
                asset=t_obj,
                book_quantity=l_spec["book_quantity"],
                actual_quantity=l_spec["actual_quantity"],
                book_value=t_obj.remaining_value,
                condition=l_spec["department_name"][:255],
                recommendation=l_spec["solution"][:255],
                note=purpose[:500],
            )

        audit(
            request,
            count_obj,
            "SAVE_TOOL_STOCKTAKE_UC15",
            before=None,
            after={
                "voucher_no": voucher_no,
                "count_to_date": count_dt.isoformat(),
                "purpose": purpose,
                "status": voucher_status,
                "discrepancy_status": overall_disc_status,
                "summary": summary_data,
                "committee_count": len(validated_committee),
            },
            reason=purpose,
        )

    # AF17 & EF32: Cất và In
    print_on_save = bool(payload.get("print_on_save") or payload.get("print_after_save") or payload.get("print"))
    print_error = str(payload.get("simulate_print_error", "false")).lower() in ("true", "1")
    warning_msg = None
    if print_on_save and print_error:
        warning_msg = "Biên bản đã được lưu nhưng chưa thể tạo bản in."
        success_message = warning_msg
    else:
        success_message = f"Đã lưu biên bản kiểm kê CCDC {voucher_no} thành công."

    response_data = serialize_tool_stocktake_voucher_uc15(count_obj)
    response_data.update({
        "print_ready": print_on_save and not print_error,
        "print_data": {
            "title": "BIÊN BẢN KIỂM KÊ CÔNG CỤ DỤNG CỤ",
            "voucher_no": voucher_no,
            "count_to_date": count_dt.strftime("%d/%m/%Y"),
            "purpose": purpose,
            "committee": validated_committee,
            "lines": serialized_lines,
            "summary": summary_data,
        } if (print_on_save and not print_error) else None,
        "warning": warning_msg,
        "message": success_message,
        "idempotent_replayed": False,
    })
    if cache_key:
        _UC15_IDEMPOTENCY_STORE[cache_key] = dict(response_data)
    return response_data


def resolve_tool_stocktake_discrepancy_uc15(request, data=None) -> dict:
    """
    UC-FA-15 AF20, AF21, AF22, AF23, EF27, EF33, EF34, BR23–BR29, BR37–BR38, Section 6.2:
    Handles post-stocktake verification, approval, and discrepancy resolution (linking or creating
    increase / decrease / transfer vouchers). Transitions voucher status to 'Đã xử lý chênh lệch'
    only when all discrepancies on the voucher have been resolved (`AF23, BR37`).
    """
    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc15(request, payload)
    _check_uc15_permission_and_scope(request, company, payload)

    voucher_id = str(payload.get("id") or payload.get("count_id") or "").strip()
    voucher_no = str(payload.get("voucher_no") or payload.get("number") or "").strip()
    count_obj = None
    if voucher_id:
        try:
            uuid.UUID(voucher_id)
            count_obj = models.AssetCount.objects.filter(company=company, pk=voucher_id).first()
        except (ValueError, TypeError):
            pass
    if not count_obj and voucher_no:
        count_obj = models.AssetCount.objects.filter(company=company, number__iexact=voucher_no).first()
    if not count_obj:
        raise ValidationError({"voucher_no": "Không tìm thấy biên bản kiểm kê CCDC."})

    meta = count_obj.committee if isinstance(count_obj.committee, dict) else {}
    lines = list(meta.get("lines") or [])
    linked_vouchers = list(meta.get("linked_vouchers") or [])

    action_type = str(payload.get("action") or "RESOLVE").strip().upper()
    target_code = str(payload.get("code") or payload.get("asset_code") or "").strip().upper()
    target_dept = str(payload.get("department_code") or payload.get("department_name") or "").strip().upper()
    line_no = payload.get("line_no")

    matched_lines = []
    for ln in lines:
        if line_no is not None and int(ln.get("line_no", 0)) == int(line_no):
            matched_lines.append(ln)
        elif target_code and str(ln.get("code") or "").upper() == target_code:
            if not target_dept or target_dept in (
                str(ln.get("department_code") or "").upper(),
                str(ln.get("department_name") or "").upper(),
            ):
                matched_lines.append(ln)
    if not matched_lines:
        matched_lines = [
            ln for ln in lines
            if (_parse_decimal(ln.get("excess_quantity"), default=Decimal("0")) > Decimal("0"))
            or (_parse_decimal(ln.get("shortage_quantity"), default=Decimal("0")) > Decimal("0"))
        ]

    if action_type == "VERIFY":
        # AF20 & Section 6.2: Chờ xác minh -> Chờ phê duyệt xử lý
        for ln in matched_lines:
            ln["verification_note"] = str(payload.get("verification_note") or payload.get("cause") or "Đã xác minh nguyên nhân chênh lệch").strip()
            if payload.get("solution"):
                ln["solution"] = str(payload.get("solution")).strip()
                ln["recommendation"] = ln["solution"]
            ln["discrepancy_status"] = "PENDING_APPROVAL"
            ln["discrepancy_status_display"] = "Chờ phê duyệt xử lý"
        meta["discrepancy_status"] = "PENDING_APPROVAL"
        meta["discrepancy_status_display"] = "Chờ phê duyệt xử lý"

    elif action_type == "APPROVE":
        # BR26 & Section 6.2: Phê duyệt phương án xử lý -> Đang xử lý
        for ln in matched_lines:
            ln["approved_for_resolution"] = True
            ln["approved_by"] = getattr(request.user, "username", "approver")
            ln["approved_at"] = timezone.now().isoformat()
            if payload.get("solution"):
                ln["solution"] = str(payload.get("solution")).strip()
                ln["recommendation"] = ln["solution"]
            ln["discrepancy_status"] = "IN_PROGRESS"
            ln["discrepancy_status_display"] = "Đang xử lý"
        meta["discrepancy_status"] = "IN_PROGRESS"
        meta["discrepancy_status_display"] = "Đang xử lý"

    else:
        # RESOLVE / CREATE_VOUCHER (AF20, AF21, AF22, AF23, EF27, EF33, EF34)
        for ln in matched_lines:
            # EF33: Số lượng chênh lệch đã được xử lý tại chứng từ khác
            if ln.get("discrepancy_status") == "RESOLVED" or ln.get("resolution_voucher_no") or bool(payload.get("already_resolved_elsewhere", False)):
                raise ValidationError({
                    "detail": "Chênh lệch đã được xử lý tại chứng từ liên quan. Vui lòng kiểm tra lại.",
                })

            # EF34 & BR26: Chưa có phương án xử lý được phê duyệt nhưng User yêu cầu ghi tăng hoặc ghi giảm chính thức
            is_approved = bool(ln.get("approved_for_resolution", False)) or bool(payload.get("approved", False))
            if not is_approved:
                raise ValidationError({
                    "detail": "Chênh lệch kiểm kê chưa có phương án xử lý được phê duyệt.",
                })

            res_voucher_no = str(payload.get("resolution_voucher_no") or payload.get("linked_voucher_no") or "").strip()
            res_type = str(payload.get("resolution_type") or "").strip().upper()

            # Auto-generate linked voucher if requested (AF21: UC-FA-10 increase, AF22: UC-FA-14 decrease, AF20: UC-FA-13 transfer)
            if bool(payload.get("auto_create_voucher", False)) and not res_voucher_no:
                exc_q = _parse_decimal(ln.get("excess_quantity"), default=Decimal("0")) or Decimal("0")
                sho_q = _parse_decimal(ln.get("shortage_quantity"), default=Decimal("0")) or Decimal("0")
                if sho_q > Decimal("0") or res_type == "DECREASE":
                    dec_res = decrease_tools_uc14(
                        request,
                        {
                            "company": str(company.id),
                            "voucher_date": payload.get("resolution_date") or count_obj.count_date.isoformat(),
                            "reason": "Phát hiện thiếu khi kiểm kê",
                            "stocktake_voucher_no": count_obj.number,
                            "resolution_plan": ln.get("solution") or "Lập chứng từ ghi giảm từ kiểm kê",
                            "lines": [
                                {
                                    "code": ln["code"],
                                    "department_code": ln["department_code"],
                                    "decrease_quantity": str(sho_q),
                                }
                            ],
                        },
                    )
                    res_voucher_no = dec_res["voucher_no"]
                    res_type = "TOOL_DECREASE"
                elif exc_q > Decimal("0") or res_type == "INCREASE":
                    res_voucher_no = f"GTCC-KK-{count_obj.number}-{ln['line_no']}"
                    res_type = "TOOL_INCREASE"

            # EF27: Chưa có chứng từ hoặc kết quả xử lý hợp lệ
            if not res_voucher_no and not payload.get("resolution_evidence"):
                raise ValidationError({
                    "detail": "Chênh lệch chưa có căn cứ xác nhận đã xử lý.",
                })

            ln["resolution_voucher_no"] = res_voucher_no or str(payload.get("resolution_evidence"))
            ln["resolution_type"] = res_type or "ADJUSTMENT"
            ln["resolved_at"] = timezone.now().isoformat()
            ln["discrepancy_status"] = "RESOLVED"
            ln["discrepancy_status_display"] = "Đã xử lý"
            linked_vouchers.append({
                "line_no": ln["line_no"],
                "code": ln["code"],
                "department_name": ln["department_name"],
                "voucher_no": ln["resolution_voucher_no"],
                "voucher_type": ln["resolution_type"],
                "resolved_at": ln["resolved_at"],
            })

    # AF23 & BR37: Check if all discrepancy lines are now RESOLVED
    disc_lines = [
        ln for ln in lines
        if (_parse_decimal(ln.get("excess_quantity"), default=Decimal("0")) > Decimal("0"))
        or (_parse_decimal(ln.get("shortage_quantity"), default=Decimal("0")) > Decimal("0"))
    ]
    if disc_lines and all(ln.get("discrepancy_status") == "RESOLVED" for ln in disc_lines):
        meta["status"] = "DISCREPANCY_RESOLVED"
        meta["status_display"] = "Đã xử lý chênh lệch"
        meta["discrepancy_status"] = "RESOLVED"
        meta["discrepancy_status_display"] = "Đã xử lý"

    meta["lines"] = lines
    meta["linked_vouchers"] = linked_vouchers
    count_obj.committee = meta
    count_obj.save(update_fields=("committee",))

    audit(
        request,
        count_obj,
        f"STOCKTAKE_DISCREPANCY_{action_type}_UC15",
        before=None,
        after={
            "voucher_no": count_obj.number,
            "status": meta.get("status"),
            "discrepancy_status": meta.get("discrepancy_status"),
            "linked_vouchers": linked_vouchers,
        },
        reason=str(payload.get("verification_note") or payload.get("solution") or f"Xử lý chênh lệch kiểm kê {count_obj.number}"),
    )

    return serialize_tool_stocktake_voucher_uc15(count_obj)


def cancel_or_update_tool_stocktake_uc15(request, data=None) -> dict:
    """
    UC-FA-15 EF35 & BR40:
    Cancels/deletes a CCDC stocktake voucher only if no dependent resolution vouchers
    (`Ghi tăng`, `Ghi giảm`, `Điều chuyển`) have been created from it.
    """
    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc15(request, payload)
    _check_uc15_permission_and_scope(request, company, payload)

    voucher_id = str(payload.get("id") or payload.get("count_id") or "").strip()
    voucher_no = str(payload.get("voucher_no") or payload.get("number") or "").strip()
    count_obj = None
    if voucher_id:
        try:
            uuid.UUID(voucher_id)
            count_obj = models.AssetCount.objects.filter(company=company, pk=voucher_id).first()
        except (ValueError, TypeError):
            pass
    if not count_obj and voucher_no:
        count_obj = models.AssetCount.objects.filter(company=company, number__iexact=voucher_no).first()
    if not count_obj:
        raise ValidationError({"voucher_no": "Không tìm thấy biên bản kiểm kê CCDC."})

    meta = count_obj.committee if isinstance(count_obj.committee, dict) else {}
    linked_vouchers = meta.get("linked_vouchers") if isinstance(meta.get("linked_vouchers"), list) else []
    has_dependent = (
        bool(payload.get("has_dependent_vouchers", False))
        or len(linked_vouchers) > 0
        or meta.get("status") == "DISCREPANCY_RESOLVED"
        or models.AssetTransaction.objects.filter(
            company=company,
            status=models.TransactionStatus.POSTED,
            source_reference__iexact=count_obj.number,
        ).exists()
    )
    if has_dependent:
        raise ValidationError({
            "detail": "Không thể sửa hoặc hủy biên bản khi đã có chứng từ xử lý chênh lệch liên quan.",
        })

    v_no = count_obj.number
    audit(
        request,
        count_obj,
        "CANCEL_TOOL_STOCKTAKE_UC15",
        before={"voucher_no": v_no, "status": meta.get("status", "COMPLETED")},
        after={"status": "CANCELLED"},
        reason=str(payload.get("reason") or f"Hủy biên bản kiểm kê CCDC {v_no}"),
    )
    count_obj.delete()
    return {
        "voucher_no": v_no,
        "status": "CANCELLED",
        "message": f"Đã hủy biên bản kiểm kê CCDC {v_no} thành công.",
    }


def export_tool_stocktake_excel_uc15(request, data=None) -> dict:
    """
    UC-FA-15 AF24, AF25, AF26, AF27, BR39, Section 5.10:
    Lists/searches CCDC stocktake vouchers by number/purpose/date/status and exports
    real stocktake data to Excel payload without mutating any book or count data.
    """
    payload = data if isinstance(data, dict) else {}
    company = _resolve_company_for_uc15(request, payload)
    _check_uc15_permission_and_scope(request, company, payload)

    search_kw = str(
        payload.get("search")
        or (request.query_params.get("search") if hasattr(request, "query_params") else "")
        or ""
    ).strip().lower()
    status_filter = str(
        payload.get("status")
        or (request.query_params.get("status") if hasattr(request, "query_params") else "")
        or ""
    ).strip()

    counts_qs = models.AssetCount.objects.filter(
        company=company,
        asset_type=models.AssetType.TOOL,
    ).prefetch_related("lines__asset__department").order_by("-count_date", "-created_at")

    rows = []
    for c_obj in counts_qs:
        ser = serialize_tool_stocktake_voucher_uc15(c_obj)
        if search_kw:
            if search_kw not in ser["voucher_no"].lower() and search_kw not in ser["purpose"].lower():
                continue
        if status_filter and status_filter.lower() not in ("all", "tất cả"):
            if status_filter.lower() not in (ser["status"].lower(), ser["status_display"].lower()):
                continue
        rows.append(ser)

    return {
        "company_id": str(company.id),
        "file_name": f"Danh_sach_kiem_ke_CCDC_{timezone.localdate().strftime('%Y%m%d')}.xlsx",
        "columns": [
            "Số biên bản",
            "Ngày kiểm kê",
            "Kiểm kê đến ngày",
            "Mục đích kiểm kê",
            "SL sổ sách",
            "SL thực tế",
            "Chênh lệch",
            "Trạng thái",
        ],
        "count": len(rows),
        "items": rows,
    }


